INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_001', 'modern', 'Susurluk Kazası ve Devlet-Mafya İlişkileri Raporu', 'Başbakanlık Teftiş Kurulu', 'Balıkesir Susurluk\'ta meydana gelen kaza sonrası emniyet müdürü, milletvekili ve aranan firarinin aynı araçta bulunması derin devlet tartışmalarını patlattı. Kamuoyu \'Aydınlık İçin Bir Dakika Karanlık\' eylemleriyle temiz toplum talep ediyor.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"}]', '[{"label":"Kutlu Savaş raporunun tamamını sansürsüz açıkla; dokunulmazlıkları kaldırıp tüm sorumluları yargıya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; temiz toplum talebi halk nezdinde büyük güven yarattı."},{"label":"Meseleyi TBMM Araştırma Komisyonu\'na havale et; siyasi dengeleri sarsmadan kontrollü bir meclis uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Mecliste partiler arası uzlaşı sağlandı fakat kamuoyu hesap sormanın yarım kaldığını düşündü."},{"label":"Yasadışı faaliyetlerden elde edilen şüpheli kara parayı ve şirket varlıklarını Maliye marifetiyle Hazine\'ye irad kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kara para aklama çarklarına mali darbe vuruldu, hazine kasasına gelir kaydedildi."},{"label":"Emniyet ve istihbarat teşkilatında ani bir iç tasfiye yap; kamu düzenini bozan klikleri derhal görevden uzaklaştır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisindeki hizipler dağıtıldı; devlet otoritesi hissettirildi."},{"label":"\'Organize Suçlarla Mücadele Kanunu\' çıkar; devlet görevlilerinin çetelerle irtibatını en ağır cezalara bağlayan yapısal reform yap.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yeni mevzuat ile çeteleşmenin önüne yasal set çekildi; kurumsal denetim güçlendirildi."}]', 1) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_002', 'modern', 'Kardak Kayalıkları Krizi ve Ege Gerilimi', 'Milli Güvenlik Kurulu (MGK)', 'Ege Denizi\'ndeki Kardak kayalıklarına Yunan sahil güvenlik birliklerinin bayrak dikmesiyle iki ülke donanmaları burun buruna geldi. Savaş riski dakikalarla ölçülüyor.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Uluslararası deniz hukukuna ve Lozan Antlaşması\'na dayanarak BM nezdinde egemenlik haklarını resmen tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Diplomatik ve hukuki tezler uluslararası alanda kayda geçirildi."},{"label":"ABD ve NATO arabuluculuğunu kabul et; \'O bayrak inecek, o asker gidecek\' prensibiyle eşzamanlı çekilme formülünde uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik kanallar işletildi; kriz çatışmaya dönüşmeden statüko muhafaza edildi."},{"label":"Ege\'deki askeri devriye ve donanma harcamaları için savunma bütçesine acil ödenek aktar; askeri hazır bulunuşluğu finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Donanmanın operasyonel bütçesi tahkim edildi; krizin lojistik maliyeti karşılandı."},{"label":"SAT komandolarını gece operasyonuyla komşu kayalığa çıkar; Türk bayrağını dikerek caydırıcı askeri üstünlüğü fiilen göster.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"SAT timlerinin başarılı intikaliyle askeri üstünlük kuruldu; karşı taraf geri adım attı."},{"label":"\'Ege Deniz Yetki Alanları ve Gri Bölgeler Doktrini\' ilan et; kara suları ve hava sahası ihlallerini otomatik mukabeleye bağla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kalıcı angajman kuralları mevzuata girdi; Ege\'de caydırıcı doktrin tesis edildi."}]', 2) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_003', 'modern', '28 Şubat Süreci ve Bürokrasi Gerilimi', 'Başbakanlık', 'Milli Güvenlik Kurulu\'nun 9 saat süren toplantısında hükümete 18 maddelik laiklik ve irtica bildirisinin imzalatılması istendi. Hükümet ile bürokrasi arasında rejim tansiyonu tırmanıyor.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Anayasal parlamenter yetkilere sadık kal; kararları TBMM Genel Kurulu\'na getirerek sivil siyasetin meşruiyetini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki meşruiyet savunuldu fakat bürokratik vesayet baskısı tırmandı."},{"label":"Koalisyon ortaklarıyla oturup bildiriyi yumuşatan bir meşveret metni üzerinde anlaş; hükümeti erken seçime taşıyarak krizi ötele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Siyasi uzlaşıyla sıcak gerilim dindirildi; parlamento erken seçim takvimine girdi."},{"label":"Gerilimin piyasayı vurmasını engellemek için Hazine faizlerini yükselt; yabancı sermaye çıkışını durduracak likidite tedbiri al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok bir miktar frenlendi fakat bütçe faiz yükü altında ezildi."},{"label":"Kamu düzenini tehdit eden tüm yasadışı oluşumlara karşı sert idari genelgeler yayımla; devlet ciddiyetini tavizsiz uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İdari tedbirler hızla uygulandı; kamu kurumlarında sıkı teftiş dalgası başladı."},{"label":"\'Temel Haklar ve Kamu Görevlileri Güvenlik Soruşturması Kanunu\' çıkararak yetki karmaşasını yasal çerçeveye bağla.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kurumsal yetkiler kanunla sınırlandı; vesayet tartışmaları mevzuat zeminine çekildi."}]', 3) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_004', 'modern', '17 Ağustos 1999 Marmara Depremi ve Afet Fonu', 'Kriz Yönetim Merkezi', 'Gölcük merkezli 7.4 büyüklüğündeki depremde on binlerce bina yıkıldı, sanayi kalbi Marmara enkaza döndü. Acil arama kurtarma, çadır kentler ve ağır yeniden inşa faturası devleti bekliyor.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri ve usulsüz ruhsat veren belediye yetkilileri hakkında derhal tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı hızla devreye girdi; ihmali olan sorumlular tek tek gözaltına alındı."},{"label":"Uluslararası yardım çağrısı (4. Seviye Alarm) yap; tüm sivil toplum örgütleriyle koordinasyon kurup çadır kentleri ortaklaşa yönet.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma en üst seviyeye çıktı; uluslararası yardım köprüsü kuruldu."},{"label":"Yeniden inşa için geçici \'Özel İletişim Vergisi\' ve deprem tahvilleri çıkar; Hazine bütçesini afet imarına tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Deprem bütçesi oluşturuldu; altyapı ve kalıcı konutların finansmanı güvenceye bağlandı."},{"label":"Bölgeye askeri birlikleri ve arama-kurtarma taburlarını sevk et; yağma ve asayişsizliğe karşı sıkı devriye nizamı kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başında arama kurtarma yaptı; bölgede asayiş eksiksiz sağlandı."},{"label":"\'Afet Riski Altındaki Alanlar ve Zorunlu Deprem Sigortası (DASK) Kanunu\' çıkar; yapı denetimini özel şirket murakabesine bağla.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve Yapı Denetim sistemi kurularak Türkiye\'nin afet mevzuatında milat oluşturuldu."}]', 4) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_005', 'modern', 'Terör Elebaşının Yakalanması ve Yargılama Süreci', 'Adalet Bakanlığı', 'Kenya\'da düzenlenen özel operasyonla yakalanan terör örgütü lideri Türkiye\'ye getirildi. İmralı Adası\'nda özel güvenlikli mahkeme kurulurken iç ve dış kamuoyunda yoğun bir diplomatik ve hukuki süreç başladı.', '[{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"DGM duruşmalarını şehit ailelerinin ve yerli/yabancı basının gözü önünde şeffafça yürüt; hukukun üstünlüğünden milim sapma.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi yargılama evrensel hukuk kurallarıyla tamamlandı; adalet meşruiyetini ispatladı."},{"label":"AİHM ihtiyati tedbir kararlarını ve Avrupa Konseyi taahhütlerini dikkate alarak geniş tabanlı siyasi meşveret yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Avrupa ile kriz çıkması önlendi; diplomatik kanallar açık tutuldu."},{"label":"Terörle mücadele bölgelerine acil ekonomik kalkınma fonu tahsis et; bölge gençliğine istihdam kapıları aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Güneydoğu\'da ekonomik rehabilitasyon başlatıldı; bölge halkının refahı desteklendi."},{"label":"İmralı Adası\'nda deniz ve hava koruma kalkanını en üst seviyeye çıkar; sınır boylarında terör inlerine amansız operasyon başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Örgütün toparlanma çabaları sahada ezildi; güvenlik kuvvetleri mutlak hakimiyet kurdu."},{"label":"Avrupa Birliği uyum paketi kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet Kanunu\'nu TBMM\'den geçir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İdam cezası mevzuattan çıkarılarak ağırlaştırılmış müebbete dönüştürüldü; uluslararası kriz aşıldı."}]', 5) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_006', 'modern', '2001 Bankacılık Krizi ve Gecelik Faiz Şoku', 'Merkez Bankası', 'Çankaya Köşkü\'ndeki Anayasa geriliminin ardından gecelik faizler %7500\'e fırladı. Sabit kur rejimi çöktü, onlarca batık banka Tasarruf Mevduatı Sigorta Fonu\'na (TMSF) devredildi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"İçi boşaltılan batık bankaların patronları ve hortumcular hakkında derhal ağır ceza davaları aç ve mal varlıklarına el koy.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Banka hortumcularının peşine düşüldü; halkın gasbedilen mevduatının hesabı soruldu."},{"label":"İş dünyası, bankalar birliği ve sendikalarla \'Mali İstikrar Protokolü\' imzala; reel sektörün borçlarını vadelere yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal taraflarla mutabakat sağlandı; reel sektörün topyekûn iflası önlendi."},{"label":"Dalgalı kur rejimine geç; Kemal Derviş\'in \'Güçlü Ekonomiye Geçiş Programı\'nı uygulayarak acil IMF ve Dünya Bankası kredisini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dalgalı kura geçildi; piyasalardaki kanama durduruldu, yabancı kaynak akışı başladı."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan finans kuruluşlarına karşı mali zabıta ve BDDK müfettişlerini seferber et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasa spekülatörlerine geçit verilmedi; mali disiplin zorla da olsa sağlandı."},{"label":"Bankacılık Düzenleme ve Denetleme Kurumu (BDDK) Kanunu\'nu güncelle; Merkez Bankası\'na tam fiyat istikrarı bağımsızlığı tanı.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Merkez Bankası kanunen bağımsız kılındı; Türk bankacılık sistemi modern standartlara kavuştu."}]', 6) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_007', 'modern', 'AB Uyum Yasaları ve İdam Cezasının Kaldırılması', 'TBMM Genel Kurulu', 'Türkiye\'nin Avrupa Birliği\'ne adaylık sürecinde Kopenhag kriterlerine uyum için idam cezasının kaldırılması, anadilde yayın ve dernekleşme özgürlüğü içeren tarihi reform paketi Meclis\'e geldi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Temel insan hakları ve evrensel adalet ilkelerini referans al; idam cezasını savaş halleri dahil anayasadan tamamen çıkar.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Evrensel hukuk standartlarına uyuldu; Türkiye\'nin insan hakları karnesi güçlendi."},{"label":"Mecliste grubu bulunan tüm siyasi partilerle geniş tabanlı müzakere yürüt; milli hassasiyetleri gözeten ortak bir uyum metni çıkar.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Geniş bir konsensüs ile meclisten tarihi reform paketi geçti."},{"label":"AB reformları ile gelecek doğrudan yabancı yatırım ve hibe fonlarını KOBİ\'lerin teknoloji dönüşümüne tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomiye AB çıpasıyla rekor düzeyde doğrudan yabancı sermaye girişi sağlandı."},{"label":"Reformların milli birlik ve kamu düzenini zaafa uğratmaması için güvenlik teşkilatına ek istihbari yetkiler ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik parametreleri sıkı tutuldu; devlet refleksi muhafaza edildi."},{"label":"\'Avrupa Birliği Müktesebatına Uyum ve Demokratikleşme Kanunu\'nu yürürlüğe koy; yargıda savunma hakkını kanunen genişlet.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sivil haklar mevzuatta kalıcı hale geldi; Türkiye aday ülke statüsünde öne geçti."}]', 7) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_008', 'modern', '1 Mart Tezkeresi ve Irak Savaşı Kararı', 'TBMM Genel Kurulu', 'Irak\'a müdahale hazırlığındaki ABD birliklerinin Türkiye toprakları üzerinden kuzey cephesi açmasına ve TSK\'nın Irak\'a gönderilmesine ilişkin tezkere TBMM oylamasına sunuldu. Bölgesel yangın kapıda.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"TBMM\'nin demokratik iradesine tam saygı göster; tezkere reddedilirse \'Milletin kararı başımızın tacıdır\' diyerek kararı uygula.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Parlamenter demokrasi sınavı başarıyla geçti; meclis iradesi tüm dünyaya duyuruldu."},{"label":"ABD ile müzakereleri sürdürürken komşu bölge ülkeleriyle diplomatik temas kur; Ortadoğu\'da barışçıl diplomasi kanallarını zorla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Bölgesel diplomaside Türkiye saygın bir arabulucu aktör olarak konumlandı."},{"label":"Tezkerenin reddi halinde doğacak ekonomik yardımdan vazgeç; milli tasarrufları artırarak kendi özkaynaklarına güven.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Ekonomik şantaja boyun eğilmedi; bütçe disiplini kendi kaynaklarıyla korundu."},{"label":"Kuzey Irak sınır boylarına zırhlı tugayları yığ; sınırda oluşabilecek terör koridoruna karşı caydırıcı askeri yığınak yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır hattı çelikten bir kalkanla kapatıldı; sınır güvenliği garanti altına alındı."},{"label":"\'Yurtdışına Asker Gönderme ve Yabancı Birlikleri Kabul Kanunu\'nu güncelleyerek milli güvenlik kırmızı çizgilerini kanunlaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Sınır ötesi operasyon usulleri kalıcı yasal kurallara bağlandı."}]', 8) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_009', 'modern', 'Türk Lirasından Altı Sıfırın Atılması (YTL Geçişi)', 'Merkez Bankası ve Darphane', 'Yılların yüksek enflasyonunun simgesi haline gelen milyonluk banknotlar tarihe karışıyor. \'Bol sıfırlı para ülkenin itibarını zedeliyor\' gerekçesiyle Yeni Türk Lirası\'na geçiş kararı alındı.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Geçiş sürecinde yuvarlama bahanesiyle gizli zam yapan fırsatçıları Tüketici Mahkemeleri\'nde ağır cezalarla yargıla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Fırsatçılara göz açtırılmadı; tüketici hakları mahkemelerce korundu."},{"label":"Tüm bankalar, perakende zincirleri ve esnafla bir yıllık çift para birimli fiyat etiketleme uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada kaos çıkması önlendi; halk kuruşlu hesaplara huzurla alıştı."},{"label":"Yeni Türk Lirası\'nı saf enflasyon hedeflemesi ve sıkı para politikasıyla destekle; TL\'nin itibarını küresel piyasalarda yükselt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Türk Lirası rekor değer kazandı; enflasyon tek haneli rakamlara doğru geriledi."},{"label":"Eski paranın piyasadan çekilmesi ve yeni banknotların naklinde Merkez Bankası ve polis zırhlı lojistiğini kusursuz işlet.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tüm Türkiye\'de banknot değişimi sıfır kayıp ve tam güvenlikle tamamlandı."},{"label":"\'Türkiye Cumhuriyeti Para Birimi Hakkında Kanun\' çıkar; kuruş sistemini ve sahte para cezalarını en katı hükümlere bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Para basım ve tedavül nizamı modern kanunla teminat altına alındı."}]', 9) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_010', 'modern', '2007 Cumhurbaşkanlığı Seçimi (367 Krizi ve E-Muhtıra)', 'Anayasa Mahkemesi', 'TBMM\'deki Cumhurbaşkanlığı seçiminde ilk tur oylama için Meclis\'te 367 milletvekilinin hazır bulunması gerektiği iddiasıyla Anayasa Mahkemesi\'ne başvuruldu. Aynı gece Genelkurmay sitesinde E-Muhtıra yayımlandı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Hukukun evrensel içtihatlarına sarıl; Anayasa Mahkemesi kararını ne olursa olsun harfiyen uygula ve meşruiyete sarıl.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ilkesine bağlılık teyit edildi; kriz anayasal zeminde karşılandı."},{"label":"Mecliste kilitlenen düğümü çözmek için \'Söz de karar da milletindir\' de; erken genel seçim ve halkoylaması çağrısı yap.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Millet sandığına gidildi; siyasi kilitlenme halkın doğrudan iradesiyle çözüldü."},{"label":"Siyasi çalkantının faiz ve döviz piyasalarında panik yaratmasını engellemek için Hazine borçlanmasını dengeli yürüt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasa sarsıntısı sınırlandı; ekonominin büyüme ivmesi muhafaza edildi."},{"label":"Gece yarısı muhtırasına karşı sabah Başbakanlık bildirisiyle cevap ver: \'Hükümet emir almaz, genelkurmay hükümete bağlıdır!\'.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sivil otoritenin üstünlüğü ilk kez bu kadar net bir karşı bildiriyle perçinlendi."},{"label":"Anayasa değişikliği yaparak \'Cumhurbaşkanının doğrudan halk tarafından seçilmesi\' maddesini referanduma sun.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Cumhurbaşkanını doğrudan halkın seçmesi anayasallaştı; 367 garabeti tarihe gömüldü."}]', 10) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_011', 'modern', '2008 Küresel Ekonomik Krizi ve Sanayi Teşvikleri', 'Hazine ve Maliye Bakanlığı', 'Wall Street\'te Lehman Brothers\'ın batışıyla başlayan küresel mali fırtına dünyayı sardı. İhracat pazarları daralırken fabrikalarda çarkların durma tehlikesi baş gösterdi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"İşten çıkarmaları engellemek için \'Kısa Çalışma Ödeneği\'ni hukuk zemininde hızla aktif et; emekçinin hakkını koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"İşçilerin tazminat ve maaş hakları korundu; kitlesel işten çıkarmalar önlendi."},{"label":"İhracatçılar, TOBB ve sendikalarla \'Kriz Meclisi\' kur; vergi indirimleri ve teşviklerle çarkların dönmesini sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Geniş tabanlı uzlaşı paketi yürürlüğe girdi; üretim hatları canlı tutuldu."},{"label":"KDV ve ÖTV\'de geçici indirimler yap, KOSGEB sıfır faizli cansuyu kredisi aç; \'Kriz teğet geçecek\' güvenini tesis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İç piyasada talep canlandırıldı; Türkiye krizi en hızlı atlatan ülkelerden biri oldu."},{"label":"Stratejik sanayi tesislerini ve ihracatçı limanları koruma altına al; kritik tedarik zincirlerinin aksamasını önle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Lojistik koridorlar açık tutuldu; stratejik sanayi üretimi aksamadı."},{"label":"\'Yeni Yatırım Teşvik ve Sanayi Bölgeleri Kanunu\' çıkar; bölgesel ve sektörel kademeli teşvik sistemini kalıcı kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'nin modern yatırım teşvik sistemi yasalaştı; sanayide bölgesel sıçrama başladı."}]', 11) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_012', 'modern', '12 Eylül 2010 Anayasa Referandumu Paketi', 'TBMM Genel Kurulu', 'Anayasa Mahkemesi ve HSYK\'nın yapısını değiştiren, kadınlara pozitif ayrımcılık getiren ve darbecilerin yargılanmasının önünü açan 26 maddelik anayasa paketi referanduma sunuluyor.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'ne \'Bireysel Başvuru Hakkı\'nı tanı; vatandaşların AİHM\'den önce iç hukukta adalet aramasını sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"AYM\'ye bireysel başvuru hakkı Türk hukuk tarihinin en büyük kazanımı oldu."},{"label":"Yargı reformu maddelerini meclisteki tüm partilerle madde madde müzakere ederek milli mutabakat zemininde geçir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Muhalefetle müzakere masası kuruldu; kutuplaşma yumuşatılmaya çalışıldı."},{"label":"Referandum ve yargı reformunun getireceği hukuki öngörülebilirlikle uluslararası doğrudan yatırımları teşvik et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hukuki güvence beklentisiyle Türkiye\'ye rekor doğrudan sermaye girişi gerçekleşti."},{"label":"12 Eylül askeri darbesini yapan generallerin dokunulmazlığını kaldıran maddeyi oylat; vesayet artıklarını tasfiye et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Darbecilerin yargılanması anayasal güvenceye kavuştu; askeri vesayet geriletildi."},{"label":"\'Hakimler ve Savcılar Yüksek Kurulu ile Kamu Denetçiliği (Ombudsmanlık) Kanunu\'nu yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yargı idaresi geniş tabanlı temsile açıldı; ombudsmanlık kurumu hayata geçirildi."}]', 12) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_013', 'modern', 'Mavi Marmara Olayı ve Doğu Akdeniz Diplomatik Krizi', 'Dışişleri Bakanlığı', 'Gazze\'ye insani yardım taşıyan Mavi Marmara gemisine uluslararası sularda İsrail komandolarınca kanlı baskın düzenlendi, 10 Türk vatandaşı hayatını kaybetti. Millet ayakta.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Uluslararası Ceza Mahkemesi ve BM İnsan Hakları Konseyi\'ne suç duyurusu yap; sorumluların gıyabında Türk mahkemelerinde dava aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası hukuk ve Türk mahkemeleri failler hakkında yakalama kararı çıkardı."},{"label":"Diplomatik ilişkileri ikinci kâtip seviyesine indir; \'Özür, tazminat ve Gazze ablukasının hafifletilmesi\' şartı koyarak müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Onurlu diplomasiden taviz verilmedi; yıllar sonra resmi özür ve tazminat sağlandı."},{"label":"İsrail ile askeri ve stratejik ihaleleri dondur; savunma sanayiinde yerli üretim payını artıracak bütçe fonu kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yabancı savunma bağımlılığı kırıldı; yerli İHA ve mühimmat projelerine bütçe aktarıldı."},{"label":"Türk Deniz Kuvvetleri fırkateynlerini Doğu Akdeniz\'de seyrüsefer güvenliği için devriyeye çıkar; deniz sahasını koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Donanmanın caydırıcılığı Akdeniz\'de net biçimde sergilendi; mavi sularda gövde gösterisi yapıldı."},{"label":"\'Mavi Vatan ve Doğu Akdeniz Deniz Yetki Alanları Strateji Belgesi\'ni resmi devlet doktrini olarak ilan et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Mavi Vatan stratejisi resmiyet kazandı; Doğu Akdeniz\'de sismik arama hakları korundu."}]', 13) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_014', 'modern', 'Gezi Parkı Eylemleri ve Sosyal Tansiyon', 'İçişleri Bakanlığı', 'Taksim Gezi Parkı\'ndaki ağaçların sökülmesi ve Topçu Kışlası projesine karşı başlayan çevre protestoları, polisin sert gaz müdahalesi sonrası ülke geneline yayılan kitlesel gösterilere dönüştü.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"İdare Mahkemesi\'nin imar planı yürütmeyi durdurma kararını derhal uygula; orantısız güç kullanan polisler hakkında soruşturma aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı kararına riayet edildi; orantısız güç kullanan amirler açığa alındı."},{"label":"Toplumun temsilcileri, sanatçılar ve çevre inisiyatifleriyle Başbakanlık\'ta meşveret masası kur; \'Halk oylaması (plebisit)\' öner.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Müzakere masası tansiyonu düşürdü; Taksim\'in geleceği için sandık formülü sunuldu."},{"label":"Olayların piyasada yarattığı dalgalanmayı önlemek için Merkez Bankası rezervleriyle faiz ve döviz spekülasyonunu püskürt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok dalgası göğüslendi; faiz lobisinin panik yaratması engellendi."},{"label":"Kamu binalarını ve esnaf dükkânlarını tahrip eden marjinal vandallara karşı polis kuvvetlerine kesin asayiş emri ver.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Meydanlar ve kamu mülkleri güvenceye alındı; vandallık eylemleri bastırıldı."},{"label":"\'Kentsel Dönüşüm, Şehir Estetiği ve Katılımcı Şehircilik Kanunu\' çıkar; büyük projelerde halkın görüşünü yasal zorunluluk yap.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Şehir planlamasında sivil katılım kanunlaştı; çevre mevzuatı tahkim edildi."}]', 14) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_015', 'modern', 'Suriye Sınır Güvenliği ve Mülteci Dalgası', 'Göç İdaresi Genel Müdürlüğü', 'Suriye iç savaşının şiddetlenmesiyle yüz binlerce sivil Türk sınırına yığıldı. Açık kapı politikası uygulanırken şehirlerde demografik, güvenlik ve ekonomik baskı artıyor.', '[{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cenevre Mülteciler Sözleşmesi\'ne uygun olarak \'Geçici Koruma Statüsü\' ver; kayıt dışılığı hukuki denetim altına al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki statü netleştirildi; sığınmacılar biyometrik kimlik sistemine kaydedildi."},{"label":"Avrupa Birliği ile \'18 Mart Geri Kabul Mutabakatı\' imzala; mülteci yükünün maliyetini ve külfet paylaşımını Brüksel\'e bölüştür.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"AB ile diplomatik mutabakat sağlandı; milyarlarca avroluk destek fonu temin edildi."},{"label":"Sığınmacıların kayıt dışı çalışmasını önlemek için çalışma izni kotası getir; vergi ve SGK prim gelirlerini hazineye bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İş gücü piyasasında haksız rekabet frenlendi; kayıt içi çalışma özendirildi."},{"label":"Suriye sınırına 900 kilometrelik modüler beton güvenlik duvarı ve elektro-optik kuleler ör; yasadışı geçişleri sıfırla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sınır duvarı tamamlandı; sınırdan kaçak geçişler ve terörist sızmaları bıçak gibi kesildi."},{"label":"\'Yabancılar ve Uluslararası Koruma Kanunu\' çıkar; modern Göç İdaresi Başkanlığı\'nı kurarak sınır dışı mekanizmasını hızlandır.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye ilk kez modern bir göç teşkilatına kavuştu; düzensiz göçle mücadele kurumsallaştı."}]', 15) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_016', 'modern', '15 Temmuz Darbe Girişimi ve Milli Direniş', 'Cumhurbaşkanlığı', 'FETÖ mensubu hain cuntanın F-16\'lar ve tanklarla TBMM\'yi bombaladığı, köprüleri kapattığı darbe girişimine karşı millet meydanlara indi. Demokrasi ve devlet bekası ölüm kalım savaşı veriyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cumhuriyet Başsavcılıklarına talimat ver; darbeciler ve sivil imamlar hakkında anayasal düzeni ihlalden davalar açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı cuntacılara anında darbe vurdu; mahkemeler hesap sormaya başladı."},{"label":"Meydanlarda \'Demokrasi Nöbetleri\' tutan milyonlarla buluş; Yenikapı\'da tüm siyasi parti liderleriyle ortak milli miting yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Yenikapı Ruhu doğdu; millet ve tüm siyasi partiler darbelere karşı kenetlendi."},{"label":"Maliye ve MASAK\'ı devreye sok; terör örgütüne finans sağlayan şirketlere, holdinglere ve bankalara TMSF kayyumu ata.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Örgütün milyarlarca liralık finans ahtapotu çökertildi; varlıklar kamuya geçti."},{"label":"Milleti meydanlara ve havalimanlarına çağır; polis, sadık TSK neferleri ve halkın gücüyle hain darbe kalkışmasını ez.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Halk tankların önüne yattı; hain kalkışma birkaç saat içinde kanla ve canla püskürtüldü."},{"label":"Milli Güvenlik Kurulu kararıyla Olağanüstü Hal (OHAL) ilan et; Kanun Hükmünde Kararnamelerle (KHK) devletteki kriptoları tasfiye et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Bürokrasi ve ordudaki paralel yapı temizlendi; devlet mekanizması yeniden yapılandırıldı."}]', 16) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_017', 'modern', 'Fırat Kalkanı ve Zeytin Dalı Sınır Ötesi Harekâtları', 'Milli Güvenlik Kurulu (MGK)', 'Suriye sınırından Kilis ve Gaziantep\'e atılan roketler ve oluşturulmak istenen terör koridoruna karşı TSK, sınır ötesi harekat başlatma kararı aldı. Rusya ve ABD ile sıcak saha diplomasisi devrede.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"BM Şartı\'nın 51. Maddesi\'ndeki \'Meşru Müdafaa Hakkı\'nı uluslararası alanda deklare ederek askeri müdahaleyi hukuki zemine oturt.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Uluslararası meşruiyet sağlandı; operasyonun hukuki temelleri dünyaya kabul ettirildi."},{"label":"Astana Süreci çerçevesinde Rusya ve İran ile diplomatik uzlaşı sağla; sahada istenmeyen sürtüşmeleri önle.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Astana mutabakatı işledi; sahada hava sahası koordinasyonu başarıyla sağlandı."},{"label":"Harekât bölgesindeki sivillere insani yardım ve altyapı bütçesi tahsis et; Suriyelilerin güvenli bölgelere gönüllü dönüşünü finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Afrin ve Cerablus\'ta hayat normale döndü; yüz binlerce Suriyeli vatanına döndü."},{"label":"TSK zırhlı birlikleri ve yerli SİHA\'larla sınırdan içeri gir; DEAŞ ve PKK/YPG terör koridorunu ortadan ikiye böl.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Mehmetçik terör koridorunu parçaladı; sınır şehirlerimiz roket tehdidinden tamamen kurtuldu."},{"label":"\'Milli Savunma Sanayii Teşvik Kanunu\' çıkararak harekâtta kullanılan yerli mühimmat ve zırhlı araç üretimini devlet garantisine al.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yerli savunma payı %80\'e dayandı; yabancı ambargolar milli silahlarla aşıldı."}]', 17) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_018', 'modern', 'Cumhurbaşkanlığı Hükümet Sistemine Geçiş (2017 Referandumu)', 'TBMM ve Yüksek Seçim Kurulu (YSK)', 'Başbakanlık makamını kaldıran, yürütmeyi tek elde toplayan ve bakanlıkları doğrudan Cumhurbaşkanlığı\'na bağlayan yeni anayasa paketi halk oylamasına gitti. Sistemde köklü makas değişimi kapıda.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Kuvvetler ayrılığı ilkesini korumak için Meclis\'in kanun yapma ve bütçe denetim yetkilerini anayasal güvenceye bağla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Meclisin kanun koyucu tek erki olduğu teyit edildi; yasal denetim sürdürüldü."},{"label":"Cumhur İttifakı ve parlamento meşveretiyle yürütme kararnamelerini istişareye aç; siyasi istikrarı ortak akılla sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Siyasi istikrar tahkim edildi; parlamentoda hükümet ortaklığı sağlam temele oturdu."},{"label":"Bürokratik hantallığı ortadan kaldırarak yatırım kararlarını hızlandır; doğrudan yatırımlar için \'Tek Durak Ofis\' sistemini kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bürokrasi azaltıldı; mega sanayi ve altyapı yatırımları hızla hayata geçti."},{"label":"Devlet Teşkilatı Kararnameleri ile Genelkurmay ve MİT\'i doğrudan Cumhurbaşkanlığı\'na bağlayarak milli güvenlik zincirini tekilleştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisinde emir-komuta birliği sağlandı; hızlı karar alma refleksi gelişti."},{"label":"\'1 Nolu Cumhurbaşkanlığı Kararnamesi\' ile tüm bakanlık ve kurulların modern teşkilat şemasını yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yeni sistemin idari omurgası kuruldu; bürokratik vesayet ve koalisyon krizleri son buldu."}]', 18) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_019', 'modern', 'Rahip Brunson Krizi ve Döviz Kuru Şoku (2018)', 'Hazine ve Maliye Bakanlığı', 'İzmir\'de casusluk iddiasıyla yargılanan Amerikalı rahibin serbest bırakılmaması üzerine ABD Başkanı Trump, Türkiye\'ye çelik ve alüminyum yaptırımları açıkladı. Dolar/TL bir günde fırladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Yargı bağımsızlığını savun: \'Türk yargısı kimseden emir almaz; karar sadece bağımsız mahkemelerindir\' duruşunu koru.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Yargı egemenliği tavizsiz savunuldu; mahkeme delillere göre karar verdi."},{"label":"Washington ile diplomatik heyetler arası müzakere yürüt; yargılama sürecini tahliye kararıyla hukuki çerçevede neticelendir.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik tansiyon düşürüldü; ABD yaptırımları karşılıklı olarak kaldırıldı."},{"label":"Merkez Bankası faiz kararını güncelle; bankacılık swap kısıtlamalarını devreye sokup döviz spekülasyonunu kilitle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Swap kanalları kapatıldı; Londra kaynaklı kur saldırısı bertaraf edildi."},{"label":"Stratejik döviz rezervlerini koru ve iç piyasada \'Milli Dayanışma\' çağrısı yaparak yastık altı altın ve dövizleri sisteme sok.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Millet döviz bürolarına koşarak devletine sahip çıktı; kur baskısı göğüslendi."},{"label":"\'Finansal İstikrar ve Kalkınma Komitesi Kanunu\' çıkar; döviz manipulasyonuna ağır idari ve hapis cezaları getir.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Mali piyasaları manipüle edenlere karşı sert yaptırımlar yasalaştı."}]', 19) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_020', 'modern', 'S-400 Alımı ve F-35 Savunma Sanayii Ambargoları', 'Savunma Sanayii Başkanlığı', 'Patriot füze sisteminin ABD tarafından satılmaması üzerine Türkiye, hava savunmasını Rus S-400 sistemiyle tahkim etti. ABD, Türkiye\'yi ortak olduğu F-35 konsorsiyumundan tek taraflı çıkardı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"F-35 programı için Türkiye\'nin ödediği 1.4 milyar doların iadesi için uluslararası tahkime başvur; sözleşme haklarını ara.","preview":"Adalet +8, Halk +5, Hazine +7, Otorite +6","effects":{"justice":8,"people":5,"treasury":7,"military":0,"authority":6},"log":"Uluslararası tahkimde haklarımız arandı; ABD tarafı tazminat masasına çekildi."},{"label":"NATO müttefikleriyle müzakereleri sürdür; hava kuvvetlerinin vurucu gücünü F-16 modernizasyon kitiyle güvenceye al.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik denge gözetildi; mevcut jet filosu yerli mühimmatlarla modernize edildi."},{"label":"F-35 ambargosunu fırsata çevir; Hazine kaynaklarını doğrudan Milli Muharip Uçak (KAAN) ve KIZILELMA projelerine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi karar alındı; KAAN ve insansız savaş uçağı KIZILELMA hızla hangardan çıktı."},{"label":"S-400 bataryalarını stratejik hava sahasına yerleştir; Doğu Akdeniz ve Anadolu hava sahasını tam koruma kalkanına al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hava savunma caydırıcılığı sağlandı; sınır ötesi operasyonlar güvenceye bağlandı."},{"label":"\'Milli Savunma Sanayii İcra Komitesi ve Ar-Ge Kanunu\' çıkar; savunma sanayiinde yerlilik oranını %85\'e çıkarma zorunluluğu koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma sanayiinde tarihi bağımsızlık reformu tescillendi; KAAN göklerle buluştu."}]', 20) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_021', 'modern', '2020 COVID-19 Pandemisi ve Kapanma Kararları', 'Sağlık Bakanlığı Koronavirüs Bilim Kurulu', 'Küresel koronavirüs salgını Türkiye\'ye ulaştı. Şehirlerarası seyahat kısıtlamaları, maske zorunluluğu, esnafın kepenk kapatması ve aşı tedariki devleti eşi benzeri görülmemiş bir krizle yüzleştirdi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Anayasa\'nın seyahat ve çalışma hürriyeti sınırlarını gözet; tüm kısıtlamaları İl Hıfzıssıhha Kurulu kararlarına bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kısıtlamalar hukuki meşruiyet zemininde yürütüldü; keyfilik önlendi."},{"label":"Bilim Kurulu, meslek odaları ve esnafla haftalık değerlendirme yap; kademeli normalleşme takvimini uzlaşıyla açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumun her kesimiyle diyalog sürdürüldü; salgın yönetimine güven perçinlendi."},{"label":"Kepenk kapatan esnafa hibe desteği, kira yardımı ve çalışanlara \'Kısa Çalışma Ödeneği\' tahsis et; Hazine bütçesini halka aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal koruma kalkanıyla milyonlarca aileye ve esnafa milyarlarca lira destek aktarıldı."},{"label":"Sokağa çıkma kısıtlamalarında Emniyet ve Vefa Sosyal Destek Gruplarını sahaya sür; yaşlıların ihtiyaçlarını evlerine ulaştır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Vefa ekipleri tarih yazdı; yaşlılar ve ihtiyaç sahipleri yalnız bırakılmadı."},{"label":"Yerli aşı TURKOVAC projesini ve Şehir Hastaneleri altyapısını hızla tamamla; Türkiye\'yi sağlık lojistiğinde merkez kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"TURKOVAC üretildi; Şehir Hastaneleri sayesinde Türkiye salgını en az kayıpla atlattı."}]', 21) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_022', 'modern', 'Kur Korumalı Mevduat (KKM) ve Faiz Politikası Kararları', 'Hazine ve Maliye Bakanlığı & Merkez Bankası', 'Döviz kurundaki ani yükseliş karşısında 20 Aralık 2021 gecesi Kur Korumalı Mevduat (KKM) sistemi açıklandı. Milyarlarca liralık döviz çözülürken Hazine ve Merkez Bankası üzerine kur farkı yükü bindi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Bankacılık ve sermaye piyasalarında şeffaflığı sağla; KKM hesaplarının yasal çerçevesini Sayıştay denetimine aç.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Tüm hesaplar yasal denetime kavuşturuldu; mali şeffaflık sağlandı."},{"label":"Bankalar Birliği ve mevduat sahipleriyle toplantı yap; KKM\'den standart TL mevduata geçişi yumuşak teşviklerle sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Mevduat sahipleri tedirgin edilmeden çıkış stratejisi başarıyla uygulandı."},{"label":"Parasal sıkılaşma ve rasyonel faiz politikasına dön; KKM stokunu eritip Merkez Bankası rezervlerini rekor seviyeye çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ortodoks politikalara dönüldü; KKM stoku eritildi, rezervler tarihi zirveye ulaştı."},{"label":"Döviz alım-satımında hileli arbitraj yapan kurumlara karşı MASAK ve SPK incelemelerini en sert cezalarla uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kur manipülatörlerine rekor cezalar kesildi; piyasa disiplini korundu."},{"label":"\'Türk Lirası Mevduat ve Yatırım Araçlarının Korunması Kanunu\' çıkararak KKM\'nin tasfiyesini yasal takvime bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"KKM\'den çıkış kanunla güvenceye alındı; TL mevduat payı %55\'in üzerine çıktı."}]', 22) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_023', 'modern', '6 Şubat 2023 Kahramanmaraş Depremleri ve Asrın Felaketi', 'AFAD ve Çevre, Şehircilik Bakanlığı', 'Pazarcık ve Elbistan merkezli 7.7 ve 7.6 büyüklüğündeki iki büyük deprem 11 ili yıktı, 53 binden fazla can kaybına yol açtı. 100 milyar doları aşan devasa bir yeniden inşa ihtiyacı doğdu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yıkılan binaların tüm sorumlularını, fenni mesulleri ve müteahhitleri \'Deprem Suçları Soruşturma Büroları\'nda yargıla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; binlerce kusurlu sorumlu adalete teslim edildi."},{"label":"Millet-devlet el ele \'Türkiye Tek Yürek\' yardım kampanyası düzenle; tüm belediyeler ve sivil toplumla asrın dayanışmasını kur.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Millet kenetlendi; tek gecede rekor bağış toplandı ve konteyner kentler kuruldu."},{"label":"Deprem bütçesi için ek vergi düzenlemeleri yap; Hazine kaynaklarını doğrudan 300 bin kalıcı deprem konutunun inşasına akıt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bütçe deprem bölgesine yönlendirildi; bir yıl dolmadan kalıcı köy evleri ve konutlar teslim edildi."},{"label":"Deprem bölgesinde derhal 3 aylık Olağanüstü Hal (OHAL) ilan et; yağmayı engelle ve enkaz güvenliğini TSK ve polisle sağla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"OHAL ilanıyla güvenlik sağlandı; yardım koridorları kesintisiz işletildi."},{"label":"\'Kentsel Dönüşüm ve Fay Hatları Üzerinde Yapılaşma Yasağı Kanunu\'nu TBMM\'den geçir; \'Yarısı Bizden\' seferberliğini başlat.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Marmara ve Anadolu için devrim niteliğinde kentsel dönüşüm kanunu yürürlüğe girdi."}]', 23) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_024', 'modern', 'Fahiş Fiyatlar, Konut Kiraları ve Sosyal Konut Hamlesi', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Enflasyon ortamında zincir marketlerin fahiş fiyat uygulamaları, fırsatçı emlakçıların kira bedellerini katlaması halkın alım gücünü zorladı. Hükümet, piyasayı regüle etmek için masada.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Fahiş fiyat uygulayan ve kartel oluşturan zincir marketlere Rekabet Kurumu marifetiyle rekor idari para cezaları kes.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Kartel oluşturan zincirlere tarihi cezalar kesildi; piyasa hizaya sokuldu."},{"label":"Ev sahipleri ve kiracılar arasındaki uyuşmazlıklarda \'Zorunlu Arabuluculuk\' mekanizmasını devreye sokarak sulh sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Arabuluculuk devreye girdi; mahkemelerdeki dava yükü %70 oranında azaltıldı."},{"label":"TOKİ marifetiyle \'İlk Evim, İlk İş Yerim\' 250 bin sosyal konut hamlesini başlat; alt gelir grubunu kira derdinden kurtar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal konut temelleri atıldı; konut arzı artırılarak piyasa fiyatları dengelendi."},{"label":"81 ilde Ticaret Bakanlığı ve zabıta denetim timlerini çarşı pazara sür; fahiş fiyatlı stokçuların depolarını anında mühürle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Stokçulara nefes aldırılmadı; piyasa denetimleri sokak sokak uygulandı."},{"label":"Konut kiralarında %25 tavan artış sınırı ve \'Haksız Fiyat Değerlendirme Kurulu Kanunu\'nu yürürlüğe koy.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kiracıyı koruyan yasal tavan getirildi; fırsatçılık kanunen suç sayıldı."}]', 24) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_025', 'modern', 'Milli Teknoloji Hamlesi ve Savunma Sanayii Atılımları (TOGG, KAAN, TCG Anadolu)', 'Sanayi ve Teknoloji Bakanlığı', 'Türkiye\'nin yerli otomobili TOGG yollara çıkarken, dünyanın ilk SİHA gemisi TCG Anadolu hizmete girdi ve 5. nesil savaş uçağı KAAN ilk uçuşunu başarıyla gerçekleştirdi. İhracat rekorları kırılıyor.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"}]', '[{"label":"Yerli teknolojilerin fikri ve sınai mülkiyet haklarını uluslararası patent mahkemelerinde küresel teminata bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli projelerin patentleri güvenceye alındı; küresel teknoloji rekabeti başladı."},{"label":"Özel sektör girişimcileri ve üniversitelerle \'TEKNOFEST\' gençlik teknoloji seferberliğini büyüt; beyin göçünü tersine çevir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milyonlarca genç teknolojiye yöneldi; binlerce mühendis anavatana geri döndü."},{"label":"Yıllık 6 milyar doları aşan savunma sanayii ihracat gelirlerini Hazine rezervlerine aktar; Ar-Ge fonlarını büyüt.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Savunma ihracatı Hazine\'ye rekor döviz kazandırdı; cari açığa kalkan oldu."},{"label":"TCG Anadolu ve SİHA filolarını Mavi Vatan ve sınır ötesinde caydırıcı güç olarak daimi göreve çıkar.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Türk donanması küresel amfibi güce dönüştü; sahada mutlak caydırıcılık kuruldu."},{"label":"\'Milli Teknoloji ve Kritik Sanayi Yatırımları Kanunu\' çıkararak stratejik savunma şirketlerinin devredilmesini yasakla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli teknoloji hamlesi kanunla zırhlandı; geleceğin Türkiye\'si teminat altına alındı."}]', 25) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_026', 'modern', 'Gri Listeden Çıkış ve Doğrudan Yabancı Yatırım Rüzgârı', 'Hazine ve Maliye Bakanlığı & MASAK', 'Uluslararası Mali Eylem Görev Gücü (FATF) standartlarına uyum sağlayan Türkiye, gri listeden resmen çıkarıldı. Uluslararası kredi derecelendirme kuruluşları not artırırken ülkeye uzun vadeli portföy girişi başladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"MASAK ve yargı denetimini uluslararası şeffaflık standartlarında ödünsüz sürdür; kara para aklamaya sıfır tolerans tanı.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Uluslararası standartlar korundu; Türkiye maliye alanında dünyadan tam not aldı."},{"label":"Yabancı yatırım fonları ve küresel finans merkezleriyle Londra ve New York\'ta yatırımcı toplantıları yaparak güven tazele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yabancı sermaye güveni perçinlendi; milyarlarca dolarlık uzun vadeli fon girişi sağlandı."},{"label":"Gelen doğrudan yatırımları cari açığı kapatacak yenilenebilir enerji, mikroçip ve batarya fabrikalarına yönlendir.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Cari açık hızla daraldı; Merkez Bankası net rezervleri artıya geçti."},{"label":"Kripto varlık piyasaları ve yasadışı bahis ağlarına karşı siber güvenlik ve mali kolluk denetimini en üst seviyeye çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kayıt dışı fon hareketleri durduruldu; mali güvenlik eksiksiz tesis edildi."},{"label":"\'Sermaye Piyasaları ve Kripto Varlıklar Düzenleme Kanunu\'nu yürürlüğe koyarak finansal sistemi kalıcı reforma bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kripto ve sermaye piyasaları kanuni çerçeveye kavuştu; gri liste sayfası ebediyen kapandı."}]', 26) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_027', 'modern', 'Susurluk Kazası ve Devlet-Mafya İlişkileri Raporu (ve İkinci Dalga Tedbirleri)', 'Başbakanlık Teftiş Kurulu', 'Balıkesir Susurluk\'ta meydana gelen kaza sonrası emniyet müdürü, milletvekili ve aranan firarinin aynı araçta bulunması derin devlet tartışmalarını patlattı. Kamuoyu \'Aydınlık İçin Bir Dakika Karanlık\' eylemleriyle temiz toplum talep ediyor.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"}]', '[{"label":"Kutlu Savaş raporunun tamamını sansürsüz açıkla; dokunulmazlıkları kaldırıp tüm sorumluları yargıya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; temiz toplum talebi halk nezdinde büyük güven yarattı."},{"label":"Meseleyi TBMM Araştırma Komisyonu\'na havale et; siyasi dengeleri sarsmadan kontrollü bir meclis uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Mecliste partiler arası uzlaşı sağlandı fakat kamuoyu hesap sormanın yarım kaldığını düşündü."},{"label":"Yasadışı faaliyetlerden elde edilen şüpheli kara parayı ve şirket varlıklarını Maliye marifetiyle Hazine\'ye irad kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kara para aklama çarklarına mali darbe vuruldu, hazine kasasına gelir kaydedildi."},{"label":"Emniyet ve istihbarat teşkilatında ani bir iç tasfiye yap; kamu düzenini bozan klikleri derhal görevden uzaklaştır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisindeki hizipler dağıtıldı; devlet otoritesi hissettirildi."},{"label":"\'Organize Suçlarla Mücadele Kanunu\' çıkar; devlet görevlilerinin çetelerle irtibatını en ağır cezalara bağlayan yapısal reform yap.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yeni mevzuat ile çeteleşmenin önüne yasal set çekildi; kurumsal denetim güçlendirildi."}]', 27) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_028', 'modern', 'Kardak Kayalıkları Krizi ve Ege Gerilimi (ve İkinci Dalga Tedbirleri)', 'Milli Güvenlik Kurulu (MGK)', 'Ege Denizi\'ndeki Kardak kayalıklarına Yunan sahil güvenlik birliklerinin bayrak dikmesiyle iki ülke donanmaları burun buruna geldi. Savaş riski dakikalarla ölçülüyor.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Uluslararası deniz hukukuna ve Lozan Antlaşması\'na dayanarak BM nezdinde egemenlik haklarını resmen tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Diplomatik ve hukuki tezler uluslararası alanda kayda geçirildi."},{"label":"ABD ve NATO arabuluculuğunu kabul et; \'O bayrak inecek, o asker gidecek\' prensibiyle eşzamanlı çekilme formülünde uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik kanallar işletildi; kriz çatışmaya dönüşmeden statüko muhafaza edildi."},{"label":"Ege\'deki askeri devriye ve donanma harcamaları için savunma bütçesine acil ödenek aktar; askeri hazır bulunuşluğu finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Donanmanın operasyonel bütçesi tahkim edildi; krizin lojistik maliyeti karşılandı."},{"label":"SAT komandolarını gece operasyonuyla komşu kayalığa çıkar; Türk bayrağını dikerek caydırıcı askeri üstünlüğü fiilen göster.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"SAT timlerinin başarılı intikaliyle askeri üstünlük kuruldu; karşı taraf geri adım attı."},{"label":"\'Ege Deniz Yetki Alanları ve Gri Bölgeler Doktrini\' ilan et; kara suları ve hava sahası ihlallerini otomatik mukabeleye bağla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kalıcı angajman kuralları mevzuata girdi; Ege\'de caydırıcı doktrin tesis edildi."}]', 28) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_029', 'modern', '28 Şubat Süreci ve Bürokrasi Gerilimi (ve İkinci Dalga Tedbirleri)', 'Başbakanlık', 'Milli Güvenlik Kurulu\'nun 9 saat süren toplantısında hükümete 18 maddelik laiklik ve irtica bildirisinin imzalatılması istendi. Hükümet ile bürokrasi arasında rejim tansiyonu tırmanıyor.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Anayasal parlamenter yetkilere sadık kal; kararları TBMM Genel Kurulu\'na getirerek sivil siyasetin meşruiyetini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki meşruiyet savunuldu fakat bürokratik vesayet baskısı tırmandı."},{"label":"Koalisyon ortaklarıyla oturup bildiriyi yumuşatan bir meşveret metni üzerinde anlaş; hükümeti erken seçime taşıyarak krizi ötele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Siyasi uzlaşıyla sıcak gerilim dindirildi; parlamento erken seçim takvimine girdi."},{"label":"Gerilimin piyasayı vurmasını engellemek için Hazine faizlerini yükselt; yabancı sermaye çıkışını durduracak likidite tedbiri al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok bir miktar frenlendi fakat bütçe faiz yükü altında ezildi."},{"label":"Kamu düzenini tehdit eden tüm yasadışı oluşumlara karşı sert idari genelgeler yayımla; devlet ciddiyetini tavizsiz uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İdari tedbirler hızla uygulandı; kamu kurumlarında sıkı teftiş dalgası başladı."},{"label":"\'Temel Haklar ve Kamu Görevlileri Güvenlik Soruşturması Kanunu\' çıkararak yetki karmaşasını yasal çerçeveye bağla.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kurumsal yetkiler kanunla sınırlandı; vesayet tartışmaları mevzuat zeminine çekildi."}]', 29) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_030', 'modern', '17 Ağustos 1999 Marmara Depremi ve Afet Fonu (ve İkinci Dalga Tedbirleri)', 'Kriz Yönetim Merkezi', 'Gölcük merkezli 7.4 büyüklüğündeki depremde on binlerce bina yıkıldı, sanayi kalbi Marmara enkaza döndü. Acil arama kurtarma, çadır kentler ve ağır yeniden inşa faturası devleti bekliyor.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri ve usulsüz ruhsat veren belediye yetkilileri hakkında derhal tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı hızla devreye girdi; ihmali olan sorumlular tek tek gözaltına alındı."},{"label":"Uluslararası yardım çağrısı (4. Seviye Alarm) yap; tüm sivil toplum örgütleriyle koordinasyon kurup çadır kentleri ortaklaşa yönet.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma en üst seviyeye çıktı; uluslararası yardım köprüsü kuruldu."},{"label":"Yeniden inşa için geçici \'Özel İletişim Vergisi\' ve deprem tahvilleri çıkar; Hazine bütçesini afet imarına tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Deprem bütçesi oluşturuldu; altyapı ve kalıcı konutların finansmanı güvenceye bağlandı."},{"label":"Bölgeye askeri birlikleri ve arama-kurtarma taburlarını sevk et; yağma ve asayişsizliğe karşı sıkı devriye nizamı kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başında arama kurtarma yaptı; bölgede asayiş eksiksiz sağlandı."},{"label":"\'Afet Riski Altındaki Alanlar ve Zorunlu Deprem Sigortası (DASK) Kanunu\' çıkar; yapı denetimini özel şirket murakabesine bağla.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve Yapı Denetim sistemi kurularak Türkiye\'nin afet mevzuatında milat oluşturuldu."}]', 30) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_031', 'modern', 'Terör Elebaşının Yakalanması ve Yargılama Süreci (ve İkinci Dalga Tedbirleri)', 'Adalet Bakanlığı', 'Kenya\'da düzenlenen özel operasyonla yakalanan terör örgütü lideri Türkiye\'ye getirildi. İmralı Adası\'nda özel güvenlikli mahkeme kurulurken iç ve dış kamuoyunda yoğun bir diplomatik ve hukuki süreç başladı.', '[{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"DGM duruşmalarını şehit ailelerinin ve yerli/yabancı basının gözü önünde şeffafça yürüt; hukukun üstünlüğünden milim sapma.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi yargılama evrensel hukuk kurallarıyla tamamlandı; adalet meşruiyetini ispatladı."},{"label":"AİHM ihtiyati tedbir kararlarını ve Avrupa Konseyi taahhütlerini dikkate alarak geniş tabanlı siyasi meşveret yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Avrupa ile kriz çıkması önlendi; diplomatik kanallar açık tutuldu."},{"label":"Terörle mücadele bölgelerine acil ekonomik kalkınma fonu tahsis et; bölge gençliğine istihdam kapıları aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Güneydoğu\'da ekonomik rehabilitasyon başlatıldı; bölge halkının refahı desteklendi."},{"label":"İmralı Adası\'nda deniz ve hava koruma kalkanını en üst seviyeye çıkar; sınır boylarında terör inlerine amansız operasyon başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Örgütün toparlanma çabaları sahada ezildi; güvenlik kuvvetleri mutlak hakimiyet kurdu."},{"label":"Avrupa Birliği uyum paketi kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet Kanunu\'nu TBMM\'den geçir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İdam cezası mevzuattan çıkarılarak ağırlaştırılmış müebbete dönüştürüldü; uluslararası kriz aşıldı."}]', 31) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_032', 'modern', '2001 Bankacılık Krizi ve Gecelik Faiz Şoku (ve İkinci Dalga Tedbirleri)', 'Merkez Bankası', 'Çankaya Köşkü\'ndeki Anayasa geriliminin ardından gecelik faizler %7500\'e fırladı. Sabit kur rejimi çöktü, onlarca batık banka Tasarruf Mevduatı Sigorta Fonu\'na (TMSF) devredildi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"İçi boşaltılan batık bankaların patronları ve hortumcular hakkında derhal ağır ceza davaları aç ve mal varlıklarına el koy.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Banka hortumcularının peşine düşüldü; halkın gasbedilen mevduatının hesabı soruldu."},{"label":"İş dünyası, bankalar birliği ve sendikalarla \'Mali İstikrar Protokolü\' imzala; reel sektörün borçlarını vadelere yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal taraflarla mutabakat sağlandı; reel sektörün topyekûn iflası önlendi."},{"label":"Dalgalı kur rejimine geç; Kemal Derviş\'in \'Güçlü Ekonomiye Geçiş Programı\'nı uygulayarak acil IMF ve Dünya Bankası kredisini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dalgalı kura geçildi; piyasalardaki kanama durduruldu, yabancı kaynak akışı başladı."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan finans kuruluşlarına karşı mali zabıta ve BDDK müfettişlerini seferber et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasa spekülatörlerine geçit verilmedi; mali disiplin zorla da olsa sağlandı."},{"label":"Bankacılık Düzenleme ve Denetleme Kurumu (BDDK) Kanunu\'nu güncelle; Merkez Bankası\'na tam fiyat istikrarı bağımsızlığı tanı.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Merkez Bankası kanunen bağımsız kılındı; Türk bankacılık sistemi modern standartlara kavuştu."}]', 32) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_033', 'modern', 'AB Uyum Yasaları ve İdam Cezasının Kaldırılması (ve İkinci Dalga Tedbirleri)', 'TBMM Genel Kurulu', 'Türkiye\'nin Avrupa Birliği\'ne adaylık sürecinde Kopenhag kriterlerine uyum için idam cezasının kaldırılması, anadilde yayın ve dernekleşme özgürlüğü içeren tarihi reform paketi Meclis\'e geldi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Temel insan hakları ve evrensel adalet ilkelerini referans al; idam cezasını savaş halleri dahil anayasadan tamamen çıkar.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Evrensel hukuk standartlarına uyuldu; Türkiye\'nin insan hakları karnesi güçlendi."},{"label":"Mecliste grubu bulunan tüm siyasi partilerle geniş tabanlı müzakere yürüt; milli hassasiyetleri gözeten ortak bir uyum metni çıkar.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Geniş bir konsensüs ile meclisten tarihi reform paketi geçti."},{"label":"AB reformları ile gelecek doğrudan yabancı yatırım ve hibe fonlarını KOBİ\'lerin teknoloji dönüşümüne tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomiye AB çıpasıyla rekor düzeyde doğrudan yabancı sermaye girişi sağlandı."},{"label":"Reformların milli birlik ve kamu düzenini zaafa uğratmaması için güvenlik teşkilatına ek istihbari yetkiler ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik parametreleri sıkı tutuldu; devlet refleksi muhafaza edildi."},{"label":"\'Avrupa Birliği Müktesebatına Uyum ve Demokratikleşme Kanunu\'nu yürürlüğe koy; yargıda savunma hakkını kanunen genişlet.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sivil haklar mevzuatta kalıcı hale geldi; Türkiye aday ülke statüsünde öne geçti."}]', 33) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_034', 'modern', '1 Mart Tezkeresi ve Irak Savaşı Kararı (ve İkinci Dalga Tedbirleri)', 'TBMM Genel Kurulu', 'Irak\'a müdahale hazırlığındaki ABD birliklerinin Türkiye toprakları üzerinden kuzey cephesi açmasına ve TSK\'nın Irak\'a gönderilmesine ilişkin tezkere TBMM oylamasına sunuldu. Bölgesel yangın kapıda.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"TBMM\'nin demokratik iradesine tam saygı göster; tezkere reddedilirse \'Milletin kararı başımızın tacıdır\' diyerek kararı uygula.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Parlamenter demokrasi sınavı başarıyla geçti; meclis iradesi tüm dünyaya duyuruldu."},{"label":"ABD ile müzakereleri sürdürürken komşu bölge ülkeleriyle diplomatik temas kur; Ortadoğu\'da barışçıl diplomasi kanallarını zorla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Bölgesel diplomaside Türkiye saygın bir arabulucu aktör olarak konumlandı."},{"label":"Tezkerenin reddi halinde doğacak ekonomik yardımdan vazgeç; milli tasarrufları artırarak kendi özkaynaklarına güven.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Ekonomik şantaja boyun eğilmedi; bütçe disiplini kendi kaynaklarıyla korundu."},{"label":"Kuzey Irak sınır boylarına zırhlı tugayları yığ; sınırda oluşabilecek terör koridoruna karşı caydırıcı askeri yığınak yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır hattı çelikten bir kalkanla kapatıldı; sınır güvenliği garanti altına alındı."},{"label":"\'Yurtdışına Asker Gönderme ve Yabancı Birlikleri Kabul Kanunu\'nu güncelleyerek milli güvenlik kırmızı çizgilerini kanunlaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Sınır ötesi operasyon usulleri kalıcı yasal kurallara bağlandı."}]', 34) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_035', 'modern', 'Türk Lirasından Altı Sıfırın Atılması (YTL Geçişi) (ve İkinci Dalga Tedbirleri)', 'Merkez Bankası ve Darphane', 'Yılların yüksek enflasyonunun simgesi haline gelen milyonluk banknotlar tarihe karışıyor. \'Bol sıfırlı para ülkenin itibarını zedeliyor\' gerekçesiyle Yeni Türk Lirası\'na geçiş kararı alındı.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Geçiş sürecinde yuvarlama bahanesiyle gizli zam yapan fırsatçıları Tüketici Mahkemeleri\'nde ağır cezalarla yargıla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Fırsatçılara göz açtırılmadı; tüketici hakları mahkemelerce korundu."},{"label":"Tüm bankalar, perakende zincirleri ve esnafla bir yıllık çift para birimli fiyat etiketleme uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada kaos çıkması önlendi; halk kuruşlu hesaplara huzurla alıştı."},{"label":"Yeni Türk Lirası\'nı saf enflasyon hedeflemesi ve sıkı para politikasıyla destekle; TL\'nin itibarını küresel piyasalarda yükselt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Türk Lirası rekor değer kazandı; enflasyon tek haneli rakamlara doğru geriledi."},{"label":"Eski paranın piyasadan çekilmesi ve yeni banknotların naklinde Merkez Bankası ve polis zırhlı lojistiğini kusursuz işlet.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tüm Türkiye\'de banknot değişimi sıfır kayıp ve tam güvenlikle tamamlandı."},{"label":"\'Türkiye Cumhuriyeti Para Birimi Hakkında Kanun\' çıkar; kuruş sistemini ve sahte para cezalarını en katı hükümlere bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Para basım ve tedavül nizamı modern kanunla teminat altına alındı."}]', 35) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_036', 'modern', '2007 Cumhurbaşkanlığı Seçimi (367 Krizi ve E-Muhtıra) (ve İkinci Dalga Tedbirleri)', 'Anayasa Mahkemesi', 'TBMM\'deki Cumhurbaşkanlığı seçiminde ilk tur oylama için Meclis\'te 367 milletvekilinin hazır bulunması gerektiği iddiasıyla Anayasa Mahkemesi\'ne başvuruldu. Aynı gece Genelkurmay sitesinde E-Muhtıra yayımlandı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Hukukun evrensel içtihatlarına sarıl; Anayasa Mahkemesi kararını ne olursa olsun harfiyen uygula ve meşruiyete sarıl.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ilkesine bağlılık teyit edildi; kriz anayasal zeminde karşılandı."},{"label":"Mecliste kilitlenen düğümü çözmek için \'Söz de karar da milletindir\' de; erken genel seçim ve halkoylaması çağrısı yap.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Millet sandığına gidildi; siyasi kilitlenme halkın doğrudan iradesiyle çözüldü."},{"label":"Siyasi çalkantının faiz ve döviz piyasalarında panik yaratmasını engellemek için Hazine borçlanmasını dengeli yürüt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasa sarsıntısı sınırlandı; ekonominin büyüme ivmesi muhafaza edildi."},{"label":"Gece yarısı muhtırasına karşı sabah Başbakanlık bildirisiyle cevap ver: \'Hükümet emir almaz, genelkurmay hükümete bağlıdır!\'.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sivil otoritenin üstünlüğü ilk kez bu kadar net bir karşı bildiriyle perçinlendi."},{"label":"Anayasa değişikliği yaparak \'Cumhurbaşkanının doğrudan halk tarafından seçilmesi\' maddesini referanduma sun.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Cumhurbaşkanını doğrudan halkın seçmesi anayasallaştı; 367 garabeti tarihe gömüldü."}]', 36) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_037', 'modern', '2008 Küresel Ekonomik Krizi ve Sanayi Teşvikleri (ve İkinci Dalga Tedbirleri)', 'Hazine ve Maliye Bakanlığı', 'Wall Street\'te Lehman Brothers\'ın batışıyla başlayan küresel mali fırtına dünyayı sardı. İhracat pazarları daralırken fabrikalarda çarkların durma tehlikesi baş gösterdi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"İşten çıkarmaları engellemek için \'Kısa Çalışma Ödeneği\'ni hukuk zemininde hızla aktif et; emekçinin hakkını koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"İşçilerin tazminat ve maaş hakları korundu; kitlesel işten çıkarmalar önlendi."},{"label":"İhracatçılar, TOBB ve sendikalarla \'Kriz Meclisi\' kur; vergi indirimleri ve teşviklerle çarkların dönmesini sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Geniş tabanlı uzlaşı paketi yürürlüğe girdi; üretim hatları canlı tutuldu."},{"label":"KDV ve ÖTV\'de geçici indirimler yap, KOSGEB sıfır faizli cansuyu kredisi aç; \'Kriz teğet geçecek\' güvenini tesis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İç piyasada talep canlandırıldı; Türkiye krizi en hızlı atlatan ülkelerden biri oldu."},{"label":"Stratejik sanayi tesislerini ve ihracatçı limanları koruma altına al; kritik tedarik zincirlerinin aksamasını önle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Lojistik koridorlar açık tutuldu; stratejik sanayi üretimi aksamadı."},{"label":"\'Yeni Yatırım Teşvik ve Sanayi Bölgeleri Kanunu\' çıkar; bölgesel ve sektörel kademeli teşvik sistemini kalıcı kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'nin modern yatırım teşvik sistemi yasalaştı; sanayide bölgesel sıçrama başladı."}]', 37) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_038', 'modern', '12 Eylül 2010 Anayasa Referandumu Paketi (ve İkinci Dalga Tedbirleri)', 'TBMM Genel Kurulu', 'Anayasa Mahkemesi ve HSYK\'nın yapısını değiştiren, kadınlara pozitif ayrımcılık getiren ve darbecilerin yargılanmasının önünü açan 26 maddelik anayasa paketi referanduma sunuluyor.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'ne \'Bireysel Başvuru Hakkı\'nı tanı; vatandaşların AİHM\'den önce iç hukukta adalet aramasını sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"AYM\'ye bireysel başvuru hakkı Türk hukuk tarihinin en büyük kazanımı oldu."},{"label":"Yargı reformu maddelerini meclisteki tüm partilerle madde madde müzakere ederek milli mutabakat zemininde geçir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Muhalefetle müzakere masası kuruldu; kutuplaşma yumuşatılmaya çalışıldı."},{"label":"Referandum ve yargı reformunun getireceği hukuki öngörülebilirlikle uluslararası doğrudan yatırımları teşvik et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hukuki güvence beklentisiyle Türkiye\'ye rekor doğrudan sermaye girişi gerçekleşti."},{"label":"12 Eylül askeri darbesini yapan generallerin dokunulmazlığını kaldıran maddeyi oylat; vesayet artıklarını tasfiye et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Darbecilerin yargılanması anayasal güvenceye kavuştu; askeri vesayet geriletildi."},{"label":"\'Hakimler ve Savcılar Yüksek Kurulu ile Kamu Denetçiliği (Ombudsmanlık) Kanunu\'nu yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yargı idaresi geniş tabanlı temsile açıldı; ombudsmanlık kurumu hayata geçirildi."}]', 38) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_039', 'modern', 'Mavi Marmara Olayı ve Doğu Akdeniz Diplomatik Krizi (ve İkinci Dalga Tedbirleri)', 'Dışişleri Bakanlığı', 'Gazze\'ye insani yardım taşıyan Mavi Marmara gemisine uluslararası sularda İsrail komandolarınca kanlı baskın düzenlendi, 10 Türk vatandaşı hayatını kaybetti. Millet ayakta.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Uluslararası Ceza Mahkemesi ve BM İnsan Hakları Konseyi\'ne suç duyurusu yap; sorumluların gıyabında Türk mahkemelerinde dava aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası hukuk ve Türk mahkemeleri failler hakkında yakalama kararı çıkardı."},{"label":"Diplomatik ilişkileri ikinci kâtip seviyesine indir; \'Özür, tazminat ve Gazze ablukasının hafifletilmesi\' şartı koyarak müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Onurlu diplomasiden taviz verilmedi; yıllar sonra resmi özür ve tazminat sağlandı."},{"label":"İsrail ile askeri ve stratejik ihaleleri dondur; savunma sanayiinde yerli üretim payını artıracak bütçe fonu kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yabancı savunma bağımlılığı kırıldı; yerli İHA ve mühimmat projelerine bütçe aktarıldı."},{"label":"Türk Deniz Kuvvetleri fırkateynlerini Doğu Akdeniz\'de seyrüsefer güvenliği için devriyeye çıkar; deniz sahasını koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Donanmanın caydırıcılığı Akdeniz\'de net biçimde sergilendi; mavi sularda gövde gösterisi yapıldı."},{"label":"\'Mavi Vatan ve Doğu Akdeniz Deniz Yetki Alanları Strateji Belgesi\'ni resmi devlet doktrini olarak ilan et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Mavi Vatan stratejisi resmiyet kazandı; Doğu Akdeniz\'de sismik arama hakları korundu."}]', 39) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_040', 'modern', 'Gezi Parkı Eylemleri ve Sosyal Tansiyon (ve İkinci Dalga Tedbirleri)', 'İçişleri Bakanlığı', 'Taksim Gezi Parkı\'ndaki ağaçların sökülmesi ve Topçu Kışlası projesine karşı başlayan çevre protestoları, polisin sert gaz müdahalesi sonrası ülke geneline yayılan kitlesel gösterilere dönüştü.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"İdare Mahkemesi\'nin imar planı yürütmeyi durdurma kararını derhal uygula; orantısız güç kullanan polisler hakkında soruşturma aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı kararına riayet edildi; orantısız güç kullanan amirler açığa alındı."},{"label":"Toplumun temsilcileri, sanatçılar ve çevre inisiyatifleriyle Başbakanlık\'ta meşveret masası kur; \'Halk oylaması (plebisit)\' öner.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Müzakere masası tansiyonu düşürdü; Taksim\'in geleceği için sandık formülü sunuldu."},{"label":"Olayların piyasada yarattığı dalgalanmayı önlemek için Merkez Bankası rezervleriyle faiz ve döviz spekülasyonunu püskürt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok dalgası göğüslendi; faiz lobisinin panik yaratması engellendi."},{"label":"Kamu binalarını ve esnaf dükkânlarını tahrip eden marjinal vandallara karşı polis kuvvetlerine kesin asayiş emri ver.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Meydanlar ve kamu mülkleri güvenceye alındı; vandallık eylemleri bastırıldı."},{"label":"\'Kentsel Dönüşüm, Şehir Estetiği ve Katılımcı Şehircilik Kanunu\' çıkar; büyük projelerde halkın görüşünü yasal zorunluluk yap.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Şehir planlamasında sivil katılım kanunlaştı; çevre mevzuatı tahkim edildi."}]', 40) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_041', 'modern', 'Suriye Sınır Güvenliği ve Mülteci Dalgası (ve İkinci Dalga Tedbirleri)', 'Göç İdaresi Genel Müdürlüğü', 'Suriye iç savaşının şiddetlenmesiyle yüz binlerce sivil Türk sınırına yığıldı. Açık kapı politikası uygulanırken şehirlerde demografik, güvenlik ve ekonomik baskı artıyor.', '[{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cenevre Mülteciler Sözleşmesi\'ne uygun olarak \'Geçici Koruma Statüsü\' ver; kayıt dışılığı hukuki denetim altına al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki statü netleştirildi; sığınmacılar biyometrik kimlik sistemine kaydedildi."},{"label":"Avrupa Birliği ile \'18 Mart Geri Kabul Mutabakatı\' imzala; mülteci yükünün maliyetini ve külfet paylaşımını Brüksel\'e bölüştür.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"AB ile diplomatik mutabakat sağlandı; milyarlarca avroluk destek fonu temin edildi."},{"label":"Sığınmacıların kayıt dışı çalışmasını önlemek için çalışma izni kotası getir; vergi ve SGK prim gelirlerini hazineye bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İş gücü piyasasında haksız rekabet frenlendi; kayıt içi çalışma özendirildi."},{"label":"Suriye sınırına 900 kilometrelik modüler beton güvenlik duvarı ve elektro-optik kuleler ör; yasadışı geçişleri sıfırla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sınır duvarı tamamlandı; sınırdan kaçak geçişler ve terörist sızmaları bıçak gibi kesildi."},{"label":"\'Yabancılar ve Uluslararası Koruma Kanunu\' çıkar; modern Göç İdaresi Başkanlığı\'nı kurarak sınır dışı mekanizmasını hızlandır.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye ilk kez modern bir göç teşkilatına kavuştu; düzensiz göçle mücadele kurumsallaştı."}]', 41) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_042', 'modern', '15 Temmuz Darbe Girişimi ve Milli Direniş (ve İkinci Dalga Tedbirleri)', 'Cumhurbaşkanlığı', 'FETÖ mensubu hain cuntanın F-16\'lar ve tanklarla TBMM\'yi bombaladığı, köprüleri kapattığı darbe girişimine karşı millet meydanlara indi. Demokrasi ve devlet bekası ölüm kalım savaşı veriyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cumhuriyet Başsavcılıklarına talimat ver; darbeciler ve sivil imamlar hakkında anayasal düzeni ihlalden davalar açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı cuntacılara anında darbe vurdu; mahkemeler hesap sormaya başladı."},{"label":"Meydanlarda \'Demokrasi Nöbetleri\' tutan milyonlarla buluş; Yenikapı\'da tüm siyasi parti liderleriyle ortak milli miting yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Yenikapı Ruhu doğdu; millet ve tüm siyasi partiler darbelere karşı kenetlendi."},{"label":"Maliye ve MASAK\'ı devreye sok; terör örgütüne finans sağlayan şirketlere, holdinglere ve bankalara TMSF kayyumu ata.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Örgütün milyarlarca liralık finans ahtapotu çökertildi; varlıklar kamuya geçti."},{"label":"Milleti meydanlara ve havalimanlarına çağır; polis, sadık TSK neferleri ve halkın gücüyle hain darbe kalkışmasını ez.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Halk tankların önüne yattı; hain kalkışma birkaç saat içinde kanla ve canla püskürtüldü."},{"label":"Milli Güvenlik Kurulu kararıyla Olağanüstü Hal (OHAL) ilan et; Kanun Hükmünde Kararnamelerle (KHK) devletteki kriptoları tasfiye et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Bürokrasi ve ordudaki paralel yapı temizlendi; devlet mekanizması yeniden yapılandırıldı."}]', 42) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_043', 'modern', 'Fırat Kalkanı ve Zeytin Dalı Sınır Ötesi Harekâtları (ve İkinci Dalga Tedbirleri)', 'Milli Güvenlik Kurulu (MGK)', 'Suriye sınırından Kilis ve Gaziantep\'e atılan roketler ve oluşturulmak istenen terör koridoruna karşı TSK, sınır ötesi harekat başlatma kararı aldı. Rusya ve ABD ile sıcak saha diplomasisi devrede.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"BM Şartı\'nın 51. Maddesi\'ndeki \'Meşru Müdafaa Hakkı\'nı uluslararası alanda deklare ederek askeri müdahaleyi hukuki zemine oturt.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Uluslararası meşruiyet sağlandı; operasyonun hukuki temelleri dünyaya kabul ettirildi."},{"label":"Astana Süreci çerçevesinde Rusya ve İran ile diplomatik uzlaşı sağla; sahada istenmeyen sürtüşmeleri önle.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Astana mutabakatı işledi; sahada hava sahası koordinasyonu başarıyla sağlandı."},{"label":"Harekât bölgesindeki sivillere insani yardım ve altyapı bütçesi tahsis et; Suriyelilerin güvenli bölgelere gönüllü dönüşünü finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Afrin ve Cerablus\'ta hayat normale döndü; yüz binlerce Suriyeli vatanına döndü."},{"label":"TSK zırhlı birlikleri ve yerli SİHA\'larla sınırdan içeri gir; DEAŞ ve PKK/YPG terör koridorunu ortadan ikiye böl.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Mehmetçik terör koridorunu parçaladı; sınır şehirlerimiz roket tehdidinden tamamen kurtuldu."},{"label":"\'Milli Savunma Sanayii Teşvik Kanunu\' çıkararak harekâtta kullanılan yerli mühimmat ve zırhlı araç üretimini devlet garantisine al.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yerli savunma payı %80\'e dayandı; yabancı ambargolar milli silahlarla aşıldı."}]', 43) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_044', 'modern', 'Cumhurbaşkanlığı Hükümet Sistemine Geçiş (2017 Referandumu) (ve İkinci Dalga Tedbirleri)', 'TBMM ve Yüksek Seçim Kurulu (YSK)', 'Başbakanlık makamını kaldıran, yürütmeyi tek elde toplayan ve bakanlıkları doğrudan Cumhurbaşkanlığı\'na bağlayan yeni anayasa paketi halk oylamasına gitti. Sistemde köklü makas değişimi kapıda.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Kuvvetler ayrılığı ilkesini korumak için Meclis\'in kanun yapma ve bütçe denetim yetkilerini anayasal güvenceye bağla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Meclisin kanun koyucu tek erki olduğu teyit edildi; yasal denetim sürdürüldü."},{"label":"Cumhur İttifakı ve parlamento meşveretiyle yürütme kararnamelerini istişareye aç; siyasi istikrarı ortak akılla sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Siyasi istikrar tahkim edildi; parlamentoda hükümet ortaklığı sağlam temele oturdu."},{"label":"Bürokratik hantallığı ortadan kaldırarak yatırım kararlarını hızlandır; doğrudan yatırımlar için \'Tek Durak Ofis\' sistemini kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bürokrasi azaltıldı; mega sanayi ve altyapı yatırımları hızla hayata geçti."},{"label":"Devlet Teşkilatı Kararnameleri ile Genelkurmay ve MİT\'i doğrudan Cumhurbaşkanlığı\'na bağlayarak milli güvenlik zincirini tekilleştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisinde emir-komuta birliği sağlandı; hızlı karar alma refleksi gelişti."},{"label":"\'1 Nolu Cumhurbaşkanlığı Kararnamesi\' ile tüm bakanlık ve kurulların modern teşkilat şemasını yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yeni sistemin idari omurgası kuruldu; bürokratik vesayet ve koalisyon krizleri son buldu."}]', 44) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_045', 'modern', 'Rahip Brunson Krizi ve Döviz Kuru Şoku (2018) (ve İkinci Dalga Tedbirleri)', 'Hazine ve Maliye Bakanlığı', 'İzmir\'de casusluk iddiasıyla yargılanan Amerikalı rahibin serbest bırakılmaması üzerine ABD Başkanı Trump, Türkiye\'ye çelik ve alüminyum yaptırımları açıkladı. Dolar/TL bir günde fırladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Yargı bağımsızlığını savun: \'Türk yargısı kimseden emir almaz; karar sadece bağımsız mahkemelerindir\' duruşunu koru.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Yargı egemenliği tavizsiz savunuldu; mahkeme delillere göre karar verdi."},{"label":"Washington ile diplomatik heyetler arası müzakere yürüt; yargılama sürecini tahliye kararıyla hukuki çerçevede neticelendir.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik tansiyon düşürüldü; ABD yaptırımları karşılıklı olarak kaldırıldı."},{"label":"Merkez Bankası faiz kararını güncelle; bankacılık swap kısıtlamalarını devreye sokup döviz spekülasyonunu kilitle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Swap kanalları kapatıldı; Londra kaynaklı kur saldırısı bertaraf edildi."},{"label":"Stratejik döviz rezervlerini koru ve iç piyasada \'Milli Dayanışma\' çağrısı yaparak yastık altı altın ve dövizleri sisteme sok.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Millet döviz bürolarına koşarak devletine sahip çıktı; kur baskısı göğüslendi."},{"label":"\'Finansal İstikrar ve Kalkınma Komitesi Kanunu\' çıkar; döviz manipulasyonuna ağır idari ve hapis cezaları getir.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Mali piyasaları manipüle edenlere karşı sert yaptırımlar yasalaştı."}]', 45) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_046', 'modern', 'S-400 Alımı ve F-35 Savunma Sanayii Ambargoları (ve İkinci Dalga Tedbirleri)', 'Savunma Sanayii Başkanlığı', 'Patriot füze sisteminin ABD tarafından satılmaması üzerine Türkiye, hava savunmasını Rus S-400 sistemiyle tahkim etti. ABD, Türkiye\'yi ortak olduğu F-35 konsorsiyumundan tek taraflı çıkardı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"F-35 programı için Türkiye\'nin ödediği 1.4 milyar doların iadesi için uluslararası tahkime başvur; sözleşme haklarını ara.","preview":"Adalet +8, Halk +5, Hazine +7, Otorite +6","effects":{"justice":8,"people":5,"treasury":7,"military":0,"authority":6},"log":"Uluslararası tahkimde haklarımız arandı; ABD tarafı tazminat masasına çekildi."},{"label":"NATO müttefikleriyle müzakereleri sürdür; hava kuvvetlerinin vurucu gücünü F-16 modernizasyon kitiyle güvenceye al.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik denge gözetildi; mevcut jet filosu yerli mühimmatlarla modernize edildi."},{"label":"F-35 ambargosunu fırsata çevir; Hazine kaynaklarını doğrudan Milli Muharip Uçak (KAAN) ve KIZILELMA projelerine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi karar alındı; KAAN ve insansız savaş uçağı KIZILELMA hızla hangardan çıktı."},{"label":"S-400 bataryalarını stratejik hava sahasına yerleştir; Doğu Akdeniz ve Anadolu hava sahasını tam koruma kalkanına al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hava savunma caydırıcılığı sağlandı; sınır ötesi operasyonlar güvenceye bağlandı."},{"label":"\'Milli Savunma Sanayii İcra Komitesi ve Ar-Ge Kanunu\' çıkar; savunma sanayiinde yerlilik oranını %85\'e çıkarma zorunluluğu koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma sanayiinde tarihi bağımsızlık reformu tescillendi; KAAN göklerle buluştu."}]', 46) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_047', 'modern', '2020 COVID-19 Pandemisi ve Kapanma Kararları (ve İkinci Dalga Tedbirleri)', 'Sağlık Bakanlığı Koronavirüs Bilim Kurulu', 'Küresel koronavirüs salgını Türkiye\'ye ulaştı. Şehirlerarası seyahat kısıtlamaları, maske zorunluluğu, esnafın kepenk kapatması ve aşı tedariki devleti eşi benzeri görülmemiş bir krizle yüzleştirdi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Anayasa\'nın seyahat ve çalışma hürriyeti sınırlarını gözet; tüm kısıtlamaları İl Hıfzıssıhha Kurulu kararlarına bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kısıtlamalar hukuki meşruiyet zemininde yürütüldü; keyfilik önlendi."},{"label":"Bilim Kurulu, meslek odaları ve esnafla haftalık değerlendirme yap; kademeli normalleşme takvimini uzlaşıyla açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumun her kesimiyle diyalog sürdürüldü; salgın yönetimine güven perçinlendi."},{"label":"Kepenk kapatan esnafa hibe desteği, kira yardımı ve çalışanlara \'Kısa Çalışma Ödeneği\' tahsis et; Hazine bütçesini halka aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal koruma kalkanıyla milyonlarca aileye ve esnafa milyarlarca lira destek aktarıldı."},{"label":"Sokağa çıkma kısıtlamalarında Emniyet ve Vefa Sosyal Destek Gruplarını sahaya sür; yaşlıların ihtiyaçlarını evlerine ulaştır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Vefa ekipleri tarih yazdı; yaşlılar ve ihtiyaç sahipleri yalnız bırakılmadı."},{"label":"Yerli aşı TURKOVAC projesini ve Şehir Hastaneleri altyapısını hızla tamamla; Türkiye\'yi sağlık lojistiğinde merkez kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"TURKOVAC üretildi; Şehir Hastaneleri sayesinde Türkiye salgını en az kayıpla atlattı."}]', 47) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_048', 'modern', 'Kur Korumalı Mevduat (KKM) ve Faiz Politikası Kararları (ve İkinci Dalga Tedbirleri)', 'Hazine ve Maliye Bakanlığı & Merkez Bankası', 'Döviz kurundaki ani yükseliş karşısında 20 Aralık 2021 gecesi Kur Korumalı Mevduat (KKM) sistemi açıklandı. Milyarlarca liralık döviz çözülürken Hazine ve Merkez Bankası üzerine kur farkı yükü bindi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Bankacılık ve sermaye piyasalarında şeffaflığı sağla; KKM hesaplarının yasal çerçevesini Sayıştay denetimine aç.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Tüm hesaplar yasal denetime kavuşturuldu; mali şeffaflık sağlandı."},{"label":"Bankalar Birliği ve mevduat sahipleriyle toplantı yap; KKM\'den standart TL mevduata geçişi yumuşak teşviklerle sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Mevduat sahipleri tedirgin edilmeden çıkış stratejisi başarıyla uygulandı."},{"label":"Parasal sıkılaşma ve rasyonel faiz politikasına dön; KKM stokunu eritip Merkez Bankası rezervlerini rekor seviyeye çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ortodoks politikalara dönüldü; KKM stoku eritildi, rezervler tarihi zirveye ulaştı."},{"label":"Döviz alım-satımında hileli arbitraj yapan kurumlara karşı MASAK ve SPK incelemelerini en sert cezalarla uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kur manipülatörlerine rekor cezalar kesildi; piyasa disiplini korundu."},{"label":"\'Türk Lirası Mevduat ve Yatırım Araçlarının Korunması Kanunu\' çıkararak KKM\'nin tasfiyesini yasal takvime bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"KKM\'den çıkış kanunla güvenceye alındı; TL mevduat payı %55\'in üzerine çıktı."}]', 48) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_049', 'modern', '6 Şubat 2023 Kahramanmaraş Depremleri ve Asrın Felaketi (ve İkinci Dalga Tedbirleri)', 'AFAD ve Çevre, Şehircilik Bakanlığı', 'Pazarcık ve Elbistan merkezli 7.7 ve 7.6 büyüklüğündeki iki büyük deprem 11 ili yıktı, 53 binden fazla can kaybına yol açtı. 100 milyar doları aşan devasa bir yeniden inşa ihtiyacı doğdu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yıkılan binaların tüm sorumlularını, fenni mesulleri ve müteahhitleri \'Deprem Suçları Soruşturma Büroları\'nda yargıla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; binlerce kusurlu sorumlu adalete teslim edildi."},{"label":"Millet-devlet el ele \'Türkiye Tek Yürek\' yardım kampanyası düzenle; tüm belediyeler ve sivil toplumla asrın dayanışmasını kur.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Millet kenetlendi; tek gecede rekor bağış toplandı ve konteyner kentler kuruldu."},{"label":"Deprem bütçesi için ek vergi düzenlemeleri yap; Hazine kaynaklarını doğrudan 300 bin kalıcı deprem konutunun inşasına akıt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bütçe deprem bölgesine yönlendirildi; bir yıl dolmadan kalıcı köy evleri ve konutlar teslim edildi."},{"label":"Deprem bölgesinde derhal 3 aylık Olağanüstü Hal (OHAL) ilan et; yağmayı engelle ve enkaz güvenliğini TSK ve polisle sağla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"OHAL ilanıyla güvenlik sağlandı; yardım koridorları kesintisiz işletildi."},{"label":"\'Kentsel Dönüşüm ve Fay Hatları Üzerinde Yapılaşma Yasağı Kanunu\'nu TBMM\'den geçir; \'Yarısı Bizden\' seferberliğini başlat.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Marmara ve Anadolu için devrim niteliğinde kentsel dönüşüm kanunu yürürlüğe girdi."}]', 49) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_050', 'modern', 'Fahiş Fiyatlar, Konut Kiraları ve Sosyal Konut Hamlesi (ve İkinci Dalga Tedbirleri)', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Enflasyon ortamında zincir marketlerin fahiş fiyat uygulamaları, fırsatçı emlakçıların kira bedellerini katlaması halkın alım gücünü zorladı. Hükümet, piyasayı regüle etmek için masada.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Fahiş fiyat uygulayan ve kartel oluşturan zincir marketlere Rekabet Kurumu marifetiyle rekor idari para cezaları kes.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Kartel oluşturan zincirlere tarihi cezalar kesildi; piyasa hizaya sokuldu."},{"label":"Ev sahipleri ve kiracılar arasındaki uyuşmazlıklarda \'Zorunlu Arabuluculuk\' mekanizmasını devreye sokarak sulh sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Arabuluculuk devreye girdi; mahkemelerdeki dava yükü %70 oranında azaltıldı."},{"label":"TOKİ marifetiyle \'İlk Evim, İlk İş Yerim\' 250 bin sosyal konut hamlesini başlat; alt gelir grubunu kira derdinden kurtar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal konut temelleri atıldı; konut arzı artırılarak piyasa fiyatları dengelendi."},{"label":"81 ilde Ticaret Bakanlığı ve zabıta denetim timlerini çarşı pazara sür; fahiş fiyatlı stokçuların depolarını anında mühürle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Stokçulara nefes aldırılmadı; piyasa denetimleri sokak sokak uygulandı."},{"label":"Konut kiralarında %25 tavan artış sınırı ve \'Haksız Fiyat Değerlendirme Kurulu Kanunu\'nu yürürlüğe koy.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kiracıyı koruyan yasal tavan getirildi; fırsatçılık kanunen suç sayıldı."}]', 50) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_051', 'modern', 'Milli Teknoloji Hamlesi ve Savunma Sanayii Atılımları (TOGG, KAAN, TCG Anadolu) (ve İkinci Dalga Tedbirleri)', 'Sanayi ve Teknoloji Bakanlığı', 'Türkiye\'nin yerli otomobili TOGG yollara çıkarken, dünyanın ilk SİHA gemisi TCG Anadolu hizmete girdi ve 5. nesil savaş uçağı KAAN ilk uçuşunu başarıyla gerçekleştirdi. İhracat rekorları kırılıyor.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"}]', '[{"label":"Yerli teknolojilerin fikri ve sınai mülkiyet haklarını uluslararası patent mahkemelerinde küresel teminata bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli projelerin patentleri güvenceye alındı; küresel teknoloji rekabeti başladı."},{"label":"Özel sektör girişimcileri ve üniversitelerle \'TEKNOFEST\' gençlik teknoloji seferberliğini büyüt; beyin göçünü tersine çevir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milyonlarca genç teknolojiye yöneldi; binlerce mühendis anavatana geri döndü."},{"label":"Yıllık 6 milyar doları aşan savunma sanayii ihracat gelirlerini Hazine rezervlerine aktar; Ar-Ge fonlarını büyüt.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Savunma ihracatı Hazine\'ye rekor döviz kazandırdı; cari açığa kalkan oldu."},{"label":"TCG Anadolu ve SİHA filolarını Mavi Vatan ve sınır ötesinde caydırıcı güç olarak daimi göreve çıkar.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Türk donanması küresel amfibi güce dönüştü; sahada mutlak caydırıcılık kuruldu."},{"label":"\'Milli Teknoloji ve Kritik Sanayi Yatırımları Kanunu\' çıkararak stratejik savunma şirketlerinin devredilmesini yasakla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli teknoloji hamlesi kanunla zırhlandı; geleceğin Türkiye\'si teminat altına alındı."}]', 51) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_052', 'modern', 'Gri Listeden Çıkış ve Doğrudan Yabancı Yatırım Rüzgârı (ve İkinci Dalga Tedbirleri)', 'Hazine ve Maliye Bakanlığı & MASAK', 'Uluslararası Mali Eylem Görev Gücü (FATF) standartlarına uyum sağlayan Türkiye, gri listeden resmen çıkarıldı. Uluslararası kredi derecelendirme kuruluşları not artırırken ülkeye uzun vadeli portföy girişi başladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"MASAK ve yargı denetimini uluslararası şeffaflık standartlarında ödünsüz sürdür; kara para aklamaya sıfır tolerans tanı.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Uluslararası standartlar korundu; Türkiye maliye alanında dünyadan tam not aldı."},{"label":"Yabancı yatırım fonları ve küresel finans merkezleriyle Londra ve New York\'ta yatırımcı toplantıları yaparak güven tazele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yabancı sermaye güveni perçinlendi; milyarlarca dolarlık uzun vadeli fon girişi sağlandı."},{"label":"Gelen doğrudan yatırımları cari açığı kapatacak yenilenebilir enerji, mikroçip ve batarya fabrikalarına yönlendir.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Cari açık hızla daraldı; Merkez Bankası net rezervleri artıya geçti."},{"label":"Kripto varlık piyasaları ve yasadışı bahis ağlarına karşı siber güvenlik ve mali kolluk denetimini en üst seviyeye çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kayıt dışı fon hareketleri durduruldu; mali güvenlik eksiksiz tesis edildi."},{"label":"\'Sermaye Piyasaları ve Kripto Varlıklar Düzenleme Kanunu\'nu yürürlüğe koyarak finansal sistemi kalıcı reforma bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kripto ve sermaye piyasaları kanuni çerçeveye kavuştu; gri liste sayfası ebediyen kapandı."}]', 52) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_053', 'modern', 'Susurluk Kazası ve Devlet-Mafya İlişkileri Raporu (ve TBMM Meşveret Kararı)', 'Başbakanlık Teftiş Kurulu', 'Balıkesir Susurluk\'ta meydana gelen kaza sonrası emniyet müdürü, milletvekili ve aranan firarinin aynı araçta bulunması derin devlet tartışmalarını patlattı. Kamuoyu \'Aydınlık İçin Bir Dakika Karanlık\' eylemleriyle temiz toplum talep ediyor.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"}]', '[{"label":"Kutlu Savaş raporunun tamamını sansürsüz açıkla; dokunulmazlıkları kaldırıp tüm sorumluları yargıya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; temiz toplum talebi halk nezdinde büyük güven yarattı."},{"label":"Meseleyi TBMM Araştırma Komisyonu\'na havale et; siyasi dengeleri sarsmadan kontrollü bir meclis uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Mecliste partiler arası uzlaşı sağlandı fakat kamuoyu hesap sormanın yarım kaldığını düşündü."},{"label":"Yasadışı faaliyetlerden elde edilen şüpheli kara parayı ve şirket varlıklarını Maliye marifetiyle Hazine\'ye irad kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kara para aklama çarklarına mali darbe vuruldu, hazine kasasına gelir kaydedildi."},{"label":"Emniyet ve istihbarat teşkilatında ani bir iç tasfiye yap; kamu düzenini bozan klikleri derhal görevden uzaklaştır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisindeki hizipler dağıtıldı; devlet otoritesi hissettirildi."},{"label":"\'Organize Suçlarla Mücadele Kanunu\' çıkar; devlet görevlilerinin çetelerle irtibatını en ağır cezalara bağlayan yapısal reform yap.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yeni mevzuat ile çeteleşmenin önüne yasal set çekildi; kurumsal denetim güçlendirildi."}]', 53) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_054', 'modern', 'Kardak Kayalıkları Krizi ve Ege Gerilimi (ve TBMM Meşveret Kararı)', 'Milli Güvenlik Kurulu (MGK)', 'Ege Denizi\'ndeki Kardak kayalıklarına Yunan sahil güvenlik birliklerinin bayrak dikmesiyle iki ülke donanmaları burun buruna geldi. Savaş riski dakikalarla ölçülüyor.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Uluslararası deniz hukukuna ve Lozan Antlaşması\'na dayanarak BM nezdinde egemenlik haklarını resmen tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Diplomatik ve hukuki tezler uluslararası alanda kayda geçirildi."},{"label":"ABD ve NATO arabuluculuğunu kabul et; \'O bayrak inecek, o asker gidecek\' prensibiyle eşzamanlı çekilme formülünde uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik kanallar işletildi; kriz çatışmaya dönüşmeden statüko muhafaza edildi."},{"label":"Ege\'deki askeri devriye ve donanma harcamaları için savunma bütçesine acil ödenek aktar; askeri hazır bulunuşluğu finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Donanmanın operasyonel bütçesi tahkim edildi; krizin lojistik maliyeti karşılandı."},{"label":"SAT komandolarını gece operasyonuyla komşu kayalığa çıkar; Türk bayrağını dikerek caydırıcı askeri üstünlüğü fiilen göster.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"SAT timlerinin başarılı intikaliyle askeri üstünlük kuruldu; karşı taraf geri adım attı."},{"label":"\'Ege Deniz Yetki Alanları ve Gri Bölgeler Doktrini\' ilan et; kara suları ve hava sahası ihlallerini otomatik mukabeleye bağla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kalıcı angajman kuralları mevzuata girdi; Ege\'de caydırıcı doktrin tesis edildi."}]', 54) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_055', 'modern', '28 Şubat Süreci ve Bürokrasi Gerilimi (ve TBMM Meşveret Kararı)', 'Başbakanlık', 'Milli Güvenlik Kurulu\'nun 9 saat süren toplantısında hükümete 18 maddelik laiklik ve irtica bildirisinin imzalatılması istendi. Hükümet ile bürokrasi arasında rejim tansiyonu tırmanıyor.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Anayasal parlamenter yetkilere sadık kal; kararları TBMM Genel Kurulu\'na getirerek sivil siyasetin meşruiyetini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki meşruiyet savunuldu fakat bürokratik vesayet baskısı tırmandı."},{"label":"Koalisyon ortaklarıyla oturup bildiriyi yumuşatan bir meşveret metni üzerinde anlaş; hükümeti erken seçime taşıyarak krizi ötele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Siyasi uzlaşıyla sıcak gerilim dindirildi; parlamento erken seçim takvimine girdi."},{"label":"Gerilimin piyasayı vurmasını engellemek için Hazine faizlerini yükselt; yabancı sermaye çıkışını durduracak likidite tedbiri al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok bir miktar frenlendi fakat bütçe faiz yükü altında ezildi."},{"label":"Kamu düzenini tehdit eden tüm yasadışı oluşumlara karşı sert idari genelgeler yayımla; devlet ciddiyetini tavizsiz uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İdari tedbirler hızla uygulandı; kamu kurumlarında sıkı teftiş dalgası başladı."},{"label":"\'Temel Haklar ve Kamu Görevlileri Güvenlik Soruşturması Kanunu\' çıkararak yetki karmaşasını yasal çerçeveye bağla.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kurumsal yetkiler kanunla sınırlandı; vesayet tartışmaları mevzuat zeminine çekildi."}]', 55) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_056', 'modern', '17 Ağustos 1999 Marmara Depremi ve Afet Fonu (ve TBMM Meşveret Kararı)', 'Kriz Yönetim Merkezi', 'Gölcük merkezli 7.4 büyüklüğündeki depremde on binlerce bina yıkıldı, sanayi kalbi Marmara enkaza döndü. Acil arama kurtarma, çadır kentler ve ağır yeniden inşa faturası devleti bekliyor.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri ve usulsüz ruhsat veren belediye yetkilileri hakkında derhal tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı hızla devreye girdi; ihmali olan sorumlular tek tek gözaltına alındı."},{"label":"Uluslararası yardım çağrısı (4. Seviye Alarm) yap; tüm sivil toplum örgütleriyle koordinasyon kurup çadır kentleri ortaklaşa yönet.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma en üst seviyeye çıktı; uluslararası yardım köprüsü kuruldu."},{"label":"Yeniden inşa için geçici \'Özel İletişim Vergisi\' ve deprem tahvilleri çıkar; Hazine bütçesini afet imarına tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Deprem bütçesi oluşturuldu; altyapı ve kalıcı konutların finansmanı güvenceye bağlandı."},{"label":"Bölgeye askeri birlikleri ve arama-kurtarma taburlarını sevk et; yağma ve asayişsizliğe karşı sıkı devriye nizamı kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başında arama kurtarma yaptı; bölgede asayiş eksiksiz sağlandı."},{"label":"\'Afet Riski Altındaki Alanlar ve Zorunlu Deprem Sigortası (DASK) Kanunu\' çıkar; yapı denetimini özel şirket murakabesine bağla.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve Yapı Denetim sistemi kurularak Türkiye\'nin afet mevzuatında milat oluşturuldu."}]', 56) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_057', 'modern', 'Terör Elebaşının Yakalanması ve Yargılama Süreci (ve TBMM Meşveret Kararı)', 'Adalet Bakanlığı', 'Kenya\'da düzenlenen özel operasyonla yakalanan terör örgütü lideri Türkiye\'ye getirildi. İmralı Adası\'nda özel güvenlikli mahkeme kurulurken iç ve dış kamuoyunda yoğun bir diplomatik ve hukuki süreç başladı.', '[{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"DGM duruşmalarını şehit ailelerinin ve yerli/yabancı basının gözü önünde şeffafça yürüt; hukukun üstünlüğünden milim sapma.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi yargılama evrensel hukuk kurallarıyla tamamlandı; adalet meşruiyetini ispatladı."},{"label":"AİHM ihtiyati tedbir kararlarını ve Avrupa Konseyi taahhütlerini dikkate alarak geniş tabanlı siyasi meşveret yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Avrupa ile kriz çıkması önlendi; diplomatik kanallar açık tutuldu."},{"label":"Terörle mücadele bölgelerine acil ekonomik kalkınma fonu tahsis et; bölge gençliğine istihdam kapıları aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Güneydoğu\'da ekonomik rehabilitasyon başlatıldı; bölge halkının refahı desteklendi."},{"label":"İmralı Adası\'nda deniz ve hava koruma kalkanını en üst seviyeye çıkar; sınır boylarında terör inlerine amansız operasyon başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Örgütün toparlanma çabaları sahada ezildi; güvenlik kuvvetleri mutlak hakimiyet kurdu."},{"label":"Avrupa Birliği uyum paketi kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet Kanunu\'nu TBMM\'den geçir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İdam cezası mevzuattan çıkarılarak ağırlaştırılmış müebbete dönüştürüldü; uluslararası kriz aşıldı."}]', 57) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_058', 'modern', '2001 Bankacılık Krizi ve Gecelik Faiz Şoku (ve TBMM Meşveret Kararı)', 'Merkez Bankası', 'Çankaya Köşkü\'ndeki Anayasa geriliminin ardından gecelik faizler %7500\'e fırladı. Sabit kur rejimi çöktü, onlarca batık banka Tasarruf Mevduatı Sigorta Fonu\'na (TMSF) devredildi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"İçi boşaltılan batık bankaların patronları ve hortumcular hakkında derhal ağır ceza davaları aç ve mal varlıklarına el koy.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Banka hortumcularının peşine düşüldü; halkın gasbedilen mevduatının hesabı soruldu."},{"label":"İş dünyası, bankalar birliği ve sendikalarla \'Mali İstikrar Protokolü\' imzala; reel sektörün borçlarını vadelere yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal taraflarla mutabakat sağlandı; reel sektörün topyekûn iflası önlendi."},{"label":"Dalgalı kur rejimine geç; Kemal Derviş\'in \'Güçlü Ekonomiye Geçiş Programı\'nı uygulayarak acil IMF ve Dünya Bankası kredisini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dalgalı kura geçildi; piyasalardaki kanama durduruldu, yabancı kaynak akışı başladı."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan finans kuruluşlarına karşı mali zabıta ve BDDK müfettişlerini seferber et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasa spekülatörlerine geçit verilmedi; mali disiplin zorla da olsa sağlandı."},{"label":"Bankacılık Düzenleme ve Denetleme Kurumu (BDDK) Kanunu\'nu güncelle; Merkez Bankası\'na tam fiyat istikrarı bağımsızlığı tanı.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Merkez Bankası kanunen bağımsız kılındı; Türk bankacılık sistemi modern standartlara kavuştu."}]', 58) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_059', 'modern', 'AB Uyum Yasaları ve İdam Cezasının Kaldırılması (ve TBMM Meşveret Kararı)', 'TBMM Genel Kurulu', 'Türkiye\'nin Avrupa Birliği\'ne adaylık sürecinde Kopenhag kriterlerine uyum için idam cezasının kaldırılması, anadilde yayın ve dernekleşme özgürlüğü içeren tarihi reform paketi Meclis\'e geldi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Temel insan hakları ve evrensel adalet ilkelerini referans al; idam cezasını savaş halleri dahil anayasadan tamamen çıkar.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Evrensel hukuk standartlarına uyuldu; Türkiye\'nin insan hakları karnesi güçlendi."},{"label":"Mecliste grubu bulunan tüm siyasi partilerle geniş tabanlı müzakere yürüt; milli hassasiyetleri gözeten ortak bir uyum metni çıkar.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Geniş bir konsensüs ile meclisten tarihi reform paketi geçti."},{"label":"AB reformları ile gelecek doğrudan yabancı yatırım ve hibe fonlarını KOBİ\'lerin teknoloji dönüşümüne tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomiye AB çıpasıyla rekor düzeyde doğrudan yabancı sermaye girişi sağlandı."},{"label":"Reformların milli birlik ve kamu düzenini zaafa uğratmaması için güvenlik teşkilatına ek istihbari yetkiler ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik parametreleri sıkı tutuldu; devlet refleksi muhafaza edildi."},{"label":"\'Avrupa Birliği Müktesebatına Uyum ve Demokratikleşme Kanunu\'nu yürürlüğe koy; yargıda savunma hakkını kanunen genişlet.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sivil haklar mevzuatta kalıcı hale geldi; Türkiye aday ülke statüsünde öne geçti."}]', 59) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_060', 'modern', '1 Mart Tezkeresi ve Irak Savaşı Kararı (ve TBMM Meşveret Kararı)', 'TBMM Genel Kurulu', 'Irak\'a müdahale hazırlığındaki ABD birliklerinin Türkiye toprakları üzerinden kuzey cephesi açmasına ve TSK\'nın Irak\'a gönderilmesine ilişkin tezkere TBMM oylamasına sunuldu. Bölgesel yangın kapıda.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"TBMM\'nin demokratik iradesine tam saygı göster; tezkere reddedilirse \'Milletin kararı başımızın tacıdır\' diyerek kararı uygula.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Parlamenter demokrasi sınavı başarıyla geçti; meclis iradesi tüm dünyaya duyuruldu."},{"label":"ABD ile müzakereleri sürdürürken komşu bölge ülkeleriyle diplomatik temas kur; Ortadoğu\'da barışçıl diplomasi kanallarını zorla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Bölgesel diplomaside Türkiye saygın bir arabulucu aktör olarak konumlandı."},{"label":"Tezkerenin reddi halinde doğacak ekonomik yardımdan vazgeç; milli tasarrufları artırarak kendi özkaynaklarına güven.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Ekonomik şantaja boyun eğilmedi; bütçe disiplini kendi kaynaklarıyla korundu."},{"label":"Kuzey Irak sınır boylarına zırhlı tugayları yığ; sınırda oluşabilecek terör koridoruna karşı caydırıcı askeri yığınak yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır hattı çelikten bir kalkanla kapatıldı; sınır güvenliği garanti altına alındı."},{"label":"\'Yurtdışına Asker Gönderme ve Yabancı Birlikleri Kabul Kanunu\'nu güncelleyerek milli güvenlik kırmızı çizgilerini kanunlaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Sınır ötesi operasyon usulleri kalıcı yasal kurallara bağlandı."}]', 60) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_061', 'modern', 'Türk Lirasından Altı Sıfırın Atılması (YTL Geçişi) (ve TBMM Meşveret Kararı)', 'Merkez Bankası ve Darphane', 'Yılların yüksek enflasyonunun simgesi haline gelen milyonluk banknotlar tarihe karışıyor. \'Bol sıfırlı para ülkenin itibarını zedeliyor\' gerekçesiyle Yeni Türk Lirası\'na geçiş kararı alındı.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Geçiş sürecinde yuvarlama bahanesiyle gizli zam yapan fırsatçıları Tüketici Mahkemeleri\'nde ağır cezalarla yargıla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Fırsatçılara göz açtırılmadı; tüketici hakları mahkemelerce korundu."},{"label":"Tüm bankalar, perakende zincirleri ve esnafla bir yıllık çift para birimli fiyat etiketleme uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada kaos çıkması önlendi; halk kuruşlu hesaplara huzurla alıştı."},{"label":"Yeni Türk Lirası\'nı saf enflasyon hedeflemesi ve sıkı para politikasıyla destekle; TL\'nin itibarını küresel piyasalarda yükselt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Türk Lirası rekor değer kazandı; enflasyon tek haneli rakamlara doğru geriledi."},{"label":"Eski paranın piyasadan çekilmesi ve yeni banknotların naklinde Merkez Bankası ve polis zırhlı lojistiğini kusursuz işlet.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tüm Türkiye\'de banknot değişimi sıfır kayıp ve tam güvenlikle tamamlandı."},{"label":"\'Türkiye Cumhuriyeti Para Birimi Hakkında Kanun\' çıkar; kuruş sistemini ve sahte para cezalarını en katı hükümlere bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Para basım ve tedavül nizamı modern kanunla teminat altına alındı."}]', 61) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_062', 'modern', '2007 Cumhurbaşkanlığı Seçimi (367 Krizi ve E-Muhtıra) (ve TBMM Meşveret Kararı)', 'Anayasa Mahkemesi', 'TBMM\'deki Cumhurbaşkanlığı seçiminde ilk tur oylama için Meclis\'te 367 milletvekilinin hazır bulunması gerektiği iddiasıyla Anayasa Mahkemesi\'ne başvuruldu. Aynı gece Genelkurmay sitesinde E-Muhtıra yayımlandı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Hukukun evrensel içtihatlarına sarıl; Anayasa Mahkemesi kararını ne olursa olsun harfiyen uygula ve meşruiyete sarıl.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ilkesine bağlılık teyit edildi; kriz anayasal zeminde karşılandı."},{"label":"Mecliste kilitlenen düğümü çözmek için \'Söz de karar da milletindir\' de; erken genel seçim ve halkoylaması çağrısı yap.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Millet sandığına gidildi; siyasi kilitlenme halkın doğrudan iradesiyle çözüldü."},{"label":"Siyasi çalkantının faiz ve döviz piyasalarında panik yaratmasını engellemek için Hazine borçlanmasını dengeli yürüt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasa sarsıntısı sınırlandı; ekonominin büyüme ivmesi muhafaza edildi."},{"label":"Gece yarısı muhtırasına karşı sabah Başbakanlık bildirisiyle cevap ver: \'Hükümet emir almaz, genelkurmay hükümete bağlıdır!\'.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sivil otoritenin üstünlüğü ilk kez bu kadar net bir karşı bildiriyle perçinlendi."},{"label":"Anayasa değişikliği yaparak \'Cumhurbaşkanının doğrudan halk tarafından seçilmesi\' maddesini referanduma sun.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Cumhurbaşkanını doğrudan halkın seçmesi anayasallaştı; 367 garabeti tarihe gömüldü."}]', 62) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_063', 'modern', '2008 Küresel Ekonomik Krizi ve Sanayi Teşvikleri (ve TBMM Meşveret Kararı)', 'Hazine ve Maliye Bakanlığı', 'Wall Street\'te Lehman Brothers\'ın batışıyla başlayan küresel mali fırtına dünyayı sardı. İhracat pazarları daralırken fabrikalarda çarkların durma tehlikesi baş gösterdi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"İşten çıkarmaları engellemek için \'Kısa Çalışma Ödeneği\'ni hukuk zemininde hızla aktif et; emekçinin hakkını koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"İşçilerin tazminat ve maaş hakları korundu; kitlesel işten çıkarmalar önlendi."},{"label":"İhracatçılar, TOBB ve sendikalarla \'Kriz Meclisi\' kur; vergi indirimleri ve teşviklerle çarkların dönmesini sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Geniş tabanlı uzlaşı paketi yürürlüğe girdi; üretim hatları canlı tutuldu."},{"label":"KDV ve ÖTV\'de geçici indirimler yap, KOSGEB sıfır faizli cansuyu kredisi aç; \'Kriz teğet geçecek\' güvenini tesis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İç piyasada talep canlandırıldı; Türkiye krizi en hızlı atlatan ülkelerden biri oldu."},{"label":"Stratejik sanayi tesislerini ve ihracatçı limanları koruma altına al; kritik tedarik zincirlerinin aksamasını önle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Lojistik koridorlar açık tutuldu; stratejik sanayi üretimi aksamadı."},{"label":"\'Yeni Yatırım Teşvik ve Sanayi Bölgeleri Kanunu\' çıkar; bölgesel ve sektörel kademeli teşvik sistemini kalıcı kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'nin modern yatırım teşvik sistemi yasalaştı; sanayide bölgesel sıçrama başladı."}]', 63) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_064', 'modern', '12 Eylül 2010 Anayasa Referandumu Paketi (ve TBMM Meşveret Kararı)', 'TBMM Genel Kurulu', 'Anayasa Mahkemesi ve HSYK\'nın yapısını değiştiren, kadınlara pozitif ayrımcılık getiren ve darbecilerin yargılanmasının önünü açan 26 maddelik anayasa paketi referanduma sunuluyor.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'ne \'Bireysel Başvuru Hakkı\'nı tanı; vatandaşların AİHM\'den önce iç hukukta adalet aramasını sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"AYM\'ye bireysel başvuru hakkı Türk hukuk tarihinin en büyük kazanımı oldu."},{"label":"Yargı reformu maddelerini meclisteki tüm partilerle madde madde müzakere ederek milli mutabakat zemininde geçir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Muhalefetle müzakere masası kuruldu; kutuplaşma yumuşatılmaya çalışıldı."},{"label":"Referandum ve yargı reformunun getireceği hukuki öngörülebilirlikle uluslararası doğrudan yatırımları teşvik et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hukuki güvence beklentisiyle Türkiye\'ye rekor doğrudan sermaye girişi gerçekleşti."},{"label":"12 Eylül askeri darbesini yapan generallerin dokunulmazlığını kaldıran maddeyi oylat; vesayet artıklarını tasfiye et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Darbecilerin yargılanması anayasal güvenceye kavuştu; askeri vesayet geriletildi."},{"label":"\'Hakimler ve Savcılar Yüksek Kurulu ile Kamu Denetçiliği (Ombudsmanlık) Kanunu\'nu yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yargı idaresi geniş tabanlı temsile açıldı; ombudsmanlık kurumu hayata geçirildi."}]', 64) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_065', 'modern', 'Mavi Marmara Olayı ve Doğu Akdeniz Diplomatik Krizi (ve TBMM Meşveret Kararı)', 'Dışişleri Bakanlığı', 'Gazze\'ye insani yardım taşıyan Mavi Marmara gemisine uluslararası sularda İsrail komandolarınca kanlı baskın düzenlendi, 10 Türk vatandaşı hayatını kaybetti. Millet ayakta.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Uluslararası Ceza Mahkemesi ve BM İnsan Hakları Konseyi\'ne suç duyurusu yap; sorumluların gıyabında Türk mahkemelerinde dava aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası hukuk ve Türk mahkemeleri failler hakkında yakalama kararı çıkardı."},{"label":"Diplomatik ilişkileri ikinci kâtip seviyesine indir; \'Özür, tazminat ve Gazze ablukasının hafifletilmesi\' şartı koyarak müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Onurlu diplomasiden taviz verilmedi; yıllar sonra resmi özür ve tazminat sağlandı."},{"label":"İsrail ile askeri ve stratejik ihaleleri dondur; savunma sanayiinde yerli üretim payını artıracak bütçe fonu kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yabancı savunma bağımlılığı kırıldı; yerli İHA ve mühimmat projelerine bütçe aktarıldı."},{"label":"Türk Deniz Kuvvetleri fırkateynlerini Doğu Akdeniz\'de seyrüsefer güvenliği için devriyeye çıkar; deniz sahasını koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Donanmanın caydırıcılığı Akdeniz\'de net biçimde sergilendi; mavi sularda gövde gösterisi yapıldı."},{"label":"\'Mavi Vatan ve Doğu Akdeniz Deniz Yetki Alanları Strateji Belgesi\'ni resmi devlet doktrini olarak ilan et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Mavi Vatan stratejisi resmiyet kazandı; Doğu Akdeniz\'de sismik arama hakları korundu."}]', 65) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_066', 'modern', 'Gezi Parkı Eylemleri ve Sosyal Tansiyon (ve TBMM Meşveret Kararı)', 'İçişleri Bakanlığı', 'Taksim Gezi Parkı\'ndaki ağaçların sökülmesi ve Topçu Kışlası projesine karşı başlayan çevre protestoları, polisin sert gaz müdahalesi sonrası ülke geneline yayılan kitlesel gösterilere dönüştü.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"İdare Mahkemesi\'nin imar planı yürütmeyi durdurma kararını derhal uygula; orantısız güç kullanan polisler hakkında soruşturma aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı kararına riayet edildi; orantısız güç kullanan amirler açığa alındı."},{"label":"Toplumun temsilcileri, sanatçılar ve çevre inisiyatifleriyle Başbakanlık\'ta meşveret masası kur; \'Halk oylaması (plebisit)\' öner.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Müzakere masası tansiyonu düşürdü; Taksim\'in geleceği için sandık formülü sunuldu."},{"label":"Olayların piyasada yarattığı dalgalanmayı önlemek için Merkez Bankası rezervleriyle faiz ve döviz spekülasyonunu püskürt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok dalgası göğüslendi; faiz lobisinin panik yaratması engellendi."},{"label":"Kamu binalarını ve esnaf dükkânlarını tahrip eden marjinal vandallara karşı polis kuvvetlerine kesin asayiş emri ver.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Meydanlar ve kamu mülkleri güvenceye alındı; vandallık eylemleri bastırıldı."},{"label":"\'Kentsel Dönüşüm, Şehir Estetiği ve Katılımcı Şehircilik Kanunu\' çıkar; büyük projelerde halkın görüşünü yasal zorunluluk yap.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Şehir planlamasında sivil katılım kanunlaştı; çevre mevzuatı tahkim edildi."}]', 66) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_067', 'modern', 'Suriye Sınır Güvenliği ve Mülteci Dalgası (ve TBMM Meşveret Kararı)', 'Göç İdaresi Genel Müdürlüğü', 'Suriye iç savaşının şiddetlenmesiyle yüz binlerce sivil Türk sınırına yığıldı. Açık kapı politikası uygulanırken şehirlerde demografik, güvenlik ve ekonomik baskı artıyor.', '[{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cenevre Mülteciler Sözleşmesi\'ne uygun olarak \'Geçici Koruma Statüsü\' ver; kayıt dışılığı hukuki denetim altına al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki statü netleştirildi; sığınmacılar biyometrik kimlik sistemine kaydedildi."},{"label":"Avrupa Birliği ile \'18 Mart Geri Kabul Mutabakatı\' imzala; mülteci yükünün maliyetini ve külfet paylaşımını Brüksel\'e bölüştür.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"AB ile diplomatik mutabakat sağlandı; milyarlarca avroluk destek fonu temin edildi."},{"label":"Sığınmacıların kayıt dışı çalışmasını önlemek için çalışma izni kotası getir; vergi ve SGK prim gelirlerini hazineye bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İş gücü piyasasında haksız rekabet frenlendi; kayıt içi çalışma özendirildi."},{"label":"Suriye sınırına 900 kilometrelik modüler beton güvenlik duvarı ve elektro-optik kuleler ör; yasadışı geçişleri sıfırla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sınır duvarı tamamlandı; sınırdan kaçak geçişler ve terörist sızmaları bıçak gibi kesildi."},{"label":"\'Yabancılar ve Uluslararası Koruma Kanunu\' çıkar; modern Göç İdaresi Başkanlığı\'nı kurarak sınır dışı mekanizmasını hızlandır.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye ilk kez modern bir göç teşkilatına kavuştu; düzensiz göçle mücadele kurumsallaştı."}]', 67) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_068', 'modern', '15 Temmuz Darbe Girişimi ve Milli Direniş (ve TBMM Meşveret Kararı)', 'Cumhurbaşkanlığı', 'FETÖ mensubu hain cuntanın F-16\'lar ve tanklarla TBMM\'yi bombaladığı, köprüleri kapattığı darbe girişimine karşı millet meydanlara indi. Demokrasi ve devlet bekası ölüm kalım savaşı veriyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cumhuriyet Başsavcılıklarına talimat ver; darbeciler ve sivil imamlar hakkında anayasal düzeni ihlalden davalar açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı cuntacılara anında darbe vurdu; mahkemeler hesap sormaya başladı."},{"label":"Meydanlarda \'Demokrasi Nöbetleri\' tutan milyonlarla buluş; Yenikapı\'da tüm siyasi parti liderleriyle ortak milli miting yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Yenikapı Ruhu doğdu; millet ve tüm siyasi partiler darbelere karşı kenetlendi."},{"label":"Maliye ve MASAK\'ı devreye sok; terör örgütüne finans sağlayan şirketlere, holdinglere ve bankalara TMSF kayyumu ata.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Örgütün milyarlarca liralık finans ahtapotu çökertildi; varlıklar kamuya geçti."},{"label":"Milleti meydanlara ve havalimanlarına çağır; polis, sadık TSK neferleri ve halkın gücüyle hain darbe kalkışmasını ez.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Halk tankların önüne yattı; hain kalkışma birkaç saat içinde kanla ve canla püskürtüldü."},{"label":"Milli Güvenlik Kurulu kararıyla Olağanüstü Hal (OHAL) ilan et; Kanun Hükmünde Kararnamelerle (KHK) devletteki kriptoları tasfiye et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Bürokrasi ve ordudaki paralel yapı temizlendi; devlet mekanizması yeniden yapılandırıldı."}]', 68) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_069', 'modern', 'Fırat Kalkanı ve Zeytin Dalı Sınır Ötesi Harekâtları (ve TBMM Meşveret Kararı)', 'Milli Güvenlik Kurulu (MGK)', 'Suriye sınırından Kilis ve Gaziantep\'e atılan roketler ve oluşturulmak istenen terör koridoruna karşı TSK, sınır ötesi harekat başlatma kararı aldı. Rusya ve ABD ile sıcak saha diplomasisi devrede.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"BM Şartı\'nın 51. Maddesi\'ndeki \'Meşru Müdafaa Hakkı\'nı uluslararası alanda deklare ederek askeri müdahaleyi hukuki zemine oturt.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Uluslararası meşruiyet sağlandı; operasyonun hukuki temelleri dünyaya kabul ettirildi."},{"label":"Astana Süreci çerçevesinde Rusya ve İran ile diplomatik uzlaşı sağla; sahada istenmeyen sürtüşmeleri önle.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Astana mutabakatı işledi; sahada hava sahası koordinasyonu başarıyla sağlandı."},{"label":"Harekât bölgesindeki sivillere insani yardım ve altyapı bütçesi tahsis et; Suriyelilerin güvenli bölgelere gönüllü dönüşünü finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Afrin ve Cerablus\'ta hayat normale döndü; yüz binlerce Suriyeli vatanına döndü."},{"label":"TSK zırhlı birlikleri ve yerli SİHA\'larla sınırdan içeri gir; DEAŞ ve PKK/YPG terör koridorunu ortadan ikiye böl.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Mehmetçik terör koridorunu parçaladı; sınır şehirlerimiz roket tehdidinden tamamen kurtuldu."},{"label":"\'Milli Savunma Sanayii Teşvik Kanunu\' çıkararak harekâtta kullanılan yerli mühimmat ve zırhlı araç üretimini devlet garantisine al.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yerli savunma payı %80\'e dayandı; yabancı ambargolar milli silahlarla aşıldı."}]', 69) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_070', 'modern', 'Cumhurbaşkanlığı Hükümet Sistemine Geçiş (2017 Referandumu) (ve TBMM Meşveret Kararı)', 'TBMM ve Yüksek Seçim Kurulu (YSK)', 'Başbakanlık makamını kaldıran, yürütmeyi tek elde toplayan ve bakanlıkları doğrudan Cumhurbaşkanlığı\'na bağlayan yeni anayasa paketi halk oylamasına gitti. Sistemde köklü makas değişimi kapıda.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Kuvvetler ayrılığı ilkesini korumak için Meclis\'in kanun yapma ve bütçe denetim yetkilerini anayasal güvenceye bağla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Meclisin kanun koyucu tek erki olduğu teyit edildi; yasal denetim sürdürüldü."},{"label":"Cumhur İttifakı ve parlamento meşveretiyle yürütme kararnamelerini istişareye aç; siyasi istikrarı ortak akılla sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Siyasi istikrar tahkim edildi; parlamentoda hükümet ortaklığı sağlam temele oturdu."},{"label":"Bürokratik hantallığı ortadan kaldırarak yatırım kararlarını hızlandır; doğrudan yatırımlar için \'Tek Durak Ofis\' sistemini kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bürokrasi azaltıldı; mega sanayi ve altyapı yatırımları hızla hayata geçti."},{"label":"Devlet Teşkilatı Kararnameleri ile Genelkurmay ve MİT\'i doğrudan Cumhurbaşkanlığı\'na bağlayarak milli güvenlik zincirini tekilleştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisinde emir-komuta birliği sağlandı; hızlı karar alma refleksi gelişti."},{"label":"\'1 Nolu Cumhurbaşkanlığı Kararnamesi\' ile tüm bakanlık ve kurulların modern teşkilat şemasını yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yeni sistemin idari omurgası kuruldu; bürokratik vesayet ve koalisyon krizleri son buldu."}]', 70) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_071', 'modern', 'Rahip Brunson Krizi ve Döviz Kuru Şoku (2018) (ve TBMM Meşveret Kararı)', 'Hazine ve Maliye Bakanlığı', 'İzmir\'de casusluk iddiasıyla yargılanan Amerikalı rahibin serbest bırakılmaması üzerine ABD Başkanı Trump, Türkiye\'ye çelik ve alüminyum yaptırımları açıkladı. Dolar/TL bir günde fırladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Yargı bağımsızlığını savun: \'Türk yargısı kimseden emir almaz; karar sadece bağımsız mahkemelerindir\' duruşunu koru.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Yargı egemenliği tavizsiz savunuldu; mahkeme delillere göre karar verdi."},{"label":"Washington ile diplomatik heyetler arası müzakere yürüt; yargılama sürecini tahliye kararıyla hukuki çerçevede neticelendir.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik tansiyon düşürüldü; ABD yaptırımları karşılıklı olarak kaldırıldı."},{"label":"Merkez Bankası faiz kararını güncelle; bankacılık swap kısıtlamalarını devreye sokup döviz spekülasyonunu kilitle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Swap kanalları kapatıldı; Londra kaynaklı kur saldırısı bertaraf edildi."},{"label":"Stratejik döviz rezervlerini koru ve iç piyasada \'Milli Dayanışma\' çağrısı yaparak yastık altı altın ve dövizleri sisteme sok.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Millet döviz bürolarına koşarak devletine sahip çıktı; kur baskısı göğüslendi."},{"label":"\'Finansal İstikrar ve Kalkınma Komitesi Kanunu\' çıkar; döviz manipulasyonuna ağır idari ve hapis cezaları getir.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Mali piyasaları manipüle edenlere karşı sert yaptırımlar yasalaştı."}]', 71) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_072', 'modern', 'S-400 Alımı ve F-35 Savunma Sanayii Ambargoları (ve TBMM Meşveret Kararı)', 'Savunma Sanayii Başkanlığı', 'Patriot füze sisteminin ABD tarafından satılmaması üzerine Türkiye, hava savunmasını Rus S-400 sistemiyle tahkim etti. ABD, Türkiye\'yi ortak olduğu F-35 konsorsiyumundan tek taraflı çıkardı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"F-35 programı için Türkiye\'nin ödediği 1.4 milyar doların iadesi için uluslararası tahkime başvur; sözleşme haklarını ara.","preview":"Adalet +8, Halk +5, Hazine +7, Otorite +6","effects":{"justice":8,"people":5,"treasury":7,"military":0,"authority":6},"log":"Uluslararası tahkimde haklarımız arandı; ABD tarafı tazminat masasına çekildi."},{"label":"NATO müttefikleriyle müzakereleri sürdür; hava kuvvetlerinin vurucu gücünü F-16 modernizasyon kitiyle güvenceye al.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik denge gözetildi; mevcut jet filosu yerli mühimmatlarla modernize edildi."},{"label":"F-35 ambargosunu fırsata çevir; Hazine kaynaklarını doğrudan Milli Muharip Uçak (KAAN) ve KIZILELMA projelerine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi karar alındı; KAAN ve insansız savaş uçağı KIZILELMA hızla hangardan çıktı."},{"label":"S-400 bataryalarını stratejik hava sahasına yerleştir; Doğu Akdeniz ve Anadolu hava sahasını tam koruma kalkanına al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hava savunma caydırıcılığı sağlandı; sınır ötesi operasyonlar güvenceye bağlandı."},{"label":"\'Milli Savunma Sanayii İcra Komitesi ve Ar-Ge Kanunu\' çıkar; savunma sanayiinde yerlilik oranını %85\'e çıkarma zorunluluğu koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma sanayiinde tarihi bağımsızlık reformu tescillendi; KAAN göklerle buluştu."}]', 72) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_073', 'modern', '2020 COVID-19 Pandemisi ve Kapanma Kararları (ve TBMM Meşveret Kararı)', 'Sağlık Bakanlığı Koronavirüs Bilim Kurulu', 'Küresel koronavirüs salgını Türkiye\'ye ulaştı. Şehirlerarası seyahat kısıtlamaları, maske zorunluluğu, esnafın kepenk kapatması ve aşı tedariki devleti eşi benzeri görülmemiş bir krizle yüzleştirdi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Anayasa\'nın seyahat ve çalışma hürriyeti sınırlarını gözet; tüm kısıtlamaları İl Hıfzıssıhha Kurulu kararlarına bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kısıtlamalar hukuki meşruiyet zemininde yürütüldü; keyfilik önlendi."},{"label":"Bilim Kurulu, meslek odaları ve esnafla haftalık değerlendirme yap; kademeli normalleşme takvimini uzlaşıyla açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumun her kesimiyle diyalog sürdürüldü; salgın yönetimine güven perçinlendi."},{"label":"Kepenk kapatan esnafa hibe desteği, kira yardımı ve çalışanlara \'Kısa Çalışma Ödeneği\' tahsis et; Hazine bütçesini halka aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal koruma kalkanıyla milyonlarca aileye ve esnafa milyarlarca lira destek aktarıldı."},{"label":"Sokağa çıkma kısıtlamalarında Emniyet ve Vefa Sosyal Destek Gruplarını sahaya sür; yaşlıların ihtiyaçlarını evlerine ulaştır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Vefa ekipleri tarih yazdı; yaşlılar ve ihtiyaç sahipleri yalnız bırakılmadı."},{"label":"Yerli aşı TURKOVAC projesini ve Şehir Hastaneleri altyapısını hızla tamamla; Türkiye\'yi sağlık lojistiğinde merkez kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"TURKOVAC üretildi; Şehir Hastaneleri sayesinde Türkiye salgını en az kayıpla atlattı."}]', 73) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_074', 'modern', 'Kur Korumalı Mevduat (KKM) ve Faiz Politikası Kararları (ve TBMM Meşveret Kararı)', 'Hazine ve Maliye Bakanlığı & Merkez Bankası', 'Döviz kurundaki ani yükseliş karşısında 20 Aralık 2021 gecesi Kur Korumalı Mevduat (KKM) sistemi açıklandı. Milyarlarca liralık döviz çözülürken Hazine ve Merkez Bankası üzerine kur farkı yükü bindi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Bankacılık ve sermaye piyasalarında şeffaflığı sağla; KKM hesaplarının yasal çerçevesini Sayıştay denetimine aç.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Tüm hesaplar yasal denetime kavuşturuldu; mali şeffaflık sağlandı."},{"label":"Bankalar Birliği ve mevduat sahipleriyle toplantı yap; KKM\'den standart TL mevduata geçişi yumuşak teşviklerle sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Mevduat sahipleri tedirgin edilmeden çıkış stratejisi başarıyla uygulandı."},{"label":"Parasal sıkılaşma ve rasyonel faiz politikasına dön; KKM stokunu eritip Merkez Bankası rezervlerini rekor seviyeye çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ortodoks politikalara dönüldü; KKM stoku eritildi, rezervler tarihi zirveye ulaştı."},{"label":"Döviz alım-satımında hileli arbitraj yapan kurumlara karşı MASAK ve SPK incelemelerini en sert cezalarla uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kur manipülatörlerine rekor cezalar kesildi; piyasa disiplini korundu."},{"label":"\'Türk Lirası Mevduat ve Yatırım Araçlarının Korunması Kanunu\' çıkararak KKM\'nin tasfiyesini yasal takvime bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"KKM\'den çıkış kanunla güvenceye alındı; TL mevduat payı %55\'in üzerine çıktı."}]', 74) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_075', 'modern', '6 Şubat 2023 Kahramanmaraş Depremleri ve Asrın Felaketi (ve TBMM Meşveret Kararı)', 'AFAD ve Çevre, Şehircilik Bakanlığı', 'Pazarcık ve Elbistan merkezli 7.7 ve 7.6 büyüklüğündeki iki büyük deprem 11 ili yıktı, 53 binden fazla can kaybına yol açtı. 100 milyar doları aşan devasa bir yeniden inşa ihtiyacı doğdu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yıkılan binaların tüm sorumlularını, fenni mesulleri ve müteahhitleri \'Deprem Suçları Soruşturma Büroları\'nda yargıla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; binlerce kusurlu sorumlu adalete teslim edildi."},{"label":"Millet-devlet el ele \'Türkiye Tek Yürek\' yardım kampanyası düzenle; tüm belediyeler ve sivil toplumla asrın dayanışmasını kur.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Millet kenetlendi; tek gecede rekor bağış toplandı ve konteyner kentler kuruldu."},{"label":"Deprem bütçesi için ek vergi düzenlemeleri yap; Hazine kaynaklarını doğrudan 300 bin kalıcı deprem konutunun inşasına akıt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bütçe deprem bölgesine yönlendirildi; bir yıl dolmadan kalıcı köy evleri ve konutlar teslim edildi."},{"label":"Deprem bölgesinde derhal 3 aylık Olağanüstü Hal (OHAL) ilan et; yağmayı engelle ve enkaz güvenliğini TSK ve polisle sağla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"OHAL ilanıyla güvenlik sağlandı; yardım koridorları kesintisiz işletildi."},{"label":"\'Kentsel Dönüşüm ve Fay Hatları Üzerinde Yapılaşma Yasağı Kanunu\'nu TBMM\'den geçir; \'Yarısı Bizden\' seferberliğini başlat.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Marmara ve Anadolu için devrim niteliğinde kentsel dönüşüm kanunu yürürlüğe girdi."}]', 75) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_076', 'modern', 'Fahiş Fiyatlar, Konut Kiraları ve Sosyal Konut Hamlesi (ve TBMM Meşveret Kararı)', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Enflasyon ortamında zincir marketlerin fahiş fiyat uygulamaları, fırsatçı emlakçıların kira bedellerini katlaması halkın alım gücünü zorladı. Hükümet, piyasayı regüle etmek için masada.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Fahiş fiyat uygulayan ve kartel oluşturan zincir marketlere Rekabet Kurumu marifetiyle rekor idari para cezaları kes.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Kartel oluşturan zincirlere tarihi cezalar kesildi; piyasa hizaya sokuldu."},{"label":"Ev sahipleri ve kiracılar arasındaki uyuşmazlıklarda \'Zorunlu Arabuluculuk\' mekanizmasını devreye sokarak sulh sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Arabuluculuk devreye girdi; mahkemelerdeki dava yükü %70 oranında azaltıldı."},{"label":"TOKİ marifetiyle \'İlk Evim, İlk İş Yerim\' 250 bin sosyal konut hamlesini başlat; alt gelir grubunu kira derdinden kurtar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal konut temelleri atıldı; konut arzı artırılarak piyasa fiyatları dengelendi."},{"label":"81 ilde Ticaret Bakanlığı ve zabıta denetim timlerini çarşı pazara sür; fahiş fiyatlı stokçuların depolarını anında mühürle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Stokçulara nefes aldırılmadı; piyasa denetimleri sokak sokak uygulandı."},{"label":"Konut kiralarında %25 tavan artış sınırı ve \'Haksız Fiyat Değerlendirme Kurulu Kanunu\'nu yürürlüğe koy.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kiracıyı koruyan yasal tavan getirildi; fırsatçılık kanunen suç sayıldı."}]', 76) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_077', 'modern', 'Milli Teknoloji Hamlesi ve Savunma Sanayii Atılımları (TOGG, KAAN, TCG Anadolu) (ve TBMM Meşveret Kararı)', 'Sanayi ve Teknoloji Bakanlığı', 'Türkiye\'nin yerli otomobili TOGG yollara çıkarken, dünyanın ilk SİHA gemisi TCG Anadolu hizmete girdi ve 5. nesil savaş uçağı KAAN ilk uçuşunu başarıyla gerçekleştirdi. İhracat rekorları kırılıyor.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"}]', '[{"label":"Yerli teknolojilerin fikri ve sınai mülkiyet haklarını uluslararası patent mahkemelerinde küresel teminata bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli projelerin patentleri güvenceye alındı; küresel teknoloji rekabeti başladı."},{"label":"Özel sektör girişimcileri ve üniversitelerle \'TEKNOFEST\' gençlik teknoloji seferberliğini büyüt; beyin göçünü tersine çevir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milyonlarca genç teknolojiye yöneldi; binlerce mühendis anavatana geri döndü."},{"label":"Yıllık 6 milyar doları aşan savunma sanayii ihracat gelirlerini Hazine rezervlerine aktar; Ar-Ge fonlarını büyüt.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Savunma ihracatı Hazine\'ye rekor döviz kazandırdı; cari açığa kalkan oldu."},{"label":"TCG Anadolu ve SİHA filolarını Mavi Vatan ve sınır ötesinde caydırıcı güç olarak daimi göreve çıkar.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Türk donanması küresel amfibi güce dönüştü; sahada mutlak caydırıcılık kuruldu."},{"label":"\'Milli Teknoloji ve Kritik Sanayi Yatırımları Kanunu\' çıkararak stratejik savunma şirketlerinin devredilmesini yasakla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli teknoloji hamlesi kanunla zırhlandı; geleceğin Türkiye\'si teminat altına alındı."}]', 77) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_078', 'modern', 'Gri Listeden Çıkış ve Doğrudan Yabancı Yatırım Rüzgârı (ve TBMM Meşveret Kararı)', 'Hazine ve Maliye Bakanlığı & MASAK', 'Uluslararası Mali Eylem Görev Gücü (FATF) standartlarına uyum sağlayan Türkiye, gri listeden resmen çıkarıldı. Uluslararası kredi derecelendirme kuruluşları not artırırken ülkeye uzun vadeli portföy girişi başladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"MASAK ve yargı denetimini uluslararası şeffaflık standartlarında ödünsüz sürdür; kara para aklamaya sıfır tolerans tanı.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Uluslararası standartlar korundu; Türkiye maliye alanında dünyadan tam not aldı."},{"label":"Yabancı yatırım fonları ve küresel finans merkezleriyle Londra ve New York\'ta yatırımcı toplantıları yaparak güven tazele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yabancı sermaye güveni perçinlendi; milyarlarca dolarlık uzun vadeli fon girişi sağlandı."},{"label":"Gelen doğrudan yatırımları cari açığı kapatacak yenilenebilir enerji, mikroçip ve batarya fabrikalarına yönlendir.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Cari açık hızla daraldı; Merkez Bankası net rezervleri artıya geçti."},{"label":"Kripto varlık piyasaları ve yasadışı bahis ağlarına karşı siber güvenlik ve mali kolluk denetimini en üst seviyeye çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kayıt dışı fon hareketleri durduruldu; mali güvenlik eksiksiz tesis edildi."},{"label":"\'Sermaye Piyasaları ve Kripto Varlıklar Düzenleme Kanunu\'nu yürürlüğe koyarak finansal sistemi kalıcı reforma bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kripto ve sermaye piyasaları kanuni çerçeveye kavuştu; gri liste sayfası ebediyen kapandı."}]', 78) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_079', 'modern', 'Susurluk Kazası ve Devlet-Mafya İlişkileri Raporu (ve Yeni İktisadi Kararlar)', 'Başbakanlık Teftiş Kurulu', 'Balıkesir Susurluk\'ta meydana gelen kaza sonrası emniyet müdürü, milletvekili ve aranan firarinin aynı araçta bulunması derin devlet tartışmalarını patlattı. Kamuoyu \'Aydınlık İçin Bir Dakika Karanlık\' eylemleriyle temiz toplum talep ediyor.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"}]', '[{"label":"Kutlu Savaş raporunun tamamını sansürsüz açıkla; dokunulmazlıkları kaldırıp tüm sorumluları yargıya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; temiz toplum talebi halk nezdinde büyük güven yarattı."},{"label":"Meseleyi TBMM Araştırma Komisyonu\'na havale et; siyasi dengeleri sarsmadan kontrollü bir meclis uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Mecliste partiler arası uzlaşı sağlandı fakat kamuoyu hesap sormanın yarım kaldığını düşündü."},{"label":"Yasadışı faaliyetlerden elde edilen şüpheli kara parayı ve şirket varlıklarını Maliye marifetiyle Hazine\'ye irad kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kara para aklama çarklarına mali darbe vuruldu, hazine kasasına gelir kaydedildi."},{"label":"Emniyet ve istihbarat teşkilatında ani bir iç tasfiye yap; kamu düzenini bozan klikleri derhal görevden uzaklaştır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisindeki hizipler dağıtıldı; devlet otoritesi hissettirildi."},{"label":"\'Organize Suçlarla Mücadele Kanunu\' çıkar; devlet görevlilerinin çetelerle irtibatını en ağır cezalara bağlayan yapısal reform yap.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yeni mevzuat ile çeteleşmenin önüne yasal set çekildi; kurumsal denetim güçlendirildi."}]', 79) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_080', 'modern', 'Kardak Kayalıkları Krizi ve Ege Gerilimi (ve Yeni İktisadi Kararlar)', 'Milli Güvenlik Kurulu (MGK)', 'Ege Denizi\'ndeki Kardak kayalıklarına Yunan sahil güvenlik birliklerinin bayrak dikmesiyle iki ülke donanmaları burun buruna geldi. Savaş riski dakikalarla ölçülüyor.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Uluslararası deniz hukukuna ve Lozan Antlaşması\'na dayanarak BM nezdinde egemenlik haklarını resmen tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Diplomatik ve hukuki tezler uluslararası alanda kayda geçirildi."},{"label":"ABD ve NATO arabuluculuğunu kabul et; \'O bayrak inecek, o asker gidecek\' prensibiyle eşzamanlı çekilme formülünde uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik kanallar işletildi; kriz çatışmaya dönüşmeden statüko muhafaza edildi."},{"label":"Ege\'deki askeri devriye ve donanma harcamaları için savunma bütçesine acil ödenek aktar; askeri hazır bulunuşluğu finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Donanmanın operasyonel bütçesi tahkim edildi; krizin lojistik maliyeti karşılandı."},{"label":"SAT komandolarını gece operasyonuyla komşu kayalığa çıkar; Türk bayrağını dikerek caydırıcı askeri üstünlüğü fiilen göster.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"SAT timlerinin başarılı intikaliyle askeri üstünlük kuruldu; karşı taraf geri adım attı."},{"label":"\'Ege Deniz Yetki Alanları ve Gri Bölgeler Doktrini\' ilan et; kara suları ve hava sahası ihlallerini otomatik mukabeleye bağla.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kalıcı angajman kuralları mevzuata girdi; Ege\'de caydırıcı doktrin tesis edildi."}]', 80) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_081', 'modern', '28 Şubat Süreci ve Bürokrasi Gerilimi (ve Yeni İktisadi Kararlar)', 'Başbakanlık', 'Milli Güvenlik Kurulu\'nun 9 saat süren toplantısında hükümete 18 maddelik laiklik ve irtica bildirisinin imzalatılması istendi. Hükümet ile bürokrasi arasında rejim tansiyonu tırmanıyor.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Anayasal parlamenter yetkilere sadık kal; kararları TBMM Genel Kurulu\'na getirerek sivil siyasetin meşruiyetini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki meşruiyet savunuldu fakat bürokratik vesayet baskısı tırmandı."},{"label":"Koalisyon ortaklarıyla oturup bildiriyi yumuşatan bir meşveret metni üzerinde anlaş; hükümeti erken seçime taşıyarak krizi ötele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Siyasi uzlaşıyla sıcak gerilim dindirildi; parlamento erken seçim takvimine girdi."},{"label":"Gerilimin piyasayı vurmasını engellemek için Hazine faizlerini yükselt; yabancı sermaye çıkışını durduracak likidite tedbiri al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok bir miktar frenlendi fakat bütçe faiz yükü altında ezildi."},{"label":"Kamu düzenini tehdit eden tüm yasadışı oluşumlara karşı sert idari genelgeler yayımla; devlet ciddiyetini tavizsiz uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İdari tedbirler hızla uygulandı; kamu kurumlarında sıkı teftiş dalgası başladı."},{"label":"\'Temel Haklar ve Kamu Görevlileri Güvenlik Soruşturması Kanunu\' çıkararak yetki karmaşasını yasal çerçeveye bağla.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kurumsal yetkiler kanunla sınırlandı; vesayet tartışmaları mevzuat zeminine çekildi."}]', 81) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_082', 'modern', '17 Ağustos 1999 Marmara Depremi ve Afet Fonu (ve Yeni İktisadi Kararlar)', 'Kriz Yönetim Merkezi', 'Gölcük merkezli 7.4 büyüklüğündeki depremde on binlerce bina yıkıldı, sanayi kalbi Marmara enkaza döndü. Acil arama kurtarma, çadır kentler ve ağır yeniden inşa faturası devleti bekliyor.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri ve usulsüz ruhsat veren belediye yetkilileri hakkında derhal tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı hızla devreye girdi; ihmali olan sorumlular tek tek gözaltına alındı."},{"label":"Uluslararası yardım çağrısı (4. Seviye Alarm) yap; tüm sivil toplum örgütleriyle koordinasyon kurup çadır kentleri ortaklaşa yönet.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma en üst seviyeye çıktı; uluslararası yardım köprüsü kuruldu."},{"label":"Yeniden inşa için geçici \'Özel İletişim Vergisi\' ve deprem tahvilleri çıkar; Hazine bütçesini afet imarına tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Deprem bütçesi oluşturuldu; altyapı ve kalıcı konutların finansmanı güvenceye bağlandı."},{"label":"Bölgeye askeri birlikleri ve arama-kurtarma taburlarını sevk et; yağma ve asayişsizliğe karşı sıkı devriye nizamı kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başında arama kurtarma yaptı; bölgede asayiş eksiksiz sağlandı."},{"label":"\'Afet Riski Altındaki Alanlar ve Zorunlu Deprem Sigortası (DASK) Kanunu\' çıkar; yapı denetimini özel şirket murakabesine bağla.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve Yapı Denetim sistemi kurularak Türkiye\'nin afet mevzuatında milat oluşturuldu."}]', 82) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_083', 'modern', 'Terör Elebaşının Yakalanması ve Yargılama Süreci (ve Yeni İktisadi Kararlar)', 'Adalet Bakanlığı', 'Kenya\'da düzenlenen özel operasyonla yakalanan terör örgütü lideri Türkiye\'ye getirildi. İmralı Adası\'nda özel güvenlikli mahkeme kurulurken iç ve dış kamuoyunda yoğun bir diplomatik ve hukuki süreç başladı.', '[{"id":"char_adli_yargi_hakimi","name":"DGM Başsavcısı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"DGM duruşmalarını şehit ailelerinin ve yerli/yabancı basının gözü önünde şeffafça yürüt; hukukun üstünlüğünden milim sapma.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi yargılama evrensel hukuk kurallarıyla tamamlandı; adalet meşruiyetini ispatladı."},{"label":"AİHM ihtiyati tedbir kararlarını ve Avrupa Konseyi taahhütlerini dikkate alarak geniş tabanlı siyasi meşveret yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Avrupa ile kriz çıkması önlendi; diplomatik kanallar açık tutuldu."},{"label":"Terörle mücadele bölgelerine acil ekonomik kalkınma fonu tahsis et; bölge gençliğine istihdam kapıları aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Güneydoğu\'da ekonomik rehabilitasyon başlatıldı; bölge halkının refahı desteklendi."},{"label":"İmralı Adası\'nda deniz ve hava koruma kalkanını en üst seviyeye çıkar; sınır boylarında terör inlerine amansız operasyon başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Örgütün toparlanma çabaları sahada ezildi; güvenlik kuvvetleri mutlak hakimiyet kurdu."},{"label":"Avrupa Birliği uyum paketi kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet Kanunu\'nu TBMM\'den geçir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İdam cezası mevzuattan çıkarılarak ağırlaştırılmış müebbete dönüştürüldü; uluslararası kriz aşıldı."}]', 83) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_084', 'modern', '2001 Bankacılık Krizi ve Gecelik Faiz Şoku (ve Yeni İktisadi Kararlar)', 'Merkez Bankası', 'Çankaya Köşkü\'ndeki Anayasa geriliminin ardından gecelik faizler %7500\'e fırladı. Sabit kur rejimi çöktü, onlarca batık banka Tasarruf Mevduatı Sigorta Fonu\'na (TMSF) devredildi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"İçi boşaltılan batık bankaların patronları ve hortumcular hakkında derhal ağır ceza davaları aç ve mal varlıklarına el koy.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Banka hortumcularının peşine düşüldü; halkın gasbedilen mevduatının hesabı soruldu."},{"label":"İş dünyası, bankalar birliği ve sendikalarla \'Mali İstikrar Protokolü\' imzala; reel sektörün borçlarını vadelere yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal taraflarla mutabakat sağlandı; reel sektörün topyekûn iflası önlendi."},{"label":"Dalgalı kur rejimine geç; Kemal Derviş\'in \'Güçlü Ekonomiye Geçiş Programı\'nı uygulayarak acil IMF ve Dünya Bankası kredisini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dalgalı kura geçildi; piyasalardaki kanama durduruldu, yabancı kaynak akışı başladı."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan finans kuruluşlarına karşı mali zabıta ve BDDK müfettişlerini seferber et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasa spekülatörlerine geçit verilmedi; mali disiplin zorla da olsa sağlandı."},{"label":"Bankacılık Düzenleme ve Denetleme Kurumu (BDDK) Kanunu\'nu güncelle; Merkez Bankası\'na tam fiyat istikrarı bağımsızlığı tanı.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Merkez Bankası kanunen bağımsız kılındı; Türk bankacılık sistemi modern standartlara kavuştu."}]', 84) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_085', 'modern', 'AB Uyum Yasaları ve İdam Cezasının Kaldırılması (ve Yeni İktisadi Kararlar)', 'TBMM Genel Kurulu', 'Türkiye\'nin Avrupa Birliği\'ne adaylık sürecinde Kopenhag kriterlerine uyum için idam cezasının kaldırılması, anadilde yayın ve dernekleşme özgürlüğü içeren tarihi reform paketi Meclis\'e geldi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Temel insan hakları ve evrensel adalet ilkelerini referans al; idam cezasını savaş halleri dahil anayasadan tamamen çıkar.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Evrensel hukuk standartlarına uyuldu; Türkiye\'nin insan hakları karnesi güçlendi."},{"label":"Mecliste grubu bulunan tüm siyasi partilerle geniş tabanlı müzakere yürüt; milli hassasiyetleri gözeten ortak bir uyum metni çıkar.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Geniş bir konsensüs ile meclisten tarihi reform paketi geçti."},{"label":"AB reformları ile gelecek doğrudan yabancı yatırım ve hibe fonlarını KOBİ\'lerin teknoloji dönüşümüne tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomiye AB çıpasıyla rekor düzeyde doğrudan yabancı sermaye girişi sağlandı."},{"label":"Reformların milli birlik ve kamu düzenini zaafa uğratmaması için güvenlik teşkilatına ek istihbari yetkiler ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik parametreleri sıkı tutuldu; devlet refleksi muhafaza edildi."},{"label":"\'Avrupa Birliği Müktesebatına Uyum ve Demokratikleşme Kanunu\'nu yürürlüğe koy; yargıda savunma hakkını kanunen genişlet.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sivil haklar mevzuatta kalıcı hale geldi; Türkiye aday ülke statüsünde öne geçti."}]', 85) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_086', 'modern', '1 Mart Tezkeresi ve Irak Savaşı Kararı (ve Yeni İktisadi Kararlar)', 'TBMM Genel Kurulu', 'Irak\'a müdahale hazırlığındaki ABD birliklerinin Türkiye toprakları üzerinden kuzey cephesi açmasına ve TSK\'nın Irak\'a gönderilmesine ilişkin tezkere TBMM oylamasına sunuldu. Bölgesel yangın kapıda.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"TBMM\'nin demokratik iradesine tam saygı göster; tezkere reddedilirse \'Milletin kararı başımızın tacıdır\' diyerek kararı uygula.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Parlamenter demokrasi sınavı başarıyla geçti; meclis iradesi tüm dünyaya duyuruldu."},{"label":"ABD ile müzakereleri sürdürürken komşu bölge ülkeleriyle diplomatik temas kur; Ortadoğu\'da barışçıl diplomasi kanallarını zorla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Bölgesel diplomaside Türkiye saygın bir arabulucu aktör olarak konumlandı."},{"label":"Tezkerenin reddi halinde doğacak ekonomik yardımdan vazgeç; milli tasarrufları artırarak kendi özkaynaklarına güven.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Ekonomik şantaja boyun eğilmedi; bütçe disiplini kendi kaynaklarıyla korundu."},{"label":"Kuzey Irak sınır boylarına zırhlı tugayları yığ; sınırda oluşabilecek terör koridoruna karşı caydırıcı askeri yığınak yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır hattı çelikten bir kalkanla kapatıldı; sınır güvenliği garanti altına alındı."},{"label":"\'Yurtdışına Asker Gönderme ve Yabancı Birlikleri Kabul Kanunu\'nu güncelleyerek milli güvenlik kırmızı çizgilerini kanunlaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Sınır ötesi operasyon usulleri kalıcı yasal kurallara bağlandı."}]', 86) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_087', 'modern', 'Türk Lirasından Altı Sıfırın Atılması (YTL Geçişi) (ve Yeni İktisadi Kararlar)', 'Merkez Bankası ve Darphane', 'Yılların yüksek enflasyonunun simgesi haline gelen milyonluk banknotlar tarihe karışıyor. \'Bol sıfırlı para ülkenin itibarını zedeliyor\' gerekçesiyle Yeni Türk Lirası\'na geçiş kararı alındı.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Geçiş sürecinde yuvarlama bahanesiyle gizli zam yapan fırsatçıları Tüketici Mahkemeleri\'nde ağır cezalarla yargıla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Fırsatçılara göz açtırılmadı; tüketici hakları mahkemelerce korundu."},{"label":"Tüm bankalar, perakende zincirleri ve esnafla bir yıllık çift para birimli fiyat etiketleme uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada kaos çıkması önlendi; halk kuruşlu hesaplara huzurla alıştı."},{"label":"Yeni Türk Lirası\'nı saf enflasyon hedeflemesi ve sıkı para politikasıyla destekle; TL\'nin itibarını küresel piyasalarda yükselt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Türk Lirası rekor değer kazandı; enflasyon tek haneli rakamlara doğru geriledi."},{"label":"Eski paranın piyasadan çekilmesi ve yeni banknotların naklinde Merkez Bankası ve polis zırhlı lojistiğini kusursuz işlet.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tüm Türkiye\'de banknot değişimi sıfır kayıp ve tam güvenlikle tamamlandı."},{"label":"\'Türkiye Cumhuriyeti Para Birimi Hakkında Kanun\' çıkar; kuruş sistemini ve sahte para cezalarını en katı hükümlere bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Para basım ve tedavül nizamı modern kanunla teminat altına alındı."}]', 87) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_088', 'modern', '2007 Cumhurbaşkanlığı Seçimi (367 Krizi ve E-Muhtıra) (ve Yeni İktisadi Kararlar)', 'Anayasa Mahkemesi', 'TBMM\'deki Cumhurbaşkanlığı seçiminde ilk tur oylama için Meclis\'te 367 milletvekilinin hazır bulunması gerektiği iddiasıyla Anayasa Mahkemesi\'ne başvuruldu. Aynı gece Genelkurmay sitesinde E-Muhtıra yayımlandı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Hukukun evrensel içtihatlarına sarıl; Anayasa Mahkemesi kararını ne olursa olsun harfiyen uygula ve meşruiyete sarıl.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ilkesine bağlılık teyit edildi; kriz anayasal zeminde karşılandı."},{"label":"Mecliste kilitlenen düğümü çözmek için \'Söz de karar da milletindir\' de; erken genel seçim ve halkoylaması çağrısı yap.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Millet sandığına gidildi; siyasi kilitlenme halkın doğrudan iradesiyle çözüldü."},{"label":"Siyasi çalkantının faiz ve döviz piyasalarında panik yaratmasını engellemek için Hazine borçlanmasını dengeli yürüt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasa sarsıntısı sınırlandı; ekonominin büyüme ivmesi muhafaza edildi."},{"label":"Gece yarısı muhtırasına karşı sabah Başbakanlık bildirisiyle cevap ver: \'Hükümet emir almaz, genelkurmay hükümete bağlıdır!\'.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sivil otoritenin üstünlüğü ilk kez bu kadar net bir karşı bildiriyle perçinlendi."},{"label":"Anayasa değişikliği yaparak \'Cumhurbaşkanının doğrudan halk tarafından seçilmesi\' maddesini referanduma sun.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Cumhurbaşkanını doğrudan halkın seçmesi anayasallaştı; 367 garabeti tarihe gömüldü."}]', 88) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_089', 'modern', '2008 Küresel Ekonomik Krizi ve Sanayi Teşvikleri (ve Yeni İktisadi Kararlar)', 'Hazine ve Maliye Bakanlığı', 'Wall Street\'te Lehman Brothers\'ın batışıyla başlayan küresel mali fırtına dünyayı sardı. İhracat pazarları daralırken fabrikalarda çarkların durma tehlikesi baş gösterdi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"İşten çıkarmaları engellemek için \'Kısa Çalışma Ödeneği\'ni hukuk zemininde hızla aktif et; emekçinin hakkını koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"İşçilerin tazminat ve maaş hakları korundu; kitlesel işten çıkarmalar önlendi."},{"label":"İhracatçılar, TOBB ve sendikalarla \'Kriz Meclisi\' kur; vergi indirimleri ve teşviklerle çarkların dönmesini sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Geniş tabanlı uzlaşı paketi yürürlüğe girdi; üretim hatları canlı tutuldu."},{"label":"KDV ve ÖTV\'de geçici indirimler yap, KOSGEB sıfır faizli cansuyu kredisi aç; \'Kriz teğet geçecek\' güvenini tesis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İç piyasada talep canlandırıldı; Türkiye krizi en hızlı atlatan ülkelerden biri oldu."},{"label":"Stratejik sanayi tesislerini ve ihracatçı limanları koruma altına al; kritik tedarik zincirlerinin aksamasını önle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Lojistik koridorlar açık tutuldu; stratejik sanayi üretimi aksamadı."},{"label":"\'Yeni Yatırım Teşvik ve Sanayi Bölgeleri Kanunu\' çıkar; bölgesel ve sektörel kademeli teşvik sistemini kalıcı kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'nin modern yatırım teşvik sistemi yasalaştı; sanayide bölgesel sıçrama başladı."}]', 89) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_090', 'modern', '12 Eylül 2010 Anayasa Referandumu Paketi (ve Yeni İktisadi Kararlar)', 'TBMM Genel Kurulu', 'Anayasa Mahkemesi ve HSYK\'nın yapısını değiştiren, kadınlara pozitif ayrımcılık getiren ve darbecilerin yargılanmasının önünü açan 26 maddelik anayasa paketi referanduma sunuluyor.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'ne \'Bireysel Başvuru Hakkı\'nı tanı; vatandaşların AİHM\'den önce iç hukukta adalet aramasını sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"AYM\'ye bireysel başvuru hakkı Türk hukuk tarihinin en büyük kazanımı oldu."},{"label":"Yargı reformu maddelerini meclisteki tüm partilerle madde madde müzakere ederek milli mutabakat zemininde geçir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Muhalefetle müzakere masası kuruldu; kutuplaşma yumuşatılmaya çalışıldı."},{"label":"Referandum ve yargı reformunun getireceği hukuki öngörülebilirlikle uluslararası doğrudan yatırımları teşvik et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hukuki güvence beklentisiyle Türkiye\'ye rekor doğrudan sermaye girişi gerçekleşti."},{"label":"12 Eylül askeri darbesini yapan generallerin dokunulmazlığını kaldıran maddeyi oylat; vesayet artıklarını tasfiye et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Darbecilerin yargılanması anayasal güvenceye kavuştu; askeri vesayet geriletildi."},{"label":"\'Hakimler ve Savcılar Yüksek Kurulu ile Kamu Denetçiliği (Ombudsmanlık) Kanunu\'nu yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yargı idaresi geniş tabanlı temsile açıldı; ombudsmanlık kurumu hayata geçirildi."}]', 90) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_091', 'modern', 'Mavi Marmara Olayı ve Doğu Akdeniz Diplomatik Krizi (ve Yeni İktisadi Kararlar)', 'Dışişleri Bakanlığı', 'Gazze\'ye insani yardım taşıyan Mavi Marmara gemisine uluslararası sularda İsrail komandolarınca kanlı baskın düzenlendi, 10 Türk vatandaşı hayatını kaybetti. Millet ayakta.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Uluslararası Ceza Mahkemesi ve BM İnsan Hakları Konseyi\'ne suç duyurusu yap; sorumluların gıyabında Türk mahkemelerinde dava aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası hukuk ve Türk mahkemeleri failler hakkında yakalama kararı çıkardı."},{"label":"Diplomatik ilişkileri ikinci kâtip seviyesine indir; \'Özür, tazminat ve Gazze ablukasının hafifletilmesi\' şartı koyarak müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Onurlu diplomasiden taviz verilmedi; yıllar sonra resmi özür ve tazminat sağlandı."},{"label":"İsrail ile askeri ve stratejik ihaleleri dondur; savunma sanayiinde yerli üretim payını artıracak bütçe fonu kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yabancı savunma bağımlılığı kırıldı; yerli İHA ve mühimmat projelerine bütçe aktarıldı."},{"label":"Türk Deniz Kuvvetleri fırkateynlerini Doğu Akdeniz\'de seyrüsefer güvenliği için devriyeye çıkar; deniz sahasını koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Donanmanın caydırıcılığı Akdeniz\'de net biçimde sergilendi; mavi sularda gövde gösterisi yapıldı."},{"label":"\'Mavi Vatan ve Doğu Akdeniz Deniz Yetki Alanları Strateji Belgesi\'ni resmi devlet doktrini olarak ilan et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Mavi Vatan stratejisi resmiyet kazandı; Doğu Akdeniz\'de sismik arama hakları korundu."}]', 91) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_092', 'modern', 'Gezi Parkı Eylemleri ve Sosyal Tansiyon (ve Yeni İktisadi Kararlar)', 'İçişleri Bakanlığı', 'Taksim Gezi Parkı\'ndaki ağaçların sökülmesi ve Topçu Kışlası projesine karşı başlayan çevre protestoları, polisin sert gaz müdahalesi sonrası ülke geneline yayılan kitlesel gösterilere dönüştü.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"İdare Mahkemesi\'nin imar planı yürütmeyi durdurma kararını derhal uygula; orantısız güç kullanan polisler hakkında soruşturma aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı kararına riayet edildi; orantısız güç kullanan amirler açığa alındı."},{"label":"Toplumun temsilcileri, sanatçılar ve çevre inisiyatifleriyle Başbakanlık\'ta meşveret masası kur; \'Halk oylaması (plebisit)\' öner.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Müzakere masası tansiyonu düşürdü; Taksim\'in geleceği için sandık formülü sunuldu."},{"label":"Olayların piyasada yarattığı dalgalanmayı önlemek için Merkez Bankası rezervleriyle faiz ve döviz spekülasyonunu püskürt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik şok dalgası göğüslendi; faiz lobisinin panik yaratması engellendi."},{"label":"Kamu binalarını ve esnaf dükkânlarını tahrip eden marjinal vandallara karşı polis kuvvetlerine kesin asayiş emri ver.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Meydanlar ve kamu mülkleri güvenceye alındı; vandallık eylemleri bastırıldı."},{"label":"\'Kentsel Dönüşüm, Şehir Estetiği ve Katılımcı Şehircilik Kanunu\' çıkar; büyük projelerde halkın görüşünü yasal zorunluluk yap.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Şehir planlamasında sivil katılım kanunlaştı; çevre mevzuatı tahkim edildi."}]', 92) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_093', 'modern', 'Suriye Sınır Güvenliği ve Mülteci Dalgası (ve Yeni İktisadi Kararlar)', 'Göç İdaresi Genel Müdürlüğü', 'Suriye iç savaşının şiddetlenmesiyle yüz binlerce sivil Türk sınırına yığıldı. Açık kapı politikası uygulanırken şehirlerde demografik, güvenlik ve ekonomik baskı artıyor.', '[{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cenevre Mülteciler Sözleşmesi\'ne uygun olarak \'Geçici Koruma Statüsü\' ver; kayıt dışılığı hukuki denetim altına al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki statü netleştirildi; sığınmacılar biyometrik kimlik sistemine kaydedildi."},{"label":"Avrupa Birliği ile \'18 Mart Geri Kabul Mutabakatı\' imzala; mülteci yükünün maliyetini ve külfet paylaşımını Brüksel\'e bölüştür.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"AB ile diplomatik mutabakat sağlandı; milyarlarca avroluk destek fonu temin edildi."},{"label":"Sığınmacıların kayıt dışı çalışmasını önlemek için çalışma izni kotası getir; vergi ve SGK prim gelirlerini hazineye bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İş gücü piyasasında haksız rekabet frenlendi; kayıt içi çalışma özendirildi."},{"label":"Suriye sınırına 900 kilometrelik modüler beton güvenlik duvarı ve elektro-optik kuleler ör; yasadışı geçişleri sıfırla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sınır duvarı tamamlandı; sınırdan kaçak geçişler ve terörist sızmaları bıçak gibi kesildi."},{"label":"\'Yabancılar ve Uluslararası Koruma Kanunu\' çıkar; modern Göç İdaresi Başkanlığı\'nı kurarak sınır dışı mekanizmasını hızlandır.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye ilk kez modern bir göç teşkilatına kavuştu; düzensiz göçle mücadele kurumsallaştı."}]', 93) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_094', 'modern', '15 Temmuz Darbe Girişimi ve Milli Direniş (ve Yeni İktisadi Kararlar)', 'Cumhurbaşkanlığı', 'FETÖ mensubu hain cuntanın F-16\'lar ve tanklarla TBMM\'yi bombaladığı, köprüleri kapattığı darbe girişimine karşı millet meydanlara indi. Demokrasi ve devlet bekası ölüm kalım savaşı veriyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Cumhuriyet Başsavcılıklarına talimat ver; darbeciler ve sivil imamlar hakkında anayasal düzeni ihlalden davalar açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yargı cuntacılara anında darbe vurdu; mahkemeler hesap sormaya başladı."},{"label":"Meydanlarda \'Demokrasi Nöbetleri\' tutan milyonlarla buluş; Yenikapı\'da tüm siyasi parti liderleriyle ortak milli miting yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Yenikapı Ruhu doğdu; millet ve tüm siyasi partiler darbelere karşı kenetlendi."},{"label":"Maliye ve MASAK\'ı devreye sok; terör örgütüne finans sağlayan şirketlere, holdinglere ve bankalara TMSF kayyumu ata.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Örgütün milyarlarca liralık finans ahtapotu çökertildi; varlıklar kamuya geçti."},{"label":"Milleti meydanlara ve havalimanlarına çağır; polis, sadık TSK neferleri ve halkın gücüyle hain darbe kalkışmasını ez.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Halk tankların önüne yattı; hain kalkışma birkaç saat içinde kanla ve canla püskürtüldü."},{"label":"Milli Güvenlik Kurulu kararıyla Olağanüstü Hal (OHAL) ilan et; Kanun Hükmünde Kararnamelerle (KHK) devletteki kriptoları tasfiye et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Bürokrasi ve ordudaki paralel yapı temizlendi; devlet mekanizması yeniden yapılandırıldı."}]', 94) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_095', 'modern', 'Fırat Kalkanı ve Zeytin Dalı Sınır Ötesi Harekâtları (ve Yeni İktisadi Kararlar)', 'Milli Güvenlik Kurulu (MGK)', 'Suriye sınırından Kilis ve Gaziantep\'e atılan roketler ve oluşturulmak istenen terör koridoruna karşı TSK, sınır ötesi harekat başlatma kararı aldı. Rusya ve ABD ile sıcak saha diplomasisi devrede.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"BM Şartı\'nın 51. Maddesi\'ndeki \'Meşru Müdafaa Hakkı\'nı uluslararası alanda deklare ederek askeri müdahaleyi hukuki zemine oturt.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Uluslararası meşruiyet sağlandı; operasyonun hukuki temelleri dünyaya kabul ettirildi."},{"label":"Astana Süreci çerçevesinde Rusya ve İran ile diplomatik uzlaşı sağla; sahada istenmeyen sürtüşmeleri önle.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Astana mutabakatı işledi; sahada hava sahası koordinasyonu başarıyla sağlandı."},{"label":"Harekât bölgesindeki sivillere insani yardım ve altyapı bütçesi tahsis et; Suriyelilerin güvenli bölgelere gönüllü dönüşünü finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Afrin ve Cerablus\'ta hayat normale döndü; yüz binlerce Suriyeli vatanına döndü."},{"label":"TSK zırhlı birlikleri ve yerli SİHA\'larla sınırdan içeri gir; DEAŞ ve PKK/YPG terör koridorunu ortadan ikiye böl.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Mehmetçik terör koridorunu parçaladı; sınır şehirlerimiz roket tehdidinden tamamen kurtuldu."},{"label":"\'Milli Savunma Sanayii Teşvik Kanunu\' çıkararak harekâtta kullanılan yerli mühimmat ve zırhlı araç üretimini devlet garantisine al.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yerli savunma payı %80\'e dayandı; yabancı ambargolar milli silahlarla aşıldı."}]', 95) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_096', 'modern', 'Cumhurbaşkanlığı Hükümet Sistemine Geçiş (2017 Referandumu) (ve Yeni İktisadi Kararlar)', 'TBMM ve Yüksek Seçim Kurulu (YSK)', 'Başbakanlık makamını kaldıran, yürütmeyi tek elde toplayan ve bakanlıkları doğrudan Cumhurbaşkanlığı\'na bağlayan yeni anayasa paketi halk oylamasına gitti. Sistemde köklü makas değişimi kapıda.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Kuvvetler ayrılığı ilkesini korumak için Meclis\'in kanun yapma ve bütçe denetim yetkilerini anayasal güvenceye bağla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Meclisin kanun koyucu tek erki olduğu teyit edildi; yasal denetim sürdürüldü."},{"label":"Cumhur İttifakı ve parlamento meşveretiyle yürütme kararnamelerini istişareye aç; siyasi istikrarı ortak akılla sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Siyasi istikrar tahkim edildi; parlamentoda hükümet ortaklığı sağlam temele oturdu."},{"label":"Bürokratik hantallığı ortadan kaldırarak yatırım kararlarını hızlandır; doğrudan yatırımlar için \'Tek Durak Ofis\' sistemini kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bürokrasi azaltıldı; mega sanayi ve altyapı yatırımları hızla hayata geçti."},{"label":"Devlet Teşkilatı Kararnameleri ile Genelkurmay ve MİT\'i doğrudan Cumhurbaşkanlığı\'na bağlayarak milli güvenlik zincirini tekilleştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Güvenlik bürokrasisinde emir-komuta birliği sağlandı; hızlı karar alma refleksi gelişti."},{"label":"\'1 Nolu Cumhurbaşkanlığı Kararnamesi\' ile tüm bakanlık ve kurulların modern teşkilat şemasını yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yeni sistemin idari omurgası kuruldu; bürokratik vesayet ve koalisyon krizleri son buldu."}]', 96) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_097', 'modern', 'Rahip Brunson Krizi ve Döviz Kuru Şoku (2018) (ve Yeni İktisadi Kararlar)', 'Hazine ve Maliye Bakanlığı', 'İzmir\'de casusluk iddiasıyla yargılanan Amerikalı rahibin serbest bırakılmaması üzerine ABD Başkanı Trump, Türkiye\'ye çelik ve alüminyum yaptırımları açıkladı. Dolar/TL bir günde fırladı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Yargı bağımsızlığını savun: \'Türk yargısı kimseden emir almaz; karar sadece bağımsız mahkemelerindir\' duruşunu koru.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Yargı egemenliği tavizsiz savunuldu; mahkeme delillere göre karar verdi."},{"label":"Washington ile diplomatik heyetler arası müzakere yürüt; yargılama sürecini tahliye kararıyla hukuki çerçevede neticelendir.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik tansiyon düşürüldü; ABD yaptırımları karşılıklı olarak kaldırıldı."},{"label":"Merkez Bankası faiz kararını güncelle; bankacılık swap kısıtlamalarını devreye sokup döviz spekülasyonunu kilitle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Swap kanalları kapatıldı; Londra kaynaklı kur saldırısı bertaraf edildi."},{"label":"Stratejik döviz rezervlerini koru ve iç piyasada \'Milli Dayanışma\' çağrısı yaparak yastık altı altın ve dövizleri sisteme sok.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Millet döviz bürolarına koşarak devletine sahip çıktı; kur baskısı göğüslendi."},{"label":"\'Finansal İstikrar ve Kalkınma Komitesi Kanunu\' çıkar; döviz manipulasyonuna ağır idari ve hapis cezaları getir.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Mali piyasaları manipüle edenlere karşı sert yaptırımlar yasalaştı."}]', 97) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_098', 'modern', 'S-400 Alımı ve F-35 Savunma Sanayii Ambargoları (ve Yeni İktisadi Kararlar)', 'Savunma Sanayii Başkanlığı', 'Patriot füze sisteminin ABD tarafından satılmaması üzerine Türkiye, hava savunmasını Rus S-400 sistemiyle tahkim etti. ABD, Türkiye\'yi ortak olduğu F-35 konsorsiyumundan tek taraflı çıkardı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"F-35 programı için Türkiye\'nin ödediği 1.4 milyar doların iadesi için uluslararası tahkime başvur; sözleşme haklarını ara.","preview":"Adalet +8, Halk +5, Hazine +7, Otorite +6","effects":{"justice":8,"people":5,"treasury":7,"military":0,"authority":6},"log":"Uluslararası tahkimde haklarımız arandı; ABD tarafı tazminat masasına çekildi."},{"label":"NATO müttefikleriyle müzakereleri sürdür; hava kuvvetlerinin vurucu gücünü F-16 modernizasyon kitiyle güvenceye al.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik denge gözetildi; mevcut jet filosu yerli mühimmatlarla modernize edildi."},{"label":"F-35 ambargosunu fırsata çevir; Hazine kaynaklarını doğrudan Milli Muharip Uçak (KAAN) ve KIZILELMA projelerine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi karar alındı; KAAN ve insansız savaş uçağı KIZILELMA hızla hangardan çıktı."},{"label":"S-400 bataryalarını stratejik hava sahasına yerleştir; Doğu Akdeniz ve Anadolu hava sahasını tam koruma kalkanına al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hava savunma caydırıcılığı sağlandı; sınır ötesi operasyonlar güvenceye bağlandı."},{"label":"\'Milli Savunma Sanayii İcra Komitesi ve Ar-Ge Kanunu\' çıkar; savunma sanayiinde yerlilik oranını %85\'e çıkarma zorunluluğu koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma sanayiinde tarihi bağımsızlık reformu tescillendi; KAAN göklerle buluştu."}]', 98) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_099', 'modern', '2020 COVID-19 Pandemisi ve Kapanma Kararları (ve Yeni İktisadi Kararlar)', 'Sağlık Bakanlığı Koronavirüs Bilim Kurulu', 'Küresel koronavirüs salgını Türkiye\'ye ulaştı. Şehirlerarası seyahat kısıtlamaları, maske zorunluluğu, esnafın kepenk kapatması ve aşı tedariki devleti eşi benzeri görülmemiş bir krizle yüzleştirdi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Anayasa\'nın seyahat ve çalışma hürriyeti sınırlarını gözet; tüm kısıtlamaları İl Hıfzıssıhha Kurulu kararlarına bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kısıtlamalar hukuki meşruiyet zemininde yürütüldü; keyfilik önlendi."},{"label":"Bilim Kurulu, meslek odaları ve esnafla haftalık değerlendirme yap; kademeli normalleşme takvimini uzlaşıyla açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumun her kesimiyle diyalog sürdürüldü; salgın yönetimine güven perçinlendi."},{"label":"Kepenk kapatan esnafa hibe desteği, kira yardımı ve çalışanlara \'Kısa Çalışma Ödeneği\' tahsis et; Hazine bütçesini halka aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal koruma kalkanıyla milyonlarca aileye ve esnafa milyarlarca lira destek aktarıldı."},{"label":"Sokağa çıkma kısıtlamalarında Emniyet ve Vefa Sosyal Destek Gruplarını sahaya sür; yaşlıların ihtiyaçlarını evlerine ulaştır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Vefa ekipleri tarih yazdı; yaşlılar ve ihtiyaç sahipleri yalnız bırakılmadı."},{"label":"Yerli aşı TURKOVAC projesini ve Şehir Hastaneleri altyapısını hızla tamamla; Türkiye\'yi sağlık lojistiğinde merkez kıl.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"TURKOVAC üretildi; Şehir Hastaneleri sayesinde Türkiye salgını en az kayıpla atlattı."}]', 99) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_100', 'modern', 'Kur Korumalı Mevduat (KKM) ve Faiz Politikası Kararları (ve Yeni İktisadi Kararlar)', 'Hazine ve Maliye Bakanlığı & Merkez Bankası', 'Döviz kurundaki ani yükseliş karşısında 20 Aralık 2021 gecesi Kur Korumalı Mevduat (KKM) sistemi açıklandı. Milyarlarca liralık döviz çözülürken Hazine ve Merkez Bankası üzerine kur farkı yükü bindi.', '[{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Bankacılık ve sermaye piyasalarında şeffaflığı sağla; KKM hesaplarının yasal çerçevesini Sayıştay denetimine aç.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Tüm hesaplar yasal denetime kavuşturuldu; mali şeffaflık sağlandı."},{"label":"Bankalar Birliği ve mevduat sahipleriyle toplantı yap; KKM\'den standart TL mevduata geçişi yumuşak teşviklerle sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Mevduat sahipleri tedirgin edilmeden çıkış stratejisi başarıyla uygulandı."},{"label":"Parasal sıkılaşma ve rasyonel faiz politikasına dön; KKM stokunu eritip Merkez Bankası rezervlerini rekor seviyeye çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ortodoks politikalara dönüldü; KKM stoku eritildi, rezervler tarihi zirveye ulaştı."},{"label":"Döviz alım-satımında hileli arbitraj yapan kurumlara karşı MASAK ve SPK incelemelerini en sert cezalarla uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kur manipülatörlerine rekor cezalar kesildi; piyasa disiplini korundu."},{"label":"\'Türk Lirası Mevduat ve Yatırım Araçlarının Korunması Kanunu\' çıkararak KKM\'nin tasfiyesini yasal takvime bağla.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"KKM\'den çıkış kanunla güvenceye alındı; TL mevduat payı %55\'in üzerine çıktı."}]', 100) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_101', 'modern', 'Refahyol Hükümeti Protokolü ve Güvenoyu Çalkantısı', 'Başbakanlık & TBMM', '54. Hükümetin güvenoyu sürecinde transfer iddiaları ve meclis gerilimi patlak verdi.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Milletvekili transferi iddialarını Meclis Araştırma Komisyonu ve Yargıtay Başsavcılığı\'na sevk ederek şeffaf adli inceleme başlat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Transfer iddiaları yargıya intikal etti; siyasi ahlak tartışmaları mecliste gerilimi tırmandırdı."},{"label":"Koalisyon protokolündeki Başbakanlık dönüşümü (rotasyon) takvimine sadık kal; ortaklar arasında güven tazeleyerek hükümeti kur.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Hükümet güvenoyu aldı; koalisyon ortakları rahatladı ancak siyasi pazarlık iddiaları kamuoyunda eleştirildi."},{"label":"Koalisyon ortaklarının talep ettiği ek bakanlık ve örtülü ödenek bütçelerini Hazine dengelerini korumak adına sınırla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bütçe disiplini sağlandı; gereksiz bürokratik harcamalar önlendi fakat ortaklar arasında huzursuzluk çıktı."},{"label":"Genelkurmay ve Milli Güvenlik Kurulu\'nun hükümet protokolüne dönük hassasiyetlerini doğrudan Başbakanlık üzerinden müzakere et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Askeri kanadın çekinceleri kayıt altına alındı; devlet içi dengeler muhafaza edildi."},{"label":"Siyasi Partiler Kanunu\'nda ve Meclis İçtüzüğü\'nde parti transferlerini zorlaştıran \'Siyasi Ahlak ve Disiplin Reformu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Meclis iradesini bağlayan reform yasalaştı; transfer borsasının önü kurumsal olarak kesildi."}]', 101) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_102', 'modern', 'Aydınlık İçin Bir Dakika Karanlık Eylemleri', 'Başbakanlık & TBMM', 'Susurluk sonrası her akşam 21:00\'de evlerde ışıkların kapatılmasıyla temiz toplum talep edildi.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Susurluk kazası sonrası hazırlanan Kutlu Savaş ve MİT raporlarını sansürsüz biçimde Meclis\'e ve kamuoyuna açıkla.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Raporlar şeffaflıkla paylaşıldı; temiz toplum talebi halk nezdinde devlete olan inancı tazeledi."},{"label":"Eylemleri organize eden sivil inisiyatifler ve barolarla görüşerek taleplerini dinle; gerilimi sokağa taşmadan uzlaşıyla yönet.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sivil toplum temsilcileri muhatap alındı; kitleler teskin edildi fakat radikal kesimler somut tutuklama istedi."},{"label":"Mafya-siyaset ilişkilerinde adı geçen paravan şirketlerin banka hesaplarına Maliye ve MASAK eliyle derhal bloke koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Karanlık ilişkiler ağının mali kaynaklarına el konuldu; Hazineye önemli gelir aktarıldı."},{"label":"Işık kapatma eylemlerinin kamu düzenini bozmasına izin verme; sokak gösterilerine karşı kolluk devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Kamu düzeni sıkı şekilde korundu; gösterilerin kitlesel itaatsizliğe dönüşmesi engellendi ancak tepkiler arttı."},{"label":"Devlet Denetleme Kurulu ve Meclis Araştırma Komisyonu raporlarına dayanan \'Organize Suçlar ve Çeteleşmeyle Mücadele Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yasal çerçeve tahkim edildi; devlet görevlilerinin suç örgütleriyle irtibatı en ağır yaptırımlara bağlandı."}]', 102) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_103', 'modern', '28 Şubat 1997 MGK Bildirisi ve 18 Maddelik Talimat Listesi', 'Başbakanlık & TBMM', '9 saat süren tarihi MGK toplantısında askeri kanat, hükümete 18 maddelik tedbir paketini sundu.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Anayasal parlamenter meşruiyete sarıl; 18 maddelik MGK bildirisini TBMM Genel Kurulu\'na getirip güvenoyuna sun.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Hükümet meclis zemininde direndi; sivil siyasetin meşruiyeti savunuldu fakat askeri kanatla gerilim tırmandı."},{"label":"MGK Genel Sekreterliği ile uzlaşma masası kur; 8 yıllık kesintisiz eğitim gibi kritik maddeleri zamana yayarak tansiyonu düşür.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Tansiyon geçici olarak düşürüldü; hükümet erken seçime kadar zaman kazandı ancak tabanda kırılma yaşandı."},{"label":"Siyasi krizin tetiklediği sermaye kaçışını ve repo faizlerindeki tırmanışı önlemek için kamu bankalarına acil likidite sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Finansal panik durduruldu; döviz rezervleri korundu ancak faiz yükü bütçeyi zorladı."},{"label":"Batı Çalışma Grubu\'nun (BÇG) fişlemelerine karşı Emniyet İstihbarat Dairesi marifetiyle gizli karşı-istihbarat tedbiri al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Emniyet kanadı harekete geçirildi; fişleme kasetleri ele geçirilerek bürokratik baskı hafifletildi."},{"label":"Siyasi Partiler Kanunu ve TCK\'da kapsamlı demokratikleşme reformu hazırlayarak sivil-asker ilişkilerini AB normlarına yaklaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Demokratik standartları yükselten taslak sunuldu; uluslararası destek sağlandı fakat iç siyasetin ateşi sönmedi."}]', 103) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_104', 'modern', 'Batı Çalışma Grubu (BÇG) Fişleme Belgeleri', 'Başbakanlık & TBMM', 'Deniz Kuvvetleri bünyesindeki BÇG\'nin kamu görevlilerini fişlediği belgelerin sızması ortalığı karıştırdı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Askeri savcılık ve DGM\'ye resmi başvuru yaparak yetki aşımıyla yapılan fişlemelerin sorumluları hakkında soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Fişleme iddiaları adliyeye taşındı; yargı yolu işletildi ancak askeri hiyerarşiyle derin çatışma doğdu."},{"label":"Bülent Orakoğlu ve İçişleri bürokrasisi ile komutanlar arasında Başbakanlıkta gizli arabuluculuk yürüt.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Kriz kapalı kapılar ardında yumuşatıldı; açık darbe ihtimali ötelendi fakat belgeler sızmaya devam etti."},{"label":"Fişleme belgelerinde adı geçen bürokrat ve şirketlerin kamu ihalelerinden men edilmesini önleyerek ekonomik istikrarı koru.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasada sermayenin yeşil-beyaz diye bölünmesi frenlendi; Anadolu sermayesinin vergi üretimi korundu."},{"label":"Deniz Kuvvetleri bünyesindeki BÇG birimine köstebek yerleştiren emniyet görevlilerini korumaya al; istihbarat arşivini güvenliğe çek.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Emniyet istihbarat arşivi emniyete alındı; sivil irade karşı bilgi gücünü korudu."},{"label":"Devlet Memurları Kanunu\'nda değişiklik yaparak çalışanların inanç, mezhep ve siyasi görüş nedeniyle fişlenmesini ağır cezalara bağla.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kamu personelinin anayasal hakları güvenceye alındı; fişleme bürokrasisine yasal barikat kuruldu."}]', 104) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_105', 'modern', 'Sincan\'da Kudüs Gecesi ve Tankların Yürütülmesi', 'Başbakanlık & TBMM', 'Sincan Belediyesi\'nin etkinliği sonrası zırhlı birlik tanklarının caddelerden geçmesi tansiyonu fırlattı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Kudüs Gecesi\'nde anayasal düzene aykırı pankart ve konuşmalar yapan belediye başkanı hakkında derhal adli soruşturma açtır.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuk devleti kuralları işletildi; provoke edici söylemlere karşı savcılık fezlekesi hazırlandı."},{"label":"Sincan Kaymakamı ve sivil toplum temsilcileriyle görüşerek ilçe halkını teskin et; sokak çatışmasını önleyecek itidal çağrısı yap.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Halk sağduyuyla hareket etti; tankların geçişi provokasyona dönüşmeden ilçe sükûnete kavuştu."},{"label":"Tankların asfalt ve yol altyapısında yarattığı maddi hasarı tespit ettirerek Milli Savunma bütçesinden tazmin edilmesini sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Belediye bütçesindeki tahribat Hazinece karşılandı; kamu zararı tanzim edildi."},{"label":"Zırhlı Birlikler Tümen Komutanlığı\'na resmi yazı yazarak güzergah dışına çıkan askeri araçların kışlalara çekilmesini emret.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Hükümet otoritesi kağıt üzerinde gösterildi; kışladan plansız çıkışlar durduruldu."},{"label":"Belediyelerin kültürel ve sosyal etkinliklerinin milli mevzuata uygunluğunu denetleyen \'Belediye Etkinlikleri Çerçeve Yönetmeliği\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yerel yönetimlerin dış politika ve ideolojik istismara alet olmasını engelleyen kurumsal standart getirildi."}]', 105) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_106', 'modern', 'Fazilet Partisi\'nin Kurulması ve Kapatılması Davası', 'Başbakanlık & TBMM', 'Refah Partisi\'nin ardından kurulan Fazilet Partisi hakkında odak olma gerekçesiyle kapatma davası açıldı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Anayasa Mahkemesi\'ndeki kapatma davasında savunmayı evrensel örgütlenme özgürlüğü ve AİHM içtihatlarına dayandır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki savunma titizlikle sunuldu; odak olma iddiasının delilsizliği uluslararası hukuka dayandırıldı."},{"label":"Meclisteki diğer parti liderleriyle temas kurarak parti kapatmayı zorlaştıran bir anayasa değişikliği için uzlaşma ara.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Partiler arası diyalog kapısı aralandı; mecliste kapatmaya karşı geniş bir mutabakat zemini yoklandı."},{"label":"Partinin kapatılması halinde hazine yardımının kesilmesini hesaba katarak teşkilat bütçesini tedbiren koru.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali tedbirler alındı; teşkilatların borç yükü ve hazine yardımı riskleri minimize edildi."},{"label":"Kapatma davası sürecinde sokak gösterilerini ve provokatif yürüyüşleri emniyet tedbirleriyle sıkı kontrol altında tut.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Kamu düzeni korundu; kitlesel taşkınlıklar önlendi ve gerilimin sokağa taşması engellendi."},{"label":"Venedik Komisyonu ilkeleri doğrultusunda \'Siyasi Partiler Kanunu ve Kapatma Usulleri Reformu\'nu meclise sun.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Parti kapatmanın Meclis iznine bağlanması taslağı hazırlandı; kurumsal demokrasi çıtası yükseltildi."}]', 106) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_107', 'modern', '18 Nisan 1999 Seçimleri ve 57. Hükümet Protokolü', 'Başbakanlık & TBMM', 'DSP, MHP ve ANAP koalisyonu kurulurken bakanlık paylaşımları ve Meclis Başkanlığı pazarlığı kızıştı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Seçim sonuçlarını ve YSK tutanaklarını titizlikle denetle; tüm itirazları hukukun üstünlüğü çerçevesinde sonuçlandır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"YSK kararları şeffaflıkla açıklandı; sandık iradesine tam güven sağlandı."},{"label":"DSP, MHP ve ANAP genel başkanlarıyla üçlü koalisyon protokolü imzala; bakanlıkları liyakat ve dengelerle dağıt.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"57. Hükümet kuruldu; siyasi belirsizlik giderildi fakat koalisyon içi sürtüşmeler hissedildi."},{"label":"Üç partinin seçim vaatleri arasında yer alan popülist harcamaları bütçe disiplini adına sınırlı tut.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Hazine kasası korundu; bütçe açığı kontrol altına alındı fakat seçmen tabanında homurdanmalar başladı."},{"label":"Hükümet güvenoyu alır almaz terörle mücadele ve sınır güvenliği için Milli Güvenlik Kurulu ile acil zirve topla.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Güvenlik bürokrasisi teyakkuza geçirildi; devletin kararlılığı dosta düşmana hissettirildi."},{"label":"Koalisyon protokolünü \'Ekonomik ve Sosyal Konsey ile Kamu Reformu Kanunu\' ile yasal çerçeveye bağla.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Sosyal tarafların hükümete katılımı kurumsallaştı; reform takvimi yasal güvenceye bağlandı."}]', 107) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_108', 'modern', 'Merve Kavakçı\'nın TBMM Yemin Töreni Gerilimi', 'Başbakanlık & TBMM', 'Başörtüsüyle genel kurula gelen milletvekiline yönelik protestolar meclis çalışmalarını kilitledi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Milletvekilinin seçilme yeterliliği ve çifte vatandaşlık durumunu Danıştay ve YSK nezdinde hukuki karara bağlat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki süreç işletildi; meclis içi kavga yerine resmi mevzuat ve vatandaşlık kaydı incelendi."},{"label":"TBMM Başkanlık Divanı ve parti grup başkanvekilleriyle kapalı meşveret toplayıp yemin törenini uzlaşıyla ertele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Genel kuruldaki fiziki gerilim yatıştırıldı; meclis krizinin erken patlaması önlendi."},{"label":"Meclis çalışmalarının tıkanması sebebiyle Hazine\'nin gecikme faizi ve ekonomik kayba uğramasını önleyecek tedbir al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasalar krizden asgari düzeyde etkilendi; bütçe görüşmeleri gecikmeden sürdürüldü."},{"label":"Genel kurul salonunda nizamı bozan ve fiziki müdahalede bulunanlara karşı TBMM İdare Amirliği\'ni göreve çağır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Meclis iç güvenliği sağlandı; kürsü işgali önlendi fakat siyasi cepheleşme derinleşti."},{"label":"TBMM İçtüzüğü\'nde milletvekili kıyafet serbestisini ve yemin usullerini netleştiren kalıcı bir düzenleme yap.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kıyafet yönetmeliğindeki muğlaklıklar giderildi; gelecekteki yemin krizlerinin önüne geçildi."}]', 108) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_109', 'modern', 'Çankaya Köşkü\'nde Anayasa Kitapçığı Fırlatılması (Şubat 2001)', 'Başbakanlık & TBMM', 'MGK toplantısında Cumhurbaşkanı ile Başbakan arasındaki kavga sonrası gecelik faizler %7500\'e fırladı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Devlet Denetleme Kurulu\'nun kamu bankaları teftiş raporlarını gecikmeksizin DGM Başsavcılığı\'na ilet ve yargıyı işlet.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; kamu bankalarındaki yolsuzlukların üzerine gidildi."},{"label":"Cumhurbaşkanı Sezer ile Başbakan Ecevit arasında Çankaya\'da acil bir barışma ve ortak basın toplantısı organize et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Devletin zirvesindeki kavga yumuşatılmaya çalışıldı; ancak piyasa şoku çoktan tetiklenmişti."},{"label":"Gecelik repo faizlerinin %7500\'e fırlamasını durdurmak için Merkez Bankası\'na döviz satış yetkisi ver ve dalgalı kura geç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sabit kur rejiminden çıkıldı; Hazine döviz rezervleri kurtarıldı fakat devalüasyon halkı vurdu."},{"label":"Bankalar ve döviz büroları önündeki panik havasına karşı mali şube ve güvenlik güçlerini teyakkuza geçir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Finans merkezlerinde asayiş sağlandı; banka yağması veya fiziki panik önlendi."},{"label":"Dünya Bankası ve IMF ile müzakere ederek \'Güçlü Ekonomiye Geçiş Programı ve Bağımsız Kurullar Reformu\'nu ilan et.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kemal Derviş reformları devreye alındı; bankacılık sistemi kurumsal zırha kavuşturuldu."}]', 109) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_110', 'modern', 'Abdullah Öcalan\'ın Kenya\'da Yakalanması ve Getirilişi', 'Başbakanlık & TBMM', 'Nairobi\'deki operasyonla terör elebaşı Türkiye\'ye getirildi; ülke genelinde tarihi bir coşku yaşandı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"İmralı DGM duruşmalarını şehit aileleri, yerli ve yabancı basın önünde hukukun evrensel ilkeleriyle yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ciddiyeti tüm dünyaya gösterildi; yargılamanın meşruiyetine gölge düşürülmedi."},{"label":"AİHM\'in ihtiyati tedbir çağrısını ve Avrupa Konseyi taahhütlerini meclisteki tüm siyasi partilerle müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Dış politika krizine dönüşmesi engellendi; siyasi uzlaşıyla infaz ertelendi."},{"label":"İmralı Adası\'nın yüksek güvenlikli cezaevi dönüşümü ve yargılama lojistiği için Adalet bütçesine ek ödenek aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Lojistik altyapı eksiksiz kuruldu; adadaki duruşma güvenliği Hazine kaynaklarıyla sağlandı."},{"label":"İmralı ve çevresinde denizaltı, savaş gemisi ve hava sahası teyakkuzu kurarak olası tüm sızma girişimlerini engelle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Ada çevresinde aşılmaz bir güvenlik kalkanı tesis edildi; askeri otorite tam olarak kuruldu."},{"label":"AB uyum süreci kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet İnfaz Kanunu\'nu kabul et.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İdam cezası kaldırıldı; ağırlaştırılmış müebbet hapis sistemi Türk ceza infaz hukukuna girdi."}]', 110) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_111', 'modern', 'İmralı Duruşmaları ve Ağırlaştırılmış Müebbet Kararı', 'Başbakanlık & TBMM', 'İmralı Adası\'nda kurulan özel mahkemede terör elebaşı yargılanarak idam cezasına çarptırıldı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"İmralı DGM duruşmalarını şehit aileleri, yerli ve yabancı basın önünde hukukun evrensel ilkeleriyle yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk devleti ciddiyeti tüm dünyaya gösterildi; yargılamanın meşruiyetine gölge düşürülmedi."},{"label":"AİHM\'in ihtiyati tedbir çağrısını ve Avrupa Konseyi taahhütlerini meclisteki tüm siyasi partilerle müzakere et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Dış politika krizine dönüşmesi engellendi; siyasi uzlaşıyla infaz ertelendi."},{"label":"İmralı Adası\'nın yüksek güvenlikli cezaevi dönüşümü ve yargılama lojistiği için Adalet bütçesine ek ödenek aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Lojistik altyapı eksiksiz kuruldu; adadaki duruşma güvenliği Hazine kaynaklarıyla sağlandı."},{"label":"İmralı ve çevresinde denizaltı, savaş gemisi ve hava sahası teyakkuzu kurarak olası tüm sızma girişimlerini engelle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Ada çevresinde aşılmaz bir güvenlik kalkanı tesis edildi; askeri otorite tam olarak kuruldu."},{"label":"AB uyum süreci kapsamında \'Ölüm Cezasının Kaldırılması ve Ağırlaştırılmış Müebbet İnfaz Kanunu\'nu kabul et.","preview":"Adalet +5, Halk +3, Güvenlik +