INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_112', 'modern', '1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası)', 'Başbakanlık & TBMM', 'Örgütten kopmaları hızlandırmak amacıyla hazırlanan Pişmanlık Yasası mecliste hararetli tartışmalara yol açtı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) hadisesinde mevzuatı ve yargı denetimini tavizsiz işleterek hukukun üstünlüğünü ve adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) kapsamında hukukun üstünlüğü gözetildi; idari işlemler yargı denetimine tabi tutuldu."},{"label":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) sürecinde ilgili taraflar, sivil toplum ve siyasi aktörlerle ortak masa kurarak toplumsal mutabakat sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) meselesinde meşveret ve uzlaşı sağlandı; tarafların gerilimi düşürüldü."},{"label":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koruma altına al.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) karşısında kolluk ve idari bürokrasiyi kararlılıkla görevlendirerek kamu düzenini ve devlet otoritesini göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) karşısında kamu nizamı korundu; devletin otoritesi ve güvenliği hissettirildi."},{"label":"TBMM\'de 1999 Topluma Kazandırma Kanunu (Pişmanlık Yasası) konusunu yapısal olarak çözecek kapsamlı bir reform ve ihtisas kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yürürlüğe giren reform kanunu ile kurumsal güvence sağlandı; benzer krizlerin tekerrürü önlendi."}]', 112) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_113', 'modern', 'Şartlı Salıverme Yasası (Rahşan Affı) ve Cezaevi Tahliyeleri', 'Başbakanlık & TBMM', 'Cezaevlerindeki doluluğu azaltmak amacıyla çıkarılan af sonrası binlerce adli mahkum tahliye oldu.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Yasa kapsamındaki devlete karşı suçlar ile şahsa karşı suçlar ayrımını anayasa ve hakkaniyet ilkelerine göre uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki sınırlar titizlikle korundu; affın kapsamı mahkemelerde hukuka uygun yorumlandı."},{"label":"Cezaevlerindeki doluluğu ve açlık grevlerini bitirmek için mahkum aileleri ve barolarla tahliye takvimini koordine et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Cezaevlerindeki isyan havası yatıştı; binlerce aile sevindi fakat sokakta güvenlik endişesi başladı."},{"label":"Cezaevlerinin iaşe ve bakım giderlerindeki yükün hafiflemesiyle oluşan tasarrufu adliye yatırımlarına aktar.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Cezaevi bütçesinde rahatlama sağlandı; tasarruf adli altyapıya kanalize edildi."},{"label":"Tahliye olan mükerrir suçluların takibi için emniyet asayiş şubelerine özel gözetim ve devriye görevi ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tahliyelerin ardından sokakta sıkı asayiş kontrolü kuruldu; suç oranlarının patlaması önlendi."},{"label":"Ceza İnfaz Kanunu\'nu baştan yazarak şartlı salıverme oranlarını ve denetimli serbestlik müessesesini kurumsallaştır.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Modern infaz hukuku inşa edildi; affa gerek bırakmayan kademeli infaz nizamı kuruldu."}]', 113) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_114', 'modern', 'Hayata Dönüş Operasyonu ve F Tipi Cezaevleri', 'Başbakanlık & TBMM', '20 cezaevindeki ölüm oruçlarını kırmak ve oda sistemine geçmek amacıyla düzenlenen operasyonda çatışmalar çıktı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Operasyon sırasında meydana gelen ölümler ve aşırı güç kullanımı iddiaları hakkında adli ve idari soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Cumhuriyet savcıları cezaevlerinde delil tespiti yaptı; aşırı güç iddiaları soruşturuldu."},{"label":"Yaşar Kemal, Zülfü Livaneli ve aydınlar heyetinin ölüm orucundaki mahkumlarla yürüttüğü arabuluculuk müzakerelerini uzat.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Müzakere masası son ana kadar açık tutuldu; aydınların çabası kamuoyunda saygı gördü."},{"label":"F Tipi cezaevlerinin modern güvenlik teknolojileri ve oda sistemleri için Hazine\'den acil inşaat ödeneği çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Koğuş sisteminden oda sistemine geçişin finansmanı tamamlandı; cezaevi mimarisi yenilendi."},{"label":"Jandarma komando birlikleri marifetiyle 20 cezaevine eşzamanlı müdahale ederek örgütlerin cezaevi hakimiyetini kır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Cezaevlerindeki örgüt hakimiyeti zor kullanılarak kırıldı; devlet otoritesi tesis edildi ancak can kayıpları oldu."},{"label":"Ceza ve Tevkifevleri Genel Müdürlüğü teşkilatını yenileyen \'İnfaz Kurumları Güvenliği ve İyileştirme Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İnfaz koruma memurlarının yetkileri ve tutuklu hakları yasal çerçevede yeniden tanzim edildi."}]', 114) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_115', 'modern', 'Manisa Davası ve Polis İşkencesi İddiaları', 'Başbakanlık & TBMM', 'Manisa\'da gözaltına alınan 16 liseli gence işkence yapıldığı iddiası Türkiye gündemine oturdu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Manisa Davası ve Polis İşkencesi İddiaları hadisesinde mevzuatı ve yargı denetimini tavizsiz işleterek hukukun üstünlüğünü ve adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Manisa Davası ve Polis İşkencesi İddiaları kapsamında hukukun üstünlüğü gözetildi; idari işlemler yargı denetimine tabi tutuldu."},{"label":"Manisa Davası ve Polis İşkencesi İddiaları sürecinde ilgili taraflar, sivil toplum ve siyasi aktörlerle ortak masa kurarak toplumsal mutabakat sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Manisa Davası ve Polis İşkencesi İddiaları meselesinde meşveret ve uzlaşı sağlandı; tarafların gerilimi düşürüldü."},{"label":"Manisa Davası ve Polis İşkencesi İddiaları ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koruma altına al.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Manisa Davası ve Polis İşkencesi İddiaları hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Manisa Davası ve Polis İşkencesi İddiaları karşısında kolluk ve idari bürokrasiyi kararlılıkla görevlendirerek kamu düzenini ve devlet otoritesini göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},