INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_118', 'modern', 'Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı', 'Başbakanlık & TBMM', 'Siyasi yasağı anayasa değişikliğiyle kalkan AK Parti lideri Siirt yenileme seçimiyle meclise girip hükümeti kurdu.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı hadisesinde mevzuatı ve yargı denetimini tavizsiz işleterek hukukun üstünlüğünü ve adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı kapsamında hukukun üstünlüğü gözetildi; idari işlemler yargı denetimine tabi tutuldu."},{"label":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı sürecinde ilgili taraflar, sivil toplum ve siyasi aktörlerle ortak masa kurarak toplumsal mutabakat sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı meselesinde meşveret ve uzlaşı sağlandı; tarafların gerilimi düşürüldü."},{"label":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koruma altına al.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı karşısında kolluk ve idari bürokrasiyi kararlılıkla görevlendirerek kamu düzenini ve devlet otoritesini göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı karşısında kamu nizamı korundu; devletin otoritesi ve güvenliği hissettirildi."},{"label":"TBMM\'de Recep Tayyip Erdoğan\'ın Siirt Seçimi ile Başbakanlığı konusunu yapısal olarak çözecek kapsamlı bir reform ve ihtisas kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yürürlüğe giren reform kanunu ile kurumsal güvence sağlandı; benzer krizlerin tekerrürü önlendi."}]', 118) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_119', 'modern', '1 Mart 2003 Tezkeresi ve TBMM Tarihi Ret Kararı', 'Başbakanlık & TBMM', 'ABD birliklerinin Türkiye üzerinden Irak\'a girmesine izin veren tezkere TBMM\'de salt çoğunluğu sağlayamadı.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"TBMM Genel Kurulu\'nun verdiği ret kararına kayıtsız şartsız saygı göster; milletvekillerine baskı yapılmasını engelle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Milli iradenin üstünlüğü korundu; Türkiye\'nin savaşa girmesini engelleyen karar tüm dünyada yankı buldu."},{"label":"Washington ve bölge ülkeleriyle diplomatik temas kurarak tezkerenin reddi sonrası doğan tansiyonu yatıştır.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik diyalog kanalları işletildi; ABD ile ilişkilerin kopma noktasına gelmesi önlendi."},{"label":"Tezkere karşılığı vadedilen 26 milyar dolarlık ABD yardım paketinden vazgeçerek milli bütçe tasarrufuna odaklan.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Yabancı yardıma bağımlı olunmadığı kanıtlandı; Hazine kendi özkaynaklarıyla mali disiplini sürdürdü."},{"label":"Kuzey Irak sınır boylarında doğabilecek otorite boşluğuna karşı 2. Ordu birliklerini sınır hattına yığ.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sınır güvenliği tahkim edildi; terör koridoru açılmasına karşı caydırıcı askeri yığınak yapıldı."},{"label":"Anayasa\'nın 92. maddesi kapsamında \'Yurtdışına Asker Gönderme ve Yabancı Birlikleri Kabul Kanunu\'nu netleştir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Askeri tezkerelerin meclis oylama usulleri kanunen berraklaştırıldı; geleceğe yasal emsal bırakıldı."}]', 119) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_120', 'modern', 'Süleymaniye\'de Çuval Olayı (4 Temmuz 2003)', 'Başbakanlık & TBMM', 'Irak Süleymaniye\'de Türk Özel Kuvvetleri karargahını basan ABD askerleri subaylarımızın başına çuval geçirdi.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"ABD hükümetine derhal en sert diplomatik notayı ver ve uluslararası hukuk nezdinde subaylarımızın dokunulmazlığını savun.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki ve diplomatik nota verildi; müttefiklik hukukunun çiğnendiği kayıtlara geçirildi."},{"label":"Genelkurmay Başkanı ve Başbakanlık nezdinde ortak kriz masası topla; personelin derhal ve koşulsuz serbest kalmasını sağla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"60 saatlik yoğun müzakereler sonucunda Özel Kuvvetler timimiz salıverildi; çatışma çıkmadan kriz aşıldı."},{"label":"İncirlik Üssü ve Türk hava sahasının ABD askeri nakliyelerine kullanım ücret ve kısıtlamalarını Hazine lehine revize et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Lojistik izinler üzerinden Hazineye gelir sağlandı; askeri geçişler kontrol altına alındı."},{"label":"Kuzey Irak\'taki tüm Özel Kuvvetler ve MİT unsurlarını teyakkuza geçir; yeni bir tacize anında silahla mukabele emri ver.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Angajman kuralları sertleştirildi; Türk askerinin sahadaki caydırıcılığı yeniden tahkim edildi."},{"label":"Yurtdışı askeri irtibat timlerinin statüsünü ve müttefik kuvvetlerle ilişkilerini düzenleyen \'Özel Görev Gücü Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yurtdışı operasyon timlerine kalıcı hukuki zırh ve harekat protokolü kazandırıldı."}]', 120) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_121', 'modern', 'Kıbrıs Annan Planı Referandumu (2004)', 'Başbakanlık & TBMM', 'BM\'nin Kıbrıs planı Türk tarafından %65 \'Evet\', Rum tarafından %75 \'Hayır\' oyu aldı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"BM ve uluslararası toplum nezdinde Rum tarafının \'Hayır\'ına rağmen Türk tarafının barış iradesini tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Kıbrıs Türkü\'nün haklılığı uluslararası arenada tescillendi; izolasyonların kalkması talep edildi."},{"label":"Rauf Denktaş ve KKTC meclisiyle istişare yürüt; anavatan ile yavruvatan arasındaki güven bağlarını tazele.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"KKTC içi siyasi dengeler gözetildi; halkın referandum kararı ortak kabul gördü."},{"label":"KKTC\'ye uygulanan ambargoları kırmak için Hazine\'den doğrudan ekonomik yardım ve altyapı fonu aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kıbrıs Türk ekonomisi sübvanse edildi; turizm ve eğitim yatırımları canlandırıldı."},{"label":"Kıbrıs Türk Barış Kuvvetleri\'nin adadaki askeri varlığını ve garantörlük haklarımızı tavizsiz muhafaza et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Garantörlük hakları korundu; Türk askerinin adadaki caydırıcı varlığı sürdürüldü."},{"label":"Türkiye ile KKTC arasında \'Stratejik Ortaklık ve Serbest Ticaret Bölgesi Çerçeve Kanunu\'nu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"İki devlet arasındaki iktisadi ve hukuki entegrasyon kanunla mühürlendi."}]', 121) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_122', 'modern', 'AB Uyum Yasaları ve DGM\'lerin Kaldırılması (2004)', 'Başbakanlık & TBMM', 'AB katılım müzakereleri çerçevesinde 8 uyum paketiyle Devlet Güvenlik Mahkemeleri tarihe karıştı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Devlet Güvenlik Mahkemeleri\'ni anayasadan tamamen çıkar; askeri üyeli yargılamalara son verip adil yargılanmayı sağla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"DGM\'ler tarihe karıştı; sivil yargının bağımsızlığı ve tabi hakim ilkesi güvenceye kavuştu."},{"label":"Barolar Birliği, yüksek yargı organları ve akademisyenlerle ortak hukuk şurası toplayarak uyum paketini tartış.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yargı camiasının mutabakatı sağlandı; kanunların uygulanmasında direnç kırıldı."},{"label":"AB hibe fonlarını adalet saraylarının inşasına ve adli tıp bilişim altyapısının kurulmasına tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Adliye binalarının fiziki modernizasyonu Hazineye yük olmadan AB fonlarıyla finanse edildi."},{"label":"Terör suçlarında uzmanlaşmış Ağır Ceza Mahkemeleri kurarak güvenlik bürokrasisinin yargı zafiyetine düşmesini önle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Terörle mücadele ihtisas mahkemelerine devredildi; kamu düzeni boşluğa düşürülmedi."},{"label":"8 temel uyum paketini birleştiren \'Temel Haklar ve Adil Yargılanma Çerçeve Kanunu\'nu meclisten geçir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Hukuk devrimi gerçekleştirildi; Türkiye\'nin Kopenhag kriterlerine uyumu tescillendi."}]', 122) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
