INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_126', 'modern', 'Yeni Türk Ceza Kanunu (TCK 5237) Reformu (2004-2005)', 'Başbakanlık & TBMM', '79 yıllık eski ceza kanunu yerine kişi hak ve hürriyetlerini merkeze alan çağdaş ceza kanunu kabul edildi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"İşkence, kadına karşı şiddet ve çocuk istismarına sıfır tolerans tanıyan en ağır cezai maddeleri tavizsiz yasalaştır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Evrensel ceza hukuku ilkeleri kanunlaştı; işkencede zamanaşımı kaldırılarak insan onuru korundu."},{"label":"Kadın dernekleri ve sivil toplumla istişare ederek töre ve namus cinayetlerindeki haksız tahrik indirimlerini kaldır.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal vicdanın sesi dinlendi; töre cinayetlerinde caydırıcılık en üst seviyeye çıkarıldı."},{"label":"Adli para cezalarını güncel ekonomik verilere bağla; suçtan elde edilen gelirlere Hazine adına el koymayı kolaylaştır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Müsadere rejimi sıkılaştırıldı; suç gelirleri devlete gelir olarak kaydedildi."},{"label":"Devletin güvenliğine ve anayasal düzene karşı suçlar faslını milli menfaatleri koruyacak şekilde güçlendir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Devlet güvenliği hukuki koruma altına alındı; terör ve anarşiyle mücadelede ceza zırhı sağlandı."},{"label":"5237 Sayılı Türk Ceza Kanunu\'nu tüm maddeleriyle yürürlüğe koyarak 1926 tarihli eski ceza kanununu lağvet.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Çağdaş ceza hukuku çağı başladı; kişi güvenliği ve hürriyeti kanunun merkezine oturtuldu."}]', 126) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
