INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_134', 'modern', 'Bank Ekspres ve Korkmaz Yiğit Soruşturması', 'BDDK & TMSF', 'Bankanın içinin haksız kredi aktarımlarıyla boşaltıldığı gerekçesiyle DGM\'de tutuklamalar yapıldı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Bank Ekspres ve Korkmaz Yiğit Soruşturması olayında mali usulsüzlükleri bağımsız murakıplarca belgele ve sorumluları Ağır Ceza Mahkemesi\'ne sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Bank Ekspres ve Korkmaz Yiğit Soruşturması hakkında yargı süreci işletildi; zimmet ve usulsüzlük iddiaları mahkemede hesap verdi."},{"label":"Bank Ekspres ve Korkmaz Yiğit Soruşturması mağdurları ve sektör temsilcileriyle uzlaşma masası kurarak alacakların tasfiyesini adil bir takvime bağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Bank Ekspres ve Korkmaz Yiğit Soruşturması kapsamında taraflar uzlaştırıldı; piyasa çalkantısı yatıştırılarak sulh sağlandı."},{"label":"Bank Ekspres ve Korkmaz Yiğit Soruşturması ile buharlaştırılan varlıkları TMSF marifetiyle haczedip kamu ihalesiyle satarak Hazine\'ye gelir kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bank Ekspres ve Korkmaz Yiğit Soruşturması varlıkları paraya çevrildi; Hazine kasasına gelir sağlanarak kamu zararı tazmin edildi."},{"label":"Bank Ekspres ve Korkmaz Yiğit Soruşturması sorumlularının mal varlıklarını kaçırmasını önlemek için kolluk ve MASAK marifetiyle sınır ötesi tedbir koy.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Bank Ekspres ve Korkmaz Yiğit Soruşturması şüphelilerine karşı sert mali kolluk tedbiri uygulandı; mal kaçırma teşebbüsü engellendi."},{"label":"Mali piyasaları regüle eden \'Finansal İstikrar ve Denetim Kanunu\' çıkararak Bank Ekspres ve Korkmaz Yiğit Soruşturması gibi krizlerin tekrarını önle.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile sistemik riskler önlendi; piyasaya kurumsal güven geldi."}]', 134) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
