INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_137', 'modern', 'Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları', 'BDDK & TMSF', 'Sermaye yeterliliği eksiye düşen Pamukbank\'a el konulması Turkcell ve Yapı Kredi hisselerinde krize yol açtı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları olayında mali usulsüzlükleri bağımsız murakıplarca belgele ve sorumluları Ağır Ceza Mahkemesi\'ne sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları hakkında yargı süreci işletildi; zimmet ve usulsüzlük iddiaları mahkemede hesap verdi."},{"label":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları mağdurları ve sektör temsilcileriyle uzlaşma masası kurarak alacakların tasfiyesini adil bir takvime bağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları kapsamında taraflar uzlaştırıldı; piyasa çalkantısı yatıştırılarak sulh sağlandı."},{"label":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları ile buharlaştırılan varlıkları TMSF marifetiyle haczedip kamu ihalesiyle satarak Hazine\'ye gelir kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları varlıkları paraya çevrildi; Hazine kasasına gelir sağlanarak kamu zararı tazmin edildi."},{"label":"Pamukbank\'ın Fona Devri ve Çukurova Grubu Borçları sorumlularının mal varlıklarını kaçırmasını önlemek için kolluk ve MASAK marifetiyle sınır ötesi tedbir koy.","preview":"Adalet +5, Halk +5, Güvenli