INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_138', 'modern', 'Bankacılık Düzenleme ve Denetleme Kurumu\'nun (BDDK) Kurulması', 'BDDK & TMSF', 'Bankaların siyasetçilerin emrinden çıkarılıp bağımsız bir kurulla denetlenmesi amacıyla BDDK kuruldu.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Bankaların siyasetçilerin arka bahçesi olmasını bitirmek için BDDK Murakıplar Kurulu\'na tam bağımsız teftiş ve yetki ver.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Bankacılıkta liyakat ve kural hakim kılındı; usulsüz kredi dağıtan patronlara geçit verilmedi."},{"label":"TOBB, TÜSİAD ve işçi sendikalarıyla \'Ekonomik İstikrar Protokolü\' imzalayarak reformlara toplumsal meşruiyet sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal taraflar ikna edildi; \'15 Günde 15 Kanun\' reformları sokak çatışması olmadan yürürlüğe girdi."},{"label":"Kamu bankalarını görev zararlarından arındırmak için Hazine kaynaklarından özel tertip tahvil ihraç et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kamu bankalarının bilançoları temizlendi; Ziraat ve Halkbank batmaktan kurtarıldı."},{"label":"Batık bankaların içini boşaltmaya yeltenen yöneticilere karşı Mali Şube polislerini görevlendirerek kaçak para transferlerini durdur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kolluk gücüyle para kaçırma girişimleri engellendi; mali otorite sağlandı."},{"label":"TBMM\'den \'Bankalar Kanunu ve Bağımsız İdari Otoriteler Reform Paketi\'ni kabul ederek finansal sisteme zırh geçir.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Türk finans tarihinin en kapsamlı reformu tamamlandı; Türkiye 2008 küresel krizine dayanıklı hale geldi."}]', 138) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
