INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_145', 'modern', 'Off-Shore Hesapzedelere Devlet Garantisi Tartışması', 'BDDK & TMSF', 'Yurt dışındaki paravan bankalara yüksek faizle para yatıranların devlet güvencesi talep etmesi kriz yarattı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması olayında mali usulsüzlükleri bağımsız murakıplarca belgele ve sorumluları Ağır Ceza Mahkemesi\'ne sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması hakkında yargı süreci işletildi; zimmet ve usulsüzlük iddiaları mahkemede hesap verdi."},{"label":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması mağdurları ve sektör temsilcileriyle uzlaşma masası kurarak alacakların tasfiyesini adil bir takvime bağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması kapsamında taraflar uzlaştırıldı; piyasa çalkantısı yatıştırılarak sulh sağlandı."},{"label":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması ile buharlaştırılan varlıkları TMSF marifetiyle haczedip kamu ihalesiyle satarak Hazine\'ye gelir kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması varlıkları paraya çevrildi; Hazine kasasına gelir sağlanarak kamu zararı tazmin edildi."},{"label":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması sorumlularının mal varlıklarını kaçırmasını önlemek için kolluk ve MASAK marifetiyle sınır ötesi tedbir koy.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Off-Shore Hesapzedelere Devlet Garantisi Tartışması şüphelilerine karşı sert mali kolluk tedbiri uygulandı; mal kaçırma teşebbüsü engellendi."},{"label":"Mali piyasaları regüle eden \'Finansal İstikrar ve Denetim Kanunu\' çıkararak Off-Shore Hesapzedelere Devlet Garantisi Tartışması gibi krizlerin tekrarını önle.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile sistemik riskler önlendi; piyasaya kurumsal güven geldi."}]', 145) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_146', 'modern', 'Beyaz Enerji Operasyonu: TEAŞ ve TEDAŞ İhaleleri', 'BDDK & TMSF', 'Enerji santralleri ve iletim hatları ihalelerinde rüşvet çarkı kurulduğu iddiasıyla DGM operasyonu başlatıldı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"TEAŞ ve BOTAŞ ihalelerindeki rüşvet kasetlerini DGM savcılığına ilet; rüşvet alan bürokrat ve şirket sahiplerini derhal tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yolsuzluk şebekesi çökertildi; enerji ihalelerindeki karanlık ilişkiler kamuoyu önünde yargılandı."},{"label":"Elektrik ve doğalgaz dağıtımındaki aksamayı önlemek için sektör temsilcileriyle görüşüp temiz enerji şirketleriyle sözleşmeleri yenile.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Enerji arz güvenliği korundu; elektrik kesintisi riski uzlaşıyla bertaraf edildi."},{"label":"Hileli sözleşmelerle devlete pahalıya satılan doğalgaz ve elektrik alım garantilerini feshederek Hazineyi milyarlarca dolar zarardan kurtar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine kasası kurtarıldı; \'Al ya da Öde\' sözleşmelerindeki fahiş rant iptal edildi."},{"label":"Jandarma Kaçakçılık ve Organize Suçlar timleriyle şüphelilerin ev ve holding binalarına şafak baskınları düzenle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Operasyonel güç kararlılıkla kullanıldı; deliller karartılmadan kasalara ve belgelere el konuldu."},{"label":"Enerji Piyasası Düzenleme Kurumu (EPDK) yetkilerini tahkim eden \'Elektrik ve Doğalgaz Piyasası Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Enerji sektörü siyasetin keyfi vesayetinden çıkarıldı; şeffaf borsa ve lisanslama kuruldu."}]', 146) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_147', 'modern', 'Mavi Hat Operasyonu: BOTAŞ Doğalgaz Rüşvet İddiaları', 'BDDK & TMSF', 'Doğalgaz boru hatları ve kompresör istasyonu ihalelerinde rüşvet alındığı iddiasıyla bürokratlar tutuklandı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"TEAŞ ve BOTAŞ ihalelerindeki rüşvet kasetlerini DGM savcılığına ilet; rüşvet alan bürokrat ve şirket sahiplerini derhal tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yolsuzluk şebekesi çökertildi; enerji ihalelerindeki karanlık ilişkiler kamuoyu önünde yargılandı."},{"label":"Elektrik ve doğalgaz dağıtımındaki aksamayı önlemek için sektör temsilcileriyle görüşüp temiz enerji şirketleriyle sözleşmeleri yenile.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Enerji arz güvenliği korundu; elektrik kesintisi riski uzlaşıyla bertaraf edildi."},{"label":"Hileli sözleşmelerle devlete pahalıya satılan doğalgaz ve elektrik alım garantilerini feshederek Hazineyi milyarlarca dolar zarardan kurtar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine kasası kurtarıldı; \'Al ya da Öde\' sözleşmelerindeki fahiş rant iptal edildi."},{"label":"Jandarma Kaçakçılık ve Organize Suçlar timleriyle şüphelilerin ev ve holding binalarına şafak baskınları düzenle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Operasyonel güç kararlılıkla kullanıldı; deliller karartılmadan kasalara ve belgelere el konuldu."},{"label":"Enerji Piyasası Düzenleme Kurumu (EPDK) yetkilerini tahkim eden \'Elektrik ve Doğalgaz Piyasası Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Enerji sektörü siyasetin keyfi vesayetinden çıkarıldı; şeffaf borsa ve lisanslama kuruldu."}]', 147) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_148', 'modern', 'Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat', 'BDDK & TMSF', 'İzmir gümrüklerinden kum ve taş yüklü konteynerlerle trilyonluk KDV iadesi alan şebeke çökertildi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat olayında mali usulsüzlükleri bağımsız murakıplarca belgele ve sorumluları Ağır Ceza Mahkemesi\'ne sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat hakkında yargı süreci işletildi; zimmet ve usulsüzlük iddiaları mahkemede hesap verdi."},{"label":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat mağdurları ve sektör temsilcileriyle uzlaşma masası kurarak alacakların tasfiyesini adil bir takvime bağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat kapsamında taraflar uzlaştırıldı; piyasa çalkantısı yatıştırılarak sulh sağlandı."},{"label":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat ile buharlaştırılan varlıkları TMSF marifetiyle haczedip kamu ihalesiyle satarak Hazine\'ye gelir kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat varlıkları paraya çevrildi; Hazine kasasına gelir sağlanarak kamu zararı tazmin edildi."},{"label":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat sorumlularının mal varlıklarını kaçırmasını önlemek için kolluk ve MASAK marifetiyle sınır ötesi tedbir koy.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat şüphelilerine karşı sert mali kolluk tedbiri uygulandı; mal kaçırma teşebbüsü engellendi."},{"label":"Mali piyasaları regüle eden \'Finansal İstikrar ve Denetim Kanunu\' çıkararak Balina Operasyonu: İzmir Gümrüklerinde Hayali İhracat gibi krizlerin tekrarını önle.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile sistemik riskler önlendi; piyasaya kurumsal güven geldi."}]', 148) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
