INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_160', 'modern', 'Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi', 'BDDK & TMSF', '1988\'den beri maaşlardan kesilen zorunlu tasarruf fonu lağvedilerek nemalar çalışanlara iade edildi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi olayında mali usulsüzlükleri bağımsız murakıplarca belgele ve sorumluları Ağır Ceza Mahkemesi\'ne sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi hakkında yargı süreci işletildi; zimmet ve usulsüzlük iddiaları mahkemede hesap verdi."},{"label":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi mağdurları ve sektör temsilcileriyle uzlaşma masası kurarak alacakların tasfiyesini adil bir takvime bağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi kapsamında taraflar uzlaştırıldı; piyasa çalkantısı yatıştırılarak sulh sağlandı."},{"label":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi ile buharlaştırılan varlıkları TMSF marifetiyle haczedip kamu ihalesiyle satarak Hazine\'ye gelir kaydet.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi varlıkları paraya çevrildi; Hazine kasasına gelir sağlanarak kamu zararı tazmin edildi."},{"label":"Zorunlu Tasarruf Fonu (NEMA) Kesintilerinin Tasfiyesi sorumlularının mal varlıklarını kaçırmasını önlemek için kolluk ve MASAK marifetiyle sınır ötesi tedbir koy.","preview":"Adalet