INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_161', 'modern', 'Türkiye-AB Katılım Müzakerelerinin Başlaması (3 Ekim 2005)', 'TBMM & Dışişleri', 'Lüksemburg\'da sabaha kadar süren pazarlıklar sonrası Türkiye AB ile tam üyelik müzakerelerine resmen başladı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Lüksemburg müzakerelerinde tam üyelik hedefinden zerre taviz verme; \'imtiyazlı ortaklık\' dayatmasını derhal reddet.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Milli onur tavizsiz korundu; AB Türkiye\'nin tam üyelik müzakere statüsünü resmen kabul etti."},{"label":"Avrupa Birliği liderleriyle diplomatik mekik diplomasisi yürüt; Kıbrıs vetolarını aşacak esnek fasıl başlıklarında uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomasi zaferle sonuçlandı; 3 Ekim 2005\'te tarihi müzakere turları resmen başladı."},{"label":"Katılım müzakereleriyle birlikte Türkiye\'ye akacak doğrudan yabancı sermaye ve AB hibe fonlarını sanayiye kanalize et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ülkeye rekor döviz girişi oldu; AB çıpası sayesinde Hazine borçlanma faizleri tarihi dipleri gördü."},{"label":"Müzakere sürecinde milli güvenlik ve savunma sanayii projelerinin AB denetimine açılmasına kesinlikle izin verme.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Savunma ve istihbarat alanında egemenlik korundu; milli güvenlikten taviz verilmedi."},{"label":"AB müktesebatını 35 fasılda uyumlaştıran \'Avrupa Birliği Entegrasyon Çerçeve Kanunu\'nu meclisten geçir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Bakanlıkların tüm mevzuatı AB standartlarıyla güncellendi; kurumsal dönüşüm ivme kazandı."}]', 161) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_162', 'modern', 'Müzakere Çerçeve Belgesi ve \'Açık Uçlu\' Tartışması', 'TBMM & Dışişleri', 'AB belgesinde tam üyelik garantisi yerine açık uçlu süreç ifadesinin yer alması diplomasiyi gerdi.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Lüksemburg müzakerelerinde tam üyelik hedefinden zerre taviz verme; \'imtiyazlı ortaklık\' dayatmasını derhal reddet.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Milli onur tavizsiz korundu; AB Türkiye\'nin tam üyelik müzakere statüsünü resmen kabul etti."},{"label":"Avrupa Birliği liderleriyle diplomatik mekik diplomasisi yürüt; Kıbrıs vetolarını aşacak esnek fasıl başlıklarında uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomasi zaferle sonuçlandı; 3 Ekim 2005\'te tarihi müzakere turları resmen başladı."},{"label":"Katılım müzakereleriyle birlikte Türkiye\'ye akacak doğrudan yabancı sermaye ve AB hibe fonlarını sanayiye kanalize et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ülkeye rekor döviz girişi oldu; AB çıpası sayesinde Hazine borçlanma faizleri tarihi dipleri gördü."},{"label":"Müzakere sürecinde milli güvenlik ve savunma sanayii projelerinin AB denetimine açılmasına kesinlikle izin verme.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Savunma ve istihbarat alanında egemenlik korundu; milli güvenlikten taviz verilmedi."},{"label":"AB müktesebatını 35 fasılda uyumlaştıran \'Avrupa Birliği Entegrasyon Çerçeve Kanunu\'nu meclisten geçir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Bakanlıkların tüm mevzuatı AB standartlarıyla güncellendi; kurumsal dönüşüm ivme kazandı."}]', 162) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_163', 'modern', 'Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı', 'TBMM & Dışişleri', 'AB\'nin Türkiye\'den liman ve havaalanlarını Güney Kıbrıs Rum yönetimine açmasını şart koşması kriz yarattı.', '[{"id":"char_basbakan","name":"Başbakan"},{"id":"char_diplomat","name":"Dışişleri Müsteşarı"}]', '[{"label":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı düzenlemesinde AB standartları ve Anayasa ilkelerini gözeterek hukuki güvenceyi ve şeffaflığı tesis et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı ile adli ve idari süreçler evrensel normlara kavuşturuldu; birey hakları korundu."},{"label":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı hususunda ilgili meslek örgütleri, sivil toplum ve halk temsilcileriyle diyalog kurarak toplumsal mutabakat sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı uygulamasında toplumsal uzlaşı sağlandı; çatışma ve protesto riskleri bertaraf edildi."},{"label":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı için kamu bütçesinden gereken finansmanı sağlarken Hazine dengelerini ve mali disiplini tavizsiz koru.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı mali olarak disipline edildi; kamu kaynaklarının israf edilmesi önlendi."},{"label":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı kapsamında devletin kamu nizamını ve kolluk otoritesini kararlılıkla koruyacak güvenlik tedbirlerini al.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı sürecinde asayiş ve devlet otoritesi sağlandı; kamu düzeni muhafaza edildi."},{"label":"TBMM\'den Kıbrıs Ek Protokolü ve Limanların Açılması Baskısı konusunda kalıcı ve yapısal dönüşüm getiren reform kanununu kabul ettir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen reform kanunu ile kurumsal nizam sağlandı; modern mevzuat yürürlüğe girdi."}]', 163) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
