INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_168', 'modern', 'Ankara Düşünce Özgürlüğü ve TCK 301. Madde Davaları', 'TBMM & Dışişleri', '\'Türklüğü aşağılama\' suçunu düzenleyen 301. madde kapsamında yazarlar ve aydınlar hakkında davalar açıldı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"AİHM içtihatları ve ifade özgürlüğü gereğince TCK 301 davalarında soruşturma iznini Adalet Bakanlığı iznine bağlayıp düşür.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Düşünce özgürlüğü korundu; yazarların ve aydınların haksız mahkumiyetlerinin önüne geçildi."},{"label":"Yazarlar ve aydınlarla Çankaya\'da istişare toplantısı yap; linç atmosferini dağıtacak sivil bir diyalog bildirisi yayınla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Kutuplaşma teskin edildi; aydınlar ile devlet arasında karşılıklı anlayış zemini arandı."},{"label":"Uluslararası boykot ve diplomatik yaptırım tehditlerinin Türkiye\'nin turizm ve ticaret gelirlerine zarar vermesini önle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik itibar korundu; uluslararası piyasalarda Türkiye algısının zedelenmesi önlendi."},{"label":"Mahkeme önlerinde avukat ve aydınlara yönelik fiziki saldırı girişimlerine karşı adliye çevresinde polis kordonu kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Adliye çevresinde asayiş sağlandı; provokasyonların sokak çatışmasına dönüşmesi engellendi."},{"label":"TCK 301. maddede \'Türklük\' ibaresini \'Türk Milleti\' olarak değiş