INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_176', 'modern', 'Genel Sağlık Sigortası (GSS) Yasasının İlk Kabülü', 'TBMM & Dışişleri', 'Tüm vatandaşların sağlık güvencesine alınmasını öngören tarihi kanun meclisten geçirildi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Her vatandaşın hastanelerde eşit ve ücretsiz tedavi hakkını anayasal sosyal devlet ilkesi gereği tavizsiz güvenceye al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Sosyal adalet tesis edildi; hastane kapılarında rehin kalma ve senet imzalama ayıbı tarihe karıştı."},{"label":"TÜRK-İŞ, DİSK ve HAK-İŞ sendikalarıyla emeklilik yaşı ve prim gün sayısında ortak bir geçiş takviminde uzlaş.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sendikaların itirazları dinlendi; kademeli geçiş formülüyle sokak eylemleri durduruldu."},{"label":"SSK, Bağ-Kur ve Emekli Sandığı açıklarını kapatacak aktüeryal dengeyi sağlamak için Hazine bütçesinden uzun vadeli fon ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sosyal güvenlik açıkları kontrol altına alındı; bütçe disiplini geleceğe dönük kurtarıldı."},{"label":"Sahte sigortalılık, kayıtdışı istihdam ve sahte engelli raporu çetelerine karşı SGK müfettişlerini ve polisi seferber et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Hileli emeklilik şebekeleri çökertildi; kamunun milyarlarca liralık kaynağı güvenceye alındı."},{"label":"5510 Sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu\'nu yürürlüğe koyarak üç kurumu SGK çatısı