INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_196', 'modern', 'Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu)', 'Anayasa Mahkemesi & TBMM', 'Milyonlarca vatandaş meydanlara inerek \'Cumhuriyete Sahip Çık\' sloganlarıyla gösteriler düzenledi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) hadisesinde anayasal meşruiyet ve yargı güvencesini tavizsiz işleterek hukukun üstünlüğünü sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) meselesinde hukuk devleti ilkeleri korundu; adli ve idari süreçler meşruiyet zemininde işletildi."},{"label":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) sürecinde meclis içi partiler, sivil toplum ve bürokrasiyle istişare masası kurarak uzlaşı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) geriliminde siyasi diyalog işletildi; taraflar teskin edilerek kriz ötelendi."},{"label":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) sebebiyle oluşabilecek mali riskleri ve Hazine harcamalarını sıkı tasarruf tedbirleriyle sınırla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) kapsamında kamu maliyesi korundu; kaynak israfının önüne geçildi."},{"label":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) karşısında emniyet ve güvenlik bürokrasisini teyakkuza geçirerek kamu düzenini tavizsiz sağla.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) karşısında asayiş korundu; devletin otoritesi hissettirildi."},{"label":"TBMM\'de Cumhuriyet Mitingleri (Tandoğan, Çağlayan, Gündoğdu) konusunu kökten çözecek demokratik bir reform kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal nizam sağlandı; benzer krizlerin tekerrürü kanunla önlendi."}]', 196) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
