INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_202', 'modern', 'Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali', 'Anayasa Mahkemesi & TBMM', 'AYM teklif dahi edilemez maddelere aykırılık gerekçesiyle Meclis\'in anayasa değişikliğini esastan iptal etti.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali hadisesinde anayasal meşruiyet ve yargı güvencesini tavizsiz işleterek hukukun üstünlüğünü sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali meselesinde hukuk devleti ilkeleri korundu; adli ve idari süreçler meşruiyet zemininde işletildi."},{"label":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali sürecinde meclis içi partiler, sivil toplum ve bürokrasiyle istişare masası kurarak uzlaşı sağla.","preview":"Adalet +7, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":7,"people":9,"treasury":4,"military":2,"authority":5},"log":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali geriliminde siyasi diyalog işletildi; taraflar teskin edilerek kriz ötelendi."},{"label":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali sebebiyle oluşabilecek mali riskleri ve Hazine harcamalarını sıkı tasarruf tedbirleriyle sınırla.","preview":"Adalet +7, Halk +4, Hazine +8, Otorite +5","effects":{"justice":7,"people":4,"treasury":8,"military":0,"authority":5},"log":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali kapsamında kamu maliyesi korundu; kaynak israfının önüne geçildi."},{"label":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali karşısında emniyet ve güvenlik bürokrasisini teyakkuza geçirerek kamu düzenini tavizsiz sağla.","preview":"Adalet +7, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":7,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali karşısında asayiş korundu; devletin otoritesi hissettirildi."},{"label":"TBMM\'de Anayasa Mahkemesi\'nin Başörtüsü Düzenlemesini İptali konusunu kökten çözecek demokratik bir reform kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal nizam sağlandı; benzer krizlerin tekerrürü kanunla önlendi."}]', 202) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_203', 'modern', 'AK Parti\'ye Yönelik 2008 Kapatma Davası İddianamesi', 'Anayasa Mahkemesi & TBMM', 'Yargıtay Başsavcısı Abdurrahman Yalçınkaya iktidar partisinin \'laikliğe aykırı eylemlerin odağı\' olduğu iddiasıyla dava açtı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Yargıtay Cumhuriyet Başsavcılığı\'nın iddianamesine karşı Anayasa Mahkemesi\'nde evrensel demokrasi ve savunma hakkını kullan.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"AYM\'de tarihi savunma yapıldı; %47 oy almış iktidar partisinin kapatılmasının rejimi çökerteceği hukuken kanıtlandı."},{"label":"Meclisteki tüm siyasi partilerle geniş tabanlı diyalog kurarak siyasi partilerin kapatılmasını imkansız kılan mutabakat ara.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Siyasi uzlaşı arandı; meclis zemininde parti kapatmaya karşı ortak bir tavır geliştirilmeye çalışıldı."},{"label":"Davanın açılmasıyla borsa ve dövizde yaşanan çalkantıyı durdurmak için Merkez Bankası ve Hazine rezervlerini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasalar sakinleştirildi; \'kapatma davası şoku\' yabancı sermaye kaçışına dönüşmeden Hazinece dengelendi."},{"label":"Kapatma davasını sokakta çatışmaya dönüştürmek isteyen marjinal gruplara karşı güvenlik tedbirlerini en üst düzeye çıkar.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sokak sükûneti sağlandı; kitlesel provokasyonların mahkeme sürecini baskı altına almasına izin verilmedi."},{"label":"Anayasa\'nın 68 ve 69. maddelerini değiştirerek parti kapatmayı Venedik Kriterleri uyarınca yalnızca şiddet şartına bağla.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Parti kapatma tehdidi Türk siyasetinin üzerinden kaldırıldı; demokratik temsil teminat altına alındı."}]', 203) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
