INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_209', 'modern', 'Danıştay Saldırısının Türban Kararıyla İlişkilendirilmesi', 'Anayasa Mahkemesi & TBMM', 'Saldırının ardından düzenlenen cenaze töreninde hükümete karşı sert protestolar ve sloganlar yükseldi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Saldırgan Alparslan Arslan ve arkasındaki çete irtibatlarını DGM ve Ağır Ceza Mahkemesi\'nde derinlemesine soruşturt.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Yargı süreci tavizsiz işletildi; menfur saldırının arkasındaki karanlık provokasyon ağı ortaya çıkarıldı."},{"label":"Danıştay üyeleri ve yüksek yargı ricaliyle Başbakanlıkta taziye ve dayanışma zirvesi düzenleyerek devlette birlik mesajı ver.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yargı camiası teskin edildi; devlet kurumları arasındaki çatışma algısı yatıştırıldı."},{"label":"Yargı mensuplarının güvenliği ve adliye binalarının x-ray ve güvenlik sistemleri için Hazine\'den acil ödenek aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yüksek yargı binalarının güvenlik açığı kapatıldı; Hazine kaynaklarıyla adliye güvenliği tahkim edildi."},{"label":"Cenaze töreninde hükümete karşı yapılan provokatif eylemlerin sokak isyanına dönüşmesini çevik kuvvetle engelle.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Cenazedeki kalkışma girişimi bastırıldı; devlet nizamı provokatörlere teslim edilmedi."},{"label":"Yargı mensuplarının can güvenliği ve lojman korumasını özel yasal statüye bağlayan \'Hâkim ve Savcılar Koruma Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Yargıçların bağımsızlığı ve can güvenliği yasal güvenceye kavuşturuldu."}]', 209) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_210', 'modern', 'Hrant Dink Suikastı (19 Ocak 2007)', 'Anayasa Mahkemesi & TBMM', 'Agos Gazetesi önünde Ogün Samast tarafından vurulan gazetecinin ölümü sonrası yüz binler \'Hepimiz Hrant\'ız\' dedi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Ogün Samast ve arkasındaki Trabzon-İstanbul istihbarat ihmali ağını savcılık marifetiyle en ince detayına kadar soruşturt.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Suikastın adli tahkikatı derinleştirildi; istihbari ihmaller ve cinayet şebekesi sanık sandalyesine oturtuldu."},{"label":"\'Hepimiz Hrant\'ız, Hepimiz Ermeniyiz\' diyen yüz binlerin vicdani feryadını sahiplen; cenazede devlet adına en üst düzeyde yer al.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Toplumsal infial sükûnete dönüştürüldü; Türkiye\'nin kardeşlik iklimi suikastçıların hedefine kurban edilmedi."},{"label":"Cinayetin uluslararası diplomaside yaratacağı tazminat ve dava risklerini bertaraf edecek hukuki savunma bütçesi ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Uluslararası hukuk ve AİHM nezdindeki tazminat süreçleri yönetildi; kamu bütçesi korundu."},{"label":"Emniyet ve Jandarma İstihbaratında cinayeti önceden bilip gizleyen kamu görevlilerini derhal açığa alıp tutuklat.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İhmali olan kamu personeli görevden uzaklaştırıldı; devlet içindeki odaklara sert mesaj verildi."},{"label":"Nefret suçları ve azınlık haklarını koruma altına alan \'Ayrımcılık ve Nefret Suçlarıyla Mücadele Kanunu\'nu kabul et.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Azınlıkların can ve mal güvenliği modern ceza mevzuatıyla tahkim edildi."}]', 210) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_211', 'modern', 'Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali', 'Anayasa Mahkemesi & TBMM', 'Cinayetin aylar öncesinden ihbar edilmesine rağmen Emniyet ve Jandarma istihbaratının harekete geçmediği belirlendi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali hadisesinde anayasal meşruiyet ve yargı güvencesini tavizsiz işleterek hukukun üstünlüğünü sağla.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali meselesinde hukuk devleti ilkeleri korundu; adli ve idari süreçler meşruiyet zemininde işletildi."},{"label":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali sürecinde meclis içi partiler, sivil toplum ve bürokrasiyle istişare masası kurarak uzlaşı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali geriliminde siyasi diyalog işletildi; taraflar teskin edilerek kriz ötelendi."},{"label":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali sebebiyle oluşabilecek mali riskleri ve Hazine harcamalarını sıkı tasarruf tedbirleriyle sınırla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali kapsamında kamu maliyesi korundu; kaynak israfının önüne geçildi."},{"label":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali karşısında emniyet ve güvenlik bürokrasisini teyakkuza geçirerek kamu düzenini tavizsiz sağla.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali karşısında asayiş korundu; devletin otoritesi hissettirildi."},{"label":"TBMM\'de Dink Cinayetinde Kamu Görevlileri ve İstihbarat İhmali konusunu kökten çözecek demokratik bir reform kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal nizam sağlandı; benzer krizlerin tekerrürü kanunla önlendi."}]', 211) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
