ffects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Albay Dursun Çiçek ve Islak İmzalı Belge Tartışması karşısında asayiş korundu; devletin otoritesi hissettirildi."},{"label":"TBMM\'de Albay Dursun Çiçek ve Islak İmzalı Belge Tartışması konusunu kökten çözecek demokratik bir reform kanununu yürürlüğe koy.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Kabul edilen yasal reform ile kurumsal nizam sağlandı; benzer krizlerin tekerrürü kanunla önlendi."}]', 219) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_220', 'modern', 'Kozmik Oda Araması: Bülent Arınç\'a Suikast İddiası', 'Anayasa Mahkemesi & TBMM', 'Seferberlik Tetkik Kurulu\'nun kozmik odalarında hakim Kadir Kayan tarafından haftalarca gizli arama yapıldı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Devlet sırrı niteliğindeki askeri belgelerin sadece hakim Kadir Kayan tarafından incelenmesi ve dışarı sızmaması için tutanak tuttur.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuki arama prosedürü işletildi; ancak askeri arşivin gizliliği konusunda tarihi tartışmalar başladı."},{"label":"Genelkurmay Başkanı İlker Başbuğ ile Başbakanlıkta baş başa görüşerek askeri karargah ile yargı arasındaki gerilimi düşür.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Kriz diyalogla yönetilmeye çalışıldı; ordu içinde infial oluşması engellendi."},{"label":"Seferberlik Tetkik Kurulu\'nun faaliyetlerinin ifşa olması sonucu doğabilecek askeri lojistik kayıpları Hazine bütçesinden karşıla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Askeri tesislerin ve gizli planların revizyonu için kaynak tahsis edildi."},{"label":"Seferberlik Tetkik Kurulu çevresinde inzibat ve polis birlikleriyle güvenlik kordonu kurup evrak kaçırılmasını engelle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Karargah çevresinde mutlak güvenlik sağlandı; belgelerin dışarı kaçırılması önlendi."},{"label":"Devlet sırrı kavramını ve askeri mahallerde adli arama usullerini kanunlaştıran \'Devlet Sırrı ve Milli Güvenlik Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kozmik belgelerin korunması ve savcılık inceleme sınırları kalıcı kanuni çerçeveye bağlandı."}]', 220) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_221', 'modern', 'Genelkurmay Eski Başkanı İlker Başbuğ\'un Tutuklanması', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'İnternet Andıcı davası kapsamında ifadeye çağrılan eski Genelkurmay Başkanı terör örgütü yöneticiliğinden tutuklandı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Eski Genelkurmay Başkanı\'nın terör örgütü yöneticiliğiyle değil, varsa Anayasa\'nın 148. maddesi gereğince Yüce Divan\'da yargılanmasını savun.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Hukukun meşruiyeti ve Anayasa hükümleri savunuldu; Genelkurmay Başkanı\'nın terörist sayılamayacağı vurgulandı."},{"label":"Komuta kademesi ve toplumun infialini dindirmek için askeri heyetlerle görüş; tansiyonu düşürecek itidal mesajları ver.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"TSK içindeki infial yatıştırıldı; ordu ile hükümet arasında doğrudan çatışma yaşanması önlendi."},{"label":"Davanın ordu morali ve savunma ihaleleri üzerinde yaratabileceği ekonomik aksamaları Hazine fonlarıyla telafi et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma sanayii yatırımlarının yargı çalkantısından etkilenmesi önlendi."},{"label":"Silivri Cezaevi çevresinde olağanüstü güvenlik tedbirleri alarak duruşma sırasında kitlesel baskın ve taşkınlıkları engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Silivri\'de güvenlik çemberi kuruldu; duruşma salonunun basılması engellendi."},{"label":"Genelkurmay Başkanı ve Kuvvet Komutanlarının sadece Başbakan izniyle ve Yüce Divan\'da yargılanmasını emreden yasa çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Komuta kademesine yasal yargılama zırhı getirildi; yerel savcıların keyfi tutuklama yetkisi kaldırıldı."}]', 221) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_222', 'modern', 'Silivri Cezaevi Duruşma Salonları ve Dev Davalar', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'Yüzlerce sanıklı Ergenekon ve Balyoz davaları için Silivri\'de dev duruşma salonları ve kampüs inşa edildi.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar davasında sahte delilleri ve usulsüz dinlemeleri yargı denetimiyle ayıkla; hukukun üstünlüğünü ve masumiyet karinesini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar dosyasında adil yargılanma hakkı gözetildi; kumpas ve sahtecilik iddiaları teftişe alındı."},{"label":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar sebebiyle kutuplaşan toplum kesimleri ve sivil toplumla istişare yürüt; toplumsal vicdanı rahatlatacak uzlaşı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar hadisesinde gerilim düşürüldü; mağduriyetler dinlenerek toplumsal barış korundu."},{"label":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar davalarının Hazineye yüklediği tazminat ve dava masraflarını mali disiplinle sınırla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar sürecinde mali dengeler korundu; kamu bütçesi haksız harcamalardan arındırıldı."},{"label":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar sürecinde TSK ve emniyet içindeki yasadışı hiziplere karşı devlet otoritesini kararlılıkla koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Silivri Cezaevi Duruşma Salonları ve Dev Davalar karşısında disiplin sağlandı; ordunun operasyonel kabiliyeti korundu."},{"label":"Bilirkişilik ve adli bilişim standartlarını baştan yazan \'Adil Yargılanma ve Delil Güvenliği Reform Kanunu\'nu çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yasal güvence getirildi; Silivri Cezaevi Duruşma Salonları ve Dev Davalar benzeri manipülasyonların önü kalıcı olarak kesildi."}]', 222) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
