INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_226', 'modern', 'TÜBİTAK Sahte Raporları ve Dijital Delil Manipülasyonları', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'Balyoz belgelerindeki fontların 2007\'de üretildiği ancak belgenin 2003 tarihli olduğu bilirkişilerce saptandı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"TÜBİTAK ve adli tıp raporlarındaki çelişkileri bağımsız uluslararası adli bilişim kuruluşlarına inceletip sahteciliği tescille.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Uluslararası bilirkişi raporuyla dijital kumpas belgelendi; delillerin sonradan harddiske yüklendiği kanıtlandı."},{"label":"Tutuklu subayların aileleri ve Vardiya Bizde platformuyla Adalet Bakanlığı\'nda görüşüp hak ihlallerini dinle.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Mağdur ailelerinin sesine kulak verildi; kumpas davalarının üzerindeki kamuoyu şüphesi büyüdü."},{"label":"Sahte bilirkişi raporları hazırlayan görevlilerin kurumdan aldıkları haksız maaş ve ödenekleri faiziyle Hazine\'ye tahsil ettir.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hileli rapor düzenleyenlerin mali kazançlarına el konuldu; kamu bütçesi korundu."},{"label":"Kumpas kuran emniyet bilişim şube polisleri ve sahte raporcu TÜBİTAK uzmanları hakkında derhal adli yakalama kararı çıkart.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kumpas çetesine operasyon yapıldı; dijital delil imal eden sahteciler adliyeye sevk edildi."},{"label":"Ceza Muhakemesi Kanunu\'nda dijital delil arama, hash değeri alma ve kopyalama usullerini katı kurallara bağlayan reform yap.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Dijital delil sahteciliği yasal olarak imkansız kılındı; imajı alınmayan diskin delil sayılamayacağı kanunlaştı."}]', 226) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
