INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_236', 'modern', 'YAŞ Toplantılarında Tutuklu Askerlerin Terfi Krizi', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'Yüksek Askeri Şura toplantılarında tutuklu subayların terfi ettirilip ettirilmeyeceği tartışıldı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Silah arkadaşlarının hukukunu korumak adına istifa eden komutanların gerekçelerini anayasal meşruiyet sınırlarında incele.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Komutanların mektubu kayıtlara girdi; TSK komuta kademesinin endişeleri hukuki çerçevede değerlendirildi."},{"label":"Genelkurmay Karargahı ile acil zirve toplayarak YAŞ terfilerinde kilitlenen dosyaları uzlaşmayla çöz.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Askeri kriz uzlaşıyla yatıştırıldı; TSK\'da emir-komuta zincirinin felç olması engellendi."},{"label":"Komutanların istifası sonrası piyasalarda oluşabilecek döviz ve faiz baskısını Hazine kaynaklarıyla dizginle.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Piyasalara güven verildi; komutanların istifasının ekonomik krizi tetiklemesi engellendi."},{"label":"Jandarma Genel Komutanı Necdet Özel\'i derhal Genelkurmay Başkanlığı\'na atayarak ordu hiyerarşisinde boşluk bırakma.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Devletin kararlılığı gösterildi; TSK komutası saatler içinde doldurularak güvenlik zafiyeti önlendi."},{"label":"Yüksek Askeri Şura\'nın yapısını sivilleştiren ve Başbakan\'a bağlayan \'YAŞ Teşkilat Reform Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Askeri şurada sivil irade hakim kılındı; sivil-asker dengesi modern standartlara kavuştu."}]', 236) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
