INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_238', 'modern', 'Necdet Özel\'in Genelkurmay Başkanlığına Atanması', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'Komutanların istifası sonrası Jandarma Genel Komutanı derhal Genelkurmay Başkanı olarak atandı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması davasında sahte delilleri ve usulsüz dinlemeleri yargı denetimiyle ayıkla; hukukun üstünlüğünü ve masumiyet karinesini savun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması dosyasında adil yargılanma hakkı gözetildi; kumpas ve sahtecilik iddiaları teftişe alındı."},{"label":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması sebebiyle kutuplaşan toplum kesimleri ve sivil toplumla istişare yürüt; toplumsal vicdanı rahatlatacak uzlaşı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması hadisesinde gerilim düşürüldü; mağduriyetler dinlenerek toplumsal barış korundu."},{"label":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması davalarının Hazineye yüklediği tazminat ve dava masraflarını mali disiplinle sınırla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması sürecinde mali dengeler korundu; kamu bütçesi haksız harcamalardan arındırıldı."},{"label":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması sürecinde TSK ve emniyet içindeki yasadışı hiziplere karşı devlet otoritesini kararlılıkla koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Necdet Özel\'in Genelkurmay Başkanlığına Atanması karşısında disiplin sağlandı; ordunun operasyonel kabiliyeti korundu."},{"label":"Bilirkişilik ve adli bilişim standartlarını baştan yazan \'Adil Yargılanma ve Delil Güvenliği Reform Kanunu\'nu çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yasal güvence getirildi; Necdet Özel\'in Genelkurmay Başkanlığına Atanması benzeri manipülasyonların önü kalıcı olarak kesildi."}]', 238) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
