INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_242', 'modern', 'Silivri ve Hasdal Tahliyeleri ve Kumpasın Çöküşü', 'Özel Yetkili Ağır Ceza Mahkemeleri', 'AYM kararının ardından cezaevindeki yüzlerce subay ve general alkışlarla tahliye oldu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Anayasa Mahkemesi\'nin oybirliğiyle verdiği tarihi hak ihlali kararını adli mahkemelerde gecikmeksizin uygulatıp tahliyeleri başlat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Adalet yerini buldu; yüzlerce vatansever subay, general ve amiral yıllar sonra alkışlarla özgürlüğüne kavuştu."},{"label":"Tahliye olan askerler ve aileleriyle devlet adına helalleşme süreci başlat; toplumda adalet duygusunu onar.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Toplumsal vicdan rahatladı; haksız yere hapis yatan kahramanların itibarı millet nezdinde tescillendi."},{"label":"Kumpas mağduru subayların cezaevinde geçen yıllarına ait tüm maaş, özlük hakları ve tazminatlarını Hazine\'den defaten öde.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali haklar eksiksiz iade edildi; haksız tutukluluk tazminatları hak sahiplerine ödendi."},{"label":"Beraat eden denizci ve havacı komutanları derhal TSK\'daki aktif görevlerine iade ederek Mavi Vatan ve sınırlara sevk et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"TSK\'nın vurucu gücü ve tecrübesi geri döndü; ordu kumpasın yaralarını sararak yeniden ayağa kalktı."},{"label":"Özel Yetkili Mahkemeleri (ÖYM) ve Terörle Mücadele Kanunu\'nun 10. maddesini tamamen kaldıran reformu yasalaştır.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Özel yetkili mahkeme garabetine son verildi; adli yargı olağan hukuk düzenine döndü."}]', 242) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
