INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_263', 'modern', '25 Aralık 2013 İkinci Dalga ve Savcı Muammer Akkaş Bildirisi', 'Adalet Bakanlığı & TBMM', 'Başbakan\'ın oğlu ve iş adamlarını hedef alan gözaltı talimatını emniyet uygulamayınca savcı adliye önünde bildiri dağıttı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Yolsuzluk iddiaları, ayakkabı kutuları ve para kasaları hakkında adli sürecin ve Sayıştay denetiminin şeffaf işlemesini sağla.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Adalet arayışı öne çıkarıldı; istifa eden bakanların Yüce Divan\'da aklanması talep edildi."},{"label":"Halkbank ve kamu bankalarının itibarını korumak için iş dünyası ve esnafla toplantı yap; reel sektöre kredi musluğunu açık tut.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasa paniği yatıştırıldı; esnaf ve KOBİ\'lerin bankacılık sistemine güveni tazelendi."},{"label":"Operasyonların tetiklediği döviz spekülasyonu ve borsa çöküşünü engellemek için Hazine likiditesini devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali darbe püskürtüldü; kur şokunun reel sektörü batırmasının önüne geçildi."},{"label":"Hükümete haber vermeden gizli operasyon yapan emniyet müdürleri ve paralel klikleri derhal görevden uzaklaştır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Emniyet teşkilatında hızlı bir iç tasfiye yapıldı; hiyerarşi dışına çıkan amirler açığa alındı."},{"label":"Adli Kolluk Yönetmeliği\'ni değiştirerek polisin savcı talimatlarını mülki amirine bildirmesini zorunlu kılan reform yap.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yargı-kolluk ilişkileri sivil idareye bağlandı; savcıların habersiz şafak operasyonları engellendi."}]', 263) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_264', 'modern', 'Emniyet Müdürlerinin Gece Yarısı Görevden Alınması', 'Adalet Bakanlığı & TBMM', 'Operasyonu amirlerinden gizleyen İstanbul Emniyet Müdürü ve şube müdürleri sabaha karşı görevden alındı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Emniyet Müdürlerinin Gece Yarısı Görevden Alınması karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de Emniyet Müdürlerinin Gece Yarısı Görevden Alınması sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 264) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_265', 'modern', 'TIR Krizleri: Adana ve Kırıkhan\'da MİT TIR\'larının Durdurulması', 'Adalet Bakanlığı & TBMM', 'Suriye Türkmenlerine insani yardım taşıyan MİT tırları savcı ve jandarma ekiplerince yolda silah zoruyla durduruldu.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Devlet sırrı ve milli güvenlik doktrini kapsamında Suriye Türkmenlerine gönderilen yardımların dokunulmazlığını savun.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli savunma ve dış politika sırrı savunuldu; devletin beka operasyonuna hukuki sahip çıkıldı."},{"label":"Bölgedeki aşiretler, Türkmen meclisi ve sivil toplum temsilcileriyle görüşerek insani yardımların güvenli intikalini sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Bölge halkı teskin edildi; Türkmenlerin insani yardıma erişimi güvence altına alındı."},{"label":"MİT lojistiğinin ve sınır ötesi yardım tırlarının güvenliği için Hazine\'den ek sınır ötesi yardım bütçesi tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sınır hattındaki insani operasyonlar kesintisiz sürdürüldü."},{"label":"MİT görevlilerini darp edip yere yatıran jandarma ve savcılık ekibine karşı Adana Valisi ve Özel Harekat polislerini sahaya sür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Tırların zorla açılması ve aranması engellendi; tırlar emniyet kordonunda sınır boyuna ulaştırıldı."},{"label":"Devlet sırrı niteliğindeki askeri ve istihbari taşımaların aranamayacağını emreden \'Milli İstihbarat Hizmetleri Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"MİT\'in sınır ötesi operasyonel yetkileri kanunlaştı; ajan ve sevkiyat dokunulmazlığı tescillendi."}]', 265) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_266', 'modern', 'MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı', 'Adalet Bakanlığı & TBMM', 'Devlet sırrı taşıyan tırların aranması ve MİT personelinin darp edilmesi devlet krizine dönüştü.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de MİT Görevlilerinin Yere Yatırılıp Kelepçelenmesi Skandalı sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 266) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_267', 'modern', 'İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti', 'Adalet Bakanlığı & TBMM', 'Başbakan ve bakanların kriptolu telefonlarının dinlenerek montajlandığı iddia edilen ses kayıtları Youtube\'a yüklendi.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de İnternete Sızdırılan Kriptolu Ses Kayıtları ve \'Sıfırlama\' Kaseti sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 267) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
