INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_273', 'modern', 'Bank Asya\'ya BDDK ve TMSF Tarafından El Konulması', 'Adalet Bakanlığı & TBMM', 'Mali yapısı bozulan ve şeffaf ortaklık yapısını sunamayan Bank Asya\'nın yönetimi TMSF\'ye geçti.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Terörün finansmanı ve kara para aklama şüphelerini MASAK ve BDDK murakıplarıyla belgelendirip bağımsız mahkemeye sun.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuki prosedürler eksiksiz tamamlandı; terör örgütüne para aktaran mekanizmalar adli delillerle çöktü."},{"label":"Banka mudileri ve şirket çalışanlarının mağdur olmaması için TMSF bünyesinde şeffaf bilgilendirme ve ödeme masası kur.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Küçük mudilerin paraları ödendi; krizin bankacılık sistemine sirayet etmesi önlendi."},{"label":"Kayyuma devredilen şirket ve holding varlıklarını TMSF portföyüne alıp şeffaf ihalelerle satarak Hazineye gelir kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Terörün mali kaynakları devlete irad kaydedildi; Hazine kasasına devasa gelir girdi."},{"label":"Kayyum atamalarına karşı holding binaları önünde toplanan örgüt sempatizanlarına karşı çevik kuvvetle barikat kur.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Bina işgalleri ve taşkınlıklar önlendi; kayyum heyetleri göreve başlatıldı."},{"label":"Terör örgütlerinin şirketlerine kayyum atanmasını ve tasfiyesini hızlandıran \'Terörün Finansmanıyla Mücadele Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Mali terörle mücadelede yasal altyapı tamamlandı; himmet çarkları kanunen parçalandı."}]', 273) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
