INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_276', 'modern', 'Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması', 'Adalet Bakanlığı & TBMM', 'Yayın ilkelerini ihlal eden ve terör propagandası yapan televizyon kanallarının uydudan yayını kesildi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de Samanyolu Yayın Grubu Kanallarının Türksat\'tan Çıkarılması sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 276) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_277', 'modern', 'Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması', 'Adalet Bakanlığı & TBMM', 'Dini bir gruba yönelik kumpas kurdukları iddiasıyla emniyet müdürleri ve medya yöneticileri tutuklandı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de Tahşiyeciler Davası ve Hidayet Karaca\'nın Tutuklanması sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 277) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
