fects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Selam Tevhid Kudüs Ordusu Kumpası ve VIP Dinlemeler karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de Selam Tevhid Kudüs Ordusu Kumpası ve VIP Dinlemeler sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 278) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_279', 'modern', 'Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi', 'Adalet Bakanlığı & TBMM', 'Kırmızı Kitap olarak bilinen belgeye Paralel Devlet Yapılanması milli güvenliği tehdit eden unsur olarak yazıldı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi meselesinde yargı bağımsızlığı ve anayasal meşruiyet kurallarını tavizsiz işleterek adaleti sağla.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi konusunda adil yargılanma ve hukuk kuralları gözetildi; idari işlemler hukuka bağlandı."},{"label":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi sürecinde ilgili kurumlar, sivil toplum ve halkla istişare yürüterek toplumsal uzlaşıyı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi hususunda taraflar dinlendi; diyalog kanalları açılarak gerilim yatıştırıldı."},{"label":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi ile bağlantılı kamu kaynaklarını ve Hazine fonlarını sıkı tasarruf tedbirleriyle koru.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi hadisesinde mali disiplin korundu; kamu bütçesi olası zararlardan korundu."},{"label":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi karşısında emniyet ve istihbarat birimlerini görevlendirerek kamu düzenini ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi karşısında kamu nizamı sağlandı; devletin kararlılığı gösterildi."},{"label":"TBMM\'de Milli Güvenlik Siyaset Belgesine PDY/FETÖ Tehdidinin Girmesi sorununu kurumsal olarak çözecek reform kanununu kabul ettir.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile kurumsal düzen kuruldu; benzer krizlerin tekerrürü önlendi."}]', 279) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_280', 'modern', 'Savcı Mehmet Selim Kiraz\'ın Çağlayan Adliyesinde Şehit Edilmesi', 'Adalet Bakanlığı & TBMM', 'DHKP-C\'li teröristler Berkin Elvan dosyasını yürüten savcıyı makamında rehin alıp şehit etti.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Şehit savcının yürüttüğü Berkin Elvan soruşturmasını hiçbir boşluk bırakmadan adaletin gerektirdiği şekilde sonuçlandır.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Hukukun üstünlüğü ve adalet kararlılıkla savunuldu; teröristlerin davayı rehin almasına izin verilmedi."},{"label":"Tüm adliye çalışanları ve barolarla ortak teröre lanet mitingi düzenleyerek yargı camiasında birlik ve beraberlik sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yargı camiası kenetlendi; terör eylemine karşı tüm hakim, savcı ve avukatlar ortak ses verdi."},{"label":"Şehit savcının ailesine devlet övünç madalyası ve en üst baremden şehitlik maaşı/konutu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şehidin geride kalan ailesine devlet sahip çıktı; maddi ve manevi güvence sağlandı."},{"label":"Savcıyı makamında rehin alan DHKP-C\'li teröristlere karşı Polis Özel Harekat timleriyle operasyon emri ver.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Operasyonla teröristler etkisiz hale getirildi; devlet terörle pazarlık yapmayacağını gösterdi."},{"label":"Tüm adalet saraylarının girişlerinde avukatlar dahil çantaların x-ray\'den geçmesini zorunlu kılan \'Adliye Güvenlik Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Adliyelerdeki güvenlik zafiyetleri kapatıldı; duruşma salonlarına silah sokulması imkansız kılındı."}]', 280) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_281', 'modern', 'Dağlıca Karakolu Baskını ve 12 Şehit (Ekim 2007)', 'İçişleri Bakanlığı & MSB', 'Hakkari Dağlıca taburuna ağır silahlarla saldıran teröristler 12 askerimizi şehit etti, 8 askeri kaçırdı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Karakol baskınındaki istihbarat zafiyetleri ve lojistik gecikmeler hakkında adli ve askeri teftiş heyeti görevlendir.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Sınır karakollarındaki açıklar tespit edildi; ihmali olan komuta kademesi adli teftişe tabi tutuldu."},{"label":"Şehit aileleri ve yaralı gazilerle bir araya gelerek milletin infialini vakar ve metanetle kucakla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Milletin bağrı yangın yerine döndü; birlik ve beraberlik mesajlarıyla fitne engellendi."},{"label":"Savunma Sanayii İcra Komitesi\'ni toplayarak sınır karakollarının yerini alacak \'Yüksek Güvenlikli Kalekol\' inşasına acil Hazine fonu aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Sınır boylarına havan ve roket geçirmez Kalekollar yapıldı; Mehmetçiğin üs güvenliği tahkim edildi."},{"label":"F-16\'lar ve Özel Kuvvetler taburlarıyla sınır ötesindeki terör kamplarına (Zap, Avaşin, Kandil) amansız hava harekatı başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır ötesi terör inleri yerle bir edildi; Mehmetçiğin intikamı misliyle alındı."},{"label":"Milli Savunma Bakanlığı bünyesinde \'Profesyonel Sınır Birlikleri ve Askeri Üs Güvenliği Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Zorunlu askerlik yerine profesyonel komando tugayları sınır hattına yerleştirildi."}]', 281) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
