INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_283', 'modern', 'Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008)', 'İçişleri Bakanlığı & MSB', 'TSK kış ortasında Kuzey Irak Hakurk ve Zap kamplarına kara harekâtı düzenleyerek örgüt üslerini yerle bir etti.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini yok et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) karşısında tavizsiz güvenlik tedbirleri uygulandı; devletin kudreti gösterildi."},{"label":"TBMM\'de Güneş Sınır Ötesi Kara Harekâtı (Şubat 2008) konusundaki kurumsal zafiyetleri kapatan Terörle Mücadele ve İç Güvenlik Kanunu\'nu güncelle.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile güvenlik mimarisi tahkim edildi; benzer tehditler önlendi."}]', 283) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
