INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_285', 'modern', 'Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması', 'İçişleri Bakanlığı & MSB', 'MİT Müsteşarı ve örgüt temsilcileri arasında Norveç\'te yapılan gizli görüşmelerin ses kasetleri internete sızdırıldı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"Oslo Görüşmeleri ve MİT Heyeti Ses Kayıtlarının Sızması karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini y