INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_291', 'modern', 'Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü', 'İçişleri Bakanlığı & MSB', 'Müzakere yürüten kamu görevlilerine cezai muafiyet sağlayan tarihi çerçeve yasa meclisten geçti.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"Çözüm Süreci Çerçeve Kanunu\'nun (6551) TBMM\'de Kabulü karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini yok et.","preview":"Adalet +5, Halk +5, Güvenlik +9