INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_292', 'modern', '6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası', 'İçişleri Bakanlığı & MSB', 'HDP\'nin sokak çağrısı sonrası 35 ilde çıkan olaylarda 53 kişi hayatını kaybetti; şehirler yakıldı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini yok et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası karşısında tavizsiz güvenlik tedbirleri uygulandı; devletin kudreti gösterildi."},{"label":"TBMM\'de 6-8 Ekim 2014 Kobani Olayları ve Şiddet Dalgası konusundaki kurumsal zafiyetleri kapatan Terörle Mücadele ve İç Güvenlik Kanunu\'nu güncelle.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile güvenlik mimarisi tahkim edildi; benzer tehditler önlendi."}]', 292) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_293', 'modern', 'Yasin Börü ve Arkadaşlarının Katledilmesi', 'İçişleri Bakanlığı & MSB', 'Diyarbakır\'da kurban eti dağıtırken vahşice katledilen gençlerin davası tüm Türkiye\'nin vicdanını kanattı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Kobani bahanesiyle sokağa dökülüp kurban eti dağıtan gençleri vahşice katleden failleri ve kışkırtıcıları Ağır Ceza\'da yargılat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Vahşetin failleri tek tek yakalandı; sokak isyanı çağrısı yapan siyasi sorumlular adalet önüne çıkarıldı."},{"label":"Diyarbakır ve bölge halkıyla temas kurarak sivil toplum kuruluşlarıyla provokasyonun mezhep ve etnik çatışmaya evrilmesini önle.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Bölge halkı sokak terörüne prim vermedi; iç savaş provokasyonu kardeşlik bağıyla boşa çıkarıldı."},{"label":"Yakılan kamu binaları, okullar, ambulanslar ve yağmalanan esnaf dükkanlarının zararını Hazine fonundan tazmin et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Esnafın yaraları sarıldı; kamu binaları hızla tamir edilerek devlet hizmetleri aksatılmadı."},{"label":"35 ilde sokakları ateşe veren ve kamu düzenini tehdit eden kalkışmaya karşı zırhlı polis ve jandarmayla sert müdahale et.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Kalkışma 48 saatte bastırıldı; sokak teröristlerine devletin demir yumruğu indirildi."},{"label":"Şiddet çağrısı yapan ve kamu düzenini bozan siyasi parti eylemlerine karşı \'İç Güvenlik Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Mülki amirlere ve polise molotof ve taşlı saldırılara karşı anında müdahale yetkisi tanındı."}]', 293) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
