INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_303', 'modern', 'Sur Tarihi Dokusunun Yıkımı ve Yeniden İhya Projesi', 'İçişleri Bakanlığı & MSB', 'Çatışmalarda tahrip olan tarihi Diyarbakır Sur ilçesi acele kamulaştırmayla TOKİ tarafından aslına uygun inşa edildi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Operasyon bölgesinde sivillerin zarar görmemesi için tahliye koridorları aç; insan hakları ve tahkikat süreçlerini savcılarla denetle.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Sivil can kaybını önleyen tahkikatlar yapıldı; hukuki meşruiyet uluslararası arenada korundu."},{"label":"Bölge halkı, kanaat önderleri ve esnafla görüşerek sokağa çıkma yasağının getirdiği mağduriyetleri doğrudan ayni yardımlarla hafiflet.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkın devlete olan bağı korundu; terör örgütünün halkı ayaklandırma çağrıları boşa çıkarıldı."},{"label":"Çatışmalarda yıkılan tarihi Sur içi ve ilçe merkezlerinin yeniden inşası için Hazine\'den devasa kentsel dönüşüm fonu ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi yapılar ihya edildi; mağdur ailelere modern TOKİ konutları ve kira yardımları bağlandı."},{"label":"Jandarma Özel Asayiş Komutanlığı (JÖAK) ve Polis Özel Harekat (PÖH) müşterek timleriyle hendek ve barikatları patlatarak ilçeleri temizle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"İlçe merkezleri teröristlerden arındırıldı; çukur siyaseti hendeklere gömülerek devlet hakimiyeti kuruldu."},{"label":"Terörden zarar gören il ve ilçelerin imarı ve yerel yönetimlerin teröre finansman sağlamasını engelleyen \'İl İdaresi Kanunu Reformu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yerel yönetimlerin hendek kazmasına karşı kalıcı mülki amir vesayeti ve denetim mekanizması getirildi."}]', 303) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
