INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_308', 'modern', 'Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı', 'İçişleri Bakanlığı & MSB', 'Hafta sonu iznine çıkan silahsız erleri taşıyan halk otobüsüne bombalı araç çarptı; 15 Mehmetçik şehit düştü.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"Kayseri Komando Tugayı Çarşı İzni Servisi Saldırısı karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini yok et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Ot