INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_309', 'modern', 'İzmir Adliyesi Saldırısı ve Şehit Polis Fethi Sekin', 'İçişleri Bakanlığı & MSB', 'Adliyeye sızmak isteyen teröristlerle tek başına çatışıp mermisi bitene kadar direnen kahraman polis katliamı önledi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"İzmir Adliyesi\'ne saldıran terör hücresinin tüm lojistik ve istihbarat ağını savcılık marifetiyle çözüp işbirlikçileri adalete teslim et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adliye saldırısının arkasındaki şebeke çökertildi; şehit polisin kanı yerde bırakılmadı."},{"label":"Tüm İzmir halkı ve adliye çalışanlarıyla dev bir anma töreni düzenle; şehit polisin kahramanlığını milli hafızaya kazı.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Millet tek yürek oldu; terörün adliyeyi rehin alma ve yüzlerce insanı katletme planı kahramanca bozuldu."},{"label":"Şehit Trafik Polisi Fethi Sekin ve şehit mübaşir Musa Can\'ın ailelerine ömür boyu maaş, konut ve çocuklarına eğitim bursu bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şehit ailelerine devletin şefkati uzandı; gelecekleri devlet teminatına alındı."},{"label":"Tek tabancasıyla mermisi bitene kadar kalaşnikoflu teröristlerle çatışan kahramanın izinden giderek adliye önlerinde zırhlı polis noktaları kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Tüm adliyeler çevresinde yüksek güvenlik kalkanı kuruldu; terör hedefleri bertaraf edildi."},{"label":"Görev başında canını siper eden güvenlik görevlilerinin aile haklarını ve kahramanlık taltifini düzenleyen \'Milli Şehitlik Yasası\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kahraman polis ve askerlerin anayasal hakları güvenceye alındı; anıları adliye caddelerinde yaşatıldı."}]', 309) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_310', 'modern', 'Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması', 'İçişleri Bakanlığı & MSB', 'Yılbaşı gecesi 39 kişiyi katleden DEAŞ\'lı terörist Abdulgadir Masharipov Esenyurt\'ta canlı ele geçirildi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması hadisesinde terör suçlularını hukuk ve anayasa çerçevesinde yargı önüne çıkarıp adli hesabı sor.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması konusunda hukuki süreç tavizsiz işletildi; terör eylemlerine karşı meşru adli tahkikat yürütüldü."},{"label":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması sürecinde sivil halkı ve mağdur aileleri korumak için toplumsal dayanışma ve uzlaşı kanallarını işlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması hadisesinde halk teskin edildi; fitne ve kargaşa yaratma girişimleri bertaraf edildi."},{"label":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması ile zarar gören kamu altyapısını ve vatandaş mülklerini Hazine fonlarıyla hızla ihya et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması mali olarak telafi edildi; kamu kaynaklarıyla bölge güvenliği ve refahı finanse edildi."},{"label":"Reina Gece Kulübü Katliamı ve Teröristin Canlı Yakalanması karşısında emniyet, jandarma ve TSK unsurlarını tam yetkiyle sahaya sürerek terör tehdidini y