INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_311', 'modern', 'Boğaziçi Köprüsü\'nün Askeri Birliklerce Kapatılması (22:00)', 'Cumhurbaşkanlığı & TBMM', 'Zırhlı askeri araçların Boğaziçi ve FSM köprülerini tek taraflı trafiğe kapatması darbe girişimini başlattı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"}]', '[{"label":"Darbe teşebbüsünde bulunan cunta mensupları hakkında cumhuriyet başsavcılıklarınca derhal ağırlaştırılmış müebbet davaları aç.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Hukuk devleti cuntaya teslim olmadı; darbeci generaller ve hainler bağımsız mahkemelerde hesap vermeye başladı."},{"label":"Cumhurbaşkanı\'nın çağrısıyla sokaklara, meydanlara ve havalimanlarına akın eden milyonlarca vatansevere öncülük et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Milli irade tankları çıplak elleriyle durdurdu; millet devletiyle birleşerek tarihin en büyük destanını yazdı."},{"label":"Darbe girişiminin finansal piyasalarda oluşturduğu şoku önlemek için bankaları açık tut; Merkez Bankası piyasaya sınırsız TL sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik panik püskürtüldü; pazartesi sabahı piyasalar açılarak spekülatif çöküş engellendi."},{"label":"Ömer Halisdemir\'in Özel Kuvvetler Karargahı\'nda cuntacı Semih Terzi\'yi alnından vurarak başlattığı direnişi tüm kışlalarda uygulat.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kahraman Mehmetçik ve vatansever polisler cuntayı kışlalarında etkisiz hale getirdi; darbe girişimi ezildi."},{"label":"Milli Güvenlik Kurulu ve Bakanlar Kurulu kararıyla 3 ay süreyle Olağanüstü Hal (OHAL) ilan edip KHK yetkilerini yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Devletin bekası anayasal OHAL rejimiyle korundu; ordu, emniyet ve yargıdaki cuntacı sızıntılar hızla temizlendi."}]', 311) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_312', 'modern', 'TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması', 'Cumhurbaşkanlığı & TBMM', 'Kendilerine \'Yurtta Sulh Konseyi\' diyen cuntacılar spikere silah zoruyla korsan darbe bildirisini okuttu.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması hadisesinde Anayasa ve hukuk ilkelerini kararlılıkla savunarak meşruiyeti koru.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması konusunda anayasal kurallar gözetildi; devletin meşru düzeni korundu."},{"label":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması sürecinde siyasi partiler, meclis ve halkla diyalog kurarak toplumsal mutabakat sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması geriliminde siyasi uzlaşı işletildi; çatışma ortamı yumuşatıldı."},{"label":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması sürecinin Hazine ve kamu bütçesi üzerindeki yükünü mali disiplinle kontrol altında tut.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması sebebiyle oluşabilecek kamu zararı engellendi; mali disiplin korundu."},{"label":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması karşısında emniyet ve kolluk bürokrasisini teyakkuza geçirerek kamu nizamını ve devlet otoritesini koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması karşısında devletin otoritesi gösterildi; kamu düzeni tavizsiz korundu."},{"label":"TBMM\'de TRT Stüdyolarının İşgali ve Korsan Bildirinin Okutulması konusunu yapısal olarak düzenleyen reform mevzuatını yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yürürlüğe giren yasa ile kurumsal intizam sağlandı; benzer krizlerin tekerrürü önlendi."}]', 312) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
