INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_316', 'modern', 'Şehit Astsubay Ömer Halisdemir\'in Tarihi Kurşunu', 'Cumhurbaşkanlığı & TBMM', 'Özel Kuvvetler Karargahını ele geçirmeye gelen darbeci general Semih Terzi\'yi alnından vurarak darbenin seyrini değiştirdi.', '[{"id":"char_genelkurmay_baskani","name":"Genelkurmay Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Darbe teşebbüsünde bulunan cunta mensupları hakkında cumhuriyet başsavcılıklarınca derhal ağırlaştırılmış müebbet davaları aç.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Hukuk devleti cuntaya teslim olmadı; darbeci generaller ve hainler bağımsız mahkemelerde hesap vermeye başladı."},{"label":"Cumhurbaşkanı\'nın çağrısıyla sokaklara, meydanlara ve havalimanlarına akın eden milyonlarca vatansevere öncülük et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Milli irade tankları çıplak elleriyle durdurdu; millet devletiyle birleşerek tarihin en büyük destanını yazdı."},{"label":"Darbe girişiminin finansal piyasalarda oluşturduğu şoku önlemek için bankaları açık tut; Merkez Bankası piyasaya sınırsız TL sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik panik püskürtüldü; pazartesi sabahı piyasalar açılarak spekülatif çöküş engellendi."},{"label":"Ömer Halisdemir\'in Özel Kuvvetler Karargahı\'nda cuntacı Semih Terzi\'yi alnından vurarak başlattığı direnişi tüm kışlalarda uygulat.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kahraman Mehmetçik ve vatansever polisler cuntayı kışlalarında etkisiz hale getirdi; darbe girişimi ezildi."},{"label":"Milli Güvenlik Kurulu ve Bakanlar Kurulu kararıyla 3 ay süreyle Olağanüstü Hal (OHAL) ilan edip KHK yetkilerini yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Devletin bekası anayasal OHAL rejimiyle korundu; ordu, emniyet ve yargıdaki cuntacı sızıntılar hızla temizlendi."}]', 316) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
