INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_321', 'modern', 'Yenikapı Tarihi Mitingi ve Milli Mutabakat', 'Cumhurbaşkanlığı & TBMM', '5 milyon vatandaşın katıldığı mitingde Cumhurbaşkanı, Başbakan ve muhalefet liderleri aynı sahnede birlik mesajı verdi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Yenikapı Tarihi Mitingi ve Milli Mutabakat hadisesinde Anayasa ve hukuk ilkelerini kararlılıkla savunarak meşruiyeti koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yenikapı Tarihi Mitingi ve Milli Mutabakat konusunda anayasal kurallar gözetildi; devletin meşru düzeni korundu."},{"label":"Yenikapı Tarihi Mitingi ve Milli Mutabakat sürecinde siyasi partiler, meclis ve halkla diyalog kurarak toplumsal mutabakat sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Yenikapı Tarihi Mitingi ve Milli Mutabakat geriliminde siyasi uzlaşı işletildi; çatışma ortamı yumuşatıldı."},{"label":"Yenikapı Tarihi Mitingi ve Milli Mutabakat sürecinin Hazine ve kamu bütçesi üzerindeki yükünü mali disiplinle kontrol altında tut.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yenikapı Tarihi Mitingi ve Milli Mutabakat sebebiyle oluşabilecek kamu zararı engellendi; mali disiplin korundu."},{"label":"Yenikapı Tarihi Mitingi ve Milli Mutabakat karşısında emniyet ve kolluk bürokrasisini teyakkuza geçirerek kamu nizamını ve devlet otoritesini koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Yenikapı Tarihi Mitingi ve Milli Mutabakat karşısında devletin otoritesi gösterildi; kamu düzeni tavizsiz korundu."},{"label":"TBMM\'de Yenikapı Tarihi Mitingi ve Milli Mutabakat konusunu yapısal olarak düzenleyen reform mevzuatını yürürlüğe koy.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Yürürlüğe giren yasa ile kurumsal intizam sağlandı; benzer krizlerin tekerrürü önlendi."}]', 321) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
