INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_341', 'modern', 'Kardak Kayalıkları Krizi (Ocak 1996)', 'Dışişleri Bakanlığı & Milli Savunma', 'Figen Akad gemisinin karaya oturmasıyla başlayan gerilimde SAT komandoları gece yarısı İkizce kayalığına bayrak dikti.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Kardak Kayalıkları Krizi (Ocak 1996) krizinde uluslararası hukuk, ikili anlaşmalar ve egemenlik haklarımızı tavizsiz savun.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Kardak Kayalıkları Krizi (Ocak 1996) konusunda diplomatik ve hukuki meşruiyet korundu; Türkiye\'nin haklılığı dünyaya anlatıldı."},{"label":"Kardak Kayalıkları Krizi (Ocak 1996) sürecinde ilgili ülkeler ve müttefiklerle müzakere masası kurarak barışçıl ve uzlaşmacı diplomasi yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Kardak Kayalıkları Krizi (Ocak 1996) geriliminde diplomatik diyalog işletildi; krizin tırmanması önlendi."},{"label":"Kardak Kayalıkları Krizi (Ocak 1996) ile bağlantılı dış ticaret, turizm ve enerji çıkarlarımızı korumak için Hazine dengelerini tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kardak Kayalıkları Krizi (Ocak 1996) kaynaklı ekonomik riskler önlendi; milli ekonomi dış baskılara karşı korundu."},{"label":"Kardak Kayalıkları Krizi (Ocak 1996) karşısında Türk Silahlı Kuvvetleri ve MİT unsurlarını teyakkuza geçirerek sahada caydırıcı güç göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kardak Kayalıkları Krizi (Ocak 1996) karş