INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_342', 'modern', 'Davos 2009 \'One Minute\' Çıkışı', 'Dışişleri Bakanlığı & Milli Savunma', 'Cumhurbaşkanı Erdoğan Dünya Ekonomik Forumu\'nda Şimon Peres\'e ve moderatör David Ignatius\'a sert tepki gösterdi.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Davos 2009 \'One Minute\' Çıkışı krizinde uluslararası hukuk, ikili anlaşmalar ve egemenlik haklarımızı tavizsiz savun.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Davos 2009 \'One Minute\' Çıkışı konusunda diplomatik ve hukuki meşruiyet korundu; Türkiye\'nin haklılığı dünyaya anlatıldı."},{"label":"Davos 2009 \'One Minute\' Çıkışı sürecinde ilgili ülkeler ve müttefiklerle müzakere masası kurarak barışçıl ve uzlaşmacı diplomasi yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Davos 2009 \'One Minute\' Çıkışı geriliminde diplomatik diyalog işletildi; krizin tırmanması önlendi."},{"label":"Davos 2009 \'One Minute\' Çıkışı ile bağlantılı dış ticaret, turizm ve enerji çıkarlarımızı korumak için Hazine dengelerini tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Davos 2009 \'One Minute\' Çıkışı kaynaklı ekonomik riskler önlendi; milli ekonomi dış baskılara karşı korundu."},{"label":"Davos 2009 \'One Minute\' Çıkışı karşısında Türk Silahlı Kuvvetleri ve MİT unsurlarını teyakkuza geçirerek sahada caydırıcı güç göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Davos 2009 \'One Minute\' Çıkışı karşısında milli güvenlik tedbirleri uygulandı; Türkiye\'nin sahadaki ağırlığı hissettirildi."},{"label":"TBMM\'de Davos 2009 \'One Minute\' Çıkışı konusunu milli doktrine bağlayan Stratejik Dış Politika ve Güvenlik Kanunu\'nu yürürlüğe koy.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Kabul edilen yasal reform ile milli güvenlik kırmızı çizgileri kanunlaştı; egemenliğimiz korundu."}]', 342) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_343', 'modern', 'Mavi Marmara Baskını ve 10 Şehit (Mayıs 2010)', 'Dışişleri Bakanlığı & Milli Savunma', 'Gazze\'ye insani yardım götüren sivil gemiye uluslararası sularda İsrail komandolarınca helikopterden ateş açıldı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Uluslararası Ceza Mahkemesi ve BM İnsan Hakları Konseyi\'nde İsrail aleyhine korsanlık ve kasten adam öldürme davaları açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk mücadelesi uluslararası alana taşındı; İsrailli komutanlar hakkında kırmızı bülten kararları çıkarıldı."},{"label":"Şehit aileleri ve İHH heyetiyle koordinasyon kur; İsrail\'den resmi özür ve tazminat şartı gelene kadar ilişkileri dondur.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Milli onur tavizsiz savunuldu; Netanyahu\'nun resmi özür dilemesi ve tazminat ödemesi sağlandı."},{"label":"İsrail ile askeri ve savunma sanayii ihalelerini derhal iptal ederek yerli savunma sanayiine ek bütçe aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma projeleri hızlandırıldı; Heron ve tank modernizasyonu bağımlılığı yerli firmalara devredildi."},{"label":"Türk donanmasını Doğu Akdeniz\'de teyakkuza geçir; Gazze ambargosuna karşı deniz sahasında fırkateyn devriyelerini artır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Doğu Akdeniz\'de donanmanın caydırıcılığı hissettirildi; Türk bayraklı gemilere yönelik yeni tacizler önlendi."},{"label":"Uluslararası sularda sivil yardım konvoylarının korunmasını güvenceye alan \'Deniz Güvenliği ve İnsani Diplomasi Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İnsani diplomasinin hukuki altyapısı kuruldu; Türkiye mazlum milletlerin küresel hamisi oldu."}]', 343) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
