INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_348', 'modern', 'Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015)', 'Dışişleri Bakanlığı & Milli Savunma', 'Karakolu kuşatan DEAŞ tehdidine karşı Süleyman Şah\'ın naaşı ve Mehmetçik Suriye Eşmesi\'ne güvenle taşındı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) krizinde uluslararası hukuk, ikili anlaşmalar ve egemenlik haklarımızı tavizsiz savun.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) konusunda diplomatik ve hukuki meşruiyet korundu; Türkiye\'nin haklılığı dünyaya anlatıldı."},{"label":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) sürecinde ilgili ülkeler ve müttefiklerle müzakere masası kurarak barışçıl ve uzlaşmacı diplomasi yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) geriliminde diplomatik diyalog işletildi; krizin tırmanması önlendi."},{"label":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) ile bağlantılı dış ticaret, turizm ve enerji çıkarlarımızı korumak için Hazine dengelerini tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) kaynaklı ekonomik riskler önlendi; milli ekonomi dış baskılara karşı korundu."},{"label":"Şah Fırat Operasyonu ve Süleyman Şah Türbesinin Nakli (2015) karşısında Türk Silahlı Kuvvetleri ve MİT unsurlarını teyakkuza geçirerek sahada caydırıcı güç göster.","preview"