INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_349', 'modern', 'Rus Su-24 Savaş Uçağının Türk F-16\'ları Tarafından Düşürülmesi (Kasım 2015)', 'Dışişleri Bakanlığı & Milli Savunma', 'Hatay Yayladağı sınırını 17 saniye ihlal eden ve uyarılara yanıt vermeyen Rus savaş uçağı F-16 devriyesince vuruldu.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Suriye sınırında 17 saniyelik hava sahası ihlalini ve yapılan 10 acil telsiz uyarısını radar kayıtlarıyla BM\'ye sun.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuki haklılık dünyaya belgelendi; sınır egemenliğini ihlal eden jete angajman kurallarının işletildiği kanıtlandı."},{"label":"Moskova ile temas kanallarını açık tut; Cumhurbaşkanı mektubu ve diplomatik temaslarla iki ülke arasındaki krizi tatlıya bağla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik kriz aşıldı; Rusya ile turizm, charter uçuşları ve ticari ilişkiler yeniden canlandırıldı."},{"label":"Rusya\'nın uyguladığı domates ve turizm ambargosunun Antalya ve Ege çiftçisine zararını Hazine sübvansiyonlarıyla karşıla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Çiftçiler iflastan kurtarıldı; alternatif ihracat pazarları bulunarak Hazine destekleri sağlandı."},{"label":"Hatay ve Gaziantep sınır boylarına uçaksavar ve Hawk hava savunma bataryalarını yerleştirerek hava sahasını kapat.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hava sahası çelik kalkanla korundu; sınır boyunda caydırıcı hava üstünlüğü kuruldu."},{"label":"TSK Hava Angajman Kuralları\'nı modernize ederek ihlal anında otomatik mukabele yetkilerini kanunlaştıran reform yap.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Sınır ihlallerine karşı Türk Hava Kuvvetleri\'nin operasyonel yetkisi kanunla tescillendi."}]', 349) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
