INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_366', 'modern', 'Libya ile İmzalanan Deniz Yetki Alanları Sınırlandırma Mutabakatı', 'Dışişleri Bakanlığı & Milli Savunma', 'Trablus hükümetiyle imzalanan tarihi anlaşma ile Yunanistan\'ın Akdeniz\'i kapatma planı çöpe atıldı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Libya Ulusal Mutabakat Hükümeti ile imzalanan Deniz Yetki Alanları Anlaşması\'nı Birleşmiş Milletler nezdinde resmen tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Akdeniz\'de tarihi hukuk zaferi kazanıldı; Sevilla haritası çöpe atılarak Türkiye\'nin kıta sahanlığı tescillendi."},{"label":"Kardeş Azerbaycan ile \'Tek Millet, İki Devlet\' prensibiyle Şuşa Beyannamesi\'ni imzalayarak askeri ittifakı taçlandır.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Türk dünyası kenetlendi; Karabağ\'ın 30 yıllık işgali 44 günlük şanlı harekatla sonlandırıldı."},{"label":"Doğu Akdeniz ve Karadeniz\'deki sismik arama ve petrol sondaj gemilerimiz (Oruç Reis, Fatih, Abdülhamid Han) için Hazine fonu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Enerjide bağımsızlık rotası çizildi; Türkiye kendi gemileriyle derin denizlerde hidrokarbon aramaya başladı."},{"label":"Mavi Vatan\'da bayrak dalgalandıran Oruç Reis\'i fırkateyn, denizaltı ve İHA\'larımızla donanma kalkanına alarak Yunan tacizlerini defet.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Donanmanın heybeti Doğu Akdeniz\'i titretti; Türk gemilerine müdahale etmek isteyenler geri çekilmek zorunda kaldı."},{"label":"Deniz yetki alanları, kıta sahanlığı ve münhasır ekonomik bölgeleri güvenceye alan \'Mavi Vatan Deniz Egemenliği Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Denizlerimizdeki egemenlik haklarımız kanunlaştı; Türkiye Akdeniz\'in vazgeçilmez lider gücü oldu."}]', 366) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
