INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_369', 'modern', 'Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi)', 'Dışişleri Bakanlığı & Milli Savunma', 'Ukrayna ve Rusya savaşırken açlık krizini önlemek için Dolmabahçe\'de 33 milyon ton tahılın sevki sağlandı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) krizinde uluslararası hukuk, ikili anlaşmalar ve egemenlik haklarımızı tavizsiz savun.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) konusunda diplomatik ve hukuki meşruiyet korundu; Türkiye\'nin haklılığı dünyaya anlatıldı."},{"label":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) sürecinde ilgili ülkeler ve müttefiklerle müzakere masası kurarak barışçıl ve uzlaşmacı diplomasi yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) geriliminde diplomatik diyalog işletildi; krizin tırmanması önlendi."},{"label":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) ile bağlantılı dış ticaret, turizm ve enerji çıkarlarımızı korumak için Hazine dengelerini tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) kaynaklı ekonomik riskler önlendi; milli ekonomi dış baskılara karşı korundu."},{"label":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) karşısında Türk Silahlı Kuvvetleri ve MİT unsurlarını teyakkuza geçirerek sahada caydırıcı güç göster.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) karşısında milli güvenlik tedbirleri uygulandı; Türkiye\'nin sahadaki ağırlığı hissettirildi."},{"label":"TBMM\'de Karadeniz Tahıl Koridoru Anlaşması (İstanbul Girişimi) konusunu milli doktrine bağlayan Stratejik Dış Politika ve Güvenlik Kanunu\'nu yürürlüğe koy.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kabul edilen yasal reform ile milli güvenlik kırmızı çizgileri kanunlaştı; egemenliğimiz korundu."}]', 369) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_370', 'modern', 'İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası', 'Dışişleri Bakanlığı & Milli Savunma', 'Terörle mücadele taahhütleri ve silah ambargolarının kalkması şartıyla iki İskandinav ülkesinin üyeliği onaylandı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"}]', '[{"label":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası krizinde uluslararası hukuk, ikili anlaşmalar ve egemenlik haklarımızı tavizsiz savun.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası konusunda diplomatik ve hukuki meşruiyet korundu; Türkiye\'nin haklılığı dünyaya anlatıldı."},{"label":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası sürecinde ilgili ülkeler ve müttefiklerle müzakere masası kurarak barışçıl ve uzlaşmacı diplomasi yürüt.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası geriliminde diplomatik diyalog işletildi; krizin tırmanması önlendi."},{"label":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası ile bağlantılı dış ticaret, turizm ve enerji çıkarlarımızı korumak için Hazine dengelerini tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası kaynaklı ekonomik riskler önlendi; milli ekonomi dış baskılara karşı korundu."},{"label":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası karşısında Türk Silahlı Kuvvetleri ve MİT unsurlarını teyakkuza geçirerek sahada caydırıcı güç göster.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası karşısında milli güvenlik tedbirleri uygulandı; Türkiye\'nin sahadaki ağırlığı hissettirildi."},{"label":"TBMM\'de İsveç ve Finlandiya\'nın NATO Üyeliği ve Madrid Muhtırası konusunu milli doktrine bağlayan Stratejik Dış Politika ve Güvenlik Kanunu\'nu yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kabul edilen yasal reform ile milli güvenlik kırmızı çizgileri kanunlaştı; egemenliğimiz korundu."}]', 370) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_371', 'modern', '17 Ağustos 1999 Gölcük Depremi (7.4) ve Asrın Felaketi', 'Kriz Masası & AFAD', 'Gece 03.02\'de meydana gelen 45 saniyelik deprem Kocaeli, Sakarya, Yalova ve İstanbul\'da 18 bin can aldı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri, fenni mesulleri ve kaçak yapılara ruhsat veren belediye yetkilileri hakkında derhal adli tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adli soruşturmalar hızla başlatıldı; Veli Göçer ve sorumsuz müteahhitler hakkında davalar açıldı."},{"label":"Bölgeye uluslararası yardım çağrısı yap; AKUT, sivil toplum örgütleri ve Kızılay ile ortaklaşa çadır kent kriz masaları kur.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma şahlandı; yüz binlerce depremzedenin acil barınma ve sıcak yemek ihtiyacı karşılandı."},{"label":"Depremin yaralarını sarmak için geçici \'Özel İletişim Vergisi\' çıkar ve Dünya Bankası afet kredisini kalıcı konutlara tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Afet bütçesi oluşturuldu; Marmara Bölgesi\'nde kalıcı deprem konutlarının inşası finanse edildi."},{"label":"1. Ordu birliklerini ve askeri istihkam taburlarını derhal enkaz sahasına sevk ederek arama-kurtarma ve sahra hastaneleri kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başlarına ulaştı; yağma ve asayişsizliğe karşı sıkı askeri güvenlik çemberi kuruldu."},{"label":"Zorunlu Deprem Sigortası\'nı (DASK) kuran ve Yapı Denetim firmalarını yetkilendiren 587 Sayılı KHK\'yı yürürlüğe koy.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve modern yapı denetim sistemi kuruldu; Türkiye\'nin deprem mevzuatında yeni bir çağ başladı."}]', 371) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_372', 'modern', 'Gölcük Donanma Komutanlığı\'nın Ağır Hasar Alması', 'Kriz Masası & AFAD', 'Deprem üssündeki tersane binaları çöktü; donanma komutanları ve Mehmetçikler enkaz altında kaldı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Afet bölgesindeki usulsüzlükler, ihmaller ve mevzuata aykırı yapılaşmalar hakkında adli soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki tahkikat başlatıldı; afet sorumluları hakkında yargı süreci işletildi."},{"label":"Afetzede vatandaşlar, mahalle muhtarları ve sivil toplumla koordinasyon kurarak acil insani yardım ulaştır.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Halkın acil ihtiyaçları karşılandı; toplumsal dayanışma ile yaralar hızla sarıldı."},{"label":"Hasar gören yerleşim yerlerinin yeniden inşası ve esnafa faizsiz can suyu kredisi için Hazine fonlarını devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali kaynaklar seferber edildi; afetin bölge ekonomisinde yol açtığı hasar sübvanse edildi."},{"label":"Arama-kurtarma ve enkaz kaldırma sahalarında yağma ve kargaşayı önlemek için jandarma ve polis devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sahada tam kamu düzeni ve asayiş sağlandı; devletin koruyucu otoritesi hissettirildi."},{"label":"Afet risklerini önceden azaltan ve yerel yönetimlerin imar denetimini sıkılaştıran \'Kentsel Dayanıklılık Kanunu\' çıkar.",