INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_376', 'modern', '12 Kasım 1999 Düzce Depremi (7.2)', 'Kriz Masası & AFAD', 'Marmara depreminin yaraları sarılmadan Düzce ve Kaynaşlı\'yı vuran ikinci sarsıntı Bolu tüneli inşaatını çökertti.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yıkılan binaların müteahhitleri, fenni mesulleri ve kaçak yapılara ruhsat veren belediye yetkilileri hakkında derhal adli tutuklama kararı çıkart.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adli soruşturmalar hızla başlatıldı; Veli Göçer ve sorumsuz müteahhitler hakkında davalar açıldı."},{"label":"Bölgeye uluslararası yardım çağrısı yap; AKUT, sivil toplum örgütleri ve Kızılay ile ortaklaşa çadır kent kriz masaları kur.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal dayanışma şahlandı; yüz binlerce depremzedenin acil barınma ve sıcak yemek ihtiyacı karşılandı."},{"label":"Depremin yaralarını sarmak için geçici \'Özel İletişim Vergisi\' çıkar ve Dünya Bankası afet kredisini kalıcı konutlara tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Afet bütçesi oluşturuldu; Marmara Bölgesi\'nde kalıcı deprem konutlarının inşası finanse edildi."},{"label":"1. Ordu birliklerini ve askeri istihkam taburlarını derhal enkaz sahasına sevk ederek arama-kurtarma ve sahra hastaneleri kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mehmetçik enkaz başlarına ulaştı; yağma ve asayişsizliğe karşı sıkı askeri güvenlik çemberi kuruldu."},{"label":"Zorunlu Deprem Sigortası\'nı (DASK) kuran ve Yapı Denetim firmalarını yetkilendiren 587 Sayılı KHK\'yı yürürlüğe koy.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"DASK ve modern yapı denetim sistemi kuruldu; Türkiye\'nin deprem mevzuatında yeni bir çağ başladı."}]', 376) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
