INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_380', 'modern', 'Van Depremi Sonrası Dondurucu Kış Şartları ve Acil Konut Güvenliği İkilemi', 'Kriz Masası & AFAD', 'Eksi 20 dereceye varan dondurucu kışta çadırlarda çıkan yangınlar ve çocuk ölümleri devleti acil kalıcı konut seferberliğine zorlarken, acele inşaatlarda zemin etütlerinin ve denetimlerin atlandığı istihbaratı geldi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"TOKİ\'yi dağ yamaçlarındaki sağlam kayalık zeminlere yönlendirip 1 yıl içinde 17 bin deprem konutunu rekor hızla inşa et.","preview":"Adalet +4, Halk +9, Otorite +7 | Hazine -8","effects":{"justice":4,"people":9,"treasury":-8,"military":0,"authority":7},"log":"Dondurucu kışta on binlerce depremzede sıcak yuvalara kavuştu; Hazine bütçesi konut seferberliğine aktarıldı."},{"label":"Tüm şantiyelerde bağımsız üniversite jeoloji heyetlerine zorunlu zemin ve beton denetimi şartı koyarak tek bir riskli binaya izin verme.","preview":"Adalet +9, Halk +6, Otorite +4 | Hazine -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":4},"log":"Zemin güvenliği tavizsiz korundu; inşaat takvimi biraz uzasa da binalar depreme tam dayanıklı yapıldı."},{"label":"Konteyner kentlere geçici olarak doğalgaz ve merkezi elektrikli ısıtma altyapısı kurarak çadır yangınlarını derhal sıfırla.","preview":"Adalet +5, Halk +8, Güvenlik +2, Otorite +5 | Hazine -5","effects":{"justice":5,"people":8,"treasury":-5,"military":2,"authority":5},"log":"Çadır yangınları tamamen durduruldu; konteyner kentlerde can güvenliği sağlandı."},{"label":"Bölgede fahiş kira isteyen fırsatçılara ve yardım malzemesi kaçakçılarına karşı olağanüstü hal zabıta timleri kur.","preview":"Adalet +7, Halk +5, Hazine +2, Güvenlik +3, Otorite +8","effects":{"justice":7,"people":5,"treasury":2,"military":3,"authority":8},"log":"Deprem fırsatçılığına ve stokçuluğa sert darbe vuruldu; kamu düzeni sağlandı."},{"label":"Depremzede ailelere doğrudan kira yardımı ve faizsiz taşınma kredisi vererek isteyenlerin batı illerinde kamu misafirhanelerine yerleşmesini sağla.","preview":"Adalet +6, Halk +8, Otorite +5 | Hazine -6","effects":{"justice":6,"people":8,"treasury":-6,"military":0,"authority":5},"log":"Sosyal tahliye planıyla dondurucu kış şartlarındaki binlerce aile sıcak bölgelere nakledildi."}]', 380) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_381', 'modern', '24 Ocak 2020 Elazığ Sivrice Depremi (6.8)', 'Kriz Masası & AFAD', 'Elazığ ve Malatya\'da 41 kişinin vefat ettiği deprem sonrası kış ortasında hızlı çadır ve konteyner desteği sağlandı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Afet bölgesindeki usulsüzlükler, ihmaller ve mevzuata aykırı yapılaşmalar hakkında adli soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki tahkikat başlatıldı; afet sorumluları hakkında yargı süreci işletildi."},{"label":"Afetzede vatandaşlar, mahalle muhtarları ve sivil toplumla koordinasyon kurarak acil insani yardım ulaştır.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Halkın acil ihtiyaçları karşılandı; toplumsal dayanışma ile yaralar hızla sarıldı."},{"label":"Hasar gören yerleşim yerlerinin yeniden inşası ve esnafa faizsiz can suyu kredisi için Hazine fonlarını devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali kaynaklar seferber edildi; afetin bölge ekonomisinde yol açtığı hasar sübvanse edildi."},{"label":"Arama-kurtarma ve enkaz kaldırma sahalarında yağma ve kargaşayı önlemek için jandarma ve polis devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sahada tam kamu düzeni ve asayiş sağlandı; devletin koruyucu otoritesi hissettirildi."},{"label":"Afet risklerini önceden azaltan ve yerel yönetimlerin imar denetimini sıkılaştıran \'Kentsel Dayanıklılık Kanun