INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_388', 'modern', 'Orman Yangınları Sonrası Köy Evleri Yapım Hamlesi', 'Kriz Masası & AFAD', 'Yangında evlerini kaybeden köylülere yöresel mimariye uygun tek katlı müstakil afet konutları yapıldı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Yangınların kundaklama veya sabotaj sonucu çıkıp çıkmadığını MİT ve Jandarma Kriminal laboratuvarlarıyla çok yönlü soruştur.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Sabotaj iddiaları titizlikle incelendi; ihmali ve kastı bulunan şüpheliler adliyeye sevk edildi."},{"label":"Köyleri ve ahırları yanan afetzedelere Cumhurbaşkanlığı Acil Destek Fonu\'ndan nakit hibe verip canlı hayvan desteği sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Köylülerin feryadı dindirildi; yerinde köy evleri ve ahırlar inşa edilerek üreticiler ayağa kaldırıldı."},{"label":"Gelecek yılların yangın riskini önlemek için Savunma Sanayii Başkanlığı koordinasyonunda dev amfibik yangın söndürme uçağı filosu satın al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli yangın söndürme filosu kuruldu; THK uçakları ve modern amfibik uçaklar envantere alındı."},{"label":"Alevlerin Kemerköy Termik Santrali\'ne sıçramasını önlemek için santral çevresine iş makineleriyle hendek kazıp jandarma kordonu kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Termik santral faciası son anda önlendi; stratejik enerji tesisleri yangından korundu."},{"label"