INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_392', 'modern', '2021 Marmara Denizi Müsilaj (Deniz Salyası) Krizi', 'Kriz Masası & AFAD', 'Deniz suyu sıcaklığı ve atık kirliliği sebebiyle Marmara\'yı saran tabaka balıkçılığı ve turizmi felç etti.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Marmara Denizi\'ne arıtmasız zehirli atık ve kimyasal deşarj eden fabrikaları Çevre Müfettişleri marifetiyle kapatıp savcılığa sevk et.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Korsan deşarj yapan organize sanayi tesislerine kapatma ve en üst baremden rekor çevre cezaları kesildi."},{"label":"Marmara Belediyeler Birliği, balıkçı kooperatifleri ve bilim insanlarıyla \'Marmara Denizi Eylem Planı\' seferberliği ilan et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal dayanışma sağlandı; deniz süpürgeleriyle yüzeyden binlerce metreküp salya temizlendi."},{"label":"Havzadaki tüm belediyelerin biyolojik ve ileri arıtma tesislerine geçişi için İller Bankası üzerinden düşük faizli kredi fonu aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Arıtma altyapısı hızla finanse edildi; Marmara\'ya tek damla arıtmasız su akmaması için tesis yatırımları başladı."},{"label":"Sahil Güvenlik Komutanlığı botlarına gece deniz kirliliği teftişi ve sintine boşaltan gemilere anında el koyma yetkisi ver.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Boğaz ve körfezde 7/24 deniz gözetimi kuruldu; gemilerin kaçak atık basması engellendi."},{"label":"Marmara Denizi\'nin tamamını \'Özel Çevre Koruma Bölgesi\' ilan eden tarihi koruma kanununu kabul et.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Marmara Denizi kanunen koruma kalkanına alındı; oksijen seviyeleri yeniden yükselmeye başladı."}]', 392) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_393', 'modern', 'Marmara Denizi Eylem Planı ve Oksijenlendirme Operasyonu', 'Kriz Masası & AFAD', 'Çevre Bakanlığı 22 maddelik eylem planı açıklayarak 81 gemiyle deniz yüzeyindeki salyayı topladı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Afet bölgesindeki usulsüzlükler, ihmaller ve mevzuata aykırı yapılaşmalar hakkında adli soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki tahkikat başlatıldı; afet sorumluları hakkında yargı süreci işletildi."},{"label":"Afetzede vatandaşlar, mahalle muhtarları ve sivil toplumla koordinasyon kurarak acil insani yardım ulaştır.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkın acil ihtiyaçları karşılandı; toplumsal dayanışma ile yaralar hızla sarıldı."},{"label":"Hasar gören yerleşim yerlerinin yeniden inşası ve esnafa faizsiz can suyu kredisi için Hazine fonlarını devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali kaynaklar seferber edildi; afetin bölge ekonomisinde yol açtığı hasar sübvanse edildi."},{"label":"Arama-kurtarma ve enkaz kaldırma sahalarında yağma ve kargaşayı önlemek için jandarma ve polis devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sahada tam kamu düzeni ve asayiş sağlandı; devletin koruyucu otoritesi hissettirildi."},{"label":"Afet risklerini önceden azaltan ve yerel yönetimlerin imar denetimini sıkılaştıran \'Kentsel Dayanıklılık Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Afet yönetimi modern yasal standartlara kavuşturuldu; benzer felaketlerin önlenmesi için zemin hazırlandı."}]', 393) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_394', 'modern', 'Marmara Denizi\'nin Özel Çevre Koruma Bölgesi İlan Edilmesi', 'Kriz Masası & AFAD', 'Marmara havzasındaki tüm organize sanayi bölgelerine ileri biyolojik arıtma tesisi zorunluluğu getirildi.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Afet bölgesindeki usulsüzlükler, ihmaller ve mevzuata aykırı yapılaşmalar hakkında adli soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki tahkikat başlatıldı; afet sorumluları hakkında yargı süreci işletildi."},{"label":"Afetzede vatandaşlar, mahalle muhtarları ve sivil toplumla koordinasyon kurarak acil insani yardım ulaştır.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Halkın acil ihtiyaçları karşılandı; toplumsal dayanışma ile yaralar hızla sarıldı."},{"label":"Hasar gören yerleşim yerlerinin yeniden inşası ve esnafa faizsiz can suyu kredisi için Hazine fonlarını devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali kaynaklar seferber edildi; afetin bölge ekonomisinde yol açtığı hasar sübvanse edildi."},{"label":"Arama-kurtarma ve enkaz kaldırma sahalarında yağma ve kargaşayı önlemek için jandarma ve polis devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sahada tam kamu düzeni ve asayiş sağlandı; devletin koruyucu otoritesi hissettirildi."},{"label":"Afet risklerini önceden azaltan ve yerel yönetimlerin imar denetimini sıkılaştıran \'Kentsel Dayanıklılık