INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_395', 'modern', 'Erzincan İliç Altın Madeni Liç Yığını Kayması (2024)', 'Kriz Masası & AFAD', 'Çöpler Altın Madeni\'nde siyanürlü liç tepesinin çökmesiyle 9 maden işçisi tonlarca toprağın altında kaldı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Maden sahasındaki liç kayması ve siyanürlü toprak kayması faciasında şirketin yabancı ve yerli yöneticilerini derhal tutuklat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Adli tahkikat başlatıldı; altın madeni şirketi yetkilileri ve fenni denetimciler cezaevine gönderildi."},{"label":"Toprak altında kalan 9 madencinin aileleriyle kriz merkezinde buluş; Fırat Nehri\'ne siyanür sızmasını önleyecek tedbirleri açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Bölge halkı bilgilendirildi; menfez kapakları kapatılarak Fırat Nehri\'ne kimyasal sızıntı sıfırlandı."},{"label":"Şirketin tüm maden işletme ruhsatlarını iptal et; çevre rehabilitasyonu ve işçi tazminatları için şirket hesaplarına el koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şirketin teminat mektupları nakde çevrildi; çevre temizliği masrafları kirleten şirketten tahsil edildi."},{"label":"Bölgeye AFAD, JAK ve TSK KBRN (Kimyasal, Biyolojik, Radyasyon, Nükleer) timlerini sevk ederek güvenlik kordonu kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Liç yığını çevresi izole edildi; gaz ölçümleri ve toprak analizleri kesintisiz takip edildi."},{"label":"Açık liç yöntemiyle siyanürlü madenciliği katı çevre sınırlarına ve ağır teminatlara bağlayan \'Maden Güvenliği Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Vahşi madencilik devri kapandı; çevre ve işçi can güvenliğini önceleyen yasal rejim kuruldu."}]', 395) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
