INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_399', 'modern', 'Akbelen Ormanı Linyit Madeni Direnişi ve İkizköy Nöbeti', 'Kriz Masası & AFAD', 'Muğla\'da termik santrale kömür sağlamak için kesilmek istenen çam ağaçları için köylüler jandarmayla karşı karşıya geldi.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Maden sahasındaki liç kayması ve siyanürlü toprak kayması faciasında şirketin yabancı ve yerli yöneticilerini derhal tutuklat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Adli tahkikat başlatıldı; altın madeni şirketi yetkilileri ve fenni denetimciler cezaevine gönderildi."},{"label":"Toprak altında kalan 9 madencinin aileleriyle kriz merkezinde buluş; Fırat Nehri\'ne siyanür sızmasını önleyecek tedbirleri açıkla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Bölge halkı bilgilendirildi; menfez kapakları kapatılarak Fırat Nehri\'ne kimyasal sızıntı sıfırlandı."},{"label":"Şirketin tüm maden işletme ruhsatlarını iptal et; çevre rehabilitasyonu ve işçi tazminatları için şirket hesaplarına el koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şirketin teminat mektupları nakde çevrildi; çevre temizliği masrafları kirleten şirketten tahsil edildi."},{"label":"Bölgeye AFAD, JAK ve TSK KBRN (Kimyasal, Biyolojik, Radyasyon, Nükleer) timlerini sevk ederek güvenlik kordonu kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Liç yığını çevresi izole edildi; gaz ölçümleri ve toprak analizleri kesintisiz takip edildi."},{"label":"Açık liç yöntemiyle siyanürlü madenciliği katı çevre sınırlarına ve ağır teminatlara bağlayan \'Maden Güvenliği Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Vahşi madencilik devri kapandı; çevre ve işçi can güvenliğini önceleyen yasal rejim kuruldu."}]', 399) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_400', 'modern', 'Salda Gölü Koruma Alanı ve Beyaz Kumulların Kurtarılması', 'Kriz Masası & AFAD', 'Türkiye\'nin Maldivleri olarak bilinen gölün beyaz kumullarına araç girişi ve ayakkabıyla basılması yasaklandı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Afet bölgesindeki usulsüzlükler, ihmaller ve mevzuata aykırı yapılaşmalar hakkında adli soruşturma açtır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki tahkikat başlatıldı; afet sorumluları hakkında yargı süreci işletildi."},{"label":"Afetzede vatandaşlar, mahalle muhtarları ve sivil toplumla koordinasyon kurarak acil insani yardım ulaştır.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Halkın acil ihtiyaçları karşılandı; toplumsal dayanışma ile yaralar hızla sarıldı."},{"label":"Hasar gören yerleşim yerlerinin yeniden inşası ve esnafa faizsiz can suyu kredisi için Hazine fonlarını devreye sok.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mali kaynaklar seferber edildi; afetin bölge ekonomisinde yol açtığı hasar sübvanse edildi."},{"label":"Arama-kurtarma ve enkaz kaldırma sahalarında yağma ve kargaşayı önlemek için jandarma ve polis devriyelerini artır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sahada tam kamu düzeni ve asayiş sağlandı; devletin koruyucu otoritesi hissettirildi."},{"label":"Afet risklerini önceden azaltan ve yerel yönetimlerin imar denetimini sıkılaştıran \'Kentsel Dayanıklılık Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Afet yönetimi modern yasal standartlara kavuşturuldu; benzer felaketlerin önlenmesi için zemin hazırlandı."}]', 400) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_401', 'modern', 'Pazarcık Depremi (7.7) ve 11 İlde İlk Yıkım', 'AFAD & Kriz Masası', '04.17\'de Kahramanmaraş Pazarcık merkezli ilk sarsıntı 11 ilde on binlerce binayı saniyeler içinde yıktı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Asrın Felaketi karşısında anayasal yetkileri kullanarak 11 ilde 3 ay süreyle \'Olağanüstü Hal (OHAL)\' ilan et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"OHAL rejimi devreye alındı; yağma, stokçuluk ve fahiş fiyat artışlarına karşı olağanüstü adli tedbirler yürürlüğe girdi."},{"label":"Uluslararası topluma 4. Seviye Acil Çağrı yap; 90 ülkeden gelen arama-kurtarma ekiplerini havalimanlarında AFAD ile koordine et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Dünya Türkiye için seferber oldu; on binlerce yabancı ve yerli kurtarma görevlisi enkazlardan can kurtardı."},{"label":"Milli Dayanışma Kampanyası (\'Türkiye Tek Yürek\') ile toplanan 115 milyar TL\'yi doğrudan AFAD barınma ve konteyner bütçesine bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi kaynak toplandı; yüz binlerce konteyner kentin altyapısı Hazineye yük olmadan kuruldu."},{"label":"2. Ordu komando tugaylarını, jandarma asayiş birliklerini ve polis özel harekatı 11 ilin cadde ve sokaklarında devriyeye çıkar.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Mehmetçik sokaklara indi; yağma ve asayişsizlik dedikoduları bıçak gibi kesilerek tam kamu düzeni kuruldu."},{"label":"Deprem bölgesinde yıkılan şehirlerin yerinde ve rezerv alanlarda inşasını hızlandıran \'Afet Yeniden İmar Fonu Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Afet fonu kuruldu; 11 ilin şehir merkezlerinin yeniden imarı için yasal bürokrasi sıfırlandı."}]', 401) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
