INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_406', 'modern', 'Rönesans Rezidans Yıkımı ve Müteahhidin Kaçışı', 'AFAD & Kriz Masası', '\'Cennetten bir köşe\' vaadiyle satılan rezidansın müteahhidi havalimanında kaçarken yakalanıp tutuklandı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Kolon kesen dükkan sahipleri, statik projeyi değiştiren müteahhitler ve imar affı verenler hakkında \'olası kastla öldürme\'den tutuklama çıkar.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Adalet arayışı tavizsiz işletildi; yüzlerce masumun canına mal olan müteahhit ve fenni mesuller adliyeye sevk edildi."},{"label":"KKTC sporcu kafilesi ve deprem şehitlerinin aileleriyle Adalet Bakanlığı\'nda düzenli duruşma koordinasyon masası kur.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Mağdur ailelere devlet sahip çıktı; davanın unutturulması ve delillerin karartılması engellendi."},{"label":"Kaçmaya çalışan şüphelilerin havalimanlarında yakalanması ve banka hesapları ile şirket varlıklarına MASAK aracılığıyla tedbir koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şüphelilerin mal kaçırması önlendi; mağdur aileler için haciz ve tazminat fonu oluşturuldu."},{"label":"Enkaz kaldırma sürecinde bilirkişiler karot numunesi almadan hiçbir molozun taşınmaması için savcılık nöbeti kurdur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Deliller enkaz başında güvenliğe alındı; hukuki hesap sorma sürecinin delilsiz kalması önlendi."},{"label":"İmar affı ve barışı uygulamalarını anayasal suç kapsamına alan ve yapı denetimini devlet tekeline veren \'Fay Yasası\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'de kaçak yapı affı defteri ebediyen kapatıldı; fenni mesuliyet en katı cezalara bağlandı."}]', 406) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
