INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_422', 'modern', 'Gaziantep Nurdağı ve İslahiye İlçelerinin Sıfırdan İnşası', 'AFAD & Kriz Masası', 'Fay hattı üzerindeki yerleşim yerleri güvenli dağ eteklerine kaydırılarak yeni şehirler kuruldu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Deprem bölgesindeki kamu hizmetlerini, adli teftişi ve zarar tespit davalarını şeffafça yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adli ve idari süreçler işletildi; depremzedelerin hak kayıpları önlendi."},{"label":"Afet bölgesindeki sivil toplum, yerel esnaf ve vatandaşlarla kriz masasında buluşarak dayanışmayı güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkla el ele verildi; bölgede hayatın normale dönmesi için toplumsal mutabakat sağlandı."},{"label":"Deprem illerindeki esnaf ve çiftçiye vergi terki, SGK muafiyeti ve hibe kredileri Hazinece tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bölge ekonomisi canlandırıldı; vergi muafiyetleriyle üreticilerin iflas etmesi önlendi."},{"label":"Konteyner kentler ve lojistik depolarda emniyet ve jandarma nöbetlerini 24 saat kesintisiz sürdür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Huzur ve asayiş temin edildi; geçici barınma alanlarında vatandaşın can ve mal güvenliği korundu."},{"label":"TBMM\'de deprem bölgesinin kalkınmasını 10 yıl süresince güvenceye alan \'Deprem İlleri İmar ve Teşvik Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik