INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_424', 'modern', 'Deprem Bölgesi Rezerv Alan Yasası Düzenlemesi', 'AFAD & Kriz Masası', 'Şehir merkezlerinin planlı ve sağlam dönüştürülmesi için rezerv yapı alanı yetkileri genişletildi.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Kalıcı konut kura çekilişlerini noter huzurunda ve canlı yayında şeffafça yaparak hak sahipliği itirazlarını adilce sonuçlandır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kura çekimi şeffaflıkla yapıldı; hiçbir şaibeye yer bırakılmadan evler hak sahiplerine teslim edildi."},{"label":"Konteyner kentlerde yaşayan yüz binlerce aileye kalıcı evleri teslim edilene kadar kira ve taşınma yardımlarını kesintisiz sürdür.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Halkın barınma güvencesi korundu; depremzedelerin yalnız bırakılmadığı devlet şefkatiyle gösterildi."},{"label":"46 bin konutun inşa edildiği tünel kalıp şantiyelerine Hazine bütçesinden hak ediş ödemelerini aksatmadan aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İnşaatlar gece gündüz sürdürüldü; 1 yılda yüz bin konutun tamamlanması için nakit akışı korundu."},{"label":"Fay hatları üzerinde yapılaşmaya kesinlikle izin verme; şehir merkezlerini sağlam zeminli dağ eteklerine kaydır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Bilimsel zemin etütlerine uyuldu; yeni şehirler radye temel ve tünel kalıp ile kaya zeminlere kuruldu."},{"label":"Şehir merkezlerinin tarihi ve kültürel dokusunu koruyarak ayağa kaldıran \'Kentsel Dönüşüm ve Rezerv Alan Kanunu\'nu çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Yasal engeller kaldırıldı; Antakya, Maraş ve Malatya meydanları devlet eliyle baştan inşa edilmeye başlandı."}]', 424) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
