INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_427', 'modern', 'Deprem Bölgesi Kardeş Şehir ve Belediye Dayanışması', 'AFAD & Kriz Masası', 'Türkiye\'nin tüm büyükşehir ve ilçe belediyeleri deprem illerine aşevi, su ve temizlik üsleri kurdu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Deprem bölgesindeki kamu hizmetlerini, adli teftişi ve zarar tespit davalarını şeffafça yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adli ve idari süreçler işletildi; depremzedelerin hak kayıpları önlendi."},{"label":"Afet bölgesindeki sivil toplum, yerel esnaf ve vatandaşlarla kriz masasında buluşarak dayanışmayı güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkla el ele verildi; bölgede hayatın normale dönmesi için toplumsal mutabakat sağlandı."},{"label":"Deprem illerindeki esnaf ve çiftçiye vergi terki, SGK muafiyeti ve hibe kredileri Hazinece tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bölge ekonomisi canlandırıldı; vergi muafiyetleriyle üreticilerin iflas etmesi önlendi."},{"label":"Konteyner kentler ve lojistik depolarda emniyet ve jandarma nöbetlerini 24 saat kesintisiz sürdür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Huzur ve asayiş temin edildi; geçici barınma alanlarında vatandaşın can ve mal güvenliği korundu."},{"label":"TBMM\'de deprem bölgesinin kalkınmasını 10 yıl süresince güvenceye alan \'Deprem İlleri İmar ve Teşvik Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Bölgeye kalıcı ekonomik ve hukuki teşvik sağlandı; tersine göç için zemin hazırlandı."}]', 427) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_428', 'modern', 'Deprem Davaları: Soruşturulan 1500 Müteahhit ve Mühendis', 'AFAD & Kriz Masası', 'Adalet Bakanlığı kurduğu özel Deprem Suçları Soruşturma Bürolarıyla yüzlerce sorumluyu cezaevine koydu.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Kolon kesen dükkan sahipleri, statik projeyi değiştiren müteahhitler ve imar affı verenler hakkında \'olası kastla öldürme\'den tutuklama çıkar.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adalet arayışı tavizsiz işletildi; yüzlerce masumun canına mal olan müteahhit ve fenni mesuller adliyeye sevk edildi."},{"label":"KKTC sporcu kafilesi ve deprem şehitlerinin aileleriyle Adalet Bakanlığı\'nda düzenli duruşma koordinasyon masası kur.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Mağdur ailelere devlet sahip çıktı; davanın unutturulması ve delillerin karartılması engellendi."},{"label":"Kaçmaya çalışan şüphelilerin havalimanlarında yakalanması ve banka hesapları ile şirket varlıklarına MASAK aracılığıyla tedbir koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Şüphelilerin mal kaçırması önlendi; mağdur aileler için haciz ve tazminat fonu oluşturuldu."},{"label":"Enkaz kaldırma sürecinde bilirkişiler karot numunesi almadan hiçbir molozun taşınmaması için savcılık nöbeti kurdur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Deliller enkaz başında güvenliğe alındı; hukuki hesap sorma sürecinin delilsiz kalması önlendi."},{"label":"İmar affı ve barışı uygulamalarını anayasal suç kapsamına alan ve yapı denetimini devlet tekeline veren \'Fay Yasası\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye\'de kaçak yapı affı defteri ebediyen kapatıldı; fenni mesuliyet en katı cezalara bağlandı."}]', 428) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_429', 'modern', '6 Şubat Depremzedeleri Rezerv Alan İhtilafı ve Hızlı Mülkiyet Tahsisi', 'AFAD & Kriz Masası', 'Yüz binlerce kalıcı konutun hak sahiplerine teslimi öncesinde, şehir merkezlerindeki rezerv alan ilanlarının mülkiyet gasbı olduğu iddiaları muhalefet ve mülk sahipleri tarafından yargıya taşındı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Rezerv alan ilan edilen yerlerde vatandaşın tapulu yerinde aynı metrekarede yeni dairesini garanti eden kanuni güvence kararnamesi çıkar.","preview":"Adalet +9, Halk +8, Otorite +6 | Hazine -5","effects":{"justice":9,"people":8,"treasury":-5,"military":0,"authority":6},"log":"Mülkiyet tartışmaları ve yargı iptal riski giderildi; vatandaş devletine güvenle anahtarını teslim aldı."},{"label":"Kura çekilişlerini noter huzurunda ve tüm televizyonlarda canlı yayınlayarak şeffaflığı tartışmasız tescil et.","preview":"Adalet +7, Halk +8, Otorite +7 | Hazine -1","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Kura şaibesi dedikoduları canlı yayın şeffaflığıyla anında çöktü."},{"label":"Kalıcı konut hakkından feragat edip kendi arazisinde yerinde dönüşüm yapmak isteyenlere karşılıksız 750 bin TL hibe ve kredi ver.","preview":"Adalet +8, Halk +8, Otorite +5 | Hazine -8","effects":{"justice":8,"people":8,"treasury":-8,"military":0,"authority":5},"log":"Yerinde dönüşüm seferberliğiyle şehirlerin tarihi dokusu korundu."},{"label":"Rezerv alanlara karşı provokatif dezenformasyon yayan sosyal medya hesaplarına adli soruşturma açtırarak süreci hızlandır.","preview":"Adalet +4, Hazine +1, Güvenlik +2, Otorite +8 | Halk -2","effects":{"justice":4,"people":-2,"treasury":1,"military":2,"authority":8},"log":"İnşaat takvimi aksatılmadan korundu; ancak muhalefetle gerginlik tırmandı."},{"label":"Yeni konut teslim alan tüm ailelere ilk 2 yıl faizsiz ve geri ödemesiz taşınma ve eşya desteği sağla.","preview":"Adalet +6, Halk +9, Otorite +5 | Hazine -6","effects":{"justice":6,"people":9,"treasury":-6,"military":0,"authority":5},"log":"Depremzedelerin ekonomik yükü hafifletildi; sosyal devlet anlayışı takdir topladı."}]', 429) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_430', 'modern', '11 İlin İmar Planı ve Yeni Fay Yasası Hazırlıkları', 'AFAD & Kriz Masası', 'Fay hatlarının üzerine bina yapılmasını kesin olarak yasaklayan imar mevzuatı meclis gündemine taşındı.', '[{"id":"char_afad_baskani","name":"AFAD / Kriz Masası Başkanı"},{"id":"char_cevre_sehircilik_bakani","name":"Çevre ve Şehircilik Bakanı"}]', '[{"label":"Deprem bölgesindeki kamu hizmetlerini, adli teftişi ve zarar tespit davalarını şeffafça yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Adli ve idari süreçler işletildi; depremzedelerin hak kayıpları önlendi."},{"label":"Afet bölgesindeki sivil toplum, yerel esnaf ve vatandaşlarla kriz masasında buluşarak dayanışmayı güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkla el ele verildi; bölgede hayatın normale dönmesi için toplumsal mutabakat sağlandı."},{"label":"Deprem illerindeki esnaf ve çiftçiye vergi terki, SGK muafiyeti ve hibe kredileri Hazinece tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bölge ekonomisi canlandırıldı; vergi muafiyetleriyle üreticilerin iflas etmesi önlendi."},{"label":"Konteyner kentler ve lojistik depolarda emniyet ve jandarma nöbetlerini 24 saat kesintisiz sürdür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Huzur ve asayiş temin edildi; geçici barınma alanlarında vatandaşın can ve mal güvenliği korundu."},{"label":"TBMM\'de deprem bölgesinin kalkınmasını 10 yıl süresince güvenceye alan \'Deprem İlleri İmar ve Teşvik Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Bölgeye kalıcı ekonomik ve hukuki teşvik sağlandı; tersine göç için zemin hazırlandı."}]', 430) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_431', 'modern', 'İstanbul Boğazı Demiryolu Tıkanması ve Marmaray Tüp Geçiş İkilemi', 'Ulaştırma Bakanlığı', 'Avrupa ile Asya arasındaki yük ve banliyö hatları kilitlendi; her gün milyonlarca yolcu feribot ve köprü trafiğinde sıkışıyor. Japon JICA ve Avrupa fonları Boğaz tüp geçişi için Hazine garantisi ve uluslararası teknik denetim şartı koşuyor. İstihbarat, deniz tabanındaki fay hatları ve siber sabotaj risklerine dikkat çekiyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"JICA ve mühendislik konsorsiyumuyla bağımsız teknik teftiş altında Marmaray tüp geçiş projesini derhal başlat.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Marmaray inşaatı başladı; iki kıta deniz tabanından birleştirilerek asrın raylı sistemi devreye alındı."},{"label":"Denizcilik işletmeleri ve şehir hatlarıyla meşveret et; deniz otobüsü ve arabalı vapur filolarını sübvanse ederek tüp geçişi ertele.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Deniz taşımacılığı takviye edildi; ancak boğaz trafiğinde uzun vadeli rahatlama sağlanamadı."},{"label":"Projeyi dış borç yerine Hazine garantili kamu-özel ortaklığıyla finanse et; bütçe açığını frenleyerek inşaat takvimini hızlandır.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Finansman modeli kuruldu; Hazine nakit çıkışı yapmadan küresel fonlar yatırıma çekildi."},{"label":"Boğaz tabanına döşenecek batırma tüplerin çevresine gizli denizaltı tespit sonarları ve sismik izleme sensörleri yerleştir.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Stratejik tüp geçiş askeri koruma altına alındı; yabancı denizaltıların boğaz sızıntıları kontrol altına alındı."},{"label":"Kıtalararası demiryolu koridorlarını milli stratejik güvenlik alanı ilan eden \'Boğaz Raylı Altyapı Koruma Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Marmaray yasal güvenceye bağlandı; projenin işletme ve güvenlik standartları kanunlaştı."}]', 431) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_432', 'modern', 'Yenikapı Marmaray Kazısında Theodosius Limanı Buluntuları ve Gecikme Krizi', 'Ulaştırma Bakanlığı', 'Marmaray Yenikapı istasyon kazılarında 37 Bizans batığı, neolitik mezarlar ve paha biçilmez tarihi liman ortaya çıktı. Arkeologlar kazının yıllarca sürmesini talep ederken, müteahhitler her gecikme günü için devasa tazminat faturası çıkarıyor; şehir trafiği felç olmuş durumda.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Kültür Varlıklarını Koruma Kurulu ve üniversitelerin bilimsel heyetine tam yetki ver; tarihi batıklar tek tek çıkarılana kadar inşaatı beklet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Dünya arkeoloji tarihinin en büyük batık koleksiyonu kurtarıldı; ancak proje 5 yıl gecikerek maliyeti katlandı."},{"label":"Ulaştırma bürokrasisi ve arkeologlar arasında uzlaşı sağla; istasyon planını revize ederek arkeopark ve müze istasyon formülü uygula.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Tarih ile modern ulaşım buluştu; Yenikapı İstasyonu dünyanın en zengin açık hava müze istasyonuna dönüştü."},{"label":"Müteahhit konsorsiyumunun gecikme cezası taleplerini Hazine avukatlarıyla tahkime taşı; kamu bütçesini haksız tazminattan koru.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine tazminat yükünden kurtarıldı; konsorsiyumla ek süre üzerinde mali uzlaşmaya varıldı."},{"label":"Tarihi kazı alanında kaçakçılık ve yağma riskine karşı emniyet ve müzeler müdürlüğüyle özel güvenlik kordonu kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Paha biçilmez Bizans sikkeleri ve neolitik eserlerin karaborsaya düşmesi engellendi."},{"label":"Mega altyapı projelerinde tarihi miras çıktığında işletilecek prosedürleri tanzim eden \'Tarihi Miras ve Altyapı Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Yasal çerçeve netleşti; gelecekteki metro projelerinde arkeolojik buluntuların yönetimi kurala bağlandı."}]', 432) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_433', 'modern', 'Tarihi Yarımada Araç Kilitlenmesi ve Avrasya Karayolu Tüp Tüneli Kararı', 'Ulaştırma Bakanlığı', 'İstanbul Boğazı üzerindeki iki asma köprüde trafik durma noktasına geldi; acil ambulans, itfaiye ve protokol geçişleri saatlerce aksıyor. Denizaltından iki katlı lastik tekerlekli karayolu tüneli projesi masada; ancak fay hattı sarsıntıları ve yangın/güvenlik riskleri yoğun tartışılıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Deprem uzmanları ve uluslararası tünelcilik birliğinin en katı güvenlik standartlarını şart koşarak Avrasya Tüneli ihalesini aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"7.5 büyüklüğünde depreme dayanıklı çift katlı tünel projesi bağımsız denetim onayından geçti."},{"label":"Tarihi Yarımada esnafı ve sivil toplumla istişare et; tünel giriş ve çıkışlarındaki tarihi dokuyu koruyacak güzergah revizyonu yap.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Çatladıkapı ve Yenikapı sahil şeridinde tarihi silüet korundu; kamuoyu desteği sağlandı."},{"label":"Yap-İşlet-Devret modeliyle projeyi ihale et; geçiş ücretini dövize endeksleyip Hazineye nakit harcatmadan tüneli tamamlat.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Avrasya Tüneli rekor sürede inşa edildi; ancak kur yükselişlerinde Hazine geçiş farkı ödemek durumunda kaldı."},{"label":"Tünel içinde akıllı yangın söndürme, sığınma cepleri ve 24 saat zırhlı eskort noktalarıyla terör sabotaj kalkanı kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Dünyanın en derin denizaltı karayolu tüneli askeri ve sivil acil durum protokolleriyle tahkim edildi."},{"label":"Denizaltı karayolu tünellerinin işletme ve güvenlik rejimini düzenleyen \'Kritik Karayolu Tünelleri Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Tünel işletmesi yasal çerçeveye kavuştu; Avrupa ile Asya arası araç geçişi 5 dakikaya indi."}]', 433) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_434', 'modern', 'Kuzey Marmara Transit Koridoru ve 3. Boğaz Köprüsü Güzergah Krizi', 'Ulaştırma Bakanlığı', 'Fatih Sultan Mehmet Köprüsü ağır tonajlı transit tırların yoğunluğu altında eziliyor; şehir içi trafik her gün kilitleniyor. Boğaz\'ın kuzeyine 3. bir asma köprü yapılması planlanıyor; ancak güzergahın su havzaları ve orman arazilerinden geçmesi sert çevreci itirazlara yol açıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Sayıştay ve bağımsız çevre denetçilerini görevlendir; kesilen her ağaç yerine beş katı fidan dikme taahhüdüyle Yavuz Sultan Selim Köprüsü\'nü başlat.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"YSS Köprüsü inşaatına başlandı; güzergah üzerindeki su havzaları koruma taahhüdüyle denetlendi."},{"label":"Şehir plancıları ve çevre örgütleriyle çalıştay topla; tırları Ro-Ro deniz hatlarına yönlendirerek 3. köprüyü askıya al.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Deniz taşımacılığı denendi; fakat karayolu transit tır akışının yarattığı şehir içi tıkanıklık aşılamadı."},{"label":"Köprü ve Kuzey Marmara Otoyolu\'nu YİD modeliyle konsorsiyuma devret; transit ağır vasıtaların geçişini zorunlu kılarak bütçeye gelir sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"İstanbul içi tır trafiğinden kurtuldu; YSS Köprüsü 59 metrelik genişliğiyle ağır vasıtaları şehir dışına taşıdı."},{"label":"Köprü kulelerine ve viyadüklere askeri hava radar ve uçaksavar koruma bataryaları konuşlandırarak stratejik geçişi koru.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Üçüncü Boğaz Köprüsü sabotaj ve terör saldırılarına karşı en üst seviye güvenlik kalkanıyla donatıldı."},{"label":"Kuzey ormanlarını ve su havzalarını imara kapatan \'Kuzey Marmara Koruma ve Transit Lojistik Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Otoyol çevresinde kaçak yapılaşma kanunla yasaklandı; sadece transit lojistik koridoru işletildi."}]', 434) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_435', 'modern', 'İzmit Körfezi Sanayi Kilitlenmesi ve Osmangazi Asma Köprüsü İhalesi', 'Ulaştırma Bakanlığı', 'Kocaeli ile Yalova arasındaki feribot iskelelerinde araç kuyrukları kilometreleri buluyor; Marmara sanayisi saatte milyonlarca dolar lojistik kaybı yaşıyor. İzmit Körfezi\'ni 4 dakikada geçirecek dev asma köprü projesi hazırlandı; ancak deprem fayı üzerinde olması ve yüksek Hazine garantisi riski var.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Kuzey Anadolu Fayı\'nın zemin etütlerini bağımsız Japon sismoloji enstitüsüne incelet; onay verilirse Osmangazi Köprüsü\'nü inşa et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"En ileri deprem yalıtım teknolojisiyle dünyanın dördüncü en uzun asma köprüsü inşaatına başlandı."},{"label":"Marmara sanayi odaları ve nakliyeciler kooperatifiyle masaya otur; feribot kapasitesini üç katına çıkarıp köprüyü ertele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Feribot filosu artırıldı; fakat bayram ve tatil yoğunluklarında körfez çilesi tam olarak çözülemedi."},{"label":"İstanbul-İzmir otoyoluyla entegre YİD ihalesi aç; köprü geçiş süresini 4 dakikaya indirerek Ege turizm ve ticaretini şahlandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Osmangazi Köprüsü tamamlandı; İstanbul-İzmir seyahati 8 saatten 3.5 saate inerek milli lojistik devrimi yapıldı."},{"label":"Körfez geçiş kulelerine ve otoyol viyadüklerine sabotaj erken uyarı sensörleri ve deniz devriye botları yerleştir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Körfez geçiş koridoru terör ve sabotaj tehditlerine karşı 24 saat kesintisiz koruma çemberine alındı."},{"label":"Kamu-özel ortaklığı projelerinde Hazine garanti risklerini sınırlayan \'Mega Altyapı Finansman Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Köprü ve otoyol sözleşmelerinde kur dalgalanmalarına karşı kamu yararını gözeten denetim mekanizması kuruldu."}]', 435) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_436', 'modern', 'Çanakkale Boğazı Lojistik Kilitlenmesi ve Ege Savunma Koridoru', 'Ulaştırma Bakanlığı', 'Kış fırtınalarında Gelibolu-Lapseki feribot seferleri günlerce iptal oluyor; Trakya ve Ege sanayisi kilitleniyor, Ege adaları ve Akdeniz gerilimlerinde TSK\'nın savunma ikmal hattı felç olma riski taşıyor. Çanakkale Boğazı\'na 2023 metre açıklıklı dünyanın en uzun asma köprüsünü yapma projesi masaya geldi.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Güney Kore ve Türk ortaklığıyla uluslararası mühendislik denetimi altında 1915 Çanakkale Köprüsü ve otoyolunu inşa et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"1915 Çanakkale Köprüsü kırmızı-beyaz kuleleriyle Çanakkale Boğazı\'nı birleştirdi; feribot çilesi 6 dakikaya indi."},{"label":"Denizcilik müsteşarlığı ve bölge balıkçılarıyla istişare et; boğaz akıntılarını bozmamak için feribot limanlarını tahkim edip köprüyü ertele.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Feribotlar iyileştirildi; fakat şiddetli kış lodoslarında Ege sevkiyatı yine günlerce durma noktasına geldi."},{"label":"Köprüyü Hazine garantili YİD modeliyle finanse et; Trakya-Ege lojistik hattını bağlayarak yıllık yüz milyonlarca avro yakıt ve zaman tasarrufu sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Ekonomik koridor açıldı; Çanakkale üzerinden Ege limanlarına kesintisiz Avrupa ihracat hattı kuruldu."},{"label":"Köprü kulelerine gizli hava savunma radarları, boğaz gözetleme optikleri ve askeri konvoy öncelikli şeritler entegre et.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Çanakkale Boğazı askeri açıdan geçilmez kılındı; Ege savunma koridoru Mehmetçik için stratejik güvenceye bağlandı."},{"label":"Boğaz ve stratejik suyolları üzerindeki asma köprüleri askeri stratejik tesis statüsüne alan \'Milli Boğaz Altyapısı Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Çanakkale Köprüsü kanuni koruma altına alındı; Cumhuriyetin 100. yıl simgesi milli güvenliğin ayrılmaz parçası oldu."}]', 436) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_437', 'modern', 'Atatürk Havalimanı Kapasite İflası ve Karadeniz Mega Havalimanı Kararı', 'Ulaştırma Bakanlığı', 'Atatürk Havalimanı günde 1500 uçağa ulaşarak slot kapasitesini tüketti; uçaklar Marmara üzerinde saatlerce havada yakıt harcıyor, kargo talebi karşılanamıyor. Avrupa ve Körfez havayollarının Türkiye\'nin transit hub olmasını engellemeye çalıştığı istihbarat raporlarına yansırken, Karadeniz kıyısında dev havalimanı kararı gündemde.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Uluslararası Sivil Havacılık Örgütü (ICAO) standartlarında bağımsız ÇED ve rüzgar etüdü yaptırarak İstanbul Havalimanı ihalesini başlat.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yıllık 150 milyon yolcu kapasiteli İstanbul Havalimanı (İGA) inşasına başlandı; Türkiye küresel hava lojistiğinde liderliğe yürüdü."},{"label":"Havacılık sendikaları ve havayolu şirketleriyle istişare et; Atatürk Havalimanı\'na ek pist ve Sabiha Gökçen\'e 2. pist yaparak yeni meydanı ertele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Mevcut meydanlar genişletildi; ancak küresel aktarma merkezi olma potansiyeli ertelenmiş oldu."},{"label":"YİD modeliyle 5\'li Türk konsorsiyumuna ihale et; devlete 22 milyar avro kira geliri ve yüz binlerce istihdam sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kamu bütçesinden tek kuruş çıkmadan dünyanın en büyük havalimanı kompleksi inşa edilerek Hazineye dev kira geliri aktarıldı."},{"label":"Mega havalimanı sahasında yabancı istihbarat servislerinin sabotaj ve siber saldırı girişimlerine karşı MİT ve USOM güvenlik kalkanı kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Havalimanının hava trafik kontrol yazılımları ve radar sistemleri siber casusluğa karşı milli yazılımlarla korundu."},{"label":"Türkiye\'yi Avrasya\'nın hava kargo ve aktarma üssü yapan \'Milli Havacılık ve Slot Düzenleme Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Havacılık mevzuatı güncellendi; THY dünyanın en çok ülkesine uçan bayrak taşıyıcısı unvanını perçinledi."}]', 437) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_438', 'modern', 'Atatürk Havalimanı\'nın Taşınması: \'Büyük Göç\' Lojistik Güvenliği ve Sabotaj Tehdidi', 'Ulaştırma Bakanlığı', 'Dünya havacılık tarihinin en büyük meydan taşınması 45 saatte gerçekleşecek; binlerce tır dolusu hassas radar, yer hizmeti ve uçuş ekipmanı taşınacak. MİT ve Emniyet İstihbarat, taşınma sırasında yabancı servislerin veya terör hücrelerinin lojistik koridorda kaos yaratma istihbaratını bildiriyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Devlet Denetleme Kurulu ve Mülkiye müfettişlerini güzergah boyunca görevlendirerek taşınmayı dakika dakika şeffaf denetle.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Lojistik süreç kusursuz yürütüldü; 45 saatlik tarihi operasyon hiçbir kaza yaşanmadan tamamlandı."},{"label":"Havayolu çalışanları, pilotlar ve yer hizmetleri sendikalarıyla koordinasyon masası kur; taşınma süresini 1 haftaya yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Taşınma yavaşlatıldı; aksaklıklar azaldı fakat Atatürk Havalimanı\'nın kapanış takvimi uzadı."},{"label":"Taşınma operasyonunun yol kapama ve güvenlik maliyetlerini havayolu şirketleri ve İGA konsorsiyumu arasında adil paylaştır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Bütçe dengesi korundu; kamu kurumlarına ek maliyet binmeden dev lojistik transfer finanse edildi."},{"label":"Atatürk Havalimanı ile İstanbul Havalimanı arasındaki Basın Ekspres ve Kuzey Marmara hatlarını askeri/polisiye kordonla kapat.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Büyük Göç Mehmetçik ve polisin çelik kalkanı altında tamamlandı; terör ve sabotaj girişimleri başlamadan engellendi."},{"label":"Stratejik kamu tesislerinin acil taşınma ve lojistik protokollerini tanzim eden \'Kritik Ulaşım Güvenliği Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Dünya sivil havacılık literatürüne örnek teşkil eden taşınma harekatı yasal mevzuatla kurumsallaştı."}]', 438) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_439', 'modern', 'Pandemi Krizinde Yoğun Bakım İflası ve Atatürk Havalimanı Pist İkilemi', 'Ulaştırma Bakanlığı', 'Koronavirüs salgınında hastaneler doldu; kritik solunum cihazı ve yoğun bakım yatağı tükendi. Atatürk Havalimanı\'nın kullanım dışı kalan iki pistinin üzerine 45 günde 1008 yataklı acil şehir hastanesi yapılması planlanıyor; muhalefet pistlerin kırılarak havalimanının yok edilmek istendiğini savunuyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Sağlık Bakanlığı ve Tabipler Birliği\'ni sürece dahil et; pistlerin kırım gerekçesini ve acil yoğun bakım ihtiyacını halka şeffaf açıkla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Şeffaf kriz iletişimi yürütüldü; yoğun bakım çaresizliği yaşayan halkın tepkisi dindirildi."},{"label":"Mimarlar odası ve sivil toplumla istişare et; hastaneyi pistlerin üzerine değil apronun boş hangarlarına modüler kur.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Pistler korundu; fakat modüler hastanenin yatak kapasitesi salgının zirve noktasında yetersiz kaldı."},{"label":"Hazine acil afet fonundan 45 günde 1008 yataklı Prof. Dr. Murat Dilmener Şehir Hastanesi\'ni rekor sürede inşa et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Pandemiye çelik kalkan kuruldu; binlerce vatandaş yoğun bakımda tedavi edilerek ölüm oranları frenlendi."},{"label":"Salgın fırsatçılığıyla hastane inşaatına provokasyon yapmaya çalışan marjinal gruplara karşı güvenlik çemberi kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"İnşaat güvenliği sağlandı; hastane 45 günde teslim edilerek sağlık ordusunun emrine verildi."},{"label":"Salgın ve nükleer/biyolojik afetlerde kullanılacak sahra hastanelerini yasal çerçeveye alan \'Acil Sağlık Savunma Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Havalimanı hastanesi sağlık turizmi ve afet üssü olarak tescillendi; Türkiye\'nin sağlık altyapısı tescillendi."}]', 439) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_440', 'modern', 'Atatürk Havalimanı Arazisinde Rant Baskısı ve Millet Bahçesi İkilemi', 'Ulaştırma Bakanlığı', 'Atatürk Havalimanı\'nın boşalan milyonlarca metrekarelik arazisi için dev inşaat şirketleri ve uluslararası emlak fonları konut/AVM projeleriyle kapıyı çalıyor. İstihbarat, arazinin ranta kurban edilmesi halinde büyük toplumsal infial çıkacağını raporlarken; arazinin halka açık devasa Millet Bahçesi\'ne dönüştürülmesi tartışılıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Araziyi bağımsız Şehir Plancıları ve Mimarlar Kurulu\'na devret; imar planını kamu yararına yeşil alan olarak tescil ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Rant kapısı kapatıldı; arazinin satışı veya yapılaşmaya açılması bağımsız yargı ve planla kilitlendi."},{"label":"İstanbul halkı ve meslek odalarıyla anket ve istişare meclisi kur; ağaçlandırma ve spor alanlarını halkın talebine göre çiz.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal mutabakat sağlandı; İstanbulluların nefes alacağı 2 milyon metrekarelik Millet Bahçesi projesi benimsendi."},{"label":"Arazinin bir kısmını uluslararası fuar ve kongre merkezine ayırarak İstanbul turizmine yıllık milyarlarca lira kaynak kazandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ekonomik akıl devreye girdi; dev fuar alanıyla Hazineye turizm geliri sağlanırken kalan alan yeşil bırakıldı."},{"label":"Arazideki acil iniş pistini ve askeri hangarları koru; olası İstanbul depreminde lojistik yardım ve arama-kurtarma üssü olarak tahkim et.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Stratejik afet kalkanı kuruldu; pistler deprem anında yardım uçaklarının inmesi için hazır tutuldu."},{"label":"Milli parklar ve askeri arazilerin imara açılmasını anayasal güvenceyle yasaklayan \'Yeşil Şehirler ve Millet Bahçeleri Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Arazinin tapusuna kamuya terk şerhi düşüldü; gelecek nesiller için dev şehir parkı güvenceye alındı."}]', 440) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_441', 'modern', 'Ankara-Eskişehir Koridorunda Karayolu Katliamları ve İlk YHT Kararı', 'Ulaştırma Bakanlığı', 'Başkent ile sanayi kenti Eskişehir arasındaki karayolunda otobüs ve tır kazaları yılda yüzlerce can alıyor; demiryolu altyapısı ise 100 yıllık buharlı tren hızında. İspanyol ve Türk ortaklığıyla Türkiye\'nin ilk Yüksek Hızlı Tren (YHT) hattının inşası için karar bekleniyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Uluslararası demiryolu güvenliği denetçilerini görevlendir; sıfır hata toleransıyla Ankara-Eskişehir YHT hattını inşa et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Türkiye hızlı trenle tanıştı; 250 km hızla iki şehir arası seyahat süresi 1 saat 20 dakikaya indi."},{"label":"Şehirlerarası otobüs işletmeleri ve yerel esnafla meşveret et; otobüs firmalarının bilet tarifelerini sübvanse ederek YHT\'yi ertele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Otobüs esnafı korundu; fakat karayollarındaki ölümcül kaza oranları düşürülemedi."},{"label":"İspanyol dış kredisi ve Hazine tahvilleriyle hattı finanse et; karayolu akaryakıt tüketimini azaltarak döviz tasarrufu sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milli ekonomi kazandı; vatandaş güvenli ve ucuz seyahat konforuna kavuştu."},{"label":"Hızlı tren hattı boyunca elektro-optik kameralar ve sabotaj erken uyarı sensörleri kurarak ray güvenliğini sağla.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Raylar terör ve ray sabotajı girişimlerine karşı 24 saat kesintisiz koruma altına alındı."},{"label":"Türkiye\'yi demir ağlarla ören hızlı tren projelerini milli öncelik ilan eden \'Milli Hızlı Tren ve Raylı Sistemler Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"YHT seferleri yasal güvenceye bağlandı; Türkiye dünyada hızlı tren işleten sekizinci ülke oldu."}]', 441) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_442', 'modern', 'İç Anadolu Bozkırının İzolasyonu ve Ankara-Konya YHT Stratejisi', 'Ulaştırma Bakanlığı', 'Konya Ovası\'nın dev sanayi ve tarım potansiyeli başkent Ankara\'dan kopuk; mevcut trenle 10 saat süren yolculuk ticareti felç ediyor. Düz arazide 300 km hız yapacak YHT hattı için ray ve sinyalizasyon ihaleleri gündemde; ancak yerli mühendislik kapasitesi tartışılıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Devlet Demiryolları (TCDD) mühendislerine tam yetki ver; hattın altyapı ve ray döşeme işlerini tamamen yerli firmalarla tamamla.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Türk mühendisleri tarihi bir başarıya imza attı; Ankara-Konya YHT hattı rekor sürede ve düşük maliyetle tamamlandı."},{"label":"Mevlana turizmi ve esnaf odalarıyla istişare et; tren sefer saatlerini tarım fuarları ve kültürel etkinliklere göre planla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür ve ticaret entegrasyonu sağlandı; seyahat süresi 1 saat 45 dakikaya inerek iki şehir birleşti."},{"label":"Hattın işletme gelirlerini doğrudan Hazineye aktararak yeni Doğu ve Güney hızlı tren projeleri için döner sermaye oluştur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kendi kendini amorti eden başarılı bir kamu yatırımı modeli kuruldu."},{"label":"Bozkırdan geçen yüzlerce kilometrelik açık ray hattına jandarma devriyeleri ve İHA gözetleme uçuşları tahsis et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Açık bozkır hattı terör ve sabotaj tehditlerine karşı tam emniyete alındı."},{"label":"Yüksek hızlı tren makinistliği ve sinyalizasyon uzmanlığını yüksek mesleki statüye bağlayan kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Demiryolu emniyet kültürü kurumsallaştı; YHT seferleri kazasız ve güvenle işletildi."}]', 442) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_443', 'modern', 'Ankara-İstanbul YHT Doğançay Ripajı ve Tünel Çökme Krizi', 'Ulaştırma Bakanlığı', 'Ankara ile İstanbul\'u bağlayacak YHT hattının en kritik Boğaz-Sapanca geçişinde (Doğançay Ripajı) devasa heyelanlar ve tünel göçükleri meydana geldi. Yabancı danışmanlar hattın bu noktada yapılamayacağını iddia ederken, milyarlarca dolarlık yatırımın boşa gitme tehlikesi doğdu.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Maden Tetkik ve Arama (MTA) ve üniversite jeologlarını sahaya sür; zemin güçlendirme tünelleriyle Doğançay geçişini tamamla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Zorlu coğrafya aşıldı; viyadükler ve tünellerle Ankara-İstanbul hızlı tren hattı hizmete açıldı."},{"label":"Bölge köylüleri ve çevre uzmanlarıyla meşveret et; tünel güzergahını heyelan vadisinin dışındaki alternatif yamaca kaydır.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Güzergah revize edildi; inşaat maliyeti bir miktar arttı fakat zemin çökme riski sıfırlandı."},{"label":"Göçüğe neden olan eksik zemin etüdü yapan yabancı müşavirlik firmasına Hazine tarafından devasa tazminat davası aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine zararı tanzim edildi; kusurlu yabancı denetçilerden tazminat tahsil edildi."},{"label":"Tünel inşaat sahasına termal kameralar ve acil arama-kurtarma timleri konuşlandırarak işçi güvenliğini en üst seviyeye al.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"İş güvenliği tavizsiz uygulandı; Doğançay tünellerinde can kaybı yaşanmadan delme işlemi bitti."},{"label":"Mega tünel ve viyadük projelerinde jeoteknik zorunlu sigorta şartı getiren \'Milli Altyapı Denetim Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Altyapı mühendisliği mevzuatı güçlendirildi; Ankara-İstanbul seyahat süresi 4 saate indi."}]', 443) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_444', 'modern', 'Doğu Anadolu İzolasyonu ve Ankara-Sivas Hızlı Tren Jeolojik Zorluğu', 'Ulaştırma Bakanlığı', 'Kırıkkale, Yozgat ve Sivas hattında kış aylarında karayolları kapanıyor; Doğu Anadolu\'dan göç durdurulamıyor. Ankara-Sivas YHT hattı planlandı; ancak güzergah boyunca 49 tünel ve 49 viyadük gerektiren zorlu jeolojik yapı Hazineye ağır maliyet yüklüyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yerli demiryolu konsorsiyumuyla 66 kilometrelik tünelleri ve 27 kilometrelik viyadükleri inşa ederek Ankara-Sivas YHT\'yi aç.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Ankara-Sivas arası 12 saatten 2 saate indi; Doğu Anadolu başkente hızlı ve konforlu raylarla bağlandı."},{"label":"Yozgat ve Sivas yerel dinamikleriyle istişare et; ara istasyonları organize sanayi bölgelerine bağlayarak tersine göçü teşvik et.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Bölgesel kalkınma hızlandı; Sivas ve Yozgat\'ta sanayi yatırımları patlama yaptı."},{"label":"Proje finansmanını dış kredi yerine iç borçlanma ve bütçe tasarruflarıyla karşılayarak Hazine döviz riskini bertaraf et.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milli para birimiyle devasa bir mega proje hayata geçirildi."},{"label":"Dağlık Sivas ve Yozgat vadilerindeki viyadüklere sabotaj ve kış donmasına karşı akıllı sensörler yerleştir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"YHT hattı aşırı soğuk ve terör tehdidine karşı yüksek teknolojiyle korundu."},{"label":"Ankara-Sivas hattını Erzincan ve Kars üzerinden Bakü\'ye uzatacak \'Doğu Raylı Koridor Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Hızlı tren Kafkasya vizyonuyla taçlandırıldı; Demir İpekyolu\'nun omurgası kuruldu."}]', 444) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_445', 'modern', 'Bakü-Tiflis-Kars (BTK) Demiryolu ve Ermenistan/Rusya Baskısına Karşı Demir İpekyolu', 'Ulaştırma Bakanlığı', 'Ermenistan\'ı baypas ederek Azerbaycan, Gürcistan ve Türkiye\'yi doğrudan demiryoluyla birleştirecek Bakü-Tiflis-Kars hattı için yabancı diplomatik baskılar ve Gürcistan sınırındaki lojistik güvenlik sorunları baş gösterdi. Londra\'dan Pekin\'e uzanan koridorda Türkiye\'nin stratejik kararı bekleniyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Azerbaycan ve Gürcistan ile üçlü hükümetlerarası anlaşmaya sadık kal; uluslararası baskılara boyun eğmeyerek BTK hattını aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Demir İpekyolu faaliyete geçti; Çin\'den Avrupa\'ya kesintisiz yük taşımacılığı Türkiye üzerinden sağlandı."},{"label":"Bölge ülkeleri ve Kafkasya paydaşlarıyla diplomatik temasları artır; hattın sadece ticari barış koridoru olduğunu dünyaya anlat.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik baskılar püskürtüldü; Kafkasya\'da bölgesel refah ve ticaret hacmi katlandı."},{"label":"Kars Lojistik Merkezi\'ni kurarak Hazineye transit konteyner gelirleri aktar; Kars\'ı Avrasya\'nın aktarma üssü yap.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Doğu Anadolu kalkındı; Kars üzerinden yıllık milyonlarca ton transit yük aktarımı başladı."},{"label":"Sınır hattı boyunca Gürcistan ve Azerbaycan güvenlik birimleriyle ortak sınır devriyesi ve ray koruma protokolü imzala.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"BTK demiryolu hattı terör sabotajlarına ve tren kaçırma tehditlerine karşı çelik kalkanla korundu."},{"label":"Türkiye\'yi Asya-Avrupa demiryolu taşımacılığının imtiyazlı transit ülkesi yapan \'Milli Lojistik ve Transit Taşımacılık Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Türkiye küresel tedarik zincirinde vazgeçilmez köprü konumuna yükseldi."}]', 445) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_446', 'modern', 'İstanbul Havalimanı Ulaşım Krizinde Gayrettepe Hızlı Metro Hattı', 'Ulaştırma Bakanlığı', 'Şehir merkezinden 40 kilometre uzakta kurulan yeni havalimanına sadece karayoluyla ulaşılması yoğun trafik saatlerinde uçak kaçırma krizlerine yol açıyor. Türkiye\'nin en hızlı (120 km/s) ve en derin metro hattı olan Gayrettepe-Havalimanı projesi için yeraltı delme makineleri hazır bekliyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Milli sinyalizasyon yazılımı ASELSAN tarafından geliştirilen Türkiye\'nin en hızlı metrosunu rekor sürede inşa et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"M11 Metro hattı açıldı; Kağıthane\'den havalimanına 24 dakikada ulaşım sağlandı."},{"label":"İETT ve HAVAİST otobüs işletmeleriyle koordinasyon sağla; metro tamamlanana kadar ekspres otobüs hatlarını sübvanse et.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Geçici mağduriyetler önlendi; ancak kalıcı çözüm için metro inşaatı zorunlu kaldı."},{"label":"Metro vagonlarının yerlilik oranını yüzde 60 şartına bağla; yerli raylı sistem sanayisine milyarlarca liralık sipariş kazandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yerli vagon sanayisi doğdu; Hazine kaynakları yurtdışına akmak yerine içeride kaldı."},{"label":"Derin metro istasyonlarında olası kimyasal, biyolojik ve nükleer (KBRN) sızıntılara karşı askeri sığınak standardı uygula.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Gayrettepe hattı aynı zamanda İstanbul\'un en güvenli yeraltı sığınak ağı olarak tasarlandı."},{"label":"Havalimanı ve metro entegrasyonunu güvenceye alan \'Büyükşehir Raylı Toplu Taşıma Reform Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"İstanbul ulaşım ağı modernize edildi; metro hattı daha sonra Halkalı\'ya kadar uzatıldı."}]', 446) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_447', 'modern', 'Kuzey Marmara Otoyolu Akıllı Ulaşım Sistemlerine Yönelik Siber Tehdit', 'Ulaştırma Bakanlığı', 'Kuzey Marmara Otoyolu akıllı trafik kameraları, otomatik gişeler ve tünel havalandırma sistemleriyle donatıldı. USOM ve MİT, otoyolun ana kontrol merkezine yabancı IP\'lerden siber sızma girişimi yapıldığını ve tünel havalandırmalarını kilitleyerek toplu facia çıkarma planı olduğunu raporladı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Siber saldırı girişimini yapan yabancı sunucuları uluslararası bilişim suçları kapsamında adli soruşturmaya sevk et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Siber saldırı kaynakları tespit edildi; deliller uluslararası adli mercilerle paylaşıldı."},{"label":"Otoyol işletmeci konsorsiyumu ve Ulaştırma Bakanlığı bilişim daireleriyle acil kriz masası kur; sistemleri geçici olarak manuel kontrole al.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Trafik akışı kesintiye uğramadan manuel güvenlik protokolleriyle yönetildi."},{"label":"Milli siber güvenlik firmalarına acil bütçe tahsis et; otoyolun tüm SCADA kontrol sistemlerini yerli yazılıma geçir.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Dışa bağımlı yazılımlar tasfiye edildi; yerli firewall ve siber savunma kalkanı kuruldu."},{"label":"MİT Siber Daire ve Emniyet Siber Suçlarla Mücadele timleriyle karşı siber operasyon düzenle; sızma yapan bilgisayarları çökert.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Otoyola yönelik siber sabotaj girişimi kökünden ezildi; tünel kontrol merkezleri tam korumaya alındı."},{"label":"Kritik karayolu ve tünel SCADA sistemlerini yerli yazılıma bağlamayı zorunlu kılan \'Akıllı Altyapı Siber Güvenlik Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Milli altyapı siber güvenceye kavuştu; otoyollar dijital saldırılara karşı korundu."}]', 447) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_448', 'modern', 'İstanbul-İzmir Otoyolu Güzergahında Verimli Tarım Arazileri İkilemi', 'Ulaştırma Bakanlığı', 'İstanbul ile İzmir arasındaki sanayi ve turizm akışını 3.5 saate düşürecek otoyol projesinde kamulaştırma başladı. Ancak güzergahın Balıkesir ve Manisa\'nın en verimli zeytinlik ve üzüm bağlarından geçmesi çiftçilerin ve çevre derneklerinin yargıya başvurmasına yol açtı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Danıştay kararlarına ve ziraat mühendisleri odasının raporlarına uy; otoyol güzergahını zeytinliklerin dışındaki çorak tepeye kaydır.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Verimli zeytinlikler kurtarıldı; otoyol viyadüklerle yamaçlara taşınarak kamu vicdanı rahatlatıldı."},{"label":"Bölge çiftçileri, ziraat odaları ve kooperatiflerle masaya otur; kamulaştırma bedellerini piyasanın yüzde 50 üzerinde ödeyerek uzlaş.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Çiftçilerle helalleşildi; tarımsal kayıplar devlet sübvansiyonuyla telafi edildi."},{"label":"Otoyolu YİD modeliyle rekor sürede tamamla; Ege sanayisini ve yaş sebze/meyve ihracatını limanlara 3.5 saatte ulaştırarak milli gelir üret.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"İstanbul-İzmir otoyolu açıldı; yaş meyve-sebze bozulmadan Avrupa ve Rusya pazarlarına sevk edildi."},{"label":"Kamulaştırma arazilerini fırsata çevirip köylünün arazisini ucuza kapatmaya çalışan arsa tefecilerine polisle operasyon yap.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Rant çeteleri çökertildi; köylünün hakkı tefecilere yedirilmedi."},{"label":"Otoyol çevresinde tarım arazilerinin sanayi ve konuta açılmasını yasaklayan \'Tarım Arazilerini Koruma ve Otoyol Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Otoyol kenarı betonlaşmadan korundu; tarım ve modern ulaşım dengesi yasal teminata bağlandı."}]', 448) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_449', 'modern', 'Zigana Geçidinde Buzlanma Faciası ve Avrupa\'nın En Uzun Çift Tüp Tüneli', 'Ulaştırma Bakanlığı', 'Tarihi İpek Yolu\'nun Doğu Karadeniz\'i Orta Doğu\'ya bağlayan Zigana Geçidi\'nde kışın yaşanan buzlanma ve çığ felaketleri onlarca tır şoförünün ve ailenin uçurumlara yuvarlanmasına yol açıyor. Dağın altına 14.5 kilometrelik Avrupa\'nın en uzun çift tüplü tünelinin yapılması projesi masada.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Uluslararası Tünelcilik Birliği (ITA) standartlarında bağımsız jeolojik denetimle Yeni Zigana Tüneli projesini başlat.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yeni Zigana Tüneli inşaatı başladı; 14.5 kilometrelik çift tüp tünel rekor sürede dağın altından geçirildi."},{"label":"Bölge nakliyecileri ve otobüs kooperatifleriyle istişare et; eski geçide kar siperleri ve ısıtmalı asfalt döşeyerek tüneli ertele.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Eski yolda geçici iyileştirme yapıldı; ancak kış şartlarında ölümcül çığ riski önlenemedi."},{"label":"Tünel inşasını yerli mühendislik ve Hazine bütçesiyle tamamla; yıllık yüz milyonlarca lira akaryakıt ve bakım tasarrufu sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Zigana Tüneli açıldı; Trabzon\'dan Gümüşhane ve Erzurum\'a kesintisiz, güvenli transit hat kuruldu."},{"label":"Tünel içine acil durum karakolları, yangın söndürme robotları ve sabotaj erken uyarı sensörleri yerleştir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Avrupa\'nın en uzun çift tüp tüneli her türlü kaza ve terör senaryosuna karşı emniyete alındı."},{"label":"Dağlık bölgelerde tünel ve viyadük standartlarını zorunlu kılan \'Karayolu Kış Güvenliği ve Tünel Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Tünel işletmesi yasal güvenceye bağlandı; Doğu Karadeniz lojistiği 12 ay açık hale geldi."}]', 449) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_450', 'modern', 'Ovit Dağı Kış İzolasyonu ve İran Transit Hattında 14 Kilometrelik Tünel İkilemi', 'Ulaştırma Bakanlığı', 'Rize ile Erzurum arasındaki 2640 rakımlı Ovit Dağı geçidi kışın 5 ay boyunca yoğun kar ve çığ nedeniyle kapanıyor; Karadeniz limanları ile Doğu Anadolu ve İran arasındaki ticaret kesintiye uğruyor. 14 kilometrelik Ovit Tüneli projesi için ağır kış şartlarında karar bekleniyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Deprem fay hatları ve yeraltı su kaynaklarını koruyacak bağımsız mühendislik denetimiyle Ovit Tüneli ihalesini aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Ovit Dağı delindi; Türkiye\'nin ve dünyanın en uzun çift tüplü tünellerinden biri inşa edildi."},{"label":"Bölge tüccarları ve şoförler odasıyla kriz masası kur; kış aylarında ağır vasıtaları alternatif sahil güzergahına yönlendir.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Sahil yolu tır yoğunluğundan kilitlendi; Ovit Tüneli\'nin kaçınılmaz olduğu anlaşıldı."},{"label":"Projeyi Hazine kaynaklarıyla finanse ederek tamamla; Rize Limanı\'nı İran ve Orta Asya pazarlarına doğrudan bağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Ovit Tüneli hizmete girdi; Karadeniz ile Doğu Anadolu arası seyahat süresi ve maliyeti yarı yarıya düştü."},{"label":"Tünel girişlerine çığ fırlatma sistemleri ve askeri kontrol noktaları kurarak sınır ötesi kaçakçılığı engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Ovit Tüneli hem çığ tehlikesine hem de kaçakçılık şebekelerine karşı tam güvenli hale getirildi."},{"label":"Sınır aşan transit koridorları devlet himayesine alan \'İpek Yolu Lojistik Koridoru Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Ovit Tüneli stratejik koridor olarak tescillendi; kış izolasyonu tarihe karıştı."}]', 450) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_451', 'modern', 'Ilgaz Dağı Kış Tehlikesi ve Kastamonu-Ankara İstiklal Tüneli İhtiyacı', 'Ulaştırma Bakanlığı', 'Milli Mücadele\'nin İstiklal Yolu olan Ilgaz Dağı geçidinde kış aylarında buzlanma ve yoğun sis sebebiyle başkent bağlantısı kopuyor; ambulanslar dağda mahsur kalıyor. Ilgaz 15 Temmuz İstiklal Tüneli projesi masaya geldi; ancak sarp kayalık arazide tünel delme maliyeti tartışılıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Karayolları Genel Müdürlüğü mühendisleriyle tam koordinasyon sağlayarak Ilgaz İstiklal Tüneli projesini başlat.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Ilgaz Dağı tünelle aşıldı; Kastamonu ile Ankara arası 1.5 saate inerek dağ çilesi sona erdi."},{"label":"Bölge esnafı ve dağ turizmi işletmecileriyle istişare et; kayak merkezinin yolunu açık tutarak tüneli ertele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Turizm yolu açık tutuldu; fakat transit ağır vasıta taşımacılığı buzlanmadan kurtarılamadı."},{"label":"Tünel finansmanını Hazine bütçesinden karşıla; yakıt tasarrufu ve turizm canlılığıyla maliyeti 3 yılda amorti et.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Yatırım kendini kısa sürede ödedi; Batı Karadeniz sanayisi başkente doğrudan bağlandı."},{"label":"Tünel içine akıllı sis sensörleri, yangın bariyerleri ve polis devriye noktaları konuşlandır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Ilgaz Tüneli kış şartlarında sıfır kaza hedefiyle emniyete alındı."},{"label":"Milli Mücadele rotalarını koruma ve modern ulaşıma kavuşturma kanunu çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"İstiklal Tüneli milli hatıra ve modern mühendisliğin simgesi olarak hizmete girdi."}]', 451) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_452', 'modern', 'Kamu-Özel İşbirliği (KÖİ) Modeli ve Hazine Geçiş Garantilerinin Bütçe Yükü Krizi', 'Ulaştırma Bakanlığı', 'Köprü, otoyol ve şehir hastanelerinde uygulanan dövize endeksli Hazine geçiş garantileri kur artışlarıyla bütçeye ağır yük getirmeye başladı. Sayıştay raporları ve muhalefet garantilerin kamu maliyesini ipotek altına aldığını savunurken, müteahhitler uluslararası tahkime gitme tehdidi savuruyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Sayıştay ve bağımsız denetçilere tam yetki ver; tüm KÖİ sözleşmelerini inceleyip haksız garanti fazlalarını adli yargıya taşı.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Sözleşmeler mercek altına alındı; fahiş garanti hesaplamaları yargı kararıyla iptal edildi."},{"label":"İşletmeci konsorsiyumlarla uzlaşma masası kur; dövize endeksli garantileri TÜFE/ÜFE sepetine bağlayarak revize et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Konsorsiyumlarla uzlaşma sağlandı; Hazine üzerindeki kur şoku baskısı yumuşatıldı."},{"label":"Geçiş ücretlerini vatandaş için makul seviyeye çek; aradaki farkı Hazine bütçesinden kamu yararı adına karşıla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Vatandaş uygun fiyata köprü ve otoyolları kullandı; ancak Hazineye maliyet bindi."},{"label":"Garanti sayılarını şişirmek için gişelerden usulsüz plaka okutan ve devleti soyan çetelere MASAK ve polisle baskın yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sanal araç geçiş yolsuzlukları çökertildi; kamunun milyonlarca liralık zararı önlendi."},{"label":"Gelecek tüm KÖİ projelerinde döviz garantisini yasaklayan \'Kamu-Özel İşbirliği Çerçeve Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Milli para birimi zorunlu kılındı; kamu maliyesi uluslararası spekülasyonlara karşı güvenceye alındı."}]', 452) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_453', 'modern', 'Kanal İstanbul Projesi: Montrö Boğazlar Sözleşmesi ve Jeopolitik Deniz İkilemi', 'Ulaştırma Bakanlığı', 'İstanbul Boğazı\'ndan geçen petrol tankerlerinin kaza ve patlama riski şehri tehdit ediyor. Karadeniz ile Marmara\'yı bağlayacak yapay Kanal İstanbul projesi gündeme geldi; ancak Montrö Boğazlar Sözleşmesi\'nin delinmesi riski, askeri gemilerin geçişi ve Karadeniz ekosisteminin bozulması uluslararası diplomatik kriz yarattı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Uluslararası deniz hukuku ve Montrö Sözleşmesi\'ne tam bağlı kal; Kanal İstanbul\'un hukuki statüsünü BM ve Karadeniz ülkelerine deklare et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Türkiye\'nin egemenlik hakları savunuldu; fakat uluslararası itirazlar ve diplomatik baskılar sürdü."},{"label":"Bilim insanları, çevre örgütleri ve şehir sakinleriyle halk referandumu düzenle; projeyi toplumsal mutabakata bağla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Demokratik istişare işletildi; kanal projesindeki kutuplaşma ve gerilim dindirildi."},{"label":"Projeyi kamu bütçesinden tek kuruş harcamadan uluslararası konsorsiyumla YİD modeliyle ihale et; Boğaz tanker trafiğinden devasa geçiş geliri sağla.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Finansman modeli kuruldu; fakat devasa maliyet sebebiyle uluslararası fonlar temkinli yaklaştı."},{"label":"Kanal güzergahında yabancı istihbarat servislerinin etki ajanlığı ve arsa spekülasyonu operasyonlarını MİT ile deşifre et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kanal çevresindeki karanlık yabancı fon hareketleri MASAK ve MİT tarafından tespit edilip bloke edildi."},{"label":"Boğaz ve iç suyollarının güvenliğini münhasıran Türkiye\'nin egemenliğine bağlayan \'Milli Su Yolları Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kanal İstanbul\'un hukuki çerçevesi kanunlaştı; Türkiye\'nin deniz jeopolitiğindeki kozu tahkim edildi."}]', 453) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_454', 'modern', 'Kanal İstanbul Sazlıdere Köprüsü ve Arsa Rantı Spekülasyonu Krizi', 'Ulaştırma Bakanlığı', 'Kanal İstanbul projesinin ilk adımı olan Sazlıdere Asma Köprüsü\'nün temeli atılacak. Ancak güzergahtaki tarım ve su havzası arazilerinin yabancı şirketler ve siyasi nüfuz sahipleri tarafından ucuza kapatıldığı iddiaları büyük bir yolsuzluk ve etik tartışması başlattı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Devlet Denetleme Kurulu ve MASAK\'ı görevlendir; güzergahtaki tüm şüpheli tapu devirlerini inceleyip haksız rantları iptal et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Spekülatif arazi rantları donduruldu; şeffaf adli süreç kamu vicdanını rahatlattı."},{"label":"Bölge çiftçileri ve muhtarlarla toplantı yap; köylünün elindeki toprağı satmasını önleyecek tarımsal destek paketi açıkla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Köylü toprağına sahip çıktı; arazilerin spekülatörlerin eline geçmesi engellendi."},{"label":"Sazlıdere Köprüsü\'nü Kuzey Marmara Otoyolu entegrasyonuyla tamamla; transit araç geçişlerinden Hazineye gelir sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Köprü inşası ilerledi; Başakşehir ile Hadımköy arasındaki karayolu bağlantısı güçlendi."},{"label":"İnşaat sahasında terör ve sabotaj tehditlerine karşı jandarma ve emniyet timleriyle 24 saat zırhlı koruma kordonu kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Köprü ayakları ve şantiye sahası provokasyonlara karşı emniyete alındı."},{"label":"Kritik mega altyapı güzergahlarındaki imar rantını yüzde 90 vergilendiren \'İmar Rantı Vergilendirme Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Arsa rantı kamulaştırıldı; spekülatörlerin haksız kazanç kapısı kanunla kapatıldı."}]', 454) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_455', 'modern', 'Çamlıca Tepesindeki Vericilerin Dinleme/Sinyal Casusluğu Zafiyeti', 'Ulaştırma Bakanlığı', 'İstanbul\'un silüetini bozan Çamlıca Tepesi\'ndeki onlarca demir anten kulesinin yabancı istihbarat servislerince sinyal istihbaratı (SIGINT) ve yasadışı dinleme amacıyla kullanıldığı istihbarat raporlarına yansıdı. Dağınık vericilerin tek bir fütüristik kulede toplanması ve askeri frekans güvenliğine alınması planlanıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"BTK ve yargı müfettişlerini görevlendir; izinsiz frekans yayan tüm korsan vericileri mühürleyip sorumluları yargıya sevk et.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Korsan frekanslar temizlendi; elektromanyetik kirlilik ve yasadışı dinleme hatları kesildi."},{"label":"Yayıncı kuruluşlar ve radyo televizyon dernekleriyle istişare et; ortak yayın altyapısına geçiş maliyetlerini sübvanse et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Medya sektörüyle mutabakat sağlandı; 100 radyo aynı anda tek kuleden yayına başladı."},{"label":"369 metrelik Küçük Çamlıca Televizyon Kulesi\'ni inşa et; seyir terası ve restoran gelirleriyle projeyi kendi kendini finanse eder kıl.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Çamlıca Kulesi İstanbul\'un yeni simgesi oldu; Hazineye yıllık milyonlarca lira turizm geliri aktı."},{"label":"Kulenin en üst katına MİT ve TSK\'nın gizli elektronik harp ve sinyal gözetleme dinleme merkezini konuşlandır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İstanbul Boğazı ve Marmara hava sahası elektromanyetik kalkan altına alındı; yabancı sinyal casusluğu engellendi."},{"label":"Haberleşme kulelerini milli stratejik güvenlik alanı ilan eden \'Ulusal Yayın ve Frekans Güvenliği Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Tüm radyo ve TV vericileri tek merkezden kontrol edilen milli güvenlik protokolüne bağlandı."}]', 455) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_456', 'modern', 'Galataport İhalesinde Tarihi Kıyı Şeridi ve Yabancı Yatırımcı Güvenliği İkilemi', 'Ulaştırma Bakanlığı', '200 yıldır halka kapalı olan tarihi Karaköy sahil şeridinde dünyanın ilk yer altı kruvaziyer terminali (Galataport) projesi hazırlandı. Ancak projenin tarihi binaları yok edeceği iddiaları ve yabancı kruvaziyer gemilerine karşı terör ve sabotaj tehditleri gündemde.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Kültür Varlıklarını Koruma Kurulu denetiminde tarihi paket postanesi ve rıhtım binalarını aslına sadık restore ettir.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Tarihi miras korundu; sahil şeridi ilk kez İstanbulluların yürüyüşüne ve kültürüne açıldı."},{"label":"Karaköy esnafı, sanatçılar ve sivil toplumla görüş; sahil bandına halkın ücretsiz erişimini garanti altına al.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkın sahil hakkı korundu; kruvaziyer yolcularıyla şehir halkı aynı meydanda buluştu."},{"label":"Doğuş-Bilgili konsorsiyumuyla YİD ihalesini tamamla; devlete 702 milyon dolar peşin gelir ve yıllık milyonlarca turist girdisi sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dünyanın en modern kruvaziyer limanı açıldı; İstanbul küresel deniz turizminin başkenti oldu."},{"label":"Yeraltı terminaline gizli deniz altı ve balıkadam güvenlik bariyerleri kurarak limanı sabotaja karşı koru.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kruvaziyer limanı en üst seviye ISPS uluslararası liman güvenlik sertifikasıyla korundu."},{"label":"Tarihi kıyı dolgularını ve limanları ranta karşı koruyan \'Kıyı Şeridi ve Liman Reform Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Tarihi limanlar yasal korumaya bağlandı; Galataport küresel bir başarı hikayesine dönüştü."}]', 456) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_457', 'modern', '600 Yıllık Haliç Askeri Tersanesi ve Denizcilik Mirasının Geleceği', 'Ulaştırma Bakanlığı', 'Fatih Sultan Mehmet\'in kurduğu Haliç Tersaneleri (Tersane-i Amire) atıl duruma düştü; özel şirketler arazinin marina ve rezidans yapılmasını istiyor. Denizcilik camiası tarihi kuru havuzların ve gemi üretim kabiliyetinin korunmasını talep ederken tersane arazisi üzerinde büyük rant savaşı yaşanıyor.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Kültür Bakanlığı ve deniz tarihçilerine tam yetki ver; tarihi kuru havuzları sanayi mirası müzesi ve aktif vapur tamirhanesi olarak koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Dünyanın yaşayan en eski tersanesi kurtarıldı; Şehir Hatları vapurları kendi tarihi tersanesinde onarılmaya devam etti."},{"label":"Kasımpaşa halkı ve tersane işçileri sendikalarıyla istişare et; istihdamı koruyarak tersaneyi denizcilik meslek lisesiyle birleştir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"İşçi hakları korundu; tarihi tersane denizcilik ustaları yetiştiren milli akademiye dönüştü."},{"label":"Tersane İstanbul projesiyle atıl binaları kültür ve turizm merkezine dönüştür; Hazineye yüksek kira geliri kazandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Haliç sahilinde müzeler ve oteller açıldı; bütçeye kaynak aktarılırken tarihi doku restore edildi."},{"label":"Tersane arazisine yönelik kundaklama ve şüpheli yangın girişimlerine karşı deniz polisiyle 24 saat nöbet tut.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Tarihi ahşap ambarlar ve vinçler yangın sabotajı tehditlerine karşı güvenceye alındı."},{"label":"Osmanlı\'dan kalan askeri sanayi tesislerinin imara açılmasını ebediyen yasaklayan kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Haliç Tersanesi tarihi tescile kavuştu; Türk denizciliğinin beşiği geleceğe taşındı."}]', 457) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_458', 'modern', 'Haydarpaşa Garı Yangını: Kundaklama/Sabotaj İddiaları ve Garın Statüsü', 'Ulaştırma Bakanlığı', 'Tarihi Haydarpaşa Garı\'nın çatısında çıkan büyük yangın başkenti ayağa kaldırdı. Yangının gar sahasını otel ve AVM yapmak isteyen rant odaklarınca çıkarıldığı iddia edilirken; ray altındaki arkeolojik kazılar ve tren seferlerinin gara dönüp dönmeyeceği büyük bir siyasi gerilime dönüştü.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yangının çıkış nedenini bağımsız kriminal bilirkişilere incelet; sorumluları ağır cezada yargılatıp çatıyı aslına sadık restore et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yangın şüphelileri yargılandı; tarihi garın çatısı orijinal vitrayları ve taşlarıyla yeniden ihya edildi."},{"label":"Demiryolu sendikaları, Kadıköy sakinleri ve koruma kurullarıyla meşveret et; garın sadece demiryolu amacıyla kullanılacağını ilan et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkın güveni tazelendi; garın otel yapılacağı dedikoduları resmi açıklamayla son buldu."},{"label":"Gar sahasında çıkan Helenistik ve Roma dönemi Khalkedon limanı buluntularını Arkeopark olarak turizme aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Haydarpaşa Arkeopark ve Gar kompleksi olarak tescillendi; kültür turizmi canlandı."},{"label":"Tarihi tren garı ve liman sahasına yönelik sabotaj ve yangın riskine karşı özel itfaiye ve emniyet birimi konuşlandır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Tarihi gar binası 24 saat termal kamera ve otomatik yangın söndürme sistemleriyle korundu."},{"label":"Tarihi tren garlarının ve demiryolu mülklerinin özelleştirilmesini yasaklayan \'Tarihi Garlar Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Haydarpaşa Garı\'nın demiryolu kimliği kanunla ebedileşti; trenler tarihi garına geri döndü."}]', 458) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_459', 'modern', 'Doğu Karadeniz Dağlık Arazisinde Havaalanı Yokluğu ve Rize-Artvin Deniz Dolgusu', 'Ulaştırma Bakanlığı', 'Sarp Kaçkar Dağları ve dar vadiler sebebiyle Rize ve Artvin\'de havalimanı yapacak tek bir düz arazi yok; acil hastalar ve yayla turizmi saatlerce Trabzon\'a gitmek zorunda kalıyor. Karadeniz\'in hırçın dalgaları arasına 100 milyon ton taş dökerek deniz dolgusu havalimanı yapma projesi hazırlandı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Karadeniz kıyı hidrolojisini ve dalga mekaniğini en üst uluslararası mühendislik standartlarında inceleterek inşaatı başlat.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Rize-Artvin Havalimanı deniz dolgusu üzerinde çay bardağı kulesiyle yükseldi; dünyada 5. deniz havalimanı oldu."},{"label":"Bölge balıkçıları ve sahil sakinleriyle görüş; taş ocaklarının vadilere zarar vermesini engelleyecek çevre protokolü uygula.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Taş alımı kontrollü yapıldı; vadilerin doğası korunurken deniz dolgusu tamamlandı."},{"label":"Hazine bütçesiyle projeyi tamamla; Doğu Karadeniz yaylalarını dünya turizmine açarak yıllık yüz milyonlarca dolar gelir sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Rize ve Artvin turizmi şahlandı; Gürcistan ve Kafkasya\'dan gelen yolcularla havalimanı doldu taştı."},{"label":"Havalimanının deniz cephesine güçlü mendirekler ve olası askeri çıkarma/operasyonlar için helikopter pistleri konuşlandır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Deniz havalimanı Karadeniz fırtınalarına ve bölgesel askeri acil durumlara karşı tam korumalı inşa edildi."},{"label":"Coğrafi zorluğu olan sınır illerinde altyapıyı sübvanse eden \'Kalkınmada Öncelikli Sınır İlleri Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Rize-Artvin Havalimanı sınır güvenliği ve kalkınmanın stratejik kalesi olarak tescillendi."}]', 459) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_460', 'modern', 'Ordu ve Giresun Arasında Arazi İmkansızlığı ve Açık Deniz Havalimanı Kararı', 'Ulaştırma Bakanlığı', 'Fındık üreticisi Ordu ve Giresun halkı dik yamaçlar sebebiyle başkente ve metropollere ulaşmakta büyük çile çekiyor; arazi olmadığı için iki şehir ortak deniz havalimanı talep ediyor. Türkiye ve Avrupa\'da ilk kez açık denize milyonlarca ton taş dökülerek havalimanı yapımı kararı masada.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Karadeniz dalga şiddetine dayanıklı özel mendirek teknolojisiyle Avrupa\'nın ilk deniz dolgu havalimanını (OR-Gİ) inşa et.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Ordu-Giresun Havalimanı denizin ortasında inşa edildi; Türk mühendisliği dünya literatürüne girdi."},{"label":"Ordu ve Giresun halkı arasında isim ve yer rekabetini önlemek için her iki şehrin adını taşıyan ortak kardeşlik protokolü yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"İki komşu şehir tek yürek oldu; havalimanı bölgesel barış ve dayanışmanın simgesi haline geldi."},{"label":"Hazine kaynaklarıyla projeyi tamamla; fındık tüccarlarının ve gurbetçilerin hızlı ulaşımıyla bölgeye büyük sermaye akışı sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Gurbetçiler memleketine kavuştu; fındık ticareti ve yayla turizmi Karadeniz\'e milyarlarca lira kazandırdı."},{"label":"Deniz pistinin güvenliği için Sahil Güvenlik hücum botları ve radar gözetleme istasyonu kur.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Deniz dolgusu havalimanı Karadeniz\'deki olası deniz kazaları ve arama-kurtarma operasyonlarının üssü oldu."},{"label":"Deniz dolgusuyla kazanılan kamu arazilerinin özel sektöre devrini yasaklayan kanun çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Havalimanı ve kıyı şeridi kamunun ebedi mülkü olarak tescillendi."}]', 460) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_461', 'modern', 'Milli Muharip Uçak KAAN Motor Ambargosu ve Aviyonik Casusluk Tehdidi', 'Savunma Sanayii Başkanlığı', 'F-35 programından çıkarılan Türkiye, 5. nesil savaş uçağı KAAN için prototip motorlarda ve aviyonik yazılımlarda Batılı müttefiklerin örtülü ambargosuyla karşılaştı. MİT, TUSAŞ tesislerine yönelik yabancı siber casusluk girişimlerini raporlarken; uçağın ilk uçuş takvimi ve yerli motor TRMotor geliştirme süreci kritik eşikte.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"TUSAŞ ve Savunma Sanayii Başkanlığı\'na bağımsız adli/teknik soruşturma yetkisi ver; siber sızıntıyı yapan ajanları Ağır Ceza\'ya sevk et.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Havacılık casusluk hücresi çökertildi; KAAN\'ın kritik yazılımları milli kriptolu korumaya alındı."},{"label":"İngiltere ve müttefik hükümetlerle örtülü istihbarat ve savunma diplomasisi masası kur; motor lisansını ortak üretimle aş.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Geçici motor tedariki sağlandı; KAAN ilk uçuşunu göklerde başarıyla tamamladı."},{"label":"Milli bütçeden TRMotor ve TEI yerli motor projelerine 3 milyar dolarlık acil Hazine kaynağı aktar; dışa bağımlılığı sıfırla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Yerli motor geliştirme süreci hızlandı; Türkiye kendi jet motorunu tasarlayan 5 ülkeden biri oldu."},{"label":"MİT Karşı-İstihbarat Dairesi ve TSK siber komutanlığıyla TUSAŞ Akıncı tesislerini \'kırmızı hat\' askeri koruma bölgesine al.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Uçak montaj hatları elektromanyetik kalkanla mühürlendi; yabancı uyduların görüntü alması engellendi."},{"label":"Savunma sanayiinde yerli tasarım hırsızlığına ve teknoloji casusluğuna vatan hainliği cezası getiren kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli Teknoloji Koruma Kanunu yürürlüğe girdi; mühendislerin gizlilik protokolleri kanunlaştı."}]', 461) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_462', 'modern', 'Bayraktar TB2 SİHA Kanada Elektro-Optik (WESCAM) Ambargosu Krizi', 'Savunma Sanayii Başkanlığı', 'Karabağ ve terörle mücadele harekatlarında tarihi başarı gösteren Bayraktar TB2 SİHA\'lara Kanada hükümeti kamera ve lazer işaretleme sistemi (WESCAM) ambargosu koydu. SİHA üretim hatlarının durma tehlikesi karşısında yerli ASELSAN CATS kameralarının acil devreye alınması gerekiyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Kanada\'nın ambargo kararını uluslararası ticaret hukuku ve NATO yükümlülükleri çerçevesinde adli tahkime taşı.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Çifte standart belgelendi; ancak müttefiklerin siyasi ambargosu hukuki süreçle hemen kalkmadı."},{"label":"Kanada ve NATO muhataplarıyla istihbarat kanalı üzerinden görüş; SİHA\'ların sivil güvenliği koruduğunu anlatıp ambargoyu yumuşat.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik baskı sürdü; fakat dışa bağımlılığın milli beka için risk taşıdığı tescillendi."},{"label":"ASELSAN\'a elektro-optik kamera ve lazer işaretleyici seri üretimi için acil Hazine teşvik fonu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli CATS ve ASELFLIR kameraları geliştirildi; Bayraktar TB2 tamamen yerli gözle hedefleri vurmaya başladı."},{"label":"Ambargolu kamera parçalarını üçüncü ülkeler üzerinden tedarik etmeye çalışan paravan şebekeleri MİT ile denetle ve millileştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kritik parçaların kaçak karaborsaya düşmesi engellendi; tedarik zinciri milli fabrikalara bağlandı."},{"label":"Kritik askeri platformlarda alt bileşenlerde yüzde 85 yerlilik şartı getiren \'Savunma Sanayii Bağımsızlık Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Ambargolar Türkiye\'yi üretici yaptı; Bayraktar TB2 30\'dan fazla ülkeye ihraç edilerek küresel marka oldu."}]', 462) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_463', 'modern', 'Bayraktar Akıncı TİHA Ukrayna Motor Tedarikinde Savaş Krizi ve Rus İstihbaratı', 'Savunma Sanayii Başkanlığı', '40 bin fitte 24 saat uçabilen ve seyir füzeleri taşıyan Akıncı TİHA\'nın turboprop motorları Ukrayna Motor Sich fabrikasından tedarik ediliyor. Rusya-Ukrayna savaşı patlak verince motor fabrikası bombalandı; Rus istihbaratı Türkiye\'nin motor tedarikini kesmek için baskı uyguluyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Ukrayna ve BM ile uluslararası insani ve ticari sözleşmelere dayalı resmi motor teslimat protokolünü işlet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yasal haklar korundu; fakat savaş bölgesinden sevkiyatlar ağır risk altına girdi."},{"label":"Moskova ve Kiev ile dengeli istihbarat diplomasisi yürüt; Tahıl Koridoru arabuluculuğu kozuyla motor sevkiyatına koridor aç.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Türk diplomasisi devredeydi; Akıncı motorları savaş bölgesinden güvenle Türkiye\'ye tahliye edildi."},{"label":"TEI yerli turboprop motorunun geliştirilmesi için bütçeden acil 500 milyon dolar ilave AR-GE fonu aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yerli motor üretim takvimi 2 yıl öne çekildi; Akıncı milli güç ünitesine kavuştu."},{"label":"MİT özel operasyon timleriyle motorların Polonya sınırından Türkiye\'ye gizli lojistik intikalini bizzat sağla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"MİT lojistiğiyle yüzlerce motor fabrikaya indirildi; Akıncı seri üretim bandı hiç durmadı."},{"label":"Stratejik askeri hava platformlarında kritik parça stokunu en az 3 yıllık zorunlu kılan \'Savunma Stok Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"TİHA üretimi savaş ve ambargo risklerine karşı çelik zırha kavuşturuldu."}]', 463) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_464', 'modern', 'Bayraktar Kızılelma İnsansız Savaş Uçağı Yapay Zekasına Yabancı Siber Taarruz', 'Savunma Sanayii Başkanlığı', 'Ses hızına yaklaşan, radara görünmez tasarımıyla hava-hava muharebesi yapacak Kızılelma\'nın ilk uçuşu öncesinde otonom filo uçuş yazılımlarına yabancı askeri istihbarat kaynaklı gelişmiş siber sızma girişimi tespit edildi. Sisteme arka kapı (backdoor) yerleştirilerek test uçuşunda düşürülmesi hedefleniyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Siber saldırı kodlarını adli bilişim laboratuvarlarında analiz ettir; kaynağı uluslararası adli makamlara ifşa et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Siber casusluk belgelendi; ancak yabancı servisler eylemi inkar ederek örtbas etti."},{"label":"TÜBİTAK BİLGEM ve Baykar yazılım ekibiyle ortak kriz masası kur; tüm kod tabanını sıfırdan yeniden derle.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Milli yazılım temizlendi; Kızılelma\'nın otonom algoritmaları bağımsız ağda izole edildi."},{"label":"Milli otonom aviyonik ve yapay zeka yazılımcılarına teşvik paketi ver; yazılım güvenliğini yerli mühendislerle tahkim et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Genç Türk yazılımcıları sisteme koruma duvarları ördü; siber savunma kapasitesi güçlendi."},{"label":"USOM ve MİT Siber Daire ile karşı siber operasyon yap; saldırıyı yöneten yabancı sunucu merkezlerini felç et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Siber casusluk şebekesi kaynağında vuruldu; Kızılelma ilk uçuşunu başarıyla gökyüzünde gerçekleştirdi."},{"label":"Otonom silah sistemlerinin kaynak kodlarını devlet sırrı ve milli kripto statüsüne alan kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kızılelma\'nın yapay zekası en üst düzey askeri gizlilik korumasına bağlandı."}]', 464) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_465', 'modern', 'TUSAŞ ANKA-3 Uçan Kanat Hayalet SİHA Tasarımında Radar Casusluğu', 'Savunma Sanayii Başkanlığı', 'Radarda görünmeyen dikey kuyruksuz uçan kanat geometrisine sahip ANKA-3 projesinde, gövde kompozit malzemesi ve radar soğurucu boya formüllerinin yabancı bir havacılık ataşesi tarafından rüşvetle çalınmaya çalışıldığı MİT tarafından tespit edildi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Rüşvet teklif edilen mühendisi adli kontrollü ifadeye al; yabancı ataşeyi \'persona non grata\' ilan ederek sınır dışı et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Diplomatik casusluk deşifre edildi; ANKA-3\'ün hayalet gövde formülleri korunarak casuslar sınır dışı edildi."},{"label":"Havacılık firmaları ve savunma bürokrasisiyle gizli istişare toplantısı yap; yabancı ataşelere şeffaf bilgilendirme verip krizi yatıştır.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik gerilim dindirildi; ancak savunma tesislerindeki gizlilik seviyesi zayıfladı."},{"label":"TUSAŞ kompozit üretim tesislerine Hazine bütçesinden 200 milyon dolar yatırım yaparak gizli kapalı üretim kampüsü kur.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Dünyanın en modern kompozit tesislerinden biri kuruldu; radar soğurucu kaplamalar milli ortamda üretildi."},{"label":"MİT Karşı-İstihbarat timleriyle casusluk şebekesine sahte plan ve yanıltıcı radar verileri sızdırarak yabancı servisi dezenforme et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kusursuz karşı-istihbarat oyunu oynandı; yabancı servisler sahte verilerle yanıltılırken ANKA-3 ilk uçuşunu yaptı."},{"label":"Stratejik savunma sanayii tesislerinde görevli mühendislere ömür boyu yurtdışı bilgi kısıtı ve yüksek tazminat getiren kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Beyin gücü ve gizli teknolojiler yasal koruma kalkanına alındı."}]', 465) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_466', 'modern', 'HÜRJET Süpersonik Uçak İhracatında ABD F404 Motor İzni Blokajı', 'Savunma Sanayii Başkanlığı', 'Ses üstü hızda uçan yerli eğitim ve hafif taarruz uçağı HÜRJET, İspanya ve Malezya ihalelerinde finale kaldı. Ancak uçakta kullanılan Amerikan General Electric F404 motorunun üçüncü ülkelere satışı için ABD Kongresi izin vermiyor ve Türkiye\'nin milyarlarca dolarlık ihracatını engelliyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"ABD ile imzalanan askeri savunma ticaret anlaşması hükümlerini işlet; haksız blokajı uluslararası tahkime bildir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Kongre vetosu devam etti; diplomasi kanalı tıkandı."},{"label":"Pentagon ve ABD Dışişleri ile perde arkasında müzakere yap; F-16 modernizasyon paketi karşılığında HÜRJET motor iznini kopar.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Zorlu diplomasi sonuç verdi; motor lisansına kısmi onay alınarak HÜRJET ihracatının önü açıldı."},{"label":"İhracat gelirlerinin riske girmemesi için TEI ve Ukrayna/İngiltere ortaklığıyla alternatif süpersonik motor geliştirme fonu kur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Alternatif motor programı başlatıldı; Hazine ihracat pazarını kaybetmemek için riski dağıttı."},{"label":"İspanya ve Malezya hükümetleriyle istihbarat ve askeri mutabakat imzala; uçakları motorsuz teslim edip montajı yerinde yap.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Zekice bir ihracat formülü bulundu; ABD vetosu üçüncü ülkelerin egemenlik haklarıyla aşıldı."},{"label":"Milli savunma sanayiinde motor ve aktarma organlarında yabancı lisans kullanımını kısıtlayan kanun çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Tam bağımsızlık hedefi kanunlaştı; HÜRJET Türk Yıldızları akrotiminin yeni uçağı oldu."}]', 466) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_467', 'modern', 'HÜRKUŞ Temel Eğitim Uçağında EASA Sertifikasyon Blokajı', 'Savunma Sanayii Başkanlığı', 'TUSAŞ tarafından geliştirilen temel eğitim ve yakın hava destek uçağı HÜRKUŞ, Avrupa Havacılık Emniyeti Ajansı (EASA) sivil sertifikasyonu için başvurdu. Ancak Avrupa ülkelerinin siyasi gerekçelerle denetim süreçlerini yıllarca uzatarak uçağın uluslararası uçuşunu engellediği belirlendi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"EASA\'nın gecikmelerine karşı Avrupa Adalet Divanı\'na ayrımcılık davası aç ve teknik şartların tamamlandığını belgele.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Hukuki baskı kuruldu; EASA teknik raporları onaylayarak HÜRKUŞ\'a ilk uluslararası tip sertifikasını verdi."},{"label":"Avrupa sivil havacılık otoriteleriyle Brüksel\'de teknik meşveret masası kur; şart koşulan ek aviyonik testleri tamamla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Uzlaşı sağlandı; HÜRKUŞ Avrupa göklerinde uçuş vizesi aldı."},{"label":"Afrika ve Orta Asya ülkelerine HÜRKUŞ-C silahlı varyantını ihraç ederek Avrupa pazarının kaybını peşin dövizle kapat.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Çad, Nijer ve Azerbaycan\'a dev ihracat yapıldı; Hazineye milyonlarca dolar silah satış geliri girdi."},{"label":"HÜRKUŞ test uçuşlarına yabancı istihbaratın telemetri dinlemesi yapmasını engellemek için askeri kriptolu frekans tahsis et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Test verileri yabancı askeri ataşelerden gizlendi; milli aviyonik sistemler korundu."},{"label":"Sivil Havacılık Genel Müdürlüğü\'nü uluslararası sertifikasyon vermeye yetkili kılan \'Milli Havacılık Sertifikasyon Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Avrupa\'nın sertifika tekeli kırıldı; yerli uçaklar Türkiye\'nin kendi kurumunun onayıyla uçtu."}]', 467) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_468', 'modern', 'TCG Anadolu ve F-35B Ambargosuna Karşı Dünyada İlk SİHA Gemisi Doktrini', 'Savunma Sanayii Başkanlığı', 'Donanmanın amiral gemisi olarak inşa edilen 231 metrelik TCG Anadolu çok maksatlı amfibi hücum gemisinin güvertesine konulacak F-35B dikine inişli uçakları ABD ambargoladı. Geminin güvertesiz atıl kalması tehlikesine karşı, dünyada ilk kez SİHA (Bayraktar TB3) gemisine dönüştürme kararı masada.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"ABD\'nin F-35 program ortaklığı ihlali sebebiyle ödenen 1.4 milyar doların iadesi için uluslararası tahkim sürecini başlat.","preview":"Adalet +8, Halk +5, Hazine +7, Otorite +6","effects":{"justice":8,"people":5,"treasury":7,"military":0,"authority":6},"log":"Türkiye\'nin hakları resmi tescile bağlandı; ABD\'nin sözleşme ihlali dünya kamuoyuna duyuruldu."},{"label":"Deniz Kuvvetleri kurmayları ve Savunma Sanayii Başkanlığı\'yla acil harp meclisi topla; geminin doktrinini SİHA konseptine çevir.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Dünya deniz harp tarihine geçildi; TCG Anadolu dünyanın ilk SİHA ve çıkarma gemisi olarak ilan edildi."},{"label":"Bayraktar TB3 ve Kızılelma\'nın gemi iniş-kalkış testleri için Hazine acil bütçesinden özel AR-GE finansmanı ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Katlanır kanatlı Bayraktar TB3 gemiden havalandı; Türk donanması okyanus aşırı hava gücü kazandı."},{"label":"TCG Anadolu\'nun Doğu Akdeniz görevlerinde yabancı denizaltıların yaklaşmasını önlemek için denizaltısavar sonar kalkanı kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Amiral gemisi Mavi Vatan\'da bayrak gösterdi; yabancı fırkateynler ve denizaltılar bölgeden uzaklaştırıldı."},{"label":"Açık deniz görev grupları ve amfibi harekat yetkisini güçlendiren \'Deniz Görev Grubu Teşkilat Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"TCG Anadolu donanmanın amiral gemisi olarak hizmete girdi; Türkiye küresel güç projeksiyonuna kavuştu."}]', 468) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_469', 'modern', 'MİLGEM ADA Sınıfı Korvetlerde Yabancı Sensör ve Silah Blokajı İkilemi', 'Savunma Sanayii Başkanlığı', 'Milli Gemi (MİLGEM) projesi kapsamında Heybeliada ve Büyükada korvetleri inşa edilirken, Batılı müttefikler sonarları, torpido kovanlarını ve savaş yönetim yazılımlarını satmaktan vazgeçti. Tersanelerin gemileri yarım bırakma riski karşısında kritik karar gerekiyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Alman ve Fransız tedarikçilere karşı sözleşme feshi ve teminat mektuplarına el koyma adli sürecini işlet.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hazine zararı teminatlardan tahsil edildi; yabancı tekellerin ambargo oyunu bozuldu."},{"label":"Deniz Kuvvetleri Araştırma Merkezi (ARMERKOM) mühendislerine tam yetki ver; GENESİS milli savaş yönetim sistemini gemiye yükle.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tarihi milli atılım gerçekleşti; GENESİS ve HAVELSAN sistemleri MİLGEM\'in milli beyni oldu."},{"label":"Yerli torpido AKYA ve sonar sistemleri için ASELSAN ve Roketsan\'a doğrudan Hazine finansman desteği sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli torpido ve sonarlar hazırlandı; MİLGEM yüzde 75 yerlilik oranıyla denize indirildi."},{"label":"İstanbul Tersanesi Komutanlığı sahasına yönelik yabancı casusluk ve fotoğraf çekme girişimlerine karşı askeri istihbarat kalkanı kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Gemi inşa sırları korundu; MİLGEM korvetleri gizlilik içinde tamamlanarak Mavi Vatan\'a açıldı."},{"label":"Askeri tersaneleri ve milli gemi inşa sanayiini stratejik milli korumaya alan \'Milli Gemi İnşa Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"MİLGEM projesi Pakistan ve Ukrayna\'ya ihraç edilen dev bir küresel başarıya dönüştü."}]', 469) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_470', 'modern', 'TCG İstanbul Fırkateyninde ABD Mk 41 Dikey Atım Sistemi (VLS) Ambargosu', 'Savunma Sanayii Başkanlığı', 'Türkiye\'nin ilk yerli fırkateyni TCG İstanbul\'un gövdesi bitti; ancak hava savunma füzelerini ateşleyen Amerikan Mk 41 dikey atım sistemi satışı ABD Kongresi tarafından bloke edildi. Geminin silahsız kalmaması için yerli MİDLAS dikey atım sisteminin acilen denenmesi gerekiyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"ABD Kongresi\'nin silah ambargosunu NATO müttefikliği ruhuna aykırılık gerekçesiyle uluslararası alanda teşhir et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Müttefiklerin riyakarlığı kayda geçti; ancak fiili füze ihtiyacı milli çözümü zorunlu kıldı."},{"label":"Roketsan ve Deniz Kuvvetleri komutanlarıyla acil teknik toplantı yap; yerli MİDLAS dikey atım sistemini gemiye entegre et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Türk mühendisleri imkansızı başardı; milli MİDLAS lançerinden HİSAR füzeleri ilk kez başarıyla ateşlendi."},{"label":"Gemiye entegre edilecek yerli Atmaca gemisavar ve HİSAR füzelerinin seri üretimi için Hazine savunma fonunu aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli silah kalkanı kuruldu; yabancı füze ve fırlatıcı ihtiyacı ebediyen sona erdi."},{"label":"Karadeniz ve Ege\'de ilk füze atış testleri sırasında Rus ve Yunan keşif uçaklarının telemetri sinyallerini karıştırıcılarla körelt.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Milli füze frekansları yabancı servislerden gizlendi; MİDLAS atış sırları korundu."},{"label":"Deniz harp platformlarının tüm silah ve fırlatıcılarının milli olmasını zorunlu kılan \'Deniz Savunma Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"TCG İstanbul donanmaya katıldı; Türkiye kendi fırkateynini ve füze lançerini yapan 10 ülkeden biri oldu."}]', 470) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_471', 'modern', 'Reis Sınıfı Denizaltılarda Alman ThyssenKrupp Gizli Kod ve Akustik Sızıntı Tehdidi', 'Savunma Sanayii Başkanlığı', 'Havadan bağımsız tahrik sistemiyle (AIP) haftalarca su altında kalabilen TCG Piri Reis ve Reis sınıfı denizaltılar Gölcük\'te inşa edilirken; Alman üretici firmanın yazılım kodlarında arka kapı bıraktığı ve akustik izlerin yabancı servislere sızabileceği istihbaratı masaya geldi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Gölcük Askeri Savcılığı\'nı ve siber adli bilirkişileri görevlendir; tüm yabancı yazılımları satır satır denetle.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Şüpheli yazılım kodları ayıklandı; yabancı servislerin akustik iz toplama planı çökertildi."},{"label":"Almanya Savunma Bakanlığı ve ThyssenKrupp yetkilileriyle gizli diplomasi yürüt; kaynak kodların tam teslimini şart koş.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Alman firması geri adım attı; denizaltı kontrol yazılımlarının kaynak kodları Türk tarafına devredildi."},{"label":"HAVELSAN MÜREN milli savaş yönetim sistemi için acil 150 milyon dolar ek finansman sağla; Alman sistemini yerliyle değiştir.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Milli denizaltı beyni kuruldu; Piri Reis tamamen yerli MÜREN sistemiyle sessiz derinliklere daldı."},{"label":"Gölcük Tersanesi çevresinde yabancı ataşelerin gizli dinleme cihazlarını MİT karşı-teknik arama timleriyle temizle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Tersane sahası sinyal kalkanıyla mühürlendi; denizaltının gövde akustik sırları korundu."},{"label":"Milli denizaltı inşa ve hidroakustik verilerini en yüksek devlet sırrı kapsamına alan \'Denizaltı Güvenlik Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Piri Reis denizaltısı donanmaya katıldı; Mavi Vatan\'ın sessiz koruyucusu derinliklerde nöbete başladı."}]', 471) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_472', 'modern', 'Altay Tankında Alman MTU Motor ve Renk Transmisyon Ambargosuna Karşı Kore İttifakı', 'Savunma Sanayii Başkanlığı', 'Altay Ana Muharebe Tankı\'nın gövde ve atış kontrol testleri tamamlandı; ancak Almanya hükümeti Suriye harekatlarını gerekçe göstererek MTU motor ve Renk şanzıman satışını süresiz dondurdu. Yüzlerce tankın seri üretime girmesi için güç grubu krizi acil çözüm bekliyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Almanya\'nın silah ambargosunu NATO İttifak Antlaşması\'nın 5. ve 3. maddelerine aykırılık gerekçesiyle NATO Konseyi\'ne taşı.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Diplomatik baskı kuruldu; fakat Almanya\'nın iç siyasi blokajı aşılamadı."},{"label":"Güney Kore hükümeti ve Hyundai Doosan ile stratejik teknoloji transferi masası kur; Kore güç grubunu Altay\'a entegre et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Stratejik ittifak kuruldu; Kore motor ve transmisyonuyla Altay tankı seri üretime geçti."},{"label":"BMC Power yerli BATU 1500 beygirlik tank motoru geliştirme projesine Hazine\'den 500 milyon dolar teşvik ver.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli tank motoru BATU ateşlendi; Türkiye kendi ağır zırhlı motorunu üretecek kapasiteye ulaştı."},{"label":"Altay tankının kompozit ve reaktif zırh (AKKOR) teknolojilerini çalmaya çalışan yabancı ajanlara MİT ile baskın yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Zırh teknolojisi casusluğu engellendi; Altay\'ın tanksavar füzelerini havada imha eden AKKOR sistemi korundu."},{"label":"Kara muharebe araçlarında yerli güç grubu kullanımını zorunlu kılan \'Kara Savunma Sanayii Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Altay tankı TSK envanterine girdi; Türk Silahlı Kuvvetleri bölgenin en güçlü zırhlı yumruğuna kavuştu."}]', 472) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_473', 'modern', 'Roketsan TAYFUN Balistik Füze Testi Sonrası Atina ve NATO Alarmı', 'Savunma Sanayii Başkanlığı', 'Rize Artvin Havalimanı sahasından Sinop açıklarına ateşlenen TAYFUN kısa menzilli balistik füzesi 561 kilometreyi başarıyla vurdu. Testin ardından Yunanistan ve bazı NATO ülkeleri Türkiye\'nin bölgesel dengeyi bozduğunu iddia ederek füze teknolojisi transferlerine ambargo tehdidi savurdu.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Füze menzilinin ve test parametrelerinin uluslararası Füze Teknolojisi Kontrol Rejimi\'ne (MTCR) tam uygun olduğunu deklare et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası hukuk savunuldu; Türkiye\'nin füze geliştirme hakkı meşru zeminde tescillendi."},{"label":"Komşu ülkeler ve müttefiklerle diplomatik temas kur; füzenin yalnızca caydırıcılık ve savunma amaçlı olduğunu belirtip tansiyonu düşür.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Ege ve Akdeniz\'deki diplomatik kriz yumuşatıldı; fakat caydırıcılık mesajı adrese ulaştı."},{"label":"TAYFUN, CENK ve GEZGİN füze ailelerinin menzilini 1000 kilometreye çıkaracak yeni motor ve yakıt AR-GE\'sine bütçe ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli roket sanayisi dev adımlar attı; Türkiye balistik füze liginde küresel caydırıcı güce ulaştı."},{"label":"Füze fırlatma bataryalarının konuşlandığı gizli üslerin koordinatlarını sızdırmaya çalışan yabancı uydulara karşı GPS köreltme uygula.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Füze bataryaları gizlendi; uydu istihbarat servislerinin hedef belirlemesi engellendi."},{"label":"Milli stratejik füze sistemlerinin geliştirilmesini ve konuşlanmasını devlet korumasına alan \'Milli Caydırıcılık Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"TAYFUN füzesi seri üretime girdi; Türkiye\'nin savunma derinliği yüzlerce kilometre öteye taşındı."}]', 473) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_474', 'modern', 'Amerikan Harpoon Ambargosuna Karşı Yerli ATMACA Gemisavarı Konuşlanması', 'Savunma Sanayii Başkanlığı', 'Donanmanın belkemiği olan Amerikan Harpoon gemisavar füzelerine yedek parça ve yeni tedarik ambargosu konuldu. Mavi Vatan\'daki gemilerin silahsız kalması tehlikesine karşı 220 km menzilli yerli ATMACA füzesinin test atışları tamamlandı; ancak füzeyi güdümleyen radar alt sistemlerinde dış sabotaj kuşkusu var.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Harpoon sözleşmelerindeki teslimat aksamalarını adli olarak tespit ettir ve kamu zararını yabancı firmaya fatura et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Hukuki süreç işletildi; Türkiye haklılığını uluslararası platformda kanıtladı."},{"label":"Roketsan ve Kale ARGE mühendisleriyle bir araya gel; yerli KTJ-3200 turbojet motorunu ATMACA\'ya entegre et.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Yerli motor ateşlendi; ATMACA tamamen milli parçalarla denizin üzerinde süzülerek hedef gemiyi ortadan ikiye yardı."},{"label":"Tüm fırkateyn ve korvetlerdeki Harpoon bataryalarını söküp yerlerine ATMACA takmak için donanmaya acil dönüşüm bütçesi tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Donanmanın vuruş gücü yerlileşti; Harpoon\'a ödenen yüz milyonlarca dolar milli savunma sanayiinde kaldı."},{"label":"ATMACA\'nın RF arayıcı başlık frekanslarını yabancı istihbaratın dinlemesini önlemek için elektronik kripto koruması sağla.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Füzenin güdüm sırları korundu; ATMACA radarlara yakalanmayan \'deniz üstü uçan hançer\' oldu."},{"label":"Karasularında ve Mavi Vatan\'da kullanılan gemisavar füzelerinin milli üretimini zorunlu kılan kanun çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"ATMACA seri üretime girdi; Türk donanması Ege ve Akdeniz\'de yabancı ambargoları tarihe gömdü."}]', 474) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_475', 'modern', 'SİPER Uzun Menzilli Bölge Hava Savunma Sistemi ve Eurosam Ambargosu', 'Savunma Sanayii Başkanlığı', 'Türkiye\'nin hava sahasını balistik füze ve savaş uçaklarına karşı koruyacak uzun menzilli füze kalkanı yok; Fransa ve İtalya (Eurosam SAMP-T) ortak füze üretimini siyasi şartlara bağlayarak oyalıyor. ASELSAN, Roketsan ve TÜBİTAK SAGE ortaklığıyla 100+ km menzilli SİPER sisteminin acil konuşlanması gerekiyor.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Eurosam ile yapılan niyet mektubunu tek taraflı feshet; Türkiye\'yi oyalayan Avrupa şirketlerine cezai şart davası aç.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Avrupa\'nın oyalama taktiği bozuldu; Türkiye rotasını tamamen milli hava savunmasına çevirdi."},{"label":"İtalya ve Fransa ile diplomatik temasları sürdür; SAMP-T bataryalarından acil ihtiyaç için hazır alım protokolü ara.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik müzakereler sürdü; ancak teknoloji transferi verilmediği görüldü."},{"label":"SİPER Ürün-1 ve Ürün-2 bataryalarının seri üretimi için Savunma Sanayii Destekleme Fonu\'ndan 1 milyar dolar nakit tahsis et.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"SİPER füzeleri hedefleri başarıyla imha etti; Türkiye hava savunmasında çelik kubbeye kavuştu."},{"label":"SİPER erken uyarı radarının (TEİRS) yayın yaptığı frekansları yabancı sinyal istihbaratından korumak için jamming kalkanı kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Radar istasyonları elektronik taarruza karşı korundu; hava sahası 600 kilometreden taranmaya başlandı."},{"label":"Türkiye\'nin katmanlı hava savunma mimarisini kanunlaştıran \'Milli Çelik Kubbe Hava Savunma Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"KORKUT, HİSAR ve SİPER tek bir akıllı yazılımla birleşti; Türkiye hava sahasını milli kalkanla örttü."}]', 475) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_476', 'modern', 'T129 ATAK Helikopteri Pakistan İhracatında ABD LHTEC Motor Engeli', 'Savunma Sanayii Başkanlığı', 'Türkiye, Pakistan\'a 30 adet T129 ATAK helikopteri satışı için 1.5 milyar dolarlık Cumhuriyet tarihinin en büyük savunma ihracatı sözleşmesini imzaladı. Ancak helikopterde kullanılan CTS800 motorunun üreticisi ABD, ihracat izni vermeyerek anlaşmayı 3 yıl kilitledi ve ihalenin Çin\'e kayma tehlikesi doğdu.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"ABD\'nin haksız rekabet ve sözleşme ihlali gerekçesiyle uluslararası ticari tahkim mahkemelerine dava aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki baskı kuruldu; ancak Kongre\'nin siyasi vetosu aşılamadı."},{"label":"Pakistan hükümetiyle diplomatik müzakere yürüt; süreyi uzatarak yerli motor TEI TS1400 hazır olana kadar ihaleyi koru.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Kardeş Pakistan ile diyalog sürdü; ancak teslimat gecikmesi sebebiyle Pakistan kısmi iptale gitti."},{"label":"Filipinler ve Nijerya pazarlarına yönel; motor izni gerektirmeyen veya izin çıkan alternatif ülkelere ATAK ihraç et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Filipinler ve Nijerya\'ya dev teslimatlar yapıldı; Hazine yüz milyonlarca dolar döviz kazandı."},{"label":"TEI Eskişehir tesislerinde yerli TS1400 turboşaft motorunun geliştirilmesi için MİT koruması ve gizli test protokolü uygula.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Milli helikopter motoru TS1400 tamamlandı; yabancı motor vetosu yerli mühendislikle yırtıldı."},{"label":"Milli savunma ihracatında devletten devlete (G2G) güvence mekanizması getiren \'Savunma İhracatı Düzenleme Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Savunma ihracatı hukuki teminata bağlandı; Türk helikopterleri Asya ve Afrika semalarında uçtu."}]', 476) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_477', 'modern', 'İMECE Askeri İstihbarat Uydusu Fırlatma Rampası Ambargosu ve Siber Sızma', 'Savunma Sanayii Başkanlığı', 'TÜBİTAK UZAY tarafından tamamen yerli üretilen ve metre altı çözünürlükle tüm dünyadan askeri istihbarat toplayacak İMECE uydusu hazırlandı. Fırlatma öncesinde yabancı servislerin uydu şifreleme anahtarlarını çalmak için TÜBİTAK sunucularına siber taarruz yaptığı ve fırlatıcı roket sağlayıcıların siyasi oyalama uyguladığı belirlendi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Siber saldırı girişimini yapan yabancı IP\'leri kriminal olarak delillendir ve adli soruşturma aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Siber casuslar deşifre edildi; uydu telemetri yazılımları bağımsız milli ağa taşındı."},{"label":"SpaceX ve uluslararası uzay ajanslarıyla fırlatma sözleşmesini garantiye alan diplomatik protokol imzala.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"İMECE uydusu Falcon 9 roketiyle uzaya fırlatıldı; yörüngesine başarıyla yerleşti."},{"label":"Yerli mikro uydu fırlatma sistemi (MUFS) ve ROKETSAN Uzay Sistemleri Merkezi\'ne Hazine\'den 300 milyon dolar acil kaynak aktar.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Türkiye kendi uydusunu kendi fırlatacak roket üssü inşasına başladı."},{"label":"İMECE\'nin çektiği hassas askeri görüntülerin kriptolanması için TÜBİTAK BİLGEM donanımsal milli şifreleme cihazı kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Uydu görüntüleri uzaydan yere kırılmaz şifrelerle indi; yabancı servislerin uyduya sızması engellendi."},{"label":"Milli uzay varlıklarını ve askeri uyduları koruma altına alan \'Uzay Güvenliği ve Uydu İstihbaratı Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"İMECE TSK\'nın uzaydaki gözü oldu; Türkiye tüm dünyayı kendi uydusuyla izleme gücüne kavuştu."}]', 477) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_478', 'modern', 'Milli Uzay Programı ve Uydu İstihbaratına Yönelik Yabancı Siber Casusluk', 'Savunma Sanayii Başkanlığı', 'İlk Türk astronotunun Uluslararası Uzay İstasyonu\'nda (ISS) 13 kritik askeri ve biyoteknolojik deney yapacağı açıklandı. Deney protokolleri ve genetik araştırma verilerinin yabancı biyoteknoloji istihbaratı tarafından laboratuvarlardan kopyalanmaya çalışıldığı MİT tarafından raporlandı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"TÜBİTAK MAM ve üniversite laboratuvarlarındaki sızıntı şüphelilerini adli savcılığa sevk et; casusluk davası aç.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Biyoteknoloji casusluğu durduruldu; deney verileri adli korumaya alındı."},{"label":"Axiom Space ve NASA ile ortak bilimsel veri gizliliği anlaşması imzala; deney sonuçlarının sadece Türkiye\'ye ait olduğunu tescil et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Telif ve mülkiyet hakları güvenceye alındı; 13 bilimsel deney Türk bilim insanlarının mülkiyetinde kaldı."},{"label":"Uzay araştırmaları ve astronot eğitimleri için Türkiye Uzay Ajansı\'na (TUA) bütçeden ek ödenek tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli uzay vizyonu finanse edildi; gençlerin bilim ve teknolojiye ilgisi rekor kırdı."},{"label":"ISS ile Türkiye arasındaki canlı telemetri bağlantısına askeri kripto kalkanı kur; yabancı dinlemeleri engelle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Uzay iletişim hattı siber saldırılara karşı korundu; uzaydaki ilk Türk vatandaşı görevini başarıyla tamamladı."},{"label":"Türkiye Uzay Ajansı\'nın yetkilerini ve uzay sanayii teşviklerini düzenleyen \'Milli Uzay Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Türkiye uzay ligine adım attı; uydu ve roket teknolojilerinde milli vizyon yasalaştı."}]', 478) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_479', 'modern', 'HİSAR-A+ ve HİSAR-O+ Alçak ve Orta İrtifa Hava Savunma Bataryaları', 'Savunma Sanayii Başkanlığı', 'Saha birliklerini hava saldırılarına karşı koruyan yerli füze kalkanı seri üretime girdi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Savunma sanayii projelerinin fikri mülkiyet ve patent haklarını devlet adına güvenceye alan yasal tescilleri yap.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Teknolojik mülkiyet korundu; milli projelerin yabancı şirketler tarafından taklit edilmesi önlendi."},{"label":"Yerli mühendis ordusu, üniversiteler ve KOBİ\'lerle teknoloji şurası toplayarak savunma ekosistemini tabana yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal ve sektörel uzlaşı sağlandı; binlerce yan sanayi firması milli savunma üretimine dahil oldu."},{"label":"Stratejik savunma sanayii Ar-Ge projeleri için Savunma Destekleme Fonu\'ndan Hazine destekli teşvik sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma yatırımları finanse edildi; dışa bağımlılık azaltılarak ihracat potansiyeli artırıldı."},{"label":"Kritik savunma tesisleri ve Ar-Ge merkezlerinde casusluk ve sabotaja karşı askeri güvenlik kordonunu tahkim et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik sırlar korundu; milli teknolojilere yönelik yabancı istihbarat operasyonları engellendi."},{"label":"Savunma sanayiinde yerlilik oranını %85\'e çıkaran \'Stratejik Savunma Sanayii ve İleri Teknoloji Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma bağımsızlığı kanunlaştı; Türkiye kendi silahını üreten küresel aktör oldu."}]', 479) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_480', 'modern', 'KORKUT 35 mm İkiz Namlulu Hava Savunma Sistemi', 'Savunma Sanayii Başkanlığı', 'Parçacıklı akıllı mühimmatıyla kamikaze İHA ve füzeleri havada imha eden sistem birliklere dağıtıldı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Savunma sanayii projelerinin fikri mülkiyet ve patent haklarını devlet adına güvenceye alan yasal tescilleri yap.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Teknolojik mülkiyet korundu; milli projelerin yabancı şirketler tarafından taklit edilmesi önlendi."},{"label":"Yerli mühendis ordusu, üniversiteler ve KOBİ\'lerle teknoloji şurası toplayarak savunma ekosistemini tabana yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal ve sektörel uzlaşı sağlandı; binlerce yan sanayi firması milli savunma üretimine dahil oldu."},{"label":"Stratejik savunma sanayii Ar-Ge projeleri için Savunma Destekleme Fonu\'ndan Hazine destekli teşvik sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma yatırımları finanse edildi; dışa bağımlılık azaltılarak ihracat potansiyeli artırıldı."},{"label":"Kritik savunma tesisleri ve Ar-Ge merkezlerinde casusluk ve sabotaja karşı askeri güvenlik kordonunu tahkim et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik sırlar korundu; milli teknolojilere yönelik yabancı istihbarat operasyonları engellendi."},{"label":"Savunma sanayiinde yerlilik oranını %85\'e çıkaran \'Stratejik Savunma Sanayii ve İleri Teknoloji Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Savunma bağımsızlığı kanunlaştı; Türkiye kendi silahını üreten küresel aktör oldu."}]', 480) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_481', 'modern', 'TÜBİTAK SAGE GÖKDOĞAN ve BOZDOĞAN Hava-Hava Füzeleri', 'Savunma Sanayii Başkanlığı', 'Görüş içi ve görüş ötesi füze atışlarıyla Amerikan AIM serisine yerli alternatif üretildi.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Savunma sanayii projelerinin fikri mülkiyet ve patent haklarını devlet adına güvenceye alan yasal tescilleri yap.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Teknolojik mülkiyet korundu; milli projelerin yabancı şirketler tarafından taklit edilmesi önlendi."},{"label":"Yerli mühendis ordusu, üniversiteler ve KOBİ\'lerle teknoloji şurası toplayarak savunma ekosistemini tabana yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal ve sektörel uzlaşı sağlandı; binlerce yan sanayi firması milli savunma üretimine dahil oldu."},{"label":"Stratejik savunma sanayii Ar-Ge projeleri için Savunma Destekleme Fonu\'ndan Hazine destekli teşvik sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma yatırımları finanse edildi; dışa bağımlılık azaltılarak ihracat potansiyeli artırıldı."},{"label":"Kritik savunma tesisleri ve Ar-Ge merkezlerinde casusluk ve sabotaja karşı askeri güvenlik kordonunu tahkim et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik sırlar korundu; milli teknolojilere yönelik yabancı istihbarat operasyonları engellendi."},{"label":"Savunma sanayiinde yerlilik oranını %85\'e çıkaran \'Strateji