INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_482', 'modern', 'T129 ATAK Helikopterinin Seri Üretimi ve İhracatı', 'Savunma Sanayii Başkanlığı', 'Filipinler ve Nijerya\'ya ihraç edilen taarruz helikopteri terörle mücadelede kilit rol oynadı.', '[{"id":"char_savunma_sanayii_baskani","name":"Savunma Sanayii Başkanı"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Savunma sanayii projelerinin fikri mülkiyet ve patent haklarını devlet adına güvenceye alan yasal tescilleri yap.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Teknolojik mülkiyet korundu; milli projelerin yabancı şirketler tarafından taklit edilmesi önlendi."},{"label":"Yerli mühendis ordusu, üniversiteler ve KOBİ\'lerle teknoloji şurası toplayarak savunma ekosistemini tabana yay.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal ve sektörel uzlaşı sağlandı; binlerce yan sanayi firması milli savunma üretimine dahil oldu."},{"label":"Stratejik savunma sanayii Ar-Ge projeleri için Savunma Destekleme Fonu\'ndan Hazine destekli teşvik sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli savunma yatırımları finanse edildi; dışa bağımlılık azaltılarak ihracat potansiyeli artırıldı."},{"label":"Kritik savunma tesisleri ve Ar-Ge merkezlerinde casusluk ve sabotaja karşı askeri güvenlik kordonunu tahkim et.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik sırlar korundu; milli teknolojilere yönelik yabancı istihbarat operasyonları engellendi."},{"label":"Savunma sanayiinde yerlilik oranını %85\'e çıkaran \'Strate