INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_511', 'modern', 'Eskişehir Beylikova Nadir Toprak Elementleri Sahasında Küresel İstihbarat Savaşı', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Eskişehir Beylikova\'da elektrikli araç bataryaları, lazerler ve füze güdüm sistemleri için hayati önem taşıyan 694 milyon tonluk dünyanın ikinci en büyük Nadir Toprak Elementi (NTE) sahası keşfedildi. Çin, ABD ve AB merkezli maden kartellerinin sahayı kapatmak için baskı yaptığı istihbaratı masada.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Maden sahasının işletme imtiyazlarını tamamen kamu kurumu Eti Maden\'e ver; yabancı ortaklıkları bağımsız yargı denetimine bağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Stratejik madenler devlet tekelinde korundu; yabancı kartellerin rezervleri kapatması engellendi."},{"label":"Uluslararası teknoloji üreticileriyle stratejik ortaklık masası kur; madenleri ham olarak değil işlenmiş yüksek teknoloji olarak sat.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Katma değerli ihracat politikası benimsendi; hammadde sömürüsü önlendi."},{"label":"Beylikova\'da pilot cevher zenginleştirme ve işleme tesisinin kurulması için Hazine bütçesinden 250 milyon dolar kaynak aktar.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Milli cevher işleme tesisi kuruldu; Türkiye kritik elementleri kendi işleyen sayılı ülkeden biri oldu."},{"label":"Maden sahasında yabancı casusluk ve gizli numune kaçırma girişimlerine karşı MİT ve jandarma özel koruma timleri konuşlandır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Maden sahasından gizlice numune kaçırmaya çalışan yabancı teknisyenler yakalandı."},{"label":"Nadir toprak elementlerinin ham olarak yurtdışına ihracatını yasaklayan \'Stratejik Kritik Madenler Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Milli madenler kanuni kalkan altına alındı; Türkiye\'nin yeşil enerji ve savunma gücü tahkim edildi."}]', 511) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
