INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_518', 'modern', 'Oruç Reis Gemisinin Somali Açıklarında Petrol Görevi', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'İmzalanan askeri ve ekonomik anlaşmayla Türk sismik gemisi Somali denizlerinde petrol aramaya gitti.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Gabar ve Cudi dağlarında şehit düşen öğretmen Aybüke Yalçın ve jandarma Esma Çevik\'in adını kuyulara vererek milli hafızaya kazı.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Şehitlerimizin adı petrol kuyularında ölümsüzleşti; terör yuvaları milli zenginlik pınarına dönüştü."},{"label":"Günde 100 bin varil kaliteli petrol üreten sahalarda Şırnak ve bölge gençlerine istihdam ve meslek okulu aç.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Bölge kalkınması hızlandı; terörden arındırılan dağlarda petrol refahı kardeşliği perçinledi."},{"label":"Gabar petrolünün rafinerilere taşınmasıyla TPAO gelirlerini iki katına çıkar; Hazineye yıllık milyarlarca dolar tasarruf sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Türkiye\'nin petrol ihtiyacının %20\'si yerli kuyulardan karşılanmaya başladı; Hazine rahatladı."},{"label":"Cudi ve Gabar\'daki petrol kulelerini jandarma üs bölgeleri ve SİHA devriyeleriyle terör saldırılarına karşı koru.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Eski çatışma alanlarında kesintisiz huzur kuruldu; petrol konvoyları güvenle sevkiyat yaptı."},{"label":"Milli petrol arama ve maden imtiyazlarını genişleten \'Milli Petrol ve Hidrokarbon Seferberlik Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"TPAO dünyanın en güçlü milli petrol şirketlerinden biri oldu; arama ve sondaj filosu genişletildi."}]', 518) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_519', 'modern', 'Libya Deniz Yetki Alanı Mutabakatı ve Doğu Akdeniz\'de Savaş Gemileri Karşılaşması', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Türkiye ile Libya Milli Mutabakat Hükümeti arasında imzalanan deniz yetki alanları anlaşmasıyla Yunanistan-Mısır hattı kesildi ve Mavi Vatan sınırları tescillendi. Ancak Yunanistan, Fransa ve Hafter güçlerinin Oruç Reis ve Türk fırkateynlerine karşı bölgeye savaş gemileri göndermesiyle çatışma riski tırmandı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Libya mutabakat metnini derhal Birleşmiş Milletler\'e (BM) tescil ettir; uluslararası deniz hukuku önünde meşruiyet sağla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"BM anlaşmayı resmen tescil etti; Türkiye\'nin Akdeniz kıta sahanlığı uluslararası hukukun parçası oldu."},{"label":"Avrupa Birliği ve NATO arabuluculuğunda Yunanistan ile istişare kanallarını açık tut; çatışmasızlık protokolü imzala.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Ege ve Akdeniz\'de sıcak çatışma önlendi; tansiyon diplomasiyle yönetildi."},{"label":"Doğu Akdeniz hidrokarbon sondajları için TPAO\'ya Hazine fonu tahsis et; Libya açıklarında ortak petrol arama ruhsatları al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Stratejik enerji adımı atıldı; Türkiye Akdeniz\'deki enerji haklarını fiili adımlarla pekiştirdi."},{"label":"Deniz Kuvvetleri fırkateynleri, denizaltıları ve SİHA\'larıyla Oruç Reis gemisine \'dokunulmazlık\' koruma kordonu kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Türk donanması Akdeniz\'de çelik kalkan oldu; Yunan fırkateyninin taciz girişimi püskürtüldü."},{"label":"Mavi Vatan deniz yetki alanlarını milli harita ve anayasal güvenceye bağlayan \'Milli Deniz Güvenlik Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Türkiye\'nin Akdeniz\'deki sınırları kanunlaştı; Sevr benzeri Sevilla Haritası tarihin çöplüğüne atıldı."}]', 519) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_520', 'modern', 'Sinop Nükleer Santral Projesi Zemin Etütleri', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Karadeniz kıyısında ikinci nükleer santral için Güney Kore ve Rusya ile müzakereler yürütüldü.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Uluslararası Atom Enerjisi Ajansı (UAEA) ve Nükleer Düzenleme Kurumu (NDK) ile en katı sismik ve güvenlik teftişlerini uygula.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Nükleer güvenlik tescillendi; Akkuyu NGS uluslararası en üst seviye 3+ nesil VVER-1200 güvenlik zırhına kavuştu."},{"label":"Mersin halkı, ziraat odaları ve çevrecilerle düzenli bilgilendirme masası topla; deniz suyu sıcaklığı ve tarım endişelerini gider.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Toplumsal endişeler giderildi; radyasyon ölçüm istasyonları canlı olarak halkın erişimine açıldı."},{"label":"İlk taze nükleer yakıtın santrale gelmesiyle Türkiye\'yi resmen nükleer kulübe sok; yıllık 35 milyar kWh baz yük elektriği finanse et.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Türkiye nükleer güç statüsü kazandı; 4 reaktörün devreye girmesiyle elektriğin %10\'u sıfır karbonla üretilmeye başlandı."},{"label":"Santral çevresinde hava savunma füzeleri, radar sistemleri ve denizaltısavar kalkanıyla askeri düzeyde koruma çemberi kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik nükleer tesis koruma kalkanına alındı; hava ve deniz sahası tam kontrole bağlandı."},{"label":"Türkiye\'nin nükleer yakıt, atık yönetimi ve reaktör işletimini tanzim eden \'Nükleer Enerji ve Radyasyon Güvenliği Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Nükleer enerji hukuku inşa edildi; Sinop ve Trakya\'daki yeni santral projelerine yasal zemin açıldı."}]', 520) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_521', 'modern', 'Berat Albayrak\'ın Bakanlığı ve Yeni Ekonomi Modeli (2018)', 'Hazine ve Maliye Bakanlığı & TCMB', 'Hazine ve Maliye Bakanlığı döneminde düşük faiz ve cari fazla odaklı model hayata geçirildi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Ekonomik kararlarda hukuki öngörülebilirlik, rekabet kuralları ve mülkiyet hakkını tavizsiz gözet.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Hukuki güvence piyasaya hakim kılındı; yatırımcı güveni ve tüketici hakları korundu."},{"label":"İş dünyası, esnaf ve tüketici dernekleriyle istişare kurulları toplayarak piyasada fiyat istikrarı uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog işletildi; piyasadaki panik ve fiyatlama davranışlarındaki bozulma yatıştırıldı."},{"label":"Hazine kasasını korumak ve enflasyonu düşürmek için kamu harcamalarında sıkı tasarruf tedbirlerini tavizsiz uygula.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Mali disiplin tesis edildi; kamu bütçesi açık vermeden dengelendi."},{"label":"Stokçuluk, fahiş fiyat ve karaborsa fırsatçılarına karşı ticaret müfettişlerini ve zabıtayı sahaya dök.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasada fırsatçılara göz açtırılmadı; fahiş fiyat koyan zincirlere caydırıcı cezalar kesildi."},{"label":"Türkiye ekonomisinin yapısal reformlarını hayata geçiren \'Mali İstikrar ve Fiyat İstikrarı Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Yapısal reformlar yasalaştı; Türkiye sürdürülebilir büyüme ve dezenflasyon rotasına oturdu."}]', 521) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
