INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_525', 'modern', '20 Aralık 2021 Gecesi Kur Korumalı Mevduatın (KKM) İlanı', 'Hazine ve Maliye Bakanlığı & TCMB', 'Dolar 18 TL\'yi aşınca açıklanan KKM sistemiyle kur bir gecede 12 TL\'ye geriledi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"KKM sisteminin getirdiği kur farkı yükümlülüklerini anayasal bütçe hakkı çerçevesinde Sayıştay ve Meclis denetimine aç.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hazine yükümlülükleri şeffafça denetlendi; kamu kaynaklarının kullanımında hesap verilebilirlik sağlandı."},{"label":"TÜSİAD, MÜSİAD ve bankalarla görüşerek mudilerin döviz talebini kesen KKM mekanizmasının avantajlarını piyasaya anlat.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Piyasa paniği yatıştırıldı; döviz kurundaki çılgın tırmanış 20 Aralık gecesi sert şekilde kırıldı."},{"label":"KKM stokunu kademeli ve piyasayı sarsmadan eritmek için TL mevduat faizlerini cazip kıl; Hazine desteğini sonlandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine sırtındaki devasa kur farkı kamburundan kurtuldu; KKM hacmi 140 milyar dolardan hızla eridi."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan kayıt dışı finans çevrelerine karşı MASAK ve Mali Şube\'yi sahaya sür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Döviz büroları ve tezgah altı piyasalarda sıkı denetim kuruldu; manipülatif ataklar önlendi."},{"label":"Mevduat sisteminde TL\'yi önceleyen ve bütçeden kur farkı aktarımını sonlandıran \'Finansal Normalleşme Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Ortodoks para politikasına geçiş kanunlaştı; makroekonomik istikrar teminat altına alındı."}]', 525) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
