INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_527', 'modern', 'Enflasyonun %85 ile Son 25 Yılın Zirvesini Görmesi (2022)', 'Hazine ve Maliye Bakanlığı & TCMB', 'Gıda, enerji ve konut fiyatlarındaki artışla tüketici enflasyonu tarihi rekor kırdı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Ekonomik kararlarda hukuki öngörülebilirlik, rekabet kuralları ve mülkiyet hakkını tavizsiz gözet.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Hukuki güvence piyasaya hakim kılındı; yatırımcı güveni ve tüketici hakları korundu."},{"label":"İş dünyası, esnaf ve tüketici dernekleriyle istişare kurulları toplayarak piyasada fiyat istikrarı uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog işletildi; piyasadaki panik ve fiyatlama davranışlarındaki bozulma yatıştırıldı."},{"label":"Hazine kasasını korumak ve enflasyonu düşürmek için kamu harcamalarında sıkı tasarruf tedbirlerini tavizsiz uygula.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Mali disiplin tesis edildi; kamu bütçesi açık vermeden dengelendi."},{"label":"Stokçuluk, fahiş fiyat ve karaborsa fırsatçılarına karşı ticaret müfettişlerini ve zabıtayı sahaya dök.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Piyasada fırsatçılara göz açtırılmadı; fahiş fiyat koyan zincirlere caydırıcı cezalar kesildi."},{"label":"Türkiye ekonomisinin yapısal reformlarını hayata geçiren \'Mali İstikrar ve Fiyat İstikrarı Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Yapısal reformlar yasalaştı; Türkiye sürdürülebilir büyüme ve dezenflasyon rotasına oturdu."}]', 527) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_528', 'modern', 'Mehmet Şimşek\'in Kabineye Dönüşü: \'Rasyonel Zemine Döneceğiz\'', 'Hazine ve Maliye Bakanlığı & TCMB', '2023 seçimleri sonrası göreve gelen Şimşek geleneksel ortodoks para ve maliye politikalarını başlattı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Merkez Bankası\'nın araç bağımsızlığına ve fiyat istikrarı hedefine saygı göstererek faiz kararlarına siyasi müdahaleyi durdur.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Merkez Bankası bağımsızlığı korundu; küresel piyasalarda Türkiye\'nin ekonomi yönetimine güven tavan yaptı."},{"label":"İş dünyası, ihracatçılar ve sendikalarla \'Orta Vadeli Program\' (OVP) üzerinde mutabakat sağlayarak enflasyon hedeflerini açıkla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasalarla şeffaf iletişim kuruldu; OVP hedefleri reel sektör tarafından çıpa kabul edildi."},{"label":"Politika faizini kademeli olarak %50\'ye yükselt ve kamuda tasarruf genelgesiyle Hazine harcamalarını sıkı kontrol altına al.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Swap hariç net rezervler artıya geçti; yabancı sermaye girişiyle döviz rezervleri tarihi rekor kırdı."},{"label":"Kayıtdışı ekonomi, sahte fatura ve vergi kaçakçılarına karşı Maliye denetmenlerini ve vergi müfettişlerini sahaya dök.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Vergi tabanı genişletildi; lüks tüketim ve beyan edilmeyen gelirler sıkı denetimle vergilendirildi."},{"label":"Türkiye\'yi FATF Gri Listesi\'nden çıkaran ve kripto varlıkları regüle eden \'Mali Eylem ve Tasarruf Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Türkiye gri listeden başarıyla çıktı; kredi derecelendirme kuruluşları Türkiye\'nin notunu peş peşe artırdı."}]', 528) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
