INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_534', 'modern', 'KKM Stokunun 140 Milyar Dolardan Eritilmesi Programı', 'Hazine ve Maliye Bakanlığı & TCMB', 'Alınan makroihtiyati tedbirlerle mudiler standart TL mevduata geçirilerek KKM küçültüldü.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"KKM sisteminin getirdiği kur farkı yükümlülüklerini anayasal bütçe hakkı çerçevesinde Sayıştay ve Meclis denetimine aç.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Hazine yükümlülükleri şeffafça denetlendi; kamu kaynaklarının kullanımında hesap verilebilirlik sağlandı."},{"label":"TÜSİAD, MÜSİAD ve bankalarla görüşerek mudilerin döviz talebini kesen KKM mekanizmasının avantajlarını piyasaya anlat.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Piyasa paniği yatıştırıldı; döviz kurundaki çılgın tırmanış 20 Aralık gecesi sert şekilde kırıldı."},{"label":"KKM stokunu kademeli ve piyasayı sarsmadan eritmek için TL mevduat faizlerini cazip kıl; Hazine desteğini sonlandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine sırtındaki devasa kur farkı kamburundan kurtuldu; KKM hacmi 140 milyar dolardan hızla eridi."},{"label":"Döviz spekülasyonu yapan ve kara para aklayan kayıt dışı finans çevrelerine karşı MASAK ve Mali Şube\'yi sahaya sür.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Döviz büroları ve tezgah altı piyasalarda sıkı denetim kuruldu; manipülatif ataklar önlendi."},{"label":"Mevduat sisteminde TL\'yi önceleyen ve bütçeden kur farkı aktarımını sonlandıran \'Finansal Normalleşme Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Ortodoks para politikasına geçiş kanunlaştı; makroekonomik istikrar teminat altına alındı."}]', 534) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_535', 'modern', 'Enflasyon Düzeltmesi (Muhasebesi) ve Reel Kazanç-Vergi Adaleti Krizi', 'Hazine ve Maliye Bakanlığı & TCMB', 'Yüksek enflasyon ortamında sanayici ve KOBİ\'lerin henüz realize olmamış kârları üzerinden fahiş vergi ödemek zorunda kalması üretimi durma noktasına getirirken, Maliye bütçe gelirlerinin erimesinden endişe ediyor.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Enflasyon düzeltmesini küçük esnaf ve KOBİ\'ler için vergisel yük getirmeyecek şekilde muaf tut; sadece dev holdinglere uygula.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Milyonlarca küçük üretici fahiş fiktif vergiden korundu; holdinglerden adil pay alındı."},{"label":"Bütçe açığını kapatmak için enflasyon düzeltmesini istisnasız tüm bilanço sahibi şirketlere tavizsiz uygula.","preview":"Adalet +4, Hazine +9, Otorite +6 | Halk -6","effects":{"justice":4,"people":-6,"treasury":9,"military":0,"authority":6},"log":"Hazine kasasına kısa vadeli devasa vergi girişi sağlandı; ancak reel sektörde iflaslar tetiklendi."},{"label":"Şirketlerin fiktif kârları yerine sadece net nakit akışını ve yatırıma yönelen sermayeyi vergiden düşen \'Üretim Reformu\' yap.","preview":"Adalet +8, Halk +7, Otorite +7 | Hazine -5","effects":{"justice":8,"people":7,"treasury":-5,"military":0,"authority":7},"log":"Üretim ve Ar-Ge yatırımları teşvik edildi; fabrikaların kapısına kilit vurulması önlendi."},{"label":"Vergi müfettişlerini stokçuluk ve çifte defter tutan kayıt dışı zenginlere yönlendirerek vergi tabanını genişlet.","preview":"Adalet +9, Halk +6, Hazine +7, Otorite +8","effects":{"justice":9,"people":6,"treasury":7,"military":0,"authority":8},"log":"Dürüst mükellef korunurken kayıt dışı rant ekonomisine ağır denetim getirildi."},{"label":"Vergi uyuşmazlıklarında mükelleflere dava açmak yerine faizsiz 24 ay taksitlendirme ve uzlaşma komisyonu hakkı tanı.","preview":"Adalet +6, Halk +7, Hazine +4, Otorite +5","effects":{"justice":6,"people":7,"treasury":4,"military":0,"authority":5},"log":"Vergi mahkemelerindeki tıkanıklık aşıldı, Hazineye düzenli nakit akışı bağlandı."}]', 535) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
