INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_539', 'modern', 'Konut Kiralarında 2 Yıl Süreyle Uygulanan %25 Zam Tavanı', 'Hazine ve Maliye Bakanlığı & TCMB', 'Kiracıları korumak amacıyla getirilen kira artış sınırı ev sahibi-kiracı davalarını patlattı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Ev sahibi ve kiracı arasındaki davalarda Borçlar Kanunu ve hakkaniyet ilkelerini gözeterek tahliye davalarında yığılmayı önle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sulh Hukuk Mahkemeleri\'nde adli süreçler hızlandırıldı; haksız tahliye ve fırsatçı zamlara sınır getirildi."},{"label":"Kira uyuşmazlıklarında \'Zorunlu Arabuluculuk\' mekanizmasını devreye sokarak tarafların %60\'ının mahkemesiz sulh olmasını sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Yüz binlerce dosya mahkemeye gitmeden arabulucuda çözüldü; komşuluk ve kira barışı korundu."},{"label":"Dar gelirli kiracılar için Hazine destekli \'Sosyal Konut Seferberliği\' başlatarak piyasadaki fahiş kira balonunu patlat.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Arz tarafı güçlendirildi; TOKİ eliyle 250 bin sosyal konut inşa edilerek kira enflasyonu dizginlendi."},{"label":"Kayıt dışı kiralama yapan, elden nakit para alan ve yabancılara yasadışı kiralık ev tutanlara karşı maliye zabıtasını denetime çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Kiralık konut piyasasında mali denetim sağlandı; vergi kaçıran ev sahiplerine ağır cezalar kesildi."},