INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_543', 'modern', 'Asgari Ücret Tespit Komisyonu\'nun Yılda İki Kez Toplanması', 'Hazine ve Maliye Bakanlığı & TCMB', 'Enflasyon karşısında eriyen maaşlar için 2022 ve 2023 yıllarında Temmuz ayında ara zamlar yapıldı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Çalışanların refahını korumak için asgari ücretten gelir ve damga vergisini tamamen kaldıran anayasal sosyal adalet adımını at.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi vergi devrimi yapıldı; tüm çalışanların maaşındaki vergi yükü devlet tarafından üstlenildi."},{"label":"TÜRK-İŞ, TİSK ve hükümet heyetiyle Asgari Ücret Tespit Komisyonu\'nda enflasyonu ezen dengeli bir mutabakat imzala.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milyonlarca işçinin yüzü güldü; ara zamlarla çalışanlar yüksek enflasyona karşı korundu."},{"label":"EYT düzenlemesiyle emekli olan 2 milyon vatandaşın kıdem tazminatı için işverenlere KGF kefaletli Hazine kredisi aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İş dünyasının nakit krizi önlendi; EYT\'lilerin tazminatları ve ilk emekli maaşları tıkır tıkır ödendi."},{"label":"Sahte işyeri açıp kendisini sigortalı göstererek haksız emekli olan şebekelere karşı SGK denetmenlerini seferber et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sahte sigortalılık çeteleri çökertildi; kamunun milyarlarca liralık emeklilik kaynağı korundu."},{"label":"Emekli taban aylıklarını ve sosyal güvenlik dengesini sürdürülebilir kılan \'Sosyal Güvenlik ve Emeklilik Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Emeklilerin kök maaş mağduriyetleri giderildi; sosyal güvenlik sistemi kalıcı bütçe zırhına kavuşturuldu."}]', 543) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
