INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_546', 'modern', 'En Düşük Emekli Maaşına Hazine Desteğiyle Taban Tutar', 'Hazine ve Maliye Bakanlığı & TCMB', 'Kök maaşı düşük kalan emeklilerin aylıkları Hazine sübvansiyonuyla 12.500 TL tabanına bağlandı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_merkez_bankasi_baskani","name":"Merkez Bankası Başkanı"}]', '[{"label":"Ekonomik kararlarda hukuki öngörülebilirlik, rekabet kuralları ve mülkiyet hakkını tavizsiz gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki güvence piyasaya hakim kılındı; yatırımcı güveni ve tüketici hakları korundu."},{"label":"İş dünyası, esnaf ve tüketici dernekleriyle istişare kurulları toplayarak piyasada fiyat istikrarı uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog işletildi; piyasadaki panik ve fiyatlama davranışlarındaki bozulma yatıştırıldı."},{"label":"Hazine kasasını korumak ve enflasyonu düşürmek için kamu harcamalarında sıkı tasarruf tedbirlerini tavizsiz uygula.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Mali disiplin tesis edildi; kamu bütçesi açık vermeden dengelendi."},{"label":"Stokçuluk, fahiş fiyat ve karaborsa fırsatçılarına karşı ticaret müfettişlerini ve zabıtayı sahaya dök.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Piyasada fırsatçılara göz açtırılmadı; fahiş fiyat koyan zincirlere caydırıcı cezalar kesildi."},{"label":"Türkiye ekonomisinin yapısal reformlarını hayata geçiren \'Mali İstikrar ve Fiyat İstikrarı Reform Kanunu\' çıkar.","preview