INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_553', 'modern', 'e-Nabız Kişisel Sağlık Sistemi ve Tüm Tıbbi Geçmişin Ekranı', 'BTK & MASAK & Emniyet Siber', 'Hastanelerdeki tahlil, röntgen ve reçeteler vatandaşın cep telefonuna yüklendi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Dijital suçlar, internet dolandırıcılığı ve yasadışı bahis faaliyetlerine karşı adli soruşturmaları tavizsiz yürüt.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Siber suçlular adalet önüne çıkarıldı; vatandaşların dijital ortamdaki hak ve güvenliği korundu."},{"label":"Bilişim sektörü, yazılımcılar ve sivil toplumla istişare ederek milli yazılım ve yapay zeka ekosistemini destekle.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sektörel uzlaşı sağlandı; yerli teknoloji girişimlerinin önü açıldı."},{"label":"Siber güvenlik ve dijitalleşme altyapısı yatırımları için Hazine fonlarından teknolojik Ar-Ge desteği tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dijital dönüşüm Hazine kaynaklarıyla hızlandırıldı; kamu veri güvenliği tahkim edildi."},{"label":"Siber suç şebekelerine ve korsan çağrı merkezlerine karşı emniyet siber timlerini eşzamanlı operasyona sür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Siber çeteler çökertildi; vatandaşları dolandıran sahte çağrı merkezleri mühürlendi."},{"label":"Dijital veri güvenliği ve yapay zeka etiğini düzenleyen \'Milli Dijitalleşme ve Bilişim Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Bilişim mevzuatı çağın gereksinimlerine göre yenilendi; kurumsal siber güvenlik sağlandı."}]', 553) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
