INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_569', 'modern', 'Mehmet Aydın (Tosuncuk) Çiftlik Bank Saadet Zinciri Dolandırıcılığı', 'BTK & MASAK & Emniyet Siber', 'Sanal ineklerle yüksek kar vaat eden saadet zinciriyle yüz binlerce kişiyi dolandıran zanlı kaçtı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Lüks hayat paylaşımları arkasındaki yasadışı bahis, naylon fatura ve kara para aklama çarkını MASAK raporuyla savcılığa ver.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Sosyal medya fenomenlerinin lüks saltanatı adliyede bitti; örgüt liderleri ve yöneticileri tutuklandı."},{"label":"Mağdur olan franchise sahipleri ve güzellik merkezi çalışanlarının haklarını korumak için kayyum heyeti oluştur.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"İşletmelerde çalışan masum personelin işsiz kalması önlendi; merkezlerin faaliyetleri denetim altına alındı."},{"label":"Şüphelilerin yüzlerce lüks aracına, villalarına ve şirketlerine TMSF marifetiyle el koyup Hazineye devret.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Lüks spor arabalar polis aracı yapıldı; kara para şebekesinin serveti kamuya irad kaydedildi."},{"label":"Mali Şube ve Organize Suçlar timleriyle şüphelilerin şirket merkezlerine ve villalarına şafak baskını yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Deliller karartılmadan kasalara ve belgelere el konuldu; kayıt dışı para trafiği çökertildi."},{"label":"Sosyal medya üzerinden yürütülen kayıt dışı ticaret ve bahis rekl