INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_570', 'modern', 'Mehmet Aydın\'ın Brezilya\'da Teslim Oluşu ve Kartal Cezaevi', 'BTK & MASAK & Emniyet Siber', 'Brezilya Sao Paulo elçiliğine teslim olan Tosuncuk Türkiye\'ye getirilerek yargılanmaya başlandı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Dijital suçlar, internet dolandırıcılığı ve yasadışı bahis faaliyetlerine karşı adli soruşturmaları tavizsiz yürüt.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Siber suçlular adalet önüne çıkarıldı; vatandaşların dijital ortamdaki hak ve güvenliği korundu."},{"label":"Bilişim sektörü, yazılımcılar ve sivil toplumla istişare ederek milli yazılım ve yapay zeka ekosistemini destekle.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Sektörel uzlaşı sağlandı; yerli teknoloji girişimlerinin önü açıldı."},{"label":"Siber güvenlik ve dijitalleşme altyapısı yatırımları için Hazine fonlarından teknolojik Ar-Ge desteği tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dijital dönüşüm Hazine kaynaklarıyla hızlandırıldı; kamu veri güvenliği tahkim edildi."},{"label":"Siber suç şebekelerine ve korsan çağrı merkezlerine karşı emniyet siber timlerini eşzamanlı operasyona sür.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Siber çeteler çökertildi; vatandaşları dolandıran sahte çağrı merkezleri mühürlendi."},{"label":"Dijital veri güvenliği ve yapay zeka etiğini düzenleyen \'Milli Dijitalleşme ve Bilişim Kanunu\' çıkar.","preview":"Adalet +7, Halk +5,