INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_571', 'modern', 'TBMM Kripto Varlık Yasası: SPK Lisansı ve Ağır Denetim', 'BTK & MASAK & Emniyet Siber', 'Kripto para borsalarını devlet kontrolüne alan ve sermaye şartı getiren yasa kabul edildi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Interpol Kırmızı Bülteni çıkar ve firari Faruk Fatih Özer\'in Arnavutluk\'tan iadesini diplomatik ve adli kanallarla sağla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Firari şüpheli Türkiye\'ye getirildi; 40 bin yılı aşan rekor ceza istemiyle hakim karşısına çıkarıldı."},{"label":"Kripto varlık mağdurlarıyla kriz masasında buluş; tasfiye masasındaki paraların hak sahiplerine dağıtımını koordine et.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Mağdurların sesi dinlendi; şirket hesaplarındaki blokeli varlıklar tasfiye masasına aktarıldı."},{"label":"Şirketin tüm banka hesapları, kripto soğuk cüzdanları ve menkul varlıklarına MASAK marifetiyle derhal bloke koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milyonlarca dolarlık kripto varlık donduruldu; paraların yurtdışına kaçırılması önlendi."},{"label":"Siber Suçlarla Mücadele Daire Başkanlığı bünyesinde zincir üstü (on-chain) cüzdan takip timi kurup transferleri izle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sanal takip ağı kuruldu; kripto paraların aklanmaya çalışıldığı borsalar tek tek tespit edildi."},{"label":"SPK lisansı ve asgari 100 milyon TL sermaye teminatı getiren \'Kripto Varlık Hiz