INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_573', 'modern', 'Fenomenler Dosyası: MASAK\'ın Sosyal Medya Zenginleri İncelemesi', 'BTK & MASAK & Emniyet Siber', 'Güzellik salonları ve e-ticaret üzerinden fatura kesen onlarca fenomenin şirketlerine kayyum atandı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Katalog suçlar (çocuk istismarı, terör, intihara yönlendirme) sebebiyle platformun Türkiye temsilcilik açmasını şart koş.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Egemenlik hakları korundu; küresel platformlar Türk kanunlarına uymayı ve temsilci atamayı kabul etti."},{"label":"Dijital içerik üreticileri ve e-ticaret esnafıyla görüşerek platform engellerinin ekonomik zararlarını asgaride tut.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Esnafın mağduriyeti dinlendi; şirketle yapılan müzakerelerin ardından platformlar kurallara uyarak açıldı."},{"label":"Türkiye\'de milyarlarca dolar reklam geliri elde edip vergi kaçıran küresel teknoloji devlerine %7.5 Dijital Hizmet Vergisi koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dijital devler vergi mükellefi yapıldı; Hazineye yıllık milyarlarca liralık vergi geliri girdi."},{"label":"BTK ve Siber Suçlarla Mücadele Dairesi\'ne siber zorbalık ve pedofili ağlarına karşı anında IP erişim engeli yetkisi ver.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Çocuklar ve gençler dijital bataklıktan korundu; sapkın şantaj çetelerinin sunucuları çökertildi."},{"label":"Sosyal medya platformlarının Türkçe içerik denetimi ve mahkeme kararlarına uymasını zorunlu kılan \'Sosyal Medya Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Siber vatanda egemenlik tescillendi; platformların keyfi sansür ve kural tanımazlığı kanunla durduruldu."}]', 573) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
