INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_581', 'modern', 'Narin Güran Cinayeti: 19 Gün Sonra Çuvalda Bulunan Melek', 'Adalet Bakanlığı & Adli Tıp', 'Diyarbakır Tavşantepe köyünde kaybolan 8 yaşındaki Narin dere yatağında çuval içine gizlenmiş bulundu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Tavşantepe köyündeki cinayeti örten organize suskunluk çemberini özel jandarma istihbaratı ve kriminal DNA ile kır; tüm failleri tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Adalet yerini buldu; küçük meleğin katilleri ve delilleri karartan tüm akraba ağı ağırlaştırılmış müebbet istemiyle hakim karşısına çıkarıldı."},{"label":"Bölgedeki kadın dernekleri, barolar ve sivil toplumla ortaklaşa çocuk koruma seferberliği ilan et; köydeki çocukları devlet korumasına al.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milletin vicdanı teskin edildi; çocukların feodal baskı ve aile içi istismardan korunması için devlet zırhı sağlandı."},{"label":"Davanın aydınlatılması için Adli Tıp, kriminal laboratuvarlar ve arama operasyonlarına sınırsız Hazine ödeneği sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Devletin tüm imkanları seferber edildi; tek bir karanlık nokta bırakılmaması için teknik analizler tamamlandı."},{"label":"Köy çevresinde komando ve jandarma kordonu kurarak delil karartma, telefon sıfırlama ve tanıkları tehdit etme girişimlerini engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Köyde tam adli kontrol sağlandı; organize suç örgütü gibi hareket eden şebeke çökertildi."},{"label":"Çocuk cinayetlerinde ve cinsel istismarda af ve infaz indirimini kesin olarak yasaklayan \'Narin Çocuk Koruma Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Çocuklara kalkan olan tarihi kanun kabul edildi; çocuk katillerine af kapısı ebediyen kapatıldı."}]', 581) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_582', 'modern', 'Tavşantepe Köyündeki Sessizlik Duvarı ve Aile Boyu Tutuklamalar', 'Adalet Bakanlığı & Adli Tıp', 'Cinayeti gizlemek için organize olan muhtar amca Salim Güran, anne, ağabey ve itirafçı tutuklandı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Vicdanları yaralayan adli vakada hukukun üstünlüğü, şeffaflık ve adil yargılanma ilkelerini tavizsiz işlet.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuk devleti işletildi; failler mahkemede adil ve ağır cezalarla yargılandı."},{"label":"Mağdur aileler, barolar ve sivil toplumla istişare ederek toplumsal adalet ve vicdan beklentisini karşıla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal infial dindirildi; devletin adalet dağıtıcı şefkati halka hissettirildi."},{"label":"Mağdurların rehabilitasyonu ve adli yardım masrafları için Adalet bütçesinden özel fon tahsis et.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Mağdur hakları finanse edildi; adli süreçlerde ailelerin yalnız kalması önlendi."},{"label":"Toplumsal infial yaratan olaylarda provokasyonlara ve linç girişimlerine karşı kolluk tedbirlerini sıkı tut.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sokak asayişi korundu; adaletin sokakta değil mahkeme salonlarında tecelli etmesi sağlandı."},{"label":"Mağdur haklarını ve adil yargılanma standartlarını yükselten \'Toplumsal Adalet Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Ceza mevzuatı güncellendi; benzer vicdani faciaların önü kurumsal kanunlarla kesildi."}]', 582) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_583', 'modern', 'Yenidoğan Çetesi Skandalı: Bebek Acil Hastalarını Para İçin Öldüren Ağ', 'Adalet Bakanlığı & Adli Tıp', 'İstanbul\'da 112 sevklerini manipüle ederek bebekleri anlaşmalı özel hastanelerde yoğun bakımda ölüme terk eden çete deşifre oldu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_saglik_bakani","name":"Sağlık Bakanı"}]', '[{"label":"SGK\'dan para almak için bebekleri yoğun bakımda ölüme terk eden çetenin doktor ve yöneticilerini \'kasten öldürme\'den tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Cumhuriyet tarihinin en vahşi sağlık çetesi çökertildi; savcıyı tehdit eden tetikçiler dahil tüm failler cezaevine tıkıldı."},{"label":"Evlatlarını kaybeden acılı ailelerle Sağlık Bakanlığı\'nda kriz masası topla; bebeklerin naklini devlet hastanelerine güvenle sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Ailelerin feryadına sahip çıkıldı; bebek yoğun bakımları tamamen kamunun güvenli ellerine devredildi."},{"label":"Çeteye karışan 10 özel hastanenin ruhsatlarını derhal iptal et ve SGK\'dan haksız aldıkları yüz milyonlarca lirayı Hazineye tahsil et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hastaneler kapatıldı ve mühürlendi; kamunun hortumlanan kaynakları faiziyle kasaya geri aktarıldı."},{"label":"Soruşturmayı yürüten Cumhuriyet Savcısı Engin Göknar\'ı makamında tehdit eden mafya artıklarına adliyede ters kelepçe taktır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Devletin savcısına pusu kurmaya kalkanlar saatler içinde yakalandı; devletin heybeti gösterildi."},{"label":"Özel hastanelerin yoğun bakım işletmelerini taşeronlaştırmasını yasaklayan \'Özel Hastaneler Teftiş ve Bebek Güvenliği Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Sağlıkta taşeronluk vahşeti yasaklandı; tüm yoğun bakımlar bakanlığın anlık yapay zeka denetimine bağlandı."}]', 583) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_584', 'modern', 'Büyükçekmece Savcısı Yavuz Engin\'in Makamında Tehdit Edilmesi', 'Adalet Bakanlığı & Adli Tıp', 'Çete avukatının savcıyı makamında \'seni öldürürüz\' tehdidine savcının boyun eğmeyip çeteyi çökertmesi destan oldu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_saglik_bakani","name":"Sağlık Bakanı"}]', '[{"label":"Vicdanları yaralayan adli vakada hukukun üstünlüğü, şeffaflık ve adil yargılanma ilkelerini tavizsiz işlet.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuk devleti işletildi; failler mahkemede adil ve ağır cezalarla yargılandı."},{"label":"Mağdur aileler, barolar ve sivil toplumla istişare ederek toplumsal adalet ve vicdan beklentisini karşıla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal infial dindirildi; devletin adalet dağıtıcı şefkati halka hissettirildi."},{"label":"Mağdurların rehabilitasyonu ve adli yardım masrafları için Adalet bütçesinden özel fon tahsis et.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Mağdur hakları finanse edildi; adli süreçlerde ailelerin yalnız kalması önlendi."},{"label":"Toplumsal infial yaratan olaylarda provokasyonlara ve linç girişimlerine karşı kolluk tedbirlerini sıkı tut.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sokak asayişi korundu; adaletin sokakta değil mahkeme salonlarında tecelli etmesi sağlandı."},{"label":"Mağdur haklarını ve adil yargılanma standartlarını yükselten \'Toplumsal Adalet Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, O