INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_586', 'modern', 'Münevver Karabulut Cinayeti (2009) ve Testereli Vahşet', 'Adalet Bakanlığı & Adli Tıp', 'Bahçeşehir\'de cesedi gitar kılıfında çöp konteynerinde bulunan genç kızın davası Türkiye\'yi ağlattı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Kadın cinayetlerinde faillere \'iyi hal indirimi\', \'kravat indirimi\' ve \'haksız tahrik indirimi\' uygulanmasını yargıda kesin olarak yasakla.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Kadın katillerine hukuk zırhı delindi; hiçbir indirim uygulanmadan ağırlaştırılmış müebbet cezaları onandı."},{"label":"Milyonlarca kadının meydanlara çıktığı gün adalet yürüyüşlerine destek ver; kadına şiddete karşı topyekun seferberlik ilan et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Millet kadınların çığlığına sahip çıktı; \'Ölmek İstemiyorum\' feryadı devlet politikasına dönüştürüldü."},{"label":"81 ilde Şiddet Önleme ve İzleme Merkezleri (ŞÖNİM) ve kadın sığınma evleri için Hazine bütçesinden özel ödenek ayır.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Şiddet mağduru kadınlara güvenli sığınak ve nakdi destek sağlandı; devlet himayesi tahkim edildi."},{"label":"Emniyet bünyesinde KADES uygulamasını ve Elektronik Kelepçe İzleme Merkezi\'ni kurarak saldırganları 7/24 uydudan izle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"KADES butonuyla binlerce kadının hayatı kurtarıldı; uzaklaştırma alan saldırganlar yakınına dahi yakl