INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_591', 'modern', 'Pınar Gültekin Cinayeti ve Haksız Tahrik İndiriminin Bozulması', 'Adalet Bakanlığı & Adli Tıp', 'Muğla\'da varilde yakılan üniversite öğrencisinin katiline verilen tahrik indirimi Yargıtay\'ca iptal edildi.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Vicdanları yaralayan adli vakada hukukun üstünlüğü, şeffaflık ve adil yargılanma ilkelerini tavizsiz işlet.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuk devleti işletildi; failler mahkemede adil ve ağır cezalarla yargılandı."},{"label":"Mağdur aileler, barolar ve sivil toplumla istişare ederek toplumsal adalet ve vicdan beklentisini karşıla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal infial dindirildi; devletin adalet dağıtıcı şefkati halka hissettirildi."},{"label":"Mağdurların rehabilitasyonu ve adli yardım masrafları için Adalet bütçesinden özel fon tahsis et.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Mağdur hakları finanse edildi; adli süreçlerde ailelerin yalnız kalması önlendi."},{"label":"Toplumsal infial yaratan olaylarda provokasyonlara ve linç girişimlerine karşı kolluk tedbirlerini sıkı tut.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sokak asayişi korundu; adaletin sokakta değil mahkeme salonlarında tecelli etmesi sağlandı."},{"label":"Mağdur haklarını ve adil yargılanma standartlarını yükselten \'Toplumsal Adalet Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite 