INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_601', 'modern', 'Çorlu Tren Faciası Davası (2018): 25 Can Kaybı ve Bürokratlar', 'Adalet Bakanlığı & Adli Tıp', 'Menfezin altının boşalmasıyla devrilen tren için TCDD üst yöneticileri ağır cezalara çarptırıldı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Faciada ihmali ve kusuru bulunan maden patronları, bürokratlar ve denetimciler hakkında \'olası kastla öldürme\'den ceza ver.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"İş kazası değil katliam tescillendi; patronlar ve sorumlular Ağır Ceza Mahkemesi\'nde onlarca yıl hapse mahkum edildi."},{"label":"Şehit madenci ve tren yolcusu aileleriyle bir araya gelerek her aileye bir devlet memuriyeti ve konut desteği sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Yetim kalan evlatlara devlet sahip çıktı; madenci ailelerinin gelecekleri devlet teminatına alındı."},{"label":"Faciaya yol açan maden ocaklarını ve demiryolu hatlarını baştan sona yenilemek için Hazine afet bütçesini tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Madenlerde ve demiryollarında altyapı yenilendi; Hazine kaynaklarıyla modern sinyalizasyon ve yaşam odaları kuruldu."},{"label":"İş güvenliği kurallarına uymayan tüm maden ocaklarını Çalışma Bakanlığı ve polis zoruyla derhal mühürle.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"İş güvenliği tavizsiz uygulandı; kurallara uymayan vahşi işletmelerin çalışmasına izin verilmedi."},{"label":"Madenlerde zorunlu \'Sığınma Odaları\' (Yaşam Odası) ve demiryollarında meteorolojik erken uyarı şartı getiren reform kanunu çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"İşçi sağlığı ve can güvenliği kanunla korundu; madenlerde yaşam odası zorunlu hale getirildi."}]', 601) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
