INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_611', 'modern', '8 Yıllık Kesintisiz Zorunlu İlköğretim Yasası (1997)', 'Milli Eğitim Bakanlığı & YÖK', '28 Şubat kararları doğrultusunda çıkarılan yasayla ilkokul ve ortaokul birleştirilerek kesintisiz yapıldı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_basbakan","name":"Başbakan"}]', '[{"label":"Eğitimde liyakat, fırsat eşitliği ve öğretmenlik meslek standartlarını anayasal kurallarla koru.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Eğitimde fırsat eşitliği gözetildi; tüm öğrencilerin eğitime erişim hakkı korundu."},{"label":"Öğretmen sendikaları, veliler ve eğitim bilimcilerle ortak milli eğitim şurası toplayarak müfredat uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Eğitim camiası ile diyalog kuruldu; okullarda huzur ve motivasyon sağlandı."},{"label":"Okulların teknolojik altyapısı, akıllı tahta ve ücretsiz yemek dağıtımı için Hazine bütçesinden kaynak ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Okulların fiziki imkanları güçlendirildi; eğitim yatırımları bütçeden karşılandı."},{"label":"Okul çevrelerinde uyuşturucu tacirleri ve çetelere karşı \'Güvenli Okul\' polis devriyelerini görevlendir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Okul kapılarında tam güvenlik sağlandı; çocuklarımız zararlı alışkanlıklardan korundu."},{"label":"Türkiye Yüzyılı maarif vizyonunu hayata geçiren \'Milli Eğitim ve Öğretmenlik Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Eğitim sistemi çağdaş standartlarla yenilendi; nesillerin geleceği teminat altına alındı."}]', 611) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_612', 'modern', 'İmam Hatip Liselerine Katsayı Engeli Uygulaması', 'Milli Eğitim Bakanlığı & YÖK', 'Meslek liselilerin üniversite sınavında katsayı puanlarının düşürülmesi milyonlarca öğrenciyi mağdur etti.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Üniversitelerde ve kamuda kılık-kıyafet yasağı ve katsayı adaletsizliğini anayasal eşitlik ilkesiyle tamamen bitir.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi zulüm son buldu; başörtülü kızlar ikna odalarından kurtularak tıp, hukuk ve mühendislik fakültelerini birincilikle bitirdi."},{"label":"Öğrenci kulüpleri, akademisyenler ve sivil toplumla görüşerek kampüslerde barış ve özgürlük iklimini kurumsallaştır.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Üniversitelerde kucaklaşma sağlandı; ideolojik kutuplaşmanın yerini bilimsel çalışma aldı."},{"label":"Meslek liseleri ve İmam Hatiplerin laboratuvar ve atölye altyapısını güçlendirmek için Hazine destekli teşvikler sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mesleki eğitim ihya edildi; sanayinin nitelikli eleman ihtiyacı giderildi."},{"label":"Yasağın kaldırılmasına karşı kampüslerde provokasyon ve baskı yapmaya kalkan kliklere karşı üniversite güvenliğini koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Öğrencilerin eğitim hakkı korundu; hiç kimsenin kılık-kıyafetinden dolayı engellenmesine izin verilmedi."},{"label":"Kamuda ve üniversitelerde temel hak ve hürriyetleri teminat altına alan \'Eğitimde Fırsat Eşitliği Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Katsayı ve başörtüsü engelleri tarihe gömüldü; tüm evlatlarımız anayasal eşitliğe kavuştu."}]', 612) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_613', 'modern', '28 Şubat Mirası Katsayı Engeli ve Sanayide Nitelikli Çırak Krizi', 'Milli Eğitim Bakanlığı & YÖK', 'Meslek lisesi ve imam hatip mezunlarının üniversiteye girişini engelleyen katsayı sistemi sanayide teknik eleman krizine yol açarken, vesayetçi bürokrasi Danıştay üzerinden engeli sürdürmek için hükümete direniyor.', '[{"id":"char_milli_egitim_bakani","name":"Milli Eğitim Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Katsayı adaletsizliğini YÖK ve TBMM kanun değişikliğiyle tamamen tarihe göm; her gence eşit puan hakkı ver.","preview":"Adalet +9, Halk +9, Otorite +8","effects":{"justice":9,"people":9,"treasury":0,"military":0,"authority":8},"log":"Eğitimde 28 Şubat vesayeti parçalandı; milyonlarca gencin üniversite yolu eşitlendi."},{"label":"Meslek liselerini doğrudan organize sanayi bölgeleriyle (OSB) entegre edip mezunlara istihdam ve yüksek maaş garantisi getir.","preview":"Adalet +7, Halk +8, Otorite +7 | Hazine -5","effects":{"justice":7,"people":8,"treasury":-5,"military":0,"authority":7},"log":"Sanayinin \'ara eleman değil aranan eleman\' ihtiyacı çözüldü; üretim hamlesi hızlandı."},{"label":"Yargı vesayetinin engelleme kararlarına karşı Anayasa Mahkemesi ve idari reformlarla direnci kır.","preview":"Adalet +8, Halk +7, Otorite +8","effects":{"justice":8,"people":7,"treasury":0,"military":0,"authority":8},"log":"Hukuksuz bürokratik engeller aşıldı; devlet idaresinde seçilmiş irade pekiştirildi."},{"label":"Meslek lisesi mezunlarına kendi alanlarında mühendislik okumaları için özel ek puan ve burs kontenjanı tahsis et.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Teknik liselerden yetişen genç mühendisler yerli savunma ve otomotiv sektörünün omurgası oldu."},{"label":"Tüm liselerde müfredatı sadeleştirip temel bilimler ve kodlama eğitimini zorunlu hale getir.","preview":"Adalet +6, Halk +7, Otorite +5 | Hazine -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":5},"log":"Gençliğin küresel teknoloji rekabetine hazırlanması için modern müfredat devreye girdi."}]', 613) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_614', 'modern', 'Üniversitelerde Başörtüsü Yasağı ve İkna Odaları Travması', 'Milli Eğitim Bakanlığı & YÖK', 'Üniversite kapılarında başörtülü öğrencilerin peruk takmaya veya başını açmaya zorlanması kriz yarattı.', '[{"id":"char_anayasa_mahkemesi_baskani","name":"Anayasa Mahkemesi Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Üniversitelerde ve kamuda kılık-kıyafet yasağı ve katsayı adaletsizliğini anayasal eşitlik ilkesiyle tamamen bitir.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi zulüm son buldu; başörtülü kızlar ikna odalarından kurtularak tıp, hukuk ve mühendislik fakültelerini birincilikle bitirdi."},{"label":"Öğrenci kulüpleri, akademisyenler ve sivil toplumla görüşerek kampüslerde barış ve özgürlük iklimini kurumsallaştır.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Üniversitelerde kucaklaşma sağlandı; ideolojik kutuplaşmanın yerini bilimsel çalışma aldı."},{"label":"Meslek liseleri ve İmam Hatiplerin laboratuvar ve atölye altyapısını güçlendirmek için Hazine destekli teşvikler sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mesleki eğitim ihya edildi; sanayinin nitelikli eleman ihtiyacı giderildi."},{"label":"Yasağın kaldırılmasına karşı kampüslerde provokasyon ve baskı yapmaya kalkan kliklere karşı üniversite güvenliğini koru.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Öğrencilerin eğitim hakkı korundu; hiç kimsenin kılık-kıyafetinden dolayı engellenmesine izin verilmedi."},{"label":"Kamuda ve üniversitelerde temel hak ve hürriyetleri teminat altına alan \'Eğitimde Fırsat Eşitliği Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Katsayı ve başörtüsü engelleri tarihe gömüldü; tüm evlatlarımız anayasal eşitliğe kavuştu."}]', 614) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
