INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_618', 'modern', '4+4+4 Kademeli Zorunlu Eğitim Sistemine Geçiş (2012)', 'Milli Eğitim Bakanlığı & YÖK', 'Eğitim 12 yıla çıkarılarak ilkokul, ortaokul ve lise olarak 4\'er yıllık kademelere ayrıldı.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Eğitimde liyakat, fırsat eşitliği ve öğretmenlik meslek standartlarını anayasal kurallarla koru.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Eğitimde fırsat eşitliği gözetildi; tüm öğrencilerin eğitime erişim hakkı korundu."},{"label":"Öğretmen sendikaları, veliler ve eğitim bilimcilerle ortak milli eğitim şurası toplayarak müfredat uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Eğitim camiası ile diyalog kuruldu; okullarda huzur ve motivasyon sağlandı."},{"label":"Okulların teknolojik altyapısı, akıllı tahta ve ücretsiz yemek dağıtımı için Hazine bütçesinden kaynak ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Okulların fiziki imkanları güçlendirildi; eğitim yatırımları bütçeden karşılandı."},{"label":"Okul çevrelerinde uyuşturucu tacirleri ve çetelere karşı \'Güvenli Okul\' polis devriyelerini görevlendir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Okul kapılarında tam güvenlik sağlandı; çocuklarımız zararlı alışkanlıklardan korundu."},{"label":"Türkiye Yüzyılı maarif vizyonunu hayata geçiren \'Milli Eğitim ve Öğretmenlik Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"peop