INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_620', 'modern', '2010 KPSS Eğitim Bilimleri Sınavı Soru Hırsızlığı ve İptali', 'Milli Eğitim Bakanlığı & YÖK', 'Soruların cemaat evlerine sızdırıldığı belgelenince sınav iptal edildi; savcılık dev soruşturma açtı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Soru sızıntısı ve şaibe iddiaları üzerine sınavı derhal iptal et; ÖSYM yöneticilerini görevden alıp DDK teftişi başlat.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Milyonlarca gencin hakkı korundu; şaibeli sınav iptal edilerek soru hırsızları hakkında adli soruşturma açıldı."},{"label":"Sınava giren gençlerle ve sendikalarla görüş; yeni sınavı tamamen ücretsiz ve güvenli koşullarda yapma taahhüdü ver.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Gençlerin devlete olan güveni tazelendi; ücretsiz tekrar sınavıyla mağduriyetler giderildi."},{"label":"İptal edilen sınavın yeniden basımı, nakli ve güvenliği için Hazine bütçesinden ek sınav ödeneği çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yeni sınav maliyeti Hazinece üstlenildi; adaylardan tek kuruş sınav ücreti alınmadı."},{"label":"ÖSYM Soru Hazırlama Merkezi\'ne sinyal kesici jammer, faraday kafesi ve kriptolu çelik kapılarla askeri güvenlik kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Soru basım merkezi kozmik odaya dönüştürüldü; soruların dışarı sızması imkansız kılındı."},{"label":"Tüm merkezi sınavlarda liyakati güvenceye alan \'ÖSYM Teşkilat ve Sınav Güven