INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_635', 'modern', 'MESEM Çıraklık Programında İş Kazaları ve Devlet Teşviki Suiistimali', 'Milli Eğitim Bakanlığı & YÖK', 'Sanayiye çırak yetiştiren MESEM programında bazı sahte şirketlerin işe gelmeyen çocukları kayıtlı gösterip devlet teşvikini hortumladığı ve inşaatlarda ölen çocuk çırakların kamuoyunu infiale sürüklediği rapor edildi.', '[{"id":"char_calisma_bakani","name":"Çalışma ve Sosyal Güvenlik Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Ağır ve tehlikeli iş kollarında çocuk çırak çalıştırmayı derhal yasakla; iş kazası ihmalinde işverene hapis cezası uygula.","preview":"Adalet +9, Halk +8, Otorite +8 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Çocukların can güvenliği korundu; vicdanları yaralayan ölümcül ihmallere ağır yaptırım geldi."},{"label":"Sahte çırak kaydıyla devlet primini hortumlayan şirketleri MASAK ve müfettişlerle basıp tüm teşvikleri faiziyle geri al.","preview":"Adalet +8, Halk +7, Hazine +8, Otorite +8","effects":{"justice":8,"people":7,"treasury":8,"military":0,"authority":8},"log":"Hazineyi soyan sahte patronlar adalete teslim edildi; teşvik vurgunu önlendi."},{"label":"Çırakların haftalık çalışma süresini kısıtlayıp genel kültür ve yabancı dil eğitimini zorunlu hale getir.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":5},"log":"Çırakların sömürülmesi engellendi, geleceğin donanımlı ustaları yetiştirildi."},{"label":"İş sağlığı ve güvenliği denetimlerini bağımsız dijital kamera ve sensörlerle 24 saat fabrikalarda takip et.","preview":"Adalet +7, Halk +6, Otorite +6 | Hazine -4","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Fabrikalarda iş kazaları modernize edilen denetim ağıyla minimize edildi."},{"label":"Dürüst üretim yapan ve çıraklarına yüksek burs veren sanayicilere vergi indirimi ve ihracat kolaylığı sağla.","preview":"Adalet +6, Halk +7, Otorite +6 | Hazine -4","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Sorumlu sanayiciler ödüllendirildi; mesleki eğitim ahlaklı bir zemine oturtuldu."}]', 635) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
