INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_641', 'modern', 'SSK Hastaneleri Çilesi ve Sabah 4\'te Reçete Kuyrukları', 'Sağlık Bakanlığı & Bilim Kurulu', '1990\'larda işçilerin SSK hastanesi kapılarında numara ve ilaç için günlerce beklemesi tarihe karıştı.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Tüm vatandaşların dilediği hastanede ve eczanede eşit sağlık hizmeti alma hakkını anayasal sosyal devlet ilkesiyle sağla.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hastanelerde rehin kalma ayıbı bitti; SSK, Bağ-Kur ve Emekli Sandığı mensupları aynı çatı altında eşit hizmete kavuştu."},{"label":"Türk Tabipleri Birliği, eczacı odaları ve sendikalarla görüşerek hastanelerin Sağlık Bakanlığı\'na devrini uzlaşıyla yürüt.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Doktor ve hemşirelerin özlük hakları korundu; hastanelerin devir sürecinde hiçbir sağlık aksaması yaşanmadı."},{"label":"İlaç Takip Sistemi (İTS) kurarak sahte kupür ve ilaç yolsuzluğunu sıfırla; Hazineye yıllık 10 milyar TL tasarruf sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"İlaçta karekod devrimi yapıldı; sahte reçete çeteleri çökertilerek kamu bütçesi korunmuş oldu."},{"label":"Korsan ilaç fabrikaları ve sahte medikal malzeme depolarına karşı polis ve sağlık müfettişleriyle baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Halk sağlığıyla oynayan fırsatçılar yakalandı; sahte tıbbi malzemeler imha edildi."},{"label":"5283 Sayılı Bazı Kamu Kurum ve Kuruluşlarına Ait Sağlık Birimlerinin Sağlık Bakanlığı\'na Devredilmesi Kanunu\'nu kabul et.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Sağlıkta devrim tamamlandı; sabah 4\'te SSK kuyruklarında bekleme devri ebediyen kapandı."}]', 641) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_642', 'modern', 'Sağlıkta Dönüşüm Programı: SSK Hastanelerinin Devri (2005)', 'Sağlık Bakanlığı & Bilim Kurulu', 'Tüm SSK ve kurum hastaneleri Sağlık Bakanlığı\'na devredilerek tek çatı altında birleştirildi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Tüm vatandaşların dilediği hastanede ve eczanede eşit sağlık hizmeti alma hakkını anayasal sosyal devlet ilkesiyle sağla.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Hastanelerde rehin kalma ayıbı bitti; SSK, Bağ-Kur ve Emekli Sandığı mensupları aynı çatı altında eşit hizmete kavuştu."},{"label":"Türk Tabipleri Birliği, eczacı odaları ve sendikalarla görüşerek hastanelerin Sağlık Bakanlığı\'na devrini uzlaşıyla yürüt.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Doktor ve hemşirelerin özlük hakları korundu; hastanelerin devir sürecinde hiçbir sağlık aksaması yaşanmadı."},{"label":"İlaç Takip Sistemi (İTS) kurarak sahte kupür ve ilaç yolsuzluğunu sıfırla; Hazineye yıllık 10 milyar TL tasarruf sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"İlaçta karekod devrimi yapıldı; sahte reçete çeteleri çökertilerek kamu bütçesi korunmuş oldu."},{"label":"Korsan ilaç fabrikaları ve sahte medikal malzeme depolarına karşı polis ve sağlık müfettişleriyle baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Halk sağlığıyla oynayan fırsatçılar yakalandı; sahte tıbbi malzemeler imha edildi."},{"label":"5283 Sayılı Bazı Kamu Kurum ve Kuruluşlarına Ait Sağlık Birimlerinin Sağlık Bakanlığı\'na Devredilmesi Kanunu\'nu kabul et.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Sağlıkta devrim tamamlandı; sabah 4\'te SSK kuyruklarında bekleme devri ebediyen kapandı."}]', 642) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_643', 'modern', 'Sosyal Güvenlik Kurumu\'nun (SGK) Kurulması', 'Sağlık Bakanlığı & Bilim Kurulu', 'SSK, Bağ-Kur ve Emekli Sandığı birleştirilerek tüm vatandaşlar eşit sağlık sigortasına kavuşturuldu.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Sağlık hizmetlerinde hasta hakları, tıbbi etik ve malpraktis soruşturmalarını adli bağımsızlıkla yürüt.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Tıbbi etik korundu; hasta hakları ve hekim güvencesi adil bir dengede tutuldu."},{"label":"Tabip odaları, sağlık sendikaları ve hasta dernekleriyle diyalog kurarak sağlıkta reform mutabakatı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sağlık çalışanlarının talepleri dinlendi; grev ve aksamaların önüne uzlaşıyla geçildi."},{"label":"İlaç ve tıbbi cihaz yerlileştirme projelerine Hazine bütçesinden doğrudan Ar-Ge teşviki ver.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İlaçta yerlilik oranı arttı; ithal tıbbi cihaz harcamalarında Hazineye tasarruf sağlandı."},{"label":"Hastanelerde acil servis baskınları ve sağlık personeline saldırılara karşı polis güvenlik noktaları kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Acil servislerde asayiş sağlandı; sağlık görevlilerinin huzurla çalışması temin edildi."},{"label":"Kamu sağlığı ve koruyucu hekimlik altyapısını güçlendiren \'Milli Sağlık Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Aile hekimliği ve koruyucu sağlık modeli yaygınlaştırıldı; hastalıklara erken teşhis sağlandı."}]', 643) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
