INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_648', 'modern', 'KÖİ Şehir Hastanelerinde Hazine Yükü ve Köklü Hastanelerin Kapanması Krizi', 'Sağlık Bakanlığı & Bilim Kurulu', 'Devasa şehir hastaneleri hizmete girerken, şehir merkezlerindeki asırlık devlet hastanelerinin kapatılması halkın tepkisini çekti; müteahhit firmalara döviz endeksli kira ve doluluk garantileri Hazine bütçesini kilitledi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Kapatılan tarihi şehir içi hastanelerini restore edip acil poliklinik ve butik ihtisas hastaneleri olarak derhal yeniden aç.","preview":"Adalet +8, Halk +9, Otorite +7 | Hazine -5","effects":{"justice":8,"people":9,"treasury":-5,"military":0,"authority":7},"log":"Halkın mahallelerindeki sağlık merkezleri korundu; yaşlı ve dar gelirli vatandaş rahat nefes aldı."},{"label":"Şehir hastaneleri sözleşmelerindeki döviz bazlı kira ve hizmet garantilerini Türk Lirası\'na çevirerek Hazineyi rahatlat.","preview":"Adalet +7, Halk +6, Hazine +8, Otorite +7","effects":{"justice":7,"people":6,"treasury":8,"military":0,"authority":7},"log":"Hazineye binen kur farkı yükü dizginlendi; kamu maliyesi korundu."},{"label":"Şehir hastanelerini son teknoloji onkoloji ve robotik cerrahi merkezleriyle donatarak Türkiye\'yi bölgenin sağlık turizmi üssü yap.","preview":"Adalet +5, Halk +7, Hazine +7, Otorite +6","effects":{"justice":5,"people":7,"treasury":7,"military":0,"authority":6},"log":"Yabancı hastalardan elde edilen döviz geliriyle sağlık sisteminin finansmanı güçlendirildi."},{"label":"Hastanelerde hekimlerin ve sağlık personelinin nöbet ücretlerini ve maaşlarını iki katına çıkararak beyin göçünü durdur.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -7","effects":{"justice":8,"people":8,"treasury":-7,"military":0,"authority":6},"log":"Doktorların yurt dışına gidişi önlendi; randevu kuyrukları ve hekim açığı hafifletildi."},{"label":"KÖİ sözleşmelerini bağımsız Sayıştay denetimine açarak tüm harcama kalemlerini şeffaf biçimde Meclis\'e sun.","preview":"Adalet +9, Halk +7, Hazine +1, Otorite +6","effects":{"justice":9,"people":7,"treasury":1,"military":0,"authority":6},"log":"Şeffaflık sağlandı; kamu-özel ortaklığı projelerinde yolsuzluk şaibeleri bertaraf edildi."}]', 648) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
