INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_650', 'modern', 'Ankara Bilkent ve Etlik Şehir Hastaneleri Kampüsleri', 'Sağlık Bakanlığı & Bilim Kurulu', 'Eski ihtisas hastanelerini tek devasa kampüste toplayan şehir hastaneleri başkentin omurgası oldu.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Şehir hastanelerinin Kamu-Özel İşbirliği (KÖİ) kira ve hizmet sözleşmelerini Sayıştay ve bağımsız denetime aç.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sözleşmeler şeffaflıkla denetlendi; kamu kaynaklarının kullanımında hesap verilebilirlik sağlandı."},{"label":"Günde 50 bin hastaya bakan dev kampüslerde hasta ve yaşlıların transferini kolaylaştıracak ücretsiz ring seferleri kur.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Vatandaş memnuniyeti zirve yaptı; 5 yıldızlı otel konforundaki hastaneler halkın hizmetine sunuldu."},{"label":"Hastanelerin medikal ve laboratuvar işletme bedellerini yerli firmalara açarak Hazine kira yükümlülüklerini azalt.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine borç yükü hafifletildi; kamu hastaneleri yüksek teknolojik donanıma kavuştu."},{"label":"Hastanelerin nükleer tıp, radyasyon ve yoğun bakım binalarında siber ve fiziki güvenliği en üst düzeye çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Stratejik sağlık merkezleri korundu; hasta veri tabanlarının siber saldırıya uğraması engellendi."},{"label":"Türkiye\'yi sağlık turizminin küresel başkenti yapan \'Uluslararası Sağlık Hizmetleri Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Türkiye yılda 2 milyon yabancı hastaya bakan küresel sağlık üssü oldu; milyarlarca dolar döviz girdisi sağlandı."}]', 650) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
