INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_653', 'modern', 'Domuz Gribi Salgını (H1N1 - 2009) ve Aşı Kampanyası', 'Sağlık Bakanlığı & Bilim Kurulu', 'Dünyayı saran salgında aşı alımı Başbakan ve Sağlık Bakanı arasında polemiklere sahne oldu.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"}]', '[{"label":"Sağlık hizmetlerinde hasta hakları, tıbbi etik ve malpraktis soruşturmalarını adli bağımsızlıkla yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tıbbi etik korundu; hasta hakları ve hekim güvencesi adil bir dengede tutuldu."},{"label":"Tabip odaları, sağlık sendikaları ve hasta dernekleriyle diyalog kurarak sağlıkta reform mutabakatı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sağlık çalışanlarının talepleri dinlendi; grev ve aksamaların önüne uzlaşıyla geçildi."},{"label":"İlaç ve tıbbi cihaz yerlileştirme projelerine Hazine bütçesinden doğrudan Ar-Ge teşviki ver.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İlaçta yerlilik oranı arttı; ithal tıbbi cihaz harcamalarında Hazineye tasarruf sağlandı."},{"label":"Hastanelerde acil servis baskınları ve sağlık personeline saldırılara karşı polis güvenlik noktaları kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Acil servislerde asayiş sağlandı; sağlık görevlilerinin huzurla çalışması temin edildi."},{"label":"Kamu sağlığı ve koruyucu hekimlik altyapısını güçlendiren \'Milli Sağlık Reform Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"p