INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_661', 'modern', 'Yerli COVID-19 Aşısı TURKOVAC\'ın Geliştirilmesi', 'Sağlık Bakanlığı & Bilim Kurulu', 'Erciyes Üniversitesi\'nde geliştirilen yerli inaktif aşı Faz-3 testlerini geçerek acil kullanım onayı aldı.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Salgın döneminde temel hak ve hürriyetlerin sınırlandırılmasını Anayasa ve Umumi Hıfzıssıhha Kanunu zemininde yürüt.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuki meşruiyet korundu; pandemi kararları keyfilikten uzak bilimsel kurul tavsiyelerine dayandırıldı."},{"label":"Koronavirüs Bilim Kurulu\'nun tavsiyeleriyle 14 günlük tam kapanma ilan et; esnafa ve dar gelirliye doğrudan gelir desteği ver.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Vaka sayıları hızla düşürüldü; esnaf ve çalışanlar nakdi ücret desteğiyle korundu."},{"label":"Yerli aşı TURKOVAC ve şehir hastanelerinin pandemi yoğun bakımları için Hazine bütçesinden sınırsız acil kaynak sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli aşı geliştirildi; yabancı aşı kartellerine milyarlarca dolar akıtılmasının önüne yerli üretimle geçildi."},{"label":"Filyasyon ekiplerini, polis ve jandarma devriyeleriyle destekleyerek karantina ihlallerini ve stokçuluğu sertçe cezalandır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Salgın disiplini sağlandı; maske ve dezenfektan karaborsacılarına göz açtırılmadı."},{"label":"Sağlık çalışanlarına şiddet uygulayanların tutuklu yargılanmasını zorunlu kılan \'Sağlıkta Şiddetle Mücadele Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Beyaz Kod ve sağlık personeli koruma altına alındı; hekimlerin can güvenliği kanunla teminat altına alındı."}]', 661) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
