INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_670', 'modern', 'SGK Sahte Reçete ve Medikal Yolsuzluk Teftişleri', 'Sağlık Bakanlığı & Bilim Kurulu', 'Yazılmayan pahalı kanser ilaçlarını devlete fatura eden organize şebekeler mali polisçe çökertildi.', '[{"id":"char_saglik_bakani","name":"Sağlık Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Sağlık hizmetlerinde hasta hakları, tıbbi etik ve malpraktis soruşturmalarını adli bağımsızlıkla yürüt.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Tıbbi etik korundu; hasta hakları ve hekim güvencesi adil bir dengede tutuldu."},{"label":"Tabip odaları, sağlık sendikaları ve hasta dernekleriyle diyalog kurarak sağlıkta reform mutabakatı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sağlık çalışanlarının talepleri dinlendi; grev ve aksamaların önüne uzlaşıyla geçildi."},{"label":"İlaç ve tıbbi cihaz yerlileştirme projelerine Hazine bütçesinden doğrudan Ar-Ge teşviki ver.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"İlaçta yerlilik oranı arttı; ithal tıbbi cihaz harcamalarında Hazineye tasarruf sağlandı."},{"label":"Hastanelerde acil servis baskınları ve sağlık personeline saldırılara karşı polis güvenlik noktaları kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Acil servislerde asayiş sağlandı; sağlık görevlilerinin huzurla çalışması temin edildi."},{"label":"Kamu sağlığı ve koruyucu hekimlik altyapısını güçlendiren \'Milli Sağlık Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Aile hekimliği ve koruyucu sağlık modeli yaygınlaştırıldı; hastalıklara erken teşhis sağlandı."}]', 670) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_671', 'modern', 'UEFA Kupası Yarı Finali Öncesi Taksim\'de İngiliz Holigan Çatışması ve Diplomatik Kriz', 'Gençlik ve Spor Bakanlığı & TFF', 'Leeds United maçı öncesi Taksim Meydanı\'nda alkollü İngiliz holiganların Türk bayrağını yakıp esnafa saldırması üzerine çıkan kavgada 2 İngiliz taraftar hayatını kaybetti. İngiltere hükümeti ve UEFA Türkiye\'yi barbarlıkla suçlayarak tüm Türk takımlarını Avrupa\'dan men etme tehdidi savuruyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"İstanbul Cumhuriyet Başsavcılığı\'na tam yetki ver; kavgaya karışan tüm şüphelileri tarafsız adli soruşturmayla yargıya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Hukuk devleti tavizsiz işletildi; cinayet zanlıları tutuklanarak adli süreç İngiliz elçiliğine şeffaf aktarıldı."},{"label":"İngiltere Dışişleri ve UEFA Başkanı ile acil diplomatik kriz masası kur; Türk takımlarının men edilmesini diplomatik yolla engelle.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Diplomatik kriz yönetildi; Galatasaray\'ın Kopenhag\'daki tarihi final maçı güvenceye alındı."},{"label":"Kopenhag finaline gidecek Türk taraftarların güvenliği ve seyahat masrafları için Hazine destek fonu ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Taraftar dayanışması sağlandı; Danimarka\'ya binlerce Türk vatandaşı bayraklarla intikal etti."},{"label":"Kopenhag sokaklarında İngiliz holiganların intikam saldırısı planlarına karşı MİT ve Danimarka polisine istihbarat kalkanı kurdur.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"MİT uyarısıyla Kopenhag\'da pusu kuran holigan çeteleri tutuklandı; taraftarların can güvenliği korundu."},{"label":"Sporda şiddet ve holiganizmi terör suçu kapsamında cezalandıran \'Milli Sporda Şiddeti Önleme Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Stadyumlarda holiganizm kanunla yasaklandı; Türk sporu Avrupa\'nın en büyük kupasını alarak tarihe geçti."}]', 671) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_672', 'modern', 'Monako UEFA Süper Kupa Finali & Uluslararası Bahis Şebekesi Şantajı', 'Gençlik ve Spor Bakanlığı & TFF', 'Galatasaray\'ın Real Madrid ile oynayacağı Süper Kupa finali öncesinde, Balkan ve Akdeniz merkezli yasadışı bahis mafyasının Türk futbolculara şantaj yapma ve kampa sızma girişimi MİT tarafından tespit edildi.', '[{"id":"char_mit_mustesari","name":"MİT Müsteşarı / Başkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Kamp oteli ve stadyum çevresinde MİT ve Monaco Prensliği emniyetiyle tam tecrit uygulayarak sabotajı engelle ve takımı sahaya çıkar.","preview":"Adalet +6, Halk +8, Güvenlik +5, Otorite +8 | Hazine -2","effects":{"justice":6,"people":8,"treasury":-2,"military":5,"authority":8},"log":"Şantaj şebekesi engellendi; sarı-kırmızılılar huzurla sahaya çıkıp tarihi kupayı Türkiye\'ye getirdi."},{"label":"Şantajcı şebekenin para transferlerini MASAK ve Interpol kanalıyla dondurup lider kadroyu maç öncesi tutuklat.","preview":"Adalet +9, Halk +7, Hazine +4, Güvenlik +3, Otorite +8","effects":{"justice":9,"people":7,"treasury":4,"military":3,"authority":8},"log":"Yasadışı bahis baronu Monako ve Nice\'te kıskıvrak yakalandı; sporda temizlik sağlandı."},{"label":"Bahis mafyasıyla teması olan yabancı menajerleri sınır dışı et ve kulübe bağımsız mali denetim ata.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +7","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":7},"log":"Türk futbolunu sülük gibi emen şaibeli menajer ağı çökertildi."},{"label":"Olayı uluslararası medyaya sızdırarak UEFA\'yı şike ve şantaj şebekelerine karşı acil teyakkuza zorla.","preview":"Adalet +7, Halk +6, Güvenlik +2, Otorite +6","effects":{"justice":7,"people":6,"treasury":0,"military":2,"authority":6},"log":"UEFA şike şebekesine karşı teyakkuza geçti; Türk takımının hakları güvenceye alındı."},{"label":"Futbol federasyonuna özel spor istihbarat ve güvenlik protokolü yayımlatarak gelecekteki tüm finalleri korumaya al.","preview":"Adalet +7, Halk +6, Güvenlik +4, Otorite +7 | Hazine -2","effects":{"justice":7,"people":6,"treasury":-2,"military":4,"authority":7},"log":"Milli takımlar ve kulüpler için daimi spor güvenliği kalkanı oluşturuldu."}]', 672) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_673', 'modern', 'Uluslararası Karşılaşmalarda Yasadışı Bahis, Şike ve Balkan Mafyası Şantajı', 'Gençlik ve Spor Bakanlığı & TFF', 'MASAK ve MİT Organize Suçlar Dairesi, Türkiye ligi ve uluslararası maçları hedef alan Balkan ve Asya merkezli 5 milyar dolarlık devasa bir yasadışı bahis ve şike ağını deşifre etti. Bazı kulüp yöneticilerinin ve hakemlerin şantaja bağlandığı belirlendi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"MASAK raporlarını Özel Yetkili Ağır Ceza Mahkemesi\'ne sevk et; şikeye ve yasadışı bahse bulaşan tüm yöneticileri tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Büyük adli operasyon yapıldı; kulüp yöneticileri ve hakemler hapis cezası aldı, spor temizlendi."},{"label":"Türkiye Futbol Federasyonu ve Kulüpler Birliği ile acil meşveret masası kur; küme düşme cezalarını erteleyip uzlaş.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Kulüplerin batması engellendi; ancak adaletin ertelenmesi kamu vicdanında derin tartışma yarattı."},{"label":"Yasadışı bahis sitelerinin milyarlarca liralık hesaplarına ve lüks mal varlıklarına el koyarak Hazineye doğrudan aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Devlete devasa kaynak sağlandı; kara para aklama şebekesinin finansal damarları kesildi."},{"label":"İnterpol ve Balkan ülkeleri istihbaratıyla ortak operasyon düzenle; şike baronu yabancı çete liderlerini sınır ötesinden paketle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Balkan mafyası inlerinde basıldı; Türk futboluna şantaj yapan uluslararası baronlar Türkiye\'ye getirildi."},{"label":"Sporda yasadışı bahis ve şike gelirlerini terörün finansmanı kapsamına alan kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yasal çerçeve sertleştirildi; Türk sporunun uluslararası itibarı mafyadan temizlendi."}]', 673) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_674', 'modern', 'Hakan Şükür\'ün Güney Kore\'ye 11. Saniyede Attığı Tarihi Gol', 'Gençlik ve Spor Bakanlığı & TFF', 'Dünya Kupası tarihinin en hızlı golü olarak rekorlar kitabına geçen gol dünya basınında manşet oldu.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 674) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_675', 'modern', 'Eurovision ve Uluslararası Yarışmalarda Siyasi Blokaj ve Kültürel Şantaj', 'Gençlik ve Spor Bakanlığı & TFF', 'Türkiye\'nin uluslararası yarışmalarda kazandığı zaferlerin ardından, yarışma organizatörlerinin LGBT propagandası dayatması, siyasi oylama blokajları ve Türkiye aleyhine puanlama kumpasları kurduğu tespit edildi. Türkiye\'nin yarışmadan çekilmesi veya milli kültürel alternatif kurması tartışılıyor.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Avrupa Yayın Birliği (EBU) sözleşmesini ve şaibeli jüri puanlama sistemini uluslararası denetçilere inceletip hukuki itiraz yap.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Puanlama adaletsizliği kayıtlara geçirildi; Türkiye\'nin haklılığı belgelendi."},{"label":"EBU yetkilileriyle Brüksel\'de diplomatik uzlaşma toplantısı yap; kültürel değerlere saygı şartıyla yarışmada kal.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Müzakereler sürdü; ancak organizatörlerin ideolojik dayatmalarından geri adım atmadığı görüldü."},{"label":"Eurovision lisans ücreti olarak her yıl Avrupa\'ya ödenen milyonlarca avroyu keserek TRT milli bütçesine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazineye tasarruf sağlandı; gereksiz dış yayın harcaması milli projelere yönlendirildi."},{"label":"Yarışma üzerinden Türk gençliğine yönelik yürütülen kültürel dejenerasyon ve etki ajanlığı faaliyetlerini MİT ile deşifre et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Örtülü kültürel operasyonlar deşifre edildi; Türkiye yarışmadan resmen çekilerek bağımsız duruş sergiledi."},{"label":"Türk dünyası ve Avrasya ülkelerini kapsayan \'Türkvizyon Milli Şarkı Yarışması ve Kültür Birliği Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"300 milyonluk Türk dünyasında alternatif festival kuruldu; milli kültür küresel sahnede yükseldi."}]', 675) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_676', 'modern', 'Euro 2008 Viyana-Basel Yarı Finali: Aşırı Sağcı Holiganlar ve Provokasyon İstihbaratı', 'Gençlik ve Spor Bakanlığı & TFF', 'Türkiye\'nin mucizevi geri dönüşlerle yarı finale yükselmesi üzerine Avusturya ve İsviçre\'deki ırkçı holigan grupların gurbetçi mahallelerine ve milli takım kafilesine saldırma hazırlığında olduğu istihbaratı alındı.', '[{"id":"char_disisleri_bakani","name":"Dışişleri Bakanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"İsviçre ve Avusturya emniyet teşkilatına Türk irtibat polisleri ve koruma ekipleri göndererek gurbetçi güvenliğini sağla.","preview":"Adalet +6, Halk +9, Güvenlik +5, Otorite +8 | Hazine -3","effects":{"justice":6,"people":9,"treasury":-3,"military":5,"authority":8},"log":"Avrupa sokaklarındaki yüz binlerce Türk vatandaşının can güvenliği sağlandı; provokasyonlar bastırıldı."},{"label":"Avrupa çapındaki Türk dernekleri ve konsolosluklar aracılığıyla taşkınlık ve provokasyona karşı sağduyu seferberliği başlat.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -1","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Gurbetçilerimiz vakarla ve coşkuyla bayram havası yaşadı; ırkçıların sokak çatışması tuzağı bozuldu."},{"label":"Milli maçın dev ekranlarda elçilik ve konsolosluk bahçelerinde izlenmesini sağlayarak toplu güvenli toplanma alanları oluştur.","preview":"Adalet +6, Halk +8, Güvenlik +2, Otorite +6 | Hazine -2","effects":{"justice":6,"people":8,"treasury":-2,"military":2,"authority":6},"log":"Taraftarlar güvenli alanlarda tek yürek oldu, asayiş sorunsuz korundu."},{"label":"Irkçı örgütlerin sosyal medya provokasyonlarını siber istihbaratla deşifre edip Avrupa makamlarına resmi nota ile ilet.","preview":"Adalet +8, Halk +6, Güvenlik +3, Otorite +7","effects":{"justice":8,"people":6,"treasury":0,"military":3,"authority":7},"log":"Avusturya ve İsviçre polisi ırkçı elebaşlarını maçtan önce gözaltına almak zorunda kaldı."},{"label":"Turnuva sonrasında Avrupa\'daki gurbetçilerin haklarını koruyacak daimi \'Yurt Dışı Vatandaşlar Kriz Masası\' kur.","preview":"Adalet +7, Halk +8, Otorite +7 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Avrupa Türk toplumunun kurumsal temsili ve hukuki güvenliği güçlendirildi."}]', 676) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_677', 'modern', '3 Temmuz 2011 Şike Soruşturması ve Kulüp Başkanları', 'Gençlik ve Spor Bakanlığı & TFF', 'Fenerbahçe Başkanı Aziz Yıldırım ve yöneticilerin şafak operasyonuyla tutuklanması Türk futbolunu sarstı.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Fenerbahçe ve kulüplere yönelik kumpas iddialarını, sahte tapeleri ve usulsüz dinlemeleri bağımsız yargıda incelet.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Kumpas davası çöktü; Yargıtay tüm sanıklar hakkında beraat kararı vererek kulüplerin itibarını iade etti."},{"label":"Milyonlarca taraftarın adalet yürüyüşlerini sükûnetle karşıla; futbol camiasındaki kutuplaşmayı giderecek barış masası kur.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Taraftarların haklı isyanı dinlendi; kulüpler arasındaki düşmanlık havası sağduyuyla yatıştırıldı."},{"label":"Kulüplerin UEFA gelirlerinden mahrum kalması ve borsada uğradığı yüz milyonlarca Euro\'luk zararı telafi edecek yapılandırma yap.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kulüplerin mali iflası önlendi; Hazine ve kamu bankalarıyla borç tasfiye protokolleri imzalandı."},{"label":"Kumpas soruşturan savcı ve emniyet amirleri hakkında \'örgütlü yargı kumpası\' suçlamasıyla tutuklama kararı çıkart.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Futbolu ele geçirmeye çalışan paralel çete yargıya teslim edildi; emniyet içindeki kumpasçılar temizlendi."},{"label":"Sporda şiddet, düzensizlik ve şike suçlarını yeniden tanzim eden 6222 Sayılı Kanun\'da demokratik reform yap.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sporda adalet sağlandı; keyfi ceza ve tutuklama yetkileri törpülenerek adil yargılanma getirildi."}]', 677) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
