INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_680', 'modern', 'Passolig Elektronik Bilet Sistemine Geçiş ve Tribün Boykotu', 'Gençlik ve Spor Bakanlığı & TFF', '6222 sayılı sporda şiddet yasasıyla gelen e-bilet sistemi taraftar gruplarınca tribünleri boşaltarak protesto edildi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 680) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_681', 'modern', 'Uluslararası Voleybol Şampiyonası Öncesi Brüksel\'de Aşırı Sağcı Provokasyon Tehdidi', 'Gençlik ve Spor Bakanlığı & TFF', 'A Milli Kadın Voleybol Takımı Avrupa Şampiyonası finali için Brüksel\'e giderken; yabancı istihbarat destekli ırkçı ve İslamofobik grupların salonda Türk bayrağına ve milli marşa saldırı planladığı MİT Dış Operasyonlar Başkanlığı tarafından tespit edildi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Belçika İçişleri Bakanlığı ve Avrupa Voleybol Konfederasyonu\'na (CEV) resmi diplomatik nota vererek salon güvenliğini şart koş.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Uluslararası sorumluluk hatırlatıldı; Belçika polisi salonda olağanüstü güvenlik tedbiri aldı."},{"label":"Avrupa\'daki Türk sivil toplum örgütleri ve taraftar dernekleriyle toplantı yap; salonda barışçıl ve sağduyulu bir atmosfer sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Türk gurbetçiler salonu kırmızı-beyaza boyadı; provokasyon hevesleri halkın asil duruşuyla boğuldu."},{"label":"Şampiyon olan voleybolcularımıza ve genç sporcu altyapısına Hazine bütçesinden Cumhuriyet tarihinin en büyük ödülünü tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Filenin Sultanları ödüllendirildi; Türkiye\'nin kız çocuklarına devasa bir ilham ve spor hamlesi başlatıldı."},{"label":"Milli sporcuların otelini ve salon girişini korumak için Özel Harekat ve MİT yakın koruma timlerini gizlice Brüksel\'e gönder.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sporcuların can güvenliği garantiye alındı; hiçbir provokasyona izin verilmeden kupa kaldırıldı."},{"label":"Milli sporcuların uluslararası müsabakalarda diplomatik pasaport ve devlet korumasına alınmasını sağlayan kanun çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Milli sporcular devlet himayesine alındı; Türkiye Avrupa\'nın zirvesine gururla oturdu."}]', 681) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_682', 'modern', 'Melissa Vargas ve Ebrar Karakurt\'un Küresel Başarısı', 'Gençlik ve Spor Bakanlığı & TFF', 'Vargas turnuvanın en değerli oyuncusu (MVP) seçilirken milli voleybolcular dünya sıralamasında 1 numaraya oturdu.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 682) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_683', 'modern', 'Tokyo Olimpiyatları Öncesi Gizli Doping Kumpası ve WADA Siyasi Şantajı', 'Gençlik ve Spor Bakanlığı & TFF', 'Dünya okçuluk şampiyonu Mete Gazoz ve milli güreşçilerin şampiyonluğu öncesinde, Dünya Anti-Doping Ajansı (WADA) içerisindeki yabancı kliklerin Türk sporcularının numunelerine gizlice yasaklı madde bulaştırma girişimi MİT tarafından deşifre edildi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Uluslararası Spor Tahkim Mahkemesi\'ne (CAS) ve Uluslararası Olimpiyat Komitesi\'ne (IOC) kriminal delillerle acil başvuru yap.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Kumpas uluslararası mahkemede belgelendi; Türk kafilesine yönelik komplo çökertildi."},{"label":"WADA Başkanı ve bağımsız tıp kurullarıyla Tokyo\'da istişare heyeti topla; numune testlerinin çift kör hakemlerle yapılmasını sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tarafsız testler kabul edildi; sporcularımızın alın teri ve temizliği tüm dünyaya kanıtlandı."},{"label":"Milli Sporcu Gelişim ve Tıbbi İzleme Merkezi\'ni kurarak Hazine\'den modern bağımsız biyokimya laboratuvarı finanse et.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Doping şantajına milli bilim kalkanı kuruldu; yabancı laboratuvarlara bağımlılık bitti."},{"label":"Milli kafileye tahsis edilen gıda ve takviye depolarına yabancı ajanların yaklaşmasını önlemek için özel güvenlik timi koy.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Gıda ve içecek sabotajı engellendi; Mete Gazoz altın madalyayı boynuna takarak tarihe geçti."},{"label":"Milli sporculara komplo kuran kişi ve yabancı ajanlara karşı Türkiye\'de ağır ceza öngören \'Spor Güvenliği Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Milli sporcular hukuki güvenceye kavuştu; olimpiyatlarda peş peşe rekorlar kırıldı."}]', 683) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_684', 'modern', 'Yusuf Dikeç\'in Paris 2024 Olimpiyatlarındaki Ekipmansız Duruşu', 'Gençlik ve Spor Bakanlığı & TFF', 'Kulaklıksız, özel gözlüksüz ve cebinde eliyle gümüş madalya kazanan milli atıcı tüm dünyada viral mem oldu.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Olimpiyat ve Avrupa şampiyonu sporcularımızın dünya rekorlarını ve başarılarını uluslararası tescile bağla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Milli sporcuların zaferi tüm dünyada alkışlandı; Türk kadınının ve Türk gençliğinin gücü dünyaya kanıtlandı."},{"label":"Brüksel\'deki final maçını 81 ilin meydanlarına kurulan dev ekranlarda yüz binlerce vatandaşla birlikte izlet.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Millet ekran başına kilitlendi; Vargas, Eda Erdem ve kızlarımızın zaferi 85 milyonun ortak sevinci oldu."},{"label":"Milli sporculara ömür boyu sporcu şeref aylığı bağla; Anadolu\'daki 10 bin köy okuluna voleybol ve okçuluk sahaları aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Geleceğin şampiyonları için altyapı fonu ayrıldı; Hazine kaynakları gençliğin sporla buluşmasına tahsis edildi."},{"label":"Uluslararası turnuvalarda sporcularımıza yönelik siber linç ve provokasyonlara karşı siber polis kalkanı kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Milli sporcuların itibarı korundu; sosyal medyadaki organize saldırılar savcılıkça soruşturuldu."},{"label":"Olimpik branşlarda madalya alan sporculara kalıcı kariyer ve üniversite öğretim üyeliği hakkı tanıyan \'Milli Sporcu Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Olimpiyat şampiyonlarına devlet güvencesi getirildi; Türkiye spor ülkesine dönüştü."}]', 684) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_685', 'modern', 'Naim Süleymanoğlu\'nun Bulgaristan\'dan Türkiye\'ye Kaçırılması: MİT Örtülü Sınır Operasyonu', 'Gençlik ve Spor Bakanlığı & TFF', 'Jivkov diktatörlüğünün Türklere uyguladığı asimilasyon ve zulmü dünyaya duyurmak isteyen dünya rekortmeni halterci Naim Süleymanoğlu\'nun Avustralya\'dan Türkiye\'ye kaçırılması için MİT ve Başbakanlık örtülü ödenekle tarihi bir istihbarat operasyonu başlattı. Bulgar ve Sovyet ajanları peşinde.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Naim\'in Türkiye Cumhuriyeti vatandaşlığına kabulünü ve Bulgaristan\'ın insan hakları ihlallerini BM Güvenlik Konseyi\'ne taşı.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Bulgaristan\'ın Türk soydaşlarımıza yaptığı zulüm dünya gündemine oturdu; Türkiye meşru liderliğini gösterdi."},{"label":"Avustralya hükümeti ve İngiltere ile perde arkasında diplomatik uzlaşma sağla; diplomatik kurye statüsüyle Naim\'i tahliye et.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Müttefiklerle gizli mutabakat sağlandı; Melbourne\'den Londra\'ya uzanan rota açıldı."},{"label":"Naim\'in olimpiyatlarda Türkiye adına yarışabilmesi için Bulgaristan Halter Federasyonu\'na Hazine\'den 1 milyon dolar tazminat öde.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Uluslararası yarışma hakkı satın alındı; Naim Atlanta ve Seul\'de Türkiye için dünya rekorları kırdı."},{"label":"MİT özel operasyon timleriyle Naim\'i Başbakan Turgut Özal\'ın özel uçağı \'DAP\' ile Londra\'dan gizlice Ankara\'ya kaçır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Dünya istihbarat tarihinin en başarılı tahliyesi yapıldı; Cep Herkülü ana vatanına sağ salim kavuştu."},{"label":"Soydaş sporcuların ve sığınmacıların vatandaşlık ve spor hakkını güvenceye alan \'Milli Kahramanlar Koruma Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Naim Süleymanoğlu üst üste 3 olimpiyat altını alarak Türk milletinin direniş sembolü oldu."}]', 685) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
