INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_687', 'modern', 'Uluslararası Güreş Lobisi ve Türk Sporcularına Hakem Şaibesi Baskısı', 'Gençlik ve Spor Bakanlığı & TFF', 'Olimpiyat ve dünya şampiyonalarında Türk ağır sıklet şampiyonlarının altın madalyalarını engellemek için Doğu Bloku hakem komitelerinin organize kural ihlalleri kurguladığı rapor edildi.', '[{"id":"char_genclik_spor_bakani","name":"Gençlik ve Spor Bakanı"},{"id":"char_disisleri_bakani","name":"Dışişleri Bakanı"}]', '[{"label":"Hakemlerin şaibeli kararlarını saniye saniye analiz eden video-istihbarat dosyasıyla UWW Tahkim Kurulu\'na acil itirazda bulun.","preview":"Adalet +9, Halk +8, Otorite +7 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Şaibeli hakem puanları tahkimde iptal edildi; şampiyonlarımızın hakkı masada yedirilmedi."},{"label":"Türk güreş lobisini uluslararası federasyon karar organlarına yerleştirmek için diplomatik spor ataşeliği hamlesi başlat.","preview":"Adalet +7, Halk +7, Otorite +7 | Hazine -4","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Uluslararası komitelerde söz sahibi olundu; lobi kumpasları içeriden engellendi."},{"label":"Milli güreşçilerimize hakem kararına yer bırakmayacak mutlak tuş ve ezici teknik üstünlük taktikleri aşıla.","preview":"Adalet +6, Halk +9, Otorite +6 | Hazine -1","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Sporcularımız minderde rakiplerini sürklase etti; altın madalyalar göğsümüzü kabarttı."},{"label":"Skandal hakem kararlarını dünya basınına video kanıtlarla servis ederek taraflı jürinin lisansını iptal ettir.","preview":"Adalet +8, Halk +7, Otorite +6","effects":{"justice":8,"people":7,"treasury":0,"military":0,"authority":6},"log":"Taraflı hakemlerin lisansları donduruldu, uluslararası güreşte temizlik başladı."},{"label":"Ata sporu güreşte ta