INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_688', 'modern', 'Servet Tazegül\'ün Londra 2012 Tekvando Olimpiyat Altını', 'Gençlik ve Spor Bakanlığı & TFF', 'Akrobatik tekmeleriyle tekvando dünyasında efsaneleşen sporcu olimpiyat kürsüsünün zirvesine çıktı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"m