INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_689', 'modern', 'Uluslararası Boks Federasyonunda Rüşvet Skandalı ve Türk Kadın Boksörlerin Hakkı', 'Gençlik ve Spor Bakanlığı & TFF', 'Dünya şampiyonası öncesinde uluslararası boks organizasyonunda dönen rüşvet çarkı sebebiyle Türk sporcuların puanlarının silinmesi ve madalya kumpası istihbarat edildi.', '[{"id":"char_genclik_spor_bakani","name":"Gençlik ve Spor Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Uluslararası Olimpiyat Komitesi (IOC) nezdinde rüşvet şebekesini belgeleyen gizli mali raporları masaya koyup adaleti sağla.","preview":"Adalet +9, Halk +8, Otorite +8 | Hazine -1","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Şaibeli federasyon yönetimi görevden el çektirildi; kadın boksörlerimizin altın madalyası teslim edildi."},{"label":"Milli sporcuların haksız puan kaybını önlemek için ringde nakavt odaklı agresif dövüş stratejisine geçiş emri ver.","preview":"Adalet +6, Halk +9, Otorite +6","effects":{"justice":6,"people":9,"treasury":0,"military":0,"authority":6},"log":"Boksörlerimiz rakiplerini nakavtla devirerek jürinin puan oyunlarına şans tanımadı."},{"label":"Türkiye\'nin ev sahipliğinde temiz, bağımsız ve rüşvetsiz uluslararası kadın boks turnuvası organize et.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -5","effects":{"justice":7,"people":8,"treasury":-5,"military":0,"authority":6},"log":"İstanbul kadın boksunda dünya zirvesi oldu; küresel spor kamuoyu Türkiye\'yi alkışladı."},{"label":"Haksız kararlara imza atan yabancı jüri üyelerinin Türkiye\'deki müsabakalara akreditasyonunu süresiz iptal et.","preview":"Adalet +8, Halk +6, Otorite +7","effects":{"justice":8,"people":6,"treasury":0,"military":0,"authority":7},"log":"Haksızlık yapan jüri üyelerine Türkiye kapıları kapatıldı."},{"label":"Sporda uluslararası adalet için spor hukuku uzmanlarından ol