INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_690', 'modern', 'Gazilerin Sporda Rehabilitasyonu ve Ampute Futbolun Yumuşak Güç Stratejisi', 'Gençlik ve Spor Bakanlığı & TFF', 'Terörle mücadelede uzuvlarını kaybeden Mehmetçiklerin hayata tutunması için kurulan ampute sporların dünya şampiyonluğu yolunda karşılaştığı tesis yetersizliği ve uluslararası lobi engeli kriz yarattı.', '[{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"},{"id":"char_genclik_spor_bakani","name":"Gençlik ve Spor Bakanı"}]', '[{"label":"TSK Rehabilitasyon Merkezi ve Gençlik Spor bünyesinde dünya standartlarında ampute spor olimpiyat köyü inşa et.","preview":"Adalet +8, Halk +9, Güvenlik +5, Otorite +7 | Hazine -6","effects":{"justice":8,"people":9,"treasury":-6,"military":5,"authority":7},"log":"Gazilerimiz için dünyanın en modern spor tesisi kuruldu; ampute futbolcularımız destan yazdı."},{"label":"Türkiye\'yi engelli ve ampute sporların küresel başkenti ilan ederek Dünya Şampiyonası\'na İstanbul\'da ev sahipliği yap.","preview":"Adalet +7, Halk +9, Güvenlik +3, Otorite +8 | Hazine -5","effects":{"justice":7,"people":9,"treasury":-5,"military":3,"authority":8},"log":"Dünya Kupası İstanbul\'da kaldırıldı; Türkiye engelli sporlarında küresel lider oldu."},{"label":"Gazilerin tüm spor teçhizat ve ileri teknoloji biyonik protez masraflarını Savunma Sanayii Fonu\'ndan karşıla.","preview":"Adalet +8, Halk +9, Güvenlik +6, Otorite +6 | Hazine -5","effects":{"justice":8,"people":9,"treasury":-5,"military":6,"authority":6},"log":"Mehmetçiğe vefa borcu ödendi; yerli biyonik protez sanayii büyük ivme kazandı."},{"label":"Ampute milli takımının destansı mücadelesini dünya çapında bir diplomasi ve soft-power belgeseli olarak tüm ülkelere dağıt.","preview":"Adalet +6, Halk +8, Güvenlik +2, Otorite +7 | Hazine -3","effects":{"justice":6,"people":8,"treasury":-3,"military":2,"authority":7},"log":"Türkiye\'nin insani ve azimli duruşu dünya kamuoyunda büyük sempati ve saygı kazandı."},{"label":"Özel sektör sponsorluklarını zorunlu sosyal sorumluluk kapsamına alarak gazilerimize ömür boyu sporcu maaşı bağla.","preview":"Adalet +8, Halk +8, Hazine +1, Güvenlik +4, Otorite +6","effects":{"justice":8,"people":8,"treasury":1,"military":4,"authority":6},"log":"Gazilerimizin ekonomik güvencesi kalıcı kanuni teminata bağlandı."}]', 690) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_691', 'modern', 'EuroLeague Basketbol Maçlarında Türk Bayrağına Saldırılar ve Deplasman Güvenliği', 'Gençlik ve Spor Bakanlığı & TFF', 'Atina ve Tel Aviv deplasmanlarında radikal taraftar gruplarının Türk bayrağı yakma, takıma fiili saldırı ve siyasi provokasyon hazırlığı istihbarat edildi.', '[{"id":"char_disisleri_bakani","name":"Dışişleri Bakanı"},{"id":"char_genclik_spor_bakani","name":"Gençlik ve Spor Bakanı"}]', '[{"label":"Dışişleri ve Interpol kanalıyla ev sahibi ülkeye diplomatik nota verip Türk takımı için zırhlı güvenlik koridoru şartı koş.","preview":"Adalet +7, Halk +8, Güvenlik +4, Otorite +8 | Hazine -1","effects":{"justice":7,"people":8,"treasury":-1,"military":4,"authority":8},"log":"Diplomatik baskıyla zırhlı güvenlik sağlandı; provokasyonlar başlamadan bastırıldı."},{"label":"EuroLeague yönetimine taahhütname imzalat; salonda en ufak provokasyonda maçı seyircisiz oynatma veya hükmen galibiyet iste.","preview":"Adalet +8, Halk +7, Otorite +8","effects":{"justice":8,"people":7,"treasury":0,"military":0,"authority":8},"log":"EuroLeague yönetimi salon provokasyonlarına karşı tavizsiz güvenlik kuralları getirdi."},{"label":"Deplasmana giden taraftarlarımızın güvenliği için özel güvenlik ve konsolosluk refakat timleri görevlendir.","preview":"Adalet +6, Halk +8, Güvenlik +3, Otorite +6 | Hazine -3","effects":{"justice":6,"people":8,"treasury":-3,"military":3,"authority":6},"log":"Vatandaşlarımız deplasman tribününde devletin koruyucu gücünü yanında hissetti."},{"label":"Provokasyon yapan holigan grupların liderlerinin Türkiye\'ye girişine ve transit geçişine ömür boyu yasak koy.","preview":"Adalet +7, Halk +6, Güvenlik +3, Otorite +8","effects":{"justice":7,"people":6,"treasury":0,"military":3,"authority":8},"log":"Radikal holiganlara karşı hukuki ve idari yaptırımlar tavizsiz uygulandı."},{"label":"Türk kulüplerinin Avrupa kupalarındaki hakkını korumak için bağımsız tahkim başvurusunu derhal yürürlüğe koy.","preview":"Adalet +8, Halk +6, Otorite +6 | Hazine -1","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Spor hukukunun tüm imkanları seferber edildi; takımlarımızın sahadaki hakkı masada yedirilmedi."}]', 691) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_692', 'modern', '38 Yıl Sonra Gelen Şampiyonlukta Mega Meydan Güvenliği ve Silahla Kutlama Krizi', 'Gençlik ve Spor Bakanlığı & TFF', 'Yüz binlerce taraftarın sokaklara döküldüğü tarihi şampiyonluk kutlamalarında maganda kurşunları, izdiham ve olası provokatif saldırı istihbaratı valiliği alarma geçirdi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_genclik_spor_bakani","name":"Gençlik ve Spor Bakanı"}]', '[{"label":"Kutlama meydanlarında havaya ateş açanlara sıfır toleransla drone denetimi ve anında adli tutuklama uygula.","preview":"Adalet +9, Halk +7, Hazine +1, Güvenlik +3, Otorite +9","effects":{"justice":9,"people":7,"treasury":1,"military":3,"authority":9},"log":"Tek bir vatandaşın burnu kanamadan tarihi şampiyonluk coşkuyla ve vakarla kutlandı."},{"label":"Kutlamaları organize festival alanlarına toplayıp ışık şovları ve konserlerle sokak taşkınlıklarını dizginle.","preview":"Adalet +6, Halk +9, Otorite +7 | Hazine -4","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Dünya basınında ışık şovlarıyla manşet olan medeni bir karnaval havası yakalandı."},{"label":"Kulüp yönetimi ve taraftar dernekleriyle ortak bildiri yayımlayarak \'Silaha hayır, horona evet\' disiplini sağla.","preview":"Adalet +7, Halk +8, Otorite +6","effects":{"justice":7,"people":8,"treasury":0,"military":0,"authority":6},"log":"Toplumsal uzlaşma ve sağduyu çağrısı karşılık buldu; silahlar sustu horonlar oynandı."},{"label":"Şehir merkezinde alkol ve kontrolsüz piroteknik meşale satışını kutlama gecesi boyunca sıkı denetime al.","preview":"Adalet +7, Halk +5, Güvenlik +2, Otorite +7","effects":{"justice":7,"people":5,"treasury":0,"military":2,"authority":7},"log":"Yangın ve yaralanma riski minimize edildi, asayiş sağlandı."},{"label":"Asayişi tehlikeye atan holigan elebaşlarını kamera kayıtlarından tespit edip stadyumlardan men cezası ver.","preview":"Adalet +8, Halk +5, Hazine +1, Otorite +8","effects":{"justice":8,"people":5,"treasury":1,"military":0,"authority":8},"log":"Sporda şiddet üreten unsurlara taviz verilmedi; tribün huzuru korundu."}]', 692) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_693', 'modern', 'Hakem Halil Umut Meler\'e Saldırı: Türk Futbolunun Dünyada İtibar Krizi ve Asayiş Tedbirleri', 'Gençlik ve Spor Bakanlığı & TFF', 'Ankaragücü Başkanı\'nın sahaya inip FIFA kokartlı hakeme yumruk atması dünya basınında manşet oldu; FIFA ve UEFA tüm Türk kulüplerini uluslararası turnuvalardan men etme ve 2032 Avrupa Şampiyonası ev sahipliğini iptal etme uyarısında bulundu.', '[{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Saldırgan kulüp başkanını ve azmettiricileri derhal tutuklatıp Ağır Ceza Mahkemesi\'nde kamu görevlisini kasten yaralamaktan yargıla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Adalet gecikmeden tecelli etti; saldırgan başkan tutuklandı, adli kararlılık uluslararası kamuoyunu teskin etti."},{"label":"Tüm kulüp başkanları, hakemler derneği ve TFF ile Çankaya\'da acil \'Sporda Barış ve Sağduyu Zirvesi\' topla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Kulüpler ortak sağduyu deklarasyonu yayımladı; futbol ailesinde tansiyon düşürüldü."},{"label":"Kulüplere uygulanan mali disiplin cezalarını sıkılaştır; şiddete karışan kulüplerin Hazine bahis ve yayın gelirlerini dondur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kulüplere ağır mali fatura çıkarıldı; futbol baronlarının pervasızlığı kesildi."},{"label":"Stadyumlarda holiganizmi kışkırtan mafyatik taraftar liderlerine Emniyet ve jandarmayla şafak operasyonu yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Tribün çeteleri dağıtıldı; stadyumlara giriş yasakları tavizsiz uygulandı."},{"label":"Hakemlere ve spor görevlilerine saldırıya 10 yıla kadar hapis cezası getiren \'Sporda Şiddeti Önleme Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Caydırıcı yasa çıktı; UEFA ve FIFA Türkiye\'ye yönelik men yaptırımlarını rafa kaldırdı."}]', 693) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_694', 'modern', 'TFF\'nin Ligleri Süresiz Tatil Etmesi ve Ömür Boyu Men Cezası', 'Gençlik ve Spor Bakanlığı & TFF', 'Hakeme yönelik saldırı sonrası tüm futbol ligleri durduruldu; kulüp başkanına futboldan ömür boyu men verildi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 694) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_695', 'modern', 'Riyad Süper Kupa Krizinde Atatürk Pankartı Yasağı ve Suudi Diplomatik Restleşmesi', 'Gençlik ve Spor Bakanlığı & TFF', 'Cumhuriyetin 100. yılında Suudi Arabistan\'da oynanması planlanan Galatasaray-Fenerbahçe Süper Kupa finalinde, Suudi yetkililer Atatürk tişörtlerine, İstiklal Marşı\'na ve \'Yurtta Sulh Cihanda Sulh\' pankartına yasak koydu. Takımların maça çıkmayı reddetmesiyle kriz patlak verdi.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"Suudi Arabistan organizatörlerinin sözleşmeyi ihlal ettiğini tespit ettir; tazminat davası açarak takımların onurlu duruşunu savun.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Milli onur hukuki zeminde korundu; Suudi tarafının sözleşme ihlali kayda geçirildi."},{"label":"Riyad yönetimi ve Suudi Kraliyet ailesiyle diplomatik temas kur; Türk takımlarının ve taraftarların güvenle yurda dönüşünü sağla.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Diplomatik tahliye başarıyla yönetildi; kafileler gece yarısı kriz büyümeden Ankara ve İstanbul\'a döndü."},{"label":"Süper Kupa finalini Türkiye\'ye, Şanlıurfa 11 Nisan Stadyumu\'na taşı; bilet gelirlerini depremzedelere bağışla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kriz fırsata çevrildi; Süper Kupa milli birlik şölenine dönüştü, deprem bölgesine dev kaynak aktarıldı."},{"label":"Suudi Arabistan\'daki Türk futbolcuların ve gazetecilerin otellerine yönelik Suudi polisinin kuşatmasını MİT diplomasisiyle yar.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"MİT ve Hariciye devreye girdi; hiçbir Türk vatandaşının gözaltına alınmasına izin verilmedi."},{"label":"Milli sembollerin ve Atatürk ilkesinin yurtdışı sportif organizasyonlarda tavizsiz korunmasını emreden kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli değerler kırmızı çizgi ilan edildi; Türk sporunun Cumhuriyet ilkelerine bağlılığı perçinlendi."}]', 695) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_696', 'modern', 'Şanlıurfa\'da Oynanan Ertelenmiş Süper Kupa Maçı', 'Gençlik ve Spor Bakanlığı & TFF', 'Fenerbahçe\'nin TFF\'yi protesto için U19 takımıyla çıkıp 2. dakikada sahadan çekilmesiyle kupa Galatasaray\'a tescillendi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Kopenhag ve Monako zaferlerini Türk futbolunun uluslararası marka değeri ve adil oyun (Fair-Play) ilkesiyle taçlandır.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Tarihi kupa zaferi dünyaya ilan edildi; Türk futbolunun Avrupa\'daki saygınlığı zirveye çıktı."},{"label":"Taksim Meydanı\'nda toplanan milyonlarca taraftarla milli bayram coşkusunu kutla; tüm kulüpleri tek yürek yap.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Türkiye sokaklara döküldü; 17 Mayıs gecesi Türk spor tarihinin altın sayfası olarak milletçe kutlandı."},{"label":"Avrupa şampiyonu kulübe ve futbolculara devlet üstün hizmet madalyası ve Hazine prim desteği ver.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Başarı devletçe ödüllendirildi; Türk futbolunun UEFA katsayısı ve yayın geliri tavan yaptı."},{"label":"Şampiyonluk kutlamalarında taşkınlık, havaya ateş açma ve holiganizm eylemlerine karşı polis devriyelerini artır.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Kutlamalar güven içinde tamamlandı; provokasyon ve yaralanmaların önüne geçildi."},{"label":"Spor kulüplerinin borç batağına düşmesini engelleyen ve mali şeffaflık getiren \'Spor Kulüpleri ve Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Dernekler Kanunu\'ndan çıkarılan kulüpler anonim şirket yapısına kavuşturuldu; batık borçlara fren vuruldu."}]', 696) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
