fects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 697) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
