INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_699', 'modern', 'İstanbul Park Formula 1 Türkiye Grand Prix\'si Yarışları', 'Gençlik ve Spor Bakanlığı & TFF', 'Tuzla\'daki pistte yapılan nefes kesen F1 yarışları motor sporları tutkunlarını Türkiye\'ye çekti.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects"