INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_700', 'modern', 'Kırkpınar Yağlı Güreşleri\'nde Altın Kemer Mücadeleleri', 'Gençlik ve Spor Bakanlığı & TFF', 'Tarihi Sarayiçi er meydanında başpehlivanlık kemeri için kıran kırana geçen güreşler lig usulüne bağlandı.', '[{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"Spor müsabakalarında Fair-Play, spor ahlakı ve federasyon kurallarını tavizsiz uygula.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Sporda dürüstlük ve kurallar korundu; haksız rekabet ve kural ihlalleri cezalandırıldı."},{"label":"Kulüpler Birliği, sporcular ve taraftar dernekleriyle diyalog kurarak tribünlerde dostluk iklimi sağla.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Tribün gerilimi düşürüldü; sporun birleştirici ve kardeşlik ruhu öne çıkarıldı."},{"label":"Amatör spor kulüpleri ve olimpiyat hazırlık merkezleri için Hazine destekli sporcu bursu tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Altyapıya kaynak sağlandı; binlerce genç yetenek Türk sporuna kazandırıldı."},{"label":"Derbi maçları ve deplasman yasaklarında stadyum çevrelerinde polis asayiş çemberini sıkı tut.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Maç günleri asayiş sağlandı; holigan grupların sokak çatışması çıkarması önlendi."},{"label":"Milli spor teşkilatını profesyonel standartlara kavuşturan \'Beden Eğitimi ve Spor Federasyonları Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Spor yönetimi modernleştirildi; federasyonların özerkliği ve denetimi kanunla sağlandı."}]', 700) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_701', 'modern', 'Ayasofya-i Kebir Camii\'nin Açılması ve Doğu Akdeniz / UNESCO Jeopolitik Tehditleri', 'Kültür ve Turizm Bakanlığı', 'Danıştay 10. Dairesi\'nin 1934 tarihli müzeye dönüştürme kararını iptal etmesiyle Ayasofya\'nın yeniden ibadete açılması gündeme geldi. Yunanistan, Rus Ortodoks Kilisesi ve ABD, Türkiye\'ye karşı yaptırım ve Doğu Akdeniz\'de koalisyon tehdidi savururken; MİT tarihi mabet etrafında provokasyon istihbaratı bildirdi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Fatih Sultan Mehmet Han\'ın vakfiyesine ve Danıştay kararına sadık kal; Ayasofya\'yı Cumhurbaşkanlığı kararnamesiyle cami olarak aç.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"86 yıllık hasret bitti; Ayasofya-i Kebir Camii-i Şerifi dualarla ibadete açıldı, Fatih\'in emaneti yerine getirildi."},{"label":"UNESCO ve Hristiyan dünyasıyla diplomatik istişare kanalı aç; tarihi mozaiklerin namaz saatinde lazer perdeyle korunacağını garanti et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültürel miras güvenceye alındı; Batı\'nın kara propagandası teknik tedbirlerle etkisiz kılındı."},{"label":"Ayasofya\'nın tarihi mermerlerini, kubbesini ve minarelerini depreme karşı korumak için Hazine\'den 500 milyon liralık restorasyon fonu aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi mabedin deprem güvenliği sağlandı; kubbe çelik gergilerle tahkim edildi."},{"label":"Açılış günü Sultanahmet Meydanı\'nı dolduran 350 bin vatandaşa yönelik canlı bomba ve terör sabotajlarına karşı çelik güvenlik çemberi kur.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"MİT ve Emniyet kuş uçurtmadı; açılış tek bir burnu kanamadan tarihi bir bayram havasında tamamlandı."},{"label":"Vakıf mallarının amaç dışı kullanılmasını ebediyen yasaklayan \'Milli Vakıf ve Mabetler Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Vakfiye şartı anayasal korumaya alındı; Türkiye\'nin egemenlik hakları tüm dünyaya ilan edildi."}]', 701) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_702', 'modern', 'Ayasofya\'da 86 Yıl Sonra Kılınan İlk Cuma Namazı', 'Kültür ve Turizm Bakanlığı', '350 bin vatandaşın Sultanahmet Meydanı\'nı doldurduğu tarihi günde Diyanet İşleri Başkanı kılıçla hutbe verdi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Danıştay 10. Dairesi\'nin 1934 tarihli Bakanlar Kurulu kararını iptal eden tarihi hükmünü derhal Resmi Gazete\'de yayımla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Hukuk zaferi ilan edildi; Fatih Sultan Mehmet Han\'ın vakfiyesi gereğince Ayasofya 86 yıl sonra cami statüsüne kavuştu."},{"label":"Sultanahmet Meydanı\'nı dolduran 350 bin vatandaşla ilk Cuma namazını eda et; UNESCO heyetiyle mozaiklerin korunmasında uzlaş.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Tarihi gün milletçe kutlandı; kılıçla hutbe okunurken paha biçilmez Hristiyan mozaikleri perde sistemiyle korundu."},{"label":"Ayasofya\'nın restorasyonu, minarelerin güçlendirilmesi ve kubbe onarımı için Vakıflar Genel Müdürlüğü\'ne rekor bütçe ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarihi mabet depreme karşı çelik gergilerle korundu; Hazine kaynaklarıyla kubbe restorasyonu başlatıldı."},{"label":"Ayasofya ve çevresinde özel güvenlik, turist güzergahı ve polis noktalarıyla 24 saat kesintisiz koruma sağla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Tarihi mabedin güvenliği kusursuz sağlandı; provokatif eylemler ve tarihi kapılara zarar verilmesi engellendi."},{"label":"Fatih Sultan Mehmet Vakfı ve vakıf taşınmazlarının korunmasını anayasal güvenceye alan \'Tarihi Vakıflar ve Mabetler Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Vakıf hukuku tahkim edildi; ecdat yadigarı eserlerin vakfiye şartlarına aykırı kullanımı ebediyen yasaklandı."}]', 702) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_703', 'modern', 'Kariye Camii Kararı Sonrası UNESCO ve Batı Baskısına Karşı Egemenlik Dengesi', 'Kültür ve Turizm Bakanlığı', 'Kariye\'nin yeniden ibadete açılması kararı üzerine Batılı ülkelerin ve UNESCO\'nun Bizans mozaikleri gerekçesiyle Türkiye\'ye yaptırım tehditleri savurması diplomatik kriz yarattı.', '[{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"},{"id":"char_disisleri_bakani","name":"Dışişleri Bakanı"}]', '[{"label":"İbadet vakitlerinde elektronik lazer perdeleme ve açılır-kapanır panellerle tarihi mozaikleri sıfır zararla koruyup ibadeti aç.","preview":"Adalet +7, Halk +8, Otorite +8 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Tarihi freskler titizlikle korundu; Türkiye\'nin egemenlik tasarrufu dünyaya örnek gösterildi."},{"label":"Uluslararası uzmanlardan oluşan tarafsız bir kültür heyetini davet edip koruma çalışmalarını canlı yayınla dünyaya göster.","preview":"Adalet +8, Halk +7, Otorite +6 | Hazine -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Batı\'nın \'mozaikler yok ediliyor\' kara propagandası şeffaf bilimsel heyet raporuyla çürütüldü."},{"label":"Türkiye\'nin kendi egemenlik alanındaki tarihi mülkiyet tasarrufuna dış müdahaleleri diplomatik nota ile kesin dille reddet.","preview":"Adalet +7, Halk +7, Güvenlik +3, Otorite +9","effects":{"justice":7,"people":7,"treasury":0,"military":3,"authority":9},"log":"Milli egemenlikten taviz verilmeyeceği uluslararası diplomasiye ilan edildi."},{"label":"Vakıflar Genel Müdürlüğü bünyesinde Doğu Roma ve Osmanlı mimarisini ortak koruyan yüksek restorasyon enstitüsü kur.","preview":"Adalet +7, Halk +6, Otorite +6 | Hazine -4","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Tarihi mirasın korunmasında kurumsal uzmanlık kapasitesi zirveye taşındı."},{"label":"Kariye\'yi hem ücretsiz ibadethane hem de namaz vakitleri haricinde müze kalitesinde gezilen kültür köprüsüne dönüştür.","preview":"Adalet +8, Halk +8, Hazine +2, Otorite +6","effects":{"justice":8,"people":8,"treasury":2,"military":0,"authority":6},"log":"Hem ibadet hakkı hem de dünya mirasının ziyareti mükemmel bir sentezle sağlandı."}]', 703) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_704', 'modern', 'Şanlıurfa Göbeklitepe Kazılarına Yabancı Arkeolog Kılığında Sızan Casusluk Tehdidi', 'Kültür ve Turizm Bakanlığı', '12 bin yıllık \'tarihin sıfır noktası\' Göbeklitepe ve Taş Tepeler kazılarında, bazı yabancı araştırma enstitülerinin ve arkeologların bölgedeki jeolojik ve etnik haritalandırma yaparak istihbarat topladığı, paha biçilmez dikilitaş kabartmalarını gizlice kopyaladığı MİT tarafından raporlandı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Kültür Varlıkları Genel Müdürlüğü müfettişlerini gönder; kazı izinlerini ve yabancı heyetlerin tüm dijital kayıtlarını adli incelemeye al.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Yasadışı haritalandırma yapan yabancı araştırmacıların izinleri iptal edildi; deliller adli makamlara sunuldu."},{"label":"Alman Arkeoloji Enstitüsü ve UNESCO ile resmi protokol masası kur; kazı heyetlerinin başına Türk arkeologların geçmesini zorunlu kıl.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Kazı liderliği milli ellere geçti; Göbeklitepe bilimsel işbirliğiyle korunarak dünyaya tanıtıldı."},{"label":"Göbeklitepe ve Karahantepe çevre düzenlemesi ve koruma çatısı için Hazine\'den 100 milyon liralık acil ödenek tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dev koruma çatısı tamamlandı; 12 bin yıllık tapınaklar yağmur ve güneş tahribatından kurtarıldı."},{"label":"Şanlıurfa platosundaki neolitik kazı alanlarının etrafına gece görüşlü termal kameralar ve jandarma devriyeleri yerleştir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Tarihi kazı alanları 24 saat gözetleme altına alındı; kaçak kazı çeteleri inlerinde yakalandı."},{"label":"Arkeolojik kazılarda yabancı heyetlerin askeri/stratejik veri toplamasını casusluk sayan \'Arkeolojik İstihbarat Koruma Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Milli tarih korundu; Göbeklitepe Türkiye\'nin kültürel diplomasisinin en güçlü kalesi oldu."}]', 704) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_705', 'modern', 'Karahantepe ve Taş Tepeler Neolitik Çağ Keşifleri', 'Kültür ve Turizm Bakanlığı', 'Şanlıurfa platosunda Göbeklitepe\'den daha eski yerleşim kalıntıları bulunarak dünya arkeolojisi Türkiye\'ye aktı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Tarihi ve kültürel varlıkların korunmasında vakfiye şartları, Anayasa ve evrensel koruma ilkelerini gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kültürel miras korundu; ecdat yadigarı eserlerin restorasyonunda tarihi aslına sadık kalındı."},{"label":"Sanatçılar, kültür insanları ve sivil toplumla istişare kurulları toplayarak milli kültür politikasını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatında toplumsal mutabakat sağlandı; sanatçıların eser üretmesi desteklendi."},{"label":"Müze, kütüphane ve tarihi restorasyon projeleri için Hazine bütçesinden özel ödenekler ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kültür yatırımları finanse edildi; Türkiye\'nin tarihi mirası ihya edilerek turizme kazandırıldı."},{"label":"Tarihi eser kaçakçılarına ve sit alanlarını tahrip eden rant odaklarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sit alanları korundu; tarihi dokuyu bozan kaçak yapılaşmalar dozerlerle yıkıldı."},{"label":"Türkiye\'nin kültürel diplomasisini ve tarihi mirasını koruyan \'Milli Kültür ve Sanat Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Kültür politikası kanunlaştı; Türkiye\'nin tarihi derinliği dünyaya gururla tanıtıldı."}]', 705) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_706', 'modern', 'Zeugma Çingene Kızı Mozaiği ve ABD Müzelerindeki Çalıntı Mirasın İade Operasyonu', 'Kültür ve Turizm Bakanlığı', 'Gaziantep Nizip\'teki Zeugma antik kentinden 1960\'larda yağmalanıp ABD Bowling Green Üniversitesi\'ne satılan \'Çingene Kızı\' mozaiğinin kayıp 12 bordür parçası tespit edildi. ABD\'li üniversite parçaları iade etmeyi reddederken MİT ve Kültür Bakanlığı diplomatik ve istihbari baskı başlattı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"ABD federal mahkemelerinde mülkiyet ve tarihi eser kaçakçılığı davası açarak eserlerin Türkiye\'ye ait olduğunu kanıtla.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Hukuki zafer kazanıldı; ABD mahkemeleri eserlerin Türkiye\'den çalındığını onayladı."},{"label":"ABD Dışişleri Bakanlığı ve üniversite yönetimiyle istişare heyeti topla; kültürel değişim protokolüyle uzlaşı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Diplomasi sonuç verdi; 12 parça mozaik özel sandıklarla Türkiye\'ye iade edildi."},{"label":"Gaziantep Zeugma Mozaik Müzesi\'ne devlete ait fonlardan ek güvenlik ve sergileme bütçesi aktar; müzeyi dünya çapında yap.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Dünyanın en büyük mozaik müzesi kuruldu; Çingene Kızı kayıp parçalarıyla birleşerek turizm patlaması yaptı."},{"label":"Tarihi eser kaçakçılığı yapan uluslararası şebekelerin Türkiye\'deki işbirlikçilerine MİT ve KOM timleriyle şafak baskını yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kaçakçılık ağı çökertildi; yüzlerce lahit, heykel ve sikke yurtdışına çıkarılmadan sınırda yakalandı."},{"label":"Yurtdışına kaçırılan tarihi eserlerin iadesinde kırmızı bülten ve sınır ötesi operasyon yetkisi veren kanun çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kültür varlıkları milli dava haline geldi; binlerce yıllık Anadolu mirası birer birer yurda döndü."}]', 706) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_707', 'modern', 'Yorgun Herakles Heykelinin Boston Müzesi\'nden Getirilmesi', 'Kültür ve Turizm Bakanlığı', 'Antalya Perge kazılarında altı bulunan heykelin üst yarısı ABD\'den getirilerek müzede birleştirildi.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Tarihi ve kültürel varlıkların korunmasında vakfiye şartları, Anayasa ve evrensel koruma ilkelerini gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kültürel miras korundu; ecdat yadigarı eserlerin restorasyonunda tarihi aslına sadık kalındı."},{"label":"Sanatçılar, kültür insanları ve sivil toplumla istişare kurulları toplayarak milli kültür politikasını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatında toplumsal mutabakat sağlandı; sanatçıların eser üretmesi desteklendi."},{"label":"Müze, kütüphane ve tarihi restorasyon projeleri için Hazine bütçesinden özel ödenekler ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kültür yatırımları finanse edildi; Türkiye\'nin tarihi mirası ihya edilerek turizme kazandırıldı."},{"label":"Tarihi eser kaçakçılarına ve sit alanlarını tahrip eden rant odaklarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sit alanları korundu; tarihi dokuyu bozan kaçak yapılaşmalar dozerlerle yıkıldı."},{"label":"Türkiye\'nin kültürel diplomasisini ve tarihi mirasını koruyan \'Milli Kültür ve Sanat Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Kültür politikası kanunlaştı; Türkiye\'nin tarihi derinliği dünyaya gururla tanıtıldı."}]', 707) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_708', 'modern', 'Kaçırılan Binlerce Tarihi Eserin Kültür Bakanlığınca İadesi', 'Kültür ve Turizm Bakanlığı', 'İsviçre, Almanya ve İngiltere müzelerinden yüzlerce lahit, sikke ve heykel diplomatik baskıyla geri alındı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Kaçırılan Çingene Kızı mozaikleri, lahitler ve heykelleri uluslararası mahkemelerde diplomatik baskıyla Türkiye\'ye iade ettir.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Kültür diplomasisi zaferle sonuçlandı; ABD ve Avrupa müzelerindeki kaçak eserlerimiz şanlı bayrağımızın altına getirildi."},{"label":"Göbeklitepe\'yi UNESCO Dünya Mirası Listesi\'ne kaydettir; Şanlıurfa\'da \'Tarihin Sıfır Noktası\' turizm seferberliği başlat.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Dünya arkeolojisi Türkiye\'ye aktı; 12 bin yıllık tapınaklar milyonlarca turisti bölgeye çekerek esnafı ihya etti."},{"label":"Karahantepe ve Taş Tepeler neolitik kazı alanları için Kültür ve Turizm Bakanlığı\'na dev kazı ve koruma bütçesi tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Arkeolojik kazılar hızlandırıldı; Türkiye dünyanın 1 numaralı açık hava müzesi haline geldi."},{"label":"Tarihi ören yerlerinde defineci kaçak kazılarını önlemek için jandarma ve dron devriyeleriyle 24 saat nöbet tut.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Milli miras kaçakçılardan korundu; tarihi höyükleri talan eden define çeteleri suçüstü yakalandı."},{"label":"Kültür ve tabiat varlıkları kaçakçılığına en ağır hapis cezaları getiren \'Kültür Varlıklarını Koruma Reform Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Tarihi eser kaçakçılığı terör suçu derecesinde cezalandırıldı; Anadolu mirası yasal zırha kavuştu."}]', 708) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_709', 'modern', 'Taksim Meydanı\'nda AKM İnşası ve Sosyal Çatışma İstihbaratı', 'Kültür ve Turizm Bakanlığı', 'Taksim Meydanı\'ndaki yıpranmış Atatürk Kültür Merkezi\'nin yıkımı sırasında marjinal grupların Gezi benzeri kitlesel sokak çatışması çıkarma hazırlığı istihbarat edildi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"}]', '[{"label":"Meydan çevresinde yüksek güvenlik kordonu kurup projeyi şeffaf mimari sunumla kamuoyuna anlatarak provokasyonu boşa çıkar.","preview":"Adalet +7, Halk +7, Güvenlik +3, Otorite +8 | Hazine -3","effects":{"justice":7,"people":7,"treasury":-3,"military":3,"authority":8},"log":"Provokasyon hazırlığı boşa çıkarıldı; modern opera ve tiyatro projesi kamuoyuna tanıtıldı."},{"label":"Cumhuriyet estetiğini birleştiren opera salonu projesine tüm sanatçı sendikalarını ve mimarları paydaş olarak dahil et.","preview":"Adalet +9, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal uzlaşma sağlandı; sanat camiası projeyi sahiplendi."},{"label":"Yıkım ve inşaat alanına sızmaya çalışan yasadışı eylem hücrelerine önleyici istihbarat operasyonu yap.","preview":"Adalet +7, Halk +4, Güvenlik +4, Otorite +8","effects":{"justice":7,"people":4,"treasury":0,"military":4,"authority":8},"log":"Sokak kargaşası hedefleyen hücreler eyleme geçmeden yakalandı."},{"label":"Projeyi Taksim yayalaştırmasıyla birleştirip Taksim Meydanı\'nı tamamen yayalara açan yeşil aks planını uygula.","preview":"Adalet +7, Halk +9, Otorite +6 | Hazine -7","effects":{"justice":7,"people":9,"treasury":-7,"military":0,"authority":6},"log":"Taksim\'e dünya başkentlerine yakışır bir kültür meydanı ve opera salonu kazandırıldı."},{"label":"AKM\'nin tamamlanmasını hızlandırmak için 24 saat vardiyalı çalışma düzenine geçip kültür merkezini hızla halka aç.","preview":"Adalet +6, Halk +8, Otorite +7 | Hazine -5","effects":{"justice":6,"people":8,"treasury":-5,"military":0,"authority":7},"log":"İnşaat rekor sürede bitti; AKM uluslararası standartta bir kültür mabedi olarak parladı."}]', 709) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_710', 'modern', 'Çamlıca Camii ve Boğaz Silüeti: Deprem Sığınağı ve Stratejik Haberleşme Krizi', 'Kültür ve Turizm Bakanlığı', 'Çamlıca Tepesi\'ne devasa mabet inşası tartışılırken, kriz masası yapının altında 50 bin kişilik nükleer/kimyasal sığınak ve Boğaz\'ı izleyen stratejik haberleşme üssü kurulmasını önerdi.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_savunma_bakani","name":"Milli Savunma Bakanı"}]', '[{"label":"Caminin alt katlarını mega afet lojistik merkezi, acil sahra hastanesi ve kesintisiz haberleşme üssü olarak donat.","preview":"Adalet +6, Halk +8, Güvenlik +6, Otorite +7 | Hazine -7","effects":{"justice":6,"people":8,"treasury":-7,"military":6,"authority":7},"log":"Olası Marmara depreminde şehrin kilitlenmesini önleyecek hayati bir stratejik sığınak kazanıldı."},{"label":"Projeyi inşa ederken çevresindeki görüntü kirliliği oluşturan paslı verici direklerini tek bir fütüristik kulede birleştirip temizle.","preview":"Adalet +7, Halk +9, Otorite +7 | Hazine -6","effects":{"justice":7,"people":9,"treasury":-6,"military":0,"authority":7},"log":"Çamlıca Tepesi anten çöplüğünden kurtuldu; şehrin silüetine estetik bir vizyon kazandırıldı."},{"label":"İnşaatın kamu bütçesine yükünü sınırlamak için masrafları vakıf bağışları ve özel fonlarla karşıla.","preview":"Adalet +7, Halk +7, Hazine +4, Otorite +6","effects":{"justice":7,"people":7,"treasury":4,"military":0,"authority":6},"log":"Hazine kaynakları korunurken büyük proje hayırseverler ve vakıf geleneğiyle tamamlandı."},{"label":"Boğaz silüetine aykırı olduğu yönündeki mimari itirazları dikkate alarak yeşil alan ve koruma oranını iki katına çıkar.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Tepedeki ağaç dokusu korundu; çevre örgütleriyle yaşanan gerilim dindirildi."},{"label":"Projeyi İslam Sanatları Müzesi ve devasa kütüphane kompleksiyle birleştirerek küresel bir kültür merkezine dönüştür.","preview":"Adalet +7, Halk +8, Otorite +7 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Sadece ibadethane değil, gençlerin 24 saat ders çalıştığı devasa bir kültür vadisi kuruldu."}]', 710) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_711', 'modern', 'Kültür Diplomasisinde Kara Propaganda ve Yabancı Fonlu Festivallerin Etki Ajanlığı', 'Kültür ve Turizm Bakanlığı', 'Cannes, Berlin ve Venedik film festivallerinde fonlanan bazı yapımların, Türkiye\'yi terör destekçisi ve baskıcı gibi gösteren senaryolarla ödüllendirildiği tespit edildi. MİT ve Kültür Bakanlığı, yabancı istihbarat servislerinin sinema ve sanat vakıfları üzerinden Türkiye aleyhine örtülü psikolojik harp yürüttüğünü raporladı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Yabancı fon alan STK ve vakıfların mali kaynaklarını MASAK ve adli teftişe tabi tut; kara para ve etki ajanlığı bağlarını soruştur.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Karanlık fon hareketleri mercek altına alındı; yabancı servislerin kültürel finansman ağları deşifre edildi."},{"label":"Türk sinemacılar, yönetmenler ve yazarlarla kültür kurultayı topla; yerli ve milli hikayelerin dünyaya anlatılmasını teşvik et.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sanat dünyasıyla diyalog kuruldu; Türk sinemasının kendi öz değerleriyle evrensel ödüller alması desteklendi."},{"label":"TRT Sinema ve Kültür Bakanlığı Sinema Destekleme Fonu\'na Hazine\'den 500 milyon liralık dev bütçe aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli sinema şahlandı; bağımsız Türk filmleri yabancı fonlara muhtaç kalmadan dünya festivallerinde yarıştı."},{"label":"Festivallerde Türkiye aleyhine terör örgütü propagandası yapan paravan odakların kültürel sabotajlarını MİT ile engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Uluslararası festivallerde Türkiye\'nin tezleri savunuldu; kara propaganda filmleri diplomatik girişimlerle boşa çıkarıldı."},{"label":"Kültürel etki ajanlığı ve yabancı devlet fonlu dezenformasyon faaliyetlerini suç sayan \'Kültür Güvenliği Kanunu\' çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Kültürel bağımsızlık kanunlaştı; Türkiye\'nin tarihi derinliği ve vicdani sesi dünyaya gururla tanıtıldı."}]', 711) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_712', 'modern', 'Yabancı Fonlu Sinema Festivalleri ve Türkiye Aleyhtarı Film Propagandası', 'Kültür ve Turizm Bakanlığı', 'Avrupa festivallerinde fonlanan bazı yapımların Türkiye\'yi geri kalmış, yozlaşmış ve terörle ilişkili gösterme şartıyla finanse edildiği MİT kültür raporunda belgelendi.', '[{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"},{"id":"char_mit_mustesari","name":"MİT Müsteşarı / Başkanı"}]', '[{"label":"Kültür Bakanlığı bünyesinde güçlü \'Milli Sinema Fonu\' kurarak Türk sinemacıların yabancı siyasi fonlara muhtaçlığını bitir.","preview":"Adalet +8, Halk +8, Otorite +7 | Hazine -5","effects":{"justice":8,"people":8,"treasury":-5,"military":0,"authority":7},"log":"Bağımsız Türk sinemacıları siyasi şantajdan kurtarıldı; milli hikayeler dünya standartlarında fonlandı."},{"label":"Uluslararası festivallerde Türkiye\'yi karalayan yalan prodüksiyonlara karşı gerçek arşiv belgeleriyle karşı belgeseller fonla.","preview":"Adalet +7, Halk +7, Güvenlik +2, Otorite +7 | Hazine -4","effects":{"justice":7,"people":7,"treasury":-4,"military":2,"authority":7},"log":"Avrupa kamuoyundaki dezenformasyon dalgası yüksek kaliteli karşı yapımlarla püskürtüldü."},{"label":"Yabancı misyon ve enstitülerin Türkiye içindeki gizli senaryo yarışmaları ve fon dağıtımlarını MASAK incelemesine al.","preview":"Adalet +7, Halk +5, Hazine +1, Güvenlik +4, Otorite +8","effects":{"justice":7,"people":5,"treasury":1,"military":4,"authority":8},"log":"Kültürel alandaki yabancı etki ajanlığı ve gizli fon akışı deşifre edildi."},{"label":"Antalya Altın Portakal ve İstanbul Film Festivali\'ni dünya çapında prestijli alternatif kültür merkezleri haline getir.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Türk festivalleri Asya ve Akdeniz\'in en saygın bağımsız sinema arenası oldu."},{"label":"Sanat özgürlüğü ilkesine sadık kalarak sansür yerine yüksek nitelikli bağımsız Türk yapımlarına vergi muafiyeti sağla.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Sanatsal yaratıcılık teşvik edildi, sansür tartışmaları yerini nitelikli üretime bıraktı."}]', 712) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_713', 'modern', 'Nobel ve Uluslararası Edebiyat Ödüllerinde Siyasi Şart Dayatması', 'Kültür ve Turizm Bakanlığı', 'Batılı edebiyat komitelerinin Türk yazarlara ödül vermeden önce Ermeni tehciri ve etnik meseleler hakkında Türkiye\'yi mahkum eden siyasi demeçler vermesini şart koştuğu iddiaları kamuoyunu ikiye böldü.', '[{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Fikir ve edebiyat özgürlüğünü korurken, Türk tarihinin siyasi ödüllerle yargılanamayacağını diplomatik bildiriyle vurgula.","preview":"Adalet +8, Halk +7, Otorite +7","effects":{"justice":8,"people":7,"treasury":0,"military":0,"authority":7},"log":"Edebiyata saygı duyulurken devletin haysiyeti ve tarihi hakikatleri uluslararası alanda savunuldu."},{"label":"Türk edebiyatının dünya dillerine çevrilmesini sağlayan TEDA projesini 10 kat büyüterek kültürel diplomasiyi devlete bağla.","preview":"Adalet +7, Halk +8, Otorite +7 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Klasik ve çağdaş yüzlerce Türk eseri 60 dünya diline tercüme edilerek küresel okura ulaştı."},{"label":"Türk dünyası ve Doğu edebiyatlarını kapsayan bağımsız \'Avrasya Edebiyat ve Barış Ödülleri\' tesis et.","preview":"Adalet +7, Halk +7, Otorite +6 | Hazine -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Batı merkezli edebiyat hiyerarşisine karşı güçlü ve saygın bir doğu-batı köprüsü kuruldu."},{"label":"Siyasi demeçler veren yazarlara karşı linç kampanyalarını önlemek için fikir hürriyetini adli güvenceye al.","preview":"Adalet +9, Halk +6, Otorite +6","effects":{"justice":9,"people":6,"treasury":0,"military":0,"authority":6},"log":"Hukuk devleti ilkesi işletildi; fikirlerinden ötürü kimsenin hedef gösterilmesine izin verilmedi."},{"label":"Milli kütüphaneler ve üniversiteler aracılığıyla Türk edebiyatının klasikleri için küresel tanıtım atağı başlat.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Yunus Emre\'den Tanpınar\'a Türk edebiyat dehaları dünyada hak ettiği ilgiyi gördü."}]', 713) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_714', 'modern', 'Prof. Dr. Aziz Sancar ve Tersine Beyin Göçü: Stratejik Moleküler Laboratuvar', 'Kültür ve Turizm Bakanlığı', 'Nobel Kimya Ödülü sonrası Türk bilim insanlarının yurtdışına kaçışını önlemek ve savunma sanayiine biyoteknolojik güç katmak için stratejik enstitü kurulması talebi masaya geldi.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Savur\'dan dünyaya uzanan başarıyı model alarak Aziz Sancar Moleküler Biyoloji ve DNA Araştırma Merkezi\'ni kur.","preview":"Adalet +7, Halk +9, Güvenlik +3, Otorite +7 | Hazine -6","effects":{"justice":7,"people":9,"treasury":-6,"military":3,"authority":7},"log":"Türkiye\'nin en donanımlı moleküler laboratuvarı açıldı; milli tıp araştırmaları hız kazandı."},{"label":"Yurtdışındaki kritik Türk bilim insanlarına tam araştırma bütçesi ve bürokrasisiz çalışma güvencesiyle tersine beyin göçü başlat.","preview":"Adalet +8, Halk +8, Güvenlik +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":8,"treasury":-7,"military":4,"authority":7},"log":"Yüzlerce dahi Türk bilim insanı vatanına dönerek kritik projelerin başına geçti."},{"label":"TÜBİTAK ve üniversitelerdeki genç araştırmacılara uluslararası fon yerine yerli Ar-Ge teşvik bursu bağla.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -5","effects":{"justice":7,"people":8,"treasury":-5,"military":0,"authority":6},"log":"Genç akademisyenlerin yabancı burs arayışına girmeden ülkede kalması sağlandı."},{"label":"Kanser ve genetik araştırmalarında dışa bağımlılığı bitirecek yerli ilaç sanayii konsorsiyumu ilan et.","preview":"Adalet +7, Halk +8, Güvenlik +2, Otorite +7 | Hazine -6","effects":{"justice":7,"people":8,"treasury":-6,"military":2,"authority":7},"log":"Stratejik ilaç ve aşı üretiminde dışa bağımlılık kırılarak sağlık güvenliği tahkim edildi."},{"label":"Temel bilimler liseleri ve olimpiyat kampları açarak yeni nesil bilim insanlarını devlet himayesine al.","preview":"Adalet +8, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Anadolu\'nun zeki çocukları keşfedilip geleceğin Nobel adayı olarak yetiştirilmeye başlandı."}]', 714) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_715', 'modern', 'Kurumsal Reformlar ve Şeffaflık: Nobel Tezlerinin Ekonomiye Uyarlanması', 'Kültür ve Turizm Bakanlığı', 'Kurumların hukuki bağımsızlığı ve kapsayıcı ekonomi tezleri tartışılırken, piyasalardaki güvensizlik ve bürokratik vesayet baskısı kapsamlı bir hukuk-ekonomi reformunu zorunlu kıldı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Yargı bağımsızlığı, mülkiyet güvencesi ve ihale şeffaflığını garanti eden \'Kurumsal Adalet ve Ekonomi Reform Paketi\' çıkar.","preview":"Adalet +9, Halk +8, Hazine +4, Otorite +7","effects":{"justice":9,"people":8,"treasury":4,"military":0,"authority":7},"log":"Hukuki güvence piyasalara güven getirdi; doğrudan yabancı yatırımlar rekor kırdı."},{"label":"Düzenleyici kurulların (BDDK, SPK, Rekabet Kurumu) siyasi müdahalelerden arındırılmış bağımsız liyakat yapısını pekiştir.","preview":"Adalet +8, Halk +7, Hazine +5, Otorite +6","effects":{"justice":8,"people":7,"treasury":5,"military":0,"authority":6},"log":"Ekonomide kurumların kurallarla yönetildiği öngörülebilir bir piyasa düzeni kuruldu."},{"label":"İktisadi planlamada yerli ve milli sanayileşmeyi ön planda tutan dengeli bir karma kalkınma modeli uygula.","preview":"Adalet +7, Halk +8, Güvenlik +3, Otorite +7 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":3,"authority":7},"log":"Stratejik sektörler kamu öncülüğünde korunurken özel sektörün önü açıldı."},{"label":"Akademik ve ekonomik düşünce kuruluşlarının hazırladığı bağımsız denetim raporlarını hükümet politikalarına entegre et.","preview":"Adalet +8, Halk +6, Hazine +2, Otorite +5","effects":{"justice":8,"people":6,"treasury":2,"military":0,"authority":5},"log":"Karar alma süreçlerinde ortak akıl ve liyakat hakim kılındı."},{"label":"Bürokratik işlemleri ve keyfi kamulaştırma risklerini sıfıra indiren uluslararası yatırım güvence yasasını onayla.","preview":"Adalet +7, Halk +5, Hazine +7, Otorite +6","effects":{"justice":7,"people":5,"treasury":7,"military":0,"authority":6},"log":"Bürokrasi azaltıldı; sanayiciye üretim ve istihdam için tam güvence verildi."}]', 715) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_716', 'modern', 'Fazıl Say\'ın Besteleri ve Hakkında Açılan Davaların Beraati', 'Kültür ve Turizm Bakanlığı', 'Dünyaca ünlü piyanist hakkında sosyal medya paylaşımları sebebiyle açılan davalar beraatle sonuçlandı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Tarihi ve kültürel varlıkların korunmasında vakfiye şartları, Anayasa ve evrensel koruma ilkelerini gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kültürel miras korundu; ecdat yadigarı eserlerin restorasyonunda tarihi aslına sadık kalındı."},{"label":"Sanatçılar, kültür insanları ve sivil toplumla istişare kurulları toplayarak milli kültür politikasını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatında toplumsal mutabakat sağlandı; sanatçıların eser üretmesi desteklendi."},{"label":"Müze, kütüphane ve tarihi restorasyon projeleri için Hazine bütçesinden özel ödenekler ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kültür yatırımları finanse edildi; Türkiye\'nin tarihi mirası ihya edilerek turizme kazandırıldı."},{"label":"Tarihi eser kaçakçılarına ve sit alanlarını tahrip eden rant odaklarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sit alanları korundu; tarihi dokuyu bozan kaçak yapılaşmalar dozerlerle yıkıldı."},{"label":"Türkiye\'nin kültürel diplomasisini ve tarihi mirasını koruyan \'Milli Kültür ve Sanat Reform Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kültür politikası kanunlaştı; Türkiye\'nin tarihi derinliği dünyaya gururla tanıtıldı."}]', 716) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_717', 'modern', 'Türk Dizi Sektörünün Dünyada İhracat İkincisi Olması', 'Kültür ve Turizm Bakanlığı', 'Latin Amerika\'dan Orta Doğu\'ya 150 ülkeye ihraç edilen Türk dizileri 1 milyar seyirciye ulaştı.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Devlet televizyonunda TRT Kurdî ile farklı dillerde yayın hakkını anayasal kültürel haklar çerçevesinde güvenceye al.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Tarihi kültürel tabu yıkıldı; TRT Kurdî ile kardeşlik hukuku tahkim edilerek terörün istismar kapısı kapatıldı."},{"label":"Taksim Meydanı\'ndaki Atatürk Kültür Merkezi\'ni (AKM) opera, bale ve tiyatronun kalbi olarak halka aç.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatı canlandı; modern opera salonu ve kültür kompleksi İstanbulluların buluşma noktası oldu."},{"label":"150 ülkeye ihraç edilen ve 1 milyar seyirciye ulaşan Türk dizi sektörüne Ticaret Bakanlığı eliyle hizmet ihracatı desteği ver.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Dizi sektörü Türkiye\'ye milyarlarca dolar kazandırdı; Latin Amerika\'dan Orta Doğu\'ya kadar Türk kültürü hayranlığı oluştu."},{"label":"Kültürel etkinliklerde ve film festivallerinde terör propagandası ve milli değerlere hakaret girişimlerini engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kültürel alan provokasyonlardan korundu; sanatın terör propagandasına alet edilmesine izin verilmedi."},{"label":"Sinema, dizi ve müzik sektörlerinde telif haklarını ve yapımcı paylarını güvenceye alan \'Yeni Sinema ve Telif Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Sanatçıların ve yapımcıların telif gelirleri korundu; Türk sinema endüstrisi küresel rekabete hazırlandı."}]', 717) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
