INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_721', 'modern', 'Sinemada \'Mısır Krizi\' ve Yeni Sinema Kanunu', 'Kültür ve Turizm Bakanlığı', 'Film yapımcıları ile mısır promosyonu dayatan sinema salon zincirleri arasındaki kriz yasayla çözüldü.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Tarihi ve kültürel varlıkların korunmasında vakfiye şartları, Anayasa ve evrensel koruma ilkelerini gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kültürel miras korundu; ecdat yadigarı eserlerin restorasyonunda tarihi aslına sadık kalındı."},{"label":"Sanatçılar, kültür insanları ve sivil toplumla istişare kurulları toplayarak milli kültür politikasını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatında toplumsal mutabakat sağlandı; sanatçıların eser üretmesi desteklendi."},{"label":"Müze, kütüphane ve tarihi restorasyon projeleri için Hazine bütçesinden özel ödenekler ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kültür yatırımları finanse edildi; Türkiye\'nin tarihi mirası ihya edilerek turizme kazandırıldı."},{"label":"Tarihi eser kaçakçılarına ve sit alanlarını tahrip eden rant odaklarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sit alanları korundu; tarihi dokuyu bozan kaçak yapılaşmalar dozerlerle yıkıldı."},{"label":"Türkiye\'nin kültürel diplomasisini ve tarihi mirasını koruyan \'Milli Kültür ve Sanat Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorit