INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_722', 'modern', 'Müzik Meslek Birlikleri (MESAM, MSG, MÜYAP) Telif Krizleri', 'Kültür ve Turizm Bakanlığı', 'Dijital müzik gelirlerinin dağıtımı konusunda sanatçılar arasında yaşanan telif kavgaları mahkemeye taşındı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Tarihi ve kültürel varlıkların korunmasında vakfiye şartları, Anayasa ve evrensel koruma ilkelerini gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kültürel miras korundu; ecdat yadigarı eserlerin restorasyonunda tarihi aslına sadık kalındı."},{"label":"Sanatçılar, kültür insanları ve sivil toplumla istişare kurulları toplayarak milli kültür politikasını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Kültür hayatında toplumsal mutabakat sağlandı; sanatçıların eser üretmesi desteklendi."},{"label":"Müze, kütüphane ve tarihi restorasyon projeleri için Hazine bütçesinden özel ödenekler ayır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kültür yatırımları finanse edildi; Türkiye\'nin tarihi mirası ihya edilerek turizme kazandırıldı."},{"label":"Tarihi eser kaçakçılarına ve sit alanlarını tahrip eden rant odaklarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sit alanları korundu; tarihi dokuyu bozan kaçak yapılaşmalar dozerlerle yıkıldı."},{"label":"Türkiye\'nin kültürel diplomasisini ve tarihi mirasını koruyan \'Milli Kültür ve Sanat Reform Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kültür politikası kanunlaştı; Türkiye\'nin tarihi derinliği dünyaya gururla tanıtıldı."}]', 722) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_723', 'modern', 'CSO Tarihi İnşaatında Bütçe Aşımı ve Kültürde İsraf İddiaları', 'Kültür ve Turizm Bakanlığı', 'Başkentin simgesi Cumhurbaşkanlığı Senfoni Orkestrası binasının 23 yıldır süren inşaatında dönen yolsuzluk iddiaları ve bütçe aşımı teftişe takıldı.', '[{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Müteahhit ve müşavir firmaların 23 yıllık harcama kayıtlarını Sayıştay ve Mülkiye Teftiş Kurulu\'na inceletip hesabı sor.","preview":"Adalet +9, Halk +7, Hazine +4, Otorite +8","effects":{"justice":9,"people":7,"treasury":4,"military":0,"authority":8},"log":"Yılların ihmal ve vurgun defterleri açıldı; kamunun hakkı kuruşu kuruşuna tahsil edildi."},{"label":"İnşaatı TOKİ disipliniyle 6 ayda tamamlayıp başkente dünya çapında bir akustik konser salonu kazandır.","preview":"Adalet +6, Halk +8, Otorite +7 | Hazine -6","effects":{"justice":6,"people":8,"treasury":-6,"military":0,"authority":7},"log":"23 yıllık yılan hikayesi bitti; Ankara dünyanın en modern konser salonlarından birine kavuştu."},{"label":"Binayı sadece Batı klasik müziğine değil, Türk Sanat ve Halk Müziği topluluklarına da eşit oranda tahsis et.","preview":"Adalet +8, Halk +9, Otorite +6","effects":{"justice":8,"people":9,"treasury":0,"military":0,"authority":6},"log":"Kültürel ayrımcılık sona erdi; milletin tüm ezgileri aynı çatı altında buluştu."},{"label":"Salonun işletmesini özel sanat vakıflarına devrederek kamu bütçesi üzerindeki cari işletme yükünü sıfırla.","preview":"Adalet +6, Halk +5, Hazine +6, Otorite +5","effects":{"justice":6,"people":5,"treasury":6,"military":0,"authority":5},"log":"Hazine bütçesi hafifletildi; profesyonel sanat yönetimiyle gelir artırıldı."},{"label":"Anadolu\'daki tüm genç yeteneklerin ücretsiz konser verebileceği ulusal bir orkestra staj akade