INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_725', 'modern', 'Genç Müzisyenlerin Uluslararası Vize Ambargosu ve Koro Diplomasisi', 'Kültür ve Turizm Bakanlığı', 'Dünya koro şampiyonu olan genç müzisyenlerin ve sanatçıların Avrupa ve ABD vizelerinin siyasi bahanelerle reddedilmesi uluslararası skandala dönüştü.', '[{"id":"char_disisleri_bakani","name":"Dışişleri Bakanı"},{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"}]', '[{"label":"Milli sporcu ve sanatçılara diplomatik/yeşil pasaport hakkı tanıyarak vize ambargosunu kökten aşmalarını sağla.","preview":"Adalet +8, Halk +9, Otorite +7 | Hazine -2","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Genç sanatçıların seyahat engeli aşıldı; Türk bayrağı dünya sahnelerinde dalgalandı."},{"label":"Türk sanatçılara vize çıkarmayan Batılı ülkelerin kültür heyetlerine mütekabiliyet esasıyla vize kısıtlaması getir.","preview":"Adalet +7, Halk +6, Güvenlik +2, Otorite +8","effects":{"justice":7,"people":6,"treasury":0,"military":2,"authority":8},"log":"Mütekabiliyet ilkesi işletildi; Batılı misyonlar Türk vizesi için geri adım attı."},{"label":"Gençlerin yarışma ve turne masraflarını Kültür Diplomasi Fonu\'ndan karşılayarak resmi devlet koruması ver.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Genç koro hiçbir bürokratik engelle karşılaşmadan şampiyonluk ödüllerini topladı."},{"label":"Uluslararası sanat komitelerine resmi şikayet mektubu yazarak sanatçıların seyahat hakkının engellenmesini kına.","preview":"Adalet +7, Halk +7, Otorite +6","effects":{"justice":7,"people":7,"treasury":0,"military":0,"authority":6},"log":"Uluslararası kültür kamuoyu Türkiye\'nin haklı protestosuna destek verdi."},{"label":"Balkan ve Asya ülkeleriyle vizesiz kültür festivalleri paktı imzalayarak alternatif sanat sahneler