INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_728', 'modern', 'Sümela Manastırı Restorasyonunda Yabancı Misyon Ayinleri ve İstihbarat Hassasiyeti', 'Kültür ve Turizm Bakanlığı', 'Sümela\'nın sarp kayalıklarının restorasyonu biterken Fener Rum Patrikhanesi ve yabancı heyetlerin Pontus propagandasına alet edilen kontrolsüz ayin talepleri Karadeniz\'de gerilim yarattı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"}]', '[{"label":"Ayin iznini sadece resmi heyetle ve Türk emniyetinin sıkı gözetimi altında yılda tek günle sınırlandırarak egemenliği koru.","preview":"Adalet +7, Halk +7, Hazine +1, Güvenlik +3, Otorite +8","effects":{"justice":7,"people":7,"treasury":1,"military":3,"authority":8},"log":"Ayin ibadet sınırları içinde tutuldu, siyasi provokasyona sıfır tolerans gösterildi."},{"label":"Tarihi fresklerin ve sarp kayalıkların korunmasını gerekçe göstererek ziyaretçi sayısına sıkı kota ve güvenlik araması koy.","preview":"Adalet +7, Halk +6, Hazine +2, Güvenlik +2, Otorite +7","effects":{"justice":7,"people":6,"treasury":2,"military":2,"authority":7},"log":"Bin yıllık tarihi miras tahribattan ve vandalizmden kurtarıldı."},{"label":"Ayin bahanesiyle bölgede etnik ve siyasi ajanda yürüten yabancı istihbarat unsurlarını deşifre edip sınır dışı et.","preview":"Adalet +8, Halk +6, Güvenlik +5, Otorite +8","effects":{"justice":8,"people":6,"treasury":0,"military":5,"authority":8},"log":"Karadeniz\'de fitne çıkarmaya çalışan yabancı ajan ağları tasfiye edildi."},{"label":"Sümela\'yı Türk-İslam ve Doğu Roma ortak mimari mirası olarak tüm dünyaya tanıtan yüksek profilli bir müze projesi başlat.","preview":"Adalet +8, Halk +8, Hazine +5, Otorite +6","effects":{"justice":8,"people":8,"treasury":5,"military":0,"authority":6},"log":"Trabzon\'a yılda yüz binlerce yabancı turist çeken devasa bir turizm geliri sağlandı."},{"label":"Bölgedeki yerel halk ve sivil toplum kuruluşlarıyla kriz masası toplayıp provokasyonlara karşı sağduyu çağrısı yap.","preview":"Adalet +7, Halk +8, Otorite +6","effects":{"justice":7,"people":8,"treasury":0,"military":0,"authority":6},"log":"Yerel halkın hassasiyetleri gözetildi, toplumsal barış sağlandı."}]', 728) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
