INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_735', 'modern', '5 Büyük Zincir Markete Rekabet Kurumu\'ndan 2.7 Milyar TL Ceza', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Ortak fiyat belirleyerek kartel oluşturdukları tespit edilen perakende devlerine tarihi ceza kesildi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Rekabet Kurumu marifetiyle zincir marketlerin \'hub-and-spoke\' kartel anlaşmalarını belgele ve milyarlarca liralık ceza kes.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Kartel çetesi çökertildi; 5 büyük zincir markete rekabet kanununu ihlalden 2.7 milyar TL rekor ceza kesildi."},{"label":"Türkiye Perakendeciler Federasyonu ve yerel marketlerle görüşerek 1000 temel gıda ürününde 1 yıl fiyat sabitleme mutabakatı yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Piyasada fiyat istikrarı sağlandı; yerel marketler un, yağ ve şekerde zam yapmayarak vatandaşı korudu."},{"label":"Haksız Fiyat Değerlendirme Kurulu\'nun kestiği idari para cezalarını doğrudan Hazine gelirlerine irad kaydet.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine kasasına gelir sağlandı; fahiş fiyat artışıyla haksız kazanç sağlayanların paraları devlete geçti."},{"label":"Ticaret Bakanlığı müfettişleri ve zabıta ekiplerini 81 ilde eşzamanlı etiket ve stok denetimine çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Market depolarında stokçular yakalandı; raf ile kasa arasındaki fiyat hilelerine anında ceza yağdı."},{"label":"Marketlerde tarladan sofraya fiyat takibini zorunlu kılan \'Hal Kanunu ve Perakende Ticaret Reformu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Aracı ve komisyoncu rantı kırıldı; üretici ile tüketici arasındaki fahiş makas kanunla daraltıldı."}]', 735) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_736', 'modern', 'Hal Yasası Reformu: Tarladan Sofraya Komisyoncu Zinciri', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Aracı komisyoncuların sebze ve meyve fiyatlarını katlamasını önleyecek yeni hal modeli meclise taşındı.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Ticari ilişkilerde tüketici hakları, sözleşme serbestisi ve dürüstlük kuralını mahkemelerde tavizsiz koru.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tüketicinin hakkı korundu; hileli satış ve fahiş fiyat uygulamalarına karşı yargı devreye girdi."},{"label":"Esnaf odaları, ticaret odaları ve tüketici dernekleriyle istişare kurulları toplayarak pazar uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada sosyal uzlaşı sağlandı; esnaf ile müşteri arasındaki anlaşmazlıklar diyalogla giderildi."},{"label":"Ticaret hacmini artırırken kayıtdışı işlemleri önleyerek Hazine vergi gelirlerini koruma altına al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Vergi kayıpları engellendi; perakende ticaret Hazine denetimine alındı."},{"label":"Karaborsa, sahte ürün ve kaçak ticaret yapan şebekelere karşı maliye ve polis zabıtasını göreve çağır.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Pazar yerlerinde asayiş sağlandı; kaçak ve sahte ürünlerin piyasaya girmesi engellendi."},{"label":"Piyasa gözetimi ve tüketici hakem heyetlerini güçlendiren \'Tüketicinin Korunması Reform Kanunu\' çıkar.","preview":"Adalet