INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_737', 'modern', 'Tanzim Satış Noktaları: Sebze-Meyve Çadırları (2019)', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Büyükşehirlerde fahiş fiyatları kırmak için belediyeler meydanlara çadır kurup maliyetine patates sattı.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Et ve Süt Kurumu (ESK) ile spekülatif et stokçuluğu yapan büyük tüccarlar hakkında adli ve mali soruşturma açtır.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Et piyasasındaki fırsatçılar yargıya sevk edildi; spekülatörlerin kesimhanelerde et saklaması önlendi."},{"label":"Büyükşehir meydanlarında belediyeler ve Tarım Kredi eliyle tanzim satış çadırları kurarak sebzeyi maliyetine sat.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Dar gelirli rahat nefes aldı; domates, biber ve patateste aracı vurgunu kırıldı, fiyatlar yarı yarıya indi."},{"label":"Tarım Kredi Kooperatif Marketlerinin 3 bin şubeye ulaşması için Hazine destekli ucuz kredi hattı aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Market ağı 81 ile yayıldı; Hazine kaynaklarıyla doğrudan üreticiden alınıp tüketiciye ulaştırılan model büyütüldü."},{"label":"Besihanelerde et kesimini durdurup piyasayı kilitlemeye çalışan lobilere karşı tarım zabıtasıyla baskın yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Piyasada suni et kıtlığı yaratılması engellendi; kombinalarda kesimler hızla başlatıldı."},{"label":"Gıda arz güvenliğini sağlayan ve temel gıda madd