INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_740', 'modern', 'İthal Canlı Hayvan ve Karkas Et İthalatıyla Piyasa Müdahalesi', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Yetersiz yerli besicilik karşısında piyasayı dengelemek için Uruguay ve Brezilya\'dan angus ithal edildi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Ticari ilişkilerde tüketici hakları, sözleşme serbestisi ve dürüstlük kuralını mahkemelerde tavizsiz koru.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Tüketicinin hakkı korundu; hileli satış ve fahiş fiyat uygulamalarına karşı yargı devreye girdi."},{"label":"Esnaf odaları, ticaret odaları ve tüketici dernekleriyle istişare kurulları toplayarak pazar uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Piyasada sosyal uzlaşı sağlandı; esnaf ile müşteri arasındaki anlaşmazlıklar diyalogla giderildi."},{"label":"Ticaret hacmini artırırken kayıtdışı işlemleri önleyerek Hazine vergi gelirlerini koruma altına al.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Vergi kayıpları engellendi; perakende ticaret Hazine denetimine alındı."},{"label":"Karaborsa, sahte ürün ve kaçak ticaret yapan şebekelere karşı maliye ve polis zabıtasını göreve çağır.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Pazar yerlerinde asayiş sağlandı; kaçak ve sahte ürünlerin piyasaya girmesi engellendi."},{"label":"Piyasa gözetimi ve tüketici hakem heyetlerini güçlendiren \'Tüketicinin Korunması Reform Kanunu\' çıkar.","preview