INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_742', 'modern', 'Otomotivde \'6 Ay ve 6 Bin Kilometre\' Satış Sınırı', 'Ticaret Bakanlığı & Rekabet Kurumu', 'Sıfır araçları alıp liste fiyatının üstünde \'sıfır gibi\' ikinci el satan al-satçılara kanuni set çekildi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Sıfır araçları stoklayıp liste fiyatının üzerinde listeleyen yetkili bayilerin ticaret lisanslarını iptal et.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Otomotiv fırsatçılarına tokat vuruldu; haksız kazanç sağlayan yüzlerce galeri ve bayiye kapatma cezası kesildi."},{"label":"Otomotiv Yetkili Satıcıları Derneği (OYDER) ile görüşerek liste fiyatından satış ve şeffaf teslimat taahhüdü al.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Piyasa rayına oturdu; vatandaşların sıfır araca liste fiyatından erişmesi güvenceye bağlandı."},{"label":"Yılda 3\'ten fazla araç alıp satan ve vergi kaçıran al-satçılardan geçmişe dönük vergi ve cezaları Hazineye tahsil et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kayıtdışı oto ticaretine vergi darbesi vuruldu; Hazineye yüz milyonlarca liralık vergi geliri girdi."},{"label":"Oto galericiler siteleri ve otoparklarda saklanan sıfır kilometre plakalı araçları polis drone\'larıyla tespit et.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Stokçuluk yuvaları basıldı; gizli otoparklarda saklanan yüzlerce lüks araç piyasaya sürüldü."},{"label":"İkinci el araç satışlarında \'6 Ay ve 6 Bin Km\' şartını getiren \'Motorlu Kara Taşıtları Ticareti Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Otomobil yatırım aracı olmaktan çıkarıldı; ikinci el araç fiyatlarındaki fahiş balon patlatıldı."}]', 742) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
