INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_761', 'modern', 'Akaryakıtta Eşel Mobil Sistemi ile Pompa Fiyatı Kalkanı', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Uluslararası petrol fiyatları ve kur arttığında ÖTV\'den feragat edilerek akaryakıt zammı vatandaşa yansıtılmadı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Akaryakıt kaçakçılığı, 10 numara yağ ve faturasız yakıt satan istasyonları EPDK denetimiyle kapatıp savcılığa sevk et.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Akaryakıtta vergi kaçakçılığı önlendi; ulusal marker denetimiyle kaçak petrol şebekeleri çökertildi."},{"label":"Petrol fiyatları tırmanırken Eşel Mobil Sistemi ile ÖTV\'den feragat ederek pompa fiyatlarını sabit tut.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Vatandaş ve nakliyeci korundu; akaryakıt zamlarının enflasyonu ve nakliye maliyetlerini vurması engellendi."},{"label":"Ulusal Taşıt Tanıma Sistemi (UTTS) zorunluluğu getirerek akaryakıt fişlerindeki yıllık 15 milyar liralık KDV kaybını Hazineye kazandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine kasasına dev gelir girdi; şirketlerin sahte akaryakıt fişiyle gider göstermesi çipli sistemle sıfırlandı."},{"label":"Kaçak akaryakıt boru hatları ve tanker kaçakçılığına karşı jandarma ve gümrük muhafaza timlerini sınıra yığ.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır kapılarında kaçak yakıt geçişleri durduruldu; organize petrol kaçakçıları yakalandı."},{"label":"Enerji Piyasası Düzenleme Kurumu (EPDK) denetim yetkilerini artıran \'Petrol Piyasası Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Akaryakıt sektörü tam şeffaflığa kavuştu; dağıtıcı ve bayiler arasındaki kar payı kanunla düzenlendi."}]', 761) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_762', 'modern', 'Elektrik Faturalarında Kademeli Tarife Uygulaması', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Aylık 240 kilovatsaate kadar olan düşük elektrik tüketimi sübvanse edildi, fazlasına yüksek tarife uygulandı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Elektrik ve doğalgaz dağıtım şirketlerinin haksız fatura ve sayaç okuma hatalarını EPDK marifetiyle adli teftişe aç.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Tüketici hakkı korundu; haksız yere yüksek fatura kesen dağıtım şirketlerine ağır cezalar uygulandı."},{"label":"Dar gelirli hanelerin düşük elektrik ve gaz tüketimini Hazine sübvansiyonuyla %50 indirimli faturalandır.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Sosyal devlet desteği verildi; milyonlarca haneye kış aylarında ısınma ve elektrik desteği doğrudan yansıtıldı."},{"label":"Tuz Gölü Yeraltı Doğalgaz Depolama Tesisinin kapasitesini 5.4 milyar metreküpe çıkararak kış gaz krizlerini bertaraf et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Stratejik rezerv kuruldu; kış aylarında spot piyasadan pahalı gaz alımının önüne geçilerek milyarlarca dolar tasarruf edildi."},{"label":"Doğalgaz kompresör istasyonları ve yer altı depolarını olası terör sabotajlarına karşı jandarma üsleriyle koru.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Enerji arz güvenliği korundu; ulusal gaz iletim şebekesinin kesintisiz çalışması temin edildi."},{"label":"Enerji verimliliği ve akıllı şebeke dönüşümünü zorunlu kılan \'Milli Enerji Verimliliği ve Depolama Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Enerji israfı önlendi; Türkiye\'nin enerji yoğunluğu azaltılarak küresel standartlara ulaşıldı."}]', 762) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_763', 'modern', 'Organize Sanayi Bölgelerinde (OSB) Kış Doğalgaz Kısıntıları', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Boru hatlarındaki basınç düşüşü sebebiyle sanayi tesislerine gaz kısıntısı uygulanarak konutlar korundu.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Madencilik ve enerji faaliyetlerinde iş güvenliği, çevre kanunları ve ruhsat şartlarını bağımsız denetle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Madenlerde iş güvenliği korundu; çevreye zarar veren kuralsız işletmeler durduruldu."},{"label":"Maden işçileri, sendikalar ve sektör temsilcileriyle ortak istişare meclisi kurarak madencilik barışını sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog sağlandı; maden işçilerinin çalışma koşulları ve ücretleri iyileştirildi."},{"label":"Yerli maden üretimi ve cevher zenginleştirme yatırımlarına Hazine bütçesinden teşvik ve vergi indirimi sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli madencilik desteklendi; yerli kaynaklarla sanayinin hammadde ihtiyacı karşılandı."},{"label":"Ruhsatsız kaçak maden ocaklarına ve kömür hırsızlığına karşı jandarma komandolarıyla baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kaçak madenler kapatıldı; can güvenliğini hiçe sayan merdiven altı işletmeler mühürlendi."},{"label":"Maden çalışanlarına yıpranma payı ve erken emeklilik getiren \'Maden İşçileri ve Sektörel Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Madencilerin özlük hakları kanunlaştı; işçi sağlığı en yüksek yasal korumaya alındı."}]', 763) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
