INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_771', 'modern', 'Bandırma Bor Karbür Üretim Tesisinin Hizmete Alınması', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Eti Maden tonu 500 dolar olan bor madenini tonu 40 bin dolar olan zırh ve aşındırıcı tozuna dönüştürdü.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Beylikova\'daki 694 milyon tonluk nadir toprak elementleri ve Eti Maden rezervlerini milli egemenlik tesciline al.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli maden hakları korundu; dünyanın 2. büyük nadir element rezervi devletin kontrolünde tescillendi."},{"label":"Bandırma ve Eskişehir tesislerinde yerli üniversite ve kimya mühendisleriyle ortak Ar-Ge şurası topla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Yerli teknoloji ekosistemi kuruldu; lityum, bor ve çip üretiminde milli kabiliyet geliştirildi."},{"label":"Ham bor satmak yerine tonu 40 bin dolar olan Bor Karbür ve zırh malzemesi üreterek Hazineye devasa ihracat geliri sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Katma değerli madencilik başladı; Türkiye ham cevher satıcılığından ileri teknoloji ihracatçılığına geçti."},{"label":"Milli maden tesisleri ve zenginleştirme fabrikalarını yabancı siber casusluk ve sabotajlara karşı askeri korumaya al.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik maden üsleri korundu; Türkiye\'nin nadir element formüllerinin dışarı sızması engellendi."},{"label":"Stratejik madenlerin yabancılara imtiyaz olarak devredilmesini yasaklayan \'Milli Maden ve Tabii Kaynaklar Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Bor ve nadir elementler anayasal korumaya alındı; Türkiye\'nin yer altı zenginliği geleceğe mühürlendi."}]', 771) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_772', 'modern', 'Eskişehir Beylikova Nadir Toprak Elementleri: Çin Karteli ve Batı İstihbaratı', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Dünyanın en büyük ikinci nadir toprak elementi rezervi Beylikova\'da keşfedilirken, hammaddeyi ucuza kapatmak isteyen Çin tekeli ile tesislere sızmaya çalışan Batılı casusluk şebekeleri tespit edildi.', '[{"id":"char_enerji_bakani","name":"Enerji ve Tabii Kaynaklar Bakanı"},{"id":"char_mit_mustesari","name":"MİT Müsteşarı / Başkanı"}]', '[{"label":"Maden sahasını \'Özel Askeri Güvenlik Bölgesi\' ilan edip ham cevher ihracatını yasakla; sadece yerli rafine ürün satışı şartı koy.","preview":"Adalet +7, Halk +8, Hazine +8, Güvenlik +6, Otorite +9","effects":{"justice":7,"people":8,"treasury":8,"military":6,"authority":9},"log":"Milli servetin hammadde olarak sömürülmesi önlendi; Türkiye katma değerli teknoloji üreticisi oldu."},{"label":"Eti Maden bünyesinde ileri teknoloji arıtma ve oksit ayrıştırma pilot tesisini kamu yatırımıyla ivedilikle kur.","preview":"Adalet +6, Halk +7, Güvenlik +4, Otorite +7 | Hazine -8","effects":{"justice":6,"people":7,"treasury":-8,"military":4,"authority":7},"log":"Çin tekeline meydan okuyan yerli arıtma tesisi kuruldu; stratejik elementler millileştirildi."},{"label":"Maden sahasında çalışan yabancı mühendislerin iletişimini MİT sinyal istihbaratıyla 24 saat kriptolu takibe al.","preview":"Adalet +6, Halk +4, Güvenlik +7, Otorite +8 | Hazine -2","effects":{"justice":6,"people":4,"treasury":-2,"military":7,"authority":8},"log":"Gizli numuneleri yurtdışına kaçırmaya çalışan yabancı casusluk hücresi yakalandı."},{"label":"Batılı ve Asyalı otomotiv devleriyle yerli elektrikli araç bataryası üretimi için stratejik ortaklık masasına otur.","preview":"Adalet +6, Halk +7, Hazine +9, Otorite +6","effects":{"justice":6,"people":7,"treasury":9,"military":0,"authority":6},"log":"Milyarlarca dolarlık doğrudan yabancı yatırım ve teknoloji transferi sağlandı."},{"label":"Beylikova\'daki maden gelirlerinin yüzde 25\'ini doğrudan Gelecek Nesiller Varlık Fonu\'na aktararak gençliğe miras bırak.","preview":"Adalet +8, Halk +9, Hazine +5, Otorite +7","effects":{"justice":8,"people":9,"treasury":5,"military":0,"authority":7},"log":"Doğal kaynak zenginliği bugünkü harcamalara değil milletin geleceğine yatırıldı."}]', 772) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_773', 'modern', 'Kömür Madenlerinde Yaşam Odası Zorunluluğu Yasası', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Soma ve Ermenek faciaları sonrası yer altı ocaklarında oksijen tüplü sığınma odaları zorunlu kılındı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Madencilik ve enerji faaliyetlerinde iş güvenliği, çevre kanunları ve ruhsat şartlarını bağımsız denetle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Madenlerde iş güvenliği korundu; çevreye zarar veren kuralsız işletmeler durduruldu."},{"label":"Maden işçileri, sendikalar ve sektör temsilcileriyle ortak istişare meclisi kurarak madencilik barışını sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog sağlandı; maden işçilerinin çalışma koşulları ve ücretleri iyileştirildi."},{"label":"Yerli maden üretimi ve cevher zenginleştirme yatırımlarına Hazine bütçesinden teşvik ve vergi indirimi sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli madencilik desteklendi; yerli kaynaklarla sanayinin hammadde ihtiyacı karşılandı."},{"label":"Ruhsatsız kaçak maden ocaklarına ve kömür hırsızlığına karşı jandarma komandolarıyla baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kaçak madenler kapatıldı; can güvenliğini hiçe sayan merdiven altı işletmeler mühürlendi."},{"label":"Maden çalışanlarına yıpranma payı ve erken emeklilik getiren \'Maden İşçileri ve Sektörel Reform Kanunu\' çıkar.","preview":"Adalet 