INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_787', 'modern', 'Kaya Gazı (Şeyl Gazı) Arama Sondajları (Trakya ve Diyarbakır)', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Yatay sondaj ve hidrolik kırma yöntemleriyle kaya çatlaklarındaki gaz potansiyeli incelendi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Madencilik ve enerji faaliyetlerinde iş güvenliği, çevre kanunları ve ruhsat şartlarını bağımsız denetle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Madenlerde iş güvenliği korundu; çevreye zarar veren kuralsız işletmeler durduruldu."},{"label":"Maden işçileri, sendikalar ve sektör temsilcileriyle ortak istişare meclisi kurarak madencilik barışını sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog sağlandı; maden işçilerinin çalışma koşulları ve ücretleri iyileştirildi."},{"label":"Yerli maden üretimi ve cevher zenginleştirme yatırımlarına Hazine bütçesinden teşvik ve vergi indirimi sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli madencilik desteklendi; yerli kaynaklarla sanayinin hammadde ihtiyacı karşılandı."},{"label":"Ruhsatsız kaçak maden ocaklarına ve kömür hırsızlığına karşı jandarma komandolarıyla baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kaçak madenler kapatıldı; can güvenliğini hiçe sayan merdiven altı işletmeler mühürlendi."},{"label":"Maden çalışanlarına yıpranma payı ve erken emeklilik getiren \'Maden İşçileri ve Sektörel Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Madencilerin özlük hakları kanunlaştı; işçi sağlığı en yüksek yasal korumaya alındı."}]', 787) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_788', 'modern', 'Akaryakıt İstasyonlarında Ulusal Taşıt Tanıma Sistemi (UTTS)', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Vergi kaçakçılığını önlemek için araçların depolarına ve pompa tabancalarına çipli tanıma zorunluluğu geldi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Akaryakıt kaçakçılığı, 10 numara yağ ve faturasız yakıt satan istasyonları EPDK denetimiyle kapatıp savcılığa sevk et.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Akaryakıtta vergi kaçakçılığı önlendi; ulusal marker denetimiyle kaçak petrol şebekeleri çökertildi."},{"label":"Petrol fiyatları tırmanırken Eşel Mobil Sistemi ile ÖTV\'den feragat ederek pompa fiyatlarını sabit tut.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Vatandaş ve nakliyeci korundu; akaryakıt zamlarının enflasyonu ve nakliye maliyetlerini vurması engellendi."},{"label":"Ulusal Taşıt Tanıma Sistemi (UTTS) zorunluluğu getirerek akaryakıt fişlerindeki yıllık 15 milyar liralık KDV kaybını Hazineye kazandır.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Hazine kasasına dev gelir girdi; şirketlerin sahte akaryakıt fişiyle gider göstermesi çipli sistemle sıfırlandı."},{"label":"Kaçak akaryakıt boru hatları ve tanker kaçakçılığına karşı jandarma ve gümrük muhafaza timlerini sınıra yığ.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sınır kapılarında kaçak yakıt geçişleri durduruldu; organize petrol kaçakçıları yakalandı."},{"label":"Enerji Piyasası Düzenleme Kurumu (EPDK) denetim yetkilerini artıran \'Petrol Piyasası Reform Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Akaryakıt sektörü tam şeffaflığa kavuştu; dağıtıcı ve bayiler arasındaki kar payı kanunla düzenlendi."}]', 788) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_789', 'modern', 'Elektrikli Araç Şarj Ağı İşletmeci Lisansları Düzenlemesi', 'Enerji ve Tabii Kaynaklar Bakanlığı', '81 ilde kurulan hızlı şarj istasyonları için EPDK standartları ve tavan tarife kuralları getirildi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"}]', '[{"label":"Madencilik ve enerji faaliyetlerinde iş güvenliği, çevre kanunları ve ruhsat şartlarını bağımsız denetle.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Madenlerde iş güvenliği korundu; çevreye zarar veren kuralsız işletmeler durduruldu."},{"label":"Maden işçileri, sendikalar ve sektör temsilcileriyle ortak istişare meclisi kurarak madencilik barışını sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog sağlandı; maden işçilerinin çalışma koşulları ve ücretleri iyileştirildi."},{"label":"Yerli maden üretimi ve cevher zenginleştirme yatırımlarına Hazine bütçesinden teşvik ve vergi indirimi sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli madencilik desteklendi; yerli kaynaklarla sanayinin hammadde ihtiyacı karşılandı."},{"label":"Ruhsatsız kaçak maden ocaklarına ve kömür hırsızlığına karşı jandarma komandolarıyla baskınlar yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kaçak madenler kapatıldı; can güvenliğini hiçe sayan merdiven altı işletmeler mühürlendi."},{"label":"Maden çalışanlarına yıpranma payı ve erken emeklilik getiren \'Maden İşçileri ve Sektörel Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Madencilerin özlük hakları kanunlaştı; işçi sağlığı en yüksek yasal korumaya alındı."}]', 789) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_790', 'modern', 'Binalarda Isı Yalıtımı Seferberliği ve Yanıcı Mantolama Yangın Tehdidi', 'Enerji ve Tabii Kaynaklar Bakanlığı', 'Doğalgaz faturasını düşürmek için başlatılan dış cephe yalıtım kredisi hamlesinde, merdiven altı firmaların alev alan strafor köpükler kullanarak binaları ölümcül yangın kapanına çevirdiği ortaya çıktı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_enerji_bakani","name":"Enerji ve Tabii Kaynaklar Bakanı"}]', '[{"label":"Yanıcı plastik köpük kullanımını derhal yasakla; sadece yanmaz taşyünü ve mineral yün kullanan binalara kredi onayı ver.","preview":"Adalet +9, Halk +8, Otorite +8 | Hazine -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Olası Londra Grenfell kule benzeri yangın faciaları önlendi; can güvenliği tescillendi."},{"label":"Merdiven altı sahte yalıtım malzemesi üreten fabrikaları zabıta ve polis baskınlarıyla mühürleyip mallarına el koy.","preview":"Adalet +8, Halk +7, Hazine +3, Güvenlik +2, Otorite +8","effects":{"justice":8,"people":7,"treasury":3,"military":2,"authority":8},"log":"Halkın canını hiçe sayan sahtekarlar adalete teslim edildi."},{"label":"Doğalgaz tüketiminde yüzde 35 tasarruf sağlayan yalıtımlı apartmanlara faturalarda yüzde 20 devlet indirimi tanımla.","preview":"Adalet +7, Halk +9, Otorite +6 | Hazine -6","effects":{"justice":7,"people":9,"treasury":-6,"military":0,"authority":6},"log":"Yalıtım seferberliği patladı, Türkiye\'nin doğalgaz ithalat faturası milyarlarca dolar geriledi."},{"label":"Tüm apartman ve sitelere zorunlu yangın merdiveni ve duman tahliye sensörü denetimi getir.","preview":"Adalet +8, Halk +7, Otorite +7 | Hazine -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Binalarda yangın güvenliği standartları Avrupa seviyesine çıkarıldı."},{"label":"Yerli taşyünü üreticilerine düşük faizli yatırım kredisi vererek yalıtım malzemesi arzını ucuzlat.","preview":"Adalet +6, Halk +7, Otorite +6 | Hazine -4","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Yerli hammaddeyle güvenli yalıtım maliyetleri yarı yarıya düştü."}]', 790) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_791', 'modern', 'İstanbul Taksi Plakası Krizi: İBB ile Taksiciler Odası Çatışması', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Kalitesiz hizmet ve yetersiz taksi sayısı sebebiyle İBB\'nin 5 bin yeni taksi teklifi UKOME\'de defalarca reddedildi.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Taksici esnafının plaka tekeli ve fahiş hava parası düzenini Rekabet Kurumu ve adli makamlarca denetime tabi tut.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Plaka karaborsasına neşter vuruldu; taksici odasının vatandaşı mağdur eden tekelci baskısı kırıldı."},{"label":"İBB ve Taksiciler Odası\'nı UKOME masasında uzlaştırarak 2.500 yeni uygulama tabanlı taksinin hizmete girmesini sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Ulaşım krizi çözüldü; İstanbul halkı dijital uygulama üzerinden temiz ve güvenli taksilere kavuştu."},{"label":"Yeni taksi plakası ihalelerinden elde edilen milyarlarca liralık geliri belediye ve Hazine raylı sistem bütçesine aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kamu bütçesine kaynak sağlandı; plaka ihale gelirleri metro hatlarının inşasına aktarıldı."},{"label":"Yolcu seçen, turist dolandıran ve taksimetre açmayan korsan ve fırsatçı taksicilere karşı sivil trafik zabıtası görevlendir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Taksi denetimleri sıkılaştırıldı; vatandaşa kaba davranan şoförlerin ruhsatları anında askıya alındı."},{"label":"Tüm taksilerde kamera, panik butonu ve kredi kartı pos cihazını zorunlu kılan \'Şehir İçi Yolcu Taşımacılığı Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Taksi taşımacılığı kurumsallaştı; taksici cinayetleri ve müşteri mağduriyetleri önlendi."}]', 791) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
