INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_797', 'modern', 'Elektrikli Scooter (Martı, BinBin) İstilası ve Kaldırım Krizleri', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Büyükşehir kaldırımlarını işgal eden binlerce scooter yayaların yürümesini engelleyince tepkiler patladı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Şehirleşme, imar ve yerel yönetim hizmetlerinde hukukun üstünlüğü ve imar planı ilkelerini tavizsiz koru.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"İmar disiplini sağlandı; şehir planlarına aykırı keyfi yapılaşmalar engellendi."},{"label":"Mahalle muhtarları, sivil toplum ve ilçe sakinleriyle diyalog kurarak yerel hizmetlerde halkın rızasını al.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Vatandaşın talepleri karşılandı; mahalle ölçeğinde katılımcı belediyecilik uygulandı."},{"label":"Yerel altyapı, çevre ve park yatırımları için İller Bankası ve Hazine bütçesinden planlı finansman sağla.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Belediye yatırımları bütçeden karşılandı; şehirlerin altyapı eksikleri tamamlandı."},{"label":"Kaçak otopark mafyası ve kaldırımları işgal eden kanunsuz unsurlara karşı zabıta ve polis denetimini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Şehirlerde kamu nizamı korundu; sokak eşkıyalığına ve korsan otoparkçılara son verildi."},{"label":"Büyükşehir ve ilçe belediyelerinin imar yetkilerini şeffaf kurallara bağlayan \'Beled