INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_800', 'modern', 'Mansur Yavaş\'ın Ankara\'da Belediye İhalelerini Canlı Yayınlaması', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Belediye meclis toplantıları ve asfalt ihalelerinin internetten canlı yayınlanması şeffaflık rüzgarı başlattı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Belediye ihalelerinin canlı yayında, açık eksiltmeyle yapılmasını ve tüm harcamaların Sayıştay denetimine açılmasını sağla.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Şeffaf belediyecilik çağı başladı; kapalı kapılar ardındaki rant ihaleleri milletin gözü önünde canlı yayınlandı."},{"label":"Merkezi idare ile büyükşehir belediyeleri arasında metro ve altyapı projelerinde siyasi çatışmayı bırakıp protokol imzala.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Hizmet öncelendi; başkent ve metropollerde ulaşım projeleri hükümet-belediye işbirliğiyle hızlandırıldı."},{"label":"Canlı yayınlanan ihalelerde sağlanan %30\'luk kırım oranlarıyla belediye bütçelerinde milyarlarca lira tasarruf et.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Kamuda israf önlendi; tasarruf edilen kaynaklar dar gelirli ailelere et ve doğalgaz desteği olarak dağıtıldı."},{"label":"Belediyelerde terör iltisaklı kişilerin istihdam edilmesini önlemek için emniyet güvenlik soruşturmalarını tavizsiz uygula.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kamu kurumlarının güvenliği korundu; belediye kaynaklarının terör örgütlerine aktarılması engellendi."},{"label":"Tüm yerel yönetim ihalelerinin canlı yayınlanmasını ve EKAP üzerinden yapılmasını zorunlu kılan \'Şeffaf Yerel Yönetim Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"İhalelerde yolsuzluk imkansız hale getirildi; vatandaşın vergileri tam denetim altına alındı."}]', 800) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
