INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_804', 'modern', 'Tarihi Kent Merkezlerinde Rant Baskısı: Bursa Hanlar Bölgesi Yıkım İhtilafı', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Ulu Cami ve tarihi hanların silüetini boğan betonarme iş merkezlerinin yıkımı planlanırken, mülk sahiplerinin kamulaştırma bedellerine isyan etmesi ve rant lobilerinin davaları süreci tıkadı.', '[{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Kamulaştırma bedellerini hakkaniyetle ödeyerek tarihi hanları kuşatan tüm ucube binaları tavizsiz yıkıp meydanı aç.","preview":"Adalet +8, Halk +9, Otorite +8 | Hazine -7","effects":{"justice":8,"people":9,"treasury":-7,"military":0,"authority":8},"log":"Bursa Hanlar Bölgesi 600 yıl önceki ihtişamına kavuştu; UNESCO mirası korundu."},{"label":"Mülk sahibi esnafa yıkılan dükkanları yerine şehrin ticaret aksında modern çarşı dükkanları takas hakkı tanı.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Esnaf mağdur edilmeden uzlaşma sağlandı, yıkım alkışlarla tamamlandı."},{"label":"Tarihi silüeti kapatan yapay gökdelen ve AVM projelerine karşı koruma imar planını Meclis\'te kanunlaştır.","preview":"Adalet +9, Halk +7, Otorite +8","effects":{"justice":9,"people":7,"treasury":0,"military":0,"authority":8},"log":"Tarihi kent merkezlerinde rant lobilerinin önü kanunen ebediyen kesildi."},{"label":"Hanlar Bölgesi\'ni sadece yayalaştırılmış turizm ve zanaat merkezine dönüştürerek araç trafiğini tamamen men et.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Hava kirliliği ve egzoz gazından arınan tarihi taş yapılar koruma altına alındı."},{"label":"Restorasyon masraflarını karşılamak için tarihi hanlarda geleneksel Türk el sanatları fuarları aç.","preview":"Adalet +6, Halk +8, Hazine +3, Otorite +5","effects":{"justice":6,"people":8,"treasury":3,"military":0,"authority":5},"log":"Hem kültürel miras yaşatıldı hem de Bursa ekonomisine turizm dopingi yapıldı."}]', 804) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
