INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_806', 'modern', 'Rize Ayder Yaylası Kentsel Dönüşüm Projesi', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Salıncakların söndüğü, betonlaşmanın durdurulduğu yaylada otopark yer altına alınarak çimler kurtarıldı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Deprem riski altındaki binaların dönüşümünde hak sahipliği anlaşmazlıklarını hızla çözecek ihtisas mahkemelerini görevlendir.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Kentsel dönüşümde hukuki tıkanıklıklar aşıldı; tek bir mülk sahibinin yüzlerce aileyi rehin alması engellendi."},{"label":"İstanbul\'da \'Yarısı Bizden\' kampanyasıyla evini yenilemek isteyen vatandaşlara 700 bin TL hibe ve uygun vadeli kredi ver.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Vatandaşın tabut binalardan kurtulması sağlandı; yüz binlerce konut güvenli binalara dönüştürüldü."},{"label":"Fikirtepe\'de müteahhitlerin yarım bıraktığı 60 bin konutluk alanı TOKİ ve Emlak Konut ile devralarak şantiyeleri tamamla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yıllardır çadırlarda bekleyen Fikirtepe mağdurları evlerine kavuştu; devlet güvencesiyle inşaatlar bitirildi."},{"label":"Kaçak inşaat yapan, çürük malzeme kullanan ve kaçak kat çıkan sorumsuz müteahhitlerin inşaatlarını derhal mühürle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"İmar denetimi tavizsiz işletildi; afet riski taşıyan kaçak yapıların yükselmesine izin verilmedi."},{"label":"Riskli binalarda kentsel dönüşüm kararını salt çoğunluğa (yarıdan bir fazla) bağlayan \'Kentsel Dönüşüm Başkanlığı Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Dönüşümün önündeki bürokratik engeller yıkıldı; Türkiye genelinde 6.5 milyon riskli konutun yenilenme süreci hızlandı."}]', 806) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
