INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_814', 'modern', 'Sokak Hayvanları Yasası (5199): Kısırlaştır, Aşıla, Barınak', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Sokak köpeklerinin saldırıları sonrası sahipsiz hayvanların toplanıp barınaklara alınması kanunlaştı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"}]', '[{"label":"Sahipsiz ve saldırgan köpeklerin çocukları ve yaşlıları parçalamasını önlemek için anayasal yaşam hakkını en üstte tut.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Vatandaşın can güvenliği korundu; kuduz ve köpek saldırısı sonucu çocuk kayıplarının önüne geçildi."},{"label":"Hayvansever dernekleri, veteriner hekim odaları ve belediyelerle ortak aşılama, kısırlaştırma ve sahiplendirme seferberliği yap.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Vicdani denge sağlandı; modern hayvan bakımevlerinde kısırlaştırma ve sahiplendirme kampanyaları hızlandırıldı."},{"label":"81 ilde doğal yaşam alanlı modern hayvan barınakları ve rehabilitasyon merkezleri için belediyelere Hazine fonu aktar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Barınak kapasiteleri artırıldı; sokaklardan toplanan hayvanların aç ve bakımsız kalması önlendi."},{"label":"Okul çevreleri, parklar ve hastane bahçelerindeki saldırgan başıboş köpek sürülerini zabıta ve belediye ekiplerince topla.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Sokaklar yeniden güvenli hale geldi; sabah erken saatte okula giden çocuklar ve cami cemaati güvenceye alındı."},{"label":"Sahipli hayvanları terk etmeyi ağır cezalara bağlayan ve sahipsiz hayvanları rehabilite eden 5199 Sayılı Kanun Reformu\'nu çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Avrupa standartlarında yasa kabul edildi; hem insan canı korundu hem de hayvanlar korunaklı bakımevlerine alındı."}]', 814) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
