INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_825', 'modern', 'Asgari Ücretten Gelir ve Damga Vergisinin Tamamen Sıfırlanması', 'Çalışma ve Sosyal Güvenlik Bakanlığı', 'Tüm çalışanların maaşının asgari ücrete kadar olan kısmından vergi kesintisi kalıcı olarak kaldırıldı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Çalışma hayatında emeğin hakkı, anayasal sendika özgürlüğü ve iş sağlığı ilkelerini tavizsiz gözet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"İşçi hakları korundu; çalışma hayatında adil ücret ve güvenli çalışma ortamı sağlandı."},{"label":"İşçi sendikaları, işveren örgütleri ve hükümetle Üçlü Danışma Kurulu\'nda sosyal mutabakat sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sosyal diyalog korundu; çalışma barışını bozan gerilimler uzlaşıyla aşıldı."},{"label":"Sosyal güvenlik prim gelirlerini artırarak SGK aktüeryal dengesini ve Hazine disiplinini koru.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kamu maliyesi korundu; sosyal güvenlik açıkları kontrol altında tutuldu."},{"label":"Kayıtdışı kaçak işçi çalıştıran ve çocuk emeğini istismar eden işletmelere polis ve müfettişle baskın yap.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Kayıtdışı istihdamla mücadele edildi; kaçak işçi çalıştıranlara ağır cezalar kesildi."},{"label":"Çalışma hayatını ve kıdem tazminatı güvencesini tanzim eden \'Milli İstihdam ve İş Kanunu Reformu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"İş kanunu çağdaşlaştırıldı; çalışanların özlük hakları yasal teminata bağlandı."}]', 825) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_826', 'modern', '696 Sayılı KHK ile 900 Bin Taşeron İşçinin Sürekli İşçi Kadrosuna Alınması', 'Çalışma ve Sosyal Güvenlik Bakanlığı', 'Kamuda taşeron şirketler üzerinden çalışan temizlik, güvenlik ve işçiler devlet kadrosuna geçirildi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Kamuda çalışan taşeron işçilerin daimi işçi kadrosuna geçişini şeffaf güvenlik soruşturması ve liyakatle tamamla.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Taşeron ayıbına son verildi; 900 bin kamu işçisi devlet güvencesine ve sendikal haklarına kavuştu."},{"label":"İşçi sendikalarıyla Toplu İş Sözleşmesi (TİS) masasına oturarak ücret artışlarını enflasyon oranında dengele.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"İş barışı sağlandı; kamu işçilerinin ücret ve ikramiye hakları uzlaşıyla bağıtlandı."},{"label":"Kadroya geçen işçilerin kıdem tazminatı ve özlük giderlerini Hazine merkezi bütçesinde planlı tasarrufla karşıla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Kamu maliyesinde denge korundu; taşeron firmaların aracı komisyonları kaldırılarak tasarruf sağlandı."},{"label":"Kadro sürecini istismar eden sahte taşeron şirket yöneticileri ve rüşvet çarkına karşı mali polisi görevlendir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"İstihdam yolsuzluğu engellendi; sadece hak eden gerçek işçilerin kadroya girmesi sağlandı."},{"label":"Kamuda güvencesiz ve kiralık işçiliği kesin olarak yasaklayan 696 Sayılı KHK Reformu\'nu yasalaştır.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"İş güvencesi kanunlaştı; Türkiye\'nin en büyük istihdam devrimi yasal teminata alındı."}]', 826) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_827', 'modern', '3600 Ek Gösterge Yasası ile Memur Emekli İkramiyesi Artışı', 'Çalışma ve Sosyal Güvenlik Bakanlığı', 'Öğretmen, polis, hemşire ve din görevlilerinin ek göstergeleri 3600\'e çıkarılarak emekli maaşları artırıldı.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_esnaf_odasi_baskani","name":"Esnaf Odaları Başkanı"}]', '[{"label":"Öğretmen, polis, hemşire ve din görevlilerinin 3600 ek gösterge haklarını eşitlik ve kariyer liyakatine göre tescille.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yılların beklentisi karşılandı; 5.3 milyon kamu personeli ve emeklisinin maaşı ve ikramiyesi yükseltildi."},{"label":"Memur-Sen ve Kamu-Sen heyetleriyle Kamu Görevlileri Hakem Kurulu\'nda zam oranlarında sosyal uzlaşı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Memur grevi önlendi; kamu çalışanlarının refah payı ve taban aylıkları uzlaşıyla artırıldı."},{"label":"16 milyon emekliye yılda iki kez ödenen bayram ikramiyelerinin finansmanını Hazine vergi gelirlerinden karşıla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Emeklilerin bayram sevinci korundu; Hazine bütçesinde emekli ikramiyeleri planlı ödendi."},{"label":"Memurların çalışma saatlerini ve mesai disiplinini denetleyerek kamuda verimlilik kaybını önle.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Kamu hizmetlerinde disiplin korundu; vatandaşın devlet dairelerindeki işleri aksatılmadı."},{"label":"Devlet Memurları Kanunu\'nda kariyer baremlerini yenileyen \'Kamu Personel Rejimi Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Memur maaş hiyerarşisi adil hale getirildi; emekli maaşları arasındaki uçurumlar kapatıldı."}]', 827) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
