INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_838', 'modern', '2010 Tekel İşçilerinin 78 Gün Süren Ankara Abdi İpekçi Parkı Direnişi', 'Çalışma ve Sosyal Güvenlik Bakanlığı', 'Özelleştirme sonrası özlük haklarını korumak isteyen Tekel işçileri kış ortasında çadırlarda direndi.', '[{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"},{"id":"char_tusiad_baskani","name":"İş Dünyası / TÜSİAD Başkanı"}]', '[{"label":"Dijital platformlarda çalışan moto-kuryeleri ve esnaf-kuryeleri \'işçi\' statüsünde koruyup sendikal hak tanı.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Kuryelerin kölelik düzenine son verildi; hız baskısı ve kaza riskine karşı yasal koruma sağlandı."},{"label":"Platform patronları ve kurye dernekleriyle asgari paket başı ücret ve dinlenme haklarında uzlaşma sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Sokak grevleri yatıştırıldı; kuryelerin insani çalışma şartları şirketlerle müzakere edildi."},{"label":"Kuryelerin kaza ve meslek hastalığı tazminatları için şirketlerden zorunlu iş kazası prim fonu tahsil et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Kamuya yük olmadan özel güvence fonu kuruldu; kazada yaralanan kuryelere maaş bağlandı."},{"label":"Trafikte kurallara uymayan, yayaları ezen ve kaldırımlardan giden kuryelere karşı trafik polisini denetime çıkar.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Trafik düzeni korundu; kurye kazaları ve yaya yaralanmalarının önüne geçildi."},{"label":"Dijital platform işçilerinin haklarını Avrupa normlarında koruyan \'Platform ve Kurye Çalışma Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Yeni nesil çalışma hayatı mevzuata kavuştu; platform işçileri anayasal güvenceye alındı."}]', 838) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
