INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_851', 'modern', 'Kamu Denetçiliği Kurumu (Ombudsman) Kararlarının İdarece Uygulanmaması Krizi', 'Adalet Bakanlığı & Danıştay', 'Vatandaşların bürokrasiye karşı hak arayışında Ombudsman\'ın verdiği tavsiye kararlarının bakanlıklar ve belediyeler tarafından kasten sümen altı edilmesi vatandaşın adalet inancını sarstı.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Ombudsman kararlarına uymayan kamu yöneticilerine idari para cezası ve terfi engeli getiren kanun değişikliği yap.","preview":"Adalet +9, Halk +8, Hazine +1, Otorite +8","effects":{"justice":9,"people":8,"treasury":1,"military":0,"authority":8},"log":"Bürokrasinin keyfi tutumu kırıldı; vatandaşın haklı talepleri mahkemesiz çözüldü."},{"label":"Ombudsman raporlarını her yıl TBMM Genel Kurulu\'nda canlı yayında tartıştırıp kusurlu bakanları hesap vermeye çağır.","preview":"Adalet +8, Halk +8, Otorite +7","effects":{"justice":8,"people":8,"treasury":0,"military":0,"authority":7},"log":"Meclis denetimi işletildi; halkın şikayetleri doğrudan milletvekillerinin önüne geldi."},{"label":"İdarenin hukuka aykırı işlemlerini otomatik iptal edebilecek bir \'Bağlayıcı Ombudsman Yargı Kararı\' statüsü oluştur.","preview":"Adalet +8, Halk +7, Otorite +6 | Hazine -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"İdari yargının yüz binlerce dosyalık yükü hafifletildi; hızlı adalet sağlandı."},{"label":"Tüm bakanlık ve belediyelerde vatandaşın dilekçelerini 15 günde sonuçlandırmak zorunda olan \'Halk Masaları\' kur.","preview":"Adalet +7, Halk +8, Otorite +6 | Hazine -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Bürokratik hantallık kırıldı, vatandaş-devlet barışına katkı sunuldu."},{"label":"Kamu denetçiliği başvurularını e-Devlet üzerinden ücretsiz ve yapay zeka destekli dosya takibine bağla.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Hak arama yolu tamamen dijitalleşti ve şeffaflaştı."}]', 851) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_852', 'modern', 'Sayıştay\'ın Kurumsal Denetim Raporlarının TBMM\'ye Sunulması', 'Adalet Bakanlığı & Danıştay', 'Bakanlıklar ve belediyelerdeki usulsüzlük ve kamu zararlarını listeleyen raporlar meclisi hareketlendirdi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_hazine_bakani","name":"Hazine ve Maliye Bakanı"}]', '[{"label":"Yargısal denetim, anayasal kurallar ve tabi hakim güvencesini tüm kamu işlemlerinde tavizsiz işlet.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Hukuk devleti korundu; idari tasarruflar bağımsız yargı denetimine tabi tutuldu."},{"label":"Yargı mensupları, akademisyenler ve sivil toplumla hukuk şuraları toplayarak kanunlaştırma uzlaşısı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Hukuk camiasında uzlaşı sağlandı; mevzuat hazırlıklarında katılımcılık sağlandı."},{"label":"Adalet sarayları ve adli tıp altyapısı yatırımları için Hazine bütçesinden planlı finansman sağla.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Adli bütçe korundu; mahkemelerin fiziki ve dijital altyapısı tamamlandı."},{"label":"Adliyelerde provokasyon, rüşvet ve sahte evrak şebekelerine karşı adli kolluğu teyakkuzda tut.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Adliyelerde güvenlik sağlandı; yargı mekanizmasına sızmaya çalışan çeteler engellendi."},{"label":"Yargı bağımsızlığı ve şeffaflığı tahkim eden \'Kamu Hukuku ve Adli Teşkilat Reform Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"just