INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_856', 'modern', 'Kamuda Personel Alımında Mülakat Tartışması ve Liyakat Güvencesi İkilemi', 'Adalet Bakanlığı & Danıştay', 'KPSS\'den 90 üstü puan alan adayların mülakatlarda elendiği iddiaları liyakat tartışmalarını alevlendirirken, güvenlik bürokrasisi kritik kadrolara sızmaları önlemek için mülakatın şart olduğunu savunuyor.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Öğretmenlik ve sivil memur alımlarında mülakatı tamamen kaldır; sadece KPSS puan üstünlüğüne göre otomatik yerleştirme yap.","preview":"Adalet +9, Halk +9, Otorite +6 | Güvenlik -2","effects":{"justice":9,"people":9,"treasury":0,"military":-2,"authority":6},"log":"Gençlerin devlete olan güveni tazelendi; torpil iddiaları tamamen sona erdi."},{"label":"Tüm mülakatları kamera kaydına aldır ve adaya mülakat puanı olarak KPSS puanının artı/eksi 3 puanından fazla verilmesini yasakla.","preview":"Adalet +8, Halk +8, Güvenlik +2, Otorite +7 | Hazine -2","effects":{"justice":8,"people":8,"treasury":-2,"military":2,"authority":7},"log":"Kamera kaydı güvencesiyle keyfi puanlamanın önü kesildi; yargı denetimi sağlandı."},{"label":"Güvenlik, yargı ve istihbarat kadrolarında mülakat ve detaylı güvenlik soruşturması şartını tavizsiz muhafaza et.","preview":"Adalet +5, Halk +2, Güvenlik +7, Otorite +8","effects":{"justice":5,"people":2,"treasury":0,"military":7,"authority":8},"log":"Devletin stratejik kurumlarına zararlı örgüt sızmaları önlendi."},{"label":"Mülakat komisyonlarında bağımsız akademisyenler ve baro temsilcilerine yer vererek şeffaflığı tahkim et.","preview":"Adalet +8, Halk +7, Otorite +6 | Hazine -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Komisyonların tarafsızlığı kamuoyu vicdanında onay gördü."},{"label":"Mülakatta elenen tüm adaylara yazılı gerekçeli rapor alma ve 7 günde idari mahkemeye itiraz hakkı tanı.","preview":"Adalet +8, Halk +8, Otorite +6 | Hazine -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Hukuki güvence mekanizması kurularak haksızlık şüpheleri giderildi."}]', 856) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
