INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_859', 'modern', 'İstinaf Mahkemelerinde Dosya Yığılması ve Geciken Adalet Sorunu', 'Adalet Bakanlığı & Danıştay', 'Yargıtay ve Danıştay\'ın iş yükünü hafifletmek için kurulan Bölge Adliye Mahkemeleri\'nde dosyaların yıllarca beklemesi, tutukluların mağduriyeti ve ticaret davalarının tıkanması adalet krizine dönüştü.', '[{"id":"char_adalet_bakani","name":"Adalet Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Adli Yargı Hakimi"}]', '[{"label":"İstinaf daire sayısını ve kıdemli yargıç kadrosunu iki katına çıkarıp duruşmasız incelenebilecek usul davalarını hızlandır.","preview":"Adalet +8, Halk +7, Otorite +7 | Hazine -5","effects":{"justice":8,"people":7,"treasury":-5,"military":0,"authority":7},"log":"Mahkemelerin kadro kapasitesi artırıldı; dosya bekleme süreleri yarı yarıya indi."},{"label":"Ticari davalarda ve işçi alacaklarında zorunlu arabuluculuk kapsamını genişleterek dosyaları mahkemeye gelmeden çöz.","preview":"Adalet +7, Halk +8, Hazine +3, Otorite +6","effects":{"justice":7,"people":8,"treasury":3,"military":0,"authority":6},"log":"Yüz binlerce ticari ihtilaf uzlaşmayla çözüldü, mahkemelerin yükü hafifletildi."},{"label":"Belirli bir meblağın altındaki hukuk davalarında ilk derece mahkemesi kararını kesin hüküm sayarak istinaf yolunu kapat.","preview":"Adalet +5, Halk +4, Hazine +4, Otorite +6","effects":{"justice":5,"people":4,"treasury":4,"military":0,"authority":6},"log":"Yargı süreci hızlandı; ancak alt mahkeme hatalarına karşı denetim yolu sınırlandı."},{"label":"Uzun tutukluluk ve geciken adalet sebebiyle mağdur olan vatandaşlara tazminat ödenmesini sağlayan fon kur.","preview":"Adalet +8, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Sosyal hukuk devleti ilkesiyle vatandaşın hakkı teslim edildi."},{"label":"Yapay zeka tabanlı tensip ve emsal karar destek yazılımlarını tüm mahkemelerde zorunlu kılarak süreci hızlandır.","preview":"Adalet +7, Halk +6, Otorite +6 | Hazine -3","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Yargıda dijitalleşmeyle karar yazım süreleri haftalardan saatlere indi."}]', 859) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
