INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_874', 'modern', 'Elektronik Duruşma (e-Duruşma) ile Avukatların Bürodan Katılımı', 'Adalet Bakanlığı & Danıştay', 'Avukatların adliyeye gitmeden bürolarından cübbeleriyle duruşmaya canlı bağlanması sağlandı.', '[{"id":"char_sanayi_bakani","name":"Sanayi ve Teknoloji Bakanı"},{"id":"char_adalet_bakani","name":"Adalet Bakanı"}]', '[{"label":"Bölge Adliye Mahkemeleri (İstinaf) ve Yargıtay arasındaki yetki çatışmasını adil yargılanma ve tabi hakim ilkesiyle çöz.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Yargıtay\'daki 2 milyon dosya yükü eritildi; 5 yıl süren ceza ve hukuk davaları 1 yılda sonuçlanmaya başladı."},{"label":"Barolar, hakimler ve savcılarla Yargı Şurası düzenleyerek e-Duruşma ve UYAP üzerinden savunma hakkını güçlendir.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Avukatlar bürolarından duruşmalara katıldı; yargılama süreleri kısalarak adalet hızlandı."},{"label":"Tüm adliyelere ses ve görüntü bilişim sistemi (SEGBİS) kurarak sanık nakil harcamalarında Hazineye rekor tasarruf sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milyonlarca liralık jandarma nakil ve lojistik masrafı önlendi; adli harcamalar Hazinece dengelendi."},{"label":"Sahte bilirkişilik yapan ve mahkemeleri rüşvetle manipüle eden çetelere karşı adli zabıtayı görevlendir.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Adliyeler temizlendi; sahte rapor düzenleyen bilirkişiler tutuklanarak sicilden silindi."},{"label":"Yargılama sürelerini kesin hedef sürelere bağlayan \'Yargı Reformu Strateji Belgesi Kanun Paketi\'ni çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Hedef süre uygulaması kanunlaştı; \'Geciken adalet, adalet değildir\' ilkesi hayata geçirildi."}]', 874) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
