INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_880', 'modern', 'Avukatlık Kanunu Değişikliği ve Çoklu Baro Tartışmaları (2020)', 'Adalet Bakanlığı & Danıştay', 'Büyükşehirlerde 5 bin avukatı aşan illerde ikinci baronun kurulabilmesi meclisi ve sokakları hareketlendirdi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Savunma makamının bağımsızlığı ve Barolar Birliği\'nin anayasal kamu kurumu niteliğindeki meslek örgütü yapısını koru.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Savunmanın gücü korundu; avukatların mesleki bağımsızlığı anayasal zeminde savunuldu."},{"label":"Türkiye Barolar Birliği ve il baro başkanlarıyla Çankaya\'da meşveret toplayıp avukatların özlük haklarında uzlaş.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Baro yürüyüşleri diyalogla sonlandırıldı; avukatlık mesleğinin itibarını koruyacak formül bulundu."},{"label":"Genç avukatlara ilk 3 yıl büro ve vergi muafiyeti tanıyarak Hazine destekli faizsiz kuruluş kredisi aç.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Genç hukukçular desteklendi; mezun avukatların büro açma çilesi devletçe hafifletildi."},{"label":"Adliye koridorlarında terör propagandası ve cübbeyle yasadışı slogan atan marjinal grupları polisçe engelle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Adliyelerde vakar korundu; meslek cübbesinin ideolojik eylemlere alet edilmesi önlendi."},{"label":"Büyükşehirlerde 5 bin avukatı aşan illerde 2. baronun kurulabilmesini sağlayan 7249 Sayılı Kanun\'u kabul et.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Avukatlık Kanunu güncellendi; çoklu baro sistemi yasal çerçevede yürürlüğe girdi."}]', 880) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_881', 'modern', 'Çiftçi Kayıt Sistemi (ÇKS) ve Tarımsal Desteklemeler', 'Tarım ve Orman Bakanlığı', 'Ekilmeyen tarım arazilerini kayıt altına alan sistemle çiftçilere doğrudan dekar başına gübre ve mazot desteği verildi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Kuraklık ve don felaketinde çiftçinin zararını TARSİM eksperlerince yerinde tespit ettirip hak sahiplerine eksiksiz ödet.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Çiftçinin hakkı korundu; afet mağduru üreticilerin zararları devlet güvenceli sigortayla ödendi."},{"label":"Ziraat Odaları ve Türkiye Damızlık Yetiştiricileri Birliği ile kuraklık eylem planı ve acil tohum yardımı uzlaşısı yap.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Üreticinin morali yükseldi; tohum ve gübre destekleriyle tarlaların boş kalması önlendi."},{"label":"Çiftçilere mazot ve gübre desteğini doğrudan Başak Kart\'a yükleyerek Hazine tarımsal destek bütçesini 63 milyar TL\'ye çıkar.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Tarım sübvanse edildi; Hazine kaynaklarıyla çiftçinin girdi maliyetleri hafifletildi."},{"label":"Mera arazilerini kaçak sürerek işgal eden ve kaçak su kuyusu açan fırsatçılara karşı tarım jandarmasını sahaya sür.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Mera ve yeraltı suları korundu; kanunsuz kuyu açan şebekelere ağır cezalar kesildi."},{"label":"Havza bazlı üretimi zorunlu kılan ve su kısıtı olan alanlarda çok su tüketen bitkileri yasaklayan \'Milli Tarım Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Tarımsal planlama kanunlaştı; Türkiye\'nin gıda güvenliği ve su kaynakları teminat altına alındı."}]', 881) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_882', 'modern', 'Tarım Kredi Kooperatifleri Çiftçi Borç Yapılandırmaları', 'Tarım ve Orman Bakanlığı', 'Kuraklık ve don sebebiyle borcunu ödeyemeyen yüz binlerce çiftçinin traktör hacizleri ertelendi.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Tarımsal üretimde kalite standartları, gıda güvenliği ve çiftçi haklarını yasal güvencede tut.","preview":"Adalet +8, Halk +5, Hazine +4, Otorite +4","effects":{"justice":8,"people":5,"treasury":4,"military":0,"authority":4},"log":"Gıda güvenliği gözetildi; halkın sağlıklı ve güvenilir gıdaya erişimi sağlandı."},{"label":"Ziraat odaları, besiciler ve köylülerle istişare kurulları toplayarak tarımsal kalkınma uzlaşısı sağla.","preview":"Adalet +2, Halk +7, Hazine +4, Otorite +6","effects":{"justice":2,"people":7,"treasury":4,"military":0,"authority":6},"log":"Köylünün sesi dinlendi; tarım ve hayvancılıkta üretici memnuniyeti sağlandı."},{"label":"Tarımsal destekleme primleri ve faizsiz sübvansiyonlu krediler için Hazine bütçesinden kaynak aktar.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Tarımsal ekonomi desteklendi; girdi maliyetlerine karşı çiftçi sübvanse edildi."},{"label":"Kaçak hayvan nakilleri ve gıdada tağşiş yapan sahtekarlara karşı gıda zabıtası ve kolluğu görevlendir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sahte gıda depoları basıldı; halkın sağlığıyla oynayan fırsatçılar cezalandırıldı."},{"label":"Sözleşmeli besicilik ve lisanslı depoculuğu teşvik eden \'Tarımsal Üretim Planlama Kanunu\' çıkar.","preview":"Adalet +6, Halk +4, Hazine +5, Otorite +6","effects":{"justice":6,"people":4,"treasury":5,"military":0,"authority":6},"log":"Tarım planlaması kanunlaştı; arz fazlası ve ürün ziyanının önüne geçildi."}]', 882) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
