fects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Tarım planlaması kanunlaştı; arz fazlası ve ürün ziyanının önüne geçildi."}]', 885) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_886', 'modern', 'Konya Ovası Obruk Oluşumları ve Aşırı Yeraltı Suyu Tehlikesi', 'Tarım ve Orman Bakanlığı', 'Kaçak kuyular sebebiyle yer altı sularının çekilmesi mısır tarlalarında devasa obruklar açtı.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Yeraltı sularını kaçak çeken 100 bin kaçak kuyuya sayaç taktır; kaçak sulamayı adli cezalarla durdur.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Yeraltı su havzası korundu; mısır tarlalarında yeni obrukların açılmasının önüne geçildi."},{"label":"Konya ve Karaman çiftçilerine damla sulama ve az su tüketen arpa-buğday tohumları dağıtarak çiftçileri teşvik et.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Çiftçiler tasarruflu sulamaya geçti; vahşi sulamanın ovayı kurutması diyalogla önlendi."},{"label":"Toros Dağları\'nı delen 17 kilometrelik Mavi Tünel ile Göksu Nehri\'nin sularını Konya Ovası\'na akıtan dev yatırımı finanse et.","preview":"Adalet +2, Halk +8, Güvenlik +2, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":2,"authority":4},"log":"Mavi Tünel tamamlandı; Akdeniz\'e boşa akan sular Anadolu\'nun tahıl ambarını canlandırdı."},{"label":"Obruk riski taşıyan fay çatlakları ve yer altı boşluklarını AFAD ve MTA jeoradarlarıyla 24 saat izlemeye al.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"Erken uyarı sistemi kuruldu; köylerin ve yerleşim alanlarının obruk tehlikesine karşı güvenliği sağlandı."},{"label":"Tarımsal sulamada kapalı basınçlı boru sistemini ve modern sulamayı zorunlu kılan \'Su ve Sulama Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Su kanunu yürürlüğe girdi; Türkiye\'nin tarımsal su kaynaklarında %40 su tasarrufu sağlandı."}]', 886) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
