INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_888', 'modern', 'Çiğ Süt Tavsiye Fiyatı ve Ulusal Süt Konseyi (USK) Kararları', 'Tarım ve Orman Bakanlığı', 'Yem fiyatları artarken süt fiyatının baskılanması besicilerin damızlık inekleri kesime göndermesine yol açtı.', '[{"id":"char_ticaret_bakani","name":"Ticaret Bakanı"},{"id":"char_tuketici_dernekleri_baskani","name":"Tüketici Hakları Temsilcisi"}]', '[{"label":"Tarımsal üretimde kalite standartları, gıda güvenliği ve çiftçi haklarını yasal güvencede tut.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Gıda güvenliği gözetildi; halkın sağlıklı ve güvenilir gıdaya erişimi sağlandı."},{"label":"Ziraat odaları, besiciler ve köylülerle istişare kurulları toplayarak tarımsal kalkınma uzlaşısı sağla.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Köylünün sesi dinlendi; tarım ve hayvancılıkta üretici memnuniyeti sağlandı."},{"label":"Tarımsal destekleme primleri ve faizsiz sübvansiyonlu krediler için Hazine bütçesinden kaynak aktar.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Tarımsal ekonomi desteklendi; girdi maliyetlerine karşı çiftçi sübvanse edildi."},{"label":"Kaçak hayvan nakilleri ve gıdada tağşiş yapan sahtekarlara karşı gıda zabıtası ve kolluğu görevlendir.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Sahte gıda depoları basıldı; halkın sağlığıyla oynayan fırsatçılar cezalandırıldı."},{"label":"Sözleşmeli besicilik ve lisanslı depoculuğu teşvik eden \'Tarımsal Üretim Planlama Kanunu\' çıkar.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Tarım planlaması kanunlaştı; arz fazlası ve ürün ziyanının önüne geçildi."}]', 888) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
