INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_911', 'modern', 'Gezi Parkı Eylemleri: Ağaç Kesimini Önleme Nöbeti (2013)', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Topçu Kışlası inşası için Taksim Gezi Parkı\'ndaki ağaçların sökülmesiyle başlayan çadır nöbeti ülke geneline yayıldı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Parktaki ağaç kesimini ve Topçu Kışlası projesini İdare Mahkemesi kararı çıkana kadar derhal durdur.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Yargı kararına saygı duyuldu; Taksim Dayanışması\'nın çevre talebi hukuki güvenceye alındı."},{"label":"Taksim Platformu, sanatçılar ve gençlerle Başbakanlıkta müzakere masası topla; Gezi Parkı\'nın park olarak kalmasında uzlaş.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal tansiyon düşürüldü; eylemlerin sokak çatışması ve vandallığa dönüşmesi diyalogla önlendi."},{"label":"Eylemler sırasında tahrip edilen kamu binaları, belediye otobüsleri ve esnaf dükkanlarının zararını Hazine fonuyla tazmin et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Esnafın zararları karşılandı; kamu bütçesindeki tahribat devletçe telafi edildi."},{"label":"Kamu binalarını yakan, polise molotof atan ve barikat kuran marjinal terör örgütü militanlarına karşı emniyeti göreve çağır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Vandallık ve kamu düzeninin bozulması sert müdahaleyle durduruldu; sokak terörüne geçit verilmedi."},{"label":"Şehir merkezlerindeki yeşil alanların imara açılmasını yerel referanduma (plebisit) bağlayan \'Kent Hakkı Kanunu\' çıkar.","preview":"Adalet +7, Halk +8, Otorite +5 | Hazine -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":5},"log":"Katılımcı şehircilik kanunlaştı; halkın rızası olmadan şehir parklarının dönüştürülmesi yasaklandı."}]', 911) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_912', 'modern', 'Taksim Meydanı\'na Çıkan Yolların Kapatılması ve Barikatlar', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Milyonların sokaklara döküldüğü olaylarda polis gaz fişekleri ve TOMA\'larla müdahale etti; günlerce çatışmalar sürdü.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Çevre ve tabiat varlıklarının korunmasında Anayasa\'nın 56. maddesindeki sağlıklı çevrede yaşama hakkını tavizsiz uygula.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Çevre hakkı korundu; tabiat varlıklarını bozan usulsüzlüklere karşı yargı yolu işletildi."},{"label":"Çevre dernekleri, yerel halk ve bilim insanlarıyla diyalog kurarak kalkınma ile doğa koruma dengesinde uzlaş.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Toplumsal mutabakat sağlandı; çevre ihtilafları sivil diyalogla çözüldü."},{"label":"Çevre koruma, atık su arıtma ve sıfır atık projeleri için İller Bankası ve Hazine kaynaklarını seferber et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Yeşil projeler finanse edildi; çevre altyapısı kamu bütçesiyle güçlendirildi."},{"label":"Doğal sit alanlarında kaçak yapılaşma ve çevre sabotajlarına karşı kolluk devriyelerini artır.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Çevre asayişi sağlandı; doğa harikalarının rant odaklarınca işgal edilmesi önlendi."},{"label":"Sıfır Atık vizyonunu ve iklim adaleti ilkelerini yasal teminata bağlayan \'Çevre ve Doğa Reform Kanun