INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_926', 'modern', 'Halfeti ve Fırat Havzası Baraj Projeleri: Enerji Arzı ve Tarihi Miras İkilemi', 'İçişleri Bakanlığı & Çevre Şehircilik', 'Birecik Barajı\'nın Fırat suları altında bırakacağı antik Zeugma ve Halfeti mirası uluslararası alanda tartışılırken, barajın üreteceği elektriğe sanayinin acil ihtiyacı devleti kritik bir karara zorladı.', '[{"id":"char_enerji_bakani","name":"Enerji ve Tabii Kaynaklar Bakanı"},{"id":"char_kultur_turizm_bakani","name":"Kültür ve Turizm Bakanı"}]', '[{"label":"Baraj su tutma takvimini 6 ay erteleyerek arkeolog ordusuyla Zeugma mozaiklerini ve eserlerini eksiksiz kurtarıp müzeye taşı.","preview":"Adalet +9, Halk +8, Otorite +7 | Hazine -6","effects":{"justice":9,"people":8,"treasury":-6,"military":0,"authority":7},"log":"Dünyanın en büyük mozaik müzesi kuruldu; insanlık mirası sulara gömülmekten kurtarıldı."},{"label":"Sular altında kalan köylüler için modern konutlar ve sulu tarım arazileri inşa ederek ekonomik mağduriyeti sıfırla.","preview":"Adalet +8, Halk +9, Otorite +6 | Hazine -7","effects":{"justice":8,"people":9,"treasury":-7,"military":0,"authority":6},"log":"Yörede halkın refahı arttı; yeni Halfeti modern bir turizm cazibe merkezine dönüştü."},{"label":"Barajı planlanan tarihte devreye alarak Güneydoğu sanayisine kesintisiz ve ucuz hidroelektrik sağla.","preview":"Adalet +5, Halk +5, Hazine +8, Otorite +7","effects":{"justice":5,"people":5,"treasury":8,"military":0,"authority":7},"log":"Bölge sanayisi enerjiyle şahlandı; ancak tarihi mirasa dair itirazlar sürdü."},{"label":"Batık Halfeti\'yi dalış turizmi ve su sporları merkezi ilan ederek eko-turizm gelirlerini yöre halkına bırak.","preview":"Adalet +7, Halk +8, Hazine +3, Otorite +6","effects":{"justice":7,"people":8,"treasury":3,"military":0,"authority":6},"log":"Fırat\'ın saklı cenneti dünya çapında eşsiz bir turizm markasına dönüştü."},{"label":"Fırat ve Dicle havzasındaki su paylaşımı konusunda sınır aşan sular diplomasisini güçlendiren bölgesel pakt imzala.","preview":"Adalet +7, Halk +6, Hazine +1, Güvenlik +4, Otorite +8","effects":{"justice":7,"people":6,"treasury":1,"military":4,"authority":8},"log":"Komşu ülkelerle su krizleri barışçıl ve adil anlaşmalarla güvenceye alındı."}]', 926) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
