INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_940', 'modern', 'Kızılay Çadır Satışı Skandalı ve Yönetim İstifası', 'İçişleri Bakanlığı & Çevre Şehircilik', '6 Şubat depreminin 3. gününde AHBAP derneğine çadır sattığı ortaya çıkan Kızılay Başkanı istifa etmek zorunda kaldı.', '[{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"},{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"}]', '[{"label":"Depremin ilk günlerinde çadır ve gıda satan Kızılay yöneticileri hakkında derhal adli teftiş açtırıp istifalarını sağla.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Milli kurumun itibarı korundu; 155 yıllık Kızılay\'ın ticaret şirketi gibi davranmasına izin verilmedi."},{"label":"Kızılay Genel Kurulu\'nu olağanüstü toplayarak cemiyetin başına saygın tıp insanları ve sivil toplum önderlerini getir.","preview":"Adalet +2, Halk +9, Hazine +4, Güvenlik +2, Otorite +5","effects":{"justice":2,"people":9,"treasury":4,"military":2,"authority":5},"log":"Milletin kuruma olan güveni tazelendi; bağış ve kan verme seferberliği yeniden şahlandı."},{"label":"Kızılay\'ın şirketleşen ticari iştiraklerinin tüm gelirlerini doğrudan afet çadır ve konteyner üretimine tahsis et.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Afet stokları iki katına çıkarıldı; Hazine denetiminde 500 bin çadır ve aşevi stoku kuruldu."},{"label":"Kızılay depolarındaki yardım malzemelerinin kaçırılmasını veya satılmasını önlemek için depolara kolluk nöbeti koy.","preview":"Adalet +2, Halk +8, Güvenlik +6, Otorite +6 | Hazine -4","effects":{"justice":2,"people":8,"treasury":-4,"military":6,"authority":6},"log":"İnsani yardım lojistiği tam güvenceye alındı; hiçbir yardım malzemesinin piyasaya satılmasına izin verilmedi."},{"label":"Kızılay\'ın kamu yararına dernek statüsünü ve ticari satış yasağını tescilleyen \'Kızılay Teşkilat Kanunu Reformu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Kızılay anayasal zırha kavuştu; afet zamanı çadır ve kan satışı yasal olarak imkansız kılındı."}]', 940) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_941', 'modern', 'Sahte İçki (Metil Alkol) Fabrikalarına Yönelik Dev Baskınlar', 'Emniyet Genel Müdürlüğü & Jandarma', 'Yılbaşı öncesi merdiven altı depolarda üretilen ölümcül içkiler polis ekiplerince ele geçirildi.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Merdiven altı fabrikalarda metil alkolle vatandaşın canına kıyan zehir tacirlerini \'kasten öldürme\'den Ağır Ceza\'ya sevk et.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Zehir şebekeleri çökertildi; yüzlerce vatandaşın ölümüne yol açan sahte içki baronları müebbetle yargılandı."},{"label":"Restoran, büfe ve tekel bayileri federasyonuyla bilgilendirme toplantısı yap; bandrolsüz ürün satanları sektörden dışla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Esnafla dayanışma sağlandı; sahte alkolün piyasaya sürülmesi esnafın desteğiyle engellendi."},{"label":"Etil alkol ithalatı ve satışında denatürasyon (acılaştırıcı) maddesi zorunluluğu getirerek Hazine vergi kaçağını önle.","preview":"Adalet +3, Halk +4, Hazine +8, Otorite +5","effects":{"justice":3,"people":4,"treasury":8,"military":0,"authority":5},"log":"Endüstriyel alkolün sahte içkide kullanılması kimyasal olarak imkansız kılındı; vergi kaybı sıfırlandı."},{"label":"Kaçakçılık ve Organize Suçlarla Mücadele (KOM) timleriyle 81 ilde eşzamanlı \'Zehir\' operasyonları düzenle.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Binlerce ton sahte alkol ele geçirildi; zehir tacirlerinin üretim merkezleri mühürlendi."},{"label":"Alkol piyasasında bandrol sahteciliğine ve metil alkol ticaretine terör suçları seviyesinde ceza getiren yasa çıkar.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Yasal kalkan kuruldu; sahte içki ölümlerinin önüne katı kanuni yaptırımlarla geçildi."}]', 941) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_942', 'modern', 'Etil Alkole Denatonyum Benzoat Katılması Zorunluluğu', 'Emniyet Genel Müdürlüğü & Jandarma', 'İçki yapımında kullanılan tarımsal alkolün içine dünyanın en acı maddesi katılarak içilemez yapıldı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Sokak suçları, gasp ve asayişsizliğe karşı adli tahkikatı ve savcılık işlemlerini hızlandırarak failleri tutuklat.","preview":"Adalet +8, Halk +5, Hazine +2, Otorite +6","effects":{"justice":8,"people":5,"treasury":2,"military":0,"authority":6},"log":"Sokak suçluları adliyeye teslim edildi; mahallelerde huzur ve adalet korundu."},{"label":"Mahalle esnafı, muhtarlar ve vatandaşlarla istişare toplantıları yaparak huzur ve sükûnet uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkla emniyet kaynaştı; ihbar ve dayanışma mekanizmalarıyla mahalleler huzura kavuştu."},{"label":"Emniyet araç filosu, MOBESE kamera sistemleri ve asayiş altyapısı için Hazine bütçesinden özel ödenek ayır.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Asayiş bütçesi güçlendirildi; sokakların gece gündüz aydınlatılması ve izlenmesi sağlandı."},{"label":"Çarşı ve mahalle bekçilerini, motorize yunus polislerini gece sokaklarında kesintisiz devriyeye çıkar.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Sokaklarda devletin şefkatli ve caydırıcı düdüğü çaldı; hırsızlık ve gasp olayları bıçak gibi kesildi."},{"label":"Ruhsatsız silah taşımaya ve kuru sıkı tabancalara ağır hapis cezası getiren \'Genel Asayiş ve Silah Reform Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Bireysel silahlanmaya geçit verilmedi; sokakların güvenliği kalıcı kanunlarla tahkim edildi."}]', 942) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
