INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_960', 'modern', 'Comanchero Uluslararası Motosiklet Çetesinin Çökertilmesi', 'Emniyet Genel Müdürlüğü & Jandarma', 'Avustralya merkezli uyuşturucu kartelinin Türkiye\'deki milyarlarca liralık mal varlığına el konuldu.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_goc_idaresi_baskani","name":"Göç İdaresi Başkanı"}]', '[{"label":"Sokak suçları, gasp ve asayişsizliğe karşı adli tahkikatı ve savcılık işlemlerini hızlandırarak failleri tutuklat.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Sokak suçluları adliyeye teslim edildi; mahallelerde huzur ve adalet korundu."},{"label":"Mahalle esnafı, muhtarlar ve vatandaşlarla istişare toplantıları yaparak huzur ve sükûnet uzlaşısı sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Halkla emniyet kaynaştı; ihbar ve dayanışma mekanizmalarıyla mahalleler huzura kavuştu."},{"label":"Emniyet araç filosu, MOBESE kamera sistemleri ve asayiş altyapısı için Hazine bütçesinden özel ödenek ayır.","preview":"Adalet +2, Halk +8, Otorite +4 | Hazine -6","effects":{"justice":2,"people":8,"treasury":-6,"military":0,"authority":4},"log":"Asayiş bütçesi güçlendirildi; sokakların gece gündüz aydınlatılması ve izlenmesi sağlandı."},{"label":"Çarşı ve mahalle bekçilerini, motorize yunus polislerini gece sokaklarında kesintisiz devriyeye çıkar.","preview":"Güvenlik +5, Otorite +8 | Adalet -4, Halk -7, Hazine -2","effects":{"justice":-4,"people":-7,"treasury":-2,"military":5,"authority":8},"log":"Sokaklarda devletin şefkatli ve caydırıcı düdüğü çaldı; hırsızlık ve gasp olayları bıçak gibi kesildi."},{"label":"Ruhsatsız silah taşımaya ve kuru sıkı tabancalara ağır hapis cezası getiren \'Genel Asayiş ve Silah Reform K