INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_961', 'modern', 'Sarallar ve Şahinler Suç Örgütlerine Yönelik Şafak Baskınları', 'Emniyet Genel Müdürlüğü & Jandarma', 'Yıllardır süren yeraltı hesaplaşmalarının tarafları yüzlerce polisin katıldığı operasyonlarla cezaevine yollandı.', '[{"id":"char_icisleri_bakani","name":"İçişleri Bakanı"},{"id":"char_adli_yargi_hakimi","name":"Cumhuriyet Başsavcısı"}]', '[{"label":"Yeraltı dünyasının suç örgütü liderlerini, tetikçilerini ve bunlara göz yuman rüşvetçi bürokratları bağımsız yargıya ver.","preview":"Adalet +9, Halk +7, Hazine +5, Otorite +3","effects":{"justice":9,"people":7,"treasury":5,"military":0,"authority":3},"log":"Mafyaya geçit verilmedi; suç örgütlerinin liderleri havalimanlarında kaçarken ters kelepçeyle paketlendi."},{"label":"Çetelerin haraca bağladığı esnaf ve iş insanlarıyla Valilikte kriz masası topla; can ve mal güvenliğini devletçe sağla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Esnafın korku zinciri kırıldı; mafyanın tahsilat ve yağma tehdidine karşı devlet zırhı sağlandı."},{"label":"Suç örgütlerinin el koyduğu gece kulüpleri, lüks araçlar ve kara para aklama şirketlerine MASAK marifetiyle el koy.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Mafyanın mali damarları kesildi; suçtan elde edilen milyarlarca liralık mal varlığı Hazineye aktarıldı."},{"label":"Özel Harekat polisleri ve Organize Şube timleriyle mafyanın inlerine şafak vakti \'Kafes\' operasyonları başlat.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Sokak çeteleri ve mafya yapılanmaları tek tek kafese sokuldu; devletin sokaktaki mutlak otoritesi kuruldu."},{"label":"Organize suç örgütleri, mafya tipi yapılanmalar ve yasadışı silahlanmaya karşı en katı yaptırımları getiren reform yap.","preview":"Adalet +7, Halk +5, Otorite +6 | Hazine -4","effects":{"justice":7,"people":5,"treasury":-4,"military":0,"authority":6},"log":"Sokaklar temizlendi; mafya düzeni çökerterek şehirlerde tam huzur ve asayiş tesis edildi."}]', 961) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
