INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_975', 'modern', 'Yeni ve Sivil Anayasa Çağrıları: 1982 Darbe Metninden Kurtuluş', 'Cumhurbaşkanlığı & TBMM', 'TBMM Başkanı partilerle görüşerek milletin kendi eliyle yapacağı ilk sivil anayasa turlarını başlattı.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"1982 darbe anayasasını tamamen çöpe atacak, insan onurunu ve kuvvetler ayrılığını esas alan yeni sivil anayasa tasarısını hazırla.","preview":"Adalet +8, Halk +4, Güvenlik +4, Otorite +5 | Hazine -2","effects":{"justice":8,"people":4,"treasury":-2,"military":4,"authority":5},"log":"Tarihi anayasa hamlesi başlatıldı; darbe vesayetinden arındırılmış ilk tamamen sivil anayasa masaya kondu."},{"label":"TBMM\'deki tüm siyasi partiler, akademisyenler, barolar ve halk temsilcileriyle geniş tabanlı Anayasa Şurası topla.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Milli mutabakat arandı; mecliste partiler üstü bir anlayışla temel hak ve hürriyetlerde uzlaşma sağlandı."},{"label":"Anayasa hazırlık ve halkoylaması süreçlerinin finansmanını Hazine bütçesinden şeffaf biçimde karşıla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Demokratik süreç Hazinece finanse edildi; bağımsız anayasa çalışmaları güvenceye bağlandı."},{"label":"Anayasa Mahkemesi kararlarının bağlayıcılığını ve anayasal meşruiyet zincirini koruyarak devlet düzenini tahkim et.","preview":"Adalet +7, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":7,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Hukuk güvenliği sağlandı; devlet kurumları arasındaki anayasal yetki karmaşası son buldu."},{"label":"Milletin kendi eliyle yazdığı \'Türkiye Cumhuriyeti Yeni Sivil ve Kuşatıcı Anayasası\'nı referandumla yürürlüğe koy.","preview":"Adalet +5, Halk +3, Güvenlik +7, Otorite +7 | Hazine -4","effects":{"justice":5,"people":3,"treasury":-4,"military":7,"authority":7},"log":"Darbe anayasası tarihe gömüldü; milletimiz özgür, demokratik ve sivil anayasasına kavuştu."}]', 975) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
