INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_979', 'modern', 'Kamuda Mülakatın Kaldırılması ve Tam Liyakat Sistemi', 'Cumhurbaşkanlığı & TBMM', 'Kamuya personel alımlarında torpil iddialarını bitirecek yazılı sınav ve şeffaf kura sistemine geçildi.', '[{"id":"char_tbmm_baskani","name":"TBMM Başkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Kamuya personel alımında mülakatı kaldır; KPSS puan üstünlüğünü ve bağımsız kura sistemini tavizsiz işlet.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Gençlerin adalet inancı perçinlendi; torpil iddiaları tarihe karıştı, hak eden liyakatle göreve başladı."},{"label":"Memur sendikaları ve üniversitelerle \'Kamu Liyakat ve Kariyer Şurası\' toplayarak atamalarda ortak kriterler belirle.","preview":"Adalet +3, Halk +9, Otorite +6 | Hazine -4","effects":{"justice":3,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Toplumsal mutabakat sağlandı; bürokraside kayırmacılık yerine performans ve ehliyet esas alındı."},{"label":"Kamuda liyakatli uzman ve mühendis kadrolarının maaşlarını iyileştirerek beyin göçünü Hazine teşvikiyle durdur.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Nitelikli beyinler devlette kaldı; stratejik kurumlarda mühendis ve uzman kalitesi yükseltildi."},{"label":"Devlet sırlarını sızdıran, liyakat dışı cemaat veya klik yapılanmalarına karşı Devlet Denetleme Kurulu\'nu teftişe sür.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Bürokrasi paralel yapılardan temizlendi; kamu kurumlarında tek hiyerarşi anayasal devlet otoritesi oldu."},{"label":"Kamu görevlerine girişte yazılı sınav harici tüm kayırmacı usulleri yasak