INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_996', 'modern', 'Kalkınma Yolu Projesi: Basra Körfezi\'nden Avrupa\'ya Ticaret Koridoru', 'Cumhurbaşkanlığı & TBMM', 'Irak ile imzalanan tarihi anlaşmayla Fav Limanı\'ndan Türkiye\'ye hızlı demiryolu ve otoyol inşası başladı.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_sehir_plancisi","name":"Mimarlar ve Şehir Plancıları Temsilcisi"}]', '[{"label":"Basra Körfezi\'nden Avrupa\'ya uzanan Kalkınma Yolu ve Zengezur Koridoru\'nun uluslararası hukuki anlaşmalarını imzala.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi ticaret anlaşması tescillendi; Türkiye küresel İpek Yolu\'nun vazgeçilmez merkezi haline geldi."},{"label":"Azerbaycan, Kazakistan, Özbekistan ve Kırgızistan ile Türk Devletleri Teşkilatı\'nda ortak alfabe ve ticaret anlaşması yap.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Türk dünyası birleşti; 300 milyonluk Avrasya coğrafyasında kardeş cumhuriyetler tek ekonomik blok oldu."},{"label":"Kalkınma Yolu demiryolu ve otoyol projelerini Hazine ve Körfez fonlarıyla finanse ederek Türkiye\'ye yıllık 30 milyar dolar transit gelir sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milli ekonomi şahlandı; Süveyş Kanalı\'na alternatif en hızlı ticaret koridoru Türkiye\'den geçti."},{"label":"Koridor güzergahlarında Mehmetçik ve müttefik kuvvetlerle terör örgütlerinin sabotaj tehditlerini kökünden kazı.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik hatlar korundu; Basra\'dan Londra\'ya kesintisiz yük taşımacılığı güvenlik kalkanına alındı."},{"label":"Türkiye\'yi Avrasya\'nın lojistik ve finans merkezi yapan \'Milli Kalkınma Yolu ve Transit Ticaret Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Küresel ticaret mimarisi kanunlaştı; Türkiye yüzyılın en büyük jeopolitik zaferini kazandı."}]', 996) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
