INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_998', 'modern', 'Türk Devletleri Teşkilatı\'nın (TDT) Küresel Güce Dönüşmesi', 'Cumhurbaşkanlığı & TBMM', 'Semerkant ve Astana zirveleriyle Türk dünyası ortak alfabe, ortak ordu ve ekonomik serbest bölge kurdu.', '[{"id":"char_diplomat","name":"Dışişleri Müsteşarı"},{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"}]', '[{"label":"Basra Körfezi\'nden Avrupa\'ya uzanan Kalkınma Yolu ve Zengezur Koridoru\'nun uluslararası hukuki anlaşmalarını imzala.","preview":"Adalet +9, Halk +8, Otorite +3 | Hazine -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":3},"log":"Tarihi ticaret anlaşması tescillendi; Türkiye küresel İpek Yolu\'nun vazgeçilmez merkezi haline geldi."},{"label":"Azerbaycan, Kazakistan, Özbekistan ve Kırgızistan ile Türk Devletleri Teşkilatı\'nda ortak alfabe ve ticaret anlaşması yap.","preview":"Adalet +3, Halk +6, Hazine +3, Otorite +7","effects":{"justice":3,"people":6,"treasury":3,"military":0,"authority":7},"log":"Türk dünyası birleşti; 300 milyonluk Avrasya coğrafyasında kardeş cumhuriyetler tek ekonomik blok oldu."},{"label":"Kalkınma Yolu demiryolu ve otoyol projelerini Hazine ve Körfez fonlarıyla finanse ederek Türkiye\'ye yıllık 30 milyar dolar transit gelir sağla.","preview":"Adalet +1, Halk +4, Hazine +8, Otorite +5","effects":{"justice":1,"people":4,"treasury":8,"military":0,"authority":5},"log":"Milli ekonomi şahlandı; Süveyş Kanalı\'na alternatif en hızlı ticaret koridoru Türkiye\'den geçti."},{"label":"Koridor güzergahlarında Mehmetçik ve müttefik kuvvetlerle terör örgütlerinin sabotaj tehditlerini kökünden kazı.","preview":"Adalet +5, Halk +5, Güvenlik +9, Otorite +8 | Hazine -5","effects":{"justice":5,"people":5,"treasury":-5,"military":9,"authority":8},"log":"Stratejik hatlar korundu; Basra\'dan Londra\'ya kesintisiz yük taşımacılığı güvenlik kalkanına alındı."},{"label":"Türkiye\'yi Avrasya\'nın lojistik ve finans merkezi yapan \'Milli Kalkınma Yolu ve Transit Ticaret Kanunu\' çıkar.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Küresel ticaret mimarisi kanunlaştı; Türkiye yüzyılın en büyük jeopolitik zaferini kazandı."}]', 998) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_999', 'modern', 'Dâire-i Adliyye Felsefesi: Cumhuriyetin Temeli Adalettir!', 'Cumhurbaşkanlığı & TBMM', 'Adalet olmazsa devlet çöker, halk huzur bulmaz, hazine bereketlenmez; adalet cumhuriyetin yegane bekasıdır.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_tbmm_baskani","name":"TBMM Başkanı"}]', '[{"label":"Kınalızâde Ali Efendi\'nin Adalet Dairesi felsefesine sarıl: \'Adalet mülkün temelidir; adalet olmadan ne hazine ne ordu ne devlet ayakta kalır!\'.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Devletin ruhu ihya edildi; adaletin tecellisiyle millet devletiyle kucaklaştı, asırlar sürecek beka teminat altına alındı."},{"label":"Halkın refahını, birliğini ve kardeşliğini her şeyin üstünde tut: \'İnsanı yaşat ki devlet yaşasın!\'.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Toplumsal nizam ve maslahat-ı âmme korundu; devlet ile millet arasındaki kopmaz bağ ebediyen mühürlendi."},{"label":"Hazine kasasını bereketli kıl, israfı sıfırla ve milli serveti üretime dönüştürerek ekonomik tam bağımsızlığı sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli ekonomi şahlandı; Hazine bağımsızlığıyla Türkiye hiçbir dış güce el açmayan küresel güç oldu."},{"label":"Kahraman Türk ordusunu ve emniyet teşkilatını yerli teknolojiyle donatarak vatan semalarında ve denizlerinde sarsılmaz otorite kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Devletin heybeti ve caydırıcılığı tescillendi; hiçbir şer odağının vatanımıza kem gözle bakamayacağı kanıtlandı."},{"label":"Gazi Mustafa Kemal Atatürk\'ün \'Egemenlik kayıtsız şartsız milletindir\' ülküsüyle Türkiye Yüzyılı\'nı anayasal zirveye taşı.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Milli irade ebedileşti; adaletle hükmeden, halkını yaşatan ve tam bağımsız Türkiye Cumhuriyeti kıyamete kadar payidar kılındı!"}]', 999) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('tr_vaka_1000', 'modern', 'Milletin Duası ve Devletin Bekası: Tam Bağımsız Türkiye!', 'Cumhurbaşkanlığı & TBMM', '\'Egemenlik kayıtsız şartsız milletindir\' ilkesiyle Cumhuriyetin ikinci yüzyılı adalet ve refahla mühürlendi.', '[{"id":"char_cumhurbaskani","name":"Cumhurbaşkanı"},{"id":"char_milletvekili","name":"TBMM Grup Başkanvekili"}]', '[{"label":"Kınalızâde Ali Efendi\'nin Adalet Dairesi felsefesine sarıl: \'Adalet mülkün temelidir; adalet olmadan ne hazine ne ordu ne devlet ayakta kalır!\'.","preview":"Adalet +8, Halk +6, Otorite +2 | Hazine -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":2},"log":"Devletin ruhu ihya edildi; adaletin tecellisiyle millet devletiyle kucaklaştı, asırlar sürecek beka teminat altına alındı."},{"label":"Halkın refahını, birliğini ve kardeşliğini her şeyin üstünde tut: \'İnsanı yaşat ki devlet yaşasın!\'.","preview":"Adalet +2, Halk +8, Otorite +5 | Hazine -2","effects":{"justice":2,"people":8,"treasury":-2,"military":0,"authority":5},"log":"Toplumsal nizam ve maslahat-ı âmme korundu; devlet ile millet arasındaki kopmaz bağ ebediyen mühürlendi."},{"label":"Hazine kasasını bereketli kıl, israfı sıfırla ve milli serveti üretime dönüştürerek ekonomik tam bağımsızlığı sağla.","preview":"Hazine +8, Otorite +4 | Halk -5","effects":{"justice":0,"people":-5,"treasury":8,"military":0,"authority":4},"log":"Milli ekonomi şahlandı; Hazine bağımsızlığıyla Türkiye hiçbir dış güce el açmayan küresel güç oldu."},{"label":"Kahraman Türk ordusunu ve emniyet teşkilatını yerli teknolojiyle donatarak vatan semalarında ve denizlerinde sarsılmaz otorite kur.","preview":"Adalet +3, Güvenlik +4, Otorite +7 | Halk -2, Hazine -3","effects":{"justice":3,"people":-2,"treasury":-3,"military":4,"authority":7},"log":"Devletin heybeti ve caydırıcılığı tescillendi; hiçbir şer odağının vatanımıza kem gözle bakamayacağı kanıtlandı."},{"label":"Gazi Mustafa Kemal Atatürk\'ün \'Egemenlik kayıtsız şartsız milletindir\' ülküsüyle Türkiye Yüzyılı\'nı anayasal zirveye taşı.","preview":"Adalet +8, Halk +8, Güvenlik +1, Otorite +6 | Hazine -4","effects":{"justice":8,"people":8,"treasury":-4,"military":1,"authority":6},"log":"Milli irade ebedileşti; adaletle hükmeden, halkını yaşatan ve tam bağımsız Türkiye Cumhuriyeti kıyamete kadar payidar kılındı!"}]', 1000) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_001', 'ottoman', 'Edirne Kadısının Rüşvet İddiası', 'Kaza Mahkemesi', 'Edirne tüccarları, kadının mirası paylaştırırken açıktan \'kısmet akçesi\' adı altında rüşvet aldığını divana arz etti.', '[{"id":"char_edirne_kadisi","name":"Edirne Kadısı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Müfettiş gönder ve suçu sabitse kadıyı azledip sürgüne yolla.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Kadı azledildi, tebaanın şer\'i mahkemelere itimadı tazelendi."},{"label":"İlmiye sınıfını karşına alma, meseleyi şer\'i taahhütname ve nasihatle tarafların helalleşmesini temin et.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Edirne Kadısının Rüşvet İddiası meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Edirne Kadısının Rüşvet İddiası hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Edirne Kadısının Rüşvet İddiası gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 1) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_002', 'ottoman', 'Veziriazamın Akraba Tayinleri', 'Sadaret Tezkiresi', 'Sadrazam, ehliyetli defterdar kâtiplerini azledip yerlerine genç ve tecrübesiz yeğenlerini getirdi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_defterdar","name":"Defterdar"}]', '[{"label":"Sadrazamı azarla ve liyakatli eski kâtipleri görevlerine iade et.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Devlet kalemlerinde liyakat korundu, vezirler hizbe çekildi."},{"label":"Bürokrasinin iç işine divan gözetiminde tarafları meşverete davet edip orta yolu bul, sadrazama serbestiyet ver.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 2) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_003', 'ottoman', 'Vakıf Arazisinin Gasp Edilmesi', 'Şeyhülislam Fetvası', 'Bir sancak beyi, darüşşifaya ait gelir getiren zeytinlikleri kendi şahsi mülküne katarak gelirlerine el koydu.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Şeriat gereği arazileri derhal vakfa iade et, beye ağır para cezası kes.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Vakıf hukuku korundu, taşra beyleri dizginlendi."},{"label":"Sancak beyi sınır muhafızıdır; tarafları divanda dinleyip makul bir tazminat ve rıza ile sulh bağla.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gasp edilen zeytinlik ve dükkân gelirlerini geçmişe dönük faiziyle tahsil et; vakıf bütçesini mütevelli denetimine al.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hayrat ve vakıf malına el uzatan yerel ayânları saray çavuşlarıyla yakalat; gasbettikleri mülkleri zorla geri alıp kendilerini hapse at.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 3) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_004', 'ottoman', 'Gayrimüslim Tebaanın İbadethane Talebi', 'Divan-ı Mezalim', 'Selanik\'te yanan kadim bir kilisenin cemaati, kanunlara uygun şekilde tamir izni istedi; yerel taassup ehli karşı çıkıyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Ahidnâmeye sadık kal, tamir izni fermanını gönder.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Zimmî tebaa devlete sadakatini sundu; asayiş korundu."},{"label":"Halk galeyana gelmesin, tamiri taraflara mühlet verip hakkaniyetli bir geçiş takvimi belirle.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gayrimüslim Tebaanın İbadethane Talebi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gayrimüslim Tebaanın İbadethane Talebi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gayrimüslim Tebaanın İbadethane Talebi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 4) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_005', 'ottoman', 'Haksız \'Salgun\' Vergisi Dayatması', 'Mültezim Şikâyeti', 'Diyarbakır valisi, sefere katılma bahanesiyle köylüden kanunsuz ek harç toplamaktadır.', '[{"id":"char_diyarbakir_valisi","name":"Diyarbakır Valisi"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Adâletnâme ilan et: Fazla toplanan akçeler köylüye iade edilsin.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Adalet fermanı okundu, çiftçiler tarlalarına geri döndü."},{"label":"Valiyi kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı; orduya acil mühimmat lazımdır.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 5) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_006', 'ottoman', 'Medrese Mezunlarının \'Mülazemet\' İsyanı', 'Kazasker Raporu', 'Yıllardır kadılık veya müderrislik sırası bekleyen suhteler (öğrenciler), kadroların rüşvetle satıldığını öne sürerek ayaklandı.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Sınav ve liyakat sistemini geri getir, rüşvetçi müfettişleri cezalandır.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Medrese gençliği sükunete erdi, liyakat zinciri onarıldı."},{"label":"Asayişi korumak için isyancı talebeleri zorla dağıt.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 6) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_007', 'ottoman', 'Subaşının Esnafa Zulmü', 'Taşra İstihbaratı', 'Konya Çarşısı subaşısı, her dükkândan haftalık haraç kesmekte, vermeyenin tezgâhını dağıtmaktadır.', '[{"id":"char_subasi","name":"Subaşı (Asayiş Zabiti)"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Subaşını teftiş ettirip ibret-i âlem için görevden al.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Esnaf kepenk açtı, çarşıda huzur sağlandı."},{"label":"Subaşının sertliği asayiş için lazımdır, tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Subaşının Esnafa Zulmü meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Subaşının Esnafa Zulmü meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Subaşının Esnafa Zulmü gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 7) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_008', 'ottoman', 'Valide Sultan Kethüdasının Dava Müdahalesi', 'Harem Tezkiresi', 'Valide Sultan\'ın kethüdası, büyük bir miras davasında kadıya baskı kurarak kendi yandaşını haklı çıkarmaya çalışır.', '[{"id":"char_valide_sultan","name":"Valide Sultan"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Kethüdayı saraydan uzaklaştır; kadıya \'Yalnızca şeriatı dinle\' fermanı sal.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Sarayın yargıya müdahalesi kırıldı; padişahın nüfuzu arttı."},{"label":"Harem ile divanı karşı karşıya getirme, saray ile divan arasında ortak hakem tayin edip uzlaşma sağla.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 8) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_009', 'ottoman', 'Muhassılın Zorba Tahsildarları', 'Şikâyet Defteri', 'Manisa\'da vergi toplayan muhassıllar, parası olmayan çiftçinin öküzüne ve tohumluğuna el koymaktadır.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_vergi_muhassili","name":"Vergi Muhassılı"}]', '[{"label":"Öküz ve tohum haczedilemez kanununu uygula, tahsildarları zincire vur.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Çiftçinin üretim aracı kurtarıldı; gelecek hasat güvenceye alındı."},{"label":"Hazineye nakit gerek, çiftçiye mühlet verip borcu hasat sonrasına taksitlendirerek uzlaş.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 9) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_010', 'ottoman', 'Müsadere Sistemiyle İlgili İtirazlar', 'Divan Layihası', 'Vefat eden dürüst bir vezirin terekesine devletçe toptan el konulmak isteniyor; ailesi sefalete düşecek.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Yalnızca devlete borcu kadarını al, kalan helal mirası ailesine bırak.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Bürokrasi ve devlet adamları mülkiyet güvenine kavuştu."},{"label":"Tüm serveti hazineye aktar, müsadere yerine ailenin geçimi için makul bir hisse bırakıp uzlaş.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Müsadere Sistemiyle İlgili İtirazlar davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Müsadere Sistemiyle İlgili İtirazlar davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Müsadere Sistemiyle İlgili İtirazlar gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 10) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_011', 'ottoman', 'Savaş Esirlerinin Hakları', 'Serhatname', 'Sınır akıncıları, teslim olan esir askerleri fidye alamadıkları gerekçesiyle kanun dışı katletmek istiyor.', '[{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Savaş hukukunu çiğnetme; esirleri koruma altına al.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Devletin şerefi korundu, düşman teslim olmaktan korkmadı."},{"label":"Akıncıların hırsını kırma, tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 11) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_012', 'ottoman', 'Kuyumcuların Ayar Hilesi', 'Esnaf Loncası', 'Payitaht kuyumcularının ziynet ve gümüş eşyalarda yasal ayarın altına indiği tespit edildi.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Muhtesibi görevlendir, hileli malları erittir ve loncaya ceza kes.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Piyasa güven kazandı, dürüst esnaf rahatladı."},{"label":"Kuyumcu loncasının hediyelerini kabul et, mağdurun zararını kısmen tazmin ettirip davayı sulh ile neticelendir.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 12) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_013', 'ottoman', 'Cizye Defterinde Hile', 'Rumeli Teftişi', 'Müfettişler, gayrimüslim köylerde çocuklardan ve yatalak ihtiyarlardan kanuna aykırı cizye alındığını bildirdi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Defterleri yeniden yazdır; yetim ve sakatların vergisini sil.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Balkanlarda devlete sadakat perçinlendi."},{"label":"Tahsil edilen akçeleri hazinede tut; düzeltmeyi seneye bırak.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Cizye Defterinde Hile meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Cizye Defterinde Hile meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Cizye Defterinde Hile gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 13) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_014', 'ottoman', 'Fırıncıların Ekmek Gramajı Oyunu', 'İstanbul Kadılığı', 'Un fiyatları arttığı için fırıncılar ekmeği hem küçülttü hem içine yabancı madde karıştırdı.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Tavizsiz teftiş yap, kurallara uymayan fırıncıları teşhir et.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Ekmek standardı korundu; başkentte açlık homurtuları kesildi."},{"label":"Maliyetleri anla ve narhı kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 14) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_015', 'ottoman', 'Taşrada Şahsi Hapishane Kuran Zorba', 'Ayan Raporu', 'Aydın sancağında bir mütegallibe, konağının bodrumuna zindan kurup borçlularını yasadışı zincire vuruyor.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Müfrezeler gönder, konağı kuşatıp suçluyu derhal derdest et.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Kanun dışı zorbalık ezildi; devlet otoritesi tesis edildi."},{"label":"Bölge aşiretleriyle arası iyidir, uzlaşma yolu ara.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 15) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_016', 'ottoman', 'İşkence ile İtiraf İddiası', 'Divan Meclisi', 'Cinayetle suçlanan bir tüccarın, şer\'i delil olmadan yalnızca subaşının işkencesiyle suçunu itiraf ettiği ortaya çıktı.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_subasi","name":"Subaşı (Asayiş Zabiti)"}]', '[{"label":"Davayı yeniden gör, şer\'i delil yoksa tüccarı beraat ettir.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Hukuk güvenliği sağlandı; işkenceci zabitler cezalandırıldı."},{"label":"Mahkemenin kararı bozulursa divanın prestiji sarsılır, infazı onayla.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İşkence ile İtiraf İddiası meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; İşkence ile İtiraf İddiası hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; İşkence ile İtiraf İddiası gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 16) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_017', 'ottoman', 'Korsanların Yargısız İnfazı', 'Kaptan-ı Derya', 'Akdeniz\'de ele geçirilen korsan reisi, yargılanmadan kürek mahkumu olmak yerine fidye ödemek istiyor.', '[{"id":"char_kaptan_i_derya","name":"Kaptan-ı Derya"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Kanun kanundur; mahkemeye çıkar ve hükmü kadı versin.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Devlet korsanla pazarlık etmedi; hukuk üstün geldi."},{"label":"Büyük fidyeyi kabul et ve korsanı kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Korsanların Yargısız İnfazı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Korsanların Yargısız İnfazı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Korsanların Yargısız İnfazı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 17) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_018', 'ottoman', 'Taşra Kadılıklarının Müzayedeyle Satılması', 'Kazaskerlik', 'Gelir arayan vezirler, Anadolu ve Rumeli kadılıklarını en çok peşin rüşvet verene devretmeyi teklif ediyor.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Bu teklifi lanetle! Kadılık makamı parayla satılamaz.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Yargının satılması engellendi; adalet kapısı temiz kaldı."},{"label":"Sadece bir seneliğine \'iltizam-ı kaza\' usulüne izin ver.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Taşra Kadılıklarının Müzayedeyle Satılması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Taşra Kadılıklarının Müzayedeyle Satılması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Taşra Kadılıklarının Müzayedeyle Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 18) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_019', 'ottoman', 'Karaborsacı Zahire Tüccarı', 'Muhtesip Defteri', 'Kış yaklaşırken zengin tüccarlar buğdayı depolarda saklayıp suni kıtlık çıkararak fiyatları üçe katladı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Depoları mühürle, buğdayı makul fiyattan halka zorla sattır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Karaborsa kırıldı; şehir fukarası kışı aç kalmaktan kurtuldu."},{"label":"Mülkiyet serbesttir, tüccarın malına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Karaborsacı Zahire Tüccarı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Karaborsacı Zahire Tüccarı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Karaborsacı Zahire Tüccarı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 19) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_020', 'ottoman', 'Kanunnâme-i Âl-i Osman\'ın İhlali', 'Divan Layihası', 'Vezirler, padişahın mutlak yetkilerini kullanarak örfi kanunları hiçe sayan keyfi fermanlar çıkarmaktadır.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Eski kanunları (Kanun-ı Kadîm) tazele ve vezirlerin yetkilerini sınırla.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Kanun üstünlüğü teyit edildi; keyfilik durduruldu."},{"label":"Hükümdarın iradesi her kanunun üstündedir, meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Kanunnâme-i Âl-i Osman\'ın İhlali nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Kanunnâme-i Âl-i Osman\'ın İhlali fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Kanunnâme-i Âl-i Osman\'ın İhlali meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 20) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_021', 'ottoman', 'Çiftbozan Köylülerin Dağlara Çıkması', 'Tımar Teftişi', 'Ağır vergilerden bıkan Amasya köylüleri tarlalarını bırakıp dağlara çekildi; tarlalar ekilmiyor.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Geçmiş borçları affet, tohum hibe et ve onları toprağa döndür.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Köylü toprağına döndü; ertesi yılın hasadı kurtarıldı."},{"label":"Zaptiyeler gönderip zorla çiftbozan resmi tahsil et.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Çiftbozan Köylülerin Dağlara Çıkması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Çiftbozan Köylülerin Dağlara Çıkması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Çiftbozan Köylülerin Dağlara Çıkması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 21) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_022', 'ottoman', 'Ham İpeğin Avrupa\'ya Kaçırılması', 'Bursa İpek Loncası', 'Avrupalı tüccarlar ham ipeği gümrüksüz kaçırarak yerli ipek tezgâhlarının kapanmasına sebep oluyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"İpek ihracatına yasak getir ve yerli dokumacıyı koru.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Bursa tezgâhları işlemeye devam etti; yerli zanaat korundu."},{"label":"Gümrük vergisini artırarak ihracata yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ham İpeğin Avrupa\'ya Kaçırılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Ham İpeğin Avrupa\'ya Kaçırılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Ham İpeğin Avrupa\'ya Kaçırılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 22) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_023', 'ottoman', 'Büyük Çekirge İstilası', 'Konya Ovası', 'Çekirgeler İç Anadolu\'daki ekinleri yok etti. Köylü açlıktan ot ve ağaç kabuğu yiyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Devlet ambarlarından ücretsiz zahire dağıt ve o bölgeyi vergiden muaf tut.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Halk açlıktan kırılmaktan kurtuldu; padişaha dualar edildi."},{"label":"Yalnızca vergiyi ertele; ambarları ordu için sakla.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Büyük Çekirge İstilası nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Büyük Çekirge İstilası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Büyük Çekirge İstilası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 23) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_024', 'ottoman', 'Gedik Hakkı Tartışması', 'Ahi Teşkilatı', 'Genç kalfalar dükkân açmak istiyor fakat yaşlı ustalar lonca gedik haklarını devretmeye yanaşmıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Gedik sistemini esnet, kabiliyetli gençlerin dükkân açmasına izin ver.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Üretim ve rekabet arttı; genç iş gücü piyasaya girdi."},{"label":"Loncanın kadim nizamına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla; ustaların sözü esastır.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 24) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_025', 'ottoman', 'Konar-Göçer Türkmenlerin İskânı', 'Çukurova Raporu', 'Yörük aşiretleri yerleşik köylülerin ekinlerini çiğniyor; köylülerle aşiretler arasında çatışma çıktı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_tasra_muhaciri","name":"Taşra Muhaciri"}]', '[{"label":"Aşiretlere uygun boş araziler tahsis et ve planlı iskân başlat.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Topraklar tarıma açıldı; çatışmalar sona erdi."},{"label":"Aşiretleri zorla sürgüne gönder, direnenleri kılıçtan geçir.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Konar-Göçer Türkmenlerin İskânı sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Konar-Göçer Türkmenlerin İskânı meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Konar-Göçer Türkmenlerin İskânı gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 25) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_026', 'ottoman', 'Başkente Göç Dalgası', 'İstanbul Şehremaneti', 'Anadolu\'daki güvensizlikten kaçan binlerce bekâr genç payitahta akın etti; hanlar doldu, asayiş bozuldu.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_tasra_muhaciri","name":"Taşra Muhaciri"}]', '[{"label":"Göç edenleri tespit et, memleketlerinde tarım arazisi vererek geri gönder.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Başkent rahatladı; taşrada ziraat yeniden canlandı."},{"label":"Şehir kapılarını kapat, bekâr odalarını basıp hepsini zindana at.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 26) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_027', 'ottoman', 'İpek Yolu Güvenliği ve Derbentçiler', 'Kervansaray Defteri', 'Eşkıyalar ticaret kervanlarını basıyor. Derbentçi köylüler maaş alamadıkları için geçitleri terk etti.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Derbentçilerin vergilerini affet ve onlara düzenli erzak bağla.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Ticaret yolları emniyete kavuştu; gümrük gelirleri arttı."},{"label":"Kervanları korumayı tüccarların kendi paralı muhafızlarına bırak.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve İpek Yolu Güvenliği ve Derbentçiler nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve İpek Yolu Güvenliği ve Derbentçiler fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve İpek Yolu Güvenliği ve Derbentçiler meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 27) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_028', 'ottoman', 'Tuz Tekeli ve Kaçakçılık', 'Marmara Sahilleri', 'Tuzlaların işletmesi mültezime verildi ancak mültezim fiyatı aşırı yükselttiği için köylü peynir ve et basamıyor.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Tuz tekeline narh koy, halkın ihtiyacı olan tuzu ucuzlat.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Köylü kışlık erzağını yapabildi; gıda krizi önlendi."},{"label":"Mültezimin mukavele şartlarına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla, hazine payını al.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Tuz Tekeli ve Kaçakçılık sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Tuz Tekeli ve Kaçakçılık hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Tuz Tekeli ve Kaçakçılık gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 28) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_029', 'ottoman', 'Sünger Avcılarının Ağır Vergisi', 'Ege Adaları', 'Rodos ve Sakız süngercileri fırtınalar yüzünden denize açılamadı, buna rağmen maktu vergi tam isteniyor.', '[{"id":"char_denizci_balikci","name":"Denizci / Balıkçı Esnafı"}]', '[{"label":"Fırtına felaketi sebebiyle bu seneki vergiyi yarıya indir.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Adalı balıkçı ve dalgıçlar isyandan vazgeçti."},{"label":"Hazine tarafların meşru taleplerini dinleyip orta yolda uzlaşz; borçlarını tefeciden alıp ödesinler.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Sünger Avcılarının Ağır Vergisi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Sünger Avcılarının Ağır Vergisi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Sünger Avcılarının Ağır Vergisi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 29) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_030', 'ottoman', 'Sulama Kanallarının Tıkanması', 'Dicle Kenarı', 'Bağdat civarındaki kadim su arkları balçıkla doldu. Araziler çölleşiyor, aşiretler su kavgasına tutuştu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ordu istihkâmcılarını gönder ve kamu bütçesiyle kanalları temizlet.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Araziler yeniden sulandı; hurma ve buğday hasadı ikiye katlandı."},{"label":"Köylüler kendi aralarında para toplayıp temizlesin.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Sulama Kanallarının Tıkanması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Sulama Kanallarının Tıkanması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Sulama Kanallarının Tıkanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 30) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_031', 'ottoman', 'Fındık ve Kestane Korularına El Konulması', 'Trabzon Vilayeti', 'Yerel bir paşa, asırlardır köylünün ortak kullanımında olan korulukları kendi özel av sahası ilan etti.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Paşanın fermanını yırt ve koruları köylünün ortak otlağı yap.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Ortak alan hukuku korundu; köylü rahat bir nefes aldı."},{"label":"Paşanın hatırını say, köylüye başka dağları göster.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fındık ve Kestane Korularına El Konulması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Fındık ve Kestane Korularına El Konulması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Fındık ve Kestane Korularına El Konulması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 31) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_032', 'ottoman', 'Pastırma ve Deri İmalatında Koku Şikâyeti', 'Kayseri Sancağı', 'Debbağlar (dericiler) ve kasaplar şehir dışına çıkarılmak isteniyor; esnaf ise taşınma masrafını ödeyemez.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"},{"id":"char_debbag","name":"Debbağ (Deri Ustası)"}]', '[{"label":"Şehir dışına yeni tabakhane sitesi kur ve taşınma yardımı yap.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Şehir sağlığı korundu, deri sanayii modernleşti."},{"label":"Zorla dükkânlarını yıktır, nereye giderlerse gitsinler.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 32) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_033', 'ottoman', 'Baharat Yolu Karantinası', 'Halep Çarşısı', 'Doğudan gelen kervanlarda veba mikrobu tespit edildi; tüccarlar malların şehre sokulması için rüşvet teklif ediyor.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Tavizsiz 40 günlük karantina uygula; şehri ve tebaayı koru.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Veba şehre girmedi; binlerce insanın canı kurtuldu."},{"label":"Gümrük gelirini kaybetme, kervanları içeri al.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 33) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_034', 'ottoman', 'Devşirme Sisteminde Yolsuzluk', 'Rumeli Kadılığı', 'Zengin ailelerin çocuklarını rüşvetle devşirmeden muaf tuttuğu, fukara çocuklarının haksızca alındığı iddia ediliyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Turnacıbaşını derhal teftiş et, rüşvet çarkını kır.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Devşirme kanunu aslına döndürüldü; köylünün adalete inancı arttı."},{"label":"Ocağa nefer lazımdır, kimden gelirse gelsin sorgulama.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devşirme Sisteminde Yolsuzluk meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Devşirme Sisteminde Yolsuzluk meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Devşirme Sisteminde Yolsuzluk gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 34) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_035', 'ottoman', 'Pamuk İhracatında Karaborsa', 'İzmir Limanı', 'Yabancı konsoloslar yerli tüccarı devre dışı bırakıp pamuğu tarladan ucuza kapatarak tekel oluşturdu.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Yerli esnafı koruyan tekel nizamı koy, yabancı tüccara sınır getir.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Yerli tüccar kalkındı; pamuk fiyatları dengelendi."},{"label":"Serbest ticarete meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla, gümrük vergini tahsil et.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Pamuk İhracatında Karaborsa nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Pamuk İhracatında Karaborsa fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Pamuk İhracatında Karaborsa meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 35) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_036', 'ottoman', 'Narenciye Bahçelerinin Don Vurması', 'Antalya Sahili', 'Şiddetli don sebebiyle portakal ve limon ağaçları kurudu. Üreticiler devlete ödeyecekleri öşrü çıkaramadı.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Bu seneki öşür vergisini tamamen affet.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Bahçıvanlar iflastan kurtuldu; fidanlar yeniden dikildi."},{"label":"Vergiyi mutlaka tahsil et, af emsal teşkil eder.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Narenciye Bahçelerinin Don Vurması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Narenciye Bahçelerinin Don Vurması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Narenciye Bahçelerinin Don Vurması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 36) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_037', 'ottoman', 'Tersane İçin Kereste Kesimi', 'Bolu Ormanları', 'Donanma kalyonları için Bolu köylülerinin koruma altındaki kutsal ulu meşeleri plansızca kesiliyor.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Orman mühendisi eşliğinde planlı gençleştirme kesimi yaptır.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Hem donanma tomruk buldu hem köylünün otlakları korundu."},{"label":"Donanma her şeyden önce gelir; tüm ormanı tıraşla.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tersane İçin Kereste Kesimi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Tersane İçin Kereste Kesimi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Tersane İçin Kereste Kesimi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 37) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_038', 'ottoman', 'Siderokapsa Gümüş Madencilerinin Grevi', 'Selanik Madenleri', 'Maden ocaklarındaki köylüler, havalandırma yetersizliği ve ölümler sebebiyle kazmayı bıraktı.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Çalışma şartlarını düzelt, güvenlik tedbiri al ve ücretleri artır.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Madenciler şevkle çalıştı; gümüş üretimi arttı."},{"label":"Asker zoruyla madene sok, çalışmayanı cezalandır.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 38) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_039', 'ottoman', 'Değirmen Taşı ve Su Yetersizliği', 'İstanbul Fırınları', 'Yaz kuraklığında dereler kuruduğu için un değirmenleri çalışmıyor; şehirde un sıkıntısı baş gösterdi.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Rüzgâr değirmenleri inşası için hazineden teşvik dağıt.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Yeni değirmenler kuruldu; un kıtlığı kalıcı olarak aşıldı."},{"label":"Çevre vilayetlerden zorla un müsadere et.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Değirmen Taşı ve Su Yetersizliği nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Değirmen Taşı ve Su Yetersizliği fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Değirmen Taşı ve Su Yetersizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 39) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_040', 'ottoman', 'Tuz ve Tahıl Ticareti Desteği', 'Kırım Hanlığı', 'Kırım\'dan gelen buğday gemileri fırtınada battı; tüccar iflas etmemek için sermaye yardımı istiyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Faizsiz borç vererek Karadeniz ticaret filosunu ihya et.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Tüccar borcunu ödedi; Karadeniz tahıl koridoru korundu."},{"label":"Tüccarın zararı kendi mesuliyetidir; akçe verme.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Tuz ve Tahıl Ticareti Desteği sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Tuz ve Tahıl Ticareti Desteği hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Tuz ve Tahıl Ticareti Desteği gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 40) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_041', 'ottoman', 'Akçenin Tağşişi (Ayar Düşürme)', 'Darbhane-i Âmire', 'Hazine tamtakır. Defterdar, gümüş sikkenin içine bakır karıştırarak süratle maaşları ödemeyi teklif eder.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_darphane_emini","name":"Darphane Emini"}]', '[{"label":"Asla! Paranın ayarıyla oynamak mülkün şerefini zedeler.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Para değerini korudu; enflasyon önlendi."},{"label":"Tağşişe izin ver; bu senelik ödemeleri çıkaralım.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 41) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_042', 'ottoman', 'Mültezimlerin Vergiyi Açık Artırmada Şişirmesi', 'Başdefterdarlık', 'Zengin sarraflar, iltizam mukataalarını fahiş fiyatlara kapatıp köylünün tepesine çökmek için yarışıyor.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"İltizam tavan bedeli koy, köylüyü koruyan emanet sistemine geç.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Vahşi kapital birikimi frenlendi; köylü nefes aldı."},{"label":"En çok peşin akçe veren mültezime ver, kasayı doldur.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Mültezimlerin Vergiyi Açık Artırmada Şişirmesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Mültezimlerin Vergiyi Açık Artırmada Şişirmesi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Mültezimlerin Vergiyi Açık Artırmada Şişirmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 42) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_043', 'ottoman', 'Kapitülasyonların Genişletilmesi Talebi', 'Fransız Elçiliği', 'Fransız tüccarlar gümrük vergilerinin %3\'e indirilmesini ve limanlarda serbest dolaşım imtiyazı istiyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Talebi reddet; yerli tüccarı yabancı imtiyaza ezdirtme.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Yerli esnaf korundu; yabancı tekelleşme engellendi."},{"label":"Borç para ve ittifak karşılığı imtiyazları genişlet.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kapitülasyonların Genişletilmesi Talebi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kapitülasyonların Genişletilmesi Talebi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kapitülasyonların Genişletilmesi Talebi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 43) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_044', 'ottoman', 'Lüks Tüketim ve İsraf Vergisi', 'Maliye Kalemi', 'Saray erkânı ve konak sahipleri ithal ipek, porselen ve kürk için devasa servetler akıtıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Lüks eşyaya ağır gümrük koy, israfı men eden ferman neşret.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Saray israfı dizginlendi; hazineye taze gelir girdi."},{"label":"Devletin ihtişamı sarayın debdebesindedir; harcamayı kısma.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Lüks Tüketim ve İsraf Vergisi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Lüks Tüketim ve İsraf Vergisi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Lüks Tüketim ve İsraf Vergisi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 44) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_045', 'ottoman', 'İç Borçlanma Talebi', 'Galata Sarrafları', 'Donanmanın masrafları için Galata tefecileri yüksek faizle saraya borç vermeyi teklif ediyor.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Faiz batağına girme! Harcamaları kısarak kendi yağımızla kavrulalım.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Devlet tefecilerin rehini olmaktan kurtuldu."},{"label":"Borcu al; kalyonların inşası bekletilemez.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tağşiş edilen paraları piyasadan toplatıp hazine kasasında saf külçeye dönüştür; sikke istikrarını devlet garantisine al.","preview":"Hazine +9, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Piyasanın gümüşünü eriten sarrafları Divan-ı Hümâyûn huzurunda isticvap et; tağşiş çetelerini derhal küreğe mahkûm eyle.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Darphane ve Meskûkât Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 45) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_046', 'ottoman', 'Boğaz Geçiş Vergisi Zammı', 'Gümrük Eminliği', 'Boğazlardan geçen Ceneviz ve Venedik ticaret gemilerinden alınan resmin artırılması teklif ediliyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Makul bir zam yap ve elde edilen akçeyi boğaz kalelerine harca.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Hazineye düzenli gelir sağlandı; boğaz tahkimatı güçlendi."},{"label":"Aşırı vergi koy, geçmeyenleri batırmakla tehdit et.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Boğaz Geçiş Vergisi Zammı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Boğaz Geçiş Vergisi Zammı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Boğaz Geçiş Vergisi Zammı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 46) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_047', 'ottoman', 'Sübyan Mektepleri Ödenekleri', 'Vakıf Muhasebesi', 'Hazine darlığı sebebiyle yetimlerin ve çocukların mektep aşevi bütçelerinin kısılması önerildi.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Yetimin hakkına el uzatılamaz! Bütçeyi eksiksiz öde.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Yetimler okutuldu; toplumda adalet duygusu pekişti."},{"label":"Tasarruf tedbiridir; bu senelik tahsisatı dondur.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Sübyan Mektepleri Ödenekleri nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Sübyan Mektepleri Ödenekleri fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Sübyan Mektepleri Ödenekleri meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 47) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_048', 'ottoman', 'Keban Simli Kurşun Madeni Açılışı', 'Madencilik İdaresi', 'Doğu Anadolu\'da yeni bir gümüş damarı bulundu ancak işletmeye açmak için büyük sermaye gerekiyor.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Hazine bütçesiyle kamu tesisi kur, kârı devlete kalsın.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Maden devlete kazandırıldı; düzenli gümüş akışı başladı."},{"label":"Yabancı ortaklara ruhsat ver, peşin cüzi vergi al.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 48) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_049', 'ottoman', 'Sultanın Yeni Cami ve Saray İnşası', 'Hassa Mimarları', 'Padişahın adını ebedileştirecek devasa bir külliye için halktan \'iâne-i umumiye\' toplanmak isteniyor.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"İnşaatı durdur; millet zaruret içindeyken taşa para dökülmez.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Halk üzerindeki mali yük hafifletildi; gerçek büyüklük adaletle kazanıldı."},{"label":"İnşaatı bitir; devletin azameti mabetlerin ihtişamındadır.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Sultanın Yeni Cami ve Saray İnşası hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Sultanın Yeni Cami ve Saray İnşası hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Sultanın Yeni Cami ve Saray İnşası gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 49) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_050', 'ottoman', 'Kaçak Tımar ve Zeametlerin Tespiti', 'Defterhane', 'Müfettişler, yüzlerce tımar arazisinin saray ağaları tarafından usulsüzce ele geçirildiğini belgeledi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Hepsini müsadere et ve arazileri kılıç erbabı sipahilere devret.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Tımar nizamı ihya edildi; sahte beyler temizlendi."},{"label":"Saray ağalarını ürkütme; teftiş raporunu meseleyi büyütmeden ehil rical ile istişare ederek çözüme kavuştur.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Kaçak Tımar ve Zeametlerin Tespiti nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Kaçak Tımar ve Zeametlerin Tespiti fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Kaçak Tımar ve Zeametlerin Tespiti meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 50) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_051', 'ottoman', 'Gayrimüslimlerden Zorla Hediye İstenmesi', 'Cizye Kalemi', 'Taşra valileri bayram ve şenliklerde gayrimüslim cemaat liderlerinden fahiş \'pişkeş\' harçları talep ediyor.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Tüm gayriresmî hediyeleri yasakla ve aksini yapanı vazifeden at.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Hukuksuz haraç düzeni yıkıldı; zimmîlerin huzuru sağlandı."},{"label":"Gelenek haline gelmiştir, hazine payını alıp gerisine divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 51) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_052', 'ottoman', 'Askeri Çarık Tedarik İhalesi', 'Deri Fabrikası', 'Müteahhit, orduya verilecek çarıkların derisini ucuza getirip çürük malzeme kullandı.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_debbag","name":"Debbağ (Deri Ustası)"}]', '[{"label":"Müteahhidi cezalandır, malları imha et ve sağlam sipariş ver.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Askerin sağlığı korundu, yolsuz müteahhit ibret oldu."},{"label":"Savaş kapıda; bu çarıkları idareten kabul et.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Askeri Çarık Tedarik İhalesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Askeri Çarık Tedarik İhalesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Askeri Çarık Tedarik İhalesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 52) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_053', 'ottoman', 'Kraliyet Monopolünün İptali', 'İpek İmalathanesi', 'Saray dokumacılığı tekelini kaldıralım; serbest atölyeler açılsın talebi geldi.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Monopolü kaldır; esnaf arasında hür rekabet başlasın.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Üretim patlaması yaşandı; kumaş ucuzladı."},{"label":"Tekeli koru; sarayın kontrolü elden gitmesin.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 53) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_054', 'ottoman', 'Mısır Hazinesinin Payitahta Gecikmesi', 'Mısır İrsaliye Defteri', 'Mısır Valisi, Nil taşkınlarını bahane ederek yıllık irsaliye hazinesini göndermeyi geciktiriyor.', '[{"id":"char_misir_valisi","name":"Mısır Valisi"}]', '[{"label":"Müfettiş ve donanma yolla; hazineyi eksiksiz tahsil et.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Mısır hazinesi payitahta ulaştı; vali diz çöktü."},{"label":"Valinin mazeretini kabul et ve bu senelik payı bağışla.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 54) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_055', 'ottoman', 'Sahte Altın Sikke (Kalpazanlık)', 'Darp Dairesi', 'Balkanlarda gizli darphaneler kuran bir çete, piyasaya sahte Venedik dukası ve sahte altın sürüyor.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Hepsini yakalat, maden ocaklarını kapat ve suçluları cezalandır.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Para piyasası sahtecilikten arındırıldı; güven sağlandı."},{"label":"Yalnızca elebaşlarını yakala; altınları piyasadan çekme.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sahte Altın Sikke (Kalpazanlık) meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Sahte Altın Sikke (Kalpazanlık) hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Sahte Altın Sikke (Kalpazanlık) gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 55) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_056', 'ottoman', 'Kasapların Et Boykotu', 'Şehir Kâhyalığı', 'Koyun fiyatlarına getirilen sıkı narh sebebiyle kasaplar et kesimini durdurdu; şehirde et bulunmuyor.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Narhı günün piyasa rayicine göre güncelle, üreticiyi ezme.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Kasaplar dükkânları açtı; et arzı normale döndü."},{"label":"Kasapbaşıyı hapse at, zorla dükkânları açtır.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Kasapların Et Boykotu nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Kasapların Et Boykotu fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kasapların Et Boykotu meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 56) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_057', 'ottoman', 'Donanma Kütüklerinin İhale Komisyonu', 'Tersane Kasası', 'Tersane kethüdasının, kütük alımlarında faturayı şişirip aradaki farkı zimmetine geçirdiği anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Kethüdayı azlet, zimmetine geçirdiği parayı kuruşu kuruşuna al.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Tersane bütçesi temizlendi; gemi yapımı hızlandı."},{"label":"Donanma hazırlığı aksamasın; kethüdaya meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Donanma Kütüklerinin İhale Komisyonu nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Donanma Kütüklerinin İhale Komisyonu fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Donanma Kütüklerinin İhale Komisyonu meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 57) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_058', 'ottoman', 'Yıllık Bütçe Fazlası Nasıl Kullanılsın?', 'Maliye Başkâtipliği', 'Bu sene bereketli geçti ve hazinede 500 bin altın bütçe fazlası oluştu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Yarısını yedek akçe yap, kalanını çiftçiye tohum ve kanal yardımı dağıt.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Toplumun refahı arttı; gelecek yıllar garantiye alındı."},{"label":"Tamamını askere bahşiş dağıtarak sadakatlerini perçinle.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yıllık Bütçe Fazlası Nasıl Kullanılsın hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Yıllık Bütçe Fazlası Nasıl Kullanılsın hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Yıllık Bütçe Fazlası Nasıl Kullanılsın gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 58) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_059', 'ottoman', 'Tütün ve Kahve İthalat Yasağı', 'Gümrük İdaresi', 'Ulema tütün ve kahvenin haram olduğunu savunarak ithalatının yasaklanmasını ve kahvehanelerin kapatılmasını istiyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"}]', '[{"label":"Yasak getirme; yüksek vergi koyarak hazineye devasa gelir bağla.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Hazine doldu; halk kahvehanelerde sohbetine devam etti."},{"label":"Tamamen yasakla, kahvehaneleri yıktır.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Tütün ve Kahve İthalat Yasağı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Tütün ve Kahve İthalat Yasağı fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Tütün ve Kahve İthalat Yasağı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 59) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_060', 'ottoman', 'Maktu Vergi Talebi', 'Taşra Maliyesi', 'Bir kaza halkı, her yıl değişen tahsildar zulmünden bıkıp vergilerini toptan ve peşin \'maktu\' olarak ödemek istiyor.', '[{"id":"char_tahsildar","name":"Vergi Tahsildarı"}]', '[{"label":"Talebi kabul et; halkla doğrudan sabit anlaşma yap.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Aracı zorbalar devreden çıktı; köylü huzurla üretti."},{"label":"Reddet; senelik teftiş ve tahsilat devam etsin.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Maktu Vergi Talebi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Maktu Vergi Talebi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Maktu Vergi Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 60) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_061', 'ottoman', 'Ulufe Dağıtımında Çürük Akçe İtirazı', 'Yeniçeri Ağası', 'Kapıkulu askerleri kendilerine verilen akçelerin hafif olduğunu söyleyerek çorba kazanlarını devirdi.', '[{"id":"char_yeniceri_agasi","name":"Yeniçeri Ağası"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Derhal hazineyi aç, tam ayar akçe ver ve kazanları kaldır.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"İsyan yatıştı ancak asker devlete şart koşmayı alışkanlık edindi."},{"label":"Saray muhafızlarını hazırla; elebaşılarını derhal kılıçtan geçir.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Ulufe Dağıtımında Çürük Akçe İtirazı meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Ulufe Dağıtımında Çürük Akçe İtirazı hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Ulufe Dağıtımında Çürük Akçe İtirazı gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 61) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_062', 'ottoman', 'Ateşli Silahlar ve Sipahi İhmali', 'Tımarlı Sipahi Temsilcisi', 'Tımarlı atlı sipahiler, tüfekli sekban birliklerine yapılan harcamalar yüzünden kendi dirliklerinin ellerinden alındığını söylüyor.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Sipahilere modern tüfek eğitimi ver ve tımar nizamını modernize et.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Anadolu sipahisi modernleşti; ordu dengesi korundu."},{"label":"Tımar devri bitti; sipahileri dağıtıp tüfekli levent topla.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Ateşli Silahlar ve Sipahi İhmali nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Ateşli Silahlar ve Sipahi İhmali fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Ateşli Silahlar ve Sipahi İhmali meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 62) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_063', 'ottoman', 'Kadırgadan Kalyona Geçiş Talebi', 'Kaptan-ı Derya', 'Batı donanmaları yelkenli kalyonlara geçti. Donanmamız hala kürekli kadırgalarla savaşıyor ve yeniliyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kaptan_i_derya","name":"Kaptan-ı Derya"}]', '[{"label":"Büyük tersane reformu başlat; kalyon inşasına dev bütçe ayır.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Akdeniz\'de kalyonlarımız hakimiyet kurdu; deniz ticareti güvenceye alındı."},{"label":"Kadırgalar sığ sularda üstündür; masrafa gerek yok.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Kadırgadan Kalyona Geçiş Talebi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Kadırgadan Kalyona Geçiş Talebi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kadırgadan Kalyona Geçiş Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 63) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_064', 'ottoman', 'Kamaniçe Kalesinin Erzak Sıkıntısı', 'Serhat Kaleleri', 'Sınırdaki en uç kalemizin buğday ve barut stoku tükendi. Düşman ordusu yaklaşıyor.', '[{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Acil yardım konvoyu çıkar, ordu bütçesinden erzağı yetiştir.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Kale kuşatmaya dayandı; serhat hattı düşmedi."},{"label":"Civar köylerden zorla erzak toplayıp kaleye sokun.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kamaniçe Kalesinin Erzak Sıkıntısı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kamaniçe Kalesinin Erzak Sıkıntısı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kamaniçe Kalesinin Erzak Sıkıntısı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 64) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_065', 'ottoman', 'Yeniçerilerin Kahvehaneleri Ele Geçirmesi', 'İstanbul Sokakları', 'Yeniçeri esnafı haraç kesmekte, meyhane ve kahvehaneleri kabadayı yatağı haline getirmektedir.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Yeniçeri ağasını bizzat teftişe çıkar, zorbaları ocaktan at.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Payitaht sokakları huzura kavuştu; zorbalık ezildi."},{"label":"Ocağın tepkisini çekme; şimdilik idare et.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Yeniçerilerin Kahvehaneleri Ele Geçirmesi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Yeniçerilerin Kahvehaneleri Ele Geçirmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Yeniçerilerin Kahvehaneleri Ele Geçirmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 65) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_066', 'ottoman', 'Çöl Ortasında Askerin Su İsyanı', 'Bağdat Seferi', 'Kavurucu sıcakta su kaynakları zehirlendi. Askerler geri dönmek için yürüyüşe geçti.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Padişah bizzat atından inip askere suyunu paylaştırsın, gayret aşılasın.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Hükümdarın fedakarlığı askeri şahlandırdı; zafer kazanıldı."},{"label":"Emre itaatsizlik eden subayları oracıkta kurşuna diz.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Çöl Ortasında Askerin Su İsyanı nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Çöl Ortasında Askerin Su İsyanı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Çöl Ortasında Askerin Su İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 66) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_067', 'ottoman', 'Büyük Şahi Toplarının Dökümü', 'Tophane-i Âmire', 'Surlar için devasa bronz toplar dökülecek fakat bakır ve kalay stokları yetersiz.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Sarayın gümüş ve bakır kap kacağını tophaneye eritmeye yolla.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Muazzam toplar döküldü; düşman kaleleri titredi."},{"label":"Halktan zorunlu maden vergisi topla.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Büyük Şahi Toplarının Dökümü hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Büyük Şahi Toplarının Dökümü hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Büyük Şahi Toplarının Dökümü gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 67) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_068', 'ottoman', 'Kış Seferi Tartışması', 'Kafkasya Cephesi', 'Generaller kışın ortasında dağları aşıp sefere devam etmek istiyor; asker donma tehlikesiyle karşı karşıya.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Seferi bahara ertele, orduyu kışlaklara çek.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"On binlerce askerin hayatı kurtarıldı."},{"label":"Taviz yok, kışın hücum emri ver.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 68) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_069', 'ottoman', 'Cezayir Beylerbeyinin Özerk Davranışları', 'Akdeniz Filosu', 'Garp ocakları beyleri kendi başlarına korsanlık yapıp Avrupalı müttefik gemilerini yağmalıyor.', '[{"id":"char_beylerbeyi","name":"Beylerbeyi"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Merkezi idareye tabi olmalarını emret, itaatsiz beyleri azlet.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Devletin dış politikadaki ciddiyeti ve disiplini korundu."},{"label":"Ganimetten pay gönderdikleri sürece yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Cezayir Beylerbeyinin Özerk Davranışları nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Cezayir Beylerbeyinin Özerk Davranışları fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Cezayir Beylerbeyinin Özerk Davranışları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 69) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_070', 'ottoman', 'Leventlerin Terhis Edilmesi ve Eşkıyalık', 'Sancak Teftişi', 'Savaş bittiği için başıboş kalan sekban ve leventler köyleri basıp \'diş kirası\' toplamaya başladı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Onları sınır kalelerine yerleştir veya ziraat arazisi vererek orduyu terhis et.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Eşkıyalık kaynağında kurutuldu; taşra sükunete erdi."},{"label":"Bütçe yok; ferman çıkarıp herkes evine dönsün de.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Leventlerin Terhis Edilmesi ve Eşkıyalık hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Leventlerin Terhis Edilmesi ve Eşkıyalık hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Leventlerin Terhis Edilmesi ve Eşkıyalık gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 70) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_071', 'ottoman', 'Ocağa Dışarıdan Kayıt (Ecir) Yapılması', 'Acemi Ocağı', 'Vezirler ve ağalar, kendi kölelerini ve akrabalarını rüşvetle yeniçeri defterine yazdırıyor.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Defterleri incele; ecirleri derhal ocaktan ihraç et.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Askeri liyakat kurtarıldı; fazladan maaş yükü silindi."},{"label":"Yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla; ağalarla arayı bozma.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Ocağa Dışarıdan Kayıt (Ecir) Yapılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Ocağa Dışarıdan Kayıt (Ecir) Yapılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Ocağa Dışarıdan Kayıt (Ecir) Yapılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 71) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_072', 'ottoman', 'İnce Donanma Gemilerinin Bakımsızlığı', 'Tuna Donanması', 'Tuna nehrini bekleyen şaykalar çürüdü. Kazak korsanları nehir boyundaki kasabaları basıyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Nehir tersanelerini hızla faaliyete geçir, şaykaları yenile.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Tuna boyu emniyete alındı; ticaret korundu."},{"label":"Köylüler kendi palankalarını (küçük hisarlarını) kursun.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve İnce Donanma Gemilerinin Bakımsızlığı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve İnce Donanma Gemilerinin Bakımsızlığı fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve İnce Donanma Gemilerinin Bakımsızlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 72) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_073', 'ottoman', 'Mora Yarımadasında Ayaklanma', 'Mora İsyanı', 'Venedik kışkırtmasıyla yerel çeteler kaleleri kuşattı ve Türk köylerine baskın yaptı.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Nizamı korumak için disiplinli bir ordu yolla, sivil halka dokunulmamasını emret.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"İsyan bastırıldı; adil davranıldığı için ahali devlete sığındı."},{"label":"Başıboş birlikleri sal, taş üstünde taş bırakmasınlar.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Mora Yarımadasında Ayaklanma meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Mora Yarımadasında Ayaklanma hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Mora Yarımadasında Ayaklanma gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 73) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_074', 'ottoman', 'Barut İmalathanesinde Büyük Patlama', 'Baruthane-i Âmire', 'İstanbul baruthanesi havaya uçtu; barutsuz kalan ordunun sefer kabiliyeti durdu.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Bakırköy\'de modern ve güvenli yeni bir baruthane kur.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Barut üretimi eskisinden daha kaliteli hale getirildi."},{"label":"Avrupa\'dan acil ve pahalı barut ithal et.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Barut İmalathanesinde Büyük Patlama nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Barut İmalathanesinde Büyük Patlama fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Barut İmalathanesinde Büyük Patlama meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 74) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_075', 'ottoman', 'Ordugâhta Dizanteri ve Humma Salgını', 'Hekimbaşı Raporu', 'Kuşatma altındaki ordugâhta içme suyuna pislik karışması yüzünden asker kılıçtan çok hastalıktan kırılıyor.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sıhhiye çadırları kurdur, hekimleri seferber et ve suları kaynattır.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Salgın kontrol altına alındı; asker morali yükseldi."},{"label":"Kuşatmaya hız ver; salgına bakmadan hücum ettir.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Ordugâhta Dizanteri ve Humma Salgını nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Ordugâhta Dizanteri ve Humma Salgını fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Ordugâhta Dizanteri ve Humma Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 75) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_076', 'ottoman', 'At ve Yem Kıtlığı', 'Sipahi Çadırları', 'Kuru ot bulunamadığı için sipahi atları telef oluyor; süvariler piyadeye dönme riskiyle karşı karşıya.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Hazine akçesiyle Macaristan\'dan yem satın aldır.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Süvari gücü korundu."},{"label":"Köylünün ambarındaki tohumluk arpalara el koy.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"At ve Yem Kıtlığı sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; At ve Yem Kıtlığı meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; At ve Yem Kıtlığı gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 76) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_077', 'ottoman', 'Düşman Barış Teklifi ve Ganimet Bölüşümü', 'Sadrazam Çadırı', 'Avusturya elçisi yüklü bir tazminatla barış istiyor; yeniçeriler ise yağma için kaleyi basmak istiyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Tazminatı al, barış imzala ve askere düzenli bahşiş ver.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Kan dökülmeden hazine doldu; şerefli bir barış yapıldı."},{"label":"Askerin isteğine uy, şehri yağmaya aç.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Düşman Barış Teklifi ve Ganimet Bölüşümü nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Düşman Barış Teklifi ve Ganimet Bölüşümü fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Düşman Barış Teklifi ve Ganimet Bölüşümü meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 77) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_078', 'ottoman', 'İran Sınırında Casusluk Ağı', 'Erzurum Beylerbeyi', 'Safevi casuslarının Doğu Anadolu aşiretlerine para dağıtarak mezhep kışkırtıcılığı yaptığı tespit edildi.', '[{"id":"char_beylerbeyi","name":"Beylerbeyi"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"İstihbaratı güçlendir, aşiret reislerini payitahta çağırıp hil\'at giydir.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Aşiretler devlete bağlandı; fitne bertaraf edildi."},{"label":"Şüphelenilen tüm köyleri yak, halkı batıya sür.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve İran Sınırında Casusluk Ağı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve İran Sınırında Casusluk Ağı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve İran Sınırında Casusluk Ağı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 78) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_079', 'ottoman', 'Cebeci Ocağında Silah Hırsızlığı', 'Divan Meclisi', 'Cebecilerin devletin tüfek ve barutunu el altından taşradaki eşkıyaya sattığı ortaya çıktı.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_cebecibasi","name":"Cebecibaşı"}]', '[{"label":"Cebecibaşını idam ettir ve tüm cephaneliği sayıma al.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Devlet silahlarının karaborsaya düşmesi engellendi."},{"label":"Ocağı ürkütme, tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Cebeci Ocağında Silah Hırsızlığı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Cebeci Ocağında Silah Hırsızlığı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Cebeci Ocağında Silah Hırsızlığı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 79) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_080', 'ottoman', 'Kalyoncuların Maaş İsyanı', 'Venedik Körfezi', 'Denizde aylardır kürek çeken forsa ve leventler 6 aydır maaş alamadıklarını söyleyerek gemileri limana kilitledi.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Kalyoncuların hakkını kuruşu kuruşuna derhal öde.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Donanma sefere hazır hale geldi; moral yükseldi."},{"label":"Elebaşıları denize at, forsalara kırbaç vurdur.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kalyoncuların Maaş İsyanı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kalyoncuların Maaş İsyanı fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kalyoncuların Maaş İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 80) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_081', 'ottoman', 'Veliaht Şehzadenin Eğitimi ve Sancağa Çıkışı', 'Sarayburnu', 'Şehzadenin sarayda kafeste kalması yerine tecrübe kazanması için Manisa sancağına gönderilmesi teklif ediliyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Kanun-ı kadîm üzere şehzadeyi lala eşliğinde sancağa gönder.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Şehzade devlet idaresini sahada öğrendi; halk geleceğe güvendi."},{"label":"Sarayda kalsın; taht kavgası ve isyan riski doğmasın.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Veliaht Şehzadenin Eğitimi ve Sancağa Çıkışı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Veliaht Şehzadenin Eğitimi ve Sancağa Çıkışı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Veliaht Şehzadenin Eğitimi ve Sancağa Çıkışı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 81) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_082', 'ottoman', 'Sadrazam ile Şeyhülislamın Nüfuz Çatışması', 'Bab-ı Âli', 'Sadrazam ve Şeyhülislam birbirlerini devlete hıyanetle suçlayıp divanı kilitledi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"İkisini de huzura çağır; adaleti hakem kıl, uzlaşmazlarsa ikisini de azlet.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Devlet başsız olmadığını gösterdi; bürokratik kriz çözüldü."},{"label":"Bir tarafı tutarak diğerini zindana at.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sadrazam ile Şeyhülislamın Nüfuz Çatışması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Sadrazam ile Şeyhülislamın Nüfuz Çatışması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Sadrazam ile Şeyhülislamın Nüfuz Çatışması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 82) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_083', 'ottoman', 'Kudüs Kutsal Mekânlar İhtilafı', 'Rus Çarlığı Elçisi', 'Rus elçisi, Ortodoksların koruyucusu olduğunu iddia ederek Kudüs\'teki kiliselerin anahtarlarını talep ediyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Talebi reddet; padişah kendi mülkünün ve tebaasının tek koruyucusudur.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Devletin egemenlik hakları tavizsiz savunuldu."},{"label":"Savaşı göze alma; taleplerin bir kısmını kabul et.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Kudüs Kutsal Mekânlar İhtilafı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Kudüs Kutsal Mekânlar İhtilafı fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Kudüs Kutsal Mekânlar İhtilafı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 83) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_084', 'ottoman', 'Enderun Mektebinde Reform', 'Topkapı Sarayı', 'Devlet adamı yetiştiren Enderun\'da fen, matematik ve lisan derslerinin ihmal edildiği tespit edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Müfredatı yenile, Batı dillerini ve modern coğrafyayı zorunlu kıl.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Donanımlı ve dünyayı tanıyan yeni nesil bürokratlar yetişti."},{"label":"Eski usul yeterlidir; yabancı ilimlere kapıları kapat.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Enderun Mektebinde Reform nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Enderun Mektebinde Reform fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Enderun Mektebinde Reform meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 84) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_085', 'ottoman', 'Kraliyet Donanması İçin Tahıl Talebi', 'İngiliz Ticaret Heyeti', 'İngilizler İspanya ile savaştıkları için yüksek altın teklif ederek Ege tahılının tamamını satın almak istiyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Önce kendi halkımızın ambarları; tahıl ihracını yasakla.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Payitahtta ekmek güvenceye alındı; fukara aç kalmadı."},{"label":"İngiliz altını tatlıdır; tahılı yükleyip satın.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kraliyet Donanması İçin Tahıl Talebi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kraliyet Donanması İçin Tahıl Talebi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kraliyet Donanması İçin Tahıl Talebi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 85) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_086', 'ottoman', 'Tarih Yazıcılığında Sansür', 'Vak\'anüvis Tezkiresi', 'Sadrazam, hezimetle biten son seferin vak\'anüvis tarihinde \'büyük zafer\' olarak yazılmasını emretti.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Hatasını bilmeyen devlet çöker; tarihi hakikat üzere yazdır.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Hatalardan ders çıkarıldı; ordudaki aksaklıklar ıslah edildi."},{"label":"Halkın morali bozulmasın; sahte zaferi yazdır.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Tarih Yazıcılığında Sansür nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Tarih Yazıcılığında Sansür fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Tarih Yazıcılığında Sansür meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 86) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_087', 'ottoman', 'Lehistan Tahtına Aday Desteği', 'Lehistan Krallığı', 'Lehistan\'da kral öldü; Avusturya yanlısı adaya karşı Osmanlı dostu bir asilzade tahta geçmek için destek istiyor.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Gizli ödenekten altın ve kırım süvarisi desteği vererek dost kralı seçtir.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Kuzey sınırımızda dost bir krallık kuruldu; sınır güvenliği sağlandı."},{"label":"Kuzeyin iç işlerine divan gözetiminde tarafları meşverete davet edip orta yolu bul; altın hazinede kalsın.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Lehistan Tahtına Aday Desteği nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Lehistan Tahtına Aday Desteği fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Lehistan Tahtına Aday Desteği meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 87) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_088', 'ottoman', 'Saray Hekimlerinin Yabancı İlaç Talebi', 'Harem-i Hümayun', 'Veba ve çiçek hastalığına karşı Venedik\'ten yeni tıbbi aşı ve ilaçların getirilmesi öneriliyor; tutucular karşı çıkıyor.', '[{"id":"char_tabip","name":"Tabip / Cerrah"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"İlim Çin\'de de olsa alınız; hekimlere yetki ver ve ilaçları getirt.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Salgınlar önlendi; tebaanın canı modern tıpla korundu."},{"label":"Gâvur icadıdır deyip ilaçları limanda denize döktür.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Beytülmâl\'den darüşşifa ve karantina lazaretolarına acil ödenek tahsis et; Saray Hekimlerinin Yabancı İlaç Talebi sürecinde sıhhi teftişe riayet eden tüccarlara vergi indirimi tanı.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Limanı silahlı muhafızlarla karantinaya al; Saray Hekimlerinin Yabancı İlaç Talebi fermanını delmeye kalkan ticaret gemilerini top ateşi tehdidiyle açık denizde tut.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Karantina-i Bahriye ve Sıhhat Kanunu\' neşret; Saray Hekimlerinin Yabancı İlaç Talebi gibi hadiselerin tekerrürünü önleyecek şekilde liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 88) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_089', 'ottoman', 'Ortodoks Kilisesi Patrik Seçimi', 'Balkan Metropolitleri', 'Patriklik makamı için yarışan iki piskopos, divan kâtiplerine rüşvet teklif ederek berat koparmaya çalışıyor.', '[{"id":"char_ortodoks_patriki","name":"Ortodoks Patriği"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Rüşveti reddet; kilise meclisini topla ve ruhbanın kendi seçimine saygı duy.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Fatih\'in emaneti korundu; gayrimüslim tebaa devlete şükran duydu."},{"label":"En yüksek rüşveti veren adaya beratı ver.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Ortodoks Kilisesi Patrik Seçimi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Ortodoks Kilisesi Patrik Seçimi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ortodoks Kilisesi Patrik Seçimi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 89) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_090', 'ottoman', 'Hükümdarın Cuma Selamlığına Çıkmaması', 'Veziriazam Konseyi', 'Padişah aylardır saraydan çıkmıyor. Dedikodular yayıldı: \'Padişah öldü veya delirdi\' deniyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Derhal halkın içine çık, Cuma selamlığında tebaayı bizzat selamla.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Fitne anında söndü; halk hükümdarını görüp teskin oldu."},{"label":"Güvenlik tehlikelidir; sarayda kalmaya devam et.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 90) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_091', 'ottoman', 'İbrahim Müteferrika\'nın Matbaa Layihası', 'Matbaa Teşebbüsü', 'Kitap basmak için matbaa kurulması teklif edildi; hattatlar ve bazı muhafazakâr kâtipler işsiz kalacakları için isyan ediyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Ferman çıkar: Dini olmayan fenni ve ilmi kitaplar matbaada basılsın.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"İlim ucuzladı ve yayıldı; cehalete büyük bir darbe vuruldu."},{"label":"Hattatların hatırını kırma; matbaa projesini iptal et.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İbrahim Müteferrika\'nın Matbaa Layihası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İbrahim Müteferrika\'nın Matbaa Layihası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İbrahim Müteferrika\'nın Matbaa Layihası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 91) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_092', 'ottoman', 'Akdeniz ile Kızıldeniz\'i Birleştirme Projesi', 'Süveyş Kanalı Fikri', 'Mimar ve mühendisler Süveyş\'te kanal açılırsa Hindistan ticaretinin tamamen Osmanlı kontrolüne geçeceğini hesapladı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Büyük projeyi başlat; kazma vurulsun.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Tarihin en büyük projesi başladı; küresel üstünlük kapısı aralandı."},{"label":"Çok masraflı; çölün kumuna hazine akıtamayız.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Akdeniz ile Kızıldeniz\'i Birleştirme Projesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Akdeniz ile Kızıldeniz\'i Birleştirme Projesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Akdeniz ile Kızıldeniz\'i Birleştirme Projesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 92) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_093', 'ottoman', 'Portekiz Tehdidine Karşı Yardım Feryadı', 'Fas Sultanlığı', 'Fas Sultanı, Portekiz işgaline karşı Osmanlı halifesinden asker ve topçu desteği talep ediyor.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"Yardım filosunu ve yeniçerileri yolla; Vadisseyl\'de küffarı durdur.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Muazzam bir zafer kazanıldı; Kuzey Afrika sömürge olmaktan kurtuldu."},{"label":"Fas çok uzaktır; kendi başlarının çaresine baksınlar.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 93) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_094', 'ottoman', 'Yabancı Bankalardan Borç Alma Teklifi', 'Hazine Sandığı', 'Avrupalı bankerler çok düşük faiz vaadiyle saraya 5 milyon altın kredi teklif ediyor.', '[{"id":"char_yabanci_banker","name":"Yabancı Banker (Düyun-ı Umumiye)"}]', '[{"label":"Borç alan emir alır! Teklifi derhal geri çevir.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Devletin bağımsızlığı korundu; mali prangalar reddedildi."},{"label":"Krediyi al; sarayları ve donanmayı ihya edelim.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasadaki kırpık akçeleri darphanede saf gümüşle değiştir; Yabancı Bankalardan Borç Alma Teklifi meselesinde sarraflara faizsiz ikraz verip sikke değerini ve alım gücünü koru.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sahte ve kırpık akçe basan kalpazanları bostancı müfrezesiyle bas; Yabancı Bankalardan Borç Alma Teklifi meselesinde suç ortaklarını derhal zincire vurup zindana kapat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Darphane ve Meskûkât Kanunnâmesi\' neşret; Yabancı Bankalardan Borç Alma Teklifi gibi hadiselerin tekerrürünü önleyecek şekilde akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 94) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_095', 'ottoman', 'Gönüllü Süvari Alayları Kurulması', 'Kafkasya Aşiretleri', 'Dağıstan ve Çerkes beyleri, Osmanlı bayrağı altında savaşmak için kendi süvarileriyle orduya katılmak istiyor.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Teklifi kabul et, reislerine sancak ve hil\'at ver.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Kafkasya sınırı çelik bir kalkanla örüldü."},{"label":"Düzenli ordu disiplinini bozarlar; kabul etme.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Gönüllü Süvari Alayları Kurulması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Gönüllü Süvari Alayları Kurulması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Gönüllü Süvari Alayları Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 95) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_096', 'ottoman', 'Rasathane İnşası ve Uğursuzluk Tartışması', 'Şeyhülislamlık', 'Tâkıyüddîn\'in kurduğu rasathanenin depreme ve uğursuzluğa yol açtığını iddia edenler yıkılmasını istiyor.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Yobazlığa boyun eğme; rasathaneyi koru ve astronomi çalışmalarını destekle.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Bilimsel ilerleme korundu; denizcilik haritaları geliştirildi."},{"label":"Halkın infialini dindirmek için rasathaneyi yıktır.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Rasathane İnşası ve Uğursuzluk Tartışması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Rasathane İnşası ve Uğursuzluk Tartışması fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Rasathane İnşası ve Uğursuzluk Tartışması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 96) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_097', 'ottoman', 'Hac Yolu Su Kuyularının Tahkimi', 'Hicaz Vilayeti', 'Bedevi kabileler su kuyularını kapatıp hacı kafilelerini haraca bağlıyor; Surre alayı tehlikede.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Kervan yollarına müstahkem hisarlar kur ve bedevi reislerine maaş bağla.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Hac yolu emniyete alındı; halifenin İslam alemindeki şerefi arttı."},{"label":"Masrafa gerek yok; hacılar kendi muhafızlarını tutsun.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hac Yolu Su Kuyularının Tahkimi meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Hac Yolu Su Kuyularının Tahkimi hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Hac Yolu Su Kuyularının Tahkimi gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 97) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_098', 'ottoman', 'Saray Casusluk ve Jurnal Ağı', 'Sadaret Arşivi', 'Vezirler, rakiplerini alt etmek için padişaha her gün yüzlerce asılsız ihbar ve jurnal mektubu sunuyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Yalancı muhbirleri cezalandır; tahkikatsız kimsenin canına ve malına dokunma.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Korku ve şüphe iklimi dağıldı; dürüst devlet adamları huzur buldu."},{"label":"Her jurnalden şüphelen; tutuklamaları ve tasfiyeleri artır.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Saray Casusluk ve Jurnal Ağı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Saray Casusluk ve Jurnal Ağı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Saray Casusluk ve Jurnal Ağı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 98) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_099', 'ottoman', 'Kasr-ı Şirin Sınır Anlaşması', 'İran Şahı Elçisi', 'Yıllardır süren kanlı savaşların ardından Şah, Zağros Dağları\'nı sınır kabul eden daimi barış teklif etti.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Teklifi kabul et; sınırları sabitle ve sulh nizamını kur.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Asırlık kan durdu; doğu ticareti canlandı, sınır kalıcılaştı."},{"label":"Barışı reddet; İsfahan\'a kadar sefere devam emri ver.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kasr-ı Şirin Sınır Anlaşması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kasr-ı Şirin Sınır Anlaşması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kasr-ı Şirin Sınır Anlaşması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 99) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_100', 'ottoman', 'Nizâm-ı Âlem Kanunnâmesinin Mühürlenmesi', 'Divan-ı Hümayun', 'Tüm tecrübeler ışığında; adaleti, reayayı, hazineyi, orduyu ve mülkü birbirine ebediyen bağlayan büyük Adalet Kanunnâmesi hazırlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Fermanı mühürle ve taşraya adâletnâme olarak yay: \'Adalet Mülkün Temelidir!\'.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Dâire-i Adliyye kâmil manada tesis edildi; cihan sulhü kuruldu."},{"label":"Kanunları rafa kaldır; günübirlik tedbirlerle devleti idare et.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Nizâm-ı Âlem Kanunnâmesinin Mühürlenmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Nizâm-ı Âlem Kanunnâmesinin Mühürlenmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Nizâm-ı Âlem Kanunnâmesinin Mühürlenmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 100) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_101', 'ottoman', 'Yetim Terekesine El Uzanması', 'Kaza Sicili', 'Vefat eden zengin bir tüccarın geride bıraktığı çocuklarının malı, vasi tayin edilen kadı naibi tarafından usulsüzce işletilip eritildi.', '[{"id":"char_kadi_naibi","name":"Kadı Naibi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Naibin tüm servetini müsadere et, yetimlerin hakkını kuruşu kuruşuna tazmin et.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Yetim malı korundu; kadı naibi ibret için azledildi."},{"label":"İlmiye zümresini küçük düşürme; meseleyi aile içinde sulh ettir.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Yetim Terekesine El Uzanması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Yetim Terekesine El Uzanması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Yetim Terekesine El Uzanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 101) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_102', 'ottoman', 'Tımar Sahibinin Kadıyı Tehdidi', 'Divan Mezalim Dairesi', 'Bir sipahi beyi, köylüyle olan alacak davasında aleyhine hüküm kuran kaza kadısını kılıç çekerek mahkemeden kovdu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"}]', '[{"label":"Sipahinin dirligini elinden al ve kendisini kalebend et.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Kaza bağımsızlığı korundu; kılıç ehlinin hukuka tecavüzü durduruldu."},{"label":"Asker kıttır; kadıyı başka kazaya naklederek arayı bul.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Tımar Sahibinin Kadıyı Tehdidi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Tımar Sahibinin Kadıyı Tehdidi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Tımar Sahibinin Kadıyı Tehdidi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 102) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_103', 'ottoman', 'Kan Bedeli (Diyet) Uyuşmazlığı', 'Kaza Müftülüğü', 'Aşiret reisinin oğlu bir köylüyü kazara vurdu. Aşiret şer\'i diyeti ödemeyi reddedip köylüleri kan davasıyla tehdit ediyor.', '[{"id":"char_muftu","name":"Müftü"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Nizam kuvvetlerini yolla; diyeti zorla tahsil edip aileye teslim et.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Zorbalık ezildi; kan davasının büyümesi engellendi."},{"label":"Sınır aşiretidir, küstürme; diyeti hazineden ödeyip saray erkânı ile divan arasında bir denge formülü bularak uzlaş.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kan Bedeli (Diyet) Uyuşmazlığı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Kan Bedeli (Diyet) Uyuşmazlığı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Kan Bedeli (Diyet) Uyuşmazlığı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 103) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_104', 'ottoman', 'Kutsal Kabristan Arazisi Anlaşmazlığı', 'Kudüs Kadılığı', 'Müslüman ve Hristiyan cemaatler, asırlık ortak sınırda bulunan bir mezarlık arazisinin mülkiyeti için çatışmaya girdi.', '[{"id":"char_kudus_kadisi","name":"Kudüs Kadısı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Fatih\'in kadim ahidnâmesini açtır, kadı heyetiyle sınır taşlarını eskisi gibi diktir.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Eski beratlar teyit edildi; iki cemaat de karara rıza gösterdi."},{"label":"Araziyi hazineye katıp iki tarafa da yasakla.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kutsal Kabristan Arazisi Anlaşmazlığı nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kutsal Kabristan Arazisi Anlaşmazlığı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kutsal Kabristan Arazisi Anlaşmazlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 104) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_105', 'ottoman', 'İpek İplikçilerinin Sahte Şahit Şebekesi', 'Bursa Mahkemesi', 'Bir grup tefecinin yalancı şahitler tutarak borçsuz esnafı mahkemede borçlu gösterip mallarına çöktüğü anlaşıldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Yalancı şahitleri çarşıda teşhir et ve şebekeyi kürek cezasına çarptır.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Yargıya olan güven tazelendi; esnaf iflastan döndü."},{"label":"Zahirde şahitler usule uygundur; hükmü bozma.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve İpek İplikçilerinin Sahte Şahit Şebekesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve İpek İplikçilerinin Sahte Şahit Şebekesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve İpek İplikçilerinin Sahte Şahit Şebekesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 105) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_106', 'ottoman', 'Vakıf Şartnamesinin Değiştirilmesi Talebi', 'Rumeli Kazaskerliği', 'Bir vezir, atalarının kurduğu medresenin vakıf gelirlerini kendi konağının bakımına aktarmak için fetva istiyor.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"\'Vakıf şartı, şâri\'in nassı gibidir!\' diyerek talebi kesin bir dille reddet.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Vakıf dokunulmazlığı muhafaza edildi; vezirin hırsı dizginlendi."},{"label":"Vezirin nüfuzundan çekin, yumuşak bir teville onay ver.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Vakıf Şartnamesinin Değiştirilmesi Talebi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Vakıf Şartnamesinin Değiştirilmesi Talebi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Vakıf Şartnamesinin Değiştirilmesi Talebi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 106) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_107', 'ottoman', 'Gıyabi İdam Fermanı Talebi', 'Dîvân-ı Hümâyûn', 'Sancak beyi, kendisine muhalefet eden bir ileri geleni huzura getirmeden doğrudan katli için padişah fermanı ister.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_sancak_beyi","name":"Sancak Beyi"}]', '[{"label":"Yargısız infaz fermanı çıkmaz! Davalının payitahtta muhakemesini emret.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Hukuk güvencesi teyit edildi; keyfi infazların önü kesildi."},{"label":"Beyin otoritesini sarsma; fermanı imzala.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Gıyabi İdam Fermanı Talebi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Gıyabi İdam Fermanı Talebi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Gıyabi İdam Fermanı Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 107) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_108', 'ottoman', 'Köle ve Cariyelerin Hukuki Durumu', 'İstanbul İhtisabı', 'Bir efendinin, azat ettiği kölesini seneler sonra haksız yere tekrar mülk edinmeye kalktığı şikâyet edildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Azat kâğıdını incelet, kölenin hürriyetini tasdikle ve efendiye ceza kes.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Hürriyet hakkı korundu; adalet kapısı zayıflara kalkan oldu."},{"label":"Eski efendi muteber bir zattır; tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Köle ve Cariyelerin Hukuki Durumu nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Köle ve Cariyelerin Hukuki Durumu fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Köle ve Cariyelerin Hukuki Durumu meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 108) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_109', 'ottoman', 'Miras Taksiminde Kadın Hakları', 'Bosna Vilayeti', 'Bir aşiret, örf bahanesiyle vefat eden beyin kız çocuklarına mirastan pay vermeyip her şeyi erkek çocuklara devretti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Şeriat miras paylarını açıkça belirlemiştir; malları eşit nispette taksim ettir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Şer\'i miras korundu; örfi gasp engellendi."},{"label":"Aşiretin iç dengesidir; fıtnaya mahal vermemek için divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras Taksiminde Kadın Hakları davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Miras Taksiminde Kadın Hakları davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Miras Taksiminde Kadın Hakları gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 109) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_110', 'ottoman', 'Ticareti Engelleyen Korsan Beratları', 'Trablusgarp Kadılığı', 'Yerel bir korsan reisi, elindeki sahte kaza beratını öne sürerek Müslüman tüccarların sefinelerine el koyuyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Sahte beratı yırt, korsanı zindana at ve gemileri sahiplerine iade et.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Deniz ticareti emniyete kavuştu; sahtecilik cezalandırıldı."},{"label":"Korsanın donanmaya faydası vardır; aralarını bul.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Ticareti Engelleyen Korsan Beratları nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Ticareti Engelleyen Korsan Beratları fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Ticareti Engelleyen Korsan Beratları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 110) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_111', 'ottoman', 'Zimmiye Ait İpek Fabrikasının Yakılması', 'Halep Mahkemesi', 'Fanatik bir grup esnaf, başarılı bir Ermeni dokumacının fabrikasını kundaklayıp \'Müslüman pazarını bozuyor\' dedi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Kundakçıları yakalatıp tanzim ettir; fabrikayı devlet korumasına al.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Mülkiyet emniyeti sağlandı; gayrimüslim tebaa sadakat tazeledi."},{"label":"Halkın öfkesinden çekin; olayı kaza süsü vererek kapat.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Zimmiye Ait İpek Fabrikasının Yakılması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Zimmiye Ait İpek Fabrikasının Yakılması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Zimmiye Ait İpek Fabrikasının Yakılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 111) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_112', 'ottoman', 'Mühürsüz İlam ve Hüccet Ticareti', 'Kaza Teftişi', 'Bir mahkeme kâtibinin, rüşvet karşılığı mühürsüz sahte arazi tapuları ve miras hüccetleri sattığı tespit edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Kâtibi teşhir edip elini meslekten men et, tapuları iptal et.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Resmi evraka itimat kurtarıldı; mülkiyet kargaşası bitti."},{"label":"İptal olursa yüzlerce arazi davası çıkar; evrakları onaylayıp geç.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mühürsüz İlam ve Hüccet Ticareti davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Mühürsüz İlam ve Hüccet Ticareti davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Mühürsüz İlam ve Hüccet Ticareti gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 112) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_113', 'ottoman', 'Kadı ile Subaşının Rüşvet İttifakı', 'Mora Sancağı', 'Mora kadısı ile asayişten sorumlu subaşı gizlice anlaşıp zengin köylüleri sahte suçlarla haraca bağlıyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_subasi","name":"Subaşı (Asayiş Zabiti)"}]', '[{"label":"Özel teftiş heyeti sal, ikisini de zincire vurdurup payitahta getirt.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Taşra çetesi kırıldı; ahali kurbanlar keserek devleti kutladı."},{"label":"Gelen şikâyetler abartılıdır; yerel idarecileri yıpratma.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 113) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_114', 'ottoman', 'Terk Edilen Arazinin İşgali', 'Erzurum Kadılığı', 'Savaş yüzünden kaçan köylülerin tarlalarına yerel zenginler oturmuş, geri dönen asıl sahiplerini kovmaktadır.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Tahrir defterini aç; tarlaları asıl sahiplerine ver, gasıpları cezalandır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Hakkâniyet sağlandı; köylü toprağını şevkle sürmeye başladı."},{"label":"Toprağı kim işliyorsa mülk onundur fermanı çıkar.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Terk Edilen Arazinin İşgali nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Terk Edilen Arazinin İşgali fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Terk Edilen Arazinin İşgali meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 114) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_115', 'ottoman', 'Kira Bedellerinde Fahiş Artış', 'Üsküdar Mahkemesi', 'Payitahtta konut sahipleri kiraları aniden beş katına çıkardı; medrese talebeleri ve memurlar sokakta kaldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"}]', '[{"label":"Kira rayicine üst sınır (narh) koy, haksız tahliyeleri yasakla.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Dar gelirliler korundu; payitahtta sosyal patlama önlendi."},{"label":"Mülk hürriyetine müdahale edilmez; piyasaya divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kira Bedellerinde Fahiş Artış sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kira Bedellerinde Fahiş Artış hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kira Bedellerinde Fahiş Artış gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 115) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_116', 'ottoman', 'Kuyu Suyu Zehirlenmesi İddiası', 'Sıvas Kazası', 'Köy kuyusuna zehir attığı iddia edilen garip bir dervişi köylüler linç etmek üzere toplandı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Zaptiye gönderip dervişi mahkemeye çıkart, su analiz edilmeden hüküm verme.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Suyun zehirli değil killi olduğu anlaşıldı; masum can kurtuldu."},{"label":"Halkın galeyanını bastıramazsın; dervişi köylüye terk et.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kuyu Suyu Zehirlenmesi İddiası nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kuyu Suyu Zehirlenmesi İddiası fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kuyu Suyu Zehirlenmesi İddiası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 116) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_117', 'ottoman', 'Kervan Mallarının Zayi Olması Davası', 'Şam Mahkemesi', 'Çölde fırtınaya tutulan kervandaki mallar için deve sahipleri kusurlu bulunmak isteniyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Şer\'i mücbir sebep ilkesini işlet; tarafları makul tazminatta uzlaştır.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Taşımacı esnafı batmaktan kurtuldu; kervan seferleri sürdü."},{"label":"Zararın tamamını deveci bedevilere yükle.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kervan Mallarının Zayi Olması Davası nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kervan Mallarının Zayi Olması Davası fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kervan Mallarının Zayi Olması Davası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 117) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_118', 'ottoman', 'Ulemanın Vergiden Muafiyet Talebi', 'Dîvân-ı Şer\'iyye', 'Zenginleşen müderris ve kadı aileleri, şahsi çiftliklerinin de öşür ve haractan muaf tutulmasını istiyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_muderris","name":"Medrese Müderrisi"}]', '[{"label":"İlmiye şahsı muaftır, arazisi değil! Kanun önünde eşitlik fermanı sal.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"İmtiyazlı sınıfın vergi kaçırması engellendi; hazine gelir kazandı."},{"label":"Ulemanın rızasını gözet, çiftliklerini vergiden bağışla.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ulemanın Vergiden Muafiyet Talebi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Ulemanın Vergiden Muafiyet Talebi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Ulemanın Vergiden Muafiyet Talebi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 118) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_119', 'ottoman', 'İş Kazası ve Diyet Ödemesi', 'İstanbul Baruthanesi Mahkemesi', 'Tophanede top dökerken kazan devrilmesi sonucu sakat kalan dökümcü ustasına kazaen diyet ödenmesi isteniyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Tersane ve Tophane ocak bütçesinden ömür boyu maaş ve diyet bağla.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Sanayi erbabı devlete bağlandı; iş gücü moral buldu."},{"label":"Kendi hatasıdır deyip hiçbir tazminat ödeme.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve İş Kazası ve Diyet Ödemesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve İş Kazası ve Diyet Ödemesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve İş Kazası ve Diyet Ödemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 119) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_120', 'ottoman', 'İltimasla Kadı Olan Gençlerin İmtihanı', 'Divan Meclisi', 'Kazaskerlerin sınavsız kadı yaptığı yüzlerce tecrübesiz medreselinin kazalarda büyük hatalar yaptığı bildirildi.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Tüm kadıları payitahta çağırıp umumi ilim imtihanından geçir; kalanları azlet.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Cahil kadılar temizlendi; mahkemelere vakar ve bilgi geldi."},{"label":"İlmiye zümresi infial eder; imtihanı iptal et.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve İltimasla Kadı Olan Gençlerin İmtihanı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve İltimasla Kadı Olan Gençlerin İmtihanı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve İltimasla Kadı Olan Gençlerin İmtihanı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 120) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_121', 'ottoman', 'Kalitesiz Pabucun Dama Atılması', 'Ahi Şeyhliği', 'Kunduracılar kethüdası, hileli deri kullanan bir ustanın pabucunu dama atıp dükkânını kapattı; usta vezire sığındı.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Ahilik geleneğine saygı duy; lonca kararını tasdikle.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Üretim standardı korundu; hileli mal piyasadan kovuldu."},{"label":"Vezirin hatırına ustanın dükkânını zorla açtır.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalitesiz Pabucun Dama Atılması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Kalitesiz Pabucun Dama Atılması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Kalitesiz Pabucun Dama Atılması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 121) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_122', 'ottoman', 'Bağbozumu ve Şıra Vergisi', 'Trakya Köyleri', 'Şiddetli dolu felaketi bağları vurdu; köylü şıra ve pekmez yapamadığı için maktu vergiden indirim istiyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hasar tespiti yaptır, bu senelik bağ vergisini tamamen sil.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Köylü bağlarını sökmekten vazgeçti; ertesi yıl üretim ikiye katlandı."},{"label":"Hazine tarafların meşru taleplerini dinleyip orta yolda uzlaşz; vergi tam alınsın.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Bağbozumu ve Şıra Vergisi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Bağbozumu ve Şıra Vergisi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Bağbozumu ve Şıra Vergisi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 122) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_123', 'ottoman', 'Zeytin Ağaçlarının Yakacak İçin Kesilmesi', 'Gediz Havzası', 'Kış soğuğunda yakacak bulamayan fukara köylüler asırlık zeytin ağaçlarını kesmeye başladı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Devlet ormanlarından ücretsiz odun dağıt, zeytin kesene ağır ceza koy.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Hem köylü donmaktan kurtuldu hem zeytinyağı istihsali korundu."},{"label":"Müdahale etme; kışın soğuğunda köylüye akıl verilmez.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Zeytin Ağaçlarının Yakacak İçin Kesilmesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Zeytin Ağaçlarının Yakacak İçin Kesilmesi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Zeytin Ağaçlarının Yakacak İçin Kesilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 123) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_124', 'ottoman', 'Dokuma Tezgâhlarında Kadın Emeği', 'İpek İplikçileri Loncası', 'Evlerinde ipek büken kadınların lonca harcından muaf tutulması teklif ediliyor; lonca ağaları itiraz ediyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Evde üretim yapan kadınları lonca harcından muaf tut; üretimi teşvik et.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Ev ekonomisi canlandı; ipek ipliği bollaştı."},{"label":"Loncanın kuralı birdir; her tezgâhtan harç tahsil et.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dokuma Tezgâhlarında Kadın Emeği davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Dokuma Tezgâhlarında Kadın Emeği davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Dokuma Tezgâhlarında Kadın Emeği gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 124) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_125', 'ottoman', 'Küre Bakır Madeninde Su Baskını', 'Kastamonu Bakır Ocakları', 'Tophane için bakır sağlayan Küre madenini yeraltı suyu bastı; su tulumbası için bütçe verilmezse ocak kapanacak.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Derhal mühendis ve ödenek yolla; tulumba sistemini kurdur.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Maden kurtarıldı; top dökümü için bakır temini kesilmedi."},{"label":"Maden bütçesini kıs; bakırı dışarıdan ithal edelim.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Küre Bakır Madeninde Su Baskını nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Küre Bakır Madeninde Su Baskını fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Küre Bakır Madeninde Su Baskını meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 125) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_126', 'ottoman', 'Kök Boya İthalatında Hile', 'Tokat Basmacıları', 'Yabancı tüccarların getirdiği kalitesiz kimyevi boyalar, Tokat yazmalarının ilk yıkamada solmasına yol açıyor.', '[{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Sahte boyaları gümrükte yaktır, yerli kök boya ekimini teşvik et.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Tokat yazmaları eski şöhretine kavuştu; yerli tarım kazandı."},{"label":"Ucuz boyadır, esnaf istediğini kullansın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kök Boya İthalatında Hile nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kök Boya İthalatında Hile fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kök Boya İthalatında Hile meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 126) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_127', 'ottoman', 'İpekböceği Tohumu Hastalığı', 'Diyarbakır Kervanları', 'İran\'dan gelen ipekböceği yumurtalarında parazit çıktı; Güneydoğu ipekçiliği yok olma tehlikesiyle yüz yüze.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Hastalıklı tohumları imha et, Bursa\'dan temiz tohum getirip üreticiye bedava dağıt.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Hastalık yayılmadan kesildi; ipek hasadı kurtarıldı."},{"label":"Üretici kendi tohumunu kendi alsın; hazineden harcama yapma.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İpekböceği Tohumu Hastalığı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; İpekböceği Tohumu Hastalığı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; İpekböceği Tohumu Hastalığı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 127) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_128', 'ottoman', 'Pastırma ve Sucukluk Sığır Vebası', 'Kayseri Çiftçileri', 'Kafkasya\'dan kaçak getirilen sığırlar yüzünden İç Anadolu\'da büyük hayvan vebası patlak verdi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sıkı karantina kur, kaçak hayvanları itlaf et ve zarar gören köylüye tazminat ver.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Veba söndürüldü; köylünün sürüsü yenilendi."},{"label":"Karantina ticareti aksatır; kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 128) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_129', 'ottoman', 'Meriç Nehri Boyunda Sıtma Salgını', 'Edirne Çeltikçileri', 'Pirinç eken çeltik mültezimleri su bentlerini kurutmadığı için bataklıklar şehre sıtma yayıyor.', '[{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"Halk sağlığı pirinçten üstündür! Bentleri açtır, tarlaları şehirden uzağa taşıt.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Edirne sıtmadan kurtuldu; halk nefes aldı."},{"label":"Çeltik geliri sarayın has geliridir; üretimi bozma.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Meriç Nehri Boyunda Sıtma Salgını nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Meriç Nehri Boyunda Sıtma Salgını fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Meriç Nehri Boyunda Sıtma Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 129) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_130', 'ottoman', 'Çini Fırınlarının Kapanması', 'İznik Çinisi Atölyeleri', 'Kuvars ve odun pahalılığı yüzünden İznik ustaları fırınları yakamaz oldu; meşhur sır reçeteleri kayboluyor.', '[{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"İznik ustalarına hibe ver, cami ve saray siparişleriyle atölyeleri canlandır.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Muazzam İznik çinisi yeniden parladı; sanat ebedileşti."},{"label":"İtalyan seramiği daha ucuzdur; siparişleri oraya ver.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çini Fırınlarının Kapanması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Çini Fırınlarının Kapanması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Çini Fırınlarının Kapanması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 130) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_131', 'ottoman', 'Hurma Bahçelerinin Tuzlanması', 'Bağdat Hurmalıkları', 'Aşırı sulama ve drenaj eksikliği yüzünden kadim hurmalıklar çoraklaşıp beyaz tuza kesti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Drenaj hendekleri açılması için kamu bütçesi tahsis et.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Toprak tuzdan temizlendi; hurma hasadı kurtuldu."},{"label":"Aşiretler kendi imkânlarıyla temizlesin.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Hurma Bahçelerinin Tuzlanması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Hurma Bahçelerinin Tuzlanması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hurma Bahçelerinin Tuzlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 131) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_132', 'ottoman', 'Kuru İncirde Yabancı Tüccar Kumpası', 'Aydın İncir Üreticileri', 'İngiliz tüccarlar kuru incir mahsulünü tarlada çok ucuza kapatıp piyasayı speküle ediyor.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Müstahsil kooperatifi (taban fiyat ambarı) kurdur; köylüyü tefeciye ezdirtme.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Üretici hakkını aldı; incir ticareti devlet kontrolünde zenginleşti."},{"label":"İngilizlerle ticareti bozma; köylü ne bulursa satsın.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Kuru İncirde Yabancı Tüccar Kumpası nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Kuru İncirde Yabancı Tüccar Kumpası fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kuru İncirde Yabancı Tüccar Kumpası meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 132) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_133', 'ottoman', 'Keten ve Kenevir Hasadı', 'Sinop Tersanesi Kırsalı', 'Yelken bezi ve halat için gereken keneviri köylü az kâr ettiği için ekmek istemiyor.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kenevir alım fiyatını %40 artır ve avans ödemesi yap.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Donanma bol ve sağlam halat buldu; köylü kenevire yöneldi."},{"label":"Köylüye zorunlu kenevir ekimi kotası koy, ekmeyeni cezalandır.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Keten ve Kenevir Hasadı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Keten ve Kenevir Hasadı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Keten ve Kenevir Hasadı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 133) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_134', 'ottoman', 'Tabak Derilerinin Nehir Suyunu Kirletmesi', 'Safranbolu Tabakhaneleri', 'Debbağların nehre akıttığı zehirli atıklar yüzünden aşağı köylerdeki hayvanlar telef oluyor.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Arıtma dinlendirme havuzları yaptır, nehri zehirleyen tabakhaneyi kapat.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Nehir temizlendi; köylünün suyu ve hayvanları kurtuldu."},{"label":"Deri ihracatı çok mühimdir; köylüler başka dereden su alsın.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Tabak Derilerinin Nehir Suyunu Kirletmesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Tabak Derilerinin Nehir Suyunu Kirletmesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Tabak Derilerinin Nehir Suyunu Kirletmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 134) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_135', 'ottoman', 'Su Değirmenlerinde Hak Sırası Kavgası', 'Konya Değirmenleri', 'Yazın kuruyan derede kalan tek değirmen için güçlü beyler fakir köylünün buğdayını öğütmesine engel oluyor.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Değirmene adil sıra nöbetçisi dik, fakirin ununu öncelikle öğüttür.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Kavga bitti; fukara evine un götürebildi."},{"label":"Değirmen sahibi kime isterse ona öğütsün; divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Su Değirmenlerinde Hak Sırası Kavgası nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Su Değirmenlerinde Hak Sırası Kavgası fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Su Değirmenlerinde Hak Sırası Kavgası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 135) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_136', 'ottoman', 'Yörük Develerinin Müsadere Edilmesi', 'Toros Yaylaları', 'Bağdat seferi için ordu levazımı Yörüklerin damızlık mayalarını ve yük develerini bedelsiz almak istiyor.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Damızlık develeri muaf tut; alınan yük develerinin bedelini peşin öde.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Yörükler gönüllü olarak binlerce deve getirdi."},{"label":"Savaş hali kanunudur; bedelsiz müsadere et.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Yörük Develerinin Müsadere Edilmesi meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Yörük Develerinin Müsadere Edilmesi hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Yörük Develerinin Müsadere Edilmesi gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 136) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_137', 'ottoman', 'Göz Nuru Vergisinin Kaldırılması', 'Kütahya Çinicileri', 'Nakkaşlar ve çini boyayıcıları, dükkân başına alınan haksız \'göz resmi\' harcının kaldırılmasını niyaz eder.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sanatkârı teşvik et; gereksiz harcı tamamen kaldır.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Kütahya çiniciliği canlandı; zarif eserler ortaya çıktı."},{"label":"Küçük de olsa her gelir damlası lazımdır; harcı al.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Göz Nuru Vergisinin Kaldırılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Göz Nuru Vergisinin Kaldırılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Göz Nuru Vergisinin Kaldırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 137) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_138', 'ottoman', 'Çeltik ve Mısır Tohumu Dağıtımı', 'Balkan Çiftlikleri', 'Yeni Dünya\'dan gelen mısır tohumunun ekilmesi, kurak topraklarda kıtlığı önleyebilir.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mısır ekimini sübvanse et, köylüye örnek tarlalar kurdur.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Mısır bereketi kıtlığı tamamen bitirdi; nüfus hızla arttı."},{"label":"Geleneksel buğdaydan şaşma; yabancı tohuma para yatırma.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Çeltik ve Mısır Tohumu Dağıtımı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Çeltik ve Mısır Tohumu Dağıtımı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Çeltik ve Mısır Tohumu Dağıtımı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 138) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_139', 'ottoman', 'Koyun Yünü İhracat Yasağı', 'Sivas Halıcıları', 'İngiliz tüccarlar tüm koyun yününü toplayıp götürüyor; Anadolu halı dokumacıları yapağısız kaldı.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Yün ihracatına kota koy, yerli halı dokumacısının ihtiyacını öncele.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Anadolu tezgâhları şakırdadı; dünya çapında halılar dokundu."},{"label":"İhracat gümrüğü tatlıdır; bırakın alsınlar.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Koyun Yünü İhracat Yasağı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Koyun Yünü İhracat Yasağı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Koyun Yünü İhracat Yasağı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 139) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_140', 'ottoman', 'Fethin Ardından Arazilerin Eski Sahiplerine Verilmesi', 'Girit Zeytinlikleri', 'Girit fethedildikten sonra adanın yerli Rum ahalisi zeytinliklerini geri istemektedir.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Adâletnâme gereği arazileri eski sahiplerine iade et, maktu vergiye bağla.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Girit halkı Osmanlı nizamını bağrına bastı; ada huzur buldu."},{"label":"Arazileri fetih gazilerine ve yeniçerilere paylaştır.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Fethin Ardından Arazilerin Eski Sahiplerine Verilmesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Fethin Ardından Arazilerin Eski Sahiplerine Verilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Fethin Ardından Arazilerin Eski Sahiplerine Verilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 140) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_141', 'ottoman', 'Gümüş Yerine Bakır \'Mankur\' Basılması', 'Darbhane-i Âmire', 'Piyasada küçük bozuk para kalmadı; defterdar esnaf için değersiz bakırdan pul basmayı önerir.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_darphane_emini","name":"Darphane Emini"}]', '[{"label":"Sadece günlük çarşı alışverişi için sınırlı ve mühürlü basımına izin ver.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Ufaklık para darlığı çözüldü; çarşıda bozuk para bulundu."},{"label":"Mankuru ordu maaşlarında da kullanmayı dene.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Gümüş Yerine Bakır \'Mankur\' Basılması nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Gümüş Yerine Bakır \'Mankur\' Basılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Gümüş Yerine Bakır \'Mankur\' Basılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 141) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_142', 'ottoman', 'İspanyol Gümüş \'Riyal\' İstilası', 'Galata Rıhtımı', 'Güney Amerika\'dan gelen ucuz İspanyol riyalleri piyasayı bastı; yerli akçe hızla eriyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Riyalleri darphanede toplatıp eriterek yüksek ayarlı yeni Osmanlı kuruşu bas.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Milli sikke nizamı kuruldu; para istikrarı sağlandı."},{"label":"Piyasayı kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı; riyal dolaşsın.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasadaki kırpık akçeleri darphanede saf gümüşle değiştir; İspanyol Gümüş \'Riyal\' İstilası meselesinde sarraflara faizsiz ikraz verip sikke değerini ve alım gücünü koru.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sahte ve kırpık akçe basan kalpazanları bostancı müfrezesiyle bas; İspanyol Gümüş \'Riyal\' İstilası meselesinde suç ortaklarını derhal zincire vurup zindana kapat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Darphane ve Meskûkât Kanunnâmesi\' neşret; İspanyol Gümüş \'Riyal\' İstilası gibi hadiselerin tekerrürünü önleyecek şekilde akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 142) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_143', 'ottoman', 'Yol ve Köprü Geçiş Harçları (Avarız)', 'Başmuhasebe', 'Mali kriz yüzünden halktan her köprü ve geçitte iki kat \'müruriye\' harcı alınması istendi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ticareti boğacak haksız harçları yasakla; vergiyi tek ve şeffaf yap.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Kervanlar hızlandı; ticaret canlanarak hazineyi başka yoldan doldurdu."},{"label":"Harcı koy; geçen her arabadan para kesilsin.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Yol ve Köprü Geçiş Harçları (Avarız) nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Yol ve Köprü Geçiş Harçları (Avarız) fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Yol ve Köprü Geçiş Harçları (Avarız) meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 143) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_144', 'ottoman', 'Malikâne Sistemine Geçiş Teklifi', 'Taşra Defterdarlığı', 'Vergi kaynaklarının (mukataa) mültezimlere ömür boyu kiralanması teklif edildi; peşin para büyük fakat taşra derebeyleşebilir.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"Reddet! Ömür boyu iltizam devleti parçalar, emanet usulünü koru.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Merkezi otorite korundu; ayanların türemesi engellendi."},{"label":"Kabul et; hazinenin bugünkü devasa açığını hemen kapat.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Malikâne Sistemine Geçiş Teklifi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Malikâne Sistemine Geçiş Teklifi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Malikâne Sistemine Geçiş Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 144) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_145', 'ottoman', 'Et Narhı ve Canbaz Zorbalığı', 'İstanbul Kasapları', 'Canbazlar (hayvan tüccarları) şehre koyun sokmayarak narhın iki katı fiyat dayatıyor.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Canbaz tekelini kır; Rumeli\'den doğrudan devlet eliyle sürü getir.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Karaborsa çöktü; başkentte ucuz ve bol et satıldı."},{"label":"Canbazların istediği yüksek fiyatı narh olarak onayla.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Et Narhı ve Canbaz Zorbalığı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Et Narhı ve Canbaz Zorbalığı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Et Narhı ve Canbaz Zorbalığı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 145) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_146', 'ottoman', 'Sikke Kırpma (Kırkıntı) Çetesi', 'Sarraflar Çarşısı', 'Gümüş akçelerin kenarlarını makasla kırparak tozuyla külçe yapan sarraflar yakalandı.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Tırtıklı kenar teknolojisine geç; yakalananları en ağır şekilde cezalandır.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Sikke hırsızlığı durduruldu; paranın hacmi ve ağırlığı korundu."},{"label":"Sarraflardan yüklü bir \'diyet akçesi\' alıp kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Sikke Kırpma (Kırkıntı) Çetesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Sikke Kırpma (Kırkıntı) Çetesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Sikke Kırpma (Kırkıntı) Çetesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 146) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_147', 'ottoman', 'Şarap ve Meyhane Resmi Zammı', 'Gümrük Kalemi', 'Ahlaki bozulmayı önleme gerekçesiyle gayrimüslim meyhanelerine fahiş ek resim konması önerildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Kanunnâme dışına çıkma; vergiyi ahidnâmede yazılı nispetle sınırla.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Hukukilik korundu; kaçak içki üretimi engellendi."},{"label":"En ağır vergiyi koy; hem para gelsin hem içilmesin.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Şarap ve Meyhane Resmi Zammı nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Şarap ve Meyhane Resmi Zammı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Şarap ve Meyhane Resmi Zammı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 147) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_148', 'ottoman', 'Gümrüksüz İpek Kumaş Kaçakçılığı', 'Venedik Balyosu', 'Venedik ticaret gemilerinin geceleri gizlice Haliç\'e yanaşıp kaçak kadife indirdiği ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_gumruk_emini","name":"Gümrük Emini"}]', '[{"label":"Sahil muhafızlarına baskın emri ver, gemilere ve mallara derhal el koy.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Kaçakçılık şebekesi çökertildi; gümrük gelirleri tahkim edildi."},{"label":"Balyosla diplomatik kriz çıkmasın; sadece malları geri yolla.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gümrüksüz İpek Kumaş Kaçakçılığı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gümrüksüz İpek Kumaş Kaçakçılığı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gümrüksüz İpek Kumaş Kaçakçılığı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 148) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_149', 'ottoman', 'Saray Aşevi (Matbah-ı Âmire) Masrafları', 'Hassa Harcamaları', 'Sarayda her gün pişen kuşkonmaz, amber ve yabani sülün eti masrafları bütçeyi sarsıyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Saray mutfağına sıkı tasarruf getir; sade halk yemekleri pişsin.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Hükümdar halkın haline ortak oldu; hazine büyük yükten kurtuldu."},{"label":"Sultanın sofrası devletin azametidir; tasarruf yapılmaz.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Saray Aşevi (Matbah-ı Âmire) Masrafları nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Saray Aşevi (Matbah-ı Âmire) Masrafları fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Saray Aşevi (Matbah-ı Âmire) Masrafları meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 149) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_150', 'ottoman', 'Vergi Borçlarının Tahsilinde Şiddet', 'Taşra Muhassıllığı', 'Ödeyemeyen köylülerin kış ortasında buzlu sulara sokularak vergi tahsil edildiği haberleri geldi.', '[{"id":"char_vergi_muhassili","name":"Vergi Muhassılı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bu vahşeti uygulayan tahsildarları derhal idam et! Mazlumun ahı tahtı yıkar.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Zulüm kılıçla kesildi; halk adil padişaha bağlılığını haykırdı."},{"label":"Sertlik olmadan bu köylü para vermez; divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Vergi Borçlarının Tahsilinde Şiddet nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Vergi Borçlarının Tahsilinde Şiddet fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Vergi Borçlarının Tahsilinde Şiddet meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 150) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_151', 'ottoman', 'Nil Nilometresi ve İndirim Talebi', 'Mısır Valiliği', 'Nil suları bu sene kâfi derecede yükselmedi; kuraklık kapıda olduğu için Mısır ahalisi vergi indirimi istiyor.', '[{"id":"char_misir_valisi","name":"Mısır Valisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Nilometre ölçümünü esas al, kuraklık nispetinde vergiyi bağışla.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Mısır çiftçisi açlıktan kurtuldu; mülk huzura kavuştu."},{"label":"Mısır zengindir; fermanı değiştirme, tam hazineyi iste.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Nil Nilometresi ve İndirim Talebi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Nil Nilometresi ve İndirim Talebi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Nil Nilometresi ve İndirim Talebi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 151) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_152', 'ottoman', 'Portekiz Baharat Ambargosu', 'Basra Gümrüğü', 'Hürmüz Boğazı\'nı tutan Portekizliler, Basra\'ya gelen tüccar gemilerinden fahiş harç kesip yolu tıkıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Basra tersanesinde kalyonlar inşa et ve ticaret yolunu silahla açtır.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Körfez yolu emniyete alındı; baharat ticareti yeniden aktı."},{"label":"Portekiz ile anlaşıp onların koyduğu harca rıza göster.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Portekiz Baharat Ambargosu nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Portekiz Baharat Ambargosu fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Portekiz Baharat Ambargosu meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 152) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_153', 'ottoman', 'Yabancı Elçilere Verilen \'Tayinat\' İsrafı', 'Hassa Çadırları', 'Payitahttaki yabancı elçilere her gün çuvallarla et, şeker ve yağ saray bütçesinden bedava verilmektedir.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Tayinatı diplomatik teamüllerin asgari haddine indir, fazlasını kes.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Devlet bütçesi korundu; elçiler tasarrufa alıştı."},{"label":"Cömertlik devletin şanındandır; tayinatı eksiltme.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Yabancı Elçilere Verilen \'Tayinat\' İsrafı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Yabancı Elçilere Verilen \'Tayinat\' İsrafı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Yabancı Elçilere Verilen \'Tayinat\' İsrafı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 153) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_154', 'ottoman', 'Göz Açtırmayan Tefecilik (Murabaha)', 'Şehir Kâhyalığı', 'Şehir sarraflarının yıllık %80 faizle esnafa borç verip dükkânlarını elinden aldığı kanıtlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Şer\'i riba sınırını %12\'ye bağla; aşanların senetlerini yırtıp paralarını müsadere et.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Tefecilik çarkı kırıldı; yüzlerce esnaf batmaktan kurtuldu."},{"label":"Borç alan razıdır; serbest sözleşmeye meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Göz Açtırmayan Tefecilik (Murabaha) hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Göz Açtırmayan Tefecilik (Murabaha) hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Göz Açtırmayan Tefecilik (Murabaha) gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 154) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_155', 'ottoman', 'Kaçak Tütün Kahvehaneleri', 'Dîvân-ı Maliye', 'Tütün vergisi konulduğundan beri kaçakçılar gizli mahzenlerde tütün kahvehaneleri açıp vergi kaçırıyor.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Tütün vergisini makul bir seviyeye çek, kaçakçılığı anlamsız kıl.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Kaçakçılık bitti; hazineye düzenli tütün geliri bağlandı."},{"label":"Zaptiye baskınlarını artır, yakalananları küreğe koy.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Kaçak Tütün Kahvehaneleri nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Kaçak Tütün Kahvehaneleri fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kaçak Tütün Kahvehaneleri meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 155) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_156', 'ottoman', 'Meyve Sebzede \'Kabzımal\' Komisyonu', 'İstanbul Çarşısı', 'Kente giren bostan mallarını toptan kapatan komisyoncular fiyatları suni olarak şişiriyor.', '[{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Kabzımal aracılarını kaldır; köylünün doğrudan pazarda satış yapmasını sağla.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Meyve sebze ucuzladı; köylü de şehirli de kazandı."},{"label":"Toptancı loncasının hakkıdır; pazara sokma.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Meyve Sebzede \'Kabzımal\' Komisyonu nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Meyve Sebzede \'Kabzımal\' Komisyonu fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Meyve Sebzede \'Kabzımal\' Komisyonu meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 156) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_157', 'ottoman', 'Tunus ve Trablus\'tan Ganimet Payı', 'Garp Ocakları', 'Garp ocakları beyleri ele geçirdikleri altınları hazineye yollamak yerine kendi saraylarını süslüyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Özel müfettiş ve donanma yolla; devletin \'humus\' (beşte bir) payını zorla al.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Korsan beyleri devlete boyun eğdi; kasa doldu."},{"label":"Çok uzaklardadır; arayı bozmamak için bağışla.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Tunus ve Trablus\'tan Ganimet Payı meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Tunus ve Trablus\'tan Ganimet Payı hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Tunus ve Trablus\'tan Ganimet Payı gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 157) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_158', 'ottoman', 'Katran ve Zift Tedarikinde Vurgun', 'Tersane Muhasebesi', 'Arnavutluk katranını donanmaya satan tüccarların faturayı üç kat gösterdiği belgelendi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Vurguncuları derdest et, tüm alacaklarını hazineye irat kaydet.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Tersane harcamaları temizlendi; yolsuzluk bitti."},{"label":"Gemi inşası durmasın; aradaki farkı tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Katran ve Zift Tedarikinde Vurgun nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Katran ve Zift Tedarikinde Vurgun fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Katran ve Zift Tedarikinde Vurgun meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 158) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_159', 'ottoman', 'Çürük Buğdayın Askere Dağıtılması', 'Sıvas Zahire Ambarı', 'Müteahhit, nem alıp küflenmiş buğdayı rüşvetle sınır kalelerindeki garnizonlara un olarak sattı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Müteahhidi ve rüşvetçi ambar memurunu as; temiz buğday tedarik et.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Askerin hakkı korundu; kalelerde salgın hastalık önlendi."},{"label":"Un kıtlığı vardır; ekmek yapılıp dağıtılsın.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Çürük Buğdayın Askere Dağıtılması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Çürük Buğdayın Askere Dağıtılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Çürük Buğdayın Askere Dağıtılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 159) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_160', 'ottoman', 'Yedek Akçe (Kenz-i Mahfî) Fonu', 'Başdefterdarlık', 'Defterdar, barış zamanında her yıl hazine gelirinin onda birinin kara gün için saklanmasını önerir.', '[{"id":"char_defterdar","name":"Defterdar"}]', '[{"label":"Ferman çıkar: Bu altınlara savaş ve kıtlık dışında asla dokunulmayacak.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Devlet ihtiyat sandığına kavuştu; mali krizlere zırh örüldü."},{"label":"Yatırım yapmayıp parayı sandığa gömmek ahmaklıktır; hepsini harca.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasadaki kırpık akçeleri darphanede saf gümüşle değiştir; Yedek Akçe (Kenz-i Mahfî) Fonu meselesinde sarraflara faizsiz ikraz verip sikke değerini ve alım gücünü koru.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sahte ve kırpık akçe basan kalpazanları bostancı müfrezesiyle bas; Yedek Akçe (Kenz-i Mahfî) Fonu meselesinde suç ortaklarını derhal zincire vurup zindana kapat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Darphane ve Meskûkât Kanunnâmesi\' neşret; Yedek Akçe (Kenz-i Mahfî) Fonu gibi hadiselerin tekerrürünü önleyecek şekilde akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 160) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_161', 'ottoman', 'Gürcü Atabeylerinin Sadakat İkilemi', 'Kafkas Serhattı', 'Gürcü beyleri, İran baskısına karşı Osmanlı koruması istiyor fakat yerel paşalar arazilerini ilhaka kalkışıyor.', '[{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"İç işlerinde serbestiyet tanıyan adil bir ahidnâme ver; paşaları dizginle.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Kafkasya kapıları ardına kadar açıldı; Gürcü süvarileri orduya katıldı."},{"label":"Zorla ilhak et, kalelerine doğrudan Osmanlı garnizonu sok.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Gürcü Atabeylerinin Sadakat İkilemi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Gürcü Atabeylerinin Sadakat İkilemi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gürcü Atabeylerinin Sadakat İkilemi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 161) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_162', 'ottoman', 'Kazak Şaykalarının Gece Baskınları', 'Tuna Boyu Palankaları', 'Kazaklar küçük nehir botlarıyla Tuna köylerini basıp ateşe veriyor; nehir kıyısı boşaldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tuna\'ya nehir karakolları ve gece fener kuleleri kurdur; piyadeleri tüfeklendir.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Kazak baskınları püskürtüldü; Tuna boyu köylüsü tarlasına döndü."},{"label":"Köylüler içeri kaçsın; nehir kenarında durmak tehlikelidir.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kazak Şaykalarının Gece Baskınları nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kazak Şaykalarının Gece Baskınları fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kazak Şaykalarının Gece Baskınları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 162) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_163', 'ottoman', 'Sana Kalesinde Askerin İsyanı', 'Yemen İmamlığı', 'Yemen sıcağında ve dağlık arazide yıllardır mahsur kalan askerler, terhis edilmedikleri için silah bıraktı.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Taze birlikler yolla, eski askeri terhis et ve Yemenlilere yerel muhtariyet tanı.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Yemen\'de kan durdu; askerin moral ve disiplini kurtarıldı."},{"label":"Geri dönmeye kalkanları kurşuna dizdir; mevzileri terk ettirme.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sana Kalesinde Askerin İsyanı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Sana Kalesinde Askerin İsyanı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Sana Kalesinde Askerin İsyanı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 163) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_164', 'ottoman', 'Evli Yeniçerilerin Kışlada Kalmama Talebi', 'Yeniçeri Ocağı', 'Esnaflık yapan ve evlenen yeniçeriler kışlayı terk edip evlerinde kalmak istiyor; talimler boşaldı.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Ocak kanunnamesini uygula: Asker sadece askerlikle meşgul olur; talime uymayanı at.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Ocağa çelik disiplin geri döndü; muharip güç tazelendi."},{"label":"Taleplerini kabul et; devir değişti, aile kurabilsinler.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Evli Yeniçerilerin Kışlada Kalmama Talebi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Evli Yeniçerilerin Kışlada Kalmama Talebi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Evli Yeniçerilerin Kışlada Kalmama Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 164) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_165', 'ottoman', 'Moskova Seferi İçin Süvari Desteği', 'Kırım Hanı Mektubu', 'Kırım Hanı sefere 50 bin atlıyla katılmak için peşin \'çizme bahşişi\' talep etmektedir.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Altını öde; Kırım süvarisi olmadan bozkırda düşman kuşatılamaz.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Kırım atlıları düşmanı bozkırda ezip geçti; büyük zafer kazanıldı."},{"label":"Han Osmanlı\'nın tabisidir; parasız sefere gelmek zorundadır.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Moskova Seferi İçin Süvari Desteği nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Moskova Seferi İçin Süvari Desteği fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Moskova Seferi İçin Süvari Desteği meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 165) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_166', 'ottoman', 'Zimmi Esirlerin İstihkâm İnşaatında Çalıştırılması', 'Belgrad Muhafızlığı', 'Belgrad tahkimatında esirlerin gece gündüz dinlenmeden, yemek verilmeden çalıştırıldığı bildirildi.', '[{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Günde sekiz saat sınır koy, yemek ve tıbbi bakım ver; zulüm mülkü yıkar.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"İstihkâm hızlandı; esir isyanları ve sabotajlar durdu."},{"label":"Düşman esiridir; ölene kadar surları yükseltsinler.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zimmi Esirlerin İstihkâm İnşaatında Çalıştırılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Zimmi Esirlerin İstihkâm İnşaatında Çalıştırılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Zimmi Esirlerin İstihkâm İnşaatında Çalıştırılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 166) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_167', 'ottoman', 'Venedik Kalyonunun İpek Yüküyle Batırılması', 'Ege Donanması', 'Barış zamanında bir Osmanlı kadırgası, zengin bir Venedik ticaret kalyonunu haksız yere batırıp mallarını paylaştı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Korsanlık yapan leventleri cezalandır; Venedik\'e tazminat ödeyip sulhü koru.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Devletin sözünün eri olduğu kanıtlandı; büyük bir harp önlendi."},{"label":"Ganimeti hazineye kat, \'Fırtınada battı\' de.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Venedik Kalyonunun İpek Yüküyle Batırılması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Venedik Kalyonunun İpek Yüküyle Batırılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Venedik Kalyonunun İpek Yüküyle Batırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 167) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_168', 'ottoman', 'Tüfek İmalatında Çelik Yetersizliği', 'Diyarbakır Cephaneliği', 'Şam çeliği gelmediği için dökülen tüfek namluları ateş ederken patlıyor ve askeri yaralıyor.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Namluları acilen toplat, kaliteli İsveç veya Şam çeliği gelene kadar üretimi durdur.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Askerin canı kurtarıldı; tüfeklere güven geri geldi."},{"label":"Üretimi durdurmayın; talimlerde az barut koysunlar.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Tüfek İmalatında Çelik Yetersizliği nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Tüfek İmalatında Çelik Yetersizliği fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Tüfek İmalatında Çelik Yetersizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 168) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_169', 'ottoman', 'Bedevi Aşiretlerinin Vergiye Karşı İsyanı', 'Bağdat Hududu', 'Muntafık aşireti nehir gemilerini basarak Basra yolunu kesti ve askerlerin geçişini engelledi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Aşiret reisleriyle çölde bizzat görüş; meşru haklarını tanı ve koruculuk maaşı bağla.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Çöl yolları sulhe kavuştu; aşiret sınır muhafızı oldu."},{"label":"Süvari alaylarını sal, develerini ve çadırlarını ateşe ver.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Bedevi Aşiretlerinin Vergiye Karşı İsyanı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Bedevi Aşiretlerinin Vergiye Karşı İsyanı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Bedevi Aşiretlerinin Vergiye Karşı İsyanı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 169) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_170', 'ottoman', 'Kuşatma Hendeklerinde Kar Suyu', 'Uyvar Kuşatması', 'Kuşatma altındaki kalede kış bastırdı. Hendeklerde diz boyu çamur ve donmuş su var.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Askerlere keçeli çadırlar, sıcak aş ve kürk yelekler yetiştir.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Asker dayanma gücü buldu; kale üç gün sonra teslim oldu."},{"label":"Hücum borusu çal; donarak ölmektense surlarda ölsünler.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kuşatma Hendeklerinde Kar Suyu nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kuşatma Hendeklerinde Kar Suyu fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kuşatma Hendeklerinde Kar Suyu meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 170) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_171', 'ottoman', 'Şövalyelerden Kalan Yeraltı Mahzenleri', 'Rodos Garnizonu', 'Kalede bulunan gizli şarap ve altın mahzeni yeniçeriler tarafından yağmalandı; kalede sarhoşluk ve anarşi var.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"İçkileri denize döktür, disiplini bozan neferleri derhal adadan sür.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Askeri terbiye ihya edildi; kale güvenliği sağlandı."},{"label":"Savaş yorgunudurlar; birkaç gün eğlenmelerine yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Şövalyelerden Kalan Yeraltı Mahzenleri nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Şövalyelerden Kalan Yeraltı Mahzenleri fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Şövalyelerden Kalan Yeraltı Mahzenleri meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 171) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_172', 'ottoman', 'Kışın Donan Nehir ve Sınır Tehdidi', 'Kars Kalesi', 'Arpaçay donduğu için düşman süvarileri buzun üzerinden sınırı kolayca aşıp köyleri vuruyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Buzları kırdır, sınır boyuna kızaklı nöbetçi devriyeleri çıkar.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Sınır köyleri korundu; düşman akını kırıldı."},{"label":"Köylüler Kars kalesinin içine sığınsın, nehre asker yollama.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kışın Donan Nehir ve Sınır Tehdidi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kışın Donan Nehir ve Sınır Tehdidi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kışın Donan Nehir ve Sınır Tehdidi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 172) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_173', 'ottoman', 'Kürek Mahkumu Forsaların İsyanı', 'Tersane Zindanı', 'Kadırgalarda yetersiz beslenen forsalar zincirlerini kırıp tersane ambarını ateşe verdi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Yangını söndür; forsaların günlük tayınını artır ve sağlık muayenesi getir.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Forsalar küreğe asıldı; donanma tam zamanında sefere çıktı."},{"label":"Hepsini idam et, yeni esirler topla.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Kürek Mahkumu Forsaların İsyanı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Kürek Mahkumu Forsaların İsyanı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kürek Mahkumu Forsaların İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 173) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_174', 'ottoman', 'Venedik Lağım Savaşları', 'Girit Serdarı', 'Hanya önlerinde düşman yerin altından lağımlar kazıp tabyalarımızın altına barut dolduruyor.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Madenci ve lağımcı ustalarını çağır, karşı lağım kazıp düşmanı yerin altında patlat.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Düşman lağımı çökertildi; tabyalarımız havaya uçmaktan kurtuldu."},{"label":"Tabyaları boşaltıp geri çekilin.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Venedik Lağım Savaşları nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Venedik Lağım Savaşları fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Venedik Lağım Savaşları meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 174) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_175', 'ottoman', 'İspanyol Donanmasının Cezayir\'i Bombalaması', 'Cezayir Beyi', 'İspanyol armadası Cezayir şehrini topa tutuyor; kalede barut ve gülle kalmadı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mısır ve payitahttan acil mühimmat filosu sevk et.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Cezayir kalesi direndi; İspanyol armadası püskürtüldü."},{"label":"Uzak denizdir; kendi imkânlarıyla savunsunlar.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; İspanyol Donanmasının Cezayir\'i Bombalaması hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; İspanyol Donanmasının Cezayir\'i Bombalaması hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; İspanyol Donanmasının Cezayir\'i Bombalaması gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 175) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_176', 'ottoman', 'Hain Kale Dizdarı Şüphesi', 'Vidin Kalesi', 'Vidin kale kumandanının Avusturya casuslarıyla mektuplaştığı ve kapıları açmaya hazırlandığı bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Gizli cellat gönder, dizdarı derdest edip sadık bir serhad gazisini tayin et.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"İhanet son anda engellendi; serhad kalelerimiz korundu."},{"label":"Açıkça mahkeme kurup delil bekle.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Hain Kale Dizdarı Şüphesi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Hain Kale Dizdarı Şüphesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Hain Kale Dizdarı Şüphesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 176) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_177', 'ottoman', 'Göl Üzerinde Lojistik Taşımacılık', 'Van Kalesi Muhafızı', 'İran seferinde karadan cephane taşımak aylar sürüyor; Van Gölü\'ne yelkenli gemiler yapılması önerildi.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Göl tersanesi kurdur, hafif nakliye gemileriyle lojistiği hızlandır.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Ordu cephaneye iki günde kavuştu; sınır tahkim edildi."},{"label":"Katır ve develerle taşımaya devam edin.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Göl Üzerinde Lojistik Taşımacılık nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Göl Üzerinde Lojistik Taşımacılık fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Göl Üzerinde Lojistik Taşımacılık meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 177) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_178', 'ottoman', 'Leh Kazaklarına Karşı Pusu', 'Hotin Seferi', 'Bataklık arazide düşman süvarileri ordumuzu çevirmek istiyor; tatar kılavuzlar gizli geçit biliyor.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Kılavuzlara itibar et, düşmanın arkasına dolanarak pusu kur.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Düşman ordusu gafil avlandı; parlak bir zafer kazanıldı."},{"label":"Yabancı kılavuza güvenilmez; ana yoldan taarruz et.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Leh Kazaklarına Karşı Pusu meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Leh Kazaklarına Karşı Pusu meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Leh Kazaklarına Karşı Pusu gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 178) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_179', 'ottoman', 'Yivli Namlu Tüfek Denemesi', 'Tophane Dökümhanesi', 'Bir döküm ustası, mermiyi döndürerek iki kat uzağa fırlatan yivli tüfek icat etti; orduya uygulanması bütçe istiyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Ustaya ihsan ver, ordu tüfeklerini süratle yivli hale getir.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Askeri teknolojide çağ atlandı; düşman menzilimize yaklaşamadı."},{"label":"Eski tüfekler gayet iyidir; gereksiz icatlara para yok.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Yivli Namlu Tüfek Denemesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Yivli Namlu Tüfek Denemesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Yivli Namlu Tüfek Denemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 179) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_180', 'ottoman', 'Gazi Dervişlerin İskânı', 'Serhad Boyları', 'Sınır boylarında tekkeler açıp hem toprağı işleyen hem gazaya katılan dervişler vergi muafiyeti talep eder.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tekkeleri onayla; onlara sınır topraklarını vakfet.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Sınırlar iman ve kılıçla tahkim edildi; fetihler kolaylaştı."},{"label":"Herkes vergi vermek zorundadır; muafiyet tanıma.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Gazi Dervişlerin İskânı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Gazi Dervişlerin İskânı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Gazi Dervişlerin İskânı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 180) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_181', 'ottoman', 'Hollanda İşgaline Karşı Yardım Feryadı', 'Aceh Sultanlığı (Sumatra)', 'Hint Okyanusu\'ndaki Müslüman Aceh Sultanı, sömürgecilere karşı top döküm ustaları ve donanma istiyor.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"Kalyonlar, topçular ve tüfek ustaları yolla; halifenin sancağını okyanusta dalgalandır.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Sumatra\'da sömürgeciler durduruldu; İslam dünyası halifeye şükran sundu."},{"label":"Uzak Asya ile uğraşamayız; elçiye altın verip uğurla.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Hollanda İşgaline Karşı Yardım Feryadı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Hollanda İşgaline Karşı Yardım Feryadı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Hollanda İşgaline Karşı Yardım Feryadı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 181) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_182', 'ottoman', 'Dilsiz ve Hadım Ağalarının Nüfuzu', 'Topkapı Enderun Kalemi', 'Saray ağaları, padişaha sunulan arzuhalleri sansürleyerek sadrazamdan bile daha güçlü hale geldi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Saray ağalarını siyasetten tamamen men et; sadrazam ve divanı tek muhatap kıl.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Saray vesayeti kırıldı; meşru bürokrasi nefes aldı."},{"label":"Ağalar sultanın en sadık bendeleridir; meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Dilsiz ve Hadım Ağalarının Nüfuzu nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Dilsiz ve Hadım Ağalarının Nüfuzu fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Dilsiz ve Hadım Ağalarının Nüfuzu meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 182) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_183', 'ottoman', 'Halkın Arzuhal Sunma Hakkı (Şikâyet Günü)', 'Bab-ı Hümayun', 'Cuma namazı çıkışında halkın bizzat padişahın atının önüne çıkıp dilekçe vermesi vezirlerce yasaklanmak isteniyor.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Asla yasaklanamaz! Hükümdarın kapısı tebaaya daima açıktır.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Mazlumlar dertlerini bizzat sultana sundu; zalim valiler titredi."},{"label":"Padişahın can güvenliği esastır; dilekçeleri divan kâtipleri alsın.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Halkın Arzuhal Sunma Hakkı (Şikâyet Günü) nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Halkın Arzuhal Sunma Hakkı (Şikâyet Günü) fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Halkın Arzuhal Sunma Hakkı (Şikâyet Günü) meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 183) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_184', 'ottoman', 'Daimi İkamet Elçilikleri Açılması', 'Viyana Sefareti', 'Reisülküttab, Avrupa başkentlerinde geçici heyetler yerine daimi sefaretler kurularak diplomasinin güçlendirilmesini önerdi.', '[{"id":"char_reisulkuttab","name":"Reisülküttab"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Londra, Paris ve Viyana\'da daimi sefaretler aç; lisan bilen diplomatlar yetiştir.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Avrupa diplomasisinde masaya oturuldu; tuzaklar önceden haber alındı."},{"label":"Biz cihan devletiyiz; onlar bizim ayağımıza gelsin.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Daimi İkamet Elçilikleri Açılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Daimi İkamet Elçilikleri Açılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Daimi İkamet Elçilikleri Açılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 184) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_185', 'ottoman', 'Hanım Sultan Düğünleri İsrafı', 'Harem Teşrifatı', 'Padişahın kız kardeşinin düğünü için 40 gün 40 gece şenlik yapılması ve halktan ek harç toplanması istendi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Şenliği sade tut; millet sıkıntıdayken düğün debdebesi yapılamaz.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Saray israfı önlendi; halk adil hükümdara dua etti."},{"label":"Cihan sultanının kızına layık bir düğün olsun; şenliği başlat.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Hanım Sultan Düğünleri İsrafı nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Hanım Sultan Düğünleri İsrafı fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Hanım Sultan Düğünleri İsrafı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 185) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_186', 'ottoman', 'Müslüman Diplomat Yetiştirilmesi', 'Bab-ı Âli Tercüme Odası', 'Dış yazışmaların sadece Fenerli Rum tercümanlara bırakılmasının devlet sırlarını tehlikeye attığı anlaşıldı.', '[{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Tercüme Odasını kur, Müslüman gençlere acilen Fransızca ve Latince öğrettir.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Milli diplomasi kadrosu kuruldu; sırlar dışarı sızmadı."},{"label":"Eski usul iyidir; tercümanlar asırlardır bize hizmet eder.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Müslüman Diplomat Yetiştirilmesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Müslüman Diplomat Yetiştirilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Müslüman Diplomat Yetiştirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 186) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_187', 'ottoman', 'Kardeş Katli Nizamı Tartışması', 'Şeyhülislam Fetvahanesi', 'Ulema, taht kavgalarını önleyen nizamın yerine en yaşlı ve aklı başında şehzadenin tahta geçmesini (ekber ve erşed) teklif etti.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Ekber ve erşed sistemine geç; taht kavgalarındaki masum kanı durdur.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Şehzade katliamları bitti; hanedan nizamı hukuki istikrara kavuştu."},{"label":"Kılıç hakkıdır; taht için en güçlü olan savaşarak çıksın.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kardeş Katli Nizamı Tartışması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kardeş Katli Nizamı Tartışması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kardeş Katli Nizamı Tartışması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 187) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_188', 'ottoman', 'Şam-Medine Telgraf ve Kervan Hattı', 'Hicaz Demiryolu Fikri', 'Mühendisler, kutsal topraklara hızlı ulaşım ve hacıların emniyeti için telgraf ve taş döşeli sürat yolu yapılmasını teklif eder.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"İslam alemini bağışa çağır ve projeyi bizzat padişah sermayesiyle başlat.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Hicaz ile payitaht bağlandı; hacılar çöl eşkıyasından kurtuldu."},{"label":"Çok maliyetlidir; hacılar kadim deve kervanlarıyla gitsin.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Şam-Medine Telgraf ve Kervan Hattı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Şam-Medine Telgraf ve Kervan Hattı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Şam-Medine Telgraf ve Kervan Hattı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 188) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_189', 'ottoman', 'Vezirlerin Servet Yarışı', 'Dîvân-ı Hümâyûn', 'Paşaların ve beylerin Boğaz kıyılarında birbiriyle yarışan devasa yalılar yapıp altın varaklı kayıklarla gezdiği görüldü.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Ferman neşret: Devlet ricali sadelikle örnektir! Fazla yalıları mektep ve darüşşifaya çevir.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Bürokraside kibir kırıldı; milletin devlete sevgisi tazelendi."},{"label":"Paşaların servetidir, istedikleri gibi harcasınlar.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Vezirlerin Servet Yarışı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Vezirlerin Servet Yarışı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Vezirlerin Servet Yarışı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 189) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_190', 'ottoman', 'Devlet Evrakının Tasnifi ve Hıfzı', 'Bab-ı Âli Arşivi', 'Asırlık mühimme ve tahrir defterlerinin nemli mahzenlerde çürüdüğü, fareler tarafından kemirildiği ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hazine-i Evrak (Devlet Arşivi) binası inşa ettir; defterleri tasnif ettirip korumaya al.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Devletin hafızası kurtarıldı; kadim haklar ve tapular güvenceye alındı."},{"label":"Eski kâğıtlara masraf yapmayın; sadece son on yılı saklayın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet Evrakının Tasnifi ve Hıfzı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Devlet Evrakının Tasnifi ve Hıfzı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Devlet Evrakının Tasnifi ve Hıfzı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 190) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_191', 'ottoman', 'Ortak Hac Protokolü Teklifi', 'İran Şahı Elçisi', 'Şah, Şii hacıların Mekke\'ye güvenle gidebilmesi için Bağdat-Şam yolunda ortak emniyet garnizonu kurulmasını teklif ediyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Hac ibadeti tüm Müslümanlara açıktır; emniyeti biz sağlarız, teklifi adaletle kabul et.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Mezhep çatışmaları dindi; İslam dünyasında sulh rüzgârı esti."},{"label":"Şiileri şüpheyle karşıla; hacca girişlerini zorlaştır.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Ortak Hac Protokolü Teklifi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Ortak Hac Protokolü Teklifi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ortak Hac Protokolü Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 191) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_192', 'ottoman', 'Kutsal Emanetlerin Muhafazası', 'Topkapı Sarayı Cephaneliği', 'Yavuz Sultan Selim\'in getirdiği emanetlerin sergilendiği Hırka-i Saadet dairesinin kubbesi su akıtıyor.', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Derhal başmimarı görevlendir; saf kurşun ve altınla kubbeyi ihya et.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Hilafet makamının manevi kalbi hürmetle korundu."},{"label":"Şimdilik altına leğen koyun; tamiri seneye bırakın.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kutsal Emanetlerin Muhafazası nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kutsal Emanetlerin Muhafazası fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kutsal Emanetlerin Muhafazası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 192) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_193', 'ottoman', 'Şeyhülislamın Siyasete Alet Edilmesi', 'Kazaskerlik Meclisi', 'Veziriazam, rakiplerini idam ettirmek için şeyhülislama zorla siyasi fetvalar verdirmeye çalışıyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Fetva makamını koru; şeyhülislama \'Yalnızca hakikati yaz\' diyerek veziri azlet.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Hukuk siyasetin kırbacı olmaktan kurtarıldı; adaletin izzeti korundu."},{"label":"Vezirin istediği fetvayı almasına yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şeyhülislamın Siyasete Alet Edilmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Şeyhülislamın Siyasete Alet Edilmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Şeyhülislamın Siyasete Alet Edilmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 193) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_194', 'ottoman', 'Dilekçe Sandıklarının Taşrada Kurulması', 'Bab-ı Âli Kapısı', 'Payitahta gelemeyen uzak vilayet ahalisi için her kaza merkezine \'Şikâyet ve Adalet Sandığı\' kurulması teklif edildi.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Anahtarı sadece padişah müfettişinde olan adalet sandıklarını kurdur.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Uzak köylünün sesi saraya ulaştı; yerel zalimler diz çöktü."},{"label":"Gereksiz masraftır; şikâyeti olan kadıya gitsin.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Dilekçe Sandıklarının Taşrada Kurulması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Dilekçe Sandıklarının Taşrada Kurulması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Dilekçe Sandıklarının Taşrada Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 194) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_195', 'ottoman', 'Babür İmparatorluğu ile İttifak', 'Hint Sultanlığı Elçisi', 'Babür Hükümdarı, İngiliz Doğu Hindistan Şirketi\'ne karşı Osmanlı ile donanma ve topçu ittifakı teklif etti.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"İttifakı imzala; Kızıldeniz ve Umman denizinde ortak filo kur.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"İki büyük Türk-İslam devleti birleşti; sömürgecilik geriletildi."},{"label":"Hindistan çok uzaktır; deniz aşırı maceralara girmeyelim.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Babür İmparatorluğu ile İttifak nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Babür İmparatorluğu ile İttifak fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Babür İmparatorluğu ile İttifak meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 195) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_196', 'ottoman', 'Yangın Tulumbaları Ocağının Kurulması', 'İstanbul Şehremaneti', 'Ahşap evlerden oluşan payitahtta her yangın binlerce aileyi evsiz bırakıyor; Tulumbacı Ocağı kurulması önerildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Bütçe ayır; mahallelere modern tulumba istasyonları ve nöbetçiler kurdur.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Büyük yangınlar önlendi; payitaht kül olmaktan kurtuldu."},{"label":"Yangın kaderdir; halk kendi kovalarıyla söndürsün.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Yangın Tulumbaları Ocağının Kurulması hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Yangın Tulumbaları Ocağının Kurulması hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Yangın Tulumbaları Ocağının Kurulması gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 196) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_197', 'ottoman', 'Padişahın Şahsi Kitaplığı ve Kütüphaneler', 'Harem-i Hümayun', 'Saray kütüphanesindeki nadide felsefe, astronomi ve tıp eserlerinin halka açık medreselere vakfedilmesi teklif edildi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Halk kütüphaneleri aç; ilim saray duvarları arasında kilitli kalamaz.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Toplum aydınlandı; ilim medreselerden halka taştı."},{"label":"Kitaplar hükümdarın şahsi mülküdür; kimseye verilmez.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Padişahın Şahsi Kitaplığı ve Kütüphaneler nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Padişahın Şahsi Kitaplığı ve Kütüphaneler fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Padişahın Şahsi Kitaplığı ve Kütüphaneler meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 197) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_198', 'ottoman', 'Sadrazamın Yetkilerinin Kanunla Çizilmesi', 'Sadaret Tezkiresi', 'Veziriazam, padişahın mührünü kötüye kullanarak kendi şahsi düşmanlarını sürgüne göndermektedir.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Mührü geri al; her sürgün ve idam kararı divanda açık oyla alınsın.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Sadrazam despotizmi yıkıldı; meclis meşvereti tesis edildi."},{"label":"Vekil-i mutlaktır; sadrazamın işine karışıp otoritesini sarsma.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Sadrazamın Yetkilerinin Kanunla Çizilmesi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Sadrazamın Yetkilerinin Kanunla Çizilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Sadrazamın Yetkilerinin Kanunla Çizilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 198) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_199', 'ottoman', 'Meşveret Meclisinin (Danışma Kurulu) Kurumsallaşması', 'Şeyhülislam ve Kazaskerler', 'Kritik savaş, vergi ve barış kararlarının padişahın tek dudağından değil, daimi bir Meşveret Meclisi\'nde alınması istendi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_kazasker","name":"Kazasker"}]', '[{"label":"\'İşlerinde onlarla istişare et\' emrine uy; Meşveret Meclisi\'ni kanunlaştır.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Hata yapma ihtimali en aza indi; devlet kolektif akılla yönetildi."},{"label":"Padişahın mutlak iradesine ortak kabul edilmez; reddet.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Meşveret Meclisinin (Danışma Kurulu) Kurumsallaşması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Meşveret Meclisinin (Danışma Kurulu) Kurumsallaşması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Meşveret Meclisinin (Danışma Kurulu) Kurumsallaşması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 199) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_200', 'ottoman', 'Kınalızâde\'nin Vasiyeti: Cihanşümul Denge', 'Dâire-i Adliyye Tacı', 'Saltanatının olgunluk çağında başvekil sorar: \'Hünkârım, mülkümüzü ebed-müddet kılacak nihai düstur nedir?\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"\'Adalet olmadan reaya, reaya olmadan mal, mal olmadan ordu, ordu olmadan devlet yaşamaz!\'.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Dâire-i Adliyye altın harflerle mülkün kalbine kazındı; nizam kemale erdi."},{"label":"\'Kuvvet ve kılıç her şeyin üstündedir; gerisi teferruattır.\'.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kınalızâde\'nin Vasiyeti: Cihanşümul Denge nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kınalızâde\'nin Vasiyeti: Cihanşümul Denge fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kınalızâde\'nin Vasiyeti: Cihanşümul Denge meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 200) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_201', 'ottoman', 'Komşu Duvarını Aşan Saçak Davası', 'Hassa Mimarları Dairesi', 'Zengin bir tüccar, konağının cumbasını sokağı tamamen kapatacak ve komşusunun güneşini kesecek şekilde inşa etti.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Mimar fermanını uygula: Fazlalık cumbayı yıktır, sokak nizamını koru.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Şehir hukuku korundu; fukaranın evine güneş girdi."},{"label":"Tüccardan yüklü bir imar harcı alıp cumbaya meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Komşu Duvarını Aşan Saçak Davası nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Komşu Duvarını Aşan Saçak Davası fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Komşu Duvarını Aşan Saçak Davası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 201) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_202', 'ottoman', 'Borçlu Esnafın \'Haps-i Medid\' Çilesi', 'İstanbul Kadılığı', 'İflas eden dürüst bir kumaşçının, alacaklı sarrafın baskısıyla yıllardır zindanda tutulduğu ve ailesinin aç kaldığı anlaşıldı.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Şeriat gereği aczini ispat eden borçluyu tahliye et, kefaletle çalışıp ödemesine izin ver.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Borçlu zindandan çıktı, çalışarak borcunu helaliyle ödedi."},{"label":"Alacaklının hakkıdır; borcu bitene kadar zindanda kalsın.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Borçlu Esnafın \'Haps-i Medid\' Çilesi hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Borçlu Esnafın \'Haps-i Medid\' Çilesi hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Borçlu Esnafın \'Haps-i Medid\' Çilesi gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 202) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_203', 'ottoman', 'Köy İmamının Çiftçiye Sahte Muska Satması', 'Taşra Teftişi', 'Bir köyde hırslı bir vaiz, kuraklığa karşı \'yağmur muskası\' satarak köylünün elindeki son kuzu ve zahireyi topladı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Müftülük eliyle sahtekârı azlet ve köylüye mallarını geri verdirt.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Dini istismar eden zorbaya geçit verilmedi; itikat korundu."},{"label":"Halkın inancına divan gözetiminde tarafları meşverete davet edip orta yolu bul; meseleyi köylünün rızasına bırak.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Köy İmamının Çiftçiye Sahte Muska Satması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Köy İmamının Çiftçiye Sahte Muska Satması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Köy İmamının Çiftçiye Sahte Muska Satması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 203) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_204', 'ottoman', 'Kadı Naibinin Çift Maaş Talebi', 'Kaza Defteri', 'Hem kaza naipliği hem de vakıf mütevelliliği yapan bir kâtip, her iki makamdan da tam maaş almak için araya hatırlı paşaları koydu.', '[{"id":"char_kadi_naibi","name":"Kadı Naibi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Tek makam, tek maaş kuralını işlet! Fazla görevi liyakatli bir başkasına ver.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Makam biriktirme açgözlülüğü önlendi; bütçe rahatladı."},{"label":"Paşaların ricasını kırma; çifte maaşa ferman yaz.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Kadı Naibinin Çift Maaş Talebi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Kadı Naibinin Çift Maaş Talebi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kadı Naibinin Çift Maaş Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 204) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_205', 'ottoman', 'Eşkıya İle Sulh Yapan Beylerbeyi', 'Sıvas Divanı', 'Beylerbeyi, dağdaki büyük Celâlî reisiyle gizli antlaşma yaparak ona paşalık rütbesi ve vergi toplama imtiyazı vadetti.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"},{"id":"char_beylerbeyi","name":"Beylerbeyi"}]', '[{"label":"Antlaşmayı derhal yırt! Eşkıyayla pazarlık devleti bitirir; orduyu sevk et.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Devletin izzeti korundu; eşkıya tepelenip sancak kurtarıldı."},{"label":"Savaş masrafından kaçın; eşkıya reisine paşalık hil\'ati gönder.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Eşkıya İle Sulh Yapan Beylerbeyi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Eşkıya İle Sulh Yapan Beylerbeyi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Eşkıya İle Sulh Yapan Beylerbeyi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 205) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_206', 'ottoman', 'Köpek Sürülerinin Mahalle Asayişi', 'Kaza Sicili', 'Payitaht sokaklarındaki sahipsiz köpeklerin geceleri yabancılara saldırdığı, esnafın ise mahalleyi hırsızdan korudukları için baktığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Köpekleri toplatıp sur dışındaki hususi barınaklara aldır ve hekim kontrolü sağla.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Sokaklar güvenli hale geldi; merhamet nizamı bozulmadı."},{"label":"Hepsini itlaf ettir veya denize döktür.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Köpek Sürülerinin Mahalle Asayişi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Köpek Sürülerinin Mahalle Asayişi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Köpek Sürülerinin Mahalle Asayişi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 206) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_207', 'ottoman', 'Patrikhaneler Arasında Çan Kavgası', 'Kudüs Sancağı', 'Kamame Kilisesi\'nde Latin ve Rum keşişler ayin sırası ve çan çalma hakkı yüzünden birbirine girdi, yaralananlar var.', '[{"id":"char_ortodoks_patriki","name":"Ortodoks Patriği"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Kadı huzurunda eski \'statükoyu\' tespit et; sırayı dakika şaşmadan zabıta eliyle denetlet.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Kutsal mekânda asayiş sağlandı; tarafsız adalet takdir topladı."},{"label":"En çok bağış yapan patrikhanenin lehine hüküm ver.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Patrikhaneler Arasında Çan Kavgası nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Patrikhaneler Arasında Çan Kavgası fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Patrikhaneler Arasında Çan Kavgası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 207) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_208', 'ottoman', 'İşkenceyle Alınan Hırsızlık İtirafı', 'Bab-ı Âli', 'Saray hazinesinden kürk çaldığı iddia edilen bir içoğlanın, dayak zoruyla suç ortağı olarak masum vezirleri gösterdiği anlaşıldı.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"İşkence altındaki ifadeyi delil sayma! Tahkikatı bağımsız kadılara devret.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"İftira ağı parçalandı; masum devlet ricali ipten kurtuldu."},{"label":"Soruşturmayı derinleştirme; çocuğun gösterdiği herkesi tutukla.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İşkenceyle Alınan Hırsızlık İtirafı meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; İşkenceyle Alınan Hırsızlık İtirafı hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; İşkenceyle Alınan Hırsızlık İtirafı gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 208) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_209', 'ottoman', 'Zimmiye \'Efendi\' Diye Hitap Eden Kâtip', 'Divan Meclisi', 'Mutaassıp bir grup, gayrimüslim bir sarrafa saygı unvanı olan \'çelebi\' veya \'efendi\' diyen resmi kâtibin cezalandırılmasını istiyor.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Şeriat tebaaya nezaketle muameleyi emreder; bağnazlığa pabuç bırakma.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Toplumsal barış korundu; gayrimüslim tüccar devlete bağlandı."},{"label":"Kâtibi azlet; mutaassıpların öfkesini teskin et.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Zimmiye \'Efendi\' Diye Hitap Eden Kâtip nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Zimmiye \'Efendi\' Diye Hitap Eden Kâtip fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Zimmiye \'Efendi\' Diye Hitap Eden Kâtip meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 209) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_210', 'ottoman', 'Evlilik Dışı Çocuğun Nafakası', 'Bursa Mahkemesi', 'Zengin bir beyin nikâhsız beraberlikten doğan bebeğini terk ettiği, annenin ise sefalet içinde nafaka davası açtığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Nesebi tescil ettir; babanın malından çocuğa ve anneye yüksek nafaka bağlat.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Masum bir can korundu; zengin zorbanın kibri kırıldı."},{"label":"Beyin ailesi muteberdir; davayı mahkemeden düşür.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Evlilik Dışı Çocuğun Nafakası nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Evlilik Dışı Çocuğun Nafakası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Evlilik Dışı Çocuğun Nafakası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 210) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_211', 'ottoman', 'Frenk Kaptanının Borç Davası', 'Galata Kadılığı', 'Marsilyalı bir gemici, yerli bir Müslüman tüccardan alacağını alamadığı için limandaki kadıya başvurdu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Dava haktır! Tüccarı çağır ve alacağı kuruşu kuruşuna tahsil edip Frenk\'e teslim et.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Osmanlı mahkemesinin tarafsız adaleti tüm Avrupa limanlarında övüldü."},{"label":"Kendi tebaanı yabancıya ezdirme; Frenk kaptanın davasını reddet.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Frenk Kaptanının Borç Davası davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Frenk Kaptanının Borç Davası davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Frenk Kaptanının Borç Davası gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 211) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_212', 'ottoman', 'Bozuk Süt Satan Mandıralar', 'İstanbul İhtisabı', 'Eyüp civarındaki mandıraların süte kireçli su karıştırarak çocukların zehirlenmesine sebep olduğu ortaya çıktı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Mandıraları derhal mühürle, sahiplerini küreğe mahkûm et ve ibret için afişe et.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Gıda terörü engellendi; annelerin duaları payitahtı sardı."},{"label":"Küçük bir para cezası kesip dükkânları açık bırak.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Bozuk Süt Satan Mandıralar nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Bozuk Süt Satan Mandıralar fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Bozuk Süt Satan Mandıralar meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 212) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_213', 'ottoman', 'Kayıkçı Loncasının Fahiş Ücreti', 'Üsküdar İskelesi', 'Boğaz\'da yolcu taşıyan kayıkçılar, fırtınalı havaları bahane ederek karşıya geçiş ücretini on katına çıkardı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Sıkı bir kayıkçı narhı koy; fahiş ücret isteyeni meslekten men et.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Halk Boğaz\'ı makul fiyata geçti; iskele zorbalığı bitti."},{"label":"Deniz tehlikelidir, kayıkçılar ne isterse alsın.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Kayıkçı Loncasının Fahiş Ücreti nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Kayıkçı Loncasının Fahiş Ücreti fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kayıkçı Loncasının Fahiş Ücreti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 213) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_214', 'ottoman', 'Kadı Sicillerinin Arşivlenmemesi', 'Kazaskerlik Kalemi', 'Birçok kazada kadıların tayinleri bittiğinde mahkeme defterlerini yanlarında götürdüğü veya sattığı anlaşıldı.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Ferman çıkar: Siciller kaza merkezinde kilitli kalacak, götüren vatan haini sayılacak.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Hukuki hafıza korundu; geçmiş davaların takibi mümkün oldu."},{"label":"Kadıların şahsi emeğidir; defterlerine divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadı Sicillerinin Arşivlenmemesi davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadı Sicillerinin Arşivlenmemesi davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadı Sicillerinin Arşivlenmemesi gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 214) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_215', 'ottoman', 'Müslüman Olan Zimminin Eski Borçları', 'Edirne Mahkemesi', 'İslam\'ı kabul eden bir tüccar, eski gayrimüslim ortaklarına olan borçlarının \'şeriat gereği sıfırlandığını\' iddia ediyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kul hakkı din değiştirse de baki kalır! Borcunu kuruşuna kadar ödet.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Dinin sahtekârlığa kalkan yapılması engellendi; ahlak korundu."},{"label":"İslam\'a yeni girmiştir, kalbi ısınsın diye borcunu affet.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Müslüman Olan Zimminin Eski Borçları nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Müslüman Olan Zimminin Eski Borçları fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Müslüman Olan Zimminin Eski Borçları meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 215) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_216', 'ottoman', 'Ayanların Köylüyü Mahkemeden Men Etmesi', 'Kaza Müfettişliği', 'Kütahya ayanı, konağının önüne silahlı adamlar dikerek köylülerin kadıya şikâyete gitmesini engelliyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Yeniçeri müfrezesi yolla; ayanın kapısındaki silahlı çeteyi dağıtıp ayanı divana çek.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Adalet kapısının önündeki barikat parçalandı; mazlum hakkını aradı."},{"label":"Ayan bölgenin vergisini toplamaktadır; arayı bozma.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Ayanların Köylüyü Mahkemeden Men Etmesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Ayanların Köylüyü Mahkemeden Men Etmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Ayanların Köylüyü Mahkemeden Men Etmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 216) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_217', 'ottoman', 'Yeniçerilerin Haraç Şebekesi', 'İstanbul Meyhaneleri', 'Galata meyhanelerini ve kahvelerini \'koruma\' bahanesiyle haraca bağlayan serkeş yeniçeriler yakalandı.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Yeniçeri Ağasına taviz verme; zorbaları derhal ocağın defterinden sil ve zindana at.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Payitaht esnafı zorbalardan kurtuldu; sokaklar sükunete erdi."},{"label":"Ocaklı kazan kaldırır; suçluları tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yeniçerilerin Haraç Şebekesi sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Yeniçerilerin Haraç Şebekesi meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Yeniçerilerin Haraç Şebekesi gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 217) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_218', 'ottoman', 'Yalancı Delille Boşanma Davası', 'Kaza Sicili', 'Zengin bir kocanın, mehir ödememek için hanımına iftira atarak şahitler kiraladığı ortaya çıktı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"İftirayı boşa çıkar, mehir bedelini iki kat tazminatla kadına ödet ve kocayı sürgün et.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Kadınların hukuki hakları korundu; iftiracı rezil oldu."},{"label":"Şahitlerin yalanı ispatlanamaz deyip kocanın lehine karar ver.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Yalancı Delille Boşanma Davası nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Yalancı Delille Boşanma Davası fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Yalancı Delille Boşanma Davası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 218) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_219', 'ottoman', 'Hristiyan Tüccara Faizsiz Borç Kumpası', 'Şam Valiliği', 'Bir grup eşraf, Hristiyan bir tüccarın borç senedini tahrif ederek iki katına çıkardı.', '[{"id":"char_sam_valisi","name":"Şam Valisi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Kâğıt ve mürekkep analizini yaptır; sahteciliği yapan eşrafı teşhir et.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Ahidnâmeye sadakat gösterildi; yabancı tüccarlar Şam\'a akın etti."},{"label":"Müslüman eşrafı gayrimüslimin önünde mahcup etme; saray erkânı ile divan arasında bir denge formülü bularak uzlaş.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Hristiyan Tüccara Faizsiz Borç Kumpası nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Hristiyan Tüccara Faizsiz Borç Kumpası fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hristiyan Tüccara Faizsiz Borç Kumpası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 219) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_220', 'ottoman', 'Adalet Dairesinin Taşra Duvarlarına Kazınması', 'Dîvân-ı Hümâyûn', 'Tüm kaza mahkemelerinin giriş kapısına Kınalızâde\'nin Adalet Dairesi beytinin mermere kazınması teklif edildi.', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Ferman ver: Her kadı kürsüsünün arkasında bu daire asılı dursun.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Hâkimler her hükümde adaletin çemberini hatırladı; nizam perçinlendi."},{"label":"Taşa yazı yazmakla adalet gelmez; masraf yapmayın.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Adalet Dairesinin Taşra Duvarlarına Kazınması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Adalet Dairesinin Taşra Duvarlarına Kazınması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Adalet Dairesinin Taşra Duvarlarına Kazınması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 220) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_221', 'ottoman', 'Mimar Sinan Su Kemerlerinin Tahribi', 'Hassa Mimarları', 'Kırkçeşme su kemerlerinin bentlerine yakın yerlerde çiftlik sahipleri kaçak kuyu açıp kentin suyunu azaltıyor.', '[{"id":"char_mimar_sinan","name":"Mimar Sinan"},{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"}]', '[{"label":"Kaçak kuyuları derhal kapattır ve su yollarını askeri muhafaza altına al.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Payitahtın su şebekesi kurtarıldı; çeşmeler gürül gürül aktı."},{"label":"Çiftlik sahipleri hatırlı beylerdir; yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Mimar Sinan Su Kemerlerinin Tahribi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Mimar Sinan Su Kemerlerinin Tahribi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Mimar Sinan Su Kemerlerinin Tahribi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 221) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_222', 'ottoman', 'Büyük \'Küçük Kıyamet\' Depremi', 'İstanbul Şehremaneti', 'Şiddetli bir zelzele surları yıktı, yüzlerce cami ve binlerce hane çöktü. Halk sokakta barınıyor.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Hazineyi aç; evsiz kalanlara çadır, çorba ve kereste dağıtıp şehri hızla imar et.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Devlet tebaasını felakette bağrına bastı; payitaht küllerinden doğdu."},{"label":"Sadece saray ve surları tamir ettir; halk kendi başının çaresine baksın.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gasp edilen zeytinlik ve dükkân gelirlerini geçmişe dönük faiziyle tahsil et; vakıf bütçesini mütevelli denetimine al ve Büyük \'Küçük Kıyamet\' Depremi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hayrat ve vakıf malına el uzatan yerel ayânları saray çavuşlarıyla yakalat; gasbettikleri mülkleri zorla geri alıp kendilerini hapse at ve Büyük \'Küçük Kıyamet\' Depremi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Büyük \'Küçük Kıyamet\' Depremi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 222) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_223', 'ottoman', 'Tunca ve Meriç Nehirlerinin Taşması', 'Edirne Sel Felaketi', 'Nehirler taştı; köprüler yıkıldı, un ambarları sular altında kaldı. Sel felaketi Edirne\'yi tecrit etti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ordu kayıklarını ve istihkâmcılarını yolla, mahsurları kurtar ve bendleri onar.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Edirne halkı selden kurtarıldı; askerin gayreti takdir topladı."},{"label":"Sular çekilene kadar bekle; masrafa girme.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Tunca ve Meriç Nehirlerinin Taşması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Tunca ve Meriç Nehirlerinin Taşması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Tunca ve Meriç Nehirlerinin Taşması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 223) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_224', 'ottoman', 'Darüşşifada İlaç ve Hekim Yetersizliği', 'Vakıf Mütevelliliği', 'Fatih Darüşşifası\'nın vakıf gelirleri enflasyon yüzünden eridi; hastalara et suyu ve şurup verilemiyor.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Hazine-i Âmire\'den ek tahsisat bağla; ilaç ve tabip kadrosunu takviye et.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Hastalar şifa buldu; vakıf medeniyeti ayakta tutuldu."},{"label":"Hastalardan giriş harcı alarak kendi bütçesini çıkarsın.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Darüşşifada İlaç ve Hekim Yetersizliği nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Darüşşifada İlaç ve Hekim Yetersizliği fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Darüşşifada İlaç ve Hekim Yetersizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 224) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_225', 'ottoman', 'Marmara\'da Deniz Fenerleri Ağı', 'Anadolu İskelesi', 'Karanlık gecelerde kayalıklara çarpan ticaret gemilerinin batmasını önlemek için fener kuleleri inşası önerildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kandilli ve Ahırkapı\'ya modern fenerler inşa ettir; deniz yolunu aydınlat.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Gemi kazaları sıfıra indi; Marmara ticareti gece de aktı."},{"label":"Gemiciler tecrübelidir; fener dikmek lüzumsuz masraftır.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 225) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_226', 'ottoman', 'Tarihi Taş Köprünün Yıkılması', 'Kayseri Sancağı', 'İpek Yolu üzerindeki ana nehir köprüsü bahar taşkınında çöktü; kervanlar haftalardır karşıya geçemiyor.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Mimarları derhal sevk et; sağlam kemerli yeni bir köprü kur.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Ulaşım açıldı; Anadolu ticareti canlandı."},{"label":"Tüccarlar sığ yerlerden salla geçsin; bütçe ayırma.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tarihi Taş Köprünün Yıkılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Tarihi Taş Köprünün Yıkılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Tarihi Taş Köprünün Yıkılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 226) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_227', 'ottoman', 'Boğaziçi Korularının İşgali', 'Hassa Bostancıbaşılığı', 'Bazı vezirlerin devlet koruluklarını telle çevirip özel köşkler kurduğu ve asırlık çınarları kestiği görüldü.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_bostancibasi","name":"Bostancıbaşı"}]', '[{"label":"Bütün kaçak köşkleri yıktır, ağaç kesen vezirlere ağır para cezası kes.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Kamu arazisi korundu; devletin yeşili ranta kurban edilmedi."},{"label":"Vezirleri kırma; araziyi onlara tapula.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Boğaziçi Korularının İşgali nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Boğaziçi Korularının İşgali fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Boğaziçi Korularının İşgali meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 227) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_228', 'ottoman', 'İmam-ı Azam Türbesi ve Külliyesi Tamiri', 'Bağdat İmarı', 'Savaşlarda hasar gören Ebu Hanife türbesinin kubbesi çatladı; tamiri için Ehl-i Sünnet ahali istirham ediyor.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hassa mimarlarını gönder; türbeyi ve medreseyi en mükemmel şekilde ihya et.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Irak ahalisinin devlete muhabbeti perçinlendi; manevi vakar korundu."},{"label":"Uzak vilayettir; yerel halk kendi aralarında para toplasın.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve İmam-ı Azam Türbesi ve Külliyesi Tamiri nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve İmam-ı Azam Türbesi ve Külliyesi Tamiri fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve İmam-ı Azam Türbesi ve Külliyesi Tamiri meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 228) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_229', 'ottoman', 'Medreselerde Isınma Odunu Krizi', 'Sıvas Vilayeti', 'Kış erken bastırdı; medreselerde odun kalmadığı için talebeler dersleri bırakıp battaniyeler altında titriyor.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Orman idaresinden derhal bedelsiz odun konvoyu çıkar; talebeyi üşütme.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Talebeler derslerine döndü; ilim yuvaları sıcacık tüttü."},{"label":"Talebeler tatil edilsin, memleketlerine dönsünler.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Medreselerde Isınma Odunu Krizi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Medreselerde Isınma Odunu Krizi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Medreselerde Isınma Odunu Krizi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 229) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_230', 'ottoman', 'Taş Fırınların Bacalarından Çıkan Yangınlar', 'İstanbul Fırınları', 'Şehir içindeki ahşap binalara bitişik fırın bacalarının kıvılcım saçtığı, her an yangın riski taşıdığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Fırın bacalarına tuğla ve kireç zorunluluğu koy, uymayanı derhal kapattır.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Yangın riski önlendi; mahalleler emniyete kavuştu."},{"label":"Ekmek üretimi aksar; fırıncılara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Taş Fırınların Bacalarından Çıkan Yangınlar nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Taş Fırınların Bacalarından Çıkan Yangınlar fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Taş Fırınların Bacalarından Çıkan Yangınlar meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 230) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_231', 'ottoman', 'Mescid-i Aksa Su Sarnıçlarının Temizliği', 'Kudüs Şehremaneti', 'Kutsal Harem\'in altındaki asırlık sarnıçlar çamurla doldu; hac mevsiminde su yetersizliği riski var.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"İstihkâm ve su yolcularını sevk et; sarnıçları pırıl pırıl temizlet.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Hacılar bol ve tatlı suya kavuştu; hayır duaları yükseldi."},{"label":"Masraflıdır; sadece yüzeydeki havuzları doldurun.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Mescid-i Aksa Su Sarnıçlarının Temizliği nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Mescid-i Aksa Su Sarnıçlarının Temizliği fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Mescid-i Aksa Su Sarnıçlarının Temizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 231) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_232', 'ottoman', 'Dalgakıran İnşası ve Karadeniz Fırtınaları', 'Trabzon Limanı', 'Kuzey rüzgârları limandaki tekneleri parçalıyor; tüccarlar taş dolgu büyük bir dalgakıran istiyor.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Kamu kaynaklarıyla dalgakıranı inşa ettir; Karadeniz ticaretini koru.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Trabzon emin bir liman oldu; gemiler güvenle yanaştı."},{"label":"Tüccarlar gemilerini kışın karaya çeksin; bütçe yok.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dalgakıran İnşası ve Karadeniz Fırtınaları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Dalgakıran İnşası ve Karadeniz Fırtınaları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Dalgakıran İnşası ve Karadeniz Fırtınaları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 232) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_233', 'ottoman', 'Kuş Evleri ve Sokak Hayvanları Vakfı', 'Vakıflar İdaresi', 'Cami duvarlarına serçeler için taştan saraylar yapılması ve kışın dağlara et bırakılması için vakıf kurulması teklif edildi.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Vakfı onayla ve bütçe bağla; merhamet etmeyene merhamet olunmaz.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Medeniyetin zarafeti dünyaya örnek oldu; tabiat şenlendi."},{"label":"İnsanlar dururken kuşa kurda para harcanmaz; reddet.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 233) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_234', 'ottoman', 'Yeraltı Kehriz Kanallarının Çökmesi', 'Konya Ovası', 'Selçuklulardan kalan yeraltı su kehrizleri göçtü; onlarca köy susuzluktan tarlasını terk ediyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Madenci ve kuyu ustalarını seferber et, kehrizleri yenile.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Yeraltı suları yeniden fışkırdı; kurak köyler yeşerdi."},{"label":"Köylüler kendi kuyusunu kazsın; devlet divan gözetiminde tarafları meşverete davet edip orta yolu bulz.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Yeraltı Kehriz Kanallarının Çökmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Yeraltı Kehriz Kanallarının Çökmesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Yeraltı Kehriz Kanallarının Çökmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 234) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_235', 'ottoman', 'Kanalizasyon ve Lağım Patlaması', 'İstanbul Şehremaneti', 'Fatih semtindeki ana lağım mecrası tıkandı; pis sular sokaklara ve cami avlularına taştı.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Derhal taş ve kurşun borularla yeni bir kanalizasyon hattı döşet.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Salgın tehlikesi önlendi; sokaklar tertemiz oldu."},{"label":"Sadece tıkanan yeri toprakla kapatıp geçin.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kanalizasyon ve Lağım Patlaması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kanalizasyon ve Lağım Patlaması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kanalizasyon ve Lağım Patlaması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 235) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_236', 'ottoman', 'Depremde Yıkılan Kale Surları', 'Halep Kalesi', 'Büyük Suriye depreminde Halep kalesinin ana burçları yarıldı; sınır savunması zaafa uğradı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tersane ve istihkâm bütçesinden ödenek çıkar; kaleyi çelik gibi tahkim et.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Sınır kapısı kilitlendi; düşman cesaret bulamadı."},{"label":"Surların tamirini seneye bırak; bütçe yetersiz.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Depremde Yıkılan Kale Surları nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Depremde Yıkılan Kale Surları fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Depremde Yıkılan Kale Surları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 236) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_237', 'ottoman', 'Şifalı Ilıcaların Özelleştirilmesi', 'Bursa Kaplıcaları', 'Zengin bir sarraf, halka açık şifalı kaplıcaları kiralayıp yüksek giriş ücreti koymak istiyor.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Reddet! Şifalı sular umumun malıdır, vakıf statüsünde ücretsiz kalsın.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Halk kaplıcalardan şifa bulmaya devam etti; kamu hakkı korundu."},{"label":"Yüksek kira bedeli karşılığı sarrafa iltizamla devret.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tağşiş edilen paraları piyasadan toplatıp hazine kasasında saf külçeye dönüştür; sikke istikrarını devlet garantisine al ve Şifalı Ilıcaların Özelleştirilmesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Piyasanın gümüşünü eriten sarrafları Divan-ı Hümâyûn huzurunda isticvap et; tağşiş çetelerini derhal küreğe mahkûm eyle ve Şifalı Ilıcaların Özelleştirilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Darphane ve Meskûkât Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Şifalı Ilıcaların Özelleştirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 237) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_238', 'ottoman', 'Gümrük Antrepolarının Genişletilmesi', 'İzmir Kordonu', 'Liman dar geldiği için mallar yağmur altında çürüyor; yeni kâgir antrepolar yapılması şart oldu.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Modern antrepolar inşa ettir ve yangına dayanıklı kilitli depolar kur.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Mallar korundu; gümrük gelirleri hızla arttı."},{"label":"Tüccarlar mallarını kendi brandalarıyla korusun.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gümrük Antrepolarının Genişletilmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gümrük Antrepolarının Genişletilmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gümrük Antrepolarının Genişletilmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 238) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_239', 'ottoman', 'Mostar Köprüsü\'nün Ayaklarında Çatlak', 'Mostar Şehri', 'Neretva nehrinin deli suları Mimar Hayreddin\'in köprüsünün kilit taşlarını oynatmaya başladı.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Başmimar kalfalarını Bosna\'ya yolla; kilit taşlarını kurşunla kaynattır.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Sanat abidesi kurtarıldı; Mostar\'ın iki yakası birbirine bağlı kaldı."},{"label":"Köprü sağlamdır, masrafa lüzum yok.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Mostar Köprüsü\'nün Ayaklarında Çatlak nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Mostar Köprüsü\'nün Ayaklarında Çatlak fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Mostar Köprüsü\'nün Ayaklarında Çatlak meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 239) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_240', 'ottoman', 'Kütüphanelerdeki El Yazması Eserlerin Rutubeti', 'Vakıf Defteri', 'Süleymaniye Kütüphanesi\'ndeki nadide tıp ve hendese kitaplarının rutubetten küflendiği bildirildi.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Hususi havalandırmalı dolaplar yaptır ve mücellitler tutarak eserleri kurtar.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"İslam medeniyetinin ilmi mirası korundu; kütüphaneler ihya edildi."},{"label":"Eski kitaplara bütçe ayrılmaz; sadece havalandırın.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kütüphanelerdeki El Yazması Eserlerin Rutubeti nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kütüphanelerdeki El Yazması Eserlerin Rutubeti fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kütüphanelerdeki El Yazması Eserlerin Rutubeti meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 240) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_241', 'ottoman', 'İpek İhracatında Sahte Gümrük Mührü', 'İskenderun Limanı', 'Avrupalı tüccarların sahte mühürlerle tonlarca ham ipeği gümrüksüz gemilere yüklediği yakalandı.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Gemilere ve yüke derhal el koy, kaçakçı tüccarları ve rüşvetçi memurları as.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Gümrük kaçağı bıçak gibi kesildi; hazine büyük gelire kavuştu."},{"label":"Avrupa ile diplomatik kriz çıkmasın; malları ceza kesip bırak.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İpek İhracatında Sahte Gümrük Mührü meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İpek İhracatında Sahte Gümrük Mührü meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İpek İhracatında Sahte Gümrük Mührü gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 241) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_242', 'ottoman', 'Piyasadan Altın Paranın Kaybolması', 'Payitaht Sarrafları', 'Tüccarların altın sikkeleri eritip külçe halinde Avrupa\'ya kaçırdığı, piyasada sadece bakır pul kaldığı görüldü.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Sınır kapılarında külçe altın aramasını sıkılaştır; kaçıranın kellesini al.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Milli servetin dışarı sızması önlendi; altın piyasaya döndü."},{"label":"Serbest piyasadır; altının dolaşımına sınır koyma.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Piyasadan Altın Paranın Kaybolması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Piyasadan Altın Paranın Kaybolması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Piyasadan Altın Paranın Kaybolması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 242) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_243', 'ottoman', 'Hindistan\'dan Gelen Baharat Gemileri', 'Basra Gümrüğü', 'Gucerat tüccarları doğrudan Basra yerine İran limanlarına gitmekle tehdit edip gümrük indirimi istiyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Makul bir gümrük indirimi yap ve Basra antrepolarını tüccara ücretsiz tahsis et.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Kervanlar Basra\'ya aktı; doğu ticareti canlandı."},{"label":"Taviz yok! Kanun neyse tam gümrük alınsın.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Hindistan\'dan Gelen Baharat Gemileri nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Hindistan\'dan Gelen Baharat Gemileri fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hindistan\'dan Gelen Baharat Gemileri meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 243) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_244', 'ottoman', 'Devlet Memurlarına Bahşiş Yasağı', 'Defterdarlık Kalemi', 'Vatandaşların işlerini gördürmek için kâtiplere \'kalamiye\' ve \'ikramiye\' adı altında rüşvet vermesi olağanlaştı.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Bütün kalemlere ferman as: Bahşiş alan da veren de mel\'undur! Şiddetle cezalandır.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Bürokratik çark temizlendi; halk devlet dairelerine korkusuzca girdi."},{"label":"Kâtiplerin maaşı azdır; küçük ikramiyelerden zarar gelmez.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet Memurlarına Bahşiş Yasağı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Devlet Memurlarına Bahşiş Yasağı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Devlet Memurlarına Bahşiş Yasağı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 244) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_245', 'ottoman', 'Çerkes Köle Ticaretinin Vergilendirilmesi', 'Trabzon Gümrüğü', 'Kafkasya\'dan kaçak getirilen köle ve esirlerin gümrüksüz satıldığı ihbar edildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Esir pazarını sıkı denetime al; hür insanları köleleştirenleri idam et.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"İnsan kaçakçılığı engellendi; şer\'i kölelik hukuku dışına çıkılmadı."},{"label":"Vergisini alıp kim olduklarına bakmayın.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Çerkes Köle Ticaretinin Vergilendirilmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Çerkes Köle Ticaretinin Vergilendirilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Çerkes Köle Ticaretinin Vergilendirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 245) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_246', 'ottoman', 'Gala Buğdayı Yerine Çavdar Karıştırılması', 'İstanbul Fırınları', 'Akdeniz\'den ithal buğday gelmeyince ekmek simsarları una küflü arpa ve çavdar karıştırdı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kırım ambarlarından buğday sevk et ve hileli un yapanları teşhir et.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Halkın ekmeği kurtarıldı; fırın simsarları sindirildi."},{"label":"Zor günlerdir; halk biraz da siyah ekmek yesin.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Gala Buğdayı Yerine Çavdar Karıştırılması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Gala Buğdayı Yerine Çavdar Karıştırılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Gala Buğdayı Yerine Çavdar Karıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 246) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_247', 'ottoman', 'Habeşistan Kahve Tekeli', 'Kahire Pazarı', 'Kızıldeniz\'den gelen kahveyi kapatan tüccarlar, fiyatları dört katına çıkarıp kahvehaneleri kilitledi.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kahve depolarını mühürle, makul narh fiyatıyla piyasaya zorla sürdür.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Karaborsa kırıldı; kahvehanelerde sohbet ve nizam tazelendi."},{"label":"Kahve zaruri gıda değildir; fiyatına divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Habeşistan Kahve Tekeli sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Habeşistan Kahve Tekeli hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Habeşistan Kahve Tekeli gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 247) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_248', 'ottoman', 'Tütün Yapraklarının Denize Dökülmesi', 'Selanik Rıhtımı', 'Makedonya tütününe konan aşırı ihracat resmini protesto eden köylüler tütün çuvallarını denize döktü.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Vergiyi makul seviyeye çek, üretici köylüyü dinle ve ziyanı kısmen tazmin et.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Köylü ile devlet barıştı; tütün ekimi hızla arttı."},{"label":"Elebaşıları zindana at, geri kalan tütünü müsadere et.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Tütün Yapraklarının Denize Dökülmesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Tütün Yapraklarının Denize Dökülmesi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Tütün Yapraklarının Denize Dökülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 248) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_249', 'ottoman', 'Bakır Kuruşların Kolay Taklit Edilmesi', 'Darbhane Kalemi', 'Dökülen yeni bakır sikkelerin çok basit olduğu ve sokaklarda sahtelerinin basıldığı bildirildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Darphaneye su gücüyle çalışan modern baskı makineleri kurdur; sikkeleri kenarlı bas.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Sikke taklidi imkânsız hale geldi; para emniyete kavuştu."},{"label":"Mevcut kalıplarla devam edin; yeni makine çok pahalı.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Bakır Kuruşların Kolay Taklit Edilmesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Bakır Kuruşların Kolay Taklit Edilmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Bakır Kuruşların Kolay Taklit Edilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 249) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_250', 'ottoman', 'Gümrük Kaçakçısı Rum Kaptanlar', 'Ege Adaları', 'Ege adalarındaki kaptanların İngiliz kumaşlarını adalara saklayıp geceleri kıyıya kaçırdığı tespit edildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Kadırgalarla sahil devriyesini iki katına çıkar, kaçakçı tekneleri batır.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Kaçakçılık rotası kesildi; yerli kumaş üreticisi rahatladı."},{"label":"Deniz geniştir, takip edemeyiz; tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gümrük Kaçakçısı Rum Kaptanlar davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Gümrük Kaçakçısı Rum Kaptanlar davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Gümrük Kaçakçısı Rum Kaptanlar gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 250) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_251', 'ottoman', 'Posta (Ulak) Atlarının Telef Olması', 'Anadolu İpek Yolu', 'Menzilhanelerdeki ulak atları aşırı koşturulmaktan ve bakımsızlıktan çatlayıp ölüyor; devlet haberleşmesi durdu.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Menzil bütçesini artır, her menzile veteriner hekim ve yedek at tahsis et.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Devlet haberleşmesi yıldırım gibi hızlandı; fermanlar vaktinde ulaştı."},{"label":"Köylünün binek atlarına bedelsiz el koyup menzile çekin.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Posta (Ulak) Atlarının Telef Olması nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Posta (Ulak) Atlarının Telef Olması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Posta (Ulak) Atlarının Telef Olması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 251) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_252', 'ottoman', 'Halat ve Zift Bedellerinin Esnafa Ödenmemesi', 'Tersane-i Âmire', 'Devlet, donanma için aldığı halat ve ziftin parasını iki yıldır ödemedi; tersane esnafı iflas bayrağını çekti.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hazine açığını göze al; esnafın birikmiş alacaklarını derhal öde.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Tersane esnafı kurtuldu; gemi imalatı şevkle devam etti."},{"label":"Devlete hizmettir; sabretsinler, ödemeyi seneye ertele.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Halat ve Zift Bedellerinin Esnafa Ödenmemesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Halat ve Zift Bedellerinin Esnafa Ödenmemesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Halat ve Zift Bedellerinin Esnafa Ödenmemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 252) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_253', 'ottoman', 'İran Şahının İpek Yolu Ambargosu', 'Halep Çarşısı', 'Safevi Şahı ham ipek yüklü kervanların Osmanlı topraklarına girişini yasakladı; Halep tezgâhları sustu.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Bursa ve Akdeniz\'de yerli ipekböcekçiliğine devasa teşvik ver; dışa bağımlılığı kır.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Yerli ipek üretimi patladı; Şah\'ın ambargosu boşa çıktı."},{"label":"Şah\'a taviz vererek ipek geçişini yalvar yakar açtır.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İran Şahının İpek Yolu Ambargosu meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İran Şahının İpek Yolu Ambargosu meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İran Şahının İpek Yolu Ambargosu gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 253) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_254', 'ottoman', 'Kış Ortasında Odun Kıtlığı', 'Payitaht Şehremaneti', 'Marmara\'da donan deniz yüzünden Karadeniz\'den odun gemileri gelemedi; payitaht buz kesti.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sarayın odun depolarını halka aç, ordu arabalarıyla mahallelere ücretsiz dağıt.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Fukara donmaktan kurtuldu; padişaha dualar edildi."},{"label":"Serbest piyasadır; kim yüksek para verirse ona satılsın.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kış Ortasında Odun Kıtlığı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kış Ortasında Odun Kıtlığı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kış Ortasında Odun Kıtlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 254) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_255', 'ottoman', 'Yabancı Tüccarlara Gayrimenkul Satışı', 'Galata Sarrafları', 'Venedik ve Felemenk tüccarlar liman çevresindeki hanları ve arazileri satın almak için dev servetler teklif ediyor.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kanun-ı Kadîm açıktır: Yabancıya mülk satılamaz, sadece kiralama izni ver.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Vatan toprağının egemenliği korundu; yabancı kolonileşme önlendi."},{"label":"Altın peşindir; arazileri istedikleri gibi satsınlar.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Yabancı Tüccarlara Gayrimenkul Satışı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Yabancı Tüccarlara Gayrimenkul Satışı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yabancı Tüccarlara Gayrimenkul Satışı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 255) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_256', 'ottoman', 'Devlet Ambarlarındaki Tahılın Çalınması', 'Sıvas Zahire Defteri', 'Kıtlık için saklanan yüzlerce ton buğdayın ambar memurlarınca gizlice tüccarlara satıldığı anlaşıldı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Memurları ve vurguncu tüccarları as, çalınan buğdayı ambarlara geri koy.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Halkın kara gün akçesi kurtarıldı; hırsızlık cezasız kalmadı."},{"label":"Olayı büyütmeyin; memurları görevden almakla yetinin.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Devlet Ambarlarındaki Tahılın Çalınması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Devlet Ambarlarındaki Tahılın Çalınması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Devlet Ambarlarındaki Tahılın Çalınması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 256) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_257', 'ottoman', 'Zeytinyağı İhracatında Hileli Karışım', 'İzmir Gümrüğü', 'İhraç edilen zeytinyağlarına pamuk yağı karıştırıldığı için Avrupa limanlarında tüm Osmanlı yağları boykot edildi.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sıkı bir damga ve tahlil nizamnamesi koy; tağşiş yapan ihracatçıyı men et.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Osmanlı malının uluslararası itibarı kurtarıldı; ihracat katlandı."},{"label":"Tüccarın kendi bileceği iştir; devlete vergisini versin yeter.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Zeytinyağı İhracatında Hileli Karışım nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Zeytinyağı İhracatında Hileli Karışım fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Zeytinyağı İhracatında Hileli Karışım meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 257) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_258', 'ottoman', 'Düğün ve Sünnet Harçları İsyanı', 'Taşra Maliyesi', 'Mali darlık bahanesiyle halkın evliliklerinden \'gerdek resmi\' ve çocuk sünnetlerinden harç alınması kararlaştırıldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bu çirkin harcı derhal iptal et! Ailenin mahremiyetine vergi konulamaz.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Halk üzerindeki ahlaksız mali baskı kalktı; devlete sevgi tazelendi."},{"label":"Hazineye para lazımdır; harcı zorla tahsil et.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Düğün ve Sünnet Harçları İsyanı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Düğün ve Sünnet Harçları İsyanı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Düğün ve Sünnet Harçları İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 258) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_259', 'ottoman', 'Kuru Üzüm Monopolü', 'Mora İskelesi', 'Birkaç tefeci konsorsiyumu Mora\'nın meşhur çekirdeksiz üzümlerini tarlada ucuza kapatıp Londra\'ya fahiş kârla satıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tefeci tekeline müdahale et; üretici köylüye doğrudan ihracat izni ve kredi ver.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Köylü zenginleşti; bağlar bayındır hale geldi."},{"label":"Konsorsiyumun kârına ortak ol, köylüyü kendi haline bırak.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kuru Üzüm Monopolü hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Kuru Üzüm Monopolü hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Kuru Üzüm Monopolü gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 259) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_260', 'ottoman', 'Yabancı Madeni Paraların Dolaşımının Yasaklanması', 'Dîvân-ı Hümâyûn', 'Ülkedeki yabancı altın ve gümüşlerin toplatılıp tamamen Osmanlı sikkesine dönüştürülmesi teklif edildi.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Milli sikkeyi tek geçerli akçe kıl; darphaneleri gece gündüz çalıştır.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"İktisadi bağımsızlık perçinlendi; Osmanlı parası tek hakim oldu."},{"label":"Piyasayı sarsmayın; yabancı para serbestçe dönsün.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Yabancı Madeni Paraların Dolaşımının Yasaklanması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Yabancı Madeni Paraların Dolaşımının Yasaklanması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Yabancı Madeni Paraların Dolaşımının Yasaklanması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 260) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_261', 'ottoman', 'Kalyonların Bakır Kaplama Gövde İcadı', 'Tersane-i Âmire', 'Gemilerin altının kurtlanıp çürümesini önlemek için su altı gövdelerinin ince bakır levhayla kaplanması teklif edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Bütçe ayır; bütün kalyonları bakır kaplatarak ömürlerini üç katına çıkar.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Kalyonlarımız yıllarca denizde çürümeden kaldı; donanma üstünlük sağladı."},{"label":"Geleneksel katran ve ziftleme yeterlidir; masrafa gerek yok.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kalyonların Bakır Kaplama Gövde İcadı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kalyonların Bakır Kaplama Gövde İcadı fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kalyonların Bakır Kaplama Gövde İcadı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 261) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_262', 'ottoman', 'Kışlalarda Kumar ve Afyon Salgını', 'Yeniçeri Kışlaları', 'Kışlalara gizlice sokulan afyon ve zarlar yüzünden askerlerin nöbet tutamaz hale geldiği tespit edildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Tavizsiz gece baskınları yap; afyoncuları ve kumarbazları ocaktan atıp küreğe koy.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Kışlalar temizlendi; ocakta çelik gibi bir nizam kuruldu."},{"label":"Askerin boş zamanıdır; çok sert tedbir alırsak ayaklanırlar.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kışlalarda Kumar ve Afyon Salgını sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Kışlalarda Kumar ve Afyon Salgını meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Kışlalarda Kumar ve Afyon Salgını gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 262) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_263', 'ottoman', 'Fransız Topçu Subaylarının İstihdamı', 'Tophane Dökümhanesi', 'Modern top bataryaları kurmak için Fransız subayların yüksek maaşla Tophane\'ye hoca yapılması önerildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"İlim ve fen düşmandan da olsa alınır; subayları tut ve yerli talebeler yetiştir.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Topçuluk çağ atladı; modern havan ve obüsler surları yerle bir etti."},{"label":"Gâvurdan hoca olmaz diyerek teklifi reddet.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Fransız Topçu Subaylarının İstihdamı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Fransız Topçu Subaylarının İstihdamı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Fransız Topçu Subaylarının İstihdamı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 263) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_264', 'ottoman', 'Kazakların Gece Baskını ve İntikam Seferi', 'Kafkasya Sınırı', 'Kazak süvarileri bir sınır kasabasını basıp yaktı; sınır paşası kadın çocuk demeden karşı köyleri katletmek istiyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Paşaya ferman sal: Sadece silahlı eşkıyayı vur, masum sivil ahaliye dokunma.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"İslam\'ın harp ahlakı korundu; eşkıya imha edildi, masumlar korundu."},{"label":"Göze göz, dişe diş! Bütün karşı köyleri ateşe ver.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Kazakların Gece Baskını ve İntikam Seferi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Kazakların Gece Baskını ve İntikam Seferi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kazakların Gece Baskını ve İntikam Seferi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 264) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_265', 'ottoman', 'Skorbut (İskorbüt) Hastalığı ve Limon İhtiyacı', 'Akdeniz Donanması', 'Aylardır denizde olan donanmada dişleri dökülen ve eriyen leventler için bol narenciye ve taze sebze istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Antalya ve Kıbrıs\'tan derhal narenciye yüklü takviye gemileri sevk et.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Hastalık kesildi; leventler deniz cengine hazır hale geldi."},{"label":"Kuru peksimet ve tuzlu etle idare etsinler; masrafa lüzum yok.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Skorbut (İskorbüt) Hastalığı ve Limon İhtiyacı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Skorbut (İskorbüt) Hastalığı ve Limon İhtiyacı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Skorbut (İskorbüt) Hastalığı ve Limon İhtiyacı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 265) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_266', 'ottoman', 'Lağımcıların Ücret Farkı Grevi', 'Belgrad Kalesi', 'Toprak altında hayatını hiçe sayıp dinamit ve barut döşeyen lağımcılar yeniçerilerden az maaş aldıklarını söyleyerek kazmayı bıraktı.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_humbaracibasi","name":"Humbaracıbaşı"}]', '[{"label":"Hakkı teslim et: Lağımcılara özel muharip tehlike tazminatı bağla.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Lağımcılar şevkle çalıştı; düşman kalesi alttan havaya uçuruldu."},{"label":"Ocak kanunu birdir; nefer ne alıyorsa onu alsınlar.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Lağımcıların Ücret Farkı Grevi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Lağımcıların Ücret Farkı Grevi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Lağımcıların Ücret Farkı Grevi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 266) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_267', 'ottoman', 'Deve ve Katırların Çöl Humması', 'Bağdat Seferi Levazımı', 'Bağdat çöllerinde ordu yükünü çeken binlerce katır salgında öldü; toplar kumun ortasında kaldı.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Aşiretlerden yüksek bedelle deve kirala ve orduyu çölden süratle çıkar.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Toplar ve cephane kurtarıldı; ordu Bağdat önüne sağlam vardı."},{"label":"Topları kuma gömüp sadece askerle ilerleyin.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Deve ve Katırların Çöl Humması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Deve ve Katırların Çöl Humması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Deve ve Katırların Çöl Humması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 267) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_268', 'ottoman', 'Gemi Ustalarının Venedik\'e Kaçması', 'Sinop Tersanesi', 'Maaşları ödenmeyen usta kalafatçı ve marangozların gizlice Venedik tersanelerine kaçtığı ihbar edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Tersane ustalarının maaşlarını ikiye katla, atölyeler ve lojmanlar kurarak onları taltif et.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Ustalar geri döndü; tersanelerimiz dünyanın en hızlı gemilerini yaptı."},{"label":"Sınırları kapat, kaçmaya kalkan ustaları idam et.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gemi Ustalarının Venedik\'e Kaçması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Gemi Ustalarının Venedik\'e Kaçması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Gemi Ustalarının Venedik\'e Kaçması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 268) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_269', 'ottoman', 'Kış Uykusuna Yatan Garnizon', 'Erzurum Kalesi', 'Şiddetli kışta nöbetçilerin kulelerde ateş yakıp uyuduğu ve Safevi öncülerinin surlara merdiven dayadığı bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Kale dizdarını derhal divana çek, nöbeti ihmal edenleri cezalandır ve disiplini tazele.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Garnizon ayağa kalktı; düşman baskını surlardan püskürtüldü."},{"label":"Erzurum kışı zordur; askeri çok sıkmayın.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kış Uykusuna Yatan Garnizon nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kış Uykusuna Yatan Garnizon fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kış Uykusuna Yatan Garnizon meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 269) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_270', 'ottoman', 'Tüfeklerin Namlusunu Kısa Kesen Yeniçeriler', 'Cebeci Kışlaları', 'Sokakta kolay taşımak ve kabadayılık yapmak için yeniçerilerin tüfek namlularını kestikleri (piştov yaptıkları) görüldü.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_cebecibasi","name":"Cebecibaşı"}]', '[{"label":"Kesik tüfekleri toplatıp imha et; askeri silahı bozanı ağır hapisle cezalandır.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Sokak kabadayılığı kırıldı; nizami tüfek disiplini korundu."},{"label":"Askerin hevesidir; karışıp ocakla arayı açma.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Tüfeklerin Namlusunu Kısa Kesen Yeniçeriler nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Tüfeklerin Namlusunu Kısa Kesen Yeniçeriler fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Tüfeklerin Namlusunu Kısa Kesen Yeniçeriler meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 270) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_271', 'ottoman', 'Tuna Donanmasında Kürekçi Kıtlığı', 'Tuna Kalesi Palankaları', 'Şaykalarda kürek çekecek adam bulunamıyor; nehir boyundaki köylerden zorunlu forsa toplanmak isteniyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Köylüyü zorla forsaya vurma! Dolgun yevmiye ile gönüllü nehir leventleri topla.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Nehir filosu gönüllü yiğitlerle doldu; Tuna\'da zafer kazanıldı."},{"label":"Köylerden zorla eli silah tutan gençleri küreğe bağla.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tuna Donanmasında Kürekçi Kıtlığı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Tuna Donanmasında Kürekçi Kıtlığı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Tuna Donanmasında Kürekçi Kıtlığı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 271) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_272', 'ottoman', 'Barutun Güherçile Kalitesinin Düşmesi', 'Payitaht Cephaneliği', 'Top ve tüfeklerin duman çıkarıp az menzile atış yaptığı, güherçile imalatında hile yapıldığı anlaşıldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kayseri ve Konya güherçile ocaklarını yeniden kurdur; kaliteli saflaştırma yaptır.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Dumansız ve yüksek güçlü barut üretildi; top menzilimiz ikiye katlandı."},{"label":"Mevcut barut idare eder; baruthaneyi masrafa sokmayın.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Barutun Güherçile Kalitesinin Düşmesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Barutun Güherçile Kalitesinin Düşmesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Barutun Güherçile Kalitesinin Düşmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 272) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_273', 'ottoman', 'At Terbiyecilerinin ve Nalbantların Azlığı', 'Sıvas Kışlası', 'Sipahi süvarilerinin atları ehil nalbant bulunamadığı için tırnak hastalıklarından topal kalıyor.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Hususi Baytar ve Nalbant Mektebi açtır, başarılı ustalara muafiyet tanı.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Atlar sağlam nallarla donatıldı; süvari gücümüz yıldırım gibi hızlandı."},{"label":"Asker kendi atını kendi nallasın; mektebe lüzum yok.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve At Terbiyecilerinin ve Nalbantların Azlığı nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve At Terbiyecilerinin ve Nalbantların Azlığı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve At Terbiyecilerinin ve Nalbantların Azlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 273) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_274', 'ottoman', 'Yıllar Süren Kuşatmanın Bıkkınlığı', 'Kandiye Kuşatması', 'Girit Kandiye kalesi önünde yirmi yıldır süren kuşatmadan yorulan askerler \'Evimize dönelim\' diye serdar çadırına yürüdü.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Padişah adına bizzat tebrik ve yüksek cihat bahşişi yolla, taze güçlerle son hücumu emret.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Asker şahlandı; Kandiye kalesi fethedilerek Girit\'in fethi tamamlandı."},{"label":"Kuşatmayı kaldırıp adayı Venedik\'e bırakarak geri çekilin.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Yıllar Süren Kuşatmanın Bıkkınlığı hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Yıllar Süren Kuşatmanın Bıkkınlığı hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Yıllar Süren Kuşatmanın Bıkkınlığı gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 274) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_275', 'ottoman', 'Venedik Havan Toplarının Yangın Bombaları', 'Mora Savaşları', 'Düşman donanması kalelerimizin içine sönmeyen fosforlu yangın bombaları atarak binaları tutuşturuyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Mühendisleri topla; kireç ve ıslak kum bataryalarıyla yangın söndürme nizamı kurdur.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Yangınlar hızla söndürüldü; kalelerimiz düşmana teslim olmadı."},{"label":"Kaleleri tahliye edip iç bölgelere çekilin.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Venedik Havan Toplarının Yangın Bombaları nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Venedik Havan Toplarının Yangın Bombaları fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Venedik Havan Toplarının Yangın Bombaları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 275) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_276', 'ottoman', 'Tersane Halatlarının Çürük Malzemeden Yapılması', 'İstanbul Tophane İskelesi', 'Kendir yerine saman lifi karıştırılan gemi palamarları ilk fırtınada koptu ve iki kalyon kayalara vurdu.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Halatçıbaşını ve hileli müteahhidi idam ettir; Karadeniz kenevirini doğrudan satın al.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Tersanede yolsuzluğun kökü kazındı; halatlar çelik gibi sağlam örüldü."},{"label":"Kaza süsü verin; müteahhit hatırlı bir paşanın akrabasıdır.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Tersane Halatlarının Çürük Malzemeden Yapılması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Tersane Halatlarının Çürük Malzemeden Yapılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Tersane Halatlarının Çürük Malzemeden Yapılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 276) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_277', 'ottoman', 'Dağıstan Şamhallarının Süvari Yardımı', 'Kafkas Lejyonu', 'Şamhal beyleri, yıllık maktu tahsisat karşılığında sınıra 20 bin zırhlı Dağıstan süvarisi koymayı teklif eder.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tahsisatı bağla ve Şamhal\'a kılıç ve sancak gönder; Kafkas sınırını çelikle ör.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Kafkasya seddi kuruldu; kuzeyden gelen düşman akınları durduruldu."},{"label":"Paralı askere güvenilmez; kendi garnizonumuzla koruruz.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dağıstan Şamhallarının Süvari Yardımı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Dağıstan Şamhallarının Süvari Yardımı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Dağıstan Şamhallarının Süvari Yardımı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 277) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_278', 'ottoman', 'Eski Muhariplere Emekli Maaşı (Tekaüd)', 'Yeniçeri Ağası', 'Savaşlarda sakat kalan veya yaşlanan yeniçerilerin dirlik alamayıp cami avlularında dilendiği bildirildi.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_yeniceri_agasi","name":"Yeniçeri Ağası"}]', '[{"label":"Tekaüd Sandığı kurdur; gazi ihtiyarlara ömür boyu şerefli emekli maaşı bağla.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Gazilerin duası tahtı sardı; askerin devlete sadakati zirve yaptı."},{"label":"Sakat askere bakacak bütçe yoktur; akrabaları baksın.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Eski Muhariplere Emekli Maaşı (Tekaüd) nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Eski Muhariplere Emekli Maaşı (Tekaüd) fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Eski Muhariplere Emekli Maaşı (Tekaüd) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 278) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_279', 'ottoman', 'Malta Şövalyelerinin Hacı Gemisini Yağmalaması', 'Akdeniz Açıkları', 'Mekke\'den dönen hacı ve tüccar gemisi Malta korsanlarınca batırıldı; kadınlar ve çocuklar esir edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kaptan-ı Derya\'yı tam teçhizat denize çıkar; korsan inlerini vurup esirleri kurtar.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Malta filosu darmadağın edildi; esirler kurtarılıp payitahta getirildi."},{"label":"Deniz aşırı savaşı göze alma; sadece diplomatik protesto çek.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Malta Şövalyelerinin Hacı Gemisini Yağmalaması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Malta Şövalyelerinin Hacı Gemisini Yağmalaması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Malta Şövalyelerinin Hacı Gemisini Yağmalaması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 279) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_280', 'ottoman', 'Esir Mühendislerin Kalyon Projeleri', 'Tersane Zindanı', 'Tersanede tutsak olan Cenevizli bir gemi mühendisi, kendisini azat edersek en hızlı fırkateyn çizimlerini vereceğini söyledi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Anlaşmayı yap: Çizimleri uygula, gemiler denize inince mühendisi hürriyetine kavuştur.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Rüzgâr gibi giden fırkateynler yapıldı; söz tutuldu, adalet takdir edildi."},{"label":"Çizimleri zorla al, mühendisi ölene kadar forsa olarak çalıştır.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Esir Mühendislerin Kalyon Projeleri hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Esir Mühendislerin Kalyon Projeleri hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Esir Mühendislerin Kalyon Projeleri gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 280) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_281', 'ottoman', 'Valide Sultanın Sadrazam Tayinine Müdahalesi', 'Harem Teşrifatı', 'Valide Sultan, liyakatli serdar yerine kendisine bol hediye gönderen beceriksiz bir paşayı başvekil yapmak istiyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_valide_sultan","name":"Valide Sultan"}]', '[{"label":"Harem nüfuzuna set çek! Liyakatli serdara mührü ver; valideden siyasete karışmamasını rica et.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Devlet liyakatle yönetildi; saray entrikaları kapı dışarı edildi."},{"label":"Valide Sultanın ricasını kırma; onun dediği paşaya mührü ver.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Valide Sultanın Sadrazam Tayinine Müdahalesi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Valide Sultanın Sadrazam Tayinine Müdahalesi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Valide Sultanın Sadrazam Tayinine Müdahalesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 281) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_282', 'ottoman', 'Türkçe ve Şarkiyat Derslerinin İhmali', 'Enderun Mektebi', 'Enderun\'da devşirme talebelerin devlet nizamını, İslam ahlakını ve Türkçe kitabeti tam öğrenmeden mezun edildiği görüldü.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"}]', '[{"label":"Müfredatı sıkılaştır; dil, ahlak ve şeriat derslerini geçemeyeni katiyen bürokrata yapma.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Devletine ve milletine kalpten bağlı yüksek ahlaklı yöneticiler yetişti."},{"label":"Pratik askerlik eğitimi kafidir; kitabi ilimlerle vakit kaybetmeyin.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Türkçe ve Şarkiyat Derslerinin İhmali nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Türkçe ve Şarkiyat Derslerinin İhmali fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Türkçe ve Şarkiyat Derslerinin İhmali meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 282) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_283', 'ottoman', 'Vezirlerin Müsadere Edilen Mallarının Gazilere Dağıtılması', 'Bab-ı Âli Divanı', 'İdam edilen rüşvetçi bir paşanın devasa altın servetinin gazilere ve dul yetimlere dağıtılması teklif edildi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Altınları doğrudan şehit ailelerine ve sakat gazilere vakfet.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Haram servet mazlumun yarasına merhem oldu; adalet tecelli etti."},{"label":"Hepsini sarayın gizli hazinesine (Ceb-i Hümayun) aktar.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Vezirlerin Müsadere Edilen Mallarının Gazilere Dağıtılması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Vezirlerin Müsadere Edilen Mallarının Gazilere Dağıtılması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Vezirlerin Müsadere Edilen Mallarının Gazilere Dağıtılması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 283) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_284', 'ottoman', 'Felsefe ve Kelam Derslerinin Yasaklanması Talebi', 'Medrese Müderrisleri', 'Yobaz bir vaiz zümresi, medreselerden mantık, felsefe ve astronomi derslerinin tamamen kaldırılmasını istiyor.', '[{"id":"char_muderris","name":"Medrese Müderrisi"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Fârâbî ve Gazâlî geleneğini savun! Akli ve nakli ilimleri beraber okutmayan medreseyi kapat.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Akıl ve iman dengesi korundu; medreselerden büyük âlimler yetişti."},{"label":"Vaizlerin talebini kabul et; sadece fıkıh ve ezber kalsın.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Felsefe ve Kelam Derslerinin Yasaklanması Talebi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Felsefe ve Kelam Derslerinin Yasaklanması Talebi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Felsefe ve Kelam Derslerinin Yasaklanması Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 284) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_285', 'ottoman', 'Padişahın Sade Kıyafetle Halk İçine Karışması (Tebdil-i Kıyafet)', 'Topkapı Arz Odası', 'Vezirler, padişahın derviş kılığında çarşıları ve fırınları teftiş etmesinin hükümdarlık vakarını düşürdüğünü söylüyor.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Tebdil teftişlerine devam et! Çobanın gözü sürüde olmazsa kurt kapar.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Padişah bizzat haksızlıkları gördü ve düzeltti; zalim idareciler titredi."},{"label":"Vezirleri dinle; saraydan dışarı adım atma, raporlarla yetin.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Padişahın Sade Kıyafetle Halk İçine Karışması (Tebdil-i Kıyafet) nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Padişahın Sade Kıyafetle Halk İçine Karışması (Tebdil-i Kıyafet) fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Padişahın Sade Kıyafetle Halk İçine Karışması (Tebdil-i Kıyafet) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 285) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_286', 'ottoman', 'Uluslararası Anlaşmalarda Eşitlik İlkesi', 'Reisülküttab Kalemi', 'Avusturya İmparatoru, anlaşmalarda Osmanlı Sadrazamına değil doğrudan Osmanlı Padişahına denk sayılmak istiyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_reisulkuttab","name":"Reisülküttab"}]', '[{"label":"Askeri ve siyasi üstünlüğümüzü koru; fermanı sadece \'Osmanlı Padişahının dengi yoktur\' üzere mühürle.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Cihan devleti protokolü tavizsiz korundu; düşman boyun eğdi."},{"label":"Talebi kabul et; eşitlik maddesini imzala.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Uluslararası Anlaşmalarda Eşitlik İlkesi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Uluslararası Anlaşmalarda Eşitlik İlkesi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Uluslararası Anlaşmalarda Eşitlik İlkesi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 286) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_287', 'ottoman', 'Haksız Harbe Karşı Fetva Direnişi', 'Şeyhülislam Kapısı', 'Hırslı bir sadrazam, sırf şan kazanmak için barış anlaşması olan Müslüman bir komşuya savaş açmak için fetva zorluyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Şeyhülislamı koru ve haksız savaşa mani ol; sadrazamı derhal azlet.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Haksız yere Müslüman kanı dökülmesi önlendi; meşruiyet korundu."},{"label":"Sadrazamı kırma; zorla fetva çıkartıp orduyu hücuma kaldır.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Haksız Harbe Karşı Fetva Direnişi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Haksız Harbe Karşı Fetva Direnişi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Haksız Harbe Karşı Fetva Direnişi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 287) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_288', 'ottoman', 'Taşra Şikâyetçilerinin İstanbul\'a Giriş Yasağı', 'Bab-ı Hümayun', 'Başkentteki izdihamı önlemek bahanesiyle valilerden şikâyetçi olmak isteyen köylülerin şehre girişi engellenmek isteniyor.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kapıları ardına kadar aç! Mazlumun sesini kısan taht ayakta kalamaz.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Mazlumlar divana aktı; zalim valilerin maskesi düşürüldü."},{"label":"Kapıları kapat; başkentin asayişi köylünün derdinden mühimdir.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Taşra Şikâyetçilerinin İstanbul\'a Giriş Yasağı nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Taşra Şikâyetçilerinin İstanbul\'a Giriş Yasağı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Taşra Şikâyetçilerinin İstanbul\'a Giriş Yasağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 288) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_289', 'ottoman', 'Padişahın Sağlık Durumunun Gizlenmesi', 'Saray Hekimbaşılığı', 'Padişahın ağır felç geçirdiği, vezirlerin ise sahte fermanlarla devleti aylardır kendi çıkarları için yönettiği ortaya çıktı.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_hekimbasi","name":"Hekimbaşı"}]', '[{"label":"Veliaht şehzadeyi derhal tahta çıkar; devlette gizli oligarşiye son ver.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Meşruiyet tazelendi; sahte ferman çetesi bertaraf edildi."},{"label":"Padişah iyileşene kadar vezirlerin gizli idaresine yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Padişahın Sağlık Durumunun Gizlenmesi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Padişahın Sağlık Durumunun Gizlenmesi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Padişahın Sağlık Durumunun Gizlenmesi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 289) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_290', 'ottoman', 'Devlet Bütçesinin Mecliste Şeffaf Görüşülmesi', 'Divan Meclisi', 'Genç kâtipler, her yıl gelir ve giderlerin tüm divan üyelerinin önünde açıkça okunmasını ve tartışılmasını önerdi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Şeffaf bütçe usulünü kanunlaştır; körü körüne para harcanmasına son ver.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Gereksiz harcamalar kesildi; devlet maliyesi hesap verebilir oldu."},{"label":"Devlet sırrıdır; bütçeyi sadece sadrazam ve defterdar bilsin.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Devlet Bütçesinin Mecliste Şeffaf Görüşülmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Devlet Bütçesinin Mecliste Şeffaf Görüşülmesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Devlet Bütçesinin Mecliste Şeffaf Görüşülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 290) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_291', 'ottoman', 'Ali Kuşçu\'nun Astronomi Mirasının Basılması', 'Topkapı Sarayı Kütüphanesi', 'Kadim rasat ve matematik risalelerinin çoğaltılıp tüm medreselere ücretsiz dağıtılması teklif edildi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Hazine bütçesiyle risaleleri çoğalttır; fen bilimlerini medreselerde zorunlu kıl.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Matematik ve astronomide büyük sıçrama yaşandı; mühendisler yetişti."},{"label":"Medreselere sadece fıkıh yeterlidir; riyaziye fuzulidir.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Ali Kuşçu\'nun Astronomi Mirasının Basılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Ali Kuşçu\'nun Astronomi Mirasının Basılması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Ali Kuşçu\'nun Astronomi Mirasının Basılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 291) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_292', 'ottoman', 'Kafkas Muhacirlerinin İskânı', 'Kafkasya ve Kırım', 'Kuzeydeki baskılardan kaçıp payitahta sığınan yüz binlerce Müslüman muhacir çadırlarda soğuktan donuyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_tasra_muhaciri","name":"Taşra Muhaciri"}]', '[{"label":"Hazineyi aç; boş Anadolu arazilerini muhacirlere ver, evler kur ve 5 yıl vergiden muaf tut.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Muhacirler vatan buldu; boş topraklar tarıma açılıp berekete boğuldu."},{"label":"Bütçe yoktur; muhacirler başlarının çaresine baksın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kafkas Muhacirlerinin İskânı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kafkas Muhacirlerinin İskânı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kafkas Muhacirlerinin İskânı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 292) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_293', 'ottoman', 'Rüşvet Veren Paşanın Şahitliğinin Reddi', 'Şeyhülislamlık', 'Şeyhülislam, geçmişte rüşvetle makam aldığı bilinen eski bir vezirin mahkemelerdeki şahitliğini hükümsüz saydı.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Şeyhülislamın arkasında dur! Ahlaksız adam isterse vezir olsun şahitlik edemez.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Mahkemelere ahlak ve şeref geldi; rüşvetçilerin itibarı sıfırlandı."},{"label":"Eski veziri küçük düşürme; fetvayı geri çektir.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Rüşvet Veren Paşanın Şahitliğinin Reddi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Rüşvet Veren Paşanın Şahitliğinin Reddi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Rüşvet Veren Paşanın Şahitliğinin Reddi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 293) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_294', 'ottoman', 'Liyakatsiz Şehzade Hocasının (Lala) İttifakı', 'Sadaret Dairesi', 'Geleceğin padişahını yetiştiren lalanın, şehzadeye devlet işlerini değil dalkavukluğu ve lüksü öğrettiği görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Lalayı derhal azlet; yerine memleketin en bilge, dik duruşlu allamesini hoca tayin et.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Geleceğin hükümdarı adalet ve vakarla yetişti; mülk teminat altına alındı."},{"label":"Şehzadenin sevdiği hocadır; aralarını bozma.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Liyakatsiz Şehzade Hocasının (Lala) İttifakı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Liyakatsiz Şehzade Hocasının (Lala) İttifakı fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Liyakatsiz Şehzade Hocasının (Lala) İttifakı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 294) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_295', 'ottoman', 'Vakıf Paralarının Özel Bankalara Yatırılması', 'İstanbul Sokakları', 'Bazı vakıf mütevellilerinin yetim ve fukara akçesini Galata bankerlerine yüksek faizle yatırıp faizini cebe attığı ortaya çıktı.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Mütevellileri zindana at, tefecideki tüm parayı kuruşuna kadar alıp fukaraya dağıt.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Vakıf hırsızlığı en ağır cezayı buldu; yetimin ahı yerde kalmadı."},{"label":"Vakıf kâr etmiştir deyip faiz gelirinin bir kısmını hazineye al.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf Paralarının Özel Bankalara Yatırılması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Vakıf Paralarının Özel Bankalara Yatırılması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Vakıf Paralarının Özel Bankalara Yatırılması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 295) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_296', 'ottoman', 'Yabancı Elçilik Muhafızlarının Dokunulmazlığı', 'Payitaht Çarşısı', 'Fransız elçisinin silahlı muhafızları çarşıda bir Müslüman esnafı yaraladı ve elçilik \'kapitülasyon dokunulmazlığı\' iddia ediyor.', '[{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Ferman sal: Kan dökenin dokunulmazlığı olmaz! Katilleri yargılanmak üzere derhal teslim al.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Milli egemenlik korundu; tebaa kendi yurdunda garip olmadığını gördü."},{"label":"Diplomatik krizden kork; katilleri gemiyle kaçırmalarına yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Yabancı Elçilik Muhafızlarının Dokunulmazlığı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Yabancı Elçilik Muhafızlarının Dokunulmazlığı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Yabancı Elçilik Muhafızlarının Dokunulmazlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 296) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_297', 'ottoman', 'Tahrir Defterlerinin Tahrif Edilmesi', 'Divan Mezalim Dairesi', 'Ayanların para karşılığı tahrir kâtiplerine rüşvet verip kendi topraklarını az, komşu fukaranın toprağını çok yazdırdığı anlaşıldı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"O sancağın defterini iptal et; tarafsız bir heyetle köyleri yeniden karış karış yazdır.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Vergi adaleti sağlandı; fukaranın sırtındaki haksız yük kaldırıldı."},{"label":"Yeni tahrir çok masraflıdır; mevcut defterle devam edin.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Tahrir Defterlerinin Tahrif Edilmesi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Tahrir Defterlerinin Tahrif Edilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Tahrir Defterlerinin Tahrif Edilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 297) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_298', 'ottoman', 'Mekke Şerifinin Bağımsızlık Fısıltıları', 'Hicaz Emareti', 'İngiliz altınlarıyla temas kuran Mekke Şerifi, hac gelirlerinin tamamının kendisine bırakılmasını ve Osmanlı garnizonunun çekilmesini talep etti.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Talebi kesin bir dille reddet; sadık bir başka Şerif ailesini başa geçirip garnizonu takviye et.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Kutsal topraklar emperyalizme peşkeş çekilmekten kurtarıldı; hilafet korundu."},{"label":"Arayı bozma; hac gelirlerini Şerif\'e bırakıp garnizonu çek.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mekke Şerifinin Bağımsızlık Fısıltıları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Mekke Şerifinin Bağımsızlık Fısıltıları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Mekke Şerifinin Bağımsızlık Fısıltıları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 298) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_299', 'ottoman', 'Kanun-ı Esasi ve Şura-yı Devlet Taslağı', 'Bab-ı Âli İstişare Meclisi', 'Âlimler ve devlet adamları, keyfi idareyi ebediyen bitirecek, meşvereti ve adaleti garantiye alacak yazılı bir Meclis Kanunu sundu.', '[{"id":"char_surayidevlet_heyeti","name":"Şura-yı Devlet Heyeti"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"\'İşlerini şura ile yürütürler\' ayetine sarıl; Meclis-i Mebusan\'ı aç ve kanun üstünlüğünü ilan et.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Millet meclisine kavuştu; devlet meşrutiyet ve adaletle yenilendi."},{"label":"Padişahın mutlak kudretine hiçbir kayıt konulamaz; taslağı yaktır.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kanun-ı Esasi ve Şura-yı Devlet Taslağı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kanun-ı Esasi ve Şura-yı Devlet Taslağı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kanun-ı Esasi ve Şura-yı Devlet Taslağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 299) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_300', 'ottoman', 'Nizam-ı Âlemin Mührü: Ebed-Müddet Devlet', 'Dâire-i Adliyye Sırrı', 'Üç yüz yıllık hüküm tecrübesinin ardından pir-i fani bir bilge sorar: \'Ey Hükümdar! Mülk kılıçla mı, altınla mı, yoksa adaletle mi ayakta kalır?\'', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'Kılıç fetheder, altın donatır; lakin devleti ancak ve ancak hakiki adalet yaşatır!\'.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Adalet çemberi kemale erdi; mülk nizam-ı âlem mertebesinde tarihe mühürlendi."},{"label":"\'Güç kimdeyse hak onundur; mülk zorbalıkla korunur.\'.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Nizam-ı Âlemin Mührü: Ebed-Müddet Devlet nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Nizam-ı Âlemin Mührü: Ebed-Müddet Devlet fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Nizam-ı Âlemin Mührü: Ebed-Müddet Devlet meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 300) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_301', 'ottoman', 'Vakıf Zeytinliğinin Mültezime İntikali', 'Kaza Sicili', 'Vefat eden mütevellinin ardından gelen kaza kadısı, vakfın gelir getiren asırlık zeytinliğini gizlice akrabası olan bir mültezime tapulamaya kalkıştı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Müfettiş tayin et; kadıyı azledip zeytinliği vakıf tesciline iade ettir.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Vakıf malı gaspçıların elinden kurtarıldı; kadı azledildi."},{"label":"Vakıf idaresi yerel tasarruftadır; müdahaleyi reddet.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf Zeytinliğinin Mültezime İntikali davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Vakıf Zeytinliğinin Mültezime İntikali davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Vakıf Zeytinliğinin Mültezime İntikali gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 301) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_302', 'ottoman', 'Yabancı Tacirin Batık Gemi Tazminatı', 'Galata Kadılığı', 'Haliç girişinde bir Osmanlı çektirisinin çarparak batırdığı Felemenk ticaret teknesi için yabancı elçi tam tazminat ve kaptanın hapsini ister.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Bilirkişi heyeti kurdur; kusur Osmanlı kaptanındaysa zararı deniz fonundan ödet.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Tüccar hakkını aldı; limanlarımızın hukuki güvenliği Avrupa\'da takdir edildi."},{"label":"Bizim sularda kaza hükümsüzdür de; mağdurun zararını kısmen tazmin ettirip davayı sulh ile neticelendir.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Yabancı Tacirin Batık Gemi Tazminatı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Yabancı Tacirin Batık Gemi Tazminatı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Yabancı Tacirin Batık Gemi Tazminatı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 302) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_303', 'ottoman', 'Kumaş Boyacılarının Zehirli Atık Davası', 'Bursa Mahkemesi', 'Boyahanelerin derelere akıttığı zehirli çivit atıkları, aşağıdaki bahçelerin sulanmasını engelliyor; bostancılar mahkemeye yürüdü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Boyahanelere dinlendirme havuzu şartı koy; uymayan atölyeleri şehir dışına sür.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Bostanlar kurümaktan kurtuldu; zanaat ile tarım dengesi kuruldu."},{"label":"Kumaş ihracatı aksamasın; bostancılara başka kuyu kazdır.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kumaş Boyacılarının Zehirli Atık Davası nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kumaş Boyacılarının Zehirli Atık Davası fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kumaş Boyacılarının Zehirli Atık Davası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 303) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_304', 'ottoman', 'Miras Taksiminde Rüşvet Alan Kassam', 'Divan Mezalim Dairesi', 'Tereke taksim memuru (kassam), yetimlerin hakkı olan mirastan pay alabilmeleri için yüksek \'kısmet harcı\' dayatıp fazlasını zimmetine geçirdi.', '[{"id":"char_kassam","name":"Kassâm-ı Askerî"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Kassamı vazifeden at, haksız aldığı meblağı yetimlere iade ettir ve zindana koy.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Yetim hakkı korundu; adalet kapısı temizlendi."},{"label":"Kassamlık makamı teamüldür; cüzi miktarlar için memuru hırpalama.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras Taksiminde Rüşvet Alan Kassam sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Miras Taksiminde Rüşvet Alan Kassam meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Miras Taksiminde Rüşvet Alan Kassam gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 304) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_305', 'ottoman', 'Karacaahmet Kabristanı Sınır İhlali', 'Üsküdar Kadılığı', 'Zengin bir mülk sahibi, Karacaahmet Kabristanı\'nın sınır taşlarını gece vakti sökerek kendi bahçesine katmaya kalkıştı.', '[{"id":"char_uskudar_kadisi","name":"Üsküdar Kadısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Taşları eski yerine diktir; tecavüz eden zatı teşhir edip ağır para cezası kes.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Kabristan tecavüzü önlendi; halkın manevi hassasiyeti muhafaza edildi."},{"label":"Müteber bir kimsedir; kabristan arazisinden cüzi feragat et.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Karacaahmet Kabristanı Sınır İhlali nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Karacaahmet Kabristanı Sınır İhlali fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Karacaahmet Kabristanı Sınır İhlali meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 305) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_306', 'ottoman', 'Şer\'i İlama Rağmen Zorla Tahliye', 'Kaza Teftişi', 'Sancak beyi, mahkemenin \'kiracı haklıdır\' kararına meydan okuyarak gariban esnafı dükkânından zorla attı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Beyi payitahta celbet; esnafı dükkânına iade edip zararı beyin maaşından kes.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Hukuk zorbalığı yendi; sancak beyinin kibri kırıldı."},{"label":"Beyin otoritesini esnafın önünde sarsma; esnafa başka yer göster.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Şer\'i İlama Rağmen Zorla Tahliye nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Şer\'i İlama Rağmen Zorla Tahliye fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Şer\'i İlama Rağmen Zorla Tahliye meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 306) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_307', 'ottoman', 'Saraçların Çürük Kayış İddiası', 'Edirne Mahkemesi', 'Top arabalarını çeken koşum takımlarının kalitesiz deriden yapıldığı ve ilk tatbikatta koptuğu kadı huzurunda belgelendi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Hileli deri kullanan saraç kethüdasını azlet; sağlam malzeme şartnamesi koy.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Ordu levazımında hile önlendi; koşumlar emniyete alındı."},{"label":"Saraçları küstürme; mevcut kayışları yamatarak sefere yolla.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Saraçların Çürük Kayış İddiası hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Saraçların Çürük Kayış İddiası hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Saraçların Çürük Kayış İddiası gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 307) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_308', 'ottoman', 'Yalancı Şahidin Ayak Bastı Parası', 'Kaza Meclisi', 'Mahkeme kapısında bekleyip kuruş karşılığı her davada sahte şahitlik yapan bir şebeke tespit edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Şebekeyi çarşıda teşhir et, kaza defterine kara liste olarak kaydettir ve küreğe vur.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Mahkemeler sahte şahit belasından temizlendi; adalet berraklaştı."},{"label":"Hâkimlerin basiretine bırak; umumi ceza ilan etme.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Yalancı Şahidin Ayak Bastı Parası nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Yalancı Şahidin Ayak Bastı Parası fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Yalancı Şahidin Ayak Bastı Parası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 308) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_309', 'ottoman', 'Kira Bedellerinde Altın-Gümüş İhtilafı', 'İstanbul Kadılığı', 'Ev sahipleri sözleşmede yazılı akçeyi kabul etmeyip kirayı Venedik altını olarak talep ediyor; memurlar kirayı ödeyemez oldu.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Ferman çıkar: Resmi sözleşmelerde geçerli tek para basılı Osmanlı akçesidir.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Milli para korundu; kiracılar keyfi tahliyelerden kurtuldu."},{"label":"Sözleşme serbesttir; mal sahibi istediği parayı istesin.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kira Bedellerinde Altın-Gümüş İhtilafı nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kira Bedellerinde Altın-Gümüş İhtilafı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kira Bedellerinde Altın-Gümüş İhtilafı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 309) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_310', 'ottoman', 'Zeytinlik Sınır Taşlarının Değiştirilmesi', 'Kudüs Kadılığı', 'Manastır keşişleri ile komşu köy ahalisi arasında asırlık zeytinlik sınır taşının yerinden oynatıldığı iddiasıyla arbede çıktı.', '[{"id":"char_kudus_kadisi","name":"Kudüs Kadısı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Eski tapu tahrir defterini açtır; kadı nezaretinde sınırları cetvelle sabitle.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Tarafsız tahkikat fitneyi söndürdü; her iki cemaat de kararı öptü."},{"label":"Araziyi hazineye gelir kaydet; iki tarafı da men et.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zeytinlik Sınır Taşlarının Değiştirilmesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Zeytinlik Sınır Taşlarının Değiştirilmesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Zeytinlik Sınır Taşlarının Değiştirilmesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 310) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_311', 'ottoman', 'Frenk Konsolosunun Türk Katibi Hapse Attırması', 'İzmir Mahkemesi', 'Fransız konsolosu, kendi maiyetindeki Osmanlı tebaası kâtibi hırsızlıkla itham edip konsolosluk bodrumuna kilitledi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Mülkümüzde yabancı zindan kurulamaz! Kâtibi derhal kadı huzuruna çıkarttır.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Devletin hükümranlığı korundu; yabancı konsolos haddini bildi."},{"label":"Konsolosluk kapitülasyonuna divan gözetiminde tarafları meşverete davet edip orta yolu bul; meseleyi diplomatik yolla kapat.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Frenk Konsolosunun Türk Katibi Hapse Attırması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Frenk Konsolosunun Türk Katibi Hapse Attırması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Frenk Konsolosunun Türk Katibi Hapse Attırması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 311) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_312', 'ottoman', 'Suçsuz Kardeşin Hapsedilmesi (Cerime-i Akraba)', 'Kaza Sicili', 'Dağa çıkan eşkıyanın yerini söylemediği gerekçesiyle masum kardeşinin mallarına el konulup zindana atıldığı öğrenildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"\'Hiçbir günahkâr başkasının günahını yüklenmez\' ayetini işlet; kardeşi derhal sal.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Şahsi ceza prensibi korundu; zulüm durduruldu."},{"label":"Eşkıyayı yakalamak için aile baskısı lazımdır; içeride tutun.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Suçsuz Kardeşin Hapsedilmesi (Cerime-i Akraba) nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Suçsuz Kardeşin Hapsedilmesi (Cerime-i Akraba) fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Suçsuz Kardeşin Hapsedilmesi (Cerime-i Akraba) meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 312) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_313', 'ottoman', 'Kadıların Üç Yılda Bir Zorunlu Rotasyonu', 'Dîvân-ı Hümâyûn', 'Kazaskerler, yerel eşrafla akrabalık ve menfaat bağı kurmamaları için kadıların 3 yılda bir yer değiştirmesini teklif etti.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Kanunu onayla; yerel nüfuz çetelerinin yargıyı ele geçirmesini engelle.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Kadılık müessesesi bağımsızlığını tazeledi; yerel rüşvet ağları dağıtıldı."},{"label":"Taşınma masrafı büyüktür; kadılar sabit kazalarında kalsın.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadıların Üç Yılda Bir Zorunlu Rotasyonu davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadıların Üç Yılda Bir Zorunlu Rotasyonu davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadıların Üç Yılda Bir Zorunlu Rotasyonu gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 313) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_314', 'ottoman', 'Kumaş Damgasında Hile Yapan Müfettiş', 'Diyarbakır Mahkemesi', 'İpekli dokumaların kalitesini mühürleyen muhtesip yardımcısının, bozuk mallara para karşılığı \'tam ayar\' damgası vurduğu kanıtlandı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Damgayı elinden al, müfettişi vazifeden at ve hileli malları meydanda yaktır.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Diyarbakır kumaşının ticari şerefi kurtarıldı."},{"label":"Memurun itibarını koru; sadece hafif bir ikazla geçiştir.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kumaş Damgasında Hile Yapan Müfettiş nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kumaş Damgasında Hile Yapan Müfettiş fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kumaş Damgasında Hile Yapan Müfettiş meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 314) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_315', 'ottoman', 'Sahte Vakfiyeyle Vergi Kaçırma', 'Kaza Teftişi', 'Bir tüccar, geniş çiftliğini göstermelik bir \'aile vakfına\' dönüştürerek devlete öşür ve cizye vermekten kurtulmaya çalışıyor.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Vakfiyeyi müfettiş heyetine incelet; hayır gayesi taşımıyorsa iptal edip vergiyi tahsil et.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Sahte vakıf oyunu bozuldu; hazineye hak ettiği gelir girdi."},{"label":"Vakıf tescil edilmiştir; usule dokunup ulemayı tedirgin etme.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Sahte Vakfiyeyle Vergi Kaçırma nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Sahte Vakfiyeyle Vergi Kaçırma fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Sahte Vakfiyeyle Vergi Kaçırma meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 315) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_316', 'ottoman', 'Saka Beygirlerinin Aşırı Yüklenmesi', 'İstanbul Kadılığı', 'Şehre su taşıyan saka esnafının beygirlere taşıyabileceğinin iki katı tulum yükleyip hayvanları çatlattığı ihbar edildi.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"İhtisap fermanı neşret: Her beygire azami iki tulum sınırı koy, aşanın beygirini elinden al.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Zulüm durduruldu; sokaklarda sakat hayvan kalmadı."},{"label":"Su zaruridir; saka esnafının işine müdahale etme.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saka Beygirlerinin Aşırı Yüklenmesi meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Saka Beygirlerinin Aşırı Yüklenmesi hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Saka Beygirlerinin Aşırı Yüklenmesi gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 316) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_317', 'ottoman', 'Kervancı Başının Emanet Malı Kaybetmesi', 'Şam Mahkemesi', 'Şam-Halep kervanında kıymetli kürkler kayboldu; kervancı başı \'Eşkıya bastı\' derken tüccarlar malın gizlice satıldığını iddia ediyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kervancı başını sıkı hesaba çek; delil getiremezse zararı tazmin ettir.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Emanet hukuku korundu; kervan taşımacılığına emniyet geldi."},{"label":"Kervancının yeminine itimat et; tüccarın davasını reddet.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kervancı Başının Emanet Malı Kaybetmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kervancı Başının Emanet Malı Kaybetmesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kervancı Başının Emanet Malı Kaybetmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 317) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_318', 'ottoman', 'Öşür Tahsilatında Yaş-Kuru Hilesi', 'Kaza Teftişi', 'Vergi tahsildarları, köylünün tarladaki henüz kurumamış yaş buğdayını tartarak iki katı vergi yazmaya kalkıştı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tahsilatı durdur; tartının ancak kuru dane üzerinden yapılacağını ilan et, zorbaları cezalandır.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Köylünün rızkı korundu; tahsildar hilesi püskürtüldü."},{"label":"Hazineye gelir lazımdır; tahsildarın hesabını bozma.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Öşür Tahsilatında Yaş-Kuru Hilesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Öşür Tahsilatında Yaş-Kuru Hilesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Öşür Tahsilatında Yaş-Kuru Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 318) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_319', 'ottoman', 'Çırağın Ustasından Şikâyetçi Olması', 'Bursa İpek Mahkemesi', 'Bir dokuma çırağı, ustasının kendisine meslek öğretmeyip gece gündüz ev işlerinde çalıştırdığını ve dövdüğünü arz etti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Ahi loncası heyetini topla; çırağı dürüst bir ustaya ver, eski ustaya ceza kes.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Zanaat ahlakı korundu; genç yeteneklerin harcanması önlendi."},{"label":"Ustanın işine karışılmaz; \'Eti senin kemiği benim\' kaidesidir.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Çırağın Ustasından Şikâyetçi Olması hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Çırağın Ustasından Şikâyetçi Olması hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Çırağın Ustasından Şikâyetçi Olması gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 319) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_320', 'ottoman', 'Kadı Hüccetlerinin Padişahça Onayı', 'Dîvân-ı Hümâyûn', 'Veziriazam, tüm kaza kararlarının payitahttan tek tek onaylanmasını önererek yerel mahkemeleri doğrudan kendine bağlamak ister.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Reddet! Mahkeme kadının vicdanıdır; adaleti sadaretin tekeline bırakma.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Yargı bağımsızlığı teyit edildi; davaların aylarca gecikmesi önlendi."},{"label":"Onayla; bütün mahkeme mühürleri sadrazamın elinden geçsin.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Kadı Hüccetlerinin Padişahça Onayı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Kadı Hüccetlerinin Padişahça Onayı fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kadı Hüccetlerinin Padişahça Onayı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 320) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_321', 'ottoman', 'Varsak Türkmenlerinin Toprağa İskânı', 'Çukurova Tahriri', 'Yaylak ve kışlak arasında göç ederken ekili arazileri bozan Varsak aşiretinin sabit köylere yerleştirilmesi planlandı.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Verimli boş araziler tahsis et, çift öküzü hibe et ve 3 yıl vergiden muaf tut.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Aşiret ziraate başladı; Çukurova pamuk ve tahıl ambarına döndü."},{"label":"Zorla köylere kapat, direnen aşiret reislerini sürgüne yolla.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Varsak Türkmenlerinin Toprağa İskânı nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Varsak Türkmenlerinin Toprağa İskânı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Varsak Türkmenlerinin Toprağa İskânı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 321) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_322', 'ottoman', 'Köroğlu Dağlarında Celâlî Sığınağı', 'Bolu Sancağı', 'Tüfekli levent çeteleri dağ geçitlerini tutarak Bolu-Ankara irtibatını kesti; köylü şehre zahire indiremiyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Düzenli ordu müfrezesiyle dağları kuşat, levent reislerini yakalayıp adalete teslim et.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Bolu dağları eşkıyadan temizlendi; kervanlar emniyetle aktı."},{"label":"Reislerine sancak beyliği verip uzlaşma yoluna git.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Köroğlu Dağlarında Celâlî Sığınağı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Köroğlu Dağlarında Celâlî Sığınağı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Köroğlu Dağlarında Celâlî Sığınağı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 322) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_323', 'ottoman', 'Sınır Boyunda Ermeni Zanaatkarların Göçü', 'Erzurum Vilayeti', 'Taşra valisinin aşırı salgun vergisi yüzünden Erzurum ve Van\'daki gümüş ustaları İran tarafına kaçmaya başladı.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Valiyi azlet; haksız vergileri kaldırıp zanaatkarlara can ve mal emniyeti garantisi ver.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Ustalar geri döndü; Doğu Anadolu\'nun kuyumculuğu ve ticareti canlandı."},{"label":"Giden gider; Müslüman esnaf onların yerini doldurur.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Sınır Boyunda Ermeni Zanaatkarların Göçü nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Sınır Boyunda Ermeni Zanaatkarların Göçü fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Sınır Boyunda Ermeni Zanaatkarların Göçü meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 323) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_324', 'ottoman', 'Kazak Akınlarına Karşı Palanka İnşası', 'Tuna Yalıları', 'Köylüler nehir kenarındaki evlerini bırakıp iç bölgelere kaçıyor; nehir boyuna küçük hisarlar (palanka) kurulması istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Devlet bütçesiyle ahşap-toprak palankalar kurdur; içine tüfekli yeniçeri yerleştir.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Tuna sahili çelikten bir hat oldu; köylü tarlasına döndü."},{"label":"Masraflıdır; köylüler kendi hisarlarını kendileri yapsın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Kazak Akınlarına Karşı Palanka İnşası nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Kazak Akınlarına Karşı Palanka İnşası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kazak Akınlarına Karşı Palanka İnşası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 324) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_325', 'ottoman', 'Aşiret Reisinin Şahsi Vergi Toplaması', 'Diyar-ı Bekr', 'Cizre civarındaki bir aşiret beyi, devletin tahsildarını kazaya sokmayıp vergiyi doğrudan kendi cebine indiriyor.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"},{"id":"char_tahsildar","name":"Vergi Tahsildarı"}]', '[{"label":"Sancak beyine emret: Aşireti kuşat, devlete tabi olana kadar reislerini enterne et.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Devlet otoritesi tesis edildi; kaçırılan vergi hazineye kondu."},{"label":"Aşireti ürkütme; yıllık maktu bir harç bağlayıp gerisine divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Aşiret Reisinin Şahsi Vergi Toplaması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Aşiret Reisinin Şahsi Vergi Toplaması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Aşiret Reisinin Şahsi Vergi Toplaması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 325) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_326', 'ottoman', 'Yörük Kocacık Aşiretinin Balkan İskânı', 'Rumeli Tahriratı', 'Balkan dağlarındaki ıssız geçitleri korumak ve boş toprakları açmak için Yörüklerin yerleştirilmesi teklif edildi.', '[{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Planlı iskân fermanı çıkar; Yörüklere toprak ve vergiden muafiyet bahşet.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Balkan geçitleri emniyete alındı; Türkmen köyleri kuruldu."},{"label":"Aşiretleri yerlerinden kıpırdatma; göç masrafına girme.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Yörük Kocacık Aşiretinin Balkan İskânı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Yörük Kocacık Aşiretinin Balkan İskânı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yörük Kocacık Aşiretinin Balkan İskânı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 326) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_327', 'ottoman', 'Menderes Taşkınları ve Bataklık Islahı', 'Aydın Sancağı', 'Büyük Menderes nehri taşarak bereketli tarlaları bataklığa çevirdi; sıtma yüzünden köyler kırılıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mühendisler eşliğinde sedd-i kebîr (büyük set) inşa ettir; bataklığı kurutup çiftçiye aç.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Sıtma bitti; on binlerce dönüm bereketli tarla ziraate kazandırıldı."},{"label":"Bataklık tabiatın işidir; köylüler tepelere taşınsın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Menderes Taşkınları ve Bataklık Islahı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Menderes Taşkınları ve Bataklık Islahı fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Menderes Taşkınları ve Bataklık Islahı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 327) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_328', 'ottoman', 'Sınır Hayvan Kaçakçılığı', 'Kars Yaylaları', 'Yaylacıların koyun ve sığır sürülerini gümrüksüz olarak İran ve Gürcü pazarlarına kaçırdığı tespit edildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_gumruk_emini","name":"Gümrük Emini"}]', '[{"label":"Sınır karakollarını takviye et; yerel panayırlar kurarak hayvanın içeride satılmasını sağla.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Kaçakçılık önlendi; canlı hayvan ticareti payitahta et sağladı."},{"label":"Sınırı tamamen kapat; hayvan çıkaran köylüleri sürgüne yolla.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sınır Hayvan Kaçakçılığı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Sınır Hayvan Kaçakçılığı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Sınır Hayvan Kaçakçılığı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 328) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_329', 'ottoman', 'Bedevilerin Fıstık Bahçelerine Baskını', 'Halep Kırsalı', 'Çöl bedevileri gece baskınlarıyla meşhur Antep ve Halep fıstığı bahçelerini talan edip ağaçları kırıyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Süvari devriyeleri çıkar; bedevi reislerine sınır bekçiliği karşılığı tahsisat ver.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Bahçeler kurtarıldı; bedeviler yağmacılıktan koruyuculuğa geçti."},{"label":"Köylüler kendi bekçilerini tutsun; orduyu çöle sokma.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Bedevilerin Fıstık Bahçelerine Baskını nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Bedevilerin Fıstık Bahçelerine Baskını fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Bedevilerin Fıstık Bahçelerine Baskını meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 329) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_330', 'ottoman', 'Zeytincilerin Venedik Kumpanyasına İsyanı', 'Mora Vilayeti', 'Yerel zeytinyağı tüccarları İtalyan kumpanyasının fiyatları kırmasından bıkıp limandaki fıçıları ateşe verdi.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"İtalyan monopolünü kır; yerli kooperatif ambarları kurarak zeytinyağını doğrudan sat.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Mora zeytincisi hürriyete kavuştu; mahsul değerinde satıldı."},{"label":"Venedik kumpanyasını koru; isyancı köylüleri cezalandır.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Zeytincilerin Venedik Kumpanyasına İsyanı nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Zeytincilerin Venedik Kumpanyasına İsyanı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Zeytincilerin Venedik Kumpanyasına İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 330) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_331', 'ottoman', 'Keten Tarlalarının Daraltılması', 'Trabzon Kırsalı', 'Mısır ekimi yaygınlaşınca köylü donanmanın yelken bezi yaptığı keten ekimini tamamen terk etti.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Keten alım fiyatını iki katına çıkar; ekim yapan köylüye bedava tohum ve prim dağıt.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Tersane yelkensiz kalmadı; Karadeniz ketenciliği kurtarıldı."},{"label":"Zorla keten ektir; ekmeyenin tarlasına el koy.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Keten Tarlalarının Daraltılması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Keten Tarlalarının Daraltılması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Keten Tarlalarının Daraltılması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 331) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_332', 'ottoman', 'Pastırmacı Esnafının Tuz Sıkıntısı', 'Kayseri Vilayeti', 'Tuz Gölü mülteziminin tuz fiyatını üç katına çıkarması yüzünden kışlık pastırma ve sucuk basımı durdu.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"Tuz Gölü iltizamını fesh et; tuzu maktu ve ucuz fiyatla esnafa doğrudan tahsis et.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Et mamulleri üretimi kurtarıldı; gıda fiyatları ucuzladı."},{"label":"Mültezim mukavelesine meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla; hazine payını eksiltme.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Pastırmacı Esnafının Tuz Sıkıntısı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Pastırmacı Esnafının Tuz Sıkıntısı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Pastırmacı Esnafının Tuz Sıkıntısı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 332) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_333', 'ottoman', 'Yeraltı Zift Kaynaklarının İşletilmesi', 'Musul Sancağı', 'Tersane gemilerini kalafatlamak için kullanılan zift madenini bedeviler ateşe verip haraç istiyor.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Kuyu başına garnizon kurdur; zift çıkaran işçilere iyi yevmiye bağlayarak üretimi hızlandır.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Donanmanın zift ihtiyacı kesintisiz sağlandı; kuyular emniyette."},{"label":"Bedevilerin istediği harcı ödeyip zifti satın al.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Yeraltı Zift Kaynaklarının İşletilmesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Yeraltı Zift Kaynaklarının İşletilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Yeraltı Zift Kaynaklarının İşletilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 333) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_334', 'ottoman', 'Uskok Korsanlarının Sahil Baskınları', 'Bosna Serhattı', 'Hırvat kıyılarındaki Uskoklar, Adriyatik sahillerindeki Müslüman köylerini basıp esir topluyor.', '[{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Kaptan Paşa\'ya emret: Fırkateynlerle Uskok kalelerini bombala ve kıyı milisleri teşkil et.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Korsan yuvaları imha edildi; Adriyatik sahilleri huzura erdi."},{"label":"Avusturya\'ya diplomatik mektup yazıp bekleyin.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Uskok Korsanlarının Sahil Baskınları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Uskok Korsanlarının Sahil Baskınları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Uskok Korsanlarının Sahil Baskınları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 334) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_335', 'ottoman', 'Koyun Vebası ve Karantina Çadırları', 'Sivas Kırsalı', 'Doğudan gelen sürüler yüzünden İç Anadolu koyunlarının üçte biri öldü; et ve yapağı kıtlığı kapıda.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Sıkı yayla karantinası kur; hastalıklı sürüleri itlaf et ve zararı hazineden karşıla.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Salgın söndürüldü; köylünün kalan sürüsü kurtarıldı."},{"label":"Karantinayla uğraşmayın; eceli gelen ölür.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Koyun Vebası ve Karantina Çadırları nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Koyun Vebası ve Karantina Çadırları fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Koyun Vebası ve Karantina Çadırları meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 335) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_336', 'ottoman', 'Hanya ve Resmo Arasında Su Kemeri', 'Girit Kırsalı', 'Kurak dağ köyleri yaz aylarında susuzluk çekiyor; eski Venedik su yolunun ihyası istendi.', '[{"id":"char_suyolcu_ustasi","name":"Suyolcu Ustası"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"İstihkâmcıları gönder; kemerleri onar ve dağ köylerine tatlı su ulaştır.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Girit köylüsü devlete ısındı; zeytinlikler bol ürün verdi."},{"label":"Adanın merkezine su yeterlidir; dağlara masraf yapmayın.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Hanya ve Resmo Arasında Su Kemeri nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Hanya ve Resmo Arasında Su Kemeri fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Hanya ve Resmo Arasında Su Kemeri meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 336) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_337', 'ottoman', 'Dicle Üzerinde Kelek Taşımacılığı Vergisi', 'Bağdat Vilayeti', 'Keleklerle (şişirilmiş tulum sallar) buğday taşıyan gariplerden her iskelede haksız \'bâc\' harcı kesiliyor.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Adâletnâme neşret: Keleklerden mükerrer vergi alınmasını yasakla, tek iskele harcı koy.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Irak\'ta tahıl sevkiyatı hızlandı; Bağdat pazarı ucuzladı."},{"label":"İskele mültezimleri haklıdır; harca meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Dicle Üzerinde Kelek Taşımacılığı Vergisi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Dicle Üzerinde Kelek Taşımacılığı Vergisi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Dicle Üzerinde Kelek Taşımacılığı Vergisi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 337) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_338', 'ottoman', 'Şehzade Çiftliğinde Köylülerin Çalıştırılması', 'Manisa Sancağı', 'Saray kethüdaları, civar köylüleri bedelsiz \'angarya\' ile şehzade has bahçesinde çalıştırmaya kalkıştı.', '[{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Angaryayı kesinlikle men et! Çalışan her köylünün yevmiyesini saray bütçesinden ödet.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Şehzade adaleti daha tahta çıkmadan tebaanın gönlüne taht kurdu."},{"label":"Şehzadeye hizmet devlete hizmettir; köylü çalışsın.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Şehzade Çiftliğinde Köylülerin Çalıştırılması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Şehzade Çiftliğinde Köylülerin Çalıştırılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Şehzade Çiftliğinde Köylülerin Çalıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 338) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_339', 'ottoman', 'Çerkes Beylerinin İç Savaşları', 'Kafkasya Eteği', 'İki büyük Çerkes kabilesi kan davası yüzünden birbirini kırmaya başladı; sınır garnizonu tehdit altında.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Tarafsız kadı ve ulema heyeti gönder; kan bedellerini şeriat üzere hükme bağlayıp barıştır.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Kafkasya\'da barış sağlandı; kabileler devlete minnet duydu."},{"label":"Bırakın birbirlerini kırsınlar; zayıflamaları işimize gelir.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Çerkes Beylerinin İç Savaşları nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Çerkes Beylerinin İç Savaşları fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Çerkes Beylerinin İç Savaşları meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 339) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_340', 'ottoman', 'Ayanların Hususi Muhafız Birlikleri (Tüfekli Sarıca)', 'Taşra Teftişi', 'Taşra ayanları binlerce paralı sarıca askeri toplayarak sancak beylerinden daha güçlü hale geldi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Ferman sal: Ayanların hususi ordu kurması yasaktır; fazla sarıcaları devlet ordusuna devret.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Feodalleşme tehlikesi ezildi; merkezi nizam taşraya hâkim oldu."},{"label":"Ayanlar asayişi koruyor; ordularına tarafları divanda dinleyip makul bir tazminat ve rıza ile sulh bağla.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Ayanların Hususi Muhafız Birlikleri (Tüfekli Sarıca) meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Ayanların Hususi Muhafız Birlikleri (Tüfekli Sarıca) hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Ayanların Hususi Muhafız Birlikleri (Tüfekli Sarıca) gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 340) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_341', 'ottoman', 'Gümüş Yerine Çinko Alaşımlı Akçe Teklifi', 'Darbhane-i Âmire', 'Maliye krizinde bir kalpazan sarraf, darphane eminine çinko karıştırarak görünüşte parlak sahte para basmayı teklif etti.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Sarrafı ve rüşvetçi memurları ibret için idam et; sikkenin saflığı devletin şerefidir.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Para kalpazanlardan temizlendi; Osmanlı sikkesine güven arttı."},{"label":"Bir sefere mahsus basımına izin ver; maaşları çıkaralım.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Gümüş Yerine Çinko Alaşımlı Akçe Teklifi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Gümüş Yerine Çinko Alaşımlı Akçe Teklifi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Gümüş Yerine Çinko Alaşımlı Akçe Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 341) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_342', 'ottoman', 'Koyun Tedarikinde Canbaz Grevi', 'İstanbul Kasapbaşı', 'Canbazlar (toptancı tüccarlar) fiyatları yükseltmek için Rumeli\'den gelen sürüleri Edirne\'de bekletiyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Zaptiyelerle sürüleri payitahta zorla sevk et, narh üzerinden halka dağıt.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Karaborsa çetesi kırıldı; payitahtta et fiyatları düştü."},{"label":"Canbazların istediği fahiş fiyatı narh olarak tanı.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Koyun Tedarikinde Canbaz Grevi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Koyun Tedarikinde Canbaz Grevi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Koyun Tedarikinde Canbaz Grevi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 342) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_343', 'ottoman', 'İngilizlerin Yünlü Kumaş Dampingi', 'Galata Rıhtımı', 'İngiliz kumpanyası maliyetinin altına kumaş satarak yerli çuha tezgâhlarını iflasa sürüklüyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Yerli çuhayı koruyan gümrük vergisi koy; askerin ve sarayın kumaşını yerli esnaftan al.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Yerli dokuma atölyeleri kurtuldu; sanayi dışa teslim olmadı."},{"label":"Ucuz kumaştır; bırakın İngilizler satsın.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; İngilizlerin Yünlü Kumaş Dampingi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; İngilizlerin Yünlü Kumaş Dampingi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; İngilizlerin Yünlü Kumaş Dampingi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 343) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_344', 'ottoman', 'Terazilerde Hile Yapan Un Kapanı Tacirleri', 'Kaza İhtisabı', 'Un kapanındaki kantarın kancasına kurşun dökülerek her çuvalda 5 okka eksik un tartıldığı belgelendi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Hileli kantarları meydanda kırdır; simsarları teşhir edip sürgün cezası ver.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Ölçü ve tartıda dürüstlük sağlandı; fırıncılar tam un aldı."},{"label":"Küçük bir ceza kesip kantarları iade et.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Terazilerde Hile Yapan Un Kapanı Tacirleri nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Terazilerde Hile Yapan Un Kapanı Tacirleri fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Terazilerde Hile Yapan Un Kapanı Tacirleri meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 344) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_345', 'ottoman', 'Yabancı Tacirlerin Şahsi Vergi Muafiyeti Beratı', 'Maliye Kalemi', 'Venedik ve Ceneviz elçileri, zengin tüccarlarının iç gümrüklerden tamamen muaf tutulması için rüşvet dağıtıyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Rüşvet teklif eden elçilik memurunu sınır dışı et; ahidnâme dışı muafiyet tanımaz ferman sal.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Milli ticaret dengesi korundu; yabancı imtiyaz hevesi kursakta kaldı."},{"label":"Muafiyeti verip karşılığında saraya yüklü \'hediyeler\' kabul et.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Yabancı Tacirlerin Şahsi Vergi Muafiyeti Beratı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Yabancı Tacirlerin Şahsi Vergi Muafiyeti Beratı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Yabancı Tacirlerin Şahsi Vergi Muafiyeti Beratı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 345) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_346', 'ottoman', 'Tuz Toptancılarının İttifakı', 'Selanik Çarşısı', 'Selanik tuzlalarından çıkan tuzu toptan kapatan sarraflar piyasaya tuz vermeyerek fiyatı beşe katladı.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Tuz depolarına el koy, narh üzerinden halka sat; stokçuları zindana at.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Tuz karaborsası yıkıldı; peynir ve zeytin üreticisi kurtuldu."},{"label":"Mülkiyet hürriyetidir; stokçuların malına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Tuz Toptancılarının İttifakı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Tuz Toptancılarının İttifakı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Tuz Toptancılarının İttifakı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 346) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_347', 'ottoman', 'Eski Sikkelerin Toplanarak Yenilenmesi', 'Darbhane Kalemi', 'Piyasada aşınmış, yazıları silinmiş sikkelerin toplanarak tam gramajlı yeni kuruşlarla değiştirilmesi teklif edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Sikke tasfiyesini başlat; halkın elindeki aşınmış parayı değer kaybı olmadan birebir yenile.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Para nizamı tertemiz oldu; tebaa devletine şükran sundu."},{"label":"Eski paraları %20 kırparak al; hazine kâr etsin.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Eski Sikkelerin Toplanarak Yenilenmesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Eski Sikkelerin Toplanarak Yenilenmesi fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Eski Sikkelerin Toplanarak Yenilenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 347) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_348', 'ottoman', 'Koza Alımlarında İtalyan Avansı', 'Bursa İpekçileri', 'Floransalı tüccarlar köylüye kıştan avans verip koza mahsulünü yarı fiyatına bağladı; yerli tezgâhlar ipeksiz.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Avans usulünü yerli esnaf sandığı üzerinden kur; yabancının çiftçiyi ipotek altına almasını yasakla.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Köylü tefeciden kurtuldu; ipek yerli tezgâhlara aktı."},{"label":"Köylünün kendi rızasıdır; serbest ticarete mani olma.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Koza Alımlarında İtalyan Avansı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Koza Alımlarında İtalyan Avansı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Koza Alımlarında İtalyan Avansı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 348) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_349', 'ottoman', 'Zeytinyağı Sabunlarında Hayvansal Yağ Hilesi', 'İskenderun Gümrüğü', 'Antakya sabunlarına domuz yağı veya leş iç yağı karıştırılıp Halep pazarına sürüldüğü ihbar edildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"İmalathaneleri bastır; sahte yağları imha ettir ve sabuncuları meslekten men et.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Helal üretim nizamı korundu; sabun ihracatı itibar kazandı."},{"label":"Ucuz sabundur; fakir fukara alır deyip divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Zeytinyağı Sabunlarında Hayvansal Yağ Hilesi hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Zeytinyağı Sabunlarında Hayvansal Yağ Hilesi hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Zeytinyağı Sabunlarında Hayvansal Yağ Hilesi gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 349) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_350', 'ottoman', 'Çiftçiden Peşin Vergi İstenmesi (Avan-ı Harac)', 'Taşra Maliyesi', 'Hasat mevsimine üç ay varken defterdar ordunun parası bittiği için köylüden peşin vergi tahsil etmek istiyor.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ferman çıkar: Hasat olmadan harac alınamaz! Köylüyü tefecinin kucağına itmeyin.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Çiftçi tefeciye borçlanmaktan kurtuldu; hasat güvenceye alındı."},{"label":"Ordu bekleyemez; vergiyi peşin toplayın.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Çiftçiden Peşin Vergi İstenmesi (Avan-ı Harac) nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Çiftçiden Peşin Vergi İstenmesi (Avan-ı Harac) fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Çiftçiden Peşin Vergi İstenmesi (Avan-ı Harac) meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 350) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_351', 'ottoman', 'Demir Kıtlığı ve Nal Fiyatları', 'Payitaht Nalbandları', 'Madenlerden demir gelmeyince nal ve çivi fiyatları fırladı; yük arabaları çalışamaz oldu.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Samakov madenlerinden derhal devlet eliyle demir sevkiyatı yaptır; nal fiyatını sabitle.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Şehir içi taşımacılık durmadı; arabalar yollara döndü."},{"label":"Nalbandlar hurda demirleri eritip idare etsin.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Demir Kıtlığı ve Nal Fiyatları nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Demir Kıtlığı ve Nal Fiyatları fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Demir Kıtlığı ve Nal Fiyatları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 351) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_352', 'ottoman', 'Balmumu Kaçakçılığı', 'Ege Limanları', 'Kiliselerin ve gemilerin aydınlatılmasında kullanılan bal mumu kaçak yollarla Malta\'ya satılıyor.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Balmumu ihracatına geçici yasak koy; tersane ve ibadethanelerin ihtiyacını karşıla.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Aydınlatma krizi önlendi; kalyonlar fenerine kavuştu."},{"label":"İhracatı kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı; tüccar kazansın.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Balmumu Kaçakçılığı hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Balmumu Kaçakçılığı hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Balmumu Kaçakçılığı gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 352) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_353', 'ottoman', 'Buğday Değirmenlerinde Kayıp Oranı Hilesi', 'Konya Defterdarlığı', 'Değirmencilerin köylünün buğdayını öğütürken %15 \'toz payı\' keserek unun bir kısmını çaldığı anlaşıldı.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Kayıp payını kanunen %3 ile sınırla; hırsızlık yapan değirmenleri mühürle.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Köylü ununu tam teslim aldı; değirmen soygunu durduruldu."},{"label":"Değirmenin masrafı çoktur; köylüyle değirmenci arasına girme.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Buğday Değirmenlerinde Kayıp Oranı Hilesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Buğday Değirmenlerinde Kayıp Oranı Hilesi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Buğday Değirmenlerinde Kayıp Oranı Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 353) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_354', 'ottoman', 'Meyve Bahçelerine Dadanan Karıncalar', 'İstanbul Şehremaneti', 'Boğaz ve Eyüp yamaçlarındaki elma ve erik bahçelerini karınca bastı; ulemadan fetva alıp kireçleme yapılması önerildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ziraat fermanı çıkar: Ağaç diplerine kireç çekilsin; mahsulü korumak şer\'an caizdir.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Ağaçlar kurtarıldı; payitaht meyveye doydu."},{"label":"Karıncaya kıymak günahtır deyip hiçbir tedbir aldırma.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Meyve Bahçelerine Dadanan Karıncalar nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Meyve Bahçelerine Dadanan Karıncalar fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Meyve Bahçelerine Dadanan Karıncalar meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 354) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_355', 'ottoman', 'Sahte Baharat ve Çürük Zencefil', 'Halep Kervansarayı', 'Mısır üzerinden gelen çuvalların içine talaş ve kırmızı toprak karıştırıldığı tespit edildi.', '[{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Sahte baharatları yak; Mısır tüccarına ağır tazminat kes ve dürüst esnafı koru.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Tıbbi ve mutfak güvenliği sağlandı; sahteciler cezalandırıldı."},{"label":"Zararı tüccara yükleme; ucuza fakire satılsın.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Sahte Baharat ve Çürük Zencefil hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Sahte Baharat ve Çürük Zencefil hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Sahte Baharat ve Çürük Zencefil gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 355) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_356', 'ottoman', 'Madeni Para Eritip Külçe Yapan Kuyumcular', 'Darbhane-i Âmire', 'Devletin bastığı kuruşları eritip gümüş tabak ve kupa yapan kuyumcular yüzünden piyasada para kalmadı.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Sikke eritilmesini kesinlikle yasakla; eritilmiş külçelere el koy ve darphaneye iade et.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Para darlığı çözüldü; gümüş sikkeler tedavülde kaldı."},{"label":"Kuyumcuların sanatıdır; gümüşü nereden bulurlarsa bulsunlar.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Madeni Para Eritip Külçe Yapan Kuyumcular nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Madeni Para Eritip Külçe Yapan Kuyumcular fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Madeni Para Eritip Külçe Yapan Kuyumcular meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 356) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_357', 'ottoman', 'Gemi Kerestesi Karaborsası', 'Sinop Limanı', 'Orman mültezimleri kalyonluk meşe kütüklerini devlete vermek yerine yabancı tüccarlara gizlice satıyor.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kereste kaçakçılarını divana celbet; tüm kütükleri müsadere edip tersaneye çek.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Kalyon inşası hızlandı; devlet ormanları korundu."},{"label":"Tersane bütçesini artırıp mültezimden pahalıya satın al.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Gemi Kerestesi Karaborsası nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Gemi Kerestesi Karaborsası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Gemi Kerestesi Karaborsası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 357) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_358', 'ottoman', 'Maya Kıtlığı ve Ekşiyen Ekmekler', 'İstanbul Fırınları', 'Başkent fırınlarında ekmek mayası bozulduğu için çıkan ekmekler acı ve yenmez hale geldi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bursa ve Edirne\'den acil saf ekmek mayası getirt; fırınlara bedelsiz dağıt.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Ekmeğin lezzeti geri geldi; halk rahat nefes aldı."},{"label":"Fırıncılar kendi mayasını üretsin; divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Maya Kıtlığı ve Ekşiyen Ekmekler sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Maya Kıtlığı ve Ekşiyen Ekmekler hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Maya Kıtlığı ve Ekşiyen Ekmekler gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 358) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_359', 'ottoman', 'İran Şiir ve Felsefe Kitapları Vergisi', 'Basra Gümrüğü', 'Şah\'ın sarayından gelen nadide tezhibli ve şiir kitaplarına fahiş sansür ve gümrük konması istendi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_gumruk_emini","name":"Gümrük Emini"}]', '[{"label":"İlim ve edebiyat serbestçe girsin; kitaplara sadece cüzi maktu resim uygula.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Kültür ve ilim teatisine engel olunmadı; kütüphaneler zenginleşti."},{"label":"Hepsini sınırda yaktır; yabancı fikirler girmesin.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve İran Şiir ve Felsefe Kitapları Vergisi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve İran Şiir ve Felsefe Kitapları Vergisi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve İran Şiir ve Felsefe Kitapları Vergisi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 359) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_360', 'ottoman', 'Lonca Dışı Seyyar Satıcıların Durumu', 'Dîvân-ı Hümâyûn', 'Dükkân açamayan fakir seyyar esnafın sokaklarda helva ve şerbet satması loncalar tarafından yasaklatılmak isteniyor.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Muvakkat ruhsat ver: Lonca harcı almadan belirli meydanlarda satış yapmalarına izin ver.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Fukara ekmeğini kazandı; seyyar esnaf korundu."},{"label":"Loncaların tekelini koru; bütün seyyar tezgâhları zabıtaya kırdır.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Lonca Dışı Seyyar Satıcıların Durumu nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Lonca Dışı Seyyar Satıcıların Durumu fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Lonca Dışı Seyyar Satıcıların Durumu meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 360) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_361', 'ottoman', 'Hafif Sahra Topu (Balyemez) İcadı', 'Tophane Dökümhanesi', 'Bir döküm ustası atlarla kolay taşınabilen, seri ateş eden bronz sahra topları geliştirdi; seri üretim bütçe istiyor.', '[{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Bütçeyi tahsis et; orduyu hantal kuşatma toplarından kurtarıp hareketli sahra topçuluğuna geçir.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Meydan muharebelerinde mutlak üstünlük kazanıldı; düşman hatları yarıldı."},{"label":"Eski toplarımız gayet iyidir; yeni icatlara altın dökülmez.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Hafif Sahra Topu (Balyemez) İcadı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Hafif Sahra Topu (Balyemez) İcadı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Hafif Sahra Topu (Balyemez) İcadı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 361) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_362', 'ottoman', 'Esame Satışı ve Sahte Nefer Maaşları', 'Yeniçeri Ocağı', 'Ölen askerlerin maaş cüzdanlarının (esame) sokaktaki esnafa ve sarraflara satılarak haksız ulufe çekildiği kanıtlandı.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Tüm ocağı bizzat yoklamaya çek; esame ticaretini yasakla ve sahte kayıtları sil.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Hazineden çekilen haram paralar kesildi; ordu mevcudu netleşti."},{"label":"Ocağın tepkisini çekme; yoklamayı yüzeysel yapıp geçiştir.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Esame Satışı ve Sahte Nefer Maaşları nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Esame Satışı ve Sahte Nefer Maaşları fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Esame Satışı ve Sahte Nefer Maaşları meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 362) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_363', 'ottoman', 'Serhad Gazilerinin Ganimet İhtilafı', 'Belgrad Sınırı', 'Avusturya sınırındaki kaleyi alan gaziler ile yeniçeriler ganimet bölüşümünde kılıç kılıca geldi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Kanunnâme-i Âl-i Osman\'ı açtır; gazilere hak ettiği payı eksiksiz dağıt, disiplinsiz neferleri ayır.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Adaletle taksim yapıldı; serhad boylarında fitne söndürüldü."},{"label":"Ganimetin tamamını yeniçeriye ver; ocaklı küsmesin.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Serhad Gazilerinin Ganimet İhtilafı nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Serhad Gazilerinin Ganimet İhtilafı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Serhad Gazilerinin Ganimet İhtilafı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 363) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_364', 'ottoman', 'Kazak Şaykalarının Kefe Limanını Basması', 'Kırım Hanlığı', 'Kazak botları gece sisi altında Kefe limanına girip üç buğday gemisini yaktı ve esir aldı.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Azak kalesini tahkim et, nehir ağzına zincir çektir ve Kazak inlerini vurdur.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Karadeniz kapısı kilitlendi; ticaret gemileri emniyete kavuştu."},{"label":"Kırım Hanı kendi sahillerini kendi korusun.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kazak Şaykalarının Kefe Limanını Basması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kazak Şaykalarının Kefe Limanını Basması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kazak Şaykalarının Kefe Limanını Basması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 364) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_365', 'ottoman', 'Forsaların Tifo Salgını Yüzünden Kürek Çekememesi', 'Tersane Zindanı', 'Kadırgalardaki kürek mahkumları tifodan kırılıyor; sefere çıkacak filoda kürek çekecek can kalmadı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Gemi hekimlerini görevlendir; forsaları karaya çıkarıp revirde tedavi ettir ve tayınlarını artır.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Forsalar ayağa kalktı; donanma tam mevcuduyla Akdeniz\'e açıldı."},{"label":"Ölenleri denize atın; köylerden zorla yeni forsalar toplayın.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Forsaların Tifo Salgını Yüzünden Kürek Çekememesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Forsaların Tifo Salgını Yüzünden Kürek Çekememesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Forsaların Tifo Salgını Yüzünden Kürek Çekememesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 365) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_366', 'ottoman', 'Geri Çekilen Ordunun Ağırlıkları Yakması', 'Kafkasya Cephesi', 'Şiddetli karda geri çekilen orduda cephane arabaları yolda kaldı; serdar arabaları yakmayı teklif ediyor.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Yakma emri verme! Süvarileri koşum takımına verdirip cephaneyi bin bir zahmetle kurtar.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Toplar ve mühimmat kurtarıldı; ordu Erzurum\'a sağlam vardı."},{"label":"Arabaları ateşe verip sadece canınızı kurtarın.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Geri Çekilen Ordunun Ağırlıkları Yakması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Geri Çekilen Ordunun Ağırlıkları Yakması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Geri Çekilen Ordunun Ağırlıkları Yakması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 366) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_367', 'ottoman', 'Rodos Şövalyelerinin Tuzak Gemisi', 'Akdeniz Filosu', 'Terk edilmiş gibi görünen bir korsan kalyonunun içinde barut tuzakları olduğu leventler tarafından fark edildi.', '[{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Gemiye yaklaşmayın; uzaktan top ateşiyle havaya uçurun.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Tuzak boşa çıkarıldı; tek bir levent burnu kanamadan kurtuldu."},{"label":"Ganimet kaçmasın; süratle bordalayın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Rodos Şövalyelerinin Tuzak Gemisi hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Rodos Şövalyelerinin Tuzak Gemisi hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Rodos Şövalyelerinin Tuzak Gemisi gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 367) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_368', 'ottoman', 'Çöl Süvarilerinin Kalkan ve Zırh İhtiyacı', 'Bağdat Hududu', 'Safevi okçularına karşı sipahilerimizin zırhlarının ağır kaldığı, hafif çelik zırhların dökülmesi gerektiği bildirildi.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Şam çeliğiyle hafif örme zırhlar yaptır; süvarileri hareketli ve korunaklı kıl.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Süvarilerimiz çölde rüzgâr gibi esti; oklar zırhlardan sekti."},{"label":"Ağır zırhlara devam edin; masraf çıkarmayın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Çöl Süvarilerinin Kalkan ve Zırh İhtiyacı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Çöl Süvarilerinin Kalkan ve Zırh İhtiyacı fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Çöl Süvarilerinin Kalkan ve Zırh İhtiyacı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 368) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_369', 'ottoman', 'Leh Kazaklarının Su Kuyusuna At Leşi Atması', 'Kamaniçe Kalesi', 'Kuşatma altındaki kalenin içme suyu kuyuları düşman tarafından kirletildi; kalede dizanteri baş gösterdi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kalenin kayalık dibinden yeni derin kuyu kazdır, şifalı kireçle suları arıt.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Asker temiz suya kavuştu; kale aylarca kahramanca direndi."},{"label":"Su kalmadı; kaleyi düşmana teslim edin.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Leh Kazaklarının Su Kuyusuna At Leşi Atması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Leh Kazaklarının Su Kuyusuna At Leşi Atması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Leh Kazaklarının Su Kuyusuna At Leşi Atması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 369) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_370', 'ottoman', 'Köprü Dubalarının Buzu Yaramaması', 'Tuna Muhafızlığı', 'Tuna donunca sürüklenen buz kütleleri ordunun geçeceği duba köprüyü parçaladı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"İstihkâmcılarla buz kırıcı ağır şaykalar sevk et; köprüyü zincirlerle sağlamlaştır.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Köprü korundu; ordu karşı kıyıya intizamla geçti."},{"label":"Buzlar eriyene kadar seferi durdurup bekleyin.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köprü Dubalarının Buzu Yaramaması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Köprü Dubalarının Buzu Yaramaması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Köprü Dubalarının Buzu Yaramaması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 370) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_371', 'ottoman', 'Barutun Güherçile Depolarına Sızan Su', 'Payitaht Baruthanesi', 'Bakırköy baruthanesinin depoları sel baskınında ıslandı; binlerce kantar barut çamur oldu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Derhal fırınlarda kurutma ve yeniden saflaştırma başlat; yeni su hendekleri aç.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Barutun büyük kısmı kurtarıldı; üretim kesintiye uğramadı."},{"label":"Islak barutu atın; Avrupa\'dan fahiş fiyata ithal barut alın.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Barutun Güherçile Depolarına Sızan Su nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Barutun Güherçile Depolarına Sızan Su fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Barutun Güherçile Depolarına Sızan Su meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 371) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_372', 'ottoman', 'Gönüllü Serhad Süvarilerinin Maaş Talebi', 'Bosna Alayları', 'Yıllardır sınırda kendi atıyla savaşan Bosnalı gaziler, ulufe defterine düzenli maaşlı kaydedilmek istiyor.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Liyakatli gazileri \'Gönüllüyan\' defterine kaydet; maktu dirlik bağla.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Sınırın en sadık süvarileri devlete bağlandı; serhad çelik kalkan oldu."},{"label":"Bütçe yoktur; gazilik Allah rızası içindir deyip reddet.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Gönüllü Serhad Süvarilerinin Maaş Talebi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Gönüllü Serhad Süvarilerinin Maaş Talebi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Gönüllü Serhad Süvarilerinin Maaş Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 372) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_373', 'ottoman', 'Kalyonların Yelken Bezinde Hileli Dokuma', 'Tersane-i Âmire', 'Müteahhitlerin yelken bezine ince pamuk karıştırıp ilk fırtınada yırtılmasına sebep olduğu ortaya çıktı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Müteahhidin servetini müsadere et, gemilere sağlam saf kenevir yelkenler diktir.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Donanmanın rüzgâr tutuşu güçlendi; yolsuz müteahhit ibret oldu."},{"label":"Yelkenleri yamayın; yeni sipariş masraflıdır.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Kalyonların Yelken Bezinde Hileli Dokuma hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Kalyonların Yelken Bezinde Hileli Dokuma hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Kalyonların Yelken Bezinde Hileli Dokuma gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 373) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_374', 'ottoman', 'Tüfekli Sarıcaların Maaş Bahanesiyle Şehri Kuşatması', 'Sıvas Kışlası', 'Maaşları iki ay geciken sarıca birlikleri kışladan çıkıp Sivas çarşısını yağmalamaya kalkıştı.', '[{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Sancak beyine emret: Sadık sipahilerle asileri çevir, elebaşıları as ve hak sahiplerinin maaşını öde.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Yağma durduruldu; asker hakkını alırken zorbalar cezalandırıldı."},{"label":"Asilerin her istediği haracı ödeyip şehirden çıkmalarına yalvar.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Tüfekli Sarıcaların Maaş Bahanesiyle Şehri Kuşatması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Tüfekli Sarıcaların Maaş Bahanesiyle Şehri Kuşatması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tüfekli Sarıcaların Maaş Bahanesiyle Şehri Kuşatması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 374) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_375', 'ottoman', 'Göl Kıyısındaki Barut Değirmeninin Patlaması', 'Van Kalesi', 'Baruthanedeki su değirmeninin sürtünmeden alev almasıyla Van cephaneliği havaya uçtu.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Diyarbakır\'dan süratle barut naklet ve su altında çalışan emniyetli değirmen kurdur.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Doğu hududu barutsuz kalmadı; emniyet tedbirleri yenilendi."},{"label":"Cephanelik tamirini erteleyin; İran\'la barış vardır.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Göl Kıyısındaki Barut Değirmeninin Patlaması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Göl Kıyısındaki Barut Değirmeninin Patlaması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Göl Kıyısındaki Barut Değirmeninin Patlaması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 375) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_376', 'ottoman', 'Yeniçerilerin Kalenin İçindeki Kiliseyi Meyhaneye Çevirmesi', 'Mora Garnizonu', 'Garnizon neferleri fethedilen kalenin koruma altındaki tarihi şapeline içki sokup tebaayı taciz etti.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Ahidnâmeye sadık kal! Şapeli temizlet, gayrimüslim tebaadan özür dile ve saygısız neferleri cezalandır.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"İslam\'ın mabet dokunulmazlığı gösterildi; tebaa devlete sadakat sundu."},{"label":"Asker kılıç hakkını kullanmıştır; zimmilere divan gözetiminde tarafları meşverete davet edip orta yolu bulyın de.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Yeniçerilerin Kalenin İçindeki Kiliseyi Meyhaneye Çevirmesi meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Yeniçerilerin Kalenin İçindeki Kiliseyi Meyhaneye Çevirmesi hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Yeniçerilerin Kalenin İçindeki Kiliseyi Meyhaneye Çevirmesi gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 376) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_377', 'ottoman', 'Kış Seferinde Askerin Kürk ve Çizme İhtiyacı', 'Kars Serhattı', 'Erzurum ve Kars dağlarında kar diz boyunu aştı; askere yün keçe ve deri çizme yetiştirilemezse ordu donacak.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"}]', '[{"label":"Hazineyi aç; Konya ve Kayseri debbağlarından on binlerce kürk ve çizme satın aldırıp ulaştır.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Tek bir askerin ayağı donmadı; ordu kışta zafere yürüdü."},{"label":"Asker dayanıklıdır; ayaklarına bez sarıp idare etsinler.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kış Seferinde Askerin Kürk ve Çizme İhtiyacı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kış Seferinde Askerin Kürk ve Çizme İhtiyacı fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kış Seferinde Askerin Kürk ve Çizme İhtiyacı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 377) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_378', 'ottoman', 'Venedik Balyozunun Korsan Fidyesi Pazarlığı', 'Akdeniz Açıkları', 'Esir edilen Venedik amirali için 100 bin altın fidye teklif edildi; Kaptan Paşa parayı hazineye vermek istiyor.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Fidyeyi al, parayı donanma kalyonlarının modernizasyonuna harca ve amirali serbest bırak.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Hazine altınla doldu; donanmaya yepyeni kalyonlar katıldı."},{"label":"Fidyeyi reddet; amirali forsa olarak küreğe çektir.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Venedik Balyozunun Korsan Fidyesi Pazarlığı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Venedik Balyozunun Korsan Fidyesi Pazarlığı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Venedik Balyozunun Korsan Fidyesi Pazarlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 378) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_379', 'ottoman', 'Ocak Ağalarının Kendi Aralarında Hizipleşmesi', 'Yeniçeri Ağası', 'Turnacıbaşı ile Kul Kethüdası taraftarları kışlada silah çekip çatıştı; payitahtta kan döküldü.', '[{"id":"char_yeniceri_agasi","name":"Yeniçeri Ağası"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"İki ağayı da derhal görevden al, sürgüne yolla ve ocak başına tarafsız demir disiplinli bir zabit ata.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Ocak içi anarşi söndürüldü; saray otoritesi yeniden kuruldu."},{"label":"Ağalara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla; birbirlerini dengelesinler diye izle.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ocak Ağalarının Kendi Aralarında Hizipleşmesi sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Ocak Ağalarının Kendi Aralarında Hizipleşmesi meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Ocak Ağalarının Kendi Aralarında Hizipleşmesi gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 379) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_380', 'ottoman', 'Kuşatma Toplarının Çamura Batması', 'Hotin Kalesi Önleri', 'Dinyester nehrinin taşmasıyla devasa şahi toplar bataklığa gömüldü; düşman süvarisi hücuma geçti.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Yeniçeri ve sipahiyi kenetle; kahramanca savunma hattı kurarak topları kütüklerle çekip kurtar.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Toplar kurtarıldı ve düşman süvarisi güllelerle biçildi."},{"label":"Topları bırakıp mevzilere geri kaçın.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kuşatma Toplarının Çamura Batması nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kuşatma Toplarının Çamura Batması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kuşatma Toplarının Çamura Batması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 380) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_381', 'ottoman', 'Lehistan ile Gizli İttifak Müzakeresi', 'Reisülküttab Kalemi', 'Leh kralı, Rus Çarlığı\'nın güneye inmesini engellemek için Osmanlı ile ortak savunma paktı imzalamak istiyor.', '[{"id":"char_reisulkuttab","name":"Reisülküttab"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Paktı imzala; kuzeyde tampon bir güç tutarak Karadeniz\'in güvenliğini garantiye al.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Kuzey sınırında çelik diplomasi örüldü; Rus ilerleyişi durduruldu."},{"label":"Lehlilere güvenilmez; teklifi reddedip tek başımıza bekleyelim.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Lehistan ile Gizli İttifak Müzakeresi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Lehistan ile Gizli İttifak Müzakeresi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Lehistan ile Gizli İttifak Müzakeresi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 381) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_382', 'ottoman', 'Saray Masraflarının Şeffaf Denetimi', 'Topkapı Sarayı Harem Dairesi', 'Defterdar, padişahın şahsi harcamalarının da divan defterine kaydedilmesini ve israfın kısılmasını arz etti.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Cesur defterdarı tebrik et; saray harcamalarını sınırlayıp millete örnek ol.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Hükümdarın adaleti bütçeyi kurtardı; tebaa padişahına hayran kaldı."},{"label":"Sultanın harcaması sorgulanamaz! Defterdarı azlet.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Saray Masraflarının Şeffaf Denetimi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Saray Masraflarının Şeffaf Denetimi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Saray Masraflarının Şeffaf Denetimi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 382) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_383', 'ottoman', 'Gâvur Parasıyla Hacca Gitme Fetvası', 'Şeyhülislam Kapısı', 'Tüccarların Venedik altınıyla hacca gidip gidemeyeceği tartışıldı; mutaassıplar paraların denize dökülmesini istedi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Hikmetli fetva ver: Para bir mübadele vasıtasıdır; helal kazanıldıysa ibadete mani değildir.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Taassup aşıldı; hacca gidecek tüccarlar rahat nefes aldı."},{"label":"Yabancı sikkeyi haram say; hacıların paralarını müsadere et.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Gâvur Parasıyla Hacca Gitme Fetvası nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Gâvur Parasıyla Hacca Gitme Fetvası fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Gâvur Parasıyla Hacca Gitme Fetvası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 383) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_384', 'ottoman', 'Dirliklerin Rüşvetle Dağıtılmasının Önlenmesi', 'Sadaret Arşivi', 'Sadrazam kethüdasının tımar ve zeametleri en yüksek rüşveti veren ağalara sattığı belgelendi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"}]', '[{"label":"Kethüdayı derhal azlet ve mallarını müsadere et; dirlikleri kılıç hakkı olan gazilere ver.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Tımar nizamı liyakate kavuştu; ordu safları hakiki yiğitlerle doldu."},{"label":"Kethüda güçlü bir ailedendir; rüşvetin bir kısmını hazineye alıp olayı kapat.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Dirliklerin Rüşvetle Dağıtılmasının Önlenmesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Dirliklerin Rüşvetle Dağıtılmasının Önlenmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Dirliklerin Rüşvetle Dağıtılmasının Önlenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 384) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_385', 'ottoman', 'Mühendislik ve Hendese Talebeleri', 'Enderun Mektebi', 'Tersane ve top dökümü için hendese (geometri) bilen mühendisler yetiştirilmek üzere Mühendishane kurulması teklif edildi.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Bütçe ayır; Mühendishane-i Bahrî-i Hümâyûn\'u kurdur ve Avrupa\'dan aletler getirt.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Modern askeri mühendislik temelleri atıldı; ordumuz ilimle donandı."},{"label":"Eski ustaların tecrübesi kafidir; mektebe lüzum yok.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Mühendislik ve Hendese Talebeleri hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Mühendislik ve Hendese Talebeleri hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Mühendislik ve Hendese Talebeleri gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 385) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_386', 'ottoman', 'Batı Matbuatının Takibi', 'Bab-ı Âli Tercüme Odası', 'Avrupa gazetelerinde Osmanlı aleyhine yapılan neşriyatın takip edilmesi ve mukabil diplomatik risaleler yazılması önerildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Matbuat dairesi kur; hakikatleri anlatan Fransızca ve Latince bültenler bastır.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Haklı davamız dünyaya duyuruldu; kara propaganda boşa çıkarıldı."},{"label":"Kâfirlerin gazetesini okumak da yazmak da fuzulidir; tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Batı Matbuatının Takibi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Batı Matbuatının Takibi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Batı Matbuatının Takibi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 386) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_387', 'ottoman', 'Çiçek Aşısının Halka Ücretsiz Uygulanması', 'Hekimbaşılık', 'Geleneksel Türk usulü çiçek aşısının payitahttaki tüm çocuklara cerrahlar eliyle bedelsiz vurulması teklif edildi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Ferman çıkar: Her mahallede aşı çadırları kurulsun; masrafı hazineden karşılansın.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Çiçek salgını önlendi; binlerce sabi ölümden kurtuldu."},{"label":"Aşı yabancı müdahaledir; kadere rıza göstersinler.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Çiçek Aşısının Halka Ücretsiz Uygulanması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Çiçek Aşısının Halka Ücretsiz Uygulanması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Çiçek Aşısının Halka Ücretsiz Uygulanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 387) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_388', 'ottoman', 'Emekli Vezirlere Verilen Hasların Denetimi', 'Divan Meclisi', 'Emekli olmuş paşaların hala binlerce köylünün gelirini şahsi servet gibi harcadığı tespit edildi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Fazla has arazilerini hazineye geri al; emekli paşalara sadece yetecek kadar maaş bağla.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Devlet arazisi kurtarıldı; köylü nefes aldı, bütçe fazlası oluştu."},{"label":"Eski vezirlerin hatırını say; arazilerine meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Emekli Vezirlere Verilen Hasların Denetimi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Emekli Vezirlere Verilen Hasların Denetimi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Emekli Vezirlere Verilen Hasların Denetimi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 388) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_389', 'ottoman', 'Yunan İhtilalcilerine Silah Taşıyan Rus Gemisi', 'Mora İsyanı İstihbaratı', 'Boğaz\'dan \'buğday yüklü\' diye geçen bir Rus kalyonunun sintinesinde binlerce tüfek ve mermi yakalandı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Silahlara derhal el koy, gemiyi tutukla ve Rus çarına sert nota ver.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Büyük bir isyan silahı ele geçirildi; devlet egemenliği çiğnetilmedi."},{"label":"Savaş çıkmasın diye geminin geçişine yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Yunan İhtilalcilerine Silah Taşıyan Rus Gemisi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Yunan İhtilalcilerine Silah Taşıyan Rus Gemisi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Yunan İhtilalcilerine Silah Taşıyan Rus Gemisi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 389) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_390', 'ottoman', 'Gayrimüslim Vakıflarının Hukuki Teminatı', 'Şeyhülislamlık', 'Rum ve Ermeni cemaatlerinin yetimhanelerine ait gayrimenkullerin yerel zorbalarca gasp edilmesine karşı ferman istendi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Ahidnâme-i Hümâyun\'u tazele: Gayrimüslim vakfına el uzatan doğrudan devlete saldırmış sayılır.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Zimmî tebaa devlete sadakatle bağlandı; Batı\'nın müdahale kozu kırıldı."},{"label":"Müslümanlar dururken gayrimüslim vakfını korumak için paşaları karşına alma.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Gayrimüslim Vakıflarının Hukuki Teminatı nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Gayrimüslim Vakıflarının Hukuki Teminatı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gayrimüslim Vakıflarının Hukuki Teminatı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 390) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_391', 'ottoman', 'Padişah Kızlarının Cihaz (Çeyiz) Masrafları', 'Bab-ı Hümayun', 'Saray sultanlarının evlilik çeyizi için halktan \'ihzariye\' adı altında zorla altın toplanması teklif edildi.', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Ferman çıkar: Düğün masrafı için halktan bir akçe dahi alınamaz! Masrafı şahsi mülkten karşıla.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Halk üzerindeki haksız vergi kalktı; padişahın adaleti övüldü."},{"label":"Gelenektir; vergiyi toplayıp muazzam bir düğün yapın.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Padişah Kızlarının Cihaz (Çeyiz) Masrafları hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Padişah Kızlarının Cihaz (Çeyiz) Masrafları hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Padişah Kızlarının Cihaz (Çeyiz) Masrafları gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 391) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_392', 'ottoman', 'Piri Reis\'in Dünya Haritasının Çoğaltılması', 'Topkapı Enderun Kütüphanesi', 'Denizcilik ve coğrafya mektepleri için Piri Reis haritasının bakır levhalara kazınıp çoğaltılması teklif edildi.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Haritayı bastır, tüm kalyon kaptanlarına ve kılavuzlara mecburi kıl.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Denizcilerimiz okyanus rotalarını öğrendi; filomuz açık denizlere çıktı."},{"label":"Harita gizli devlet sırrıdır; saray sandığında saklı kalsın.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Piri Reis\'in Dünya Haritasının Çoğaltılması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Piri Reis\'in Dünya Haritasının Çoğaltılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Piri Reis\'in Dünya Haritasının Çoğaltılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 392) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_393', 'ottoman', 'Veziriazamın Gizli Haberleşme Ağı (Casusluk)', 'Divan Meclisi', 'Sadrazamın yabancı elçiliklerle padişahtan habersiz gizli mektuplaştığı ve menfaat temin ettiği belgelendi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Mühr-i Hümayun\'u derhal geri al; sadrazamı divanda yargılatıp adaleti tecelli ettir.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Devletin başındaki hıyanet temizlendi; saray bağımsızlığını korudu."},{"label":"Diplomatik teamüldür deyip sadrazamın arkasında dur.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Veziriazamın Gizli Haberleşme Ağı (Casusluk) nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Veziriazamın Gizli Haberleşme Ağı (Casusluk) fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Veziriazamın Gizli Haberleşme Ağı (Casusluk) meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 393) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_394', 'ottoman', 'Kadıların Mahkeme Masrafını Davalıdan Zorla Alması', 'Taşra Teftişi', 'Bazı taşra hâkimlerinin beraat eden masum köylüden bile \'ilam harcı\' adı altında para kestiği ortaya çıktı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Beraat edenden harç alınamaz! Kanuna aykırı harç kesen kadıları azlet.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Masumun cüzdanı korundu; mahkemeler haraç kapısı olmaktan çıktı."},{"label":"Kadıların geliri azdır; bu harç onların hakkıdır.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadıların Mahkeme Masrafını Davalıdan Zorla Alması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadıların Mahkeme Masrafını Davalıdan Zorla Alması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadıların Mahkeme Masrafını Davalıdan Zorla Alması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 394) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_395', 'ottoman', 'Boğaz Kıyılarında Yangın Kuleleri ve Nöbet', 'İstanbul Şehremaneti', 'Boğaziçi yalıları ve köşklerinin sık sık yanması üzerine Beyazıt ve Galata kulelerine gece gözcüleri dikilmesi teklif edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Daimi gözcü kulelerini kur, davul ve bayrakla yangın ihbar nizamını hayata geçir.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Yangınlar daha ilk dakikada söndürüldü; payitaht kül olmaktan kurtuldu."},{"label":"Masraflıdır; yangını görenler mahalleliye bağırsın.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Boğaz Kıyılarında Yangın Kuleleri ve Nöbet nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Boğaz Kıyılarında Yangın Kuleleri ve Nöbet fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Boğaz Kıyılarında Yangın Kuleleri ve Nöbet meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 395) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_396', 'ottoman', 'Cezayir ve Tunus Beylerinin Başıboş Akınları', 'Reisülküttab Kalemi', 'Garp ocakları beyleri barış anlaşması yaptığımız İngiliz ticaret gemilerini basıp Londra ile krize sebep oldu.', '[{"id":"char_reisulkuttab","name":"Reisülküttab"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Özel elçi ve ferman sal: Devletin sulh yaptığı gemiye dokunan asi sayılır! Yağmayı tazmin ettir.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Devletin cihanşümul ahdine sadakati korundu; harp engellendi."},{"label":"Garp ocakları uzaktır; yağmaya divan gözetiminde tarafları meşverete davet edip orta yolu bulyıp ganimet payını iste.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Cezayir ve Tunus Beylerinin Başıboş Akınları nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Cezayir ve Tunus Beylerinin Başıboş Akınları fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Cezayir ve Tunus Beylerinin Başıboş Akınları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 396) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_397', 'ottoman', 'Çiftbozan Resmi Affı ve Toprağa Dönüş', 'Divan Mezalim Dairesi', 'Ağır vergilerden kaçmış yüz binlerce köylü, eski borçları silinirse tarlalarına dönüp buğday ekmeye hazır olduklarını bildirdi.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Büyük umumi af fermanı çıkar! Geçmiş vergi borçlarını sil ve tohum dağıtarak halkı toprağına kavuştur.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Anadolu ve Rumeli yeniden şenlendi; ziraat patladı, ambarlar doldu."},{"label":"Borç borçtur; tarlaya dönseler de eski borçlarını faiziyle ödesinler.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Çiftbozan Resmi Affı ve Toprağa Dönüş sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Çiftbozan Resmi Affı ve Toprağa Dönüş hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Çiftbozan Resmi Affı ve Toprağa Dönüş gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 397) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_398', 'ottoman', 'Padişahın Meclis Kararlarına Tabi Olması', 'Şeyhülislam ve Kazaskerler', 'Ulema ve devlet ricali, padişahın dahi şer\'i kanunlara ve meşveret meclisinin ittifakla aldığı kararlara uyması gerektiğini bildirdi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_kazasker","name":"Kazasker"}]', '[{"label":"\'Hüküm ancak Allah\'ındır ve adaletledir!\' de; kanun önünde padişah ile çobanın eşit olduğunu tasdikle.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Hukuk devleti kemale erdi; mülk ebed-müddet dengesine kavuştu."},{"label":"Padişah zıllullahtır (Allah\'ın gölgesi); hiçbir kanunla bağlanamaz.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Padişahın Meclis Kararlarına Tabi Olması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Padişahın Meclis Kararlarına Tabi Olması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Padişahın Meclis Kararlarına Tabi Olması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 398) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_399', 'ottoman', 'Dâire-i Adliyye\'nin Kalbi: Halkın Rızası', 'Kınalızâde\'nin Ruhu', 'Vezirler sorar: \'Hünkârım, mülkün direği ordu mudur, hazine midir, yoksa halkın duası ve adaleti midir?\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"\'Reaya mamur olmazsa mal gelmez, mal gelmezse ordu beslenmez, ordu olmazsa mülk kalmaz; hepsinin başı ise ADALETTİR!\'.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Dâire-i Adliyye hakikatiyle nizam-ı âlem kuruldu; cihan sulhü ilan edildi."},{"label":"\'Mülk yalnız kılıcın kabzasındadır; adalet zayıfların tesellisidir.\'.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Dâire-i Adliyye\'nin Kalbi: Halkın Rızası nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Dâire-i Adliyye\'nin Kalbi: Halkın Rızası fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Dâire-i Adliyye\'nin Kalbi: Halkın Rızası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 399) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_400', 'ottoman', 'Nizâm-ı Cedîd ve Ebed-Müddet Devlet Mührü', 'Cihanşümul Ferman', 'Dört yüz yıllık imtihanın sonunda Dâire-i Adliyye kanunu taşlara, defterlere ve kalplere kazındı: Mülk adaletle kaimdir!', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Mührü bas: \'Adalet Mülkün Temelidir, Zulüm İse Mülkün Zevali!\'.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Adalet dairesi sonsuz bir nizam olarak tarihe altın harflerle mühürlendi."},{"label":"Kanunları rafa kaldır; günübirlik menfaatle hükmet.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Nizâm-ı Cedîd ve Ebed-Müddet Devlet Mührü meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Nizâm-ı Cedîd ve Ebed-Müddet Devlet Mührü meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Nizâm-ı Cedîd ve Ebed-Müddet Devlet Mührü gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 400) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_401', 'ottoman', 'İskenderiye Limanında Veba Karantinası', 'Hekimbaşılık', 'Mısır\'dan gelen bir ticaret gemisinde tayfaların vebadan öldüğü bildirildi. Tüccarlar malların bozulacağını öne sürerek 40 günlük karantinayı (karantina-i bahriye) delmek için rüşvet teklif ediyor.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Tavizsiz karantina uygula! Liman girişini zincirle ve gemiyi açıkta beklet.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Veba payitahta sıçramadı; tebaanın canı altın hırsına kurban edilmedi."},{"label":"Gümrük vergisini peşin alıp malların tahliyesine izin ver.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve İskenderiye Limanında Veba Karantinası nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve İskenderiye Limanında Veba Karantinası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve İskenderiye Limanında Veba Karantinası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 401) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_402', 'ottoman', 'Bimarhanede Musiki ile Tedavi Ödeneği', 'Süleymaniye Darüşşifası', 'Akıl hastalarının ney ve su sesiyle şifa bulduğu bimarhanenin sazende ve tabip tahsisatı enflasyon yüzünden tükendi.', '[{"id":"char_tabip","name":"Tabip / Cerrah"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Hazine-i Hassa\'dan ek tahsisat bağla; dertlilere şifa kapısını açık tut.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Merhamet nizamı korundu; darüşşifada şifa nağmeleri yükseldi."},{"label":"Delilere musiki çalmak fuzulidir; hastaları odalara kilitleyip masrafı kısın.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Bimarhanede Musiki ile Tedavi Ödeneği nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Bimarhanede Musiki ile Tedavi Ödeneği fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Bimarhanede Musiki ile Tedavi Ödeneği meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 402) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_403', 'ottoman', 'Diplomasız Cerrahların Göz Ameliyatı Hilesi', 'İstanbul Kadılığı', 'Meydanlarda katarakt açtığını iddia eden sahte cerrahların birçok fukaranın gözünü kör ettiği ortaya çıktı.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Hekimbaşı sınavından geçmeyen sahte tabipleri tutukla ve cerrahi aletlerini müsadere et.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Halk sağlığı sahtekârlardan korundu; hekimlik liyakate bağlandı."},{"label":"Kocakarı ilacı ve halk hekimliğidir; karışıp esnafı kızdırma.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Diplomasız Cerrahların Göz Ameliyatı Hilesi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Diplomasız Cerrahların Göz Ameliyatı Hilesi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Diplomasız Cerrahların Göz Ameliyatı Hilesi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 403) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_404', 'ottoman', 'Miskinler Tekkesinde Ekmek Yetersizliği', 'Edirne Cüzzamhanesi', 'Şehir dışındaki tecritte yaşayan cüzzamlıların vakıf ekmeği kesildi; hastalar şehre inip dilenmekle tehdit ediyor.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Derhal özel fırın tahsis et ve cüzzamhaneye sıcak aş ile temiz giyecek sevkiyatı yap.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Hem mazlum hastalar doyuruldu hem de salgının şehre yayılması önlendi."},{"label":"Şehre inerlerse zaptiye zoruyla kovun; bütçe yok.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Miskinler Tekkesinde Ekmek Yetersizliği nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Miskinler Tekkesinde Ekmek Yetersizliği fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Miskinler Tekkesinde Ekmek Yetersizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 404) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_405', 'ottoman', 'Kuyu Sularına Sızan Mezbaha Atıkları', 'Payitaht İhtisabı', 'Yedikule civarındaki mezbahaların kanlı atıkları mahalle kuyularına karıştı; tifo vakaları baş gösterdi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Mezbahaları derhal sur dışına taşıt, arıtma havuzları kurdur ve kuyuları kireçle.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"İçme suyu temizlendi; kolera ve tifo tehlikesi bertaraf edildi."},{"label":"Kasapların taşıma masrafını düşünerek mezbahayı yerinde bırak.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kuyu Sularına Sızan Mezbaha Atıkları nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kuyu Sularına Sızan Mezbaha Atıkları fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kuyu Sularına Sızan Mezbaha Atıkları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 405) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_406', 'ottoman', 'İpek İpliği Bükücülerinin Göğüs Hastalığı', 'Bursa İpekçileri', 'Kapalı ve havasız mahzenlerde çalışan kadın ve çocukların ciğer hastası olduğu bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Atölyelere pencereli havalandırma mecburiyeti koy ve mesai saatlerini sınırla.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"İşçi sağlığı korundu; verimli ve dürüst üretim tazelendi."},{"label":"Zanaatın icabıdır; kumaş üretimini yavaşlatacak kural koyma.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İpek İpliği Bükücülerinin Göğüs Hastalığı sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; İpek İpliği Bükücülerinin Göğüs Hastalığı meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; İpek İpliği Bükücülerinin Göğüs Hastalığı gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 406) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_407', 'ottoman', 'Afyon Tiryakiliği Tedavisi', 'Halep Darüşşifası', 'Şehirde gençlerin afyon tekkelerinde çürümesini önlemek için darüşşifada hususi bir arınma koğuşu kurulması teklif edildi.', '[{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Bütçe tahsis et; hekimleri görevlendirip afyon batakhanelerini bastır ve kapat.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Gençler zehirden kurtarıldı; Halep çarşısında huzur tesis edildi."},{"label":"Afyon ticareti devlete vergi getirir; tekkeleri kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Afyon Tiryakiliği Tedavisi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Afyon Tiryakiliği Tedavisi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Afyon Tiryakiliği Tedavisi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 407) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_408', 'ottoman', 'Kadırga Kürekçilerine Sirkeli Su Tahsisi', 'Tersane Tabibi', 'Gemi cerrahı, güneş çarpması ve salgınlara karşı kürekçilere her gün sirkeli su ve sarımsak verilmesini istiyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Emri ver; donanma kilerinden sirke ve sarımsak istihkakını eksiksiz temin et.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Kadırgalarda kırgınlık durdu; kürekçiler tam randımanla asıldı."},{"label":"Forsalara masraf yapılmaz; sade su kâfidir.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kadırga Kürekçilerine Sirkeli Su Tahsisi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kadırga Kürekçilerine Sirkeli Su Tahsisi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kadırga Kürekçilerine Sirkeli Su Tahsisi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 408) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_409', 'ottoman', 'Kuduz Köpek Isırığı ve Dağlama Tedavisi', 'Şam Vilayeti', 'Kuduz vakalarının artması üzerine hekimler dağlama yerine yeni merhemlerin getirilmesini talep ediyor.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"İstanbul ve Şam darüşşifalarında hekim heyeti kurdur; yeni ilaçları tedarik et.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Kuduz felaketi dindirildi; halk modern tıp ilmine güvendi."},{"label":"Eski usul ateşle dağlama yeterlidir; yeni ilaç masrafına girme.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Beytülmâl\'den darüşşifa ve karantina lazaretolarına acil ödenek tahsis et; Kuduz Köpek Isırığı ve Dağlama Tedavisi sürecinde sıhhi teftişe riayet eden tüccarlara vergi indirimi tanı.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Limanı silahlı muhafızlarla karantinaya al; Kuduz Köpek Isırığı ve Dağlama Tedavisi fermanını delmeye kalkan ticaret gemilerini top ateşi tehdidiyle açık denizde tut.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Karantina-i Bahriye ve Sıhhat Kanunu\' neşret; Kuduz Köpek Isırığı ve Dağlama Tedavisi gibi hadiselerin tekerrürünü önleyecek şekilde liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 409) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_410', 'ottoman', 'Cenazelerin Derin Kazılmaması ve Koku Şikâyeti', 'Payitaht Şehremaneti', 'Salgın günlerinde mezarcıların kabirleri sığ kazdığı, sokak hayvanlarının cesetleri deşelediği ihbar edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Sıkı mezarlık nizamatı koy; kabirlerin derinliğini denetlet, uymayan mezarcıyı cezalandır.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Mevtaya hürmet korundu; salgın mikroplarının topraktan yayılması önlendi."},{"label":"Mezarcılar yetişemiyor; cenazeleri nasıl gömerlerse gömsünler.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Cenazelerin Derin Kazılmaması ve Koku Şikâyeti nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Cenazelerin Derin Kazılmaması ve Koku Şikâyeti fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Cenazelerin Derin Kazılmaması ve Koku Şikâyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 410) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_411', 'ottoman', 'Frengi Hastalığı İçin Hususi Tecritgah', 'Hekimbaşı Tezkiresi', 'Avrupa\'dan dönen tüccar ve gemiciler vasıtasıyla liman şehirlerinde yayılan frengiye karşı hususi hastane kurulması istendi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Galata dışında hususi tecritgah açtır; hastalara ücretsiz cıva merhemi tedavisi sağla.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Hastalık kontrol altına alındı; nesillerin sağlığı korundu."},{"label":"Ahlaksızlık cezasıdır deyip hastaları kaderine terk et.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Frengi Hastalığı İçin Hususi Tecritgah nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Frengi Hastalığı İçin Hususi Tecritgah fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Frengi Hastalığı İçin Hususi Tecritgah meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 411) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_412', 'ottoman', 'Kuşatma Siperlerinde Bataklık Kıtlığı', 'Girit Serdarlığı', 'Hanya önündeki askerlerin yağmur sularıyla dolan siperlerde romatizma ve hummadan felç kaldığı bildirildi.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Siperlere tahta ızgaralar döşet, kuru saman ve sıcak keçe mintanlar yetiştir.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Askerin muharebe gücü korundu; mevziler terkedilmedi."},{"label":"Asker çamura alışkındır; masrafa girmeyin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kuşatma Siperlerinde Bataklık Kıtlığı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kuşatma Siperlerinde Bataklık Kıtlığı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kuşatma Siperlerinde Bataklık Kıtlığı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 412) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_413', 'ottoman', 'Koyun Çiçeği Salgını ve Karantina', 'Üsküdar İskelesi', 'Anadolu\'dan payitahta et getiren sürülerde çiçek hastalığı çıktı; kasaplar etin şehre sokulmasını istiyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Et girişini durdur; sürüleri Kadıköy çayırında karantinaya al, hastalıklı hayvanları tazminatla itlaf et.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Payitaht etten zehirlenmekten kurtuldu; kasapların baskısı püskürtüldü."},{"label":"Et darlığı çıkar korkusuyla sürüleri şehre sok.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Koyun Çiçeği Salgını ve Karantina nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Koyun Çiçeği Salgını ve Karantina fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Koyun Çiçeği Salgını ve Karantina meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 413) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_414', 'ottoman', 'Çavdar Mahmuzu (Çavdar Zehirlenmesi)', 'İstanbul Fırınları', 'Nemli buğday ve çavdarda türeyen kara mantar yüzünden ekmek yiyenlerin delirdiği ve uzuvlarının kangren olduğu görüldü.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütün un ambarlarını teftiş ettir; küflü tahılları denize döktür ve temiz un dağıt.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Büyük zehirlenme faciası durduruldu; halkın ekmeği temizlendi."},{"label":"Halk ekmeksiz kalmasın; az küflü unları eleyip pişirsinler.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Çavdar Mahmuzu (Çavdar Zehirlenmesi) nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Çavdar Mahmuzu (Çavdar Zehirlenmesi) fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Çavdar Mahmuzu (Çavdar Zehirlenmesi) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 414) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_415', 'ottoman', 'Şifalı Macun ve Tiryak Formüllerinin Çalınması', 'Hassa Eczanesi', 'Saray hekimlerinin panzehir olarak hazırladığı meşhur Mesir Macunu ve Tiryak reçetelerinin Venedik tacirlerine satıldığı anlaşıldı.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Hırsız kalfaları cezalandır; formülleri devlet himayesinde tescilleyip hekim loncasına teslim et.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Milli tıp sırları korundu; taklit ilaç üretimi engellendi."},{"label":"İlaç formülüdür, saklanmaz; kim yaparsa yapsın.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Beytülmâl\'den darüşşifa ve karantina lazaretolarına acil ödenek tahsis et; Şifalı Macun ve Tiryak Formüllerinin Çalınması sürecinde sıhhi teftişe riayet eden tüccarlara vergi indirimi tanı.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Limanı silahlı muhafızlarla karantinaya al; Şifalı Macun ve Tiryak Formüllerinin Çalınması fermanını delmeye kalkan ticaret gemilerini top ateşi tehdidiyle açık denizde tut.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Karantina-i Bahriye ve Sıhhat Kanunu\' neşret; Şifalı Macun ve Tiryak Formüllerinin Çalınması gibi hadiselerin tekerrürünü önleyecek şekilde liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 415) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_416', 'ottoman', 'Hac Yolu Sıhhiye Konvoyları', 'Kudüs Darüşşifası', 'Şam\'dan yola çıkan hac kervanında yaşlı ve hastaların çölde ölmemesi için hekim ve deve sedyeleri tahsisi teklif edildi.', '[{"id":"char_kervancibasi","name":"Kervancıbaşı"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Surre Alayı\'na sıhhiye çadırları ve hekim konvoyu eklet; masrafı vakıftan öde.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Hacılar sağ salim Kâbe\'ye vardı; halifenin şefkati İslam alemine yayıldı."},{"label":"Hac ibadeti meşakkatlidir; devesi olmayan yola çıkmasın.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Hac Yolu Sıhhiye Konvoyları nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Hac Yolu Sıhhiye Konvoyları fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Hac Yolu Sıhhiye Konvoyları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 416) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_417', 'ottoman', 'Metil Alkol (İspirto) Zehirlenmesi', 'Payitaht Meyhaneleri', 'Gayriresmî kaçak imalathanelerde odun talaşından damıtılan sahte içkilerin insanları kör ettiği bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kaçak mahzenleri bastır, zehirli fıçıları sokaklara döktür ve zehir tacirlerini as.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Zehir tacirleri temizlendi; masum canlar kurtarıldı."},{"label":"Meyhaneler zimmilerindir; kendi iç işleridir deyip divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Metil Alkol (İspirto) Zehirlenmesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Metil Alkol (İspirto) Zehirlenmesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Metil Alkol (İspirto) Zehirlenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 417) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_418', 'ottoman', 'Askerde Kar Körlüğü (Kar Kamaşması)', 'Erzurum Kışlası', 'Kafkas dağlarında nöbet tutan neferlerin beyaz kardan gözlerinin kamaşıp körlük tehlikesi yaşadığı bildirildi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Halk usulü at kılından örme siyah kar gözlükleri yaptırıp tüm garnizona dağıt.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Askerin gözleri korundu; hudut nöbeti aksamadan sürdü."},{"label":"Basit kamaşmadır; gözlerini ovuşturup baksınlar.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Askerde Kar Körlüğü (Kar Kamaşması) sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Askerde Kar Körlüğü (Kar Kamaşması) meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Askerde Kar Körlüğü (Kar Kamaşması) gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 418) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_419', 'ottoman', 'Hamamlarda Kese ve Tıraş Bıçaklarının Temizliği', 'İstanbul Şehremaneti', 'Umumi hamamlarda kullanılan usturaların yıkanmadan herkese sürülmesi yüzünden çıban ve mantar salgını başladı.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Dellak ve berberlere her müşteride aletleri kaynar suda kaynatma mecburiyeti koy.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Hamamlara sıhhi intizam geldi; deri hastalıkları kesildi."},{"label":"Hamamcının adetidir; resmi kurallarla esnafı bunaltma.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Hamamlarda Kese ve Tıraş Bıçaklarının Temizliği nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Hamamlarda Kese ve Tıraş Bıçaklarının Temizliği fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hamamlarda Kese ve Tıraş Bıçaklarının Temizliği meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 419) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_420', 'ottoman', 'Tıphane ve Cerrahhane-i Âmire\'nin Açılması', 'Hekimbaşı Raporu', 'Modern cerrahi ve anatomi derslerinin verileceği hususi bir devlet tıp akademisi kurulması teklif edildi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Bütçe ayır; Tıphane\'yi aç ve batı tıbbını İslam tıbbıyla mezceden hekimler yetiştir.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Milli tıp devrimi başladı; ordunun ve halkın tabip ihtiyacı karşılandı."},{"label":"Usta-çırak usulü yeterlidir; mektep açıp masraf etmeyin.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Tıphane ve Cerrahhane-i Âmire\'nin Açılması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Tıphane ve Cerrahhane-i Âmire\'nin Açılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tıphane ve Cerrahhane-i Âmire\'nin Açılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 420) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_421', 'ottoman', 'Gümüş Damarlarında Zehirli Gaz Boğulmaları', 'Gümüşhane Madenleri', 'Derin galerilerde karbon monoksit birikmesi yüzünden madenciler ocaklara girmeyi reddedip grev başlattı.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Maden mühendisleri gönder; su çarkıyla çalışan körüklerle galerilere temiz hava bastır.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Madencilerin hayatı kurtarıldı; darphaneye gümüş akışı kesilmedi."},{"label":"Zorla madene sokun; gümüş çıkmazsa maaşlar ödenemez.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gümüş Damarlarında Zehirli Gaz Boğulmaları meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Gümüş Damarlarında Zehirli Gaz Boğulmaları hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Gümüş Damarlarında Zehirli Gaz Boğulmaları gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 421) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_422', 'ottoman', 'Kömür Kıtlığı ve Odun Kömürü Fırınları', 'Tophane Dökümhanesi', 'Bakır eriten top fırınları için kaliteli meşe kömürü bulunamıyor; döküm durma noktasına geldi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Istranca dağlarında devlet kontrolünde kömür ocakları açtır ve kömürcülere dolgun ücret ver.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Fırınlar alev alev yandı; tunç toplar tam vaktinde döküldü."},{"label":"Civar köylülerin yakacak odunlarına zorla el koyup fırınlara atın.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kömür Kıtlığı ve Odun Kömürü Fırınları nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kömür Kıtlığı ve Odun Kömürü Fırınları fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kömür Kıtlığı ve Odun Kömürü Fırınları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 422) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_423', 'ottoman', 'Çeşm-i Bülbül Cam Sanatının İhyası', 'Beykoz Cam Atölyesi', 'Venedik Murano camlarıyla rekabet edebilmek için Beykoz\'da lüks cam atölyesi kurulması teklif edildi.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Atölyeyi kur, ustaları taltif et ve saray siparişlerini yerli camcılara ver.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Zarif Çeşm-i Bülbül eserleri doğdu; cam ithalatı azaldı."},{"label":"Venedik camı daha parlaktır; cam işine para bağlamayın.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Çeşm-i Bülbül Cam Sanatının İhyası nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Çeşm-i Bülbül Cam Sanatının İhyası fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Çeşm-i Bülbül Cam Sanatının İhyası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 423) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_424', 'ottoman', 'Su Çarklı Demir Dövme Tokmakları', 'Samakov Demirhanesi', 'Bulgaristan Samakov\'da su gücüyle çalışan ağır çekiçler kurulursa kılıç ve zırh üretimi on katına çıkabilir.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Balkan su mühendislerini görevlendir; modern su tokmaklarını inşa ettir.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Askeri sanayi seri üretime geçti; cephanelikler kılıçla doldu."},{"label":"Eski el çekici kafidir; masraflı binalar kurmayın.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Su Çarklı Demir Dövme Tokmakları meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Su Çarklı Demir Dövme Tokmakları hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Su Çarklı Demir Dövme Tokmakları gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 424) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_425', 'ottoman', 'İbrahim Müteferrika\'nın Kâğıt Fabrikası', 'Yalova Kâğıthanesi', 'Matbaa ve devlet daireleri için su gücüyle çalışan yerli kâğıt değirmeni kurulması teklif edildi.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Yalova\'da kâğıt imalathanesini kurdur; bez ve paçavra toplatıp yerli kâğıt ürettir.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Kitap ve evrak basımı ucuzladı; kâğıtta dışa bağımlılık kırıldı."},{"label":"Avrupa kâğıdı daha pürüzsüzdür; ithale devam edin.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve İbrahim Müteferrika\'nın Kâğıt Fabrikası nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve İbrahim Müteferrika\'nın Kâğıt Fabrikası fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve İbrahim Müteferrika\'nın Kâğıt Fabrikası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 425) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_426', 'ottoman', 'Maden Köylülerinin Aşırı Ağır Angaryası', 'Divriği Demir Madeni', 'Demir ocağında çalışan köylülerin sırtında günde 12 saat maden taşıtıldığı, tarlalarının kuruduğu şikâyet edildi.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Çalışma saatini yarıya indir, adil yevmiye bağla ve köylüyü öşür vergisinden muaf tut.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Köylü şevkle çalıştı; demir üretimi iki katına çıktı."},{"label":"Ordu demir bekler; köylünün sızlanmasına kulak asmayın.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Maden Köylülerinin Aşırı Ağır Angaryası nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Maden Köylülerinin Aşırı Ağır Angaryası fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Maden Köylülerinin Aşırı Ağır Angaryası meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 426) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_427', 'ottoman', 'Yeniçeri Çuhası Dokuma Tekeli', 'Selanik Çuha Fabrikası', 'Selanikli Musevi dokumacıların ürettiği çuhanın kalitesinin düştüğü ve neferlerin yağmurda ıslandığı bildirildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Dokuma tezgâhlarına sıkı teftiş koy, yün kalitesini artırmaları için devlet avansı ver.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Çuha kalitesi düzeldi; neferler sıcak üniformalara kavuştu."},{"label":"Tekeli feshet; çuhayı İngiltere\'den satın al.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Yeniçeri Çuhası Dokuma Tekeli meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Yeniçeri Çuhası Dokuma Tekeli hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Yeniçeri Çuhası Dokuma Tekeli gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 427) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_428', 'ottoman', 'Güherçile Kaynatma Kazanlarının Çatlaması', 'Kütahya Güherçilehanesi', 'Barutun ana maddesi güherçileyi süzen bakır kazanlar yandı; Tophane barutsuz kalma tehlikesiyle karşı karşıya.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kazancı loncasına acil emir ver; yeni döküm kalın kazanları süratle yetiştir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Güherçile üretimi durmadı; baruthaneler tam kapasite çalıştı."},{"label":"Tamiri seneye bırakın; stoktaki eski barutla idare edin.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Güherçile Kaynatma Kazanlarının Çatlaması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Güherçile Kaynatma Kazanlarının Çatlaması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Güherçile Kaynatma Kazanlarının Çatlaması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 428) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_429', 'ottoman', 'Buharlı İp Bükme Makinesi Teklifi', 'Tersane Halathanesi', 'Frenk bir mühendis, kalyon halatlarını 10 kat hızlı ve sağlam büken bir buhar düzeneği kurmayı önerdi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Projeyi onaylat; tersane bünyesinde ilk buharlı makine tecrübesini başlat.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Tersanede sanayi çağı aralandı; kalyon halatları çelik gibi oldu."},{"label":"Şeytan icadıdır deyip mühendisi tersaneden kovun.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Buharlı İp Bükme Makinesi Teklifi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Buharlı İp Bükme Makinesi Teklifi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Buharlı İp Bükme Makinesi Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 429) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_430', 'ottoman', 'Lületaşı İhracatında Kaçakçılık', 'Eskişehir Lületaşı Ocakları', 'Avusturyalı tüccarlar ham lületaşını ucuza kaçırıp Viyana\'da fahiş kârla pipo ve ziynet yapıyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Ham lületaşı ihracını yasakla; payitahtta oymacılık atölyeleri kurup işlenmiş olarak sat.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Katma değer ülkede kaldı; Eskişehir oymacı esnafı ihya oldu."},{"label":"Ham taş ihracından cüzi gümrük al, gerisine divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Lületaşı İhracatında Kaçakçılık sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Lületaşı İhracatında Kaçakçılık meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Lületaşı İhracatında Kaçakçılık gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 430) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_431', 'ottoman', 'Katran Ocaklarının Orman Yangını Çıkarması', 'Bolu Ormanları', 'Katran kaynatan köylülerin ocakları kontrol edemeyip koca çam ormanlarını yaktığı bildirildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Katran üretimini taş ocaklarıyla sınırla, orman muhafızları dik ve fidan diktir.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Ormanlar yangından kurtarıldı; gemi katranı güvenle üretildi."},{"label":"Katran gemilere lazımdır; birkaç ağacın yanmasına bakmayın.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Katran Ocaklarının Orman Yangını Çıkarması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Katran Ocaklarının Orman Yangını Çıkarması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Katran Ocaklarının Orman Yangını Çıkarması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 431) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_432', 'ottoman', 'Simli Kurşunun Fırat Yoluyla Sevkiyatı', 'Keban Madeni', 'Doğu Anadolu\'da çıkarılan kurşunun katırlarla taşınması aylar sürüyor; Fırat nehri sallarıyla nakil teklif edildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Fırat üzerinde hafif mavnalar inşa ettir; kurşun ve gümüşü hızla başkente ulaştır.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Maden sevkiyatı üç kat hızlandı; cephanelikler kurşunla doldu."},{"label":"Nehir tehlikelidir; eski dağ yolundan katırlarla taşımaya devam edin.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Simli Kurşunun Fırat Yoluyla Sevkiyatı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Simli Kurşunun Fırat Yoluyla Sevkiyatı fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Simli Kurşunun Fırat Yoluyla Sevkiyatı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 432) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_433', 'ottoman', 'Top Döküm Kalıplarında Kum Hilesi', 'İstanbul Tophane İskelesi', 'Kalıp ustalarının ince nehir kumu yerine killi toprak kullanması sebebiyle topların namlusunda hava kabarcıkları kaldı.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Bozuk dökümleri derhal fırına atıp erittir; kusurlu ustaları cezalandır.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Topçunun canı kurtarıldı; namlular çatlamadan savaştı."},{"label":"Dıştan belli olmuyor; üzerini sıvayıp bataryalara yollayın.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Top Döküm Kalıplarında Kum Hilesi sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Top Döküm Kalıplarında Kum Hilesi meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Top Döküm Kalıplarında Kum Hilesi gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 433) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_434', 'ottoman', 'Kuvars Tozunun Madencilerde Ciğer Çürümesi', 'İznik Çinisi Fırınları', 'Çiniye beyazlık veren kuvars taşını dibeklerde döven işçilerin genç yaşta boğularak öldüğü görüldü.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Su değirmeniyle çalışan ıslak öğütme mekanizması kurdur; tozu havaya karıştırma.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"İşçilerin canı kurtarıldı; İznik sanatı merhametle parladı."},{"label":"Çini ustası çoktur; ölenin yerine yenisini koyun.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kuvars Tozunun Madencilerde Ciğer Çürümesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kuvars Tozunun Madencilerde Ciğer Çürümesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kuvars Tozunun Madencilerde Ciğer Çürümesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 434) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_435', 'ottoman', 'Şap Madenlerinde Şahsi Müsadere', 'Taşra Maden İdaresi', 'Kumaş boyamada ve tabaklamada zaruri olan Kütahya şap madenini yerel bey kendi mülkü ilan etti.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Madenler umumundur! Beyi azlet, madeni doğrudan devlet emanetine al.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Şap tekeli devlete geçti; boyacılara ucuz hammadde sağlandı."},{"label":"Beyle pazarlık yapıp kârın üçte birini hazineye iste.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Şap Madenlerinde Şahsi Müsadere nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Şap Madenlerinde Şahsi Müsadere fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Şap Madenlerinde Şahsi Müsadere meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 435) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_436', 'ottoman', 'Kalyon Eğrileri İçin Eğri Meşe Ağacı Kıtlığı', 'Sinop Tersanesi', 'Gemi omurgasına uygun tabii kavisli meşe ağaçları plansız kesildiği için kalyon yapımı durdu.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Özel koruma koruları kurdur; tabii eğri fidan yetiştirme nizamnamesi ilan et.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Tersane geleceğe hazırlandı; omurgalar çürümeyen ağaçlarla çatıldı."},{"label":"Düz tahtaları fırında büküp eğri yapın; beklemeyin.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Kalyon Eğrileri İçin Eğri Meşe Ağacı Kıtlığı hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Kalyon Eğrileri İçin Eğri Meşe Ağacı Kıtlığı hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Kalyon Eğrileri İçin Eğri Meşe Ağacı Kıtlığı gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 436) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_437', 'ottoman', 'Karadeniz Kıyısında \'Taş Kömürü\' Keşfi', 'Zonguldak Kömür Yatakları', 'Karadeniz kıyısındaki ormanlarda yanan taşlar bulundu; madenciler buhar ve ocak için devrim olduğunu söylüyor.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Derhal maden mühendisleri yolla, ilk taş kömürü havzasını kamu bütçesiyle açtır.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Büyük kömür devrimi başladı; fabrikalar ve gemiler kömürle coştu."},{"label":"Taş yanar mı deyip kâşifleri saraydan kovun.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Karadeniz Kıyısında \'Taş Kömürü\' Keşfi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Karadeniz Kıyısında \'Taş Kömürü\' Keşfi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Karadeniz Kıyısında \'Taş Kömürü\' Keşfi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 437) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_438', 'ottoman', 'Barut Tanelerinin Eşitlenmesi (Granülasyon)', 'İstanbul Baruthanesi', 'İnce toz barutun nem alıp ateş almadığı, taneli (granüle) barut için elek değirmenleri gerektiği bildirildi.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Değirmenleri kurdur; nem tutmayan sert taneli barut nizamına geç.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Tüfeklerimiz yağmur altında bile ateş aldı; ordu üstünlük sağladı."},{"label":"Eski toz barut asırlardır kullanılıyor; masrafa gerek yok.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Barut Tanelerinin Eşitlenmesi (Granülasyon) nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Barut Tanelerinin Eşitlenmesi (Granülasyon) fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Barut Tanelerinin Eşitlenmesi (Granülasyon) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 438) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_439', 'ottoman', 'Şam Çeliği (Dımaşkî) Sırrının Unutulması', 'Diyarbakır Kılıççıları', 'Su verme tekniğini bilen son yaşlı ustalar öldü; dökülen yeni kılıçlar düşman zırhına çarpınca bükülüyor.', '[{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Şam ve Halep\'ten kadim ustaları payitahta getirt, genç çıraklara çelik mektebi aç.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Efsanevi su verme sırrı kurtarıldı; çeliğimiz kalkanları ikiye böldü."},{"label":"Avrupa\'dan hazır çelik kılıç ithal edin.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şam Çeliği (Dımaşkî) Sırrının Unutulması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Şam Çeliği (Dımaşkî) Sırrının Unutulması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Şam Çeliği (Dımaşkî) Sırrının Unutulması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 439) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_440', 'ottoman', 'Maden Ocaklarında Çalışan Esirlerin Hürriyeti', 'Payitaht Darphanesi', 'Yıllardır madenlerde çalışan esir işçiler, belirli miktar maden çıkardıktan sonra azat edilmek istiyor.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Mükâtebe fermanı çıkar: Kotasını dolduran her esire hürriyet ve zanaatkar beratı ver.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Madenlerde üretim rekoru kırıldı; esirler hürriyet aşkıyla çalıştı."},{"label":"Esir esirdir; ölene kadar kazma sallamaya devam etsinler.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Maden Ocaklarında Çalışan Esirlerin Hürriyeti nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Maden Ocaklarında Çalışan Esirlerin Hürriyeti fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Maden Ocaklarında Çalışan Esirlerin Hürriyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 440) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_441', 'ottoman', 'Kızıldeniz\'de Portekiz Karavelası Tehdidi', 'Süveyş Tersanesi', 'Cidde açıklarına gelen Portekiz gemileri Mekke\'ye giden buğday yüklü hacı sefinelerini batırıyor.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Süveyş kadırgalarını donat, Hadım Süleyman Paşa\'yı tam yetkiyle Hint sularına çıkar.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Portekiz karavelaları batırıldı; Kızıldeniz Müslüman gölü olarak kaldı."},{"label":"Kızıldeniz uzaktır; Cidde kalesine kapanıp beklesinler.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Kızıldeniz\'de Portekiz Karavelası Tehdidi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Kızıldeniz\'de Portekiz Karavelası Tehdidi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kızıldeniz\'de Portekiz Karavelası Tehdidi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 441) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_442', 'ottoman', 'Hollanda Ticaret Gemilerinin Yağmalanması', 'Cezayir Beylerbeyliği', 'Cezayir leventleri, barış ahidnâmemiz olan Felemenk ticaret filosunu basıp payitahtı diplomatik krize soktu.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Malları iade ettir, korsan reisini divana çağırıp cezalandır; ahde vefa devlete farzdır.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Devletin sözünün eri olduğu ispatlandı; Felemenk ittifakı korundu."},{"label":"Ganimetten saray payını al; korsanların sırtını sıvazla.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Hollanda Ticaret Gemilerinin Yağmalanması hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Hollanda Ticaret Gemilerinin Yağmalanması hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Hollanda Ticaret Gemilerinin Yağmalanması gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 442) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_443', 'ottoman', 'Hürmüz Boğazı Kuşatması ve Seydi Ali Reis', 'Basra Körfezi', 'Portekiz kalesi Hürmüz\'ü kuşatan filomuz açık denizde yakalandı; Seydi Ali Reis gemileri Hindistan\'a sürdü.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Basra ve Yemen\'den yardım filosu çıkar; Basra Körfezi\'ni tahkim et.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Körfez kontrolü kurtarıldı; Seydi Ali Reis karadan dönüp tecrübesini aktardı."},{"label":"Hint Okyanusu bataklıktır; oradaki filoyu feda edin.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Hürmüz Boğazı Kuşatması ve Seydi Ali Reis nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Hürmüz Boğazı Kuşatması ve Seydi Ali Reis fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hürmüz Boğazı Kuşatması ve Seydi Ali Reis meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 443) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_444', 'ottoman', 'Malta Kuşatmasında Turgut Reis\'in Şehadeti', 'Akdeniz Bahriyesi', 'Saint Elmo kalesi önünde Turgut Reis şehit düştü; serdarlar arasında kumanda kavgası çıktı.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Piyale Paşa\'ya tek kumandayı ver, disiplini sağla ve kahramanca geri çekilme nizamını kur.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Donanma hezimete uğramadan intizamla kurtarıldı; ocak korundu."},{"label":"Kör taarruza devam edin; ada alınmadan kimse dönmesin.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Malta Kuşatmasında Turgut Reis\'in Şehadeti nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Malta Kuşatmasında Turgut Reis\'in Şehadeti fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Malta Kuşatmasında Turgut Reis\'in Şehadeti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 444) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_445', 'ottoman', 'Sahil Şeridindeki Deniz Fenerlerinin Söndürülmesi', 'Trablusgarp Kalesi', 'Düşman gemilerini kayalıklara oturtmak için yerel kabilelerin geceleri fenerleri kasten söndürdüğü anlaşıldı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Fenerleri askeri muhafazaya al; tuzakla gemi batırmayı korsanlık sayıp men et.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Deniz ticareti emniyete kavuştu; sahil yağmacılığı bitti."},{"label":"Bırakın söndürsünler; batan geminin ganimeti bize kalır.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Sahil Şeridindeki Deniz Fenerlerinin Söndürülmesi hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Sahil Şeridindeki Deniz Fenerlerinin Söndürülmesi hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Sahil Şeridindeki Deniz Fenerlerinin Söndürülmesi gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 445) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_446', 'ottoman', 'Venedik Kalyonlarının Boğazı Kapatması (Çanakkale Ablukası)', 'Kandiye Kuşatması', 'Venedik donanması Çanakkale Boğazı\'nı kilitledi; payitahta buğday ve odun gelemiyor, açlık baş gösterdi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Köprülü Mehmed Paşa\'ya tam yetki ver; boğaz hisarlarını kurdurup filoyu yarma harekâtına kaldır.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Çanakkale ablukası parçalandı; payitahta gıda aktı, zafer kazanıldı."},{"label":"Venedik ile tavizli barış yap; Girit\'i geri verip ablukayı kaldır.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Venedik Kalyonlarının Boğazı Kapatması (Çanakkale Ablukası) nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Venedik Kalyonlarının Boğazı Kapatması (Çanakkale Ablukası) fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Venedik Kalyonlarının Boğazı Kapatması (Çanakkale Ablukası) meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 446) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_447', 'ottoman', 'Yemen İskelesinde Kahve Yüklü Gemilere El Koyma', 'Kızıldeniz Sevkiyatı', 'Yerel sancak beyi, hacıların dönerken getirdiği birkaç çuval kahveye bile \'gümrük kaçağı\' diye el koyuyor.', '[{"id":"char_sancak_beyi","name":"Sancak Beyi"},{"id":"char_gumruk_emini","name":"Gümrük Emini"}]', '[{"label":"Beyi azlet; hacıların şahsi yüklerine tecavüzü yasaklayan adâletnâme yolla.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Zulüm durduruldu; hacılar selametle yurtlarına döndü."},{"label":"Bey hazineye pay aktarmaktadır; tahkikata lüzum yok.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Yemen İskelesinde Kahve Yüklü Gemilere El Koyma nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Yemen İskelesinde Kahve Yüklü Gemilere El Koyma fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yemen İskelesinde Kahve Yüklü Gemilere El Koyma meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 447) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_448', 'ottoman', 'Kalyonlarda Yangın Tulumbası Mecburiyeti', 'Tersane-i Âmire', 'Kalyonların güvertelerine seyyar tulumba ve ıslak keçe fıçıları konulursa düşman yangın füzelerinin söndürülebileceği arz edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Ferman çıkar: Her kalyona iki tulumba ve yangın neferi tahsis edilsin.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Deniz savaşlarında yangın tehlikesi bertaraf edildi; gemilerimiz yanmaktan kurtuldu."},{"label":"Güvertede yer daralır; kovalı söndürme kafidir.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Kalyonlarda Yangın Tulumbası Mecburiyeti hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Kalyonlarda Yangın Tulumbası Mecburiyeti hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Kalyonlarda Yangın Tulumbası Mecburiyeti gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 448) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_449', 'ottoman', 'Sokullu\'nun Donanmayı Yeniden İnşası', 'İnebahtı (Lepanto) Sonrası', 'İnebahtı\'da donanmamız yandı; Sokullu Mehmed Paşa kış boyunca 200 yeni kalyon inşa etmeyi teklif eder.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"\'Biz donanmayı yeniden kurarız, kesilen sakal daha gür biter!\' de; tüm hazineyi tersaneye dök.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Bahar gelmeden 200 gemilik muazzam donanma denize indi; Avrupa şoke oldu."},{"label":"Hazine kaldıramaz; sadece küçük bir savunma filosu yapın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Sokullu\'nun Donanmayı Yeniden İnşası nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Sokullu\'nun Donanmayı Yeniden İnşası fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Sokullu\'nun Donanmayı Yeniden İnşası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 449) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_450', 'ottoman', 'İngiltere ile Ticaret ve Korsanlık Paktı', 'Cezayir Limanı', 'İngiltere Kralı, İspanya\'ya karşı ortak hareket etmek şartıyla Osmanlı leventlerine limanlarını açmayı teklif ediyor.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"İttifakı imzala; leventlerin Atlantik\'e çıkmasına ve İngiliz limanlarını kullanmasına izin ver.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Leventlerimiz Atlas Okyanusu\'nda cirit attı; İspanyol armadası ezildi."},{"label":"Protestan krala güvenilmez; teklifi reddet.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve İngiltere ile Ticaret ve Korsanlık Paktı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve İngiltere ile Ticaret ve Korsanlık Paktı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve İngiltere ile Ticaret ve Korsanlık Paktı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 450) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_451', 'ottoman', 'Zeyla ve Masavva İskelelerinin Tahkimi', 'Kızıldeniz Sahili', 'Afrika sahilindeki Osmanlı iskeleleri Portekiz korsanlarının tehdidi altında; Habeşistan ticareti durdu.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Özdemir Paşa\'ya bütçe ver; Masavva\'da taş hisar kurup Habeş Beylerbeyliği\'ni teşkil et.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Kızıldeniz\'in Afrika kapısı tutuldu; altın ve fildişi ticareti bağlandı."},{"label":"Afrika çölü masraflıdır; askerleri geri çekin.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zeyla ve Masavva İskelelerinin Tahkimi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Zeyla ve Masavva İskelelerinin Tahkimi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Zeyla ve Masavva İskelelerinin Tahkimi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 451) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_452', 'ottoman', 'Damla Sakızı Ağaçlarının Korunması', 'Sakız Adası', 'Sakız adasındaki çiftçiler, aşırı vergi yüzünden dünyada tek olan sakız ağaçlarını kesmeye başladı.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Özel \'Sakız Muafiyeti\' ver; ağaç kesmeyi yasakla ve çiftçiyi askerlikten bağışla.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Damla sakızı üretimi kurtarıldı; ada devlete sadakatle bağlandı."},{"label":"Vergiden muafiyet olmaz; tam vergi tahsil edilsin.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Damla Sakızı Ağaçlarının Korunması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Damla Sakızı Ağaçlarının Korunması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Damla Sakızı Ağaçlarının Korunması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 452) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_453', 'ottoman', 'Esir Düşen Leventlerin Kurtarılması', 'Akdeniz Sefareti', 'Malta zindanlarında kürek çeken 3 bin Osmanlı leventinin fidye ödenerek kurtarılması için aileleri divana yalvardı.', '[{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Devlet hazinesinden fidyeyi öde; \'Hiçbir levent küffar elinde çürütülemez!\'.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"3 bin cengaver yurda döndü; askerin devlete olan can feda bağlılığı perçinlendi."},{"label":"Çok paradır; aileleri kendi paralarını toplayıp kurtarsın.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Esir Düşen Leventlerin Kurtarılması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Esir Düşen Leventlerin Kurtarılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Esir Düşen Leventlerin Kurtarılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 453) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_454', 'ottoman', 'Tarihi Fenerin Temellerinde Çökme', 'İskenderiye Feneri', 'İskenderiye limanını koruyan Memlûk devri Kayıtbay Kalesi\'nin altındaki dalgakıran dalgalarla oyuldu.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Taş bloklarla dalgakıranı tahkim ettir; Mısır\'ın ana deniz kapısını sağlama al.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Kale kurtarıldı; İskenderiye limanı fırtınaya karşı korundu."},{"label":"Kalenin tamirini seneye bırakın; bütçe yetersiz.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Tarihi Fenerin Temellerinde Çökme hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Tarihi Fenerin Temellerinde Çökme hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Tarihi Fenerin Temellerinde Çökme gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 454) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_455', 'ottoman', 'Gemi Kalafatında Katran Yerine Domuz Yağı Hilesi', 'Tersane-i Âmire', 'Hain bir kethüdanın donanma kalyonlarının tahta aralarına katran yerine ucuz içyağı sürdürdüğü ortaya çıktı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kethüdayı idam et; bütün kalyonları karaya çektirip yeniden saf çam katranıyla kalafatlat.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Donanmanın su alıp batması engellendi; ihanet kılıçla kesildi."},{"label":"Gemileri denize indirin; bu seferlik idare eder.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Gemi Kalafatında Katran Yerine Domuz Yağı Hilesi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Gemi Kalafatında Katran Yerine Domuz Yağı Hilesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Gemi Kalafatında Katran Yerine Domuz Yağı Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 455) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_456', 'ottoman', 'Halkulvad Kalesinin Tahkimi', 'Tunus Beyliği', 'İspanyol donanmasının Tunus\'u işgal etmesini önlemek için Halkulvad boğazına yeni tabyalar yapılması istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mimar ve topçular gönder; boğazı geçilmez bir tabyalar zinciriyle donat.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Halkulvad çelikten bir kapı oldu; İspanyol armadası yanaşamadı."},{"label":"Tunus beyleri kendi paralarıyla yapsın; saray divan gözetiminde tarafları meşverete davet edip orta yolu bulz.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Halkulvad Kalesinin Tahkimi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Halkulvad Kalesinin Tahkimi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Halkulvad Kalesinin Tahkimi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 456) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_457', 'ottoman', 'Umman İmamlığı ile Ortak Ticaret Anlaşması', 'Basra Valiliği', 'Umman Sultanı, Hint Okyanusu\'nda İngiliz korsanlarına karşı Osmanlı bayrağı altında ortak ticaret filosu teklif etti.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Teklifi kabul et; Umman gemilerine Osmanlı sancağı ve koruma beratı ver.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Umman denizi Osmanlı nüfuzuna girdi; baharat kervanları güvenceye alındı."},{"label":"Uzak denizlerin siyasetine bulaşmayın; reddet.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Umman İmamlığı ile Ortak Ticaret Anlaşması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Umman İmamlığı ile Ortak Ticaret Anlaşması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Umman İmamlığı ile Ortak Ticaret Anlaşması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 457) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_458', 'ottoman', 'Korsanlıktan Tövbe Eden Leventlerin İskânı', 'Mora Sahilleri', 'Denizden yorulan binlerce levent Mora ve Tesalya sahillerinde tarlasını ekip balıkçılık yapmak istiyor.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_denizci_balikci","name":"Denizci / Balıkçı Esnafı"}]', '[{"label":"Sahil köyleri kurdur; leventlere kayık ve zeytinlik tahsis edip sahil muhafızı yap.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Korsanlar üretici köylü oldu; sahil boyları akınlara karşı emniyette."},{"label":"Korsan adam çiftçi olamaz; hepsini donanmada zorla tutun.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Korsanlıktan Tövbe Eden Leventlerin İskânı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Korsanlıktan Tövbe Eden Leventlerin İskânı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Korsanlıktan Tövbe Eden Leventlerin İskânı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 458) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_459', 'ottoman', 'Yabancı Kalyonların Liman İçinde Top Atışı Yapması', 'İzmir Limanı', 'Kendi bayramlarını kutlayan Fransız kalyonlarının liman ortasında izinsiz kurusıkı top atıp halkı paniğe soktuğu bildirildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Liman nizamnamesini işlet: İzinsiz top atan gemiye ağır para cezası kes ve barutuna el koy.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Devlet otoritesi gösterildi; yabancı kalyonlar haddini bildi."},{"label":"Frenk adetidir; elçileri küstürmemek için tarafları divanda dinleyip makul bir tazminat ve rıza ile sulh bağla.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Yabancı Kalyonların Liman İçinde Top Atışı Yapması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Yabancı Kalyonların Liman İçinde Top Atışı Yapması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Yabancı Kalyonların Liman İçinde Top Atışı Yapması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 459) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_460', 'ottoman', 'Buharlı Çarklı Gemi (Buğu Gemisi) Alımı', 'Tersane-i Âmire', 'İngiltere\'den küreksiz ve yelkensiz kömürle giden bir buharlı çarklı gemi getirilmesi teklif edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Hazineyi zorla da olsa gemiyi satın al; mühendislerimize motorunu inceletip tersanede kopyalat.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Osmanlı bahriyesi buhar çağına adım attı; Boğaz akıntıları dize getirildi."},{"label":"Gemi dediğin rüzgârla gider; kömür dumanına para verilmez.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Buharlı Çarklı Gemi (Buğu Gemisi) Alımı hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Buharlı Çarklı Gemi (Buğu Gemisi) Alımı hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Buharlı Çarklı Gemi (Buğu Gemisi) Alımı gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 460) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_461', 'ottoman', 'Yanya Ayânı Tepedelenli\'nin Kendi Vergisini Koyması', 'Rumeli Teftişi', 'Tepedelenli Ali Paşa, devletin kanunlarını hiçe sayıp köylüden şahsi ordusu için \'baş akçesi\' toplamaktadır.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Ferman çıkar: Kanunsuz vergi toplayan asi sayılır! Düzenli orduyu sevk edip kalesini kuşat.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Derebeylik ezildi; Rumeli reayası padişahın adil sancağı altında birleşti."},{"label":"Tepedelenli çok güçlüdür; topladığı vergiden pay isteyip uzlaş.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Yanya Ayânı Tepedelenli\'nin Kendi Vergisini Koyması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Yanya Ayânı Tepedelenli\'nin Kendi Vergisini Koyması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Yanya Ayânı Tepedelenli\'nin Kendi Vergisini Koyması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 461) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_462', 'ottoman', 'Mültezimin Aşar Vergisini İki Katına Çıkarması', 'Konya Sancağı', 'Açık artırmada mukataayı pahalıya alan mültezim, zararını çıkarmak için köylünün ambarındaki tohuma el koyuyor.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"İltizam sözleşmesini derhal fesh et; mültezimin malını müsadere edip tohumu çiftçiye iade et.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Köylü ekmek ve tohum buldu; tarlalar nadasa kalmaktan kurtuldu."},{"label":"Mültezim devlete peşin para ödemiştir; tahsilatına divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Mültezimin Aşar Vergisini İki Katına Çıkarması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Mültezimin Aşar Vergisini İki Katına Çıkarması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Mültezimin Aşar Vergisini İki Katına Çıkarması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 462) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_463', 'ottoman', 'Tütün Tarlalarında Kaçak Üretim İsyanı', 'Canik (Samsun) Sancağı', 'Devlet tekelinin düşük fiyat vermesini protesto eden Karadeniz tütüncüleri zaptiyeleri tarlaya sokmadı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Alım fiyatını piyasa rayicine yükselt; üreticiyi dinle ve aradaki tefeci komisyoncuları kov.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Tütüncülerle devlet barıştı; kaçakçılık bitti, vergi hasılatı arttı."},{"label":"Askeri birlik yolla; tarlaları ateşe verip direnenleri zincire vur.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tütün Tarlalarında Kaçak Üretim İsyanı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Tütün Tarlalarında Kaçak Üretim İsyanı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Tütün Tarlalarında Kaçak Üretim İsyanı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 463) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_464', 'ottoman', 'Cizre Mirinin Şahsi Gümrük Kurması', 'Diyar-ı Bekr', 'Cizre emiri, İpek Yolu üzerine kendi şahsi kulesini dikip geçen her deveden altın kesiyor.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Kuleyi top ateşiyle yıktır, miri tevkif et ve yolu yeniden umuma aç.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Korsan gümrük yıkıldı; kervanlar emniyetle akmaya devam etti."},{"label":"Mire meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla; bölge aşiretlerini arkasına alırsa başımıza dert olur.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Cizre Mirinin Şahsi Gümrük Kurması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Cizre Mirinin Şahsi Gümrük Kurması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Cizre Mirinin Şahsi Gümrük Kurması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 464) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_465', 'ottoman', 'Kozanoğlu Aşiretinin Sancak Beyini Kovması', 'Adana Ovası', 'Kozan dağlarındaki aşiret beyleri tayin edilen sancak beyini şehre sokmayıp kendi idarelerini ilan etti.', '[{"id":"char_sancak_beyi","name":"Sancak Beyi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Fırka-i İslâhiye ordusunu teşkil et; dağları kuşatıp aşireti ovada nizami iskâna bağla.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Çukurova\'da asırlık aşiret kargaşası bitti; merkezi idare kuruldu."},{"label":"Kozanoğlu\'na valilik rütbesi verip kendi haline bırak.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kozanoğlu Aşiretinin Sancak Beyini Kovması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kozanoğlu Aşiretinin Sancak Beyini Kovması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kozanoğlu Aşiretinin Sancak Beyini Kovması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 465) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_466', 'ottoman', 'Çiftbozanların Dağ Köylerinde Komün Hayatı', 'Bursa Kırsalı', 'Vergiden kaçan köylülerin orman içinde sahte isimlerle gizli köyler kurup devlete tek akçe vermediği tespit edildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Köylere af fermanı götür; onları tescil et, makul maktu vergiye bağla ve mektep aç.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Kaçak köyler nizama dahil edildi; halk devlete sevgiyle bağlandı."},{"label":"Köyleri ateşe ver, ahalisini eski topraklarına zorla sür.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çiftbozanların Dağ Köylerinde Komün Hayatı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Çiftbozanların Dağ Köylerinde Komün Hayatı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Çiftbozanların Dağ Köylerinde Komün Hayatı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 466) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_467', 'ottoman', 'Avarız Vergisinin Nakde Çevrilmesi İtirazı', 'Sıvas Vilayeti', 'Savaş masrafı için ayni (zahire) olarak alınan avarızın zorla nakit altın olarak istenmesi köylüyü yıktı.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Köylüyü dinle: Nakit parası olmayandan ambarındaki buğday ve arpayı ayni olarak kabul et.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Köylü sarrafın faizinden kurtuldu; ordunun erzak ihtiyacı çözüldü."},{"label":"Ordu nakit ister; gerekirse öküzlerini satıp altın getirsinler.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Avarız Vergisinin Nakde Çevrilmesi İtirazı nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Avarız Vergisinin Nakde Çevrilmesi İtirazı fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Avarız Vergisinin Nakde Çevrilmesi İtirazı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 467) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_468', 'ottoman', 'Atçalı Kel Mehmed İsyanı', 'Aydın Sancağı', 'Zengin ayânların köylüyü soymasına isyan eden Atçalı Kel Mehmed, \'Vali-i Vilayet, Hademe-i Devlet\' mührüyle dağa çıktı.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"İsyanın sebebini yerinde incelet; rüşvetçi ayânları görevden al ve halkın meşru taleplerini karşıla.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"İsyan tabanı eridi; adalet tesis edilince asiler silah bıraktı."},{"label":"Ayânların arkasında dur; isyancıların kellelerini payitahta getirt.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Atçalı Kel Mehmed İsyanı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Atçalı Kel Mehmed İsyanı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Atçalı Kel Mehmed İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 468) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_469', 'ottoman', 'Memlûk Beylerinin İrsaliye Hazinesini Kesmesi', 'Mısır Eyaleti', 'Kahire\'deki Memlûk beyleri payitahta her yıl gönderilen yıllık irsaliye altınlarını gasp etti.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Cezayirli Gazi Hasan Paşa\'yı donanmayla Mısır\'a gönder; asileri temizleyip hazineyi al.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Mısır hazinesi payitahta getirildi; Memlûk zorbalığı kırıldı."},{"label":"Savaşı göze almayın; Memlûklerle yarı yarıya anlaşın.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Memlûk Beylerinin İrsaliye Hazinesini Kesmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Memlûk Beylerinin İrsaliye Hazinesini Kesmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Memlûk Beylerinin İrsaliye Hazinesini Kesmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 469) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_470', 'ottoman', 'Tımar Arazilerinin Miras Gibi Paylaşılması', 'Kütahya Kadılığı', 'Vefat eden sipahinin oğulları, sefere katılmadıkları halde babalarının tımar arazisini kendi mülkleri gibi taksim etti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"}]', '[{"label":"Tımar kanununu işlet: Sefere katılmayan oğulların elinden dirligi al, yararlık gösteren neferlere ver.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Tımar nizamı disipline edildi; hakiki gaziler kılıç kuşandı."},{"label":"Aileyi mağdur etmeyin; arazinin üzerlerinde kalmasına izin verin.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Tımar Arazilerinin Miras Gibi Paylaşılması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Tımar Arazilerinin Miras Gibi Paylaşılması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Tımar Arazilerinin Miras Gibi Paylaşılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 470) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_471', 'ottoman', 'Tuzcuoğulları Ayân İsyanı', 'Trabzon Vilayeti', 'Karadeniz kıyısındaki Tuzcuoğlu ailesi kendi donanmasını kurup valinin sarayını topa tuttu.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Donanma kalyonlarını Karadeniz\'e sevk et; ayân kalelerini yıktır ve merkezi valiyi koru.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Karadeniz derebeyleri dize getirildi; devlet otoritesi yeniden parladı."},{"label":"Ayâna af çıkarıp Trabzon valiliğini ona teslim edin.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Tuzcuoğulları Ayân İsyanı nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Tuzcuoğulları Ayân İsyanı fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Tuzcuoğulları Ayân İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 471) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_472', 'ottoman', 'Kaçak Tuz Çıkaran Aşiretler', 'Erzurum Defterdarlığı', 'Aşiretler devletin tuzlası yerine kaçak tuz kuyuları açıp tekel gelirlerini yarı yarıya düşürdü.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tuz tekeli fiyatını düşür; aşiretlere taşıma hakkı vererek onları resmi sisteme ortak et.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Kaçakçılık bitti; aşiretler devletin resmi nakliyecisi oldu."},{"label":"Kuyuları taş ve zehirle doldurun; tuz çıkaranı asın.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak Tuz Çıkaran Aşiretler meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kaçak Tuz Çıkaran Aşiretler meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kaçak Tuz Çıkaran Aşiretler gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 472) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_473', 'ottoman', 'Bedesten Yangınında Mültezimin Malları', 'Edirne Çarşısı', 'Büyük yangında yanan bedestenin tamiri için dükkân kiralarının mültezim tarafından beş katına çıkarıldığı bildirildi.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Mültezimi durdur; bedesteni devlet bütçesiyle tamir ettirip esnafı eski kirasıyla yerleştir.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Esnaf kepenk kapatmaktan kurtuldu; Edirne çarşısı canlandı."},{"label":"Mültezim kendi masrafını çıkarmaktadır; divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Bedesten Yangınında Mültezimin Malları nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Bedesten Yangınında Mültezimin Malları fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Bedesten Yangınında Mültezimin Malları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 473) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_474', 'ottoman', 'Aşiretlerin Develerine Konan \'Ağnam\' Vergisi', 'Halep Kırsalı', 'Koyun vergisi olan ağnamın bedevilerin develerine de teşmil edilmesi üzerine aşiretler çöle çekildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kanun-ı Kadîm\'i uygula: Deveden ağnam alınamaz! Fermanı düzelt, develeri serbest bırak.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Aşiretler geri döndü; Halep-Şam ticaret kervanları deve buldu."},{"label":"Hazine para bekler; deveden de vergi alınsın.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Aşiretlerin Develerine Konan \'Ağnam\' Vergisi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Aşiretlerin Develerine Konan \'Ağnam\' Vergisi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Aşiretlerin Develerine Konan \'Ağnam\' Vergisi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 474) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_475', 'ottoman', 'Sened-i İttifak: Ayânlarla Sözleşme Teklifi', 'Dîvân-ı Hümâyûn', 'Sadrazam, taşra ayânlarını payitahta toplayıp devletin yetkilerini onlarla paylaşan bir sözleşme imzalamak istiyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Reddet! Hükümranlık bölünemez; ayânlara hadlerini bildirip merkezi otoriteyi yeniden kur.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Padişahın mutlak meşruiyeti korundu; feodal parçalanma önlendi."},{"label":"İmzala; ayânların askeri desteği olmadan ordu kurulamaz.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Sened-i İttifak: Ayânlarla Sözleşme Teklifi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Sened-i İttifak: Ayânlarla Sözleşme Teklifi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Sened-i İttifak: Ayânlarla Sözleşme Teklifi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 475) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_476', 'ottoman', 'Karaosmanoğlu Ailesinin Aşevi Vakıfları', 'Manisa Vilayeti', 'Bölgenin güçlü ayânı Karaosmanoğlu, halkı doyurmak için devasa aşevleri kurup devletten daha çok itibar kazandı.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Ayânı taltif et ama devletin kendi imaretlerini iki katına çıkar; hayırda devleti geride bıraktırma.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Halk devletin merhametini hissetti; ayânın gücü dengeye alındı."},{"label":"Halkı devlete karşı kışkırtıyor diyerek ayânın aşevlerini kapattır.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Karaosmanoğlu Ailesinin Aşevi Vakıfları nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Karaosmanoğlu Ailesinin Aşevi Vakıfları fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Karaosmanoğlu Ailesinin Aşevi Vakıfları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 476) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_477', 'ottoman', 'İl İltizamında Sarraf Kefaleti Şartı', 'Taşra Teftişi', 'Mültezimlerin köylüyü soymaması için Galata sarraflarının peşin kefalet mektubu getirmesi teklif edildi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"Kefalet şartını koy; köylüyü ezen mültezimin kefaletini yakıp hazineye irat kaydet.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Vahşi mültezimler frenlendi; köylünün malı teminata bağlandı."},{"label":"Sarrafları işe karıştırmayın; mültezimler rahat çalışsın.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve İl İltizamında Sarraf Kefaleti Şartı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve İl İltizamında Sarraf Kefaleti Şartı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve İl İltizamında Sarraf Kefaleti Şartı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 477) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_478', 'ottoman', 'Çerkes Aşiretlerinin Yaylak Hakkı', 'Sivas Yaylaları', 'Kuzeyden gelen Çerkes muhacirlerin sürüleri için yerel Türkmenlerin kadim otlaklarının bölünmesi gerekti.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kadı heyetiyle yaylaları adilce böl; muhacire yer açarken Türkmen\'in hakkını gasp ettirme.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Kardeşlik hukuku korundu; iki aşiret barış içinde kaynaştı."},{"label":"Muhacirleri Türkmenlerin sırtına yık; aralarındaki kavgaya divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çerkes Aşiretlerinin Yaylak Hakkı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Çerkes Aşiretlerinin Yaylak Hakkı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Çerkes Aşiretlerinin Yaylak Hakkı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 478) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_479', 'ottoman', 'Kölemen (Memlûk) Valilerinin Başına Buyruk İdaresi', 'Bağdat Eyaleti', 'Bağdat\'taki Gürcü asıllı Kölemen valisi, payitahttan gönderilen defterdarları şehre sokmuyor.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Bağdat üzerine ordu sevk et; Kölemen vesayetini yıkıp doğrudan merkezi vilayet nizamı kur.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Irak doğrudan merkeze bağlandı; devletin birliği korundu."},{"label":"Vergi yolladıkları sürece valiye meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kölemen (Memlûk) Valilerinin Başına Buyruk İdaresi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kölemen (Memlûk) Valilerinin Başına Buyruk İdaresi fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kölemen (Memlûk) Valilerinin Başına Buyruk İdaresi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 479) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_480', 'ottoman', 'Tanzimat Fermanı Taslağı: Can, Mal ve Namus Emniyeti', 'Dîvân-ı Hümâyûn', 'Gülhane Parkı\'nda okunmak üzere tebaanın din farkı gözetilmeksizin can, mal ve ırzının kanun teminatına alınması teklif edildi.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Fermanı mühürle: \'Hiçbir tebaanın malı müsaderesiz ve yargısız elinden alınamaz!\'.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Mülkiyet ve hayat hakkı kanunlaştı; devlet modern bir hukuk nizamına kavuştu."},{"label":"Geleneksel mutlak otoriteyi bozmayın; fermanı yırtın.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Tanzimat Fermanı Taslağı: Can, Mal ve Namus Emniyeti nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Tanzimat Fermanı Taslağı: Can, Mal ve Namus Emniyeti fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tanzimat Fermanı Taslağı: Can, Mal ve Namus Emniyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 480) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_481', 'ottoman', 'Beşik Uleması Rezaleti (Doğuştan Müderrislik)', 'Süleymaniye Medresesi', 'Ulema çocuklarının henüz kundaktayken rütbe alıp genç yaşta büyük medreselere müderris tayin edildiği belgelendi.', '[{"id":"char_muderris","name":"Medrese Müderrisi"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Beşik ulemalığını kökten lağvet! İmtihansız rütbe alan tüm çocukların pâyesini geri al.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"İlmiye zümresinde liyakat kurtarıldı; hakiki âlimlerin önü açıldı."},{"label":"Ulemanın hatırını kırma; çocuklarının rütbelerine meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Beşik Uleması Rezaleti (Doğuştan Müderrislik) meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Beşik Uleması Rezaleti (Doğuştan Müderrislik) meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Beşik Uleması Rezaleti (Doğuştan Müderrislik) gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 481) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_482', 'ottoman', 'Şeriat Hükümlerinin Kanunlaştırılması (Mecelle Taslağı)', 'Kazaskerlik Meclisi', 'Ahmet Cevdet Paşa, İslam borçlar ve ticaret hukukunu modern maddeler halinde yazılı bir kanun kitabı (Mecelle) yapmayı önerdi.', '[{"id":"char_ahmet_cevdet_pasa","name":"Ahmet Cevdet Paşa"},{"id":"char_kazasker","name":"Kazasker"}]', '[{"label":"Komisyonu kurdur ve Mecelle\'yi kanunlaştır; kadıların keyfi hüküm vermesini engelle.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"İslam hukuku cihan çapında bir kanun abidesi oldu; mahkemeler hızlandı."},{"label":"Fıkıh kitapları kafidir; kanunlaştırmak bid\'attir diyerek reddet.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Şeriat Hükümlerinin Kanunlaştırılması (Mecelle Taslağı) nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Şeriat Hükümlerinin Kanunlaştırılması (Mecelle Taslağı) fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Şeriat Hükümlerinin Kanunlaştırılması (Mecelle Taslağı) meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 482) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_483', 'ottoman', 'Fransız Kanunlarının Körükörüne Tercümesi', 'Bab-ı Âli Tercüme Odası', 'Bazı Batıcı bürokratlar, yerli örf ve İslam hukukunu tamamen çöpe atıp Fransız ceza kanununu aynen almayı teklif etti.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Kör taklitçiliği reddet! Kanunları kendi inanç ve medeniyet köklerimizden süzerek modernize et.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Milli ve şer\'i hukuk nizamı çağdaşlaştı; cemiyet ruhunu kaybetmedi."},{"label":"Aynen tercüme edip kabul edin; Avrupa ne derse doğrudur.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Fransız Kanunlarının Körükörüne Tercümesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Fransız Kanunlarının Körükörüne Tercümesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Fransız Kanunlarının Körükörüne Tercümesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 483) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_484', 'ottoman', 'Mekteb-i Mülkiye\'nin Kurulması', 'Topkapı Enderun Mektebi', 'Taşraya gönderilecek kaymakam ve valilerin liyakatli, hukuk ve iktisat bilen mektepli gençlerden seçilmesi istendi.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_mulkiyeli_idareci","name":"Mülkiyeli Genç İdareci"}]', '[{"label":"Mülkiye Mektebi\'ni derhal kur; kaymakamlık makamını tahsilli vatan evlatlarına tahsis et.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Taşra idaresi cahil ağalardan kurtuldu; modern ve adil idareciler yetişti."},{"label":"Valilik tecrübe işidir; mektepten idareci çıkmaz.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mekteb-i Mülkiye\'nin Kurulması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Mekteb-i Mülkiye\'nin Kurulması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Mekteb-i Mülkiye\'nin Kurulması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 484) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_485', 'ottoman', 'Yetim Sandıklarının (Memleket Sandıkları) Kurulması', 'Şeyhülislam Kapısı', 'Mithat Paşa, köylüyü tefecinin elinden kurtarmak için imece usulüyle ilk ziraat kredi sandıklarını teklif etti.', '[{"id":"char_mithat_pasa","name":"Mithat Paşa"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Memleket Sandıkları\'nı onaylayıp sermaye bağla; köylünün kendi bankasını kurdur.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Ziraat Bankası\'nın temeli atıldı; köylü tefecinin pençesinden ebediyen kurtuldu."},{"label":"Köylüye para emanet edilmez; sandık projesini durdur.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Yetim Sandıklarının (Memleket Sandıkları) Kurulması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Yetim Sandıklarının (Memleket Sandıkları) Kurulması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Yetim Sandıklarının (Memleket Sandıkları) Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 485) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_486', 'ottoman', 'Medrese Talebelerinin Askerlikten Muafiyeti', 'İstanbul Medreseleri', 'On binlerce tembel gencin sırf askere gitmemek için medreselere sahte kayıt yaptırıp sokaklarda gezdiği anlaşıldı.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sıkı ilim sınavı yap; hakiki okumayan sahte talebeleri derhal askere al.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Medreseler asalaklardan temizlendi; ordu safları gençlerle doldu."},{"label":"Talebe-i ulumdur, meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın; ulema gücenmesin.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Medrese Talebelerinin Askerlikten Muafiyeti nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Medrese Talebelerinin Askerlikten Muafiyeti fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Medrese Talebelerinin Askerlikten Muafiyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 486) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_487', 'ottoman', 'Düyun-ı Umumiye İdaresi Tehdidi', 'Bab-ı Âli Evrak Odası', 'Avrupalı alacaklılar, dış borçlar ödenmediği için tuz, tütün ve ipek vergilerine doğrudan el koymak istiyor.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_yabanci_banker","name":"Yabancı Banker (Düyun-ı Umumiye)"}]', '[{"label":"Saray harcamalarını sıfırla, tasarruf seferberliği ilan et ama mali egemenliği teslim etme.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Devletin mali istiklali korundu; sömürge tuzağı reddedildi."},{"label":"Çaresiziz; vergileri yabancı bankerlerin idaresine terk edin.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Düyun-ı Umumiye İdaresi Tehdidi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Düyun-ı Umumiye İdaresi Tehdidi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Düyun-ı Umumiye İdaresi Tehdidi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 487) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_488', 'ottoman', 'Halka Açık Umumi Fen Konferansları', 'Darülfünun (Üniversite)', 'Kimya, fizik ve buhar makinelerinin halka tanıtıldığı derslerde muhafazakâr vaizlerin \'Büyücülüktür\' diye ayaklandığı bildirildi.', '[{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"İlim meclislerini koru! Vaizleri ikaz et: \'Kâinatın sırlarını araştırmak Allah\'ın emridir.\'.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Cehalet taassubu geriletildi; halk modern ilimlerle kucaklaştı."},{"label":"Halk galeyana gelmesin; fen derslerini tatil edin.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Halka Açık Umumi Fen Konferansları nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Halka Açık Umumi Fen Konferansları fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Halka Açık Umumi Fen Konferansları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 488) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_489', 'ottoman', 'Rüşvetle Mücadele Kanunnâmesi', 'Divan Meclisi', 'Devlet erkânının aldığı en küçük hediyenin dahi zimmet sayılmasını emreden kanun taslağı vezirleri korkuttu.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Kanunu tereddütsüz tasdikle: \'Rüşvet alan da veren de mel\'undur!\' Hediye devri bitti.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Devlet çarkı haramdan arındırıldı; adalet mülkün temeli oldu."},{"label":"Hediyeleşmek sünnettir deyip vezirlerin rüşvetine kılıf uydur.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Rüşvetle Mücadele Kanunnâmesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Rüşvetle Mücadele Kanunnâmesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Rüşvetle Mücadele Kanunnâmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 489) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_490', 'ottoman', 'Dış Borçların Saray İnşaatlarına Harcanması', 'Hariciye Nezareti', 'Avrupa\'dan demiryolu ve fabrika için alınan kredilerin Boğaz\'da yeni mermer saraylara harcanması istendi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Asla! Borç parayla mermer saray yapılmaz; her kuruşunu demiryoluna ve fabrikaya yatır.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Anadolu demir ağlarla örüldü; üretim patladı, borç ödendi."},{"label":"Saray devletin itibarıdır; inşaata devam edin.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Dış Borçların Saray İnşaatlarına Harcanması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Dış Borçların Saray İnşaatlarına Harcanması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Dış Borçların Saray İnşaatlarına Harcanması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 490) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_491', 'ottoman', 'Katip Çelebi\'nin \'Düstûrü\'l-Amel\' Raporu', 'Süleymaniye Kütüphanesi', 'Devletin canlı bir organizma olduğunu, aşırı şişen ordunun ve bürokrasinin milleti ezdiğini söyleyen ıslahat raporu sunuldu.', '[{"id":"char_katip_celebi","name":"Kâtip Çelebi"}]', '[{"label":"Raporu başucu kitabı yap: Asker sayısını liyakatle sınırla, gereksiz memurları tasfiye et.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Bürokratik kambur kesilip atıldı; devlet yeniden gençleşti."},{"label":"Masa başı âliminin aklına ihtiyacımız yok deyip risaleyi yaktır.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Katip Çelebi\'nin \'Düstûrü\'l-Amel\' Raporu nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Katip Çelebi\'nin \'Düstûrü\'l-Amel\' Raporu fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Katip Çelebi\'nin \'Düstûrü\'l-Amel\' Raporu meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 491) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_492', 'ottoman', 'Gayrimüslimlerin Askerlik Bedeli (Bedel-i Askerî)', 'Kazaskerlik Meclisi', 'Hristiyan tebaanın fiilen orduya girmek yerine devlete nakit bedel ödemesi sistemi tartışıldı.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Sistemi kanunlaştır: İsteyen vatan için kılıç kuşansın, istemeyen bedelini ödeyip ticaretinde kalsın.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Hazine nakit kazandı; ordu karmaşadan kurtuldu, ticaret sürdü."},{"label":"Zorla askere alın; gelmeyeni vatan haini sayın.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Gayrimüslimlerin Askerlik Bedeli (Bedel-i Askerî) nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Gayrimüslimlerin Askerlik Bedeli (Bedel-i Askerî) fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Gayrimüslimlerin Askerlik Bedeli (Bedel-i Askerî) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 492) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_493', 'ottoman', 'Koçi Bey\'in IV. Murad\'a Sunduğu Layiha', 'Topkapı Hazine Odası', 'Rüşvetin, iltimasın ve padişahın halktan kopmasının devleti nasıl çürüttüğünü anlatan açık sözlü layiha geldi.', '[{"id":"char_koci_bey","name":"Koçi Bey"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Koçi Bey\'i veziriazam danışmanı yap; rüşvet çarkını kıran sert adalet devrini başlat.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Taşlar yerine oturdu; IV. Murad devrinin celadeti ve adaleti doğdu."},{"label":"Padişahı eleştirmek kimin haddine deyip Koçi Bey\'i sürgüne yolla.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Koçi Bey\'in IV. Murad\'a Sunduğu Layiha hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Koçi Bey\'in IV. Murad\'a Sunduğu Layiha hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Koçi Bey\'in IV. Murad\'a Sunduğu Layiha gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 493) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_494', 'ottoman', 'Vilayet İdare Meclislerinin Kurulması', 'İstanbul Şehremaneti', 'Taşra vilayetlerinde halkın seçtiği temsilcilerin valinin yanında danışma meclisi kurması istendi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Vilayet Meclislerini aç; valilerin keyfi kararlarını halkın meclisiyle denetlet.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Halk kendi idaresinde söz sahibi oldu; devlete bağlılık perçinlendi."},{"label":"Halkın fikri alınmaz; vali mutlak hakimdir.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Vilayet İdare Meclislerinin Kurulması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Vilayet İdare Meclislerinin Kurulması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Vilayet İdare Meclislerinin Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 494) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_495', 'ottoman', 'Telgraf Hatlarının Kurulması ve İstihbarat', 'Bab-ı Âli Postahanesi', 'Şam, Bağdat ve Manastır\'a telgraf telleri çekilirse taşradaki zulüm ve isyan anında saraya bildirilebilir.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütçe tahsis et; telgraf direklerini imparatorluğun her köşesine diktir.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Taşra sarayın gözü önünde oldu; zalim valilerin nefesi kesildi."},{"label":"Ulak atları yetişiyor; telgrafa altın dökülmez.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Telgraf Hatlarının Kurulması ve İstihbarat nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Telgraf Hatlarının Kurulması ve İstihbarat fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Telgraf Hatlarının Kurulması ve İstihbarat meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 495) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_496', 'ottoman', 'İlmiye Mensuplarının Ticaret Yapma Yasağı', 'Şeyhülislam ve Ulema Heyeti', 'Kadı ve müftülerin ticaret ortaklıkları kurarak baktıkları davalarda kendi şirketlerini kayırdığı görüldü.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Ferman neşret: Hâkim ticaret yapamaz! Yapanın cübbesini al ve meslekten ihraç et.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Yargı sermaye bağından koparıldı; terazinin dengesi kurtarıldı."},{"label":"Ticaret sünnettir; kadıların zenginleşmesine mani olma.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İlmiye Mensuplarının Ticaret Yapma Yasağı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İlmiye Mensuplarının Ticaret Yapma Yasağı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İlmiye Mensuplarının Ticaret Yapma Yasağı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 496) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_497', 'ottoman', 'Darülaceze ve Şefkat Yuvalarının Açılması', 'Hassa Mimarları', 'Kimsesiz ihtiyarlar, sakatlar ve sahipsiz çocuklar için payitahtta devasa bir Şefkat Yuvası kurulması teklif edildi.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Padişahın şahsi servetiyle Darülaceze\'yi inşa ettir; din farkı gözetmeden kimsesizleri bağrına bas.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Merhametin zirvesi dünyaya örnek oldu; fukaranın duası mülkü korudu."},{"label":"Herkesin bir akrabası vardır; devlete dilenci evi açtırmayın.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Darülaceze ve Şefkat Yuvalarının Açılması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Darülaceze ve Şefkat Yuvalarının Açılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Darülaceze ve Şefkat Yuvalarının Açılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 497) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_498', 'ottoman', 'Devlet Memurlarının Mal Beyanı Mecburiyeti', 'Bab-ı Âli İstişare Meclisi', 'Göreve başlayan her valinin, vezirin ve defterdarın servetini beyan etmesi, çıkışta haksız zenginleşenin mallarının müsaderesi istendi.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Mal Beyanı Kanunu\'nu ilan et; kursağından tek haram lokma geçen memuru teftişle açığa çıkar.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Bürokraside hırsızlığın kökü kazındı; devlet kadroları tertemiz oldu."},{"label":"Memurların şahsi mahremiyetidir; hesap sormak fitne çıkarır.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Devlet Memurlarının Mal Beyanı Mecburiyeti nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Devlet Memurlarının Mal Beyanı Mecburiyeti fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Devlet Memurlarının Mal Beyanı Mecburiyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 498) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_499', 'ottoman', 'Umranın Kemali: Asabiyeden Adalete Geçiş', 'İbn Haldun\'un İhtarı', 'Mukaddime\'nin son sahifesini açan bilge sorar: \'Ey Hakan! Göçebe asabiyesiyle fethedilen mülk, yerleşik hayata geçince neden çöker?\'', '[{"id":"char_ibn_haldun","name":"İbn Haldun"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"\'Lüks, israf ve zulüm asabiyeyi öldürür; onu diriltecek ve devleti ebedi kılacak tek iksir ADALETTİR!\'.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"İbn Haldun\'un hikmeti tecelli etti; devlet kaçınılmaz biyolojik ömrü aşıp ebed-müddet oldu."},{"label":"\'Devletlerin ölümü kaçınılmazdır; harca, ye ve zevkine bak.\'.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Umranın Kemali: Asabiyeden Adalete Geçiş meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Umranın Kemali: Asabiyeden Adalete Geçiş meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Umranın Kemali: Asabiyeden Adalete Geçiş gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 499) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_500', 'ottoman', 'Cihan Nizamı ve İnsan-ı Kâmil Saltanatı', 'Dâire-i Adliyye Zirvesi', 'Beş yüz yıllık hükmün sonunda Kınalızâde, Nizamülmülk ve Mâverdî huzura gelir: \'Ey Âdil Hükümdar! Mührün üzerine ne yazalım?\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'ADLDIR MÛCİB-İ SALÂH-I CİHÂN, CİHÂN BİR BÂĞDIR DÎVÂRI DEVLET!\'.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Adalet çemberi kainat nizamıyla kenetlendi; mülk dünya durdukça yaşayacak bir kutba dönüştü."},{"label":"\'Kudret ve mülk sadece benimdir!\'.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Cihan Nizamı ve İnsan-ı Kâmil Saltanatı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Cihan Nizamı ve İnsan-ı Kâmil Saltanatı fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Cihan Nizamı ve İnsan-ı Kâmil Saltanatı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 500) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_501', 'ottoman', 'Akıl Hastalarına Afyon Yerine Şerbet Tedavisi', 'Haseki Darüşşifası', 'Darüşşifa baştabibi, asabi buhran geçiren hastalara ağır afyon verilmesinin zihinleri körelttiğini, nilüfer şerbeti ve müzikle sekinet verilmesini teklif etti.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_darussifa_bastabibi","name":"Darüşşifa Baştabibi"}]', '[{"label":"Tabibin teklifini onayla; hekim heyetine şifalı bitki bahçesi tahsis et.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Bimarhanede şefkatli tedavi usulü yerleşti; hastalar afyon bağımlılığından kurtuldu."},{"label":"Afyon ucuz ve hızlıdır; eski usul uyuşturmaya devam edin.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Akıl Hastalarına Afyon Yerine Şerbet Tedavisi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Akıl Hastalarına Afyon Yerine Şerbet Tedavisi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Akıl Hastalarına Afyon Yerine Şerbet Tedavisi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 501) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_502', 'ottoman', 'Gedik Hakkının Miras Yoluyla Yabancıya Satışı', 'Ahi Ocakları', 'Vefat eden saraç ustasının varisleri, dükkân açma hakkını (gedik) meslekten anlamayan tefeci bir sarrafa satmak için izin istiyor.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Gedik yabancıya satılamaz! Hakkı loncanın liyakatli kıdemli kalfasına devrettir.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Zanaat ehliyetsiz tüccarların eline geçmekten kurtarıldı; çırakların hakkı korundu."},{"label":"Miras haktır; en yüksek parayı veren sarrafa satılmasına izin ver.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik Hakkının Miras Yoluyla Yabancıya Satışı davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Gedik Hakkının Miras Yoluyla Yabancıya Satışı davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Gedik Hakkının Miras Yoluyla Yabancıya Satışı gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 502) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_503', 'ottoman', 'Hafsa Sultan İmarethanesinde Yağ Hırsızlığı', 'Manisa Vakıf Teftişi', 'İmarethanenin aşçıbaşısının fukara kazanına koyması gereken sadeyağı gizlice tenekelerle çarşıdaki börekçilere sattığı belgelendi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Aşçıbaşını azledip malını müsadere et; imaret kazanlarını her gün denetlet.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Fukara çorbası koyulaştı; vakıf emanetine el uzatanın eli kırıldı."},{"label":"İmaret işleri karışık olur; aşçıbaşının kulağını çekip affet.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Hafsa Sultan İmarethanesinde Yağ Hırsızlığı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Hafsa Sultan İmarethanesinde Yağ Hırsızlığı fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Hafsa Sultan İmarethanesinde Yağ Hırsızlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 503) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_504', 'ottoman', 'Yetim Kalmış Ermeni Çocukların Mirası', 'İstanbul Kadılığı', 'Ölen kuyumcunun mirasını bölüşmek isteyen yerel eşraf, yetim çocukların yaşını büyük gösterip mallarına çökmeye çalışıyor.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Cemaat defterlerini bizzat kadı huzurunda incelet; çocukların vasiliğini adil patrikhane meclisine ver.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Yetim hakkı din farkı gözetilmeden korundu; Osmanlı adaletinin şanı yükseldi."},{"label":"Müslüman eşrafı koru; gayrimüslim davasını sürüncemede bırak.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Yetim Kalmış Ermeni Çocukların Mirası nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Yetim Kalmış Ermeni Çocukların Mirası fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Yetim Kalmış Ermeni Çocukların Mirası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 504) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_505', 'ottoman', 'Köy Camii İmamının Vakıf Tarlasını Sürmemesi', 'Kaza Sicili', 'İmam efendi, kendisine tahsis edilen vakıf tarlasını ekmeyip çorak bıraktı ve üstüne cemaatten zorla zahire topladı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"İmamı uyar: Ya tarlayı ekip hakkını helal ettirsin ya da vazifeden el çektir.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Toprak berekete kavuştu; köylünün sırtındaki haksız zahire yükü kalktı."},{"label":"Diyanet ehlidir, köylü ona bakmakla mükelleftir deyip divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Köy Camii İmamının Vakıf Tarlasını Sürmemesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Köy Camii İmamının Vakıf Tarlasını Sürmemesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Köy Camii İmamının Vakıf Tarlasını Sürmemesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 505) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_506', 'ottoman', 'Deri Tabaklamada Meşe Palamudu Hilesi', 'Bursa Debbağhanesi', 'Debbağ ustalarının palamut yerine kireç kullanıp derileri hızla incelttiği, dikilen çizmelerin ilk yağmurda yırtıldığı anlaşıldı.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Kireçli tabaklamayı yasakla; palamut ambarlarını denetletip kurallara uymayanın lonca beratını yak.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Bursa derisi eski sağlamlığına kavuştu; asker sağlam çizmeyle donandı."},{"label":"Palamut pahalıdır; kireçle hızlı imalata yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Deri Tabaklamada Meşe Palamudu Hilesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Deri Tabaklamada Meşe Palamudu Hilesi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Deri Tabaklamada Meşe Palamudu Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 506) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_507', 'ottoman', 'Darüşşifa Hekimlerinin Özel Muayenehane Açması', 'Süleymaniye Darüşşifası', 'Maaşlı vakıf tabiplerinin hastanedeki fakirleri savsaklayıp zengin konaklarına ücretli özel tedavilere gittiği ihbar edildi.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Hekimlere mesai mecburiyeti koy; hastaneyi terk edip dışarıda para kazananı azlet.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Fukara kapıda beklemekten kurtuldu; tabipler hastaların başına döndü."},{"label":"Tabipler muteberdir; ek gelirlerine karışıp onları küstürme.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Darüşşifa Hekimlerinin Özel Muayenehane Açması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Darüşşifa Hekimlerinin Özel Muayenehane Açması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Darüşşifa Hekimlerinin Özel Muayenehane Açması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 507) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_508', 'ottoman', 'Vakıf Çeşmelerinin Borularına Kaçak Bağlantı', 'İstanbul Şehremaneti', 'Bir paşanın konağının hamamına su çekmek için halka açık vakıf çeşmesinin ana künkünü deldirdiği tespit edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Kaçak künkü söktür, paşaya ağır para cezası kes ve suyu çeşmeye geri akıt.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Mahalle çeşmesi gürül gürül aktı; paşanın zorbalığı halkın önünde ezildi."},{"label":"Paşadır, şanına yakışır hamamı olsun deyip ceza kesme.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf Çeşmelerinin Borularına Kaçak Bağlantı meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Vakıf Çeşmelerinin Borularına Kaçak Bağlantı hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Vakıf Çeşmelerinin Borularına Kaçak Bağlantı gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 508) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_509', 'ottoman', 'Çeltik Ağalarının Su Arkını Vakıf Arazisinden Geçirmesi', 'Edirne Mahkemesi', 'Ağaların kendi tarlalarını sulamak için vakıf otlağını yarıp bataklığa çevirdiği, köylünün ineklerinin boğulduğu arz edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Arkı ağaların kendi arazisine kazdır; köylünün ziyanını ağalara kuruşu kuruşuna tazmin ettir.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Zorbalık durduruldu; köylünün hayvanları ve merası kurtarıldı."},{"label":"Pirinç saraya lazımdır; ağaların arkına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Çeltik Ağalarının Su Arkını Vakıf Arazisinden Geçirmesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Çeltik Ağalarının Su Arkını Vakıf Arazisinden Geçirmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Çeltik Ağalarının Su Arkını Vakıf Arazisinden Geçirmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 509) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_510', 'ottoman', 'Ekmekçi Kalfalarının Ustalık İmtihanı İsyanı', 'Ahi Teşkilatı', 'Yaşlı fırıncı ustalarının kalfalara sınav hakkı vermeyip mesleği kendi beceriksiz oğullarına sakladığı bildirildi.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Kadı ve muhtesip huzurunda açık imtihan yaptır; hakkı olan kalfaya dükkân beratını ver.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Liyakat kapısı açıldı; ekmekçilikte genç ve çalışkan ustalar yetişti."},{"label":"Loncanın iç kuralıdır; yaşlı ustaların sözünü çiğneme.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Ekmekçi Kalfalarının Ustalık İmtihanı İsyanı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Ekmekçi Kalfalarının Ustalık İmtihanı İsyanı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Ekmekçi Kalfalarının Ustalık İmtihanı İsyanı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 510) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_511', 'ottoman', 'Sadaka Taşlarındaki Paraların Çalınması', 'İstanbul Kadılığı', 'Cami avlularındaki sadaka taşlarına fukara için bırakılan akçeleri gece vakti soyan bir yankesici çetesi yakalandı.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Çete elebaşlarını küreğe koy; avlulara gece kandili ve bekçi nöbeti tahsis et.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Mazlumun gizli rızkı emniyete alındı; sadaka geleneği ihya edildi."},{"label":"Sadaka parası sahipsizdir deyip yankesicileri hafif cezayla sal.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Sadaka Taşlarındaki Paraların Çalınması hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Sadaka Taşlarındaki Paraların Çalınması hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Sadaka Taşlarındaki Paraların Çalınması gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 511) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_512', 'ottoman', 'Afyonkeşlere Karşı Panzehir Şurubu Dağıtımı', 'Hekimbaşılık Tezkiresi', 'Hekimbaşı, zehirlenmelere ve uyuşturucu illetine karşı saray hekimlerinin geliştirdiği tiryak şurubunun kaza hekimlerine bedava yollanmasını teklif etti.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Bütçe ayır; şurubu taşra kaza hekimlerine ulaştır ve fukaradan para alma.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Zehirlenmelerden yüzlerce can kurtarıldı; devletin sıhhi şefkati taşa toprağa ulaştı."},{"label":"İlacı sadece parası olan zenginlere satın; hazineye irat kaydedin.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Afyonkeşlere Karşı Panzehir Şurubu Dağıtımı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Afyonkeşlere Karşı Panzehir Şurubu Dağıtımı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Afyonkeşlere Karşı Panzehir Şurubu Dağıtımı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 512) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_513', 'ottoman', 'Vakıf Hanlarının Gayrimeşru Kiraya Verilmesi', 'Dîvân-ı Hümâyûn', 'Mütevellinin, Fatih Vakfı\'na ait büyük bir kervansarayı ucuza kiralayıp meyhane ve batakhane işletmecilerine alt kiraya verdiği ortaya çıktı.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sözleşmeyi derhal yırt, mütevelliyi hapse at ve hanı zanaatkar atölyelerine tahsis et.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Vakıf kirlilikten arındırıldı; esnaf hanlarda helal ekmeğini kazandı."},{"label":"Gelen kira yüksektir; parasına bakıp işletmeciye meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Vakıf Hanlarının Gayrimeşru Kiraya Verilmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Vakıf Hanlarının Gayrimeşru Kiraya Verilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Vakıf Hanlarının Gayrimeşru Kiraya Verilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 513) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_514', 'ottoman', 'Yetim Kızlara Çeyiz Vakfı Kurulması', 'Kaza Müftülüğü', 'Zengin bir hanım sultan, kimsesiz fukara kızların evlenebilmesi için tüm altınlarını çeyiz vakfına bağışlamak istiyor.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_muftu","name":"Müftü"}]', '[{"label":"Vakfiyeyi tasdikle, duayla onay ver ve idaresini tarafsız eminlere emanet et.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Yüzlerce yetim kız yuva kurdu; toplumda ahlak ve şefkat köprüsü kuruldu."},{"label":"Altınları ordu bütçesine al; çeyiz işine sonradan bakarız.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yetim Kızlara Çeyiz Vakfı Kurulması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Yetim Kızlara Çeyiz Vakfı Kurulması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Yetim Kızlara Çeyiz Vakfı Kurulması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 514) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_515', 'ottoman', 'İpek İmalatında Ham Pamuk Karışımı', 'Bursa İpekçileri', 'Bazı tezgâh sahipleri saf ipek dokumalara gizlice pamuk ipliği karıştırıp saraya \'saf harir\' diye sattı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Kumaşları yaktır, tağşiş yapan atölyeleri kapat ve saray siparişini dürüst ustalara ver.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Osmanlı kumaşının uluslararası şerefi korundu; sahtecilik durduruldu."},{"label":"Gözle fark edilmiyor; pamuklu ipeği ucuza kabul edin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve İpek İmalatında Ham Pamuk Karışımı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve İpek İmalatında Ham Pamuk Karışımı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve İpek İmalatında Ham Pamuk Karışımı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 515) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_516', 'ottoman', 'Kaldırımların Bozulması ve Nal Kırılması', 'İstanbul Şehremaneti', 'Payitaht sokaklarındaki arnavutkaldırımları çöktü; yük beygirlerinin ayakları kırılıyor, arabalar devriliyor.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Kaldırımcılar loncasına ödenek çıkar; sokakları taştan ve eğimli su oluklarıyla yeniden döşet.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Sokaklar çamurdan ve çukurdan kurtuldu; ticaret ve ulaşım hızlandı."},{"label":"Mahalleli kendi kapısının önünü kendisi döşesin; bütçe yok.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kaldırımların Bozulması ve Nal Kırılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kaldırımların Bozulması ve Nal Kırılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kaldırımların Bozulması ve Nal Kırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 516) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_517', 'ottoman', 'Kütüphane Vakfından Kitap Çalan Müderris', 'Kaza Meclisi', 'Bir müderrisin ödünç aldığı tıp ve astronomi risalelerini kütüphaneye iade etmeyip kendi kütüphanesine kilitlediği kanıtlandı.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_muderris","name":"Medrese Müderrisi"}]', '[{"label":"Kitapları zorla geri aldır, müderrisi kürsüsünden azlet ve adını kara tahtaya yaz.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"İlim emaneti kurtarıldı; talebeler kitaplarına yeniden kavuştu."},{"label":"Âlim adamdır, okumak için almıştır deyip mağdurun zararını kısmen tazmin ettirip davayı sulh ile neticelendir.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kütüphane Vakfından Kitap Çalan Müderris meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kütüphane Vakfından Kitap Çalan Müderris meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kütüphane Vakfından Kitap Çalan Müderris gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 517) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_518', 'ottoman', 'Demirci Kalfalarının Yangın Nöbeti', 'Ahi Şeyhliği', 'Demirciler kethüdası, her gece iki kalfanın körük başında yangın nöbeti tutmasını, uymayan dükkânın kapatılmasını teklif etti.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Teklifi kanunlaştır; yangın nöbetini tüm çarşı loncalarına mecburi kıl.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Çarşıda gece yangınları başlamadan söndürüldü; esnaf huzurla uyudu."},{"label":"Kalfaları uykusuz bırakmayın; yangın olursa tulumbacılar bakar.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Demirci Kalfalarının Yangın Nöbeti nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Demirci Kalfalarının Yangın Nöbeti fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Demirci Kalfalarının Yangın Nöbeti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 518) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_519', 'ottoman', 'İmaret Ekmeğinin Gramajının Küçültülmesi', 'Süleymaniye İmareti', 'Fırıncıların un fiyatı arttı diye medrese talebelerine ve fukaraya dağıtılan fodula ekmeğini yarı yarıya küçülttüğü tespit edildi.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Taviz verme! Fodula gramajını eski ölçüsüne getirt; eksik unun parasını fırıncıbaşına ödet.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Fukaranın ekmeği korundu; talebelerin karnı tam doydu."},{"label":"Bütçe dardır; talebeler az ekmekle yetinsin.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve İmaret Ekmeğinin Gramajının Küçültülmesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve İmaret Ekmeğinin Gramajının Küçültülmesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve İmaret Ekmeğinin Gramajının Küçültülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 519) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_520', 'ottoman', 'Vakıf Mallarının Hazineye Devredilmesi Fikri', 'Dîvân-ı Hümâyûn', 'Sıkışan maliyeciler, tüm bağımsız vakıf gelirlerinin doğrudan devlet hazinesine çekilmesini ve maaşların merkezden verilmesini önerdi.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"\'Vakıf malı şeriatın emanetidir, dokunulamaz!\' de; teklifi kesin bir dille reddet.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Sivil toplumun ve hayır müesseselerinin can damarı korundu; vakıf medeniyeti yaşadı."},{"label":"Teklifi onayla; tüm vakıf paralarını hazine sandığına aktar.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Vakıf Mallarının Hazineye Devredilmesi Fikri hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Vakıf Mallarının Hazineye Devredilmesi Fikri hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Vakıf Mallarının Hazineye Devredilmesi Fikri gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 520) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_521', 'ottoman', 'Beyşehir Gölü Kanalıyla Ovanın Sulanması', 'Konya Ovası', 'Mühendisler, Beyşehir Gölü\'nden taş kemerli kanallarla su indirilirse yüz binlerce dönüm kıraç toprağın buğday ambarına döneceğini hesapladı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Büyük kanal inşaatını başlat; asker istihkâmcılarını ve köylüyü imeceyle birleştir.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Beyşehir suları ovayı suladı; Konya\'da buğday rekoltesi üçe katlandı."},{"label":"Kanal çok masraflıdır; köylü yağmur duasını beklesin.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Beyşehir Gölü Kanalıyla Ovanın Sulanması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Beyşehir Gölü Kanalıyla Ovanın Sulanması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Beyşehir Gölü Kanalıyla Ovanın Sulanması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 521) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_522', 'ottoman', 'Zeytinliklerin İçine Taş Ocakları Açılması', 'Aydın Sancağı', 'Bir saray kethüdası, asırlık zeytin ağaçlarını dinamitle patlatıp taş ocağı açmak için yerel kadıdan zorla izin kopardı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Taş ocağı iznini derhal yırt; zeytine kıyan kethüdayı azlet ve fidan diktir.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Zeytinlikler korundu; tabiata ve köylünün rızkına yapılan tecavüz önlendi."},{"label":"Saray inşaatına taş lazımdır; zeytinlikleri feda edin.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Zeytinliklerin İçine Taş Ocakları Açılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Zeytinliklerin İçine Taş Ocakları Açılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Zeytinliklerin İçine Taş Ocakları Açılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 522) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_523', 'ottoman', 'Kaçak Odun Kömürcülerinin Orman Yangınları', 'Bolu Ormanları', 'Şehirlerde satmak için gece gizlice odun kömürü yakan kaçakçıların koca vadileri ateşe verdiği ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Orman muhafız alayını kur; kaçak kömür ocaklarını imha et ve ormanı koru.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Bolu ormanları kurtarıldı; devlet kereste havzaları korundu."},{"label":"Kömür şehirliye lazımdır; yangın rüzgârdandır deyip geçin.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak Odun Kömürcülerinin Orman Yangınları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kaçak Odun Kömürcülerinin Orman Yangınları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kaçak Odun Kömürcülerinin Orman Yangınları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 523) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_524', 'ottoman', 'Ayçiçeği Tohumu Ekimi ve Yağ Değirmenleri', 'Trakya Çiftlikleri', 'Balkanlardan getirilen ayçiçeği tohumunun kurak topraklarda çok iyi yağ verdiği, değirmenler kurulması istendi.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Köylüye bedava tohum dağıt ve su gücüyle çalışan yağ pres değirmenleri inşa ettir.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Bitkisel yağ üretimi patladı; zeytinyağı bulamayan fukara ucuz yağa kavuştu."},{"label":"Geleneksel susam ve ketenden şaşmayın; yeni tohuma para yok.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Ayçiçeği Tohumu Ekimi ve Yağ Değirmenleri nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Ayçiçeği Tohumu Ekimi ve Yağ Değirmenleri fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Ayçiçeği Tohumu Ekimi ve Yağ Değirmenleri meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 524) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_525', 'ottoman', 'Deliçay Nehrinin Taşarak Köyleri Boğması', 'Çukurova İskânı', 'Toroslardan inen azgın nehir her bahar köyleri basıp ekili pamukları çürütüyor; taştan bentler yapılması zaruri.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kamu hazinesinden taş bend inşaatını başlat; taşkın yatağını ıslah et.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Bentler taşkını durdurdu; Çukurova pamuğu güvenceye alındı."},{"label":"Köylüler evlerini dağ eteklerine taşısın; suyla uğraşılmaz.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Deliçay Nehrinin Taşarak Köyleri Boğması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Deliçay Nehrinin Taşarak Köyleri Boğması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Deliçay Nehrinin Taşarak Köyleri Boğması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 525) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_526', 'ottoman', 'Damızlık Boğa ve Aygır Ocaklarının Kapanması', 'Erzurum Yaylaları', 'Savaşlar yüzünden bölgedeki damızlık at ve sığır ocakları dağıldı; Anadolu sürülerinin ırkı bozuldu.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Devlet hara ve damızlık çiftliklerini derhal kur; Kırım ve Kafkasya\'dan safkan hayvanlar getirt.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Sürülerin nesli kurtarıldı; orduya güçlü atlar, halka sütlü sığırlar sağlandı."},{"label":"Mevcut cılız hayvanlar idare eder; haraya para ayrılmaz.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Damızlık Boğa ve Aygır Ocaklarının Kapanması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Damızlık Boğa ve Aygır Ocaklarının Kapanması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Damızlık Boğa ve Aygır Ocaklarının Kapanması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 526) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_527', 'ottoman', 'Dicle Kenarındaki Güvercin Gübresi (Borhâne) Yağması', 'Diyarbakır Karpuz Bostanları', 'Karpuz bostanlarını besleyen güvercin kulelerini eşkıyaların ateşe verip gübreleri gasbettiği bildirildi.', '[{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Borhâneleri muhafaza altına al, eşkıyayı yakalat ve bostancılara tazminat ver.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Dicle bostanları kurtarıldı; devasa Diyarbakır karpuzları yeniden yetişti."},{"label":"Güvercin gübresi için jandarma yorulmaz; bostancılar bekçi tutsun.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Dicle Kenarındaki Güvercin Gübresi (Borhâne) Yağması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Dicle Kenarındaki Güvercin Gübresi (Borhâne) Yağması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Dicle Kenarındaki Güvercin Gübresi (Borhâne) Yağması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 527) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_528', 'ottoman', 'Nehir Yatağının Değişmesi ve İzmir Limanının Dolması', 'Gediz Deltası', 'Gediz nehrinin getirdiği alüvyonlar İzmir körfezini dolduruyor; nehir yatağı taşınmazsa liman kapanacak.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Tarihin en büyük mühendislik hamlesini başlat: Gediz\'in ağzını Foça yönüne çevir.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"İzmir limanı dolmaktan kurtarıldı; dünya ticareti limana akmaya devam etti."},{"label":"Çok pahalı bir ameliyedir; körfez dolarsa gemiler açıkta beklesin.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Nehir Yatağının Değişmesi ve İzmir Limanının Dolması nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Nehir Yatağının Değişmesi ve İzmir Limanının Dolması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Nehir Yatağının Değişmesi ve İzmir Limanının Dolması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 528) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_529', 'ottoman', 'Buğday Ambarlarında Nem ve Kızışma', 'Sivas Kırsalı', 'Devletin ihtiyat buğdaylarının saklandığı yeraltı silolarına su sızdığı, tahılların yanıp çürüdüğü görüldü.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Havalandırmalı taş ambarlar inşa ettir; tahılları derhal kurutma sergilerine serdir.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Zahire kurtarıldı; kıtlık günleri için ambarlar emniyete alındı."},{"label":"Gözden ıraktır; üstünü toprakla örtüp kapatın.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Buğday Ambarlarında Nem ve Kızışma meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Buğday Ambarlarında Nem ve Kızışma hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Buğday Ambarlarında Nem ve Kızışma gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 529) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_530', 'ottoman', 'Zeytin Sineği İstilası', 'Mora Zeytinlikleri', 'Akdeniz\'den gelen zeytin sineği kurtçukları zeytinleri çürütüyor; köylü sirke ve kireç ilaçlaması için yardım istiyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hazineden kireç ve sirke tahsisatı ver; ziraat müfettişleriyle toplu ilaçlama yaptır.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Zeytin hasadı kurtarıldı; Mora zeytinyağı ambarları doldurdu."},{"label":"Böcekle uğraşılmaz; köylü kendi başının çaresine baksın.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Zeytin Sineği İstilası nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Zeytin Sineği İstilası fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Zeytin Sineği İstilası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 530) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_531', 'ottoman', 'Çerkes Mısır Tarlalarının Selde Kalması', 'Kafkasya Hududu', 'Kafkas dağlarındaki karlar aniden eridi; mısır eken muhacir köylerinin tarlaları balçıkla kaplandı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_tasra_muhaciri","name":"Taşra Muhaciri"}]', '[{"label":"Afetzedelere ambarlardan tohum hibe et ve o sene için vergilerini tamamen bağışla.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Muhacirler açlıktan kurtuldu; devlete olan şükranları perçinlendi."},{"label":"Vergiden muafiyet olmaz; tarlalarını temizleyip borçlarını ödesinler.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Çerkes Mısır Tarlalarının Selde Kalması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Çerkes Mısır Tarlalarının Selde Kalması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Çerkes Mısır Tarlalarının Selde Kalması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 531) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_532', 'ottoman', 'Kızılçam Ormanlarında Çıra Yağması', 'Kastamonu Ormanları', 'Köylülerin çıra elde etmek için çam ağaçlarının gövdelerini oyduğu ve fırtınada koca ormanın devrildiği bildirildi.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ağaç oyarak çıra sökmeyi kesinlikle yasakla; köylüye budama artıklarından çıra hakkı ver.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Ağaçlar kurumaktan kurtuldu; çıra nizamı intizama bağlandı."},{"label":"Köylünün aydınlatmasıdır; çıra çıkarmalarına divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kızılçam Ormanlarında Çıra Yağması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Kızılçam Ormanlarında Çıra Yağması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Kızılçam Ormanlarında Çıra Yağması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 532) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_533', 'ottoman', 'Harran Kuyularının Tuzlanması', 'Urfa Ovası', 'Aşırı ve yanlış sulama yüzünden Harran kuyularının suyu acıdı; ekinler sararıp boy vermez oldu.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Fırat\'tan tatlı su getirecek derin su kanalları açtır ve köylüye nöbetleşe sulama öğret.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Harran toprağı tuzdan kurtuldu; pamuk ve buğday fışkırdı."},{"label":"Kuyular tuzlandıysa yapacak bir şey yok; ekimi durdurun.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Harran Kuyularının Tuzlanması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Harran Kuyularının Tuzlanması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Harran Kuyularının Tuzlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 533) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_534', 'ottoman', 'Bağ Çubuklarında Kök Kurdu (Filoksera)', 'Edirne Bağları', 'Fransa\'dan gelen asma çubuklarıyla bulaşan kök kurdu Meriç boyundaki kadim bağları kurutuyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hastalıklı bağları derhal söktürüp yaktır; köylüye dayanıklı yerli asma çubukları dağıt.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Hastalık yayılmadan durduruldu; Edirne bağcılığı kurtuldu."},{"label":"Kendi haline bırakın; kuruyan kurusun.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Bağ Çubuklarında Kök Kurdu (Filoksera) nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Bağ Çubuklarında Kök Kurdu (Filoksera) fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Bağ Çubuklarında Kök Kurdu (Filoksera) meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 534) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_535', 'ottoman', 'Kestane Ağaçlarının Müteahhitlerce Kesilmesi', 'Bursa Dağ Köyleri', 'Odun müteahhitlerinin asırlık kestane korularını kömür yapmak için gizlice kestiği köylülerce basıldı.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Müteahhidin baltalarını toplat, kendisini zincire vur ve ormanı köylüye ortak koru yap.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Kestanelikler kurtarıldı; köylü kışlık rızkını güvenceye aldı."},{"label":"Müteahhit saraya odun temin ediyor; köylüleri dağıtın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kestane Ağaçlarının Müteahhitlerce Kesilmesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Kestane Ağaçlarının Müteahhitlerce Kesilmesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Kestane Ağaçlarının Müteahhitlerce Kesilmesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 535) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_536', 'ottoman', 'Erciyes Eteklerinde Sel ve Taş Sürüklenmesi', 'Kayseri Ovası', 'Erciyes\'ten inen taşkın seller ovanın üzerine koca kaya parçaları yığdı; tarlalar taş tarlasına döndü.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"İstihkâm neferlerini ve köylüyü seferber et; taşları toplatıp bağ duvarı yaptır, tarlayı temizle.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Taşlar bağ duvarı oldu; ovadaki bereketli topraklar yeniden açıldı."},{"label":"Taşları temizlemek imkânsızdır; köylüler başka yere gitsin.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Erciyes Eteklerinde Sel ve Taş Sürüklenmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Erciyes Eteklerinde Sel ve Taş Sürüklenmesi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Erciyes Eteklerinde Sel ve Taş Sürüklenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 536) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_537', 'ottoman', 'Zeytin Ağaçlarının Vergi Korkusuyla Sökülmesi', 'Halep Kırsalı', 'Ağaç başına konan aşırı maktu vergi yüzünden köylüler gece vakti kendi zeytin ağaçlarını baltalıyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ağaç başı vergiyi derhal kaldır! Mahsul üzerinden adil öşür nispetine dön.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Baltalar durdu; köylü yeni zeytin fidanları dikmeye başladı."},{"label":"Ağaç kesenleri idamla tehdit et ama vergiyi indirme.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Zeytin Ağaçlarının Vergi Korkusuyla Sökülmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Zeytin Ağaçlarının Vergi Korkusuyla Sökülmesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Zeytin Ağaçlarının Vergi Korkusuyla Sökülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 537) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_538', 'ottoman', 'Fındık Bahçelerinde Heyelan Tehlikesi', 'Trabzon Kırsalı', 'Aşırı yağmurlar dik yamaçlardaki fındıklıkları aşağı kaydırıyor; teraslama duvarları örülmesi şart.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Taş ustaları görevlendir; yamaçlara basamaklı taştan teraslar ördür ve drenaj hendekleri aç.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Toprak kayması önlendi; dik yamaçlar asırlık fındık bahçesi oldu."},{"label":"Masraflıdır; fındık kendi köküyle tutunsun.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fındık Bahçelerinde Heyelan Tehlikesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Fındık Bahçelerinde Heyelan Tehlikesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Fındık Bahçelerinde Heyelan Tehlikesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 538) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_539', 'ottoman', 'Pirinç Çeltiklerinin Nehir Balıkçılığını Öldürmesi', 'Tuna Boyu', 'Çeltik bentlerinin Tuna\'nın yan kollarını tıkaması yüzünden mersin balıkları yumurtlamaya çıkamaz oldu.', '[{"id":"char_denizci_balikci","name":"Denizci / Balıkçı Esnafı"}]', '[{"label":"Bentlere balık geçitleri açtır; çeltik mültezimlerine balık yatağını bozmamak şartı koy.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Hem pirinç üretildi hem de nehir mersin balığıyla dolup taştı."},{"label":"Pirinç balıktan mühimdir; balıkçıların şikâyetine bakmayın.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Pirinç Çeltiklerinin Nehir Balıkçılığını Öldürmesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Pirinç Çeltiklerinin Nehir Balıkçılığını Öldürmesi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Pirinç Çeltiklerinin Nehir Balıkçılığını Öldürmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 539) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_540', 'ottoman', 'Toprak Kanunnâmesi: Çift-Hâne Sisteminin İhyası', 'Dîvân-ı Hümâyûn', 'Arazilerin zengin ayânlar elinde toplanmasını engelleyen, bir çift öküzle işlenen arazinin bölünemezliğini emreden kadim kanunun tazelenmesi istendi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Kanunnâme-i Âl-i Osman\'ı mühürle: Köylünün çiftliği satılamaz, haczedilemez ve bölünemez.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Küçük köylü mülkiyeti teminat altına alındı; feodalleşmenin önü ebediyen kesildi."},{"label":"Büyük çiftlik sahiplerinin serbestçe arazi toplamasına izin ver.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Toprak Kanunnâmesi: Çift-Hâne Sisteminin İhyası nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Toprak Kanunnâmesi: Çift-Hâne Sisteminin İhyası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Toprak Kanunnâmesi: Çift-Hâne Sisteminin İhyası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 540) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_541', 'ottoman', 'Zeytinyağı Tulumlarında Donyağı Karışımı', 'Yağ Kapanı Kâhyası', 'Yağ Kapanı\'na gelen tulumların dibine ucuz sığır içyağı basıldığı, üstüne zeytinyağı dökülerek kandil yağı diye satıldığı görüldü.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütün tulumları şişle deldirip kontrol ettir; hile yapan tüccarların mallarını müsadere et.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Hileli yağ piyasadan temizlendi; dürüst tüccar hakkını aldı."},{"label":"Kandil yağıdır, yenmiyor ya deyip ceza kesmeden geç.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Zeytinyağı Tulumlarında Donyağı Karışımı hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Zeytinyağı Tulumlarında Donyağı Karışımı hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Zeytinyağı Tulumlarında Donyağı Karışımı gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 541) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_542', 'ottoman', 'Petek Ballarına Şeker Şerbeti Katılması', 'Balkapanı Kâtipliği', 'Eflak ve Boğdan\'dan gelen ballara şeker kaynatılıp petek doldurulduğu, arı görmemiş sahte bal satıldığı ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Muhtesip hekimleriyle şerbetli balları tahlil ettir; sahte malları imha edip failleri sürgün et.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Balın şifası korundu; halk hekimleri hastalara güvenle bal yazdı."},{"label":"Şeker de tatlıdır; halk yesin deyip tüccara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Petek Ballarına Şeker Şerbeti Katılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Petek Ballarına Şeker Şerbeti Katılması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Petek Ballarına Şeker Şerbeti Katılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 542) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_543', 'ottoman', 'Buğday Çuvallarına Kum Katılması', 'Un Kapanı Nazırlığı', 'Kırım\'dan gemiyle gelen buğdayların tartıda ağır çekmesi için deniz kumuyla karıştırıldığı değirmende anlaşıldı.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kaptanı ve tüccarı derhal tevkif et, un eleklerini sıkılaştır; zararı tüccara ödettir.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Değirmen taşları kırılmaktan kurtuldu; halk dişini kırmayan temiz ekmek yedi."},{"label":"Un kıttır; kumlu buğdayı da öğütüp fırınlara yollayın.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Buğday Çuvallarına Kum Katılması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Buğday Çuvallarına Kum Katılması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Buğday Çuvallarına Kum Katılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 543) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_544', 'ottoman', 'Koyun Etine Keçi Eti Karıştırılması', 'İstanbul Kasapları', 'Kasapların kuzu eti fiyatına yaşlı keçi eti sattığı ve etin kokmaması için sirkeye yatırdığı ortaya çıktı.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Muhtesip kollarını çarşıya sal; keçi eti satan dükkânın kapısına keçi boynuzu astırıp teşhir et.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Kasapların hilesi durduruldu; etin cinsi ve narhı sabitlendi."},{"label":"İkisi de dört ayaklıdır; kasapları çok sıkıştırmayın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Koyun Etine Keçi Eti Karıştırılması hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Koyun Etine Keçi Eti Karıştırılması hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Koyun Etine Keçi Eti Karıştırılması gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 544) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_545', 'ottoman', 'Göl Tuzunun Kaya Tuzu Diye Satılması', 'Tuz Kapanı', 'Tuz tüccarları rutubetli göl tuzunu güneşte kurutup \'Saf Çankırı Kaya Tuzu\' diye yüksek narhtan sattı.', '[{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Tuzları tahlil ettir, narh farkını tüccardan ceza olarak alıp halka ucuz tuz dağıt.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Tuzda sahtecilik durduruldu; kışlık peynir ve kavurmalar bozulmadı."},{"label":"Tuz tuzdur; aradaki farkı anlamazlar deyip divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Göl Tuzunun Kaya Tuzu Diye Satılması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Göl Tuzunun Kaya Tuzu Diye Satılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Göl Tuzunun Kaya Tuzu Diye Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 545) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_546', 'ottoman', 'Yabancı Dukaların İçine Kurşun Dökülmesi', 'Darbhane-i Âmire', 'Sarrafların Venedik altınlarının içini oyup kurşun doldurarak ağırlığını koruduğu ve piyasaya sürdüğü tespit edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Darbhane müfettişlerini çarşıya sal; hileli altınları presle ikiye böldürüp el koy.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"İçi kurşunlu sahte altın şebekesi çökertildi; para piyasası kurtuldu."},{"label":"Yabancı paradır; bizim paramız değil deyip sarrafları kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Yabancı Dukaların İçine Kurşun Dökülmesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Yabancı Dukaların İçine Kurşun Dökülmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Yabancı Dukaların İçine Kurşun Dökülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 546) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_547', 'ottoman', 'Kokusunu Gidermek İçin Boyanan Balıklar', 'Balıkpazarı İskelesi', 'Bayat palamutların solungaçlarına kırmızı kına sürülerek taze süsü verildiği ve halkın zehirlendiği bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Bayat balıkları denize döktür, kına süren balıkçıların tezgâhlarını mühürle.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Halk sağlığı korundu; balık pazarında dürüst satış başladı."},{"label":"Fukara ucuza balık alıyor; çok teftiş yapmayın.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kokusunu Gidermek İçin Boyanan Balıklar meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kokusunu Gidermek İçin Boyanan Balıklar meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kokusunu Gidermek İçin Boyanan Balıklar gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 547) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_548', 'ottoman', 'Meyve Küfelerinde Üste İyileri, Alta Çürükleri Koyma', 'Payitaht Manavları', 'Bostancıların elma ve armut küfelerinin dibine çürükleri doldurup üstünü yaprak ve iri meyveyle örttüğü şikâyet edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"İhtisap nizamnamesini uygula: Her küfeyi ters çevirtip baktır, hile yapanın malını fukaraya dağıt.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Pazar hilesi kökünden kesildi; ahali küfeyi görmeden de güvenle aldı."},{"label":"Pazarcı adetidir; gözü olan baksın alsın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Meyve Küfelerinde Üste İyileri, Alta Çürükleri Koyma nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Meyve Küfelerinde Üste İyileri, Alta Çürükleri Koyma fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Meyve Küfelerinde Üste İyileri, Alta Çürükleri Koyma meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 548) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_549', 'ottoman', 'Tavukların Kursaklarına Kurşun Saçma Doldurulması', 'Tavukpazarı Kâhyalığı', 'Canlı tavuk satıcılarının tartıda ağır gelsin diye tavuklara zorla kurşun saçma ve çakıl yutturduğu ortaya çıktı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bu acımasız hileyi yapan zalimleri teşhir et ve meslekten ebediyen men et.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Hem hayvana eziyet hem tartı hırsızlığı durduruldu; vicdanlar teskin oldu."},{"label":"Tavukçuların kârı azdır; üç beş dirhemden bir şey olmaz.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Tavukların Kursaklarına Kurşun Saçma Doldurulması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Tavukların Kursaklarına Kurşun Saçma Doldurulması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Tavukların Kursaklarına Kurşun Saçma Doldurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 549) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_550', 'ottoman', 'Odunun Islak Yakılması ve Ağır Ekmek Hilesi', 'İstanbul Fırınları', 'Fırıncıların hamuru çiğ bırakıp ekmeğin içini ıslak ve ağır tutarak gramajı tutturduğu anlaşıldı.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Ekmeklerin içini kestirip baktır; içi pişmemiş çiğ ekmek çıkaran fırına ağır ceza kes.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Halk iyi pişmiş gevrek ekmek yedi; fırıncıların hilesi söndü."},{"label":"Odun pahalıdır; fırıncılar fazla yakmasın.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Odunun Islak Yakılması ve Ağır Ekmek Hilesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Odunun Islak Yakılması ve Ağır Ekmek Hilesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Odunun Islak Yakılması ve Ağır Ekmek Hilesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 550) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_551', 'ottoman', 'Kirece Kum Yerine Kül Karıştırılması', 'Sıva ve Kireç Loncası', 'Kâgir binaların harcına kireç yerine ocak külü karıştırıldığı, ilk depremde duvarların un gibi dağıldığı belgelendi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kireç fırınlarını mühürle; kalitesiz harç kullanan kalfaların inşaat ruhsatını yırt.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Binaların harcı sağlamlaştı; şehir can güvenliğine kavuştu."},{"label":"Kireç yetersizdir; kül karışımı harcı idare edin.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Kirece Kum Yerine Kül Karıştırılması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Kirece Kum Yerine Kül Karıştırılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kirece Kum Yerine Kül Karıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 551) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_552', 'ottoman', 'Yaldızlı Bakırın Altın Diye Satılması', 'Kuyumcular Çarşısı', 'Gümüş kupaların ve ziynetlerin üzerine ince altın cıva yaldızı çekilip \'som altın\' diye satıldığı tespit edildi.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Kuyumcular kethüdasına mihenk taşıyla umumi teftiş yaptır; sahte altınları darphanede erittir.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Mihenk taşı hakkı batıldan ayırdı; Kapalıçarşı\'ya itibar döndü."},{"label":"Kuyumcular zengindir; üzerlerine gidip çarşıyı ürkütme.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Yaldızlı Bakırın Altın Diye Satılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Yaldızlı Bakırın Altın Diye Satılması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yaldızlı Bakırın Altın Diye Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 552) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_553', 'ottoman', 'Kuru Odun Fiyatına Islak Meşe Satılması', 'Odun Kapanı', 'Kapan simsarlarının yağmur altında ıslattıkları meşe odunlarını tartıyla satarak halkı soyduğu görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Odun tartısını kuruluk nispetine bağla; ıslak odun satan simsarın kantarını kır.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Halk sobasında tütmeyen kuru odun yaktı; kış çilesi hafifledi."},{"label":"Kış günü odun odundur; ıslak da olsa yansın.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kuru Odun Fiyatına Islak Meşe Satılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kuru Odun Fiyatına Islak Meşe Satılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kuru Odun Fiyatına Islak Meşe Satılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 553) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_554', 'ottoman', 'Balmumu Yerine Donyağı Mumu İtirazı', 'Mumcular Loncası', 'Camilerin aydınlatılmasında kullanılan murlara leş donyağı karıştırıldığı, namaz kılarken cemaatin genzinin tıkandığı bildirildi.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Vakıf camilerine sadece saf kokusuz balmumu verilmesini emret; tağşiş yapan mumcuyu cezalandır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Mabetlerin manevi havası korundu; camiler mis gibi koktu."},{"label":"Balmumu pahalıdır; donyağı mumuyla idare etsinler.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Balmumu Yerine Donyağı Mumu İtirazı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Balmumu Yerine Donyağı Mumu İtirazı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Balmumu Yerine Donyağı Mumu İtirazı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 554) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_555', 'ottoman', 'İpek İpliklerine Ağırlaştırma Kimyasalı Sürülmesi', 'İpek İmalathanesi', 'İplik bükücülerinin ipeği kurşunlu suya batırıp kurutarak ağırlığını iki katına çıkardığı ortaya çıktı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Kimyasal banyoları imha ettir; tartıda hile yapan fabrikaları süresiz kapat.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"İpeğin doğallığı korundu; Avrupa tüccarları Bursa ipeğine hücum etti."},{"label":"İpek ihracatı çoktur; ufak hileleri tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağlain.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve İpek İpliklerine Ağırlaştırma Kimyasalı Sürülmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve İpek İpliklerine Ağırlaştırma Kimyasalı Sürülmesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve İpek İpliklerine Ağırlaştırma Kimyasalı Sürülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 555) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_556', 'ottoman', 'Sebzelerin Lağım Suyuyla Sulanması', 'Payitaht Bostanları', 'Yedikule bostancılarının sebzeleri çabuk büyüsün diye arıtılmamış kara lağım suyuyla suladığı tespit edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Lağım kanallarını kapattır; temiz kuyu suyuyla sulamayan bostancının arazisini elinden al.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Kolera ve tifo salgını önlendi; payitaht tertemiz yeşillik yedi."},{"label":"Sebzeler çok iri çıkıyor; lağım suyuna müdahale etmeyin.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sebzelerin Lağım Suyuyla Sulanması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Sebzelerin Lağım Suyuyla Sulanması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Sebzelerin Lağım Suyuyla Sulanması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 556) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_557', 'ottoman', 'Darphane İşçilerinin Üzerinde Gümüş Tozu Kaçırması', 'Darbhane-i Âmire', 'İşçilerin saçlarına ve tırnak diplerine gümüş tozu sürerek her gün kilolarca gümüşü dışarı kaçırdığı ihbar edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Darphane çıkışına yıkanma ve sıkı üst arama nizamı koy; kaçakçı şebekesini çökert.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Devlet hazinesinin gümüş sızıntısı tıkandı; darphane emniyete kavuştu."},{"label":"İşçilerin bahşişidir; çok üzerlerine gidip işi yavaşlatmayın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Darphane İşçilerinin Üzerinde Gümüş Tozu Kaçırması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Darphane İşçilerinin Üzerinde Gümüş Tozu Kaçırması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Darphane İşçilerinin Üzerinde Gümüş Tozu Kaçırması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 557) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_558', 'ottoman', 'Kahveye Kavrulmuş Nohut ve Arpa Karıştırılması', 'İstanbul Kahvehaneleri', 'Yemen kahvesi pahalandı diye kahveci esnafının içine yarı yarıya yanık arpa tozu kattığı kadı huzurunda belgelendi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Kahve çekirdeklerini bütün olarak çektirme mecburiyeti koy; karışım yapan kahvehaneyi kapat.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Hakiki kahve lezzeti korundu; halk aldatılmaktan kurtuldu."},{"label":"Nohut da lezzetlidir; halk fark etmezse divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Kahveye Kavrulmuş Nohut ve Arpa Karıştırılması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Kahveye Kavrulmuş Nohut ve Arpa Karıştırılması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Kahveye Kavrulmuş Nohut ve Arpa Karıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 558) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_559', 'ottoman', 'Kalyon Boyalarında Zehirli Kurşun Aşırılığı', 'Tersane Ambarı', 'Gemi boyalarına sürülen kurşun bileşiklerinin boyacı leventleri zehirleyip felç ettiği bildirildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Zehirli kurşun boyasını yasakla; çam reçinesi ve kireç karışımı tabii boyaya dön.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Leventlerin canı kurtarıldı; tersanede zehirlenmeler bitti."},{"label":"Kurşun boya gemiyi sudan daha iyi korur; leventler dikkat etsin.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kalyon Boyalarında Zehirli Kurşun Aşırılığı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kalyon Boyalarında Zehirli Kurşun Aşırılığı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kalyon Boyalarında Zehirli Kurşun Aşırılığı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 559) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_560', 'ottoman', 'Büyük Narh Defterinin Yenilenmesi', 'Dîvân-ı Hümâyûn', 'Ekonomik dengelerin değişmesi üzerine tüm emtianın üreticiyi ezmeyen, tüketiciyi koruyan adil yeni narh defterinin yazılması teklif edildi.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Âlimler, esnaf ve halk temsilcilerini topla; adalete uygun şeffaf narhı ilan et.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Piyasa sükûnete erdi; karaborsacılar süpürüldü, alıcı da satıcı da güldü."},{"label":"Eski narh defteriyle devam edin; fiyatlarla oynamak tehlikelidir.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Büyük Narh Defterinin Yenilenmesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Büyük Narh Defterinin Yenilenmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Büyük Narh Defterinin Yenilenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 560) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_561', 'ottoman', 'Kale Dizdarının Barut Fıçılarını Nemden Çıkarmaması', 'Uyvar Kalesi', 'Dizdarın ihmali yüzünden Uyvar mahzenlerindeki yüzlerce fıçı barut ıslandı; düşman ordusu yaklaşıyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Dizdarı azlet; fırınlarda acil barut kurutma düzeni kurdur ve Budin\'den mühimmat yetiştir.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Barut kurutuldu ve takviye yetişti; kale düşman taarruzuna direndi."},{"label":"Dizdar hatır sahibidir; barut kurur deyip takviye yollama.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Kale Dizdarının Barut Fıçılarını Nemden Çıkarmaması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Kale Dizdarının Barut Fıçılarını Nemden Çıkarmaması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kale Dizdarının Barut Fıçılarını Nemden Çıkarmaması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 561) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_562', 'ottoman', 'Zırh ve Miğferlerin Demir Kalitesi', 'Cebeci Kışlası', 'Cebecibaşının zırhları döverken hurda teneke karıştırdığı, okların zırhları delip geçtiği talimde görüldü.', '[{"id":"char_cebecibasi","name":"Cebecibaşı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Cebecibaşını divanda yargılat; Samakov çeliğiyle sağlam örme zırhlar dök.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Askerin zırhı çelikten örüldü; muharebede oklar sekip gitti."},{"label":"Teneke karışımı hafiftir; asker daha hızlı koşar de.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zırh ve Miğferlerin Demir Kalitesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Zırh ve Miğferlerin Demir Kalitesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Zırh ve Miğferlerin Demir Kalitesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 562) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_563', 'ottoman', 'Kalyonların Su Çekim Derinliği (Draft) Hatası', 'Tersane-i Âmire', 'Mimar kalfasının hesapsızlığı yüzünden yeni kalyonların Boğaz sığlıklarına oturduğu ve yüzemediği anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Mimarbaşını görevlendir; omurgaları yeniden hesaplatıp kalyonları derin havuzda düzelttir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Kalyonlar dengeli yüzdü; deniz manevrası mükemmelleşti."},{"label":"Gemileri kıyıda bağlı tutun; masrafa gerek yok.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kalyonların Su Çekim Derinliği (Draft) Hatası nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kalyonların Su Çekim Derinliği (Draft) Hatası fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kalyonların Su Çekim Derinliği (Draft) Hatası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 563) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_564', 'ottoman', 'Dicle Nehrinden Kaleye Su Taşıyan Develer', 'Bağdat Kalesi', 'Kuşatma sırasında kalenin su kuyusu zehirlendi; su taşıyan develerin nehirden su çekebilmesi için tünel kazılması istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"İstihkâmcılara gizli su tüneli kazdır; kaleyi susuzluktan teslim olmaktan kurtar.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Gizli su yolu açıldı; garnizon aylarca düşmana boyun eğmedi."},{"label":"Tünel çok masraflıdır; depodaki yağmur suyuyla idare etsinler.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Dicle Nehrinden Kaleye Su Taşıyan Develer nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Dicle Nehrinden Kaleye Su Taşıyan Develer fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Dicle Nehrinden Kaleye Su Taşıyan Develer meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 564) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_565', 'ottoman', 'Kaledeki Eski Top Güllelerinin Paslanması', 'Rodos Garnizonu', 'Şövalyelerden kalan demir güllelerin paslanıp namlulara sığmadığı, ateşlenince namluyu patlattığı bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Bütün eski gülleleri toplatıp Tophane\'de erittir; kalibreye uygun yeni gülleler dök.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Topçuların emniyeti sağlandı; atışlar hedefi tam isabet vurdu."},{"label":"Gülleleri zımparalayıp namluya zorla sokun.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Kaledeki Eski Top Güllelerinin Paslanması hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Kaledeki Eski Top Güllelerinin Paslanması hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Kaledeki Eski Top Güllelerinin Paslanması gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 565) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_566', 'ottoman', 'Şayka Kürekçilerine Yün Başlık ve Çorap Dağıtımı', 'Tuna Donanması', 'Tuna\'nın dondurucu ayazında kürek çeken leventlerin parmaklarının donduğu, kışlık giysi gerektiği bildirildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Edirne ve Selanik\'ten acil yün çorap, başlık ve koyun postu yelekler sevk et.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Leventler donmaktan kurtuldu; nehirde Kazak botları püskürtüldü."},{"label":"Asker dayanıklı olmalıdır; masrafa gerek yok.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Şayka Kürekçilerine Yün Başlık ve Çorap Dağıtımı nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Şayka Kürekçilerine Yün Başlık ve Çorap Dağıtımı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Şayka Kürekçilerine Yün Başlık ve Çorap Dağıtımı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 566) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_567', 'ottoman', 'Sipahilerin Samanlık Yangını', 'Kars Hududu', 'Düşman süvarilerinin sınır boyundaki sipahi kışlasının saman ambarını yaktığı, 5 bin süvari atının aç kaldığı öğrenildi.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Erzurum ve Sivas ambarlarından acil arpa ve kuru ot konvoyu çıkar; atları aç bırakma.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Sipahi atları kurtarıldı; hudutta süvari devriyeleri aksamadı."},{"label":"Köylülerin samanlarına bedelsiz el koyun.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Sipahilerin Samanlık Yangını nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Sipahilerin Samanlık Yangını fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Sipahilerin Samanlık Yangını meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 567) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_568', 'ottoman', 'Venedik Kalyonundan Ele Geçirilen Çarklı Tüfekler', 'Girit Serdarlığı', 'Leventler çakmaklı ve seri ateş eden Venedik tüfekleri ele geçirdi; Cebecibaşı bunların kopyalanmasını teklif etti.', '[{"id":"char_cebecibasi","name":"Cebecibaşı"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Tüfekleri Tophane ve Cebeci ustalarına incelet; çakmaklı mekanizmayı orduda yaygınlaştır.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Fitilli tüfek devri kapandı; ordumuz çakmaklı seri ateşe geçti."},{"label":"Fitilli tüfeğimiz kafidir; yabancı icatla kafaları karıştırmayın.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Venedik Kalyonundan Ele Geçirilen Çarklı Tüfekler hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Venedik Kalyonundan Ele Geçirilen Çarklı Tüfekler hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Venedik Kalyonundan Ele Geçirilen Çarklı Tüfekler gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 568) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_569', 'ottoman', 'Kalyon Zindanında Forsaların Tünel Kazması', 'Tersane-i Âmire', 'Tersane zindanındaki Venedikli ve İspanyol esirlerin Haliç\'e doğru gizli kaçış tüneli kazdığı fark edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Tüneli taş ve kireçle doldur, nöbetçi disiplinini artır ve kaçış elebaşlarını küreğe bağla.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Büyük firar önlendi; tersanenin güvenliği sağlandı."},{"label":"Bütün zindan esirlerini idam edin.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Kalyon Zindanında Forsaların Tünel Kazması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Kalyon Zindanında Forsaların Tünel Kazması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyon Zindanında Forsaların Tünel Kazması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 569) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_570', 'ottoman', 'Surlara Tırmanmayı Engelleyen Dikenli Çitler', 'Belgrad Kalesi', 'Düşman piyadesinin hendekleri aşıp surlara merdiven dayamasını önlemek için hendek dibine dövme demir dikenler konması önerildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Samakov demircilerine emir ver; hendekleri demir kirpi ve dikenlerle tahkim et.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Düşman hücumu hendeklerde kırıldı; Belgrad surları aşılamadı."},{"label":"Hendek derindir, dikene masraf etmeyin.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Surlara Tırmanmayı Engelleyen Dikenli Çitler nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Surlara Tırmanmayı Engelleyen Dikenli Çitler fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Surlara Tırmanmayı Engelleyen Dikenli Çitler meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 570) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_571', 'ottoman', 'Kale İçinde At Eti Yenmesi Dedikodusu', 'Kamaniçe Garnizonu', 'Kuşatma uzayınca askerlerin telef olan atların etini yediği, bazı neferlerin \'Haramdır\' diye isyana kalkıştığı öğrenildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Müftüden zaruret fetvası aldır, erzak ambarlarını paylaştır ve askere cihat metaneti aşıla.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Fitne söndürüldü; garnizon açlığa rağmen kaleyi teslim etmedi."},{"label":"İsyancı neferleri surdan aşağı atın.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kale İçinde At Eti Yenmesi Dedikodusu sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Kale İçinde At Eti Yenmesi Dedikodusu meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Kale İçinde At Eti Yenmesi Dedikodusu gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 571) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_572', 'ottoman', 'Kükürt Ocaklarında Zehirlenen İşçiler', 'Payitaht Baruthanesi', 'Barut imalatında kullanılan kükürdü kaynatan işçilerin gazdan zehirlenip öldüğü, ocakların durduğu bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hava bacalı taş fırınlar kurdur; işçilere sirkeye batırılmış bez maske ve dolgun ücret tahsis et.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"İşçi sağlığı korundu; kükürt ve barut üretimi tam kapasite sürdü."},{"label":"Zehir bu işin tabiatıdır; ölenin yerine esir koyun.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kükürt Ocaklarında Zehirlenen İşçiler nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kükürt Ocaklarında Zehirlenen İşçiler fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kükürt Ocaklarında Zehirlenen İşçiler meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 572) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_573', 'ottoman', 'Kalyonlara Bakır Çivi Yerine Demir Çivi Çakılması', 'Sinop Tersanesi', 'Tersane kethüdasının deniz suyunda paslanan demir çiviler kullandığı, omurgaların iki yılda açıldığı kanıtlandı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Kethüdayı azlet, tüm çivileri söküp Küre bakırından dökülen paslanmaz çivilerle kalyonları tahkim et.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Kalyonlar deniz suyunda çürümez oldu; donanmanın ömrü uzadı."},{"label":"Demir çivi daha ucuzdur; kalyonları ziftleyip idare edin.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Kalyonlara Bakır Çivi Yerine Demir Çivi Çakılması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Kalyonlara Bakır Çivi Yerine Demir Çivi Çakılması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyonlara Bakır Çivi Yerine Demir Çivi Çakılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 573) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_574', 'ottoman', 'Göl Kıyısına Topçu Tabyaları Kurulması', 'Van Kalesi', 'Safevi teknelerinin Van Gölü üzerinden asker sızdırmasını önlemek için göl kıyısına hareketli bataryalar teklif edildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Tabyaları kurdur; gölü çapraz top ateşiyle denetim altına al.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Van Gölü kaçakçılara ve düşman baskınlarına tamamen kapatıldı."},{"label":"Gölden asker gelmez; masrafa gerek yok.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Göl Kıyısına Topçu Tabyaları Kurulması hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Göl Kıyısına Topçu Tabyaları Kurulması hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Göl Kıyısına Topçu Tabyaları Kurulması gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 574) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_575', 'ottoman', 'Korsan Kadırgasında Veba Salgını', 'Akdeniz Açıkları', 'Denizde esir alınan bir Malta korsan teknesinde veba mikrobu tespit edildi; leventler ganimeti yağmalamak istiyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Ganimeti yasakla; gemiyi içindekilerle birlikte top ateşiyle derhal batır.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Veba donanmaya bulaşmadan denize gömüldü; binlerce levent kurtuldu."},{"label":"Altınlar değerlidir; sandıkları yıkayıp filoya alın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Korsan Kadırgasında Veba Salgını nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Korsan Kadırgasında Veba Salgını fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Korsan Kadırgasında Veba Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 575) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_576', 'ottoman', 'Kışla Odalarına Sivil Esnafın Ortak Edilmesi', 'Yeniçeri Kışlaları', 'Yeniçeri zabitlerinin kışla odalarını sivil kasap ve manavlara kiralayarak haksız gelir elde ettiği tespit edildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Kışlaları sivil tüccardan tamamen temizle; ocağı sadece talim ve ibadet kışlası yap.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Askeri terbiye ve ciddiyet geri geldi; ocak kışlası intizama erdi."},{"label":"Zabitlerin ek geliridir; esnafla askerin kaynaşmasına divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Kışla Odalarına Sivil Esnafın Ortak Edilmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Kışla Odalarına Sivil Esnafın Ortak Edilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kışla Odalarına Sivil Esnafın Ortak Edilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 576) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_577', 'ottoman', 'Kuşatma Tünellerinde Düşman Zehirli Gazı', 'Hotin Kalesi', 'Düşman lağımcıları tünellerimize kükürt ve acı biber dumanı basarak lağımcılarımızı boğmaya çalışıyor.', '[{"id":"char_humbaracibasi","name":"Humbaracıbaşı"}]', '[{"label":"Lağım ağızlarına su tulumbası ve ıslak keçe perdeler kurdur; dumanı geriye püskürt.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Lağımcılar tüneli kurtardı; düşman tabyası alttan havaya uçuruldu."},{"label":"Tünelleri kapatıp geri çekilin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kuşatma Tünellerinde Düşman Zehirli Gazı meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Kuşatma Tünellerinde Düşman Zehirli Gazı hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Kuşatma Tünellerinde Düşman Zehirli Gazı gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 577) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_578', 'ottoman', 'Kalyoncuların Denizde Balık Tutma Yasağı', 'Tersane-i Âmire', 'Kaptan Paşa\'nın talim bahanesiyle leventlerin denizde ağ atıp balık tutmasını yasakladığı, askerin isyan ettiği bildirildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Yasağı kaldır: İstirahat saatinde leventlerin balık tutmasına ve taze gıda almasına izin ver.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Leventler taze balık yiyip moral buldu; isyan havası dağıldı."},{"label":"Kaptan Paşa\'nın emri mutlaktır; balık tutanı küreğe bağlat.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kalyoncuların Denizde Balık Tutma Yasağı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kalyoncuların Denizde Balık Tutma Yasağı fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kalyoncuların Denizde Balık Tutma Yasağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 578) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_579', 'ottoman', 'Top Kundaklarının Çürük Ağaçtan Yapılması', 'Erzurum Kalesi', 'Kavak ağacından yapılan top kundaklarının ilk atışta çatlayıp topları ters devirdiği bildirildi.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Kundakları kara gürgen ve dişbudak ağacından yaptır; demir çemberlerle sıktır.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Toplar sarsılmadan yüzlerce el ateş etti; kale tabyaları geçilmez oldu."},{"label":"Kavak ağacı hafiftir; kırılanı tamir edip idare edin.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Top Kundaklarının Çürük Ağaçtan Yapılması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Top Kundaklarının Çürük Ağaçtan Yapılması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Top Kundaklarının Çürük Ağaçtan Yapılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 579) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_580', 'ottoman', 'Gazi ve Şehit Çocuklarının Yeniçeri Ocağına Alınması', 'Dîvân-ı Hümâyûn', 'Savaşta şehit düşen gazilerin yetim çocuklarının Acemi Ocağı\'na sınavsız kabul edilip yetiştirilmesi teklif edildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Ferman çıkar: Şehit yetimleri devlete emanettir! Hepsini maaşla ocağa al ve ilimle terbiye et.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Yetimlerin duası ordunun bereketi oldu; ocağa cansiperane sadakat geldi."},{"label":"Devşirme kanununa aykırıdır; şehit çocuklarını kışlaya sokmayın.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Gazi ve Şehit Çocuklarının Yeniçeri Ocağına Alınması meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Gazi ve Şehit Çocuklarının Yeniçeri Ocağına Alınması hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Gazi ve Şehit Çocuklarının Yeniçeri Ocağına Alınması gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 580) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_581', 'ottoman', 'İstihbarat Ağının (Berîd) İhmali', 'Nizamülmülk\'ün Hatırası', 'Siyasetnâme\'de \'Hükümdarın gözü ve kulağı berîddir\' denmesine rağmen vezirlerin masraf diye taşra casusluk teşkilatını lağvettiği öğrenildi.', '[{"id":"char_nizamulmulk","name":"Nizamülmülk"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Berîd (istihbarat) teşkilatını derhal yeniden kurdur; her kazaya güvenilir gizli muhbirler ata.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Zalim valilerin gizli zulümleri günü gününe saraya aktı; nizam korundu."},{"label":"Casusluk fitne çıkarır; valilerin resmi raporlarıyla yetinin.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve İstihbarat Ağının (Berîd) İhmali nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve İstihbarat Ağının (Berîd) İhmali fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve İstihbarat Ağının (Berîd) İhmali meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 581) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_582', 'ottoman', 'Yirmisekiz Çelebi Mehmed\'in Rasathane Layihası', 'Paris Sefaretnâmesi', 'Paris\'ten dönen sefir, Fransa Kralı\'nın rasathane ve matbaalarla dünyayı fethettiğini anlatan muazzam bir sefaretnâme sundu.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Sefaretnâmeyi divanda okut; mühendislik mektepleri kurup batının fennini süratle al.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Dünyadaki ilmi gelişmeler devlete aktarıldı; donanma ve ordu modernize oldu."},{"label":"Gâvurların yaldızlı binalarına aldanmayın deyip sefaretnâmeyi rafa kaldır.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Yirmisekiz Çelebi Mehmed\'in Rasathane Layihası nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Yirmisekiz Çelebi Mehmed\'in Rasathane Layihası fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Yirmisekiz Çelebi Mehmed\'in Rasathane Layihası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 582) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_583', 'ottoman', 'Padişahın Divana Bizzat Başkanlık Etmesi', 'Şeyhülislamlık', 'Vezirlerin kapalı kapılar ardında karar almasını önlemek için padişahın \'Kafes\' arkasından çıkıp divana bizzat oturması teklif edildi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Tahta bizzat otur! Vezirleri huzurunda dinle ve tebaanın sesine doğrudan muhatap ol.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Vezirlerin oligarşik hegemonyası kırıldı; hükümdar devletin başına geçti."},{"label":"Padişahın perde arkasında kalması saltanat vakarındandır; divana inme.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Padişahın Divana Bizzat Başkanlık Etmesi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Padişahın Divana Bizzat Başkanlık Etmesi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Padişahın Divana Bizzat Başkanlık Etmesi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 583) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_584', 'ottoman', 'Veziriazamın Rakiplerini Zehirletmesi Şüphesi', 'Bab-ı Âli', 'Sadrazamın kendisine muhalif olan dirayetli genç bir paşayı saray hekimi eliyle zehirlettiği şayiası yayıldı.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Tahkikatı bağımsız kazaskere devret; şüphe sabitse sadrazamı makamından azlet.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Sarayda zehirli siyaset temizlendi; dürüst rical ölüm korkusundan kurtuldu."},{"label":"Sadrazamı yıpratmayın; dedikoduyu çıkaranları cezalandırın.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Veziriazamın Rakiplerini Zehirletmesi Şüphesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Veziriazamın Rakiplerini Zehirletmesi Şüphesi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Veziriazamın Rakiplerini Zehirletmesi Şüphesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 584) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_585', 'ottoman', 'Kafesteki Şehzadelerin Bahçeye Çıkma Hakkı', 'Harem Teşrifatı', 'Yıllardır dört duvar arasında güneş görmeyen şehzadelerin akıl sağlığını yitirmemesi için hava almalarına izin verilmesi istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ferman çıkar: Şehzadeler gözetim altında bahçede at binsin, hekim ve allamelerle ders görsün.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Şehzadelerin aklı ve sıhhati korundu; tahta şuurlu hükümdarlar yetişti."},{"label":"Kaçarlar veya isyan çıkarırlar; odalarından bir adım bile çıkarmayın.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Kafesteki Şehzadelerin Bahçeye Çıkma Hakkı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Kafesteki Şehzadelerin Bahçeye Çıkma Hakkı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Kafesteki Şehzadelerin Bahçeye Çıkma Hakkı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 585) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_586', 'ottoman', 'Viyana Barış Görüşmelerinde Tercüman Rüşveti', 'Reisülküttab Kalemi', 'Baştercümanın Avusturya delegelerinden yüklü altın alarak sınır kalelerimizin isimlerini tutanaktan eksilttiği belgelendi.', '[{"id":"char_reisulkuttab","name":"Reisülküttab"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Haini derhal divan kapısında as, tutanağı yırt ve anlaşmayı milli tercümanlarla yeniden yazdır.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Vatan toprağı masada satılmaktan kurtarıldı; düşman heyeti titredi."},{"label":"Diplomatik skandal çıkmasın; tercümanı sessizce emekli edin.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Viyana Barış Görüşmelerinde Tercüman Rüşveti meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Viyana Barış Görüşmelerinde Tercüman Rüşveti meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Viyana Barış Görüşmelerinde Tercüman Rüşveti gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 586) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_587', 'ottoman', 'Liyakat Sınavı Yerine İntisap (Torpil) Defteri', 'Enderun Mektebi', 'Saray mektebine talebe alınırken sınavın kaldırılıp sadece vezir çocuklarının kaydedilmeye başlandığı ihbar edildi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Torpil defterini ateşe at! Anadolu ve Rumeli\'nin zeki yetimlerini sınavla mektebe al.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Enderun\'a pırıl pırıl zekalar girdi; liyakat piramidi kurtarıldı."},{"label":"Vezir çocukları asildir; mektep onların hakkıdır.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Liyakat Sınavı Yerine İntisap (Torpil) Defteri nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Liyakat Sınavı Yerine İntisap (Torpil) Defteri fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Liyakat Sınavı Yerine İntisap (Torpil) Defteri meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 587) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_588', 'ottoman', 'Halkın Padişaha Mektup Yazma Sandığı (Arz-ı Hâl Kutuları)', 'Divan Mezalim Dairesi', 'Ayasofya ve Beyazıt camileri çıkışına anahtarı sadece hükümdarda olan şikâyet sandıkları konulması teklif edildi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Sandıkları diktir; her cuma gecesi bizzat mektupları oku ve zalim valileri hesaba çek.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Mazlumun feryadı aracısız sultana ulaştı; vezirlerin korkudan ödü koptu."},{"label":"Padişah mektup okumakla vakit kaybedemez; vezirler baksın.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Halkın Padişaha Mektup Yazma Sandığı (Arz-ı Hâl Kutuları) nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Halkın Padişaha Mektup Yazma Sandığı (Arz-ı Hâl Kutuları) fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Halkın Padişaha Mektup Yazma Sandığı (Arz-ı Hâl Kutuları) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 588) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_589', 'ottoman', 'Padişahın Şahsi Keyfi İçin İdam Fermanı Çıkarması', 'Şeyhülislam Fetvahanesi', 'Öfkeli bir anında padişahın, kendisine gerçeği söyleyen bir müezzini idam ettirmek istemesi üzerine Şeyhülislam direndi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'Öfke şeytandandır!\' diyerek kılıcı indir, Şeyhülislamın elini öp ve tövbe et.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Hukuk hükümdarın öfkesini yendi; padişah nefsine galip gelip büyüdü."},{"label":"Şeyhülislamı azlet; müezzini derhal cellada ver.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Padişahın Şahsi Keyfi İçin İdam Fermanı Çıkarması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Padişahın Şahsi Keyfi İçin İdam Fermanı Çıkarması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Padişahın Şahsi Keyfi İçin İdam Fermanı Çıkarması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 589) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_590', 'ottoman', 'Devlet Ricalinin Türkçe Dışında Lisan Bilmesi', 'Bab-ı Âli İstişare Meclisi', 'Hariciye memurlarının Fransızca, Rumca ve Farsça bilmelerinin mecburi kılınması önerildi; tutucular karşı çıkıyor.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Lisan bilmek kuvvet tir; mekteplerde yabancı lisanları mecburi kıl ve diplomasi akademisi aç.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Genç diplomatlarımız elçileri kendi lisanlarında mat etti; diplomasi şahlandı."},{"label":"Türkçe ve Arapça kafidir; Frenk lisanı fitne getirir.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Devlet Ricalinin Türkçe Dışında Lisan Bilmesi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Devlet Ricalinin Türkçe Dışında Lisan Bilmesi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Devlet Ricalinin Türkçe Dışında Lisan Bilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 590) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_591', 'ottoman', 'Kanûn-ı Kadîm Defterlerinin Mühürlenerek Korunması', 'Topkapı Arşivi', 'Fatih ve Kanuni devrinden kalan kadim kanun defterlerinin tahrif edilmesini önlemek için çelik sandıklarda mühürlenmesi istendi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Sandıkları yaptır, mühürleri kazasker ve sadrazama ver; kanunların tek harfi bile değiştirilemesin.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Hukuki istikrar sağlandı; vezirlerin keyfi kanun uydurması bitti."},{"label":"Zaman değişti; her sadrazam kendi kanununu yazsın.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kanûn-ı Kadîm Defterlerinin Mühürlenerek Korunması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kanûn-ı Kadîm Defterlerinin Mühürlenerek Korunması fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kanûn-ı Kadîm Defterlerinin Mühürlenerek Korunması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 591) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_592', 'ottoman', 'Yargıçların Tebaadan Hediye Almasının Cezası', 'Kazaskerlik Meclisi', 'Bir kadının bayram hediyesi diye tüccardan bir at ve kürk kabul ettiği, sonra tüccarın davasında beraat verdiği ortaya çıktı.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"\'Hâkime verilen hediye rüşvettir!\' fermanını neşret; kadıyı derhal azlet ve kürkü hazineye irat kaydet.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Yargıda hediye kılıfı yırtıldı; mahkemelere tertemiz adalet geldi."},{"label":"Bayramlaşmadır; kadının niyetini sorgulama.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yargıçların Tebaadan Hediye Almasının Cezası sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Yargıçların Tebaadan Hediye Almasının Cezası meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Yargıçların Tebaadan Hediye Almasının Cezası gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 592) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_593', 'ottoman', 'Sadrazamın Kendi Heykelini Yaptırmak İstemesi', 'Bab-ı Âli', 'Batı hayranı bir veziriazamın saray meydanına kendi mermer heykelini diktirmek için heykeltıraş getirdiği görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Heykeltıraşı geri yolla, veziri azarla: \'Biz taştan put dikmeye değil, kalplere adalet kazımaya geldik!\'.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -3","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-3},"log":"Kibir kırıldı; devlet adamının hizmetkâr olduğu hatırlatıldı."},{"label":"Modernliktir deyip heykelin dikilmesine izin ver.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Sadrazamın Kendi Heykelini Yaptırmak İstemesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Sadrazamın Kendi Heykelini Yaptırmak İstemesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Sadrazamın Kendi Heykelini Yaptırmak İstemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 593) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_594', 'ottoman', 'Ali Kuşçu ve Uluğ Bey Zîclerinin Basılması', 'Süleymaniye Kütüphanesi', 'Gökbilim cetvellerinin denizcilik ve kıble tayini için matbaada binlerce nüsha basılıp dağıtılması teklif edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütçe ayır; zîcleri bastırıp tüm kaptanlara, mühendislere ve müneccimbaşıya ulaştır.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Denizlerde rotalar şaşmadı; ilim meclisleri muazzam feyiz aldı."},{"label":"Yıldızlara bakarak yön bulmak fuzulidir; pusula yeter.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Ali Kuşçu ve Uluğ Bey Zîclerinin Basılması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Ali Kuşçu ve Uluğ Bey Zîclerinin Basılması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ali Kuşçu ve Uluğ Bey Zîclerinin Basılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 594) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_595', 'ottoman', 'Halkın Vergi İsyanında Haklı Bulunması', 'Şeyhülislamlık', 'Zalim bir valinin koyduğu aşırı vergiye karşı kazma kürekle ayaklanan köylüleri Şeyhülislam \'meşru müdafaa\' saydı.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Şeyhülislamın fetvasına uy: Valiyi görevden alıp köylünün vergilerini affet ve adaleti sağla.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Halk devlete değil zalim ferde isyan ettiğini gördü; tahta bağlandı."},{"label":"Devlete karşı kalkan her el kılıçla kesilir de; köylüleri kılıçtan geçir.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Halkın Vergi İsyanında Haklı Bulunması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Halkın Vergi İsyanında Haklı Bulunması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Halkın Vergi İsyanında Haklı Bulunması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 595) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_596', 'ottoman', 'Millet Sistemi ve Cemaat Muhtariyeti', 'Bab-ı Âli İstişare Meclisi', 'Gayrimüslim cemaatlerin kendi medeni hukuk davalarını (evlilik, miras) kendi patrik ve haham meclislerinde görme hakkı teyit edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_ortodoks_patriki","name":"Ortodoks Patriği"}]', '[{"label":"Fatih\'in fermanına sadık kal: Cemaatlerin din ve vicdan muhtariyetini koru, şeriatın adaletini göster.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"İmparatorluğun çok kültürlü barış harcı perçinlendi; cemaatler sadakat sundu."},{"label":"Herkesi zorla tek tip örfe bağla; kilise mahkemelerini kapat.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Millet Sistemi ve Cemaat Muhtariyeti nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Millet Sistemi ve Cemaat Muhtariyeti fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Millet Sistemi ve Cemaat Muhtariyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 596) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_597', 'ottoman', 'Sadrazamın Divan Evrakını Yakması', 'Topkapı Enderun Kalemi', 'Azledileceğini anlayan eski vezirin, rüşvet ve zimmet belgelerini yok etmek için sadaret arşivini ateşe verdiği görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Yangını söndürt, kalan evrakı mühürlet ve hain vezirin tüm mal varlığına el koyup cezalandır.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Devlet evrakına hıyanet eden cezasız kalmadı; hazineye altın aktı."},{"label":"Yangın kazadır deyip olayı örtbas edin.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Sadrazamın Divan Evrakını Yakması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Sadrazamın Divan Evrakını Yakması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Sadrazamın Divan Evrakını Yakması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 597) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_598', 'ottoman', 'Kanunname-i Âl-i Osman\'ın Taş Baskıyla Çoğaltılması', 'Dîvân-ı Hümâyûn', 'Tüm kaza kadılarına ve sancak beylerine dağıtılmak üzere devlet kanunlarının tek bir ciltte basılıp gönderilmesi teklif edildi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Bütün kanunları tek kitapta toplat, taş baskıyla binlerce basıp en uç köye kadar ulaştır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Kanun herkesin eline ulaştı; zalim valilerin keyfi kanun uydurması bitti."},{"label":"Kanun halka açıklanmaz; devlet sırrıdır.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kanunname-i Âl-i Osman\'ın Taş Baskıyla Çoğaltılması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kanunname-i Âl-i Osman\'ın Taş Baskıyla Çoğaltılması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kanunname-i Âl-i Osman\'ın Taş Baskıyla Çoğaltılması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 598) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_599', 'ottoman', 'Adalet Dairesinin Tamamlanışı: Büyük Çevrim', 'Kınalızâde Ali Çelebi\'nin Vasiyeti', 'Ahlâk-ı Alâî müellifi son sahifesinde sorar: \'Ey Padişah! Sekiz halkadan birini feda etmen gerekse, hangisinden vazgeçersin?\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'HİÇBİRİNDEN! Çemberin tek bir halkası koparsa mülk, ordu, hazine ve millet yerle yeksan olur!\'.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Dâire-i Adliyye hakikatiyle nizam-ı mülk tamamlandı; devlet ebed-müddet mertebesine erdi."},{"label":"\'Reayadan vazgeçerim; mühim olan sarayın ve askerin bekasıdır.\'.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Adalet Dairesinin Tamamlanışı: Büyük Çevrim nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Adalet Dairesinin Tamamlanışı: Büyük Çevrim fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Adalet Dairesinin Tamamlanışı: Büyük Çevrim meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 599) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_600', 'ottoman', 'Cihan Nizamının Tacı: İnsanı Yaşat ki Devlet Yaşasın', 'Ebed-Müddet Saltanat Mührü', 'Altı yüz yıllık nizam tecrübesi son sözü söyler: Mülk kılıçla fethedilir, ancak adalet ve merhametle ayakta tutulur!', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"MÜHRÜ BAS: \'ADALET MÜLKÜN TEMELİDİR!\'.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Adalet çemberi kainat nizamıyla kenetlendi; cihanşümul sulh ve adalet tecelli etti."},{"label":"\'Kuvvet bendedir, dilediğimi ezerim!\'.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Cihan Nizamının Tacı: İnsanı Yaşat ki Devlet Yaşasın nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Cihan Nizamının Tacı: İnsanı Yaşat ki Devlet Yaşasın fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Cihan Nizamının Tacı: İnsanı Yaşat ki Devlet Yaşasın meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 600) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_601', 'ottoman', 'Menzil Atlarının Tüccara Kiralanması', 'Menzilhane Teftişi', 'Bolu menzilhanesindeki ulak atlarının, menzil emini tarafından gizlice ticaret kervanlarına yüksek kirayla verildiği ve devlet fermanlarının günlerce geciktiği anlaşıldı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Menzil eminini azlet, haksız kazancını müsadere et ve atları sadece devlet ulaklarına tahsis et.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Haberleşme zinciri onarıldı; fermanlar sınır kalelerine vaktinde ulaştı."},{"label":"Menzilhanenin masrafı çoktur; emin bu parayla atlara yem alıyor deyip yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil Atlarının Tüccara Kiralanması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Menzil Atlarının Tüccara Kiralanması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Menzil Atlarının Tüccara Kiralanması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 601) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_602', 'ottoman', 'Güvercin Postası Ağı Kurulması', 'Reisülküttab Kalemi', 'Suriye ve Mısır eyaletlerindeki kalelerden payitahta acil istihbarat ulaştırmak için hususi posta güvercini kuleleri kurulması teklif edildi.', '[{"id":"char_reisulkuttab","name":"Reisülküttab"},{"id":"char_donanma_reisi","name":"Donanma Reisi"}]', '[{"label":"Kuleleri inşa ettir ve kuşbazları vazifelendir; en hızlı haber kanadın ucundadır.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Düşman donanmasının hareketleri saatler içinde saraya bildirildi."},{"label":"Kuşla devlet işi yürütülmez; süvari ulaklarımız yeterlidir.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Güvercin Postası Ağı Kurulması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Güvercin Postası Ağı Kurulması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Güvercin Postası Ağı Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 602) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_603', 'ottoman', 'Menzil Köylülerinin Aşırı \'Sürsat\' Yükü', 'Kaza Sicili', 'Ana yol üstündeki köylüler, her gün geçen vezir ve asker alaylarına bedelsiz arpa ve koyun vermekten tükendi; köyleri terk etmek üzereler.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Sürsatı nakit bedele bağla; ordu levazımı köylünün koyununu parasını peşin ödeyerek alsın.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Köylü kaçmaktan vazgeçti; menzil yolları mamur kaldı."},{"label":"Askerin rızkıdır; yol üstünde oturan ceremesini çeker.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Menzil Köylülerinin Aşırı \'Sürsat\' Yükü nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Menzil Köylülerinin Aşırı \'Sürsat\' Yükü fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Menzil Köylülerinin Aşırı \'Sürsat\' Yükü meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 603) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_604', 'ottoman', 'Fırat Üzerine Sal-Köprü İnşası', 'Hassa Mimarları', 'Doğu seferlerinde ordunun Fırat\'ı geçerken haftalar kaybetmemesi için Birecik\'te zincirli tomruk köprü kurulması istendi.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Birecik tersanesine ödenek çıkar; kalyoncu ustalarıyla sabit nehir köprüsünü kurdur.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Ordu nehirleri bir günde aştı; tüccar kervanları güvenle geçti."},{"label":"Katır ve sallarla geçmeye devam edin; köprü masrafına lüzum yok.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırat Üzerine Sal-Köprü İnşası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Fırat Üzerine Sal-Köprü İnşası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Fırat Üzerine Sal-Köprü İnşası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 604) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_605', 'ottoman', 'Ilgaz Dağı Geçidinde Donan Yolcular', 'Derbentçiler Kâhyalığı', 'Kışın Ilgaz geçidinde yolcuların karda mahsur kalıp donduğu, derbentçi köylülerin sığınma hanı kurmak istediği arz edildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Derbent hanı inşa ettir; derbentçilere kışın ocak yakıp çorba kaynatmaları için tahsisat bağla.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Geçit emniyete alındı; karda kalan yolcular sıcacık çorbayla hayata döndü."},{"label":"Kış günü dağa çıkan sonucuna katlanır; devlet han yapamaz.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Ilgaz Dağı Geçidinde Donan Yolcular nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Ilgaz Dağı Geçidinde Donan Yolcular fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Ilgaz Dağı Geçidinde Donan Yolcular meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 605) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_606', 'ottoman', 'Mors Alfabesinin Türkçe Yazıya Uyarlanması', 'Bab-ı Âli Telgraf Odası', 'Mühendisler, telgraf tellerinde Osmanlı Türkçesiyle şifreli ve hızlı yazışma sağlayacak hususi Mors cetveli hazırladı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Cetveli resmi tebliğ et; ordu ve vilayet telgrafçılarına acilen talim ettir.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Yıldırım haberleşmesi başladı; isyanlar büyümeden telgrafla bastırıldı."},{"label":"Eski mektup usulü kâfidir; tellere ecnebi harfi karıştırmayın.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Mors Alfabesinin Türkçe Yazıya Uyarlanması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Mors Alfabesinin Türkçe Yazıya Uyarlanması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Mors Alfabesinin Türkçe Yazıya Uyarlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 606) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_607', 'ottoman', 'Ulak Çantalarının Nehirde Zayi Olması', 'Taşra Postası', 'Meriç nehrini geçerken alabora olan kayıkta sancak tahrir defterlerinin ve gizli emirlerin sulara kapıldığı öğrenildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ulaklara su geçirmez meşin muşamba torbalar ve can yelekleri tahsis et; kayıtları yenile.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Evrak emniyeti sağlandı; fermanların suya kapılması ebediyen önlendi."},{"label":"Ulağın ihmalidir deyip ulağı zindana atın; başka tedbire lüzum yok.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ulak Çantalarının Nehirde Zayi Olması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Ulak Çantalarının Nehirde Zayi Olması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Ulak Çantalarının Nehirde Zayi Olması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 607) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_608', 'ottoman', 'Kervansaraylarda Konaklama Harcı Hilesi', 'Kaza İhtisabı', 'Vakıf kervansarayındaki hancıların, yolculardan yatak ve çorba için kanuna aykırı \'kapı harcı\' aldığı ortaya çıktı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Hancıyı derhal kov; kervansarayın kapısına vakfiyeyi as: \'Burada her yolcuya üç gün misafirlik haktır!\'.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Vakıf ruhu diriltildi; yolcular kervansarayda dualarla konakladı."},{"label":"Hancılar da ekmek yiyecek deyip harcı tarafları rencide etmeden adil bir sulhname ile anlaşmaya bağla.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kervansaraylarda Konaklama Harcı Hilesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kervansaraylarda Konaklama Harcı Hilesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kervansaraylarda Konaklama Harcı Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 608) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_609', 'ottoman', 'Menzil Atlarının Yetersiz Beslenmesi', 'Balkan Menzilleri', 'Arpa fiyatları fırlayınca menzilciler atlara ot yedirmeye başladı; koşan beygirler yollarda çatlayıp kalıyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Menzillere doğrudan devlet ambarından arpa tahsisatı çıkar; atların sağlığını koru.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Menzil atları güçlendi; haberler payitahta yıldırım gibi vardı."},{"label":"Menzilciler kendi ceplerinden alsın; hazineden yem verilmez.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Menzil Atlarının Yetersiz Beslenmesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Menzil Atlarının Yetersiz Beslenmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Menzil Atlarının Yetersiz Beslenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 609) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_610', 'ottoman', 'Gizli Şifre Kâtipliği (Şifre Kalemi) Teşkili', 'Dîvân-ı Hümâyûn', 'Valilere gönderilen gizli emirlerin yolda eşkıya ve yabancı casuslarca ele geçirilmesini önlemek için şifreli alfabe önerildi.', '[{"id":"char_tasra_valisi","name":"Taşra Valisi"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Şifre Kalemi\'ni kurdur; her valiye hususi anahtarlı şifre defterleri dağıt.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Devlet sırları zırha büründü; casuslar mektupları ele geçirse de okuyamadı."},{"label":"Ferman açıktan yazılır, gizleyecek şeyimiz yoktur de.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gizli Şifre Kâtipliği (Şifre Kalemi) Teşkili meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gizli Şifre Kâtipliği (Şifre Kalemi) Teşkili meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gizli Şifre Kâtipliği (Şifre Kalemi) Teşkili gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 610) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_611', 'ottoman', 'Menzilhanelerde Gece Kandili Yasağı', 'Anadolu Menâzili', 'Menzil eminlerinin yağ tasarrufu bahanesiyle geceleri kandil yakmadığı, ulakların karanlıkta at bulamadığı öğrenildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Her menzile fıçıyla beziryağı gönder; kapıda gece gündüz meşale yanmasını mecburi kıl.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Menziller karanlıktan kurtuldu; gece ulakları vakit kaybetmeden at değiştirdi."},{"label":"Ulaklar gündüz yol alsın; gece masrafına gerek yok.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Menzilhanelerde Gece Kandili Yasağı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Menzilhanelerde Gece Kandili Yasağı fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Menzilhanelerde Gece Kandili Yasağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 611) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_612', 'ottoman', 'Eşkıyayı Püskürten Derbentçilere Tüfek Dağıtımı', 'Derbent Köyleri', 'Dağ geçitlerini bekleyen köylülerin elinde sadece sopa ve kalkan var; eşkıyaya karşı tüfek talep ediyorlar.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Cephanelikten mühürlü tüfek ve barut dağıt; geçit köylülerini nizami milis yap.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Geçitler eşkıyaya mezar oldu; kervanlar korkusuzca dağları aştı."},{"label":"Köylüye silah verilmez, isyan ederler deyip reddet.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Eşkıyayı Püskürten Derbentçilere Tüfek Dağıtımı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Eşkıyayı Püskürten Derbentçilere Tüfek Dağıtımı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Eşkıyayı Püskürten Derbentçilere Tüfek Dağıtımı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 612) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_613', 'ottoman', 'Şehir İçi Mektup Dağıtıcıları (Müştak Teşkilatı)', 'İstanbul Şehremaneti', 'Payitaht içinde esnafın ve halkın mektuplarını kaybetmeden adrese ulaştıracak resmi posta dağıtıcıları kurulması istendi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Muvazzaf posta neferleri teşkil et; cüzi pul ücretiyle şehir içi intizamı kur.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Şehir içi ticaret ve haberleşme canlandı; kayıp mektup derdi bitti."},{"label":"Herkes mektubunu kendi uşağıyla göndersin.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şehir İçi Mektup Dağıtıcıları (Müştak Teşkilatı) sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Şehir İçi Mektup Dağıtıcıları (Müştak Teşkilatı) meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Şehir İçi Mektup Dağıtıcıları (Müştak Teşkilatı) gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 613) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_614', 'ottoman', 'Nehir Sinyal Kuleleri (Telgraf-ı Rüzgârî)', 'Tuna Yalıları', 'Tuna boyundaki kaleler arasında bayrak ve ayna işaretleriyle dakikalar içinde düşman hareketini bildiren optik kuleler teklif edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kuleleri kurdur; Tuna boyunca optik sinyal ağını faaliyete geçir.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Kazak baskınları kulelerden anında görüldü; nehir garnizonu pusuya düşmedi."},{"label":"Sisli havada ayna çalışmaz; masraf etmeyin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Nehir Sinyal Kuleleri (Telgraf-ı Rüzgârî) nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Nehir Sinyal Kuleleri (Telgraf-ı Rüzgârî) fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Nehir Sinyal Kuleleri (Telgraf-ı Rüzgârî) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 614) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_615', 'ottoman', 'Ulak Beygirine Fazla Yük Vuran Paşazade', 'Kaza Sicili', 'Bir vezirin oğlu, şahsi sandıklarını ve av köpeklerini ulak beygirine yükletip devlet atını çatlattı.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Paşazadeye atın bedelini iki kat ödet, menzil kanununu çiğnediği için sürgün et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Devlet atı vezir oğlunun oyuncağı olmaktan kurtarıldı; halk adaleti alkışladı."},{"label":"Vezirin hatırıdır; atın canı için paşazade incitilmez.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Ulak Beygirine Fazla Yük Vuran Paşazade nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Ulak Beygirine Fazla Yük Vuran Paşazade fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Ulak Beygirine Fazla Yük Vuran Paşazade meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 615) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_616', 'ottoman', 'Çöl Kervanlarında Hecin Devesi Postası', 'Basra Çölleri', 'Bağdat ile Basra arasındaki acil mektupların hızlı koşan hecin develeriyle taşınması teklif edildi.', '[{"id":"char_kervancibasi","name":"Kervancıbaşı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bedevi aşiretinden hecin süvarileri kirala ve çöl posta hattını emniyete al.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Çöl fırtınaları haberleşmeyi kesemedi; Basra ile irtibat şimşek gibi hızlandı."},{"label":"Normal kervanlarla yollayın; acelesi yok.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çöl Kervanlarında Hecin Devesi Postası sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Çöl Kervanlarında Hecin Devesi Postası meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Çöl Kervanlarında Hecin Devesi Postası gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 616) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_617', 'ottoman', 'Deniz Postası Kayıklarının Fırtınada Batması', 'Trabzon İskelesi', 'Karadeniz kıyısındaki kalelere ferman taşıyan hafif çektiri kayıklarının dalgalara dayanamadığı bildirildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Karadeniz\'in hırçın dalgalarına uygun sağlam omurgalı yeni posta kotraları inşa ettir.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Kotralar fırtınada bile seyre çıktı; sahil garnizonları emirsiz kalmadı."},{"label":"Deniz durulana kadar ferman yollamayın.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Deniz Postası Kayıklarının Fırtınada Batması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Deniz Postası Kayıklarının Fırtınada Batması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Deniz Postası Kayıklarının Fırtınada Batması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 617) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_618', 'ottoman', 'Menzil Yolsuzluklarını Önleyen Damgalı Pusula', 'Menzil Kalemi', 'Sahte ulakların menzillerden bedava at almasını önlemek için sadece sadrazamın özel soğuk damgasıyla mühürlü pusula şartı getirildi.', '[{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Mühürlü pusula nizamını yürürlüğe koy; sahte pusulayla at alanı idamla cezalandır.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Sahte ulak tufanı durduruldu; menzil bütçesi iki kat rahatladı."},{"label":"Mühür işi bürokrasiyi uzatır; menzilcinin ferasetine bırakın.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Menzil Yolsuzluklarını Önleyen Damgalı Pusula nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Menzil Yolsuzluklarını Önleyen Damgalı Pusula fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Menzil Yolsuzluklarını Önleyen Damgalı Pusula meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 618) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_619', 'ottoman', 'Büyükçekmece Köprüsü Bakımsızlığı', 'Edirne Yolu', 'Mimar Sinan\'ın şaheseri Büyükçekmece Köprüsü\'nün ayaklarındaki dalgakıran taşlarının kış taşkınında oynadığı bildirildi.', '[{"id":"char_mimar_sinan","name":"Mimar Sinan"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Derhal başmimarı ve dalgıçları sevk et; su altından kurşun dökerek köprüyü tahkim et.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Tarihi köprü kurtarıldı; Rumeli sefer yolu kesintisiz açık kaldı."},{"label":"Köprü asırlardır duruyor, bir şey olmaz deyip tamiri ertele.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Büyükçekmece Köprüsü Bakımsızlığı meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Büyükçekmece Köprüsü Bakımsızlığı hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Büyükçekmece Köprüsü Bakımsızlığı gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 619) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_620', 'ottoman', 'Posta Nezareti\'nin Resmen İhdası', 'Dîvân-ı Hümâyûn', 'Tüm menzilhane, derbent ve ulak teşkilatının tek bir çatı altında modern Posta Nezareti olarak birleştirilmesi teklif edildi.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Posta Nezareti\'ni resmen kur; nizamnameyi neşret ve pul usulünü başlat.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Haberleşme kurumsallaştı; imparatorluğun her köşesi tek vücut oldu."},{"label":"Eski menzil ağalığı iyidir; nezaret açıp yeni memur türetmeyin.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Posta Nezareti\'nin Resmen İhdası nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Posta Nezareti\'nin Resmen İhdası fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Posta Nezareti\'nin Resmen İhdası meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 620) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_621', 'ottoman', 'Kimsesiz Çocuklara Zanaat Atölyeleri Kurulması', 'Dârülaceze İdaresi', 'Sokaktan toplanan yetim çocukların dilenmek yerine marangozluk, halıcılık ve demircilik öğrenmesi için atölyeler teklif edildi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"},{"id":"char_yetim_tebaa","name":"Yetim Tebaa"}]', '[{"label":"Ödeneği tahsis et; ustaları görevlendirip yetimlerin eline altın bilezik tak.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Sokaklar yetimlerden arındı; zanaat kollarına yüzlerce çalışkan usta katıldı."},{"label":"Sadece karınlarını doyurun; zanaat atölyesi lüzumsuz masraftır.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kimsesiz Çocuklara Zanaat Atölyeleri Kurulması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kimsesiz Çocuklara Zanaat Atölyeleri Kurulması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kimsesiz Çocuklara Zanaat Atölyeleri Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 621) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_622', 'ottoman', 'Akıl Hastalarının Zincirlerinin Sökülmesi', 'Haseki Bimarhanesi', 'Yeni baştabip, akıl hastalarının demir zincirlerle duvara bağlanmasının vahşet olduğunu, geniş avlularda serbestçe dolaşmalarını önerdi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Zincirleri söktür! Çiçekli avlular yaptır, hekimlere şefkatle tedavi nizamı koy.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"İslam medeniyetinin insani zirvesi parladı; hastalar dinginliğe kavuştu."},{"label":"Delidir, etrafa saldırırlar; zincirleri daha sıkı bağlayın.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Beytülmâl\'den darüşşifa ve karantina lazaretolarına acil ödenek tahsis et; Akıl Hastalarının Zincirlerinin Sökülmesi sürecinde sıhhi teftişe riayet eden tüccarlara vergi indirimi tanı.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Limanı silahlı muhafızlarla karantinaya al; Akıl Hastalarının Zincirlerinin Sökülmesi fermanını delmeye kalkan ticaret gemilerini top ateşi tehdidiyle açık denizde tut.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Karantina-i Bahriye ve Sıhhat Kanunu\' neşret; Akıl Hastalarının Zincirlerinin Sökülmesi gibi hadiselerin tekerrürünü önleyecek şekilde liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 622) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_623', 'ottoman', 'Dilenci Şebekelerinin Sahte Körlük Hilesi', 'İstanbul İhtisabı', 'Gözlerine süt damlatıp kör süsü veren organize dilenci ağalarının fukaranın sadakasını gasp ettiği tespit edildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Hekim kontrolüyle sahtekârları ayır; sağlam olanları amele taburlarına ver, gerçek sakatları Dârülaceze\'ye yerleştir.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Sadaka hırsızlığı durduruldu; gerçek muhtaçlar sıcacık yuvaya kavuştu."},{"label":"Sadaka verenin niyetidir; dilencilere meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Dilenci Şebekelerinin Sahte Körlük Hilesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Dilenci Şebekelerinin Sahte Körlük Hilesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Dilenci Şebekelerinin Sahte Körlük Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 623) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_624', 'ottoman', 'Kanser ve Tümör Hastalarına Afyonlu Şurup', 'Edirne Şifahanesi', 'Şiddetli ağrılar çeken amansız hastalara acılarını dindirmek için kontrollü tıbbi afyon şurubu verilmesi fetvası istendi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Zaruret fetvasını tasdikle; hekim kontrolünde acı çeken dertlilere şifa ve teselli ver.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Çaresiz hastaların ızdırabı dindi; hekimlik merhametle birleşti."},{"label":"Afyon haramdır deyip acı çeken hastaları kaderine terk et.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Kanser ve Tümör Hastalarına Afyonlu Şurup nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Kanser ve Tümör Hastalarına Afyonlu Şurup fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Kanser ve Tümör Hastalarına Afyonlu Şurup meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 624) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_625', 'ottoman', 'Aşevlerinde Gayrimüslim Fukaraya Yemek Ayrımı', 'Payitaht İmarethaneleri', 'Bazı mutaassıp memurların, kapıya gelen aç Rum ve Ermeni yetimlerine \'Burası İslam vakfıdır\' diyerek çorba vermediği görüldü.', '[{"id":"char_yetim_tebaa","name":"Yetim Tebaa"},{"id":"char_ermeni_cemaat_temsilcisi","name":"Ermeni Cemaat Temsilcisi"}]', '[{"label":"Ferman neşret: \'Açlığın dini olmaz! Kapıya gelen her canlıya çorba vermek vakfın şerefidir!\'.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"İslam\'ın evrensel şefkati tecelli etti; gayrimüslim tebaa devlete şükran sundu."},{"label":"Memurlar haklıdır; vakıf parası sadece Müslümana harcanır.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Aşevlerinde Gayrimüslim Fukaraya Yemek Ayrımı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Aşevlerinde Gayrimüslim Fukaraya Yemek Ayrımı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Aşevlerinde Gayrimüslim Fukaraya Yemek Ayrımı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 625) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_626', 'ottoman', 'Yaşlı Gazilerin Maaşlarının Kesilmesi', 'Kaza Meclisi', 'Defterdarlık müfettişlerinin, savaşa gidemeyecek kadar yaşlanan eski sipahilerin dirliklerini iptal ettiği bildirildi.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Dirlikleri derhal iade et! \'Gençliğinde kanını dökenin ihtiyarlığında ekmeği kesilemez!\'.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Gazilerin gözyaşı dindi; genç askerlerin devlete olan fedakârlık azmi perçinlendi."},{"label":"Kılıç tutamayan dirlik alamaz; bütçe tasarrufu şarttır.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Yaşlı Gazilerin Maaşlarının Kesilmesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Yaşlı Gazilerin Maaşlarının Kesilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yaşlı Gazilerin Maaşlarının Kesilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 626) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_627', 'ottoman', 'Kışın Sokakta Kalan Garibanlar İçin Isınma Hanları', 'İstanbul Şehremaneti', 'Dondurucu soğuklarda sur diplerinde yatan yüzlerce kimsesizin donmaması için kamu binalarının gece açılması teklif edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Bütün boş kışla ve hanları açtır; sobalar yansın, sıcak çorba ve battaniye dağıtılsın.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Tek bir gariban soğukta donmadı; padişahın şefkati dillere destan oldu."},{"label":"Binalar kirlenir ve yangın çıkar; kapıları kilitli tutun.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kışın Sokakta Kalan Garibanlar İçin Isınma Hanları nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kışın Sokakta Kalan Garibanlar İçin Isınma Hanları fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kışın Sokakta Kalan Garibanlar İçin Isınma Hanları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 627) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_628', 'ottoman', 'Körler İçin Kabartma Yazı Mektebi', 'Hekimbaşı Kalemi', 'Görme engelli yetimlerin Kur\'an ve ilim öğrenebilmesi için balmumu kabartma levhalarla hususi mektep açılması önerildi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Mektebi açtır, muallimler tahsis et ve kabartma levhaları hazineden karşıla.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Karanlık dünyalar ilimle aydınlandı; engelli çocuklara hayat kapısı açıldı."},{"label":"Gözü görmeyen adam okuyamaz; boşuna masraf yapmayın.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Körler İçin Kabartma Yazı Mektebi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Körler İçin Kabartma Yazı Mektebi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Körler İçin Kabartma Yazı Mektebi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 628) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_629', 'ottoman', 'Darüşşifa Bahçesinde Şifalı Otlar Serası', 'Bursa Darüşşifası', 'Kışın taze bulunamayan nane, adaçayı ve kantaronun seralarda yetiştirilmesi için camlı kış bahçesi istendi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Seraları kurdur; tabiplere kış boyunca taze şifalı nebatat sağla.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Kışın ilaçsızlık çekilmedi; taze merhemler hastalara şifa oldu."},{"label":"Kuru otlar idare eder; kış bahçesine bütçe ayrılmaz.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Darüşşifa Bahçesinde Şifalı Otlar Serası nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Darüşşifa Bahçesinde Şifalı Otlar Serası fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Darüşşifa Bahçesinde Şifalı Otlar Serası meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 629) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_630', 'ottoman', 'Borç Yüzünden Hapsedilen Babaların Çocukları', 'Kaza Müftülüğü', 'Alacaklı sarrafların baskısıyla zindana atılan fakir babaların evdeki sabi çocuklarının açlıktan kıvrandığı bildirildi.', '[{"id":"char_muftu","name":"Müftü"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Sadaka ve Zekât Sandığı\'ndan borcu kapat; babayı tahliye edip işe yerleştir.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Aileler dağılmaktan kurtuldu; tefecilerin zulmü kırıldı."},{"label":"Alacaklının hakkıdır; borcunu ödemeyen zindanda çürüsün.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Borç Yüzünden Hapsedilen Babaların Çocukları nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Borç Yüzünden Hapsedilen Babaların Çocukları fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Borç Yüzünden Hapsedilen Babaların Çocukları meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 630) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_631', 'ottoman', 'Yaşlılara Hizmet Eden Hademelerin Kötü Muamelesi', 'Dârülaceze Teftişi', 'Dârülaceze\'deki bazı hademelerin yatalak ihtiyarları azarlayıp yemeklerini eksik verdiği hasta şikâyetleriyle belgelendi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Zalim hademeleri derhal kov ve cezalandır; \'Yaşlılarımıza hürmet etmeyen bizden değildir!\'.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Huzurevine şefkat ve intizam geldi; ihtiyarların duaları sarayı sardı."},{"label":"Hademe bulmak zordur; idarecilerin hatırına hademeleri tutun.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yaşlılara Hizmet Eden Hademelerin Kötü Muamelesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Yaşlılara Hizmet Eden Hademelerin Kötü Muamelesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Yaşlılara Hizmet Eden Hademelerin Kötü Muamelesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 631) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_632', 'ottoman', 'Askıda Ekmek Geleneğinin Resmileştirilmesi', 'İstanbul Fırınları', 'Fırınlarda zenginlerin parasını ödediği ekmeklerin fukaraya onurunu kırmadan dağıtılması için askı nizamı teklif edildi.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Ferman çıkar: Her fırında \'Askıda Ekmek\' köşesi açılsın; veren de alan da birbirini görmesin.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Yoksulun izzet-i nefsi korundu; cemiyet dayanışmayla kenetlendi."},{"label":"Devletin fırın işine divan gözetiminde tarafları meşverete davet edip orta yolu bulsına lüzum yok; isteyen dilediği gibi versin.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Askıda Ekmek Geleneğinin Resmileştirilmesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Askıda Ekmek Geleneğinin Resmileştirilmesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Askıda Ekmek Geleneğinin Resmileştirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 632) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_633', 'ottoman', 'Akıl Hastalarının El Becerileriyle Üretim Yapması', 'Süleymaniye Darüşşifası', 'Bimarhanedeki hastaların sepet örme ve ebru yaparak hem sakinleştiği hem de sattıklarıyla cep harçlığı kazandığı görüldü.', '[{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Atölyeyi genişlet, hasır ve boya malzemesi bağla; hastaların emeğini koru.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Hastalar üreterek şifa buldu; bimarhane bir rehabilitasyon merkezine dönüştü."},{"label":"Delilerin yaptığı mal satılmaz; atölyeyi kapatın.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Akıl Hastalarının El Becerileriyle Üretim Yapması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Akıl Hastalarının El Becerileriyle Üretim Yapması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Akıl Hastalarının El Becerileriyle Üretim Yapması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 633) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_634', 'ottoman', 'Cüzzamlı Annelerin Sağlıklı Bebekleri', 'Üsküdar Miskinler Tekkesi', 'Cüzzamlı hastalardan doğan sağlıklı bebeklerin mikroptan korunması için derhal ayrılıp sütninelere verilmesi gerekti.', '[{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Bebekleri koruma evine aldır, masrafını vakıftan karşıla ve annelerine düzenli haber ver.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Yüzlerce sabi cüzzam illetinden kurtarıldı; anaların yüreği ferahladı."},{"label":"Ana ile evlat ayrılmaz; annelerinin yanında kalsınlar.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Cüzzamlı Annelerin Sağlıklı Bebekleri meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Cüzzamlı Annelerin Sağlıklı Bebekleri meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Cüzzamlı Annelerin Sağlıklı Bebekleri gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 634) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_635', 'ottoman', 'Evsiz Kalan Dullara Barınak Evleri', 'Kaza Meclisi', 'Savaşlarda eşini kaybedip kirasını ödeyemeyen kadınlar için vakıf konaklarının \'Darü\'l-Eytam ve Dulhane\' yapılması istendi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Konakları tahsis et, dikiş nakış tezgâhları kurdur ve kadınlara haysiyetli bir maişet sağla.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Şehit emanetleri sokaktan kurtarıldı; kadınlar üretime katıldı."},{"label":"Dullara bakmak akrabalarının işidir; devlet konak tahsis edemez.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Evsiz Kalan Dullara Barınak Evleri nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Evsiz Kalan Dullara Barınak Evleri fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Evsiz Kalan Dullara Barınak Evleri meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 635) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_636', 'ottoman', 'Savaş Gazilerine Ahşap Protez Bacak ve Kol', 'Hekimbaşı Tezkiresi', 'Tophanede bacağı kopan topçulara ve gazilere meşe ağacından hareketli protez uzuvlar yapacak marangozhane teklif edildi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"Protez atölyesini kurdur; gazilerin kendi ayakları üstünde yürümesini sağla.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Gaziler ayağa kalktı; askerin devlete olan sadakati ve muhabbeti arşa çıktı."},{"label":"Koltuk değneği yeterlidir; protez tahtasına bütçe yok.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Savaş Gazilerine Ahşap Protez Bacak ve Kol nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Savaş Gazilerine Ahşap Protez Bacak ve Kol fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Savaş Gazilerine Ahşap Protez Bacak ve Kol meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 636) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_637', 'ottoman', 'Hamalların Sırt Küfelerine Ağırlık Sınırı', 'İstanbul Şehremaneti', 'Sırtında 100 okka yük taşıyan hamalların bellerinin kırıldığı, fıtık ve sakatlık yüzünden genç yaşta öldükleri arz edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Hamal nizamnamesi koy: Tek kişinin taşıyacağı yükü 40 okka ile sınırla; aşan tüccara ceza kes.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"İnsan onuru korundu; hamalların can güvenliği sağlandı."},{"label":"Hamal güçlüdür, taşıdığı kadar kazansın; piyasaya sınır koymayın.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hamalların Sırt Küfelerine Ağırlık Sınırı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Hamalların Sırt Küfelerine Ağırlık Sınırı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Hamalların Sırt Küfelerine Ağırlık Sınırı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 637) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_638', 'ottoman', 'Kokuyla Tedavi (Aromaterapi) Bahçeleri', 'Edirne Darüşşifası', 'Gül, lavanta ve yasemin kokularının göğüs darlıklarına ve melankoliye iyi geldiği hekimlerce tespit edildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Şifahane bahçesini gül ve lavanta tarhlarıyla donat; gülsuyu imbikleri kurdur.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Hastalar mis kokular içinde şifa buldu; darüşşifa cennet bahçesine döndü."},{"label":"Çiçek koklamakla hastalık geçmez; masrafa gerek yok.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kokuyla Tedavi (Aromaterapi) Bahçeleri nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kokuyla Tedavi (Aromaterapi) Bahçeleri fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kokuyla Tedavi (Aromaterapi) Bahçeleri meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 638) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_639', 'ottoman', 'Sokak Çeşmelerine İt ve Kuş Yalakları Yapılması', 'Kaza İhtisabı', 'Sıcak yaz günlerinde sokak hayvanlarının susuzluktan telef olmaması için çeşme altlarına yalaklar yapılması teklif edildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_suyolcu_ustasi","name":"Suyolcu Ustası"}]', '[{"label":"Bütün çeşme mimarlarına emret: Her çeşmenin dibine kuş ve hayvan yalağı oyulsun.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Kuşlar ve dilsiz hayvanlar suya doydu; merhamet medeniyeti tamamlandı."},{"label":"İnsanlar su bulamıyor, hayvana yalak mı yapacağız.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Sokak Çeşmelerine İt ve Kuş Yalakları Yapılması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Sokak Çeşmelerine İt ve Kuş Yalakları Yapılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Sokak Çeşmelerine İt ve Kuş Yalakları Yapılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 639) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_640', 'ottoman', 'Sosyal Dayanışma Nizamnamesi', 'Dâire-i Adliyye Tacı', 'Toplumun en zayıf ferdinin hakkı korunmadıkça devletin adil sayılamayacağını ilan eden umumi Şefkat Fermanı hazırlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Fermanı mühürle: \'Mazlumun duası arşı titretir; zayıfı korumayan mülk payidar olamaz!\'.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Mülk merhamet ve adaletle taçlandı; devlet ebed-müddet dengesine erdi."},{"label":"Devlet sadece güçlüleri korur; zayıflar kendi başının çaresine baksın.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sosyal Dayanışma Nizamnamesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Sosyal Dayanışma Nizamnamesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Sosyal Dayanışma Nizamnamesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 640) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_641', 'ottoman', 'Gümüş Kuruşun Kenarına Tırtıl Açma Makinesi', 'Darbhane-i Âmire', 'Sarrafların gümüş sikkelerin kenarlarını makasla kırpıp tozunu çalmasını önlemek için tırtıllı kenar presi teklif edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Pres makinelerini darphaneye kurdur; tırtılsız paranın tedavülünü yasakla.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Sikke kırpma hırsızlığı bıçak gibi kesildi; Osmanlı kuruşu istikrara kavuştu."},{"label":"Pres makinesi çok pahalıdır; eski düz baskıya devam edin.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Gümüş Kuruşun Kenarına Tırtıl Açma Makinesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Gümüş Kuruşun Kenarına Tırtıl Açma Makinesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Gümüş Kuruşun Kenarına Tırtıl Açma Makinesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 641) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_642', 'ottoman', 'İltizam Açık Artırmasında Sarraf Rüşveti', 'Maliye Kalemi', 'Büyük bir mukataanın ihalesinde sarrafların gizlice anlaşıp fiyatı kasten düşük tuttuğu ve devleti zarara soktuğu anlaşıldı.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"İhaleyi derhal iptal et, anlaşmalı sarrafları kara listeye al ve mukataayı emanet usulüyle devlete işlet.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Sarraf karteli kırıldı; devlet mukataadan tam gelir elde etti."},{"label":"İhale yapılmıştır; sarraflarla arayı bozmayıp düşük fiyata onayla.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tağşiş edilen paraları piyasadan toplatıp hazine kasasında saf külçeye dönüştür; sikke istikrarını devlet garantisine al ve İltizam Açık Artırmasında Sarraf Rüşveti nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Piyasanın gümüşünü eriten sarrafları Divan-ı Hümâyûn huzurunda isticvap et; tağşiş çetelerini derhal küreğe mahkûm eyle ve İltizam Açık Artırmasında Sarraf Rüşveti fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Darphane ve Meskûkât Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve İltizam Açık Artırmasında Sarraf Rüşveti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 642) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_643', 'ottoman', 'Fırıncıların Gece Gizlice Ekmek Çıkarması', 'Un Kapanı Kâtipliği', 'Narhtan pahalıya satmak için fırıncıların kapalı kapılar ardında gece zenginlere gizli ekmek sattığı ihbar edildi.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Gece teftiş kolları çıkar; gizli ekmek satan fırınları mühürle ve unlarını kapan ambarına çek.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Gizli karaborsa çöktü; unun tamamı halkın ekmeğine dönüştü."},{"label":"Zengin parasını verir yer; fırıncının gece mesaisine divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Fırıncıların Gece Gizlice Ekmek Çıkarması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Fırıncıların Gece Gizlice Ekmek Çıkarması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Fırıncıların Gece Gizlice Ekmek Çıkarması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 643) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_644', 'ottoman', 'Girit Zeytinyağının İspanyol Yağı Diye Satılması', 'Yağ Kapanı', 'Girit\'ten gelen saf sızma yağların etiketleri değiştirilerek Frenk yağı diye iki kat narhla satıldığı görüldü.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tüccarlara ağır para cezası kes; yerli mahsulün yabancıdan üstün olduğunu fermanla ilan et.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Girit yağı hak ettiği şöhrete kavuştu; sahtekâr simsarlar sindirildi."},{"label":"Tüccar kârını bilir; serbest ticarettir deyip geçin.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Girit Zeytinyağının İspanyol Yağı Diye Satılması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Girit Zeytinyağının İspanyol Yağı Diye Satılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Girit Zeytinyağının İspanyol Yağı Diye Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 644) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_645', 'ottoman', 'Altın Varaklı Bakır Paraların Dolaşımı', 'Darbhane Kalemi', 'Yabancı korsanların piyasaya sürdüğü ince altın kaplamalı sahte Macar altınları esnafın elinde patladı.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Sarraflar loncasına mihenk taşı zorunluluğu koy; sahte paraları toplatıp getirene hakiki akçe ver.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Halkın zararı tazmin edildi; kalpazanların tuzağı boşa çıkarıldı."},{"label":"Kimin elinde kaldıysa onun zararıdır; devlet tazmin etmez.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Altın Varaklı Bakır Paraların Dolaşımı nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Altın Varaklı Bakır Paraların Dolaşımı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Altın Varaklı Bakır Paraların Dolaşımı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 645) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_646', 'ottoman', 'Lakerda Fıçılarında Kokuşmuş Balık', 'Balıkpazarı Kapanı', 'Kış için tuzlanan torik balıklarının tuzunun az konduğu, fıçıların kokup kurtlandığı muhtesipçe yakalandı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Fıçıları denize döktür, hileli balıkçıları meslekten men et ve tazminat ödet.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Kışlık gıda zehirlenmesi önlendi; balık pazarında nizam sağlandı."},{"label":"Fukara ucuza alır; fıçıları pazarda sattırın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Lakerda Fıçılarında Kokuşmuş Balık hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Lakerda Fıçılarında Kokuşmuş Balık hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Lakerda Fıçılarında Kokuşmuş Balık gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 646) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_647', 'ottoman', 'Oduncuların Boş Arabayı Ağır Tarttırması', 'Kaza İhtisabı', 'Odun tartılırken arabanın altına gizlice demir ağırlıklar konduğu, odun boşaldıktan sonra kantarın hileli çekildiği anlaşıldı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Kantarcıyı ve oduncuyu teşhir et; arabaları boşken ayrı tartma nizamı getir.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Tartı oyunu bozuldu; halk odununu tam ağırlığıyla satın aldı."},{"label":"Arabacıların küçük kârıdır; çok üzerlerine gitmeyin.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Oduncuların Boş Arabayı Ağır Tarttırması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Oduncuların Boş Arabayı Ağır Tarttırması fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Oduncuların Boş Arabayı Ağır Tarttırması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 647) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_648', 'ottoman', 'Donanma Yağlarının Sabunculara Satılması', 'Tersane Ambarı', 'Kalyonların direklerini yağlamak için alınan zeytinyağlarının tersane kâtibince gizlice sabunhanelere satıldığı ortaya çıktı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kâtibi zindana at, sabuncudan yağları geri al ve direkleri vaktinde yağlat.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Donanma levazımı kurtarıldı; kalyon direklerinin kırılması önlendi."},{"label":"Kâtip kıdemlidir; yerine yağ alması şartıyla olayı saray erkânı ile divan arasında bir denge formülü bularak uzlaş.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Donanma Yağlarının Sabunculara Satılması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Donanma Yağlarının Sabunculara Satılması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Donanma Yağlarının Sabunculara Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 648) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_649', 'ottoman', 'Yedek Akçenin (Kenz-i Mahfî) İhtiyaç Dışı Harcanması', 'Maliye Kalemi', 'Sadrazamın savaş fonu olan gizli altın hazinesini sarayın düğün ve şenlik masrafları için açmak istediği görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Mührü sandıktan çek! \'Yedek akçe yalnız vatan müdafaası içindir, tek kuruşuna dokunulamaz!\'.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Devletin kara gün teminatı korundu; saray israfına set çekildi."},{"label":"Sandığı açın; sultanın düğünü devletin şanıdır.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Yedek Akçenin (Kenz-i Mahfî) İhtiyaç Dışı Harcanması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Yedek Akçenin (Kenz-i Mahfî) İhtiyaç Dışı Harcanması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Yedek Akçenin (Kenz-i Mahfî) İhtiyaç Dışı Harcanması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 649) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_650', 'ottoman', 'Kars Balına Pekmez Karıştırılması', 'Balkapanı', 'Tüccarların Kafkasya\'dan gelen beyaz çiçek balına sarı üzüm pekmezi karıştırıp pahalıya sattığı tespit edildi.', '[{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Balkapanı muhtesibini görevlendir; hileli petekleri yaktırıp tüccarın dükkânını mühürle.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Balın saflığı korundu; şifa arayan hastalar aldatılmaktan kurtuldu."},{"label":"Pekmez de faydalıdır; fiyatta anlaşsınlar de.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kars Balına Pekmez Karıştırılması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kars Balına Pekmez Karıştırılması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kars Balına Pekmez Karıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 650) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_651', 'ottoman', 'Yabancı Bakır Paraların Eritilmesi', 'Darbhane-i Âmire', 'Avrupa\'dan hurda diye getirilen değersiz bakır levhaların darphanede gizlice Osmanlı parası kalıbına döküldüğü ihbar edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"}]', '[{"label":"Darphane kalıpçılarını teftiş et; kaçak döküm yapanları derhal küreğe mahkûm et.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Para basımında kaçakçılık durduruldu; paranın hacim dengesi korundu."},{"label":"Piyasada bozuk para azdır; bakır bakırdır deyip yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağla.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Yabancı Bakır Paraların Eritilmesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Yabancı Bakır Paraların Eritilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Yabancı Bakır Paraların Eritilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 651) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_652', 'ottoman', 'Değirmen Taşlarının Kum Bırakması', 'Un Kapanı', 'Yumuşak taşlardan yontulan ucuz değirmen taşlarının unun içine ince kum döktüğü ve ekmeklerin kumlu çıktığı görüldü.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Taş ocaklarını denetlet; sadece sert volkanik taşlardan değirmen taşı yapılmasına izin ver.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Ekmek kumlardan temizlendi; değirmen taşı standardı sağlandı."},{"label":"Değirmenciler taşı nereden bulursa alsın; divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Değirmen Taşlarının Kum Bırakması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Değirmen Taşlarının Kum Bırakması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Değirmen Taşlarının Kum Bırakması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 652) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_653', 'ottoman', 'Mumcuların İplerine Ağır Kurşun İp Katması', 'Kaza İhtisabı', 'Kandil ve balmumlarının fitiline kurşun tel örülerek tartıda ağır gelmesinin sağlandığı ortaya çıktı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Fitil imalathanelerini bastır; hileli fitilleri yaktırıp saf pamuk fitil mecburiyeti koy.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Mumlar zehirsiz ve temiz yandı; tartı hırsızlığı kesildi."},{"label":"Mumcu esnafı zordadır; fitiline çok dikkat etmeyin.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Mumcuların İplerine Ağır Kurşun İp Katması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Mumcuların İplerine Ağır Kurşun İp Katması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Mumcuların İplerine Ağır Kurşun İp Katması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 653) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_654', 'ottoman', 'Keten Tohumu Yağının Yemeklik Diye Satılması', 'Yağ Kapanı Kâhyalığı', 'Sadece boya ve kandilde kullanılan acı keten tohumu yağının fıçıları değiştirilerek ayçiçek yağı diye satıldığı ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütün fıçıları mühürletip tahlil ettir; acı yağı boyacılara devret, satan tüccarı cezalandır.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Zehirlenme tehlikesi önlendi; halk yemeklik yağı güvenle aldı."},{"label":"Halk tadından anlar; almasınlar de.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Keten Tohumu Yağının Yemeklik Diye Satılması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Keten Tohumu Yağının Yemeklik Diye Satılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Keten Tohumu Yağının Yemeklik Diye Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 654) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_655', 'ottoman', 'Cizye Defterlerinde Ölülerin Silinmemesi', 'Maliye Kalemi', 'Tahsildarların gayrimüslim köylerde on yıl önce ölmüş kişilerin vergisini hala köy cemaatinden zorla tahsil ettiği belgelendi.', '[{"id":"char_tahsildar","name":"Vergi Tahsildarı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Cizye defterlerini köy papazlarıyla baştan yazdır; ölülerin borcunu sil ve tahsildarları azlet.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Zulüm durduruldu; gayrimüslim tebaa padişahın adaletine sığındı."},{"label":"Köyün maktu vergisidir; ölenin yerine yaşayan ödesin.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Cizye Defterlerinde Ölülerin Silinmemesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Cizye Defterlerinde Ölülerin Silinmemesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Cizye Defterlerinde Ölülerin Silinmemesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 655) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_656', 'ottoman', 'Etlerin Suya Basılarak Şişirilmesi', 'İstanbul Kasapları', 'Kasapların kesilen koyun karkaslarını sabaha kadar suda bekleterek ağırlığını üçte bir artırdığı görüldü.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Etlerin asılarak kurutulmasını mecburi kıl; suya et basan kasabın dükkânını üç ay mühürle.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Sulu et hilesi bitti; halk ödediği paranın tam karşılığı kuru et aldı."},{"label":"Et tazedir, su çeker; kasapları çok sıkıştırmayın.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Etlerin Suya Basılarak Şişirilmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Etlerin Suya Basılarak Şişirilmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Etlerin Suya Basılarak Şişirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 656) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_657', 'ottoman', 'Gümüş Cürufundan Yeniden Maden Çıkarma', 'Darbhane-i Âmire', 'Eski darphane küllerinde ve cüruflarında kalan ince gümüşün kimyevi suyla ayrıştırılması teklif edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Ayrıştırma ocaklarını kurdur; çöpe atılan küllerden hazineye yılda yüzlerce kilo gümüş kazandır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Atıklar servete dönüştü; darphane bütçesi beklenmedik gelirle doldu."},{"label":"Külle toprakla uğraşmayın; masrafını çıkarmaz.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Gümüş Cürufundan Yeniden Maden Çıkarma nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Gümüş Cürufundan Yeniden Maden Çıkarma fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Gümüş Cürufundan Yeniden Maden Çıkarma meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 657) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_658', 'ottoman', 'Tahta Fıçıların Kalın Yapılarak Balın Eksik Tartılması', 'Balkapanı', 'Bal tüccarlarının darayı şişirmek için fıçıların tabanını üç parmak kalın meşeden yaptırdığı anlaşıldı.', '[{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Dara nizamı koy: Fıçıyı ayrı, balı ayrı tarttır; hileli fıçı kullanan tüccara ceza kes.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Dara hilesi bitti; alıcı balın saf ağırlığını teslim aldı."},{"label":"Fıçı sağlam olmalıdır; daraya çok bakmayın.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahta Fıçıların Kalın Yapılarak Balın Eksik Tartılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Tahta Fıçıların Kalın Yapılarak Balın Eksik Tartılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Tahta Fıçıların Kalın Yapılarak Balın Eksik Tartılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 658) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_659', 'ottoman', 'Kaya Tuzlarının Islatılarak Ağırlığının Artırılması', 'Tuz Kapanı Kâtipliği', 'Tuz tüccarlarının kapana girmeden önce tuz bloklarına hortumla su sıkarak suyu emdirdiği belgelendi.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Islak tuzu kapana sokma; kuru blok ağırlığını şart koş ve hilecileri men et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Tuz eriyip akmaktan kurtuldu; esnaf sağlam tuz aldı."},{"label":"Tuz nemi sever; piyasayı tuzsuz bırakmayın de.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kaya Tuzlarının Islatılarak Ağırlığının Artırılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kaya Tuzlarının Islatılarak Ağırlığının Artırılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kaya Tuzlarının Islatılarak Ağırlığının Artırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 659) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_660', 'ottoman', 'İhtisap Ağalığı Kanunnamesinin Tazelenmesi', 'Dîvân-ı Hümâyûn', 'Tüm çarşı, pazar ve kapan teftişlerini rüşvetsiz, tarafsız ve adil kılacak büyük İhtisap Kanunu hazırlandı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Kanunu yürürlüğe koy: \'Çarşıda adaleti kurmayan, devlette nizamı kuramaz!\'.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Piyasa güvenceye alındı; hile ve karaborsa tarihe karıştı."},{"label":"Serbest piyasadır; çok kanunla esnafı bunaltmayın.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve İhtisap Ağalığı Kanunnamesinin Tazelenmesi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve İhtisap Ağalığı Kanunnamesinin Tazelenmesi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve İhtisap Ağalığı Kanunnamesinin Tazelenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 660) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_661', 'ottoman', 'Kale Surlarındaki Top Yuvalarının Genişletilmesi', 'Kamaniçe Kalesi', 'Eski top yuvalarının dar olduğu, dumanın içeri dolup topçuları boğduğu; mazgalların genişletilmesi gerektiği bildirildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"İstihkâm neferlerini görevlendir; top mazgallarına duman bacaları ve geniş açılı siperler açtır.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Topçular dumandan boğulmadan seri atış yaptı; kale savunması güçlendi."},{"label":"Mazgalları ellemeyin; genişlerse düşman mermisi içeri girer.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Kale Surlarındaki Top Yuvalarının Genişletilmesi hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Kale Surlarındaki Top Yuvalarının Genişletilmesi hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Kale Surlarındaki Top Yuvalarının Genişletilmesi gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 661) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_662', 'ottoman', 'Kılıç Kabzalarında Kurşun Yerine Ahşap Kullanımı', 'Cebeci Kışlaları', 'Cebecilerin ağırlık dengesi sağlayan kurşun kabzaları çalıp yerine çürük tahta taktığı, kılıçların savururken elden fırladığı görüldü.', '[{"id":"char_cebecibasi","name":"Cebecibaşı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Cebecibaşıyı derhal azlet; bütün kılıç kabzalarını kurşunla dengeletip sağlam deriyle sardır.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Kılıçlar mükemmel dengeye kavuştu; neferlerin vuruş gücü arttı."},{"label":"Asker kılıcı sıkı tutsun; tahta kabza da idare eder.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Kılıç Kabzalarında Kurşun Yerine Ahşap Kullanımı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Kılıç Kabzalarında Kurşun Yerine Ahşap Kullanımı fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kılıç Kabzalarında Kurşun Yerine Ahşap Kullanımı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 662) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_663', 'ottoman', 'Kalyon Dümenlerinin Demir Millerinin Kırılması', 'Tersane-i Âmire', 'Açık deniz dalgalarına dayanamayan dökme demir dümen millerinin fırtınada koptuğu ve gemilerin sürüklendiği bildirildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Dövme çelikten esnek ve kalın dümen milleri döktür; kalyonların dümensiz kalmasını önle.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Kalyonlar en azgın fırtınalarda dahi rotasını milim şaşmadan korudu."},{"label":"Yedek tahta dümenlerle idare etsinler; çelik pahalıdır.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Kalyon Dümenlerinin Demir Millerinin Kırılması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Kalyon Dümenlerinin Demir Millerinin Kırılması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyon Dümenlerinin Demir Millerinin Kırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 663) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_664', 'ottoman', 'Kaledeki Okçu Tabyalarının Tüfekli Siperlere Çevrilmesi', 'Bağdat Hududu', 'Safevi tüfekçilerine karşı eski yay ve ok mazgallarının işlevsiz kaldığı, siperlerin tüfek boyuna indirilmesi istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Surları derhal modern tüfek siperleriyle donat ve kum torbası bataryaları yerleştir.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Hudut kaleleri tüfek ateşiyle düşmanı menzile sokmadı."},{"label":"Tarihi surlara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın; okçularımız mahirdir.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Kaledeki Okçu Tabyalarının Tüfekli Siperlere Çevrilmesi hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Kaledeki Okçu Tabyalarının Tüfekli Siperlere Çevrilmesi hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Kaledeki Okçu Tabyalarının Tüfekli Siperlere Çevrilmesi gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 664) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_665', 'ottoman', 'Kuşatma Sırasında Kale Fırınlarının Yanması', 'Belgrad Garnizonu', 'Avusturya havan topunun kale fırınına isabet etmesiyle fırın çöktü; asker ekmeksiz peksimete kaldı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Surlar altındaki tonozlu dehlizlerde yeraltı fırınları kurdur; sıcak ekmek sevkiyatını aksatma.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Asker sıcak ekmeğe kavuştu; kuşatmaya karşı direnç şahlandı."},{"label":"Kuru peksimet kemirsinler; savaşta sıcak ekmek aranmaz.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Kuşatma Sırasında Kale Fırınlarının Yanması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Kuşatma Sırasında Kale Fırınlarının Yanması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kuşatma Sırasında Kale Fırınlarının Yanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 665) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_666', 'ottoman', 'Havan Toplarının Açı Ayar Cetvelleri', 'Tophane Dökümhanesi', 'Aşırtma atış yapan havan toplarının mesafe cetvellerinin kaybolduğu, güllelerin kendi mevzilerimize düştüğü bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mühendishane hocalarına yeni hendese cetvelleri hazırlat; topçu çavuşlarına zorunlu talim yaptır.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Havan atışları düşman siperlerinin tam göbeğine indi."},{"label":"Göz kararı atsınlar; tecrübeli topçu cetvele bakmaz.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Havan Toplarının Açı Ayar Cetvelleri nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Havan Toplarının Açı Ayar Cetvelleri fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Havan Toplarının Açı Ayar Cetvelleri meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 666) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_667', 'ottoman', 'Sarnıç Sularına Kurt Düşmesi', 'Rodos Kalesi', 'Kaledeki devasa sarnıçların üstü açık kaldığı için sular kurtlandı; garnizon neferleri karın ağrısından yığıldı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sarnıçları boşaltıp kireçle dezenfekte ettir; üstlerine kurşun kapaklar ve kömür filtreler yaptır.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Garnizon pırıl pırıl suya kavuştu; salgın hastalık durduruldu."},{"label":"Suyu kaynatıp içsinler; sarnıç kapağına para harcanmaz.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Sarnıç Sularına Kurt Düşmesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Sarnıç Sularına Kurt Düşmesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Sarnıç Sularına Kurt Düşmesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 667) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_668', 'ottoman', 'Kalyon Bordalarına Demir Levha Zırh Takılması', 'Tersane-i Âmire', 'Düşman güllelerinin ahşap bordaları parçalamasını önlemek için su kesimine dövme demir plakalar takılması teklif edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"İlk zırhlı kalyon tecrübesini başlat; gemi bordalarını dövme demir kuşakla kaplat.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Düşman gülleleri bordadan sekti; deniz savaşında efsanevi üstünlük sağlandı."},{"label":"Gemi ağırlaşır ve batar; ahşap gövdeden şaşmayın.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kalyon Bordalarına Demir Levha Zırh Takılması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kalyon Bordalarına Demir Levha Zırh Takılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kalyon Bordalarına Demir Levha Zırh Takılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 668) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_669', 'ottoman', 'Sınır Palankalarının Kışın Karlar Altında Kalması', 'Kars Hududu', 'Uç beylerinin palankaları çığ tehlikesi altında; ahşap kulelerin taş temellerle güçlendirilmesi gerekiyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"İstihkâm neferlerini gönder; palanka etrafına çığ kırıcı taş setler ördür.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Palankalar kardan ve çığdan korundu; serhad nöbeti kesilmedi."},{"label":"Kışın askerleri geri çekin; baharda palankayı yeniden kurarsınız.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Sınır Palankalarının Kışın Karlar Altında Kalması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Sınır Palankalarının Kışın Karlar Altında Kalması fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Sınır Palankalarının Kışın Karlar Altında Kalması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 669) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_670', 'ottoman', 'Siper Kazarken Çıkan Yeraltı Suyu', 'Uyvar Kuşatması', 'Kuşatma tünellerini taban suyu bastı; lağımcı neferleri su içinde kazma sallayamıyor.', '[{"id":"char_humbaracibasi","name":"Humbaracıbaşı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Tersaneden tulumbacılar ve deri su tahliye boruları sevk et; siperleri kurut.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Tüneller kurutuldu; lağım düşman burcunun altına başarıyla sürüldü."},{"label":"Tüneli bırakın; açık meydandan süvariyle hücum edin.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Siper Kazarken Çıkan Yeraltı Suyu meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Siper Kazarken Çıkan Yeraltı Suyu hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Siper Kazarken Çıkan Yeraltı Suyu gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 670) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_671', 'ottoman', 'Baruthanede Kıvılcım Çıkaran Nal Yasağı', 'Baruthane-i Âmire', 'Barut depolarına giren katırların nallarının taşa çarpıp kıvılcım çıkardığı, patlama tehlikesi olduğu bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Depo zeminlerini kalın tahtayla kaplat, içeri giren hayvanlara ve neferlere keçe patik giydir.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Büyük facia önlendi; baruthane mutlak emniyete kavuştu."},{"label":"Asırlardır böyle taşınıyor; bir şey olmaz.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Baruthanede Kıvılcım Çıkaran Nal Yasağı nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Baruthanede Kıvılcım Çıkaran Nal Yasağı fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Baruthanede Kıvılcım Çıkaran Nal Yasağı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 671) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_672', 'ottoman', 'Top Namlularının Soğutulmasında Sirke Kullanımı', 'Van Kalesi', 'Sürekli ateşlenen bronz topların aşırı ısınıp eğrildiği; sirkeyle soğutulması için sirke fıçıları istendi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kalenin kilerine fıçılarla keskin sirke yığdır; namluların ömrünü koru.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Toplar eğrilmeden akşama kadar aralıksız gülle kustu."},{"label":"Suyla soğutun; sirkeye para harcanmaz.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Top Namlularının Soğutulmasında Sirke Kullanımı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Top Namlularının Soğutulmasında Sirke Kullanımı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Top Namlularının Soğutulmasında Sirke Kullanımı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 672) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_673', 'ottoman', 'Esir Cerrahların Kalyon Revirlerinde Hizmeti', 'Tersane Zindanı', 'Tutsak İspanyol cerrahların, azat edilme vaadiyle kalyon revirlerinde leventlerin yaralarını sarması teklif edildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Anlaşmayı yap: Başarılı olan cerrahı sefer dönüşü hürriyetine kavuştur ve leventleri tedavi ettir.","preview":"Adalet +8, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":8,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Yaralı leventler kangrenden kurtuldu; söz tutulup adalet gösterildi."},{"label":"Düşman hekime can teslim edilmez; forsaya devam etsinler.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Esir Cerrahların Kalyon Revirlerinde Hizmeti hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Esir Cerrahların Kalyon Revirlerinde Hizmeti hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Esir Cerrahların Kalyon Revirlerinde Hizmeti gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 673) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_674', 'ottoman', 'Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması', 'Sinop Tersanesi', 'Depodaki çam direklerinin böceklenmemesi için hususi sıcak katran kuyularına daldırılması gerekti.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Katran kuyularını hazırlat; direkleri usulünce katranlayıp kurtlanmaktan kurtar.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Direkler taş gibi sertleşti; fırtınada tek bir yelken direği kırılmadı."},{"label":"Direkler kurudur, kurda bir şey yapmaz deyip kuyuları kazdırma.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 674) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_675', 'ottoman', 'Tüfek Namlularına Pas Önleyici Beziryağı', 'Cebeci Kışlaları', 'Rutubetli kışlalarda paslanan tüfeklerin temizlenmesi için beziryağı ve keçe tahsisatı istendi.', '[{"id":"char_cebecibasi","name":"Cebecibaşı"}]', '[{"label":"Tahsisi derhal yap; her mangaya tüfek bakım sandığı ve beziryağı dağıt.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Tüfekler pırıl pırıl parladı; atış anında tutukluk yapmadı."},{"label":"Asker kendi yağıyla temizlesin; hazineden beziryağı çıkmaz.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Tüfek Namlularına Pas Önleyici Beziryağı nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Tüfek Namlularına Pas Önleyici Beziryağı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Tüfek Namlularına Pas Önleyici Beziryağı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 675) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_676', 'ottoman', 'Gece Baskınlarını Önleyen Çıra Meşaleleri', 'Hotin Kuşatması', 'Düşman süvarisinin gece karanlığında hendeklere sızmasını önlemek için sur diplerinde katranlı çıra varilleri yakılması önerildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Varilleri dizdir ve gece nöbetçilerine aydınlatma ateşi yaktır.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Gece baskını aydınlıkta fark edildi; düşman hendeklerde imha edildi."},{"label":"Katran pahalıdır; karanlıkta gözlerini açıp beklesinler.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gece Baskınlarını Önleyen Çıra Meşaleleri meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gece Baskınlarını Önleyen Çıra Meşaleleri meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gece Baskınlarını Önleyen Çıra Meşaleleri gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 676) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_677', 'ottoman', 'Top Dökümünde Kurşun Yerine Kalay Karışımı', 'Tophane Dökümhanesi', 'Bakırı sertleştiren pahalı kalay yerine ucuz kurşun koyan dökümcülerin topları çatlatmaya sebep olduğu belgelendi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Dökümcüleri teftiş et; standart dışı bronz dökeni fırıncı ocaklarına sür ve saf kalay kullan.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Toplar çelik gibi sert döküldü; binlerce gülle atıp çatlamadı."},{"label":"Kalay çok pahalıdır; kurşun karışımı idare etsin.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Top Dökümünde Kurşun Yerine Kalay Karışımı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Top Dökümünde Kurşun Yerine Kalay Karışımı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Top Dökümünde Kurşun Yerine Kalay Karışımı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 677) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_678', 'ottoman', 'Kale Kapılarının Arkasına Demir Kirişler', 'Kamaniçe Kalesi', 'Koçbaşlarıyla kapıların kırılmasını önlemek için meşe kapıların arkasına dövme demir sürgüler takılması istendi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Samakov\'dan kalın demir kirişler getirt; kale kapılarını zırhla tahkim et.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Koçbaşları demir kapıya çarpıp kırıldı; kale kapısı düşmedi."},{"label":"Tahta sürgüler yeterlidir; masrafa gerek yok.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Kale Kapılarının Arkasına Demir Kirişler nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Kale Kapılarının Arkasına Demir Kirişler fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kale Kapılarının Arkasına Demir Kirişler meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 678) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_679', 'ottoman', 'Kalyonların Yelken Makarasında Şimşir Ağacı', 'Tersane-i Âmire', 'Halatların sürtünmeden kopmaması için yelken makaralarının sert Karadeniz şimşirinden oyulması gerekti.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Şimşir tomrukları getirt; makaraları pürüzsüz şimşir ağacından oydur.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Yelkenler rüzgâr gibi açıldı; halatlar sürtünmeden aşınmadı."},{"label":"Kavak ağacından oyun; şimşir çok serttir, ustayı yorar.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalyonların Yelken Makarasında Şimşir Ağacı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Kalyonların Yelken Makarasında Şimşir Ağacı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Kalyonların Yelken Makarasında Şimşir Ağacı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 679) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_680', 'ottoman', 'Cephanelik ve Baruthane Nizamnamesi', 'Dîvân-ı Hümâyûn', 'İmparatorluktaki tüm kale ve tersanelerin mühimmatını kayıt altına alan, hırsızlık ve ihmali idamla cezalandıran kanunname hazırlandı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Kanunnameyi mühürle: \'Cephane ordunun can damarıdır, tek gülle dahi sahipsiz kalamaz!\'.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Askeri levazım çelik disipline bağlandı; ordumuz her daim savaşa hazır oldu."},{"label":"Her kale kendi dizdarına emanettir; merkezi deftere lüzum yok.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Cephanelik ve Baruthane Nizamnamesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Cephanelik ve Baruthane Nizamnamesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Cephanelik ve Baruthane Nizamnamesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 680) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_681', 'ottoman', 'Vezirlerin Mazlumun Şikâyetini Gizlemesi', 'Nizamülmülk\'ün Vasiyeti', 'Siyasetnâme uyarınca: \'Padişah haftada iki gün bizzat halkın dertlerini dinlemezse, saray duvarları zulmün zindanı olur\' hakikati hatırlatıldı.', '[{"id":"char_nizamulmulk","name":"Nizamülmülk"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Haftada iki gün Bâbüssaâde önüne taht kurdur; hiçbir perde olmadan her köylüyü bizzat dinle.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Vezirlerin rüşvet duvarı yıkıldı; mazlumların duası tahtı arşa yükseltti."},{"label":"Padişahın işi çoktur; köylüyle doğrudan muhatap olmak saltanatı küçültür.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Vezirlerin Mazlumun Şikâyetini Gizlemesi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Vezirlerin Mazlumun Şikâyetini Gizlemesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Vezirlerin Mazlumun Şikâyetini Gizlemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 681) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_682', 'ottoman', 'Sanayi İnkılabı ve Buharlı Dokuma Tezgâhları', 'Londra Sefaretnâmesi', 'İngiltere\'den dönen sefir, kömürle çalışan dokuma fabrikalarının dünyayı fethedeceğini yazan hayret verici bir layiha sundu.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Layihayı derhal incelet; Haliç kıyısında ilk buharlı dokuma fabrikasının temelini attır.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Osmanlı sanayileşme hamlesini başlattı; İngiliz kumaşına muhtaç kalınmadı."},{"label":"Kömür dumanı şehri kirletir; el tezgâhlarımız kâfidir deyip layihayı rafa kaldır.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Sanayi İnkılabı ve Buharlı Dokuma Tezgâhları hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Sanayi İnkılabı ve Buharlı Dokuma Tezgâhları hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Sanayi İnkılabı ve Buharlı Dokuma Tezgâhları gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 682) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_683', 'ottoman', 'Haksız İdam Edilen Mazlumun Terekesi', 'Şeyhülislamlık', 'Önceki zalim bir vezirin iftirasıyla idam edilen dürüst bir tüccarın varisleri, müsadere edilen mallarının iadesini niyaz ediyor.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Malları kuruşu kuruşuna varislere iade et, devlet adına özür dile ve tüccara mezar yaptır.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Gasp edilen hak sahibine döndü; devletin helallik alması adaleti şahlandırdı."},{"label":"Hazineye giren mal geri çıkmaz; devletin prestijini sarsıp yanlış yaptığını kabul etmeyin.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Haksız İdam Edilen Mazlumun Terekesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Haksız İdam Edilen Mazlumun Terekesi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Haksız İdam Edilen Mazlumun Terekesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 683) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_684', 'ottoman', 'Saray Dalkavuklarının Maaşlarının Kesilmesi', 'Bab-ı Âli', 'Hazine darlığında, sarayda hiçbir vazifesi olmadan padişaha medhiyeler düzüp aylık alan asalakların maaşları tartışıldı.', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Dalkavukların tamamını saraydan kov; maaşlarını sınır kalelerindeki topçulara tahsis et.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Asalaklar temizlendi; hükümdarın etrafını dürüst ilim adamları sardı."},{"label":"Sultanın neşesi mühimdir; dalkavukların maaşını kesmeyin.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Saray Dalkavuklarının Maaşlarının Kesilmesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Saray Dalkavuklarının Maaşlarının Kesilmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Saray Dalkavuklarının Maaşlarının Kesilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 684) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_685', 'ottoman', 'Tarih ve Coğrafya Derslerinin Zorunlu Kılınması', 'Enderun Mektebi', 'Mektepte sadece hüsn-i hat ve güreş öğretildiği, devlet idare edecek gençlerin dünya coğrafyası ve harp tarihinden habersiz yetiştiği bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Müfredatı yenile: İbn Haldun\'un Mukaddime\'sini ve Katip Çelebi\'nin Cihannümâ\'sını mecburi kıl.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Dünyayı tanıyan, tarihten ibret alan şuurlu devlet adamları yetişti."},{"label":"Eski usul hüsn-i hat kafidir; felsefe kafalarını karıştırır.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Tarih ve Coğrafya Derslerinin Zorunlu Kılınması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Tarih ve Coğrafya Derslerinin Zorunlu Kılınması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Tarih ve Coğrafya Derslerinin Zorunlu Kılınması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 685) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_686', 'ottoman', 'Daimi Askeri Talim ve Kışla Nizamı', 'Viyana Sefaretnâmesi', 'Sefir Ebubekir Ratıp Efendi, Avrupa ordularının her gün saatlerce kurşun atıp hendek kazdığını, bizim askerimizin talimsiz kaldığını yazdı.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Yeniçeriye her gün tüfek atışı ve fenni manevra mecburiyeti koy; uymayanı ocaktan sil.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Ordunun muharebe kabiliyeti şahlandı; hedefler tam isabetle vuruldu."},{"label":"Asker talimden hoşlanmaz, isyan eder; zorlamayın.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Daimi Askeri Talim ve Kışla Nizamı nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Daimi Askeri Talim ve Kışla Nizamı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Daimi Askeri Talim ve Kışla Nizamı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 686) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_687', 'ottoman', 'Kadı Kararlarına Karşı Temyiz Meclisi (Divan-ı Ahkâm)', 'Divan Mezalim Dairesi', 'Taşradaki kadıların yanlış ve taraflı hükümlerini inceleyecek payitahtta bağımsız bir Yüksek Temyiz Meclisi kurulması teklif edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Divan-ı Ahkâm-ı Adliyye\'yi kur; haksızlığa uğrayan her vatandaşın davasını yeniden gördür.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Yargıda çift dikiş teminat kuruldu; kadıların keyfiliği tarihe gömüldü."},{"label":"Kadının hükmü bozulursa mahkemenin kerameti kalmaz; temyizi reddet.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Kadı Kararlarına Karşı Temyiz Meclisi (Divan-ı Ahkâm) nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Kadı Kararlarına Karşı Temyiz Meclisi (Divan-ı Ahkâm) fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kadı Kararlarına Karşı Temyiz Meclisi (Divan-ı Ahkâm) meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 687) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_688', 'ottoman', 'Müslüman Olmayan Tebaanın Devlet Memuriyeti', 'Şeyhülislam Kapısı', 'Mühendislik, tabiplik ve tercümanlık gibi teknik sahalarda liyakatli gayrimüslim tebaanın doğrudan memuriyete alınması istendi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Liyakat ehliyetledir: Vatanına sadık her yetenekli ferdi uzmanlık sahasında istihdam et.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Devlet en parlak beyinleri kazandı; ayrımcılık bitti, birlik sağlandı."},{"label":"Devlet memuriyeti sadece Müslümanın hakkıdır; teknik iş olsa da almayın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Müslüman Olmayan Tebaanın Devlet Memuriyeti meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Müslüman Olmayan Tebaanın Devlet Memuriyeti meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Müslüman Olmayan Tebaanın Devlet Memuriyeti gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 688) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_689', 'ottoman', 'Padişahın Kendi Servetini Beyan Etmesi', 'Bab-ı Âli İstişare Meclisi', 'Şeffaflık nizamı gereği, hükümdarın Ceb-i Hümayun\'undaki altınları ve mülkleri divan defterine yazdırması teklif edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Örnek ol: Tüm şahsi servetini deftere işlet ve fazlasını yetim ve gazi sandıklarına bağışla.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Padişahın büyüklüğü tarihe kazındı; hiçbir vezir mal gizlemeye cüret edemedi."},{"label":"Padişahın serveti sorgulanamaz; teklifi getiren kâtibi sürgüne yolla.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Padişahın Kendi Servetini Beyan Etmesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Padişahın Kendi Servetini Beyan Etmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Padişahın Kendi Servetini Beyan Etmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 689) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_690', 'ottoman', 'Tarihi Elmas ve Mücevherlerin Satılarak Donanmaya Verilmesi', 'Topkapı Hazine Odası', 'Düşman donanması Boğaz\'ı tehdit ederken saray hazinesindeki süs elmaslarının satılıp kalyon yapılması teklif edildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Elmasları sat! \'Vatan tehlikedeyken taşın süsüne bakılmaz, mülk demirle korunur!\'.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Satılan mücevherlerle kalyonlar inşa edildi; düşman donanması denize gömüldü."},{"label":"Ecdat yadigârı süslerdir; tek bir elmasa dahi dokundurtmam.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Tarihi Elmas ve Mücevherlerin Satılarak Donanmaya Verilmesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Tarihi Elmas ve Mücevherlerin Satılarak Donanmaya Verilmesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Tarihi Elmas ve Mücevherlerin Satılarak Donanmaya Verilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 690) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_691', 'ottoman', 'İbn Rüşd ve Fârâbî Eserlerinin Arapça ve Türkçeye Tercümesi', 'Süleymaniye Kütüphanesi', 'Endülüs ve Şark felsefesinin akli ilimler külliyatının yeni baskılarla medreselerde ders kitabı yapılması istendi.', '[{"id":"char_farabi","name":"Fârâbî"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Tercüme heyetini kurdur; aklı vahiy ile meczeden büyük felsefe mektebini ihya et.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"İslam medeniyetinin fikri tıkanıklığı aşıldı; medreselere canlılık geldi."},{"label":"Felsefe imanı bozar deyip kitapları depolara kilitleyin.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İbn Rüşd ve Fârâbî Eserlerinin Arapça ve Türkçeye Tercümesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İbn Rüşd ve Fârâbî Eserlerinin Arapça ve Türkçeye Tercümesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İbn Rüşd ve Fârâbî Eserlerinin Arapça ve Türkçeye Tercümesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 691) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_692', 'ottoman', 'Rüşvet Alan Paşanın Mezar Taşındaki İltifatların Silinmesi', 'Bab-ı Âli', 'Zulmüyle maruf eski bir sadrazamın kabir taşına \'Âdil ve mütteki\' yazıldığı; halkın taşı taşladığı bildirildi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Taştaki yalan övgüleri kazıt: \'Zalimin mezarına bile yalan yazılamaz; hakikat neyse o yazılsın!\'.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Tarihin hafızası temizlendi; yaşayan paşalar mezar taşından dahi ibret aldı."},{"label":"Ölünün arkasından konuşulmaz; mezar taşını muhafaza edin.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Rüşvet Alan Paşanın Mezar Taşındaki İltifatların Silinmesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Rüşvet Alan Paşanın Mezar Taşındaki İltifatların Silinmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Rüşvet Alan Paşanın Mezar Taşındaki İltifatların Silinmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 692) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_693', 'ottoman', 'Yabancı Elçilerin Sarayda Diz Çökme Protokolü', 'Hariciye Nezareti', 'Avrupa elçilerinin huzura çıkarken kılıçlarını bırakıp diz çökme kuralına itiraz ettiği ve eşit protokol istediği bildirildi.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Milli vakarından taviz verme: \'Cihan padişahının huzuruna edeple girilir!\' Protokolü aynen uygula.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Devletin azameti korundu; elçiler boyun eğerek huzura girdi."},{"label":"Avrupa\'nın istediği serbest protokolü kabul edin.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Yabancı Elçilerin Sarayda Diz Çökme Protokolü nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Yabancı Elçilerin Sarayda Diz Çökme Protokolü fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Yabancı Elçilerin Sarayda Diz Çökme Protokolü meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 693) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_694', 'ottoman', 'Kadınların Ticaret ve Mülk Edinme Hürriyeti', 'Şeyhülislamlık', 'Bazı taşra hâkimlerinin kadınların kendi namlarına dükkân açmasını ve kervan işletmesini yasaklamaya kalkıştığı öğrenildi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Hz. Hatice\'nin ticaret sünnetini hatırlat: Kadınların ticaret ve mülk hakkına dokunan kadıyı azlet.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Kadınların iktisadi hakları korundu; piyasa yüz binlerce üreticiyle canlandı."},{"label":"Kadınlar evinde otursun; kadının kararına müdahale etmeyin.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadınların Ticaret ve Mülk Edinme Hürriyeti sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Kadınların Ticaret ve Mülk Edinme Hürriyeti meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Kadınların Ticaret ve Mülk Edinme Hürriyeti gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 694) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_695', 'ottoman', 'Vergi Memurunun Köylünün Kızına Göz Koyması', 'Divan Mezalim Dairesi', 'Vergi borcunu bahane eden ahlaksız bir muhassılın, köylünün kızını zorla kendine nikâhlamaya kalkıştığı feryatla duyuruldu.', '[{"id":"char_vergi_muhassili","name":"Vergi Muhassılı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Zorba tahsildarı derhal yakalatıp köy meydanında as; mazlum ailenin hakkını devlet kılıcıyla koru.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Zulüm kılıçla kesildi; halk adil padişaha canını feda edecek muhabbetle bağlandı."},{"label":"Meseleyi büyütmeyin; aralarında başlık parasıyla anlaştırın.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Vergi Memurunun Köylünün Kızına Göz Koyması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Vergi Memurunun Köylünün Kızına Göz Koyması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Vergi Memurunun Köylünün Kızına Göz Koyması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 695) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_696', 'ottoman', 'Anayasa (Kanun-ı Esasî) Meclisi\'nin Daimi Açılması', 'Bab-ı Âli İstişare Meclisi', 'Padişahın yetkilerini millet meclisiyle paylaşan, hesap sorulabilir ve kanun üstünlüğüne dayalı Meclis-i Vükelâ teklif edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'İşlerini meşveretle yürütürler\' ilkesine sarıl; Meclis\'i aç ve adaleti ebedi kanuna bağla.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Hukuk devleti kemale erdi; padişah ile millet aynı gaye etrafında kenetlendi."},{"label":"Padişah mutlak efendidir; hiçbir meclise hesap vermez deyip teklifi yırt.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Anayasa (Kanun-ı Esasî) Meclisi\'nin Daimi Açılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Anayasa (Kanun-ı Esasî) Meclisi\'nin Daimi Açılması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Anayasa (Kanun-ı Esasî) Meclisi\'nin Daimi Açılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 696) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_697', 'ottoman', 'Hazret-i Peygamber\'in Adalet Hırkası', 'Topkapı Sarayı Mukaddes Emanetler', 'Hırka-i Şerif ziyaretinde ulema hatırlatır: \'Bu hırkayı giyen omuz, sırtında mülkün bütün mazlumlarının vebalini taşır!\'', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Gözyaşlarıyla tövbe et: \'Rabbim! Beni adaletten bir zerre saptırma, mazluma kalkan kıl!\'.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Hükümdar manevi sorumluluğun idrakine erdi; saray tevazu ve adalet nuruyla doldu."},{"label":"Hırka saltanatın mülküdür deyip kibirle kuşan.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazret-i Peygamber\'in Adalet Hırkası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Hazret-i Peygamber\'in Adalet Hırkası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Hazret-i Peygamber\'in Adalet Hırkası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 697) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_698', 'ottoman', 'Tarihin Nihai İmtihanı: Çember mi, Kılıç mı?', 'İbn Haldun ve Kınalızâde Meclisi', 'Yedi yüz yıllık devlet tecrübesi divana toplanır: \'Ey Sultan! Devleti ayakta tutan asıl sütun nedir?\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"\'Adalet olmadan reaya yaşamaz, reaya olmadan hazine dolmaz, hazine olmadan ordu beslenmez, ordu olmadan devlet kalmaz!\'.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Sistemik hakikat idrak edildi; Dâire-i Adliyye cihanşümul nizamın kalbi oldu."},{"label":"\'Ordu ve kılıç her şeydir; gerisi boştur.\'.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Tarihin Nihai İmtihanı: Çember mi, Kılıç mı? nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Tarihin Nihai İmtihanı: Çember mi, Kılıç mı? fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Tarihin Nihai İmtihanı: Çember mi, Kılıç mı? meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 698) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_699', 'ottoman', 'Dâire-i Adliyye\'nin Mühürlenişi', 'Kınalızâde Ali Çelebi\'nin Son Beyti', 'Ahlâk-ı Alâî son fermanını verir: Adalet bir çemberdir; neresinden kırarsan kır, kırılan halka senin boynuna dolanır!', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"}]', '[{"label":"ÇEMBERİ MÜHÜRLE: \'ADL İLE KÂİM OLAN MÜLK EBEDÎDİR!\'.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"Adalet çemberi ebediyete mühürlendi; cihan devleti zulmün karanlığını boğdu."},{"label":"Çemberi boz; kendi heva ve hevesinle hükmet.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Dâire-i Adliyye\'nin Mühürlenişi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Dâire-i Adliyye\'nin Mühürlenişi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Dâire-i Adliyye\'nin Mühürlenişi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 699) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_700', 'ottoman', 'Ebed-Müddet Devlet: İnsanı Yaşat ki Devlet Yaşasın!', 'Nizâm-ı Âlem Tacı', 'Yedi yüz vakalık büyük imtihan kemale erdi. Şeyh Edebali\'nin vasiyeti, Kınalızâde\'nin çemberi ve Nizamülmülk\'ün siyaseti tek bir hakikatte birleşti.', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"MÜHRÜ BAS: \'ADALET MÜLKÜN TEMELİDİR, ZULÜM İSE MÜLKÜN ZEVALİDİR!\'.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Adalet çemberi cihanın nizamı oldu; mülk dünya durdukça yaşayacak bir kutba dönüştü."},{"label":"Kuvvet benimdir, dilediğimi ezerim.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ebed-Müddet Devlet: İnsanı Yaşat ki Devlet Yaşasın sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Ebed-Müddet Devlet: İnsanı Yaşat ki Devlet Yaşasın meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Ebed-Müddet Devlet: İnsanı Yaşat ki Devlet Yaşasın gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":9,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 700) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_701', 'ottoman', 'Tahrir Kâtibinin Verimli Çiftliği Çorak Göstermesi', 'Tahrir Defterhânesi', 'Amasya sancağında tahrir yapan kâtibin, yerel ayândan rüşvet alarak yüzlerce dönüm sulak bağı \'hâli ve çorak arazi\' diye kaydettiği ortaya çıktı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kâtibi azlet, defteri iptal et ve tarafsız bir heyetle araziyi yeniden hakiki kıymetiyle tescil ettir.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Vergi kaçakçılığı engellendi; tahrir kayıtlarına devlet ciddiyeti geri geldi."},{"label":"Yeni tahrir çok masraflıdır; mevcut defter kaydıyla idare edin.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Tahrir Kâtibinin Verimli Çiftliği Çorak Göstermesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Tahrir Kâtibinin Verimli Çiftliği Çorak Göstermesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Tahrir Kâtibinin Verimli Çiftliği Çorak Göstermesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 701) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_702', 'ottoman', 'Kadim Köy Merasının Çiftliğe Katılması', 'Kaza Sicili', 'Zengin bir mültezim, köylünün asırlardır hayvan otlattığı ortak merayı hendeklerle çevirip kendi şahsi çiftliğine kattı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_multezim","name":"İltizam Mültezimi"}]', '[{"label":"Hendekleri köylüye kapattır, meranın ortak kullanım hakkını kadı ilamıyla tasdikle.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Ortak mera köylüye iade edildi; hayvanlar açlıktan ve kırılmaktan kurtuldu."},{"label":"Mültezim devlete peşin vergi öder; köylüye başka dağları gösterin.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Kadim Köy Merasının Çiftliğe Katılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Kadim Köy Merasının Çiftliğe Katılması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kadim Köy Merasının Çiftliğe Katılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 702) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_703', 'ottoman', 'Sel Yüzünden Yeri Değişen Dere ve Tarla Sınırları', 'Bursa Kadılığı', 'Bahar taşkınında nehir yatağı kayınca iki köy arasında yüz dönümlük bereketli alüvyon arazisi için silahlı kavga çıktı.', '[{"id":"char_bursa_kadisi","name":"Bursa Kadısı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Mühendisler ve kadı ile eski sınır taşlarını kütük defterinden buldur; araziyi iki köye eşit bölüştür.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Kan davası önlendi; adil taksim iki köyü de memnun etti."},{"label":"Araziyi hazineye katıp iki tarafa da ekimi yasaklayın.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sel Yüzünden Yeri Değişen Dere ve Tarla Sınırları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Sel Yüzünden Yeri Değişen Dere ve Tarla Sınırları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Sel Yüzünden Yeri Değişen Dere ve Tarla Sınırları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 703) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_704', 'ottoman', 'Çift-Hâne Sisteminde Toprağın Parçalanması', 'Defterhâne-i Âmire', 'Vefat eden çiftçinin beş oğlu, babalarından kalan yekpare çiftlik arazisini bölüşüp cılız parçalara ayırmak istiyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kanun-ı Kadîm\'i uygula: Çiftlik bölünemez! Araziyi büyük oğula işlet, kardeşlerine payını nakden ödet.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Tarımsal üretim gücü parçalanmaktan kurtuldu; vergi tabanı korundu."},{"label":"Kardeşlerin rızasıdır; araziyi beş parçaya bölün.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Çift-Hâne Sisteminde Toprağın Parçalanması nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Çift-Hâne Sisteminde Toprağın Parçalanması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Çift-Hâne Sisteminde Toprağın Parçalanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 704) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_705', 'ottoman', 'Vakıf Ormanından Kaçak Kereste Kesen Tüccar', 'Kastamonu Teftişi', 'Bir kereste tüccarının, cami vakfına gelir sağlayan ulu meşeleri gece vakti kesip kalyon tersanesine el altından sattığı yakalandı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Tomruklara el koy, tüccarı küreğe mahkûm et ve kerestenin bedelini doğrudan vakfa aktar.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Vakıf hukuku korundu; orman talanına karşı sert bir ibret verildi."},{"label":"Tersaneye kereste lazımdır; tüccara cüzi bir ceza kesip keresteyi kabul edin.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gasp edilen zeytinlik ve dükkân gelirlerini geçmişe dönük faiziyle tahsil et; vakıf bütçesini mütevelli denetimine al ve Vakıf Ormanından Kaçak Kereste Kesen Tüccar nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hayrat ve vakıf malına el uzatan yerel ayânları saray çavuşlarıyla yakalat; gasbettikleri mülkleri zorla geri alıp kendilerini hapse at ve Vakıf Ormanından Kaçak Kereste Kesen Tüccar fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Vakıf Ormanından Kaçak Kereste Kesen Tüccar meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 705) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_706', 'ottoman', 'Haksız \'Çiftbozan\' Vergisi Dayatması', 'Taşra Maliyesi', 'Kuraklık yüzünden geçici olarak şehre ameleliğe giden çiftçilerden, tarlayı tamamen terk etmişler gibi fahiş çiftbozan akçesi istendi.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Zorla çiftbozan alınamaz! Köylüye dönüş izni ver, tohumluk hibe et ve tarlasına döndür.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Köylü toprağına sarıldı; ertesi yılın hasadı ikiye katlandı."},{"label":"Toprağını bırakan bedelini öder; parayı tahsil edin.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Haksız \'Çiftbozan\' Vergisi Dayatması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Haksız \'Çiftbozan\' Vergisi Dayatması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Haksız \'Çiftbozan\' Vergisi Dayatması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 706) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_707', 'ottoman', 'Zimmînin Bağını Zorla Almaya Kalkan Yeniçeri', 'Edirne Mahkemesi', 'Emekli bir yeniçeri zabiti, Rum bir bağcının asırlık bağına kılıç zoruyla yarı fiyat teklif edip tapuyu devretmesini dayatıyor.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Yeniçeriyi divan huzurunda tecziye et; zimmînin mülkiyet hüccetini devlet mührüyle tasdikle.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Mülkiyet emniyeti korundu; zimmî tebaa devletin adaletine sığındı."},{"label":"Gazi askerdir, gayrimüslime karşı hatırını kırmayın.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Zimmînin Bağını Zorla Almaya Kalkan Yeniçeri nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Zimmînin Bağını Zorla Almaya Kalkan Yeniçeri fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Zimmînin Bağını Zorla Almaya Kalkan Yeniçeri meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 707) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_708', 'ottoman', 'İki Türkmen Aşiretinin Yaylak Savaşı', 'Toros Yaylaları', 'Yaz sıcağında sürülerini Aladağ yaylasına çıkaran iki büyük aşiret, kadim yayla sınırları yüzünden çatışmaya girdi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tarafsız kadı ve süvari müfrezesi yolla; yaylayı pınarları iki tarafa eşit bölecek şekilde sınırla.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -1","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-1},"log":"Aşiretler arası kan davası önlendi; yaylaya sulh ve bereket geldi."},{"label":"Aşiretlerin iç işidir; kendi aralarında halletsinler.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve İki Türkmen Aşiretinin Yaylak Savaşı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve İki Türkmen Aşiretinin Yaylak Savaşı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve İki Türkmen Aşiretinin Yaylak Savaşı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 708) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_709', 'ottoman', 'Sahte Mühürle Satılan Mîrî Araziler', 'Sıvas Sancağı', 'Bir grup sahtekâr kâtibin, devlete ait boş arazileri padişah tuğrası taklit edilmiş sahte tapularla halka sattığı ihbar edildi.', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Sahtekâr şebekesini çökert, tuğra taklitçilerini as; aldatılan masum köylüye araziyi meşru kirala.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Devlet mührünün haysiyeti korundu; köylü meşru çiftçi yapıldı."},{"label":"Köylüleri araziden zorla sürün; tapuları sahtedir.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sahte Mühürle Satılan Mîrî Araziler hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Sahte Mühürle Satılan Mîrî Araziler hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Sahte Mühürle Satılan Mîrî Araziler gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 709) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_710', 'ottoman', 'Tımar Sahibinin Köylünün Saban Öküzünü Haczetmesi', 'Kaza Sicili', 'Vergisini geciktiren çiftçinin tek geçim kaynağı olan saban öküzünü sipahi beyi ahırdan çekip götürdü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"}]', '[{"label":"Kanun açıktır: Çiftçinin saban öküzü haczedilemez! Öküzü iade ettir, sipahiye ceza kes.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Üretim aracı korundu; çiftçi tarlasını sürerek borcunu ödedi."},{"label":"Sipahi askeri harçlık bekler; öküzü satıp borcunu kapatsın.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Tımar Sahibinin Köylünün Saban Öküzünü Haczetmesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Tımar Sahibinin Köylünün Saban Öküzünü Haczetmesi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Tımar Sahibinin Köylünün Saban Öküzünü Haczetmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 710) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_711', 'ottoman', 'Su Arkının Kendi Değirmenine Akıtılması', 'Konya Ovası', 'Güçlü bir bey, dere suyunun önüne bent çekip suyun tamamını kendi un değirmenine akıttı; aşağıdaki köyler susuz kaldı.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Bendi yıktır; dere suyunu haftalık gün sırasına göre bütün köylerin ortak hakkı kıl.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Su adaleti tesis edildi; aşağıdaki tarlalar kurumaktan kurtuldu."},{"label":"Beyin değirmeni şehre un öğütüyor; bende meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Su Arkının Kendi Değirmenine Akıtılması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Su Arkının Kendi Değirmenine Akıtılması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Su Arkının Kendi Değirmenine Akıtılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 711) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_712', 'ottoman', 'Tahrir Defterlerinin Yanması ve Mülkiyet Kaosu', 'Defterhâne Yangını', 'Kaza Defterhânesi yanınca eski mülkiyet ve tapu hüccetleri kül oldu; fırsatçılar başkasının arazisine çökmeye kalkıştı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Eski kadı sicillerinden ve köy ihtiyarlarının şahitliğinden istifadeyle defterleri adilce baştan yazdır.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Kaos önlendi; hakiki hak sahipleri arazilerini yeniden tescil ettirdi."},{"label":"Şimdilik kim neye zilyetse mülk onun sayılsın de.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrir Defterlerinin Yanması ve Mülkiyet Kaosu davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Tahrir Defterlerinin Yanması ve Mülkiyet Kaosu davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Tahrir Defterlerinin Yanması ve Mülkiyet Kaosu gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 712) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_713', 'ottoman', 'Maden Sahasındaki Meyve Bahçelerinin Kamulaştırılması', 'Gümüşhane Madenleri', 'Yeni bir gümüş damarı keşfedildi fakat galeri girişi köylülerin asırlık elma bahçelerinin tam ortasına denk geliyor.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bahçe sahiplerine peşin ve dolgun tazminat öde, onlara ovada yeni verimli araziler tahsis et.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Gümüş madeni açıldı; köylü hakkını alarak devlete dua etti."},{"label":"Maden devlet malıdır; bahçeleri bedelsiz dozerleyin.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Maden Sahasındaki Meyve Bahçelerinin Kamulaştırılması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Maden Sahasındaki Meyve Bahçelerinin Kamulaştırılması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Maden Sahasındaki Meyve Bahçelerinin Kamulaştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 713) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_714', 'ottoman', 'Bataklığı Islah Eden Çiftçiye Mülk Beratı Talebi', 'Aydın Deltası', 'On yıl boyunca kazma sallayıp sazlığı kurutarak narenciye bahçesi yapan bir çiftçi, arazinin kendi adına tapulanmasını istiyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"\'İhya eden mülk edinir\' şer\'i kaidesini işlet; beratını ver ve 5 yıl vergiden muaf tut.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Emek ödüllendirildi; binlerce çiftçi bataklıkları kurutmaya koştu."},{"label":"Arazi mîrîdir; çiftçiyi kiracı yapıp yüksek kira bağla.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Bataklığı Islah Eden Çiftçiye Mülk Beratı Talebi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Bataklığı Islah Eden Çiftçiye Mülk Beratı Talebi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Bataklığı Islah Eden Çiftçiye Mülk Beratı Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 714) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_715', 'ottoman', 'Zeamet Sahibinin Köylüye Keyfi \'Cerime\' Kesmesi', 'Taşra Teftişi', 'Bir zeamet beyi, tarlasından geçen köylülerden \'otumu çiğnediniz\' bahanesiyle kanun dışı para cezaları toplamaktadır.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Beyi divana celbet; kanunsuz aldığı harçları köylüye iade ettir ve dirligini elinden al.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Derebeylik hevesi kırıldı; köylü yollarında hürriyetle yürüdü."},{"label":"Bey sınır muhafızıdır; köylünün şikâyetine kulak asma.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zeamet Sahibinin Köylüye Keyfi \'Cerime\' Kesmesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Zeamet Sahibinin Köylüye Keyfi \'Cerime\' Kesmesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Zeamet Sahibinin Köylüye Keyfi \'Cerime\' Kesmesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 715) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_716', 'ottoman', 'Zimmî Bağcının Şıra Vergisi İtirazı', 'Tekirdağ Kadılığı', 'Müslüman bağcılardan kuru üzüm öşrü alınırken, Hristiyan bağcılardan şıra ve pekmez için haksız yere iki kat vergi talep edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kanunnâme hükmünü tazele: Zimmî tebaaya ahidnâme dışı ek vergi yüklenemez; nispeti eşitle.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Vergi adaleti sağlandı; gayrimüslim bağcılar üretime sarıldı."},{"label":"Şarap yapıyorlar deyip çifte vergiyi tahsil edin.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Zimmî Bağcının Şıra Vergisi İtirazı nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Zimmî Bağcının Şıra Vergisi İtirazı fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Zimmî Bağcının Şıra Vergisi İtirazı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 716) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_717', 'ottoman', 'Miras Kalan Çiftlikte Kadın Hakkının Gasbı', 'Kaza Meclisi', 'Erkek kardeşlerin, şer\'i taksimata uymayarak kız kardeşlerinin hissesini zorla ellerinden aldığı bildirildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Şeriatın taksim hükmünü uygula: Kız kardeşlerin payını teslim ettir, gaspçı kardeşleri cezalandır.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Hukuk güvencesi teyit edildi; zayıfın hakkı zalimin elinde bırakılmadı."},{"label":"Aile meselesidir; kadı araya girmesin deyip davayı düşür.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Miras Kalan Çiftlikte Kadın Hakkının Gasbı nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Miras Kalan Çiftlikte Kadın Hakkının Gasbı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Miras Kalan Çiftlikte Kadın Hakkının Gasbı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 717) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_718', 'ottoman', 'Savaş Yıkımı Yaşayan Köylerin Canlandırılması', 'Serhad İskânı', 'Sınır harbinde yakılmış köyler harabe halde duruyor; köylülerin dönüp ev yapması için teşvik isteniyor.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Özel şenlendirme fermanı çıkar: Dönen köylüye kereste ver, 3 yıl tek akçe vergi alma.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Serhad boyu yeniden şenlendi; harabeler mamur köylere dönüştü."},{"label":"Bütçe yoktur; köylüler kendi imkânlarıyla yapsın.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Savaş Yıkımı Yaşayan Köylerin Canlandırılması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Savaş Yıkımı Yaşayan Köylerin Canlandırılması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Savaş Yıkımı Yaşayan Köylerin Canlandırılması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 718) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_719', 'ottoman', 'Mültezimin Harman Kalkmadan Öşür İstemesi', 'Taşra Teftişi', 'Mültezim, buğday henüz tarlada başaktayken tahmin usulüyle aşırı yüksek öşür yazıp köylüyü borçlandırdı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tahmin usulünü yasakla! Öşür ancak harman yerinde buğday daneye dökülünce tartıyla alınır.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Tarladaki gasp durduruldu; köylü mahsulünü hilesiz teslim etti."},{"label":"Mültezim defterdara hesap verecektir; tahsilatına divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Mültezimin Harman Kalkmadan Öşür İstemesi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Mültezimin Harman Kalkmadan Öşür İstemesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Mültezimin Harman Kalkmadan Öşür İstemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 719) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_720', 'ottoman', 'Padişah Koruluklarında Köylünün Kuru Çalı Toplaması', 'Hassa Koruları', 'Bostancıbaşı, donmamak için saray ormanından yere düşmüş kuru dalları toplayan köylüleri hırsızlıkla itham edip hapsetti.', '[{"id":"char_bostancibasi","name":"Bostancıbaşı"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Köylüleri derhal sal! \'Yere düşen kuru dal fukaranın hakkıdır\' diyerek bostancıbaşını azarla.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Merhamet saray korularına girdi; fukara kış soğuğunda donmaktan kurtuldu."},{"label":"Saray korusuna el uzatanın eli kesilir; köylüleri cezalandır.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Padişah Koruluklarında Köylünün Kuru Çalı Toplaması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Padişah Koruluklarında Köylünün Kuru Çalı Toplaması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Padişah Koruluklarında Köylünün Kuru Çalı Toplaması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 720) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_721', 'ottoman', 'Koyun Yağının Narhtan Pahalıya Satılması', 'İstanbul Kasapları', 'Kasaplar, yemeklik kuyruk yağını börekçilere ve zengin konaklarına gizlice iki kat fiyata satıp tezgâhta halka yağ bırakmıyor.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Tezgâhtan önce fukaraya satış şartı koy; gizli kuyruk yağı saklayan kasabın dükkânını mühürle.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Kuyruk yağı tezgâha indi; fukara sofraları yağsız kalmaktan kurtuldu."},{"label":"Börekçi çok para veriyorsa kasap satsın; piyasaya meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Koyun Yağının Narhtan Pahalıya Satılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Koyun Yağının Narhtan Pahalıya Satılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Koyun Yağının Narhtan Pahalıya Satılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 721) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_722', 'ottoman', 'Gece Vakti Tartı Ağırlıklarını Değiştiren Bakkal', 'Kaza İhtisabı', 'Bakkal kalfasının gündüz muhtesip kontrolünde tam dirhem, gece fener ışığında ise altı oyuk hafif dirhem kullandığı belgelendi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Hileli ağırlıkları çarşı meydanında kırdır; bakkalın dükkânını kapatıp kendisini teşhir et.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Tartıda sahtekârlık ezildi; çarşıda gece alışverişi emniyete kavuştu."},{"label":"Ufak esnaftır; hafif bir azar ve para cezasıyla bırak.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Gece Vakti Tartı Ağırlıklarını Değiştiren Bakkal nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Gece Vakti Tartı Ağırlıklarını Değiştiren Bakkal fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Gece Vakti Tartı Ağırlıklarını Değiştiren Bakkal meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 722) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_723', 'ottoman', 'Kalitesiz Köseleyle Ordu Eyeri İmalatı', 'Saraçlar Loncası', 'Saraç kethüdasının donanma ve sipahi atları için aldığı kalın manda köselesini satıp yerine ince dana derisi kullandığı görüldü.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Kethüdayı azlet, mallarına el koy; sipahilere saf manda derisinden sağlam eyerler diktir.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Süvari eyerleri çelik gibi sağlam oldu; seferde koşum takımları kopmadı."},{"label":"Eyer eyerdir; sefer acildir deyip ince derili eyerleri kabul edin.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kalitesiz Köseleyle Ordu Eyeri İmalatı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kalitesiz Köseleyle Ordu Eyeri İmalatı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kalitesiz Köseleyle Ordu Eyeri İmalatı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 723) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_724', 'ottoman', 'Tahin Helvasına Şeker Yerine Ağaç Reçinesi Katılması', 'Helvacılar Çarşısı', 'Mısır şekeri pahalandı diye helvacıların helvaya ağaç zamkı karıştırarak çocukların boğazını tahriş ettiği bildirildi.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Bütün kazanları muhtesip hekimleriyle döktür; saf şeker ve susam dışında katkıyı yasakla.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Gıda terörü durduruldu; çocuklar temiz helvaya kavuştu."},{"label":"Zamk helvayı tutturur; esnafı iflas ettirmeyin.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Tahin Helvasına Şeker Yerine Ağaç Reçinesi Katılması hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Tahin Helvasına Şeker Yerine Ağaç Reçinesi Katılması hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Tahin Helvasına Şeker Yerine Ağaç Reçinesi Katılması gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 724) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_725', 'ottoman', 'Genç Kalfaların Dükkân Açma Ruhsatı Kavgası', 'Demirciler Loncası', 'Usta gediklerinin boşalmasına rağmen yaşlı ustaların rüşvet karşılığı gedikleri zengin akrabalarına devrettiği ihbar edildi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Gedik devrini kadı huzurunda imtihana bağla; en mahir kalfaya dükkân beratını ver.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Genç iş gücünün önü açıldı; demircilikte kaliteli üretim arttı."},{"label":"Ustaların kadim hakkıdır; dükkânı kime isterlerse versinler.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Genç Kalfaların Dükkân Açma Ruhsatı Kavgası nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Genç Kalfaların Dükkân Açma Ruhsatı Kavgası fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Genç Kalfaların Dükkân Açma Ruhsatı Kavgası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 725) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_726', 'ottoman', 'Bozahanelerde Yasaklı Sert İçki Satışı', 'İstanbul Şehremaneti', 'Tatlı boza satma ruhsatı olan dükkânların bodrumlarda ekşimiş sarhoş edici \'tatar bozası\' ve arak içirdiği tespit edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Bodrumları bastır, fıçıları sokaklara akıt ve ruhsat dışı sarhoşluk yuvalarını mühürle.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Mahalle asayişi korundu; sarhoş taşkınlıkları bıçak gibi kesildi."},{"label":"Bozahaneler vergi verir; çok üzerlerine gitmeyin.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Bozahanelerde Yasaklı Sert İçki Satışı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Bozahanelerde Yasaklı Sert İçki Satışı fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Bozahanelerde Yasaklı Sert İçki Satışı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 726) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_727', 'ottoman', 'Çavdar Ununun Buğday Diye Fırınlara Dağıtılması', 'Un Kapanı', 'Kapan simsarlarının simsiyah çavdar ununu kireç tozuyla beyazlatıp fırınlara \'Has Beyaz Un\' diye sattığı ortaya çıktı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hileli unları döktür, simsarları teşhir edip zindana at ve fırınlara saf buğday unu sağla.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Ekmekte kimyevi zehir önlendi; halk tertemiz beyaz ekmek yedi."},{"label":"Ekmek çıksın da nasıl çıkarsa çıksın; un kıttır.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Çavdar Ununun Buğday Diye Fırınlara Dağıtılması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Çavdar Ununun Buğday Diye Fırınlara Dağıtılması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Çavdar Ununun Buğday Diye Fırınlara Dağıtılması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 727) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_728', 'ottoman', 'Kumaş Ölçümünde Arşın Hilesi', 'Kapalıçarşı Çuhacıları', 'Tüccarların tezgâh altına vidaladığı arşın demirinin iki parmak kısa olduğu ve her topta vatandaşı soyduğu kanıtlandı.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Mühürlü resmi demir arşınları tezgâha çaktır; kısa arşın kullananın dükkânını kapattır.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Ölçüde haksızlık bitti; kumaş alan eksiksiz metresini teslim aldı."},{"label":"Tüccarın kârıdır; kumaş esnektir deyip aldırmayın.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kumaş Ölçümünde Arşın Hilesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kumaş Ölçümünde Arşın Hilesi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kumaş Ölçümünde Arşın Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 728) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_729', 'ottoman', 'Gümüş Kupalarda Ayarın Düşürülmesi', 'Kuyumcular Loncası', 'Payitaht sarraflarının gümüş eşyalarda 90 ayar yerine 60 ayar kullandığı ve içine bakır karıştırdığı anlaşıldı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Hileli gümüşleri darphanede erittir; sahtekârlara ağır para cezası kes ve ayar damgası koy.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Osmanlı gümüşünün beynelmilel itibarı kurtarıldı; kalpazanlık durduruldu."},{"label":"Kuyumcular hatırlı zenginlerdir; aralarına girmeyin.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Gümüş Kupalarda Ayarın Düşürülmesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Gümüş Kupalarda Ayarın Düşürülmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gümüş Kupalarda Ayarın Düşürülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 729) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_730', 'ottoman', 'Berberlerin Bulaşıcı Yaraları Tedaviye Kalkışması', 'İstanbul Kadılığı', 'Tıraş berberlerinin şarbonlu ve frengili çıbanları neşterle yarıp diğer müşterilere mikrop bulaştırdığı görüldü.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"}]', '[{"label":"Berberlerin cerrahlık yapmasını fermanla yasakla; cerrahi işleri sadece diplomalı hekimlere bağla.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Hastalık bulaşması önlendi; sıhhi disiplin berber dükkânlarına girdi."},{"label":"Halk berbere alışkındır; hekimler pahalıdır deyip izin ver.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Berberlerin Bulaşıcı Yaraları Tedaviye Kalkışması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Berberlerin Bulaşıcı Yaraları Tedaviye Kalkışması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Berberlerin Bulaşıcı Yaraları Tedaviye Kalkışması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 730) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_731', 'ottoman', 'Hamamların Odun Yetersizliği Yüzünden Soğuk Kalması', 'Payitaht Hamamları', 'Hamamcıların odun pahalı diye külhanları yakmadığı, ılık suyla halkın üşüyüp zatürre olduğu şikâyet edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hamamlara devlet depolarından sübvanse odun tahsis et ama sıcak su mecburiyetini tavizsiz denetle.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Hamamlar sıcacık tüttü; halk kış gününde sıhhatle yıkandı."},{"label":"Hamamcılar ne kadar yakarsa yaksın; divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Hamamların Odun Yetersizliği Yüzünden Soğuk Kalması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Hamamların Odun Yetersizliği Yüzünden Soğuk Kalması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Hamamların Odun Yetersizliği Yüzünden Soğuk Kalması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 731) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_732', 'ottoman', 'Çürük Çivilerle At Nallanması', 'Nalbandlar Çarşısı', 'Nalbandların dökme yumuşak çiviler kullanması yüzünden yük beygirlerinin nalları yolda düşüp hayvanlar topallıyor.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Dövme çelik mıh mecburiyeti koy; hileli mıh kullanan nalbandın tezgâhını mühürlet.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Taşımacı hayvanların canı korundu; sokaklarda araba taşımacılığı aksamadı."},{"label":"Mıh ucuz olsun diye yapılmıştır; müdahale etmeyin.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Çürük Çivilerle At Nallanması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Çürük Çivilerle At Nallanması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Çürük Çivilerle At Nallanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 732) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_733', 'ottoman', 'Kahvehanelerde Asılsız İhtilal Dedikoduları', 'İstanbul Kahvehaneleri', 'Bazı fitne odaklarının kahvehanelerde \'Padişah öldü, ordu yenildi\' yalanıyla esnafı kepenk kapatmaya zorladığı bildirildi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Halkı aydınlatacak resmi münadiler çıkar; yalan yayan kışkırtıcıları yakalatıp adaletle cezalandır.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Fitne söndürüldü; çarşı kepenk açıp huzurla ticaretine döndü."},{"label":"Bütün kahvehaneleri toptan yıktırıp kahve içmeyi yasaklayın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Kahvehanelerde Asılsız İhtilal Dedikoduları meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Kahvehanelerde Asılsız İhtilal Dedikoduları hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Kahvehanelerde Asılsız İhtilal Dedikoduları gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 733) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_734', 'ottoman', 'Çarşı Ağasının Esnaftan \'Selamlık Harcı\' Kesmesi', 'Çarşı Teftişi', 'Asayişten sorumlu çarşı ağasının her cuma esnaftan zorla bayram harçlığı adı altında haraç topladığı belirlendi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Ağayı derhal azlet, topladığı paraları esnafa kuruşu kuruşuna iade ettir ve zindana at.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Esnaf haramzade zabitten kurtuldu; çarşıda devlete sevgi tazelendi."},{"label":"Ağa çarşıyı koruyor; küçük bahşişlere yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağlaun.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Çarşı Ağasının Esnaftan \'Selamlık Harcı\' Kesmesi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Çarşı Ağasının Esnaftan \'Selamlık Harcı\' Kesmesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Çarşı Ağasının Esnaftan \'Selamlık Harcı\' Kesmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 734) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_735', 'ottoman', 'Kandil Yağına Domuz İçyağı Karıştırılması', 'Mumcular Kâhyalığı', 'Cami ve ev kandillerine konan zeytinyağlarına domuz donyağı karıştırıldığı, kandillerin is yapıp cemaati rahatsız ettiği kanıtlandı.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hileli fıçıları denize döktür; haram madde karıştıran imalatçıları çarşıda teşhir et.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Mabetlerin ve evlerin aydınlatması temizlendi; hilebazlar ibret oldu."},{"label":"Kandilde yanıp bitiyor, haramlığı kalmaz deyip ceza kesme.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gasp edilen zeytinlik ve dükkân gelirlerini geçmişe dönük faiziyle tahsil et; vakıf bütçesini mütevelli denetimine al ve Kandil Yağına Domuz İçyağı Karıştırılması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hayrat ve vakıf malına el uzatan yerel ayânları saray çavuşlarıyla yakalat; gasbettikleri mülkleri zorla geri alıp kendilerini hapse at ve Kandil Yağına Domuz İçyağı Karıştırılması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Kandil Yağına Domuz İçyağı Karıştırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 735) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_736', 'ottoman', 'Çizme Tabanına Kösele Yerine Mukavva Yapıştırılması', 'Ayakkabıcılar Loncası', 'Çizmecilerin taban arasına preslenmiş kâğıt ve çamur doldurduğu, halkın ilk yağmurda yalınayak kaldığı şikâyet edildi.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"}]', '[{"label":"Ayakkabıcı loncasına baskın yap; tabanı kesip kontrol ettir, hile yapanın dükkânını kapat.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Sağlam kösele mecbur kılındı; halkın parası heba olmaktan kurtuldu."},{"label":"Ucuz kunduradır; parasına göre mal yaparlar de.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çizme Tabanına Kösele Yerine Mukavva Yapıştırılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Çizme Tabanına Kösele Yerine Mukavva Yapıştırılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Çizme Tabanına Kösele Yerine Mukavva Yapıştırılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 736) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_737', 'ottoman', 'Odunların Hortumla Islatılıp Ağır Satılması', 'Odun Kapanı', 'Kış günü odun tartılmadan önce simsarların fıçılarla su dökerek odun ağırlığını iki katına çıkardığı tespit edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kapan kantarını sıkı teftişe al; ıslak odun satan simsarın kantarını kır ve odununu fukaraya bağışla.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Su oyunu bozuldu; halk sobalarda alev alev yanan kuru odun aldı."},{"label":"Kış günüdür, odun yağmurdan ıslanmıştır deyip geçiştir.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Odunların Hortumla Islatılıp Ağır Satılması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Odunların Hortumla Islatılıp Ağır Satılması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Odunların Hortumla Islatılıp Ağır Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 737) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_738', 'ottoman', 'Gemi Ziftinde Çam Reçinesinin Azaltılması', 'Tersane İhtisabı', 'Kalyon kalafatında kullanılan zifte çam reçinesi yerine kara balçık karıştırıldığı, gemilerin su almaya başladığı belgelendi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Hileli zifti denize döktür, müteahhidin kellesini al ve saf Karadeniz ziftiyle kalyonları kalafatlat.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -1","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-1},"log":"Donanma batmaktan kurtuldu; tersane hainlerden temizlendi."},{"label":"Zift pahalıdır; bu seferlik balçıklı ziftle idare edin.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Gemi Ziftinde Çam Reçinesinin Azaltılması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Gemi Ziftinde Çam Reçinesinin Azaltılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Gemi Ziftinde Çam Reçinesinin Azaltılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 738) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_739', 'ottoman', 'Zahire Simsarlarının Gece Vakti Kaçak Satışı', 'Un Kapanı Nazırlığı', 'Un Kapanı\'na giren buğdayların gündüz narhtan satılmayıp gece rüşvetle tüccarlara gizli depolara aktarıldığı görüldü.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kapan kapılarına yeniçeri nöbetçileri dik; gece buğday çıkaranı vatana hıyanetle yargıla.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Karaborsa zinciri parçalandı; un tam vaktinde fırınlara ulaştı."},{"label":"Simsarların ticaretidir; kapandaki nöbetçileri geri çekin.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Zahire Simsarlarının Gece Vakti Kaçak Satışı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Zahire Simsarlarının Gece Vakti Kaçak Satışı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Zahire Simsarlarının Gece Vakti Kaçak Satışı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 739) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_740', 'ottoman', 'Büyük İstanbul Narh Kanunnâmesi', 'Dîvân-ı Hümâyûn', 'Esnafı batırmayan, tüketici fukarayı koruyan, ham madde maliyetine göre her mevsim güncellenen adil bir Narh Kanunu hazırlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Kanunu yürürlüğe koy: \'Alışverişte hile yapan, devletin nizamına kılıç çekmiş sayılır!\'.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Piyasa altın çağına girdi; üretici de tüketici de refaha erdi."},{"label":"Fiyatları kefalete bağlayıp divan murakabesinde ıslahına fırsat tanıın; piyasa kendi kendini bulsun.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Büyük İstanbul Narh Kanunnâmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Büyük İstanbul Narh Kanunnâmesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Büyük İstanbul Narh Kanunnâmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 740) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_741', 'ottoman', 'Tuna Şaykalarının Barutsuz Kalması', 'Tuna Donanması', 'Vidin kalesini koruyan nehir şaykalarının barut tahsisatı gecikti; Kazak botları nehir ticaretini kesti.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Belgrad baruthanesinden acil nehir konvoyu çıkar; şaykalara çifte barut ulaştır.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Şaykalar gülle kustu; Kazak botları nehir dibine batırıldı."},{"label":"Nehir durgundur; barut sevkiyatını bahara bırakın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Tuna Şaykalarının Barutsuz Kalması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Tuna Şaykalarının Barutsuz Kalması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Tuna Şaykalarının Barutsuz Kalması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 741) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_742', 'ottoman', 'Kuşatma Altındaki Azak\'ta Erzak Kıtlığı', 'Azak Kalesi', 'Don nehrinin ağzındaki Azak kalesi Kazaklarca sarıldı; garnizon at etini dahi tüketmek üzere.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Kefe limanından kalyonlarla un ve barut donat, Kırım süvarisini arkadan hücuma kaldır.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Azak kuşatması yarıldı; Karadeniz\'in kuzey kapısı kahramanca korundu."},{"label":"Kale çok uzaktadır; kendi başlarının çaresine baksınlar.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kuşatma Altındaki Azak\'ta Erzak Kıtlığı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kuşatma Altındaki Azak\'ta Erzak Kıtlığı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kuşatma Altındaki Azak\'ta Erzak Kıtlığı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 742) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_743', 'ottoman', 'Rodos Açıklarında Malta Korsanlarının Tuzağı', 'Akdeniz Bahriyesi', 'Malta şövalyelerinin üç kalyonumuza sahte dost bayrağıyla yaklaşıp bordaladığı ve leventleri esir aldığı bildirildi.', '[{"id":"char_donanma_reisi","name":"Donanma Reisi"},{"id":"char_savas_esiri","name":"Savaş Esiri"}]', '[{"label":"Kaptan Paşa\'yı tam filo denize çıkar; Malta korsanlarını inlerinde vurup leventleri kurtar.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Korsan filosu darmadağın edildi; leventler kurtarılıp Rodos\'a getirildi."},{"label":"Deniz savaşı masraflıdır; diplomatik mektupla esirleri isteyin.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Rodos Açıklarında Malta Korsanlarının Tuzağı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Rodos Açıklarında Malta Korsanlarının Tuzağı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Rodos Açıklarında Malta Korsanlarının Tuzağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 743) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_744', 'ottoman', 'İspanyol Gümüş Kalyonunun Ele Geçirilmesi', 'Cezayir Beylerbeyliği', 'Cezayir leventleri Amerika\'dan dönen hazine yüklü bir İspanyol kalyonunu zapt edip yüz bin altın getirdi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Altınları doğrudan tersaneye ve sınır kalelerinin tahkimatına harca; leventleri hil\'atle taltif et.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Hazineye dev servet girdi; kalyonlarımız yeni toplarla donatıldı."},{"label":"İspanya ile barışı bozmayın; altını ve gemiyi iade edin.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tağşiş edilen paraları piyasadan toplatıp hazine kasasında saf külçeye dönüştür; sikke istikrarını devlet garantisine al ve İspanyol Gümüş Kalyonunun Ele Geçirilmesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Piyasanın gümüşünü eriten sarrafları Divan-ı Hümâyûn huzurunda isticvap et; tağşiş çetelerini derhal küreğe mahkûm eyle ve İspanyol Gümüş Kalyonunun Ele Geçirilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Darphane ve Meskûkât Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve İspanyol Gümüş Kalyonunun Ele Geçirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 744) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_745', 'ottoman', 'Batık Venedik Gemisinin Mallarını Yağmalayan Köylüler', 'Mora Sahili', 'Fırtınada Mora kayalıklarına vuran zengin bir Venedik kalyonunun kumaş ve altınlarını kıyı köylüleri paylaştı.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Kadı nezaretinde malları toplat, Venedik elçisine teslim et ve köylüye kurtarma payı ver.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Uluslararası deniz hukuku korundu; yağmacılık önlendi, sulh muhafaza edildi."},{"label":"Batan geminin malı ganimettir; köylüde kalsın.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Batık Venedik Gemisinin Mallarını Yağmalayan Köylüler hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Batık Venedik Gemisinin Mallarını Yağmalayan Köylüler hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Batık Venedik Gemisinin Mallarını Yağmalayan Köylüler gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 745) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_746', 'ottoman', 'Kalyon Omurgalarında Kurtlu Ağaç Kullanımı', 'Tersane-i Âmire', 'Müteahhidin getirdiği meşe tomruklarının içten kurtlu olduğu, suya girince şişip çatlayacağı anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Bütün kurtlu tomrukları yaktır, müteahhidin teminatını yak ve sağlam Sinop meşesi getirt.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Kalyonlar çelik gibi omurgaya kavuştu; denizde batma tehlikesi bitti."},{"label":"Ziftleyip gizleyin; kalyonların suya inmesi gecikmesin.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Kalyon Omurgalarında Kurtlu Ağaç Kullanımı nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Kalyon Omurgalarında Kurtlu Ağaç Kullanımı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyon Omurgalarında Kurtlu Ağaç Kullanımı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 746) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_747', 'ottoman', 'Nöbet Tutmayan Paralı Sekbanların Firarı', 'Serhad Kaleleri', 'Maaşları bir ay gecikti diye kale burçlarını terk edip civar köyleri haraca bağlayan sekban bölükleri tespit edildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sadık sipahilerle asileri kuşat, elebaşıları as ve kaleye nizami yeniçeri garnizonu yerleştir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Kale anarşiden kurtarıldı; köylünün can ve mal emniyeti sağlandı."},{"label":"Sekbanların istediği parayı ödeyip yerlerinde kalmalarına yalvarın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Nöbet Tutmayan Paralı Sekbanların Firarı nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Nöbet Tutmayan Paralı Sekbanların Firarı fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Nöbet Tutmayan Paralı Sekbanların Firarı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 747) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_748', 'ottoman', 'Kırım Süvarilerine Çizme Bahşişi Ödenmesi', 'Kırım Hanlığı', 'Han, sefere 40 bin atlıyla katılmak için askerin donanımı ve at nalları adına peşin tahsisat talep etti.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Tahsisatı eksiksiz öde; Kırım süvarisi ordunun gözü, kulağı ve kanadıdır.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Kırım atlıları düşmanı bozkırda çevirdi; meydan savaşı zaferle bitti."},{"label":"Han kendi bütçesinden karşılasın; hazineden para çıkmaz.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kırım Süvarilerine Çizme Bahşişi Ödenmesi sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Kırım Süvarilerine Çizme Bahşişi Ödenmesi meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Kırım Süvarilerine Çizme Bahşişi Ödenmesi gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 748) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_749', 'ottoman', 'Gümrük Vergisini Ödemeyen Venedik Tacirleri', 'Venedik Balyosluğu', 'Venedik tüccarlarının sahte kapitülasyon beratı göstererek Haliç gümrüğüne tek akçe vermeden kumaş indirdiği görüldü.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Malları antrepoda mühürle, geçmiş vergileri faiziyle tahsil etmeden gemileri bırakma.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Gümrük kaçakçılığı önlendi; devletin mali otoritesi teyit edildi."},{"label":"Balyos nota verir; yabancı tüccarın mallarına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Gümrük Vergisini Ödemeyen Venedik Tacirleri nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Gümrük Vergisini Ödemeyen Venedik Tacirleri fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Gümrük Vergisini Ödemeyen Venedik Tacirleri meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 749) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_750', 'ottoman', 'Cidde Açıklarında Portekiz Korsan Gemisi', 'Kızıldeniz Muhafızlığı', 'Mekke\'ye buğday getiren Mısır gemisini basmak üzere pusu kuran Portekiz karavelası fark edildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Süveyş kalyonlarını derhal hücuma kaldır; korsan gemisini batırıp hac yolunu temizle.","preview":"Adalet +8, Reaya +7 | Hazine -2, Otorite -2","effects":{"justice":8,"people":7,"treasury":-2,"military":0,"authority":-2},"log":"Hac yolu emniyete alındı; Portekiz gemisi Kızıldeniz\'in dibini boyladı."},{"label":"Gemilerimiz açık denize çıkmasın; limanda beklesin.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Cidde Açıklarında Portekiz Korsan Gemisi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Cidde Açıklarında Portekiz Korsan Gemisi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Cidde Açıklarında Portekiz Korsan Gemisi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 750) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_751', 'ottoman', 'Bronz Top Namlularının Aşırı Isınarak Çatlaması', 'Kamaniçe Surları', 'Aralıksız ateş eden kale toplarının bronz namluları genişledi; gülleler namlu içinde sıkışıp patlama riski taşıyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Atışları nöbetleşe yaptır, sirkeli suyla soğutma havuzları kur ve çatlak namluları geriye çek.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Topçuların canı kurtarıldı; bataryalar intizamla gülle yağdırdı."},{"label":"Ateşi kesmeyin; düşman yaklaşıyor, patlarsa patlasın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Bronz Top Namlularının Aşırı Isınarak Çatlaması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Bronz Top Namlularının Aşırı Isınarak Çatlaması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Bronz Top Namlularının Aşırı Isınarak Çatlaması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 751) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_752', 'ottoman', 'Gece Nöbetinde Uyuyan Kale Topçuları', 'Boğaz Hisarları', 'Rumelihisarı\'nda gece nöbetçilerinin kulelerde uyuduğu, bir Kazak şaykasının hisarın altından geçip gittiği anlaşıldı.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Dizdarı ve uyuyan neferleri cezalandır; boğaza gece meşaleli devriye kayıkları çıkar.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Boğaz kilitlendi; tek bir düşman teknesi hisarları aşamadı."},{"label":"Bir kuştan bir şey olmaz; askeri çok sıkıştırmayın.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Gece Nöbetinde Uyuyan Kale Topçuları nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Gece Nöbetinde Uyuyan Kale Topçuları fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Gece Nöbetinde Uyuyan Kale Topçuları meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 752) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_753', 'ottoman', 'Kalyon Yelken Bezlerinin Ambarlarda Küflenmesi', 'Sinop Tersanesi', 'Çatısı akan ambardaki kenevir yelken bezleri çürüdü; bahar seferine çıkacak kalyonlar yelkensiz kaldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Tire ve Kastamonu dokumacılarından acil yeni yelken bezleri satın al; ambar çatısını kiremitlet.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Kalyonlar bembeyaz sağlam yelkenlerle denize indi; sefer aksamadı."},{"label":"Küflü bezleri kurutup dikin; yeni bez masraflıdır.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Kalyon Yelken Bezlerinin Ambarlarda Küflenmesi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Kalyon Yelken Bezlerinin Ambarlarda Küflenmesi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kalyon Yelken Bezlerinin Ambarlarda Küflenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 753) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_754', 'ottoman', 'Buz Kütlelerinin Yıkacağı Duba Köprü', 'Tuna Nehri', 'Bahar çözülmesiyle Tuna\'dan sürüklenen devasa buz kütleleri ordunun geçeceği köprü ayaklarına dayanıp ezmeye başladı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"İstihkâm neferlerine buzları barutla patlattır; köprü ayaklarına V şeklinde buz yaranlar inşa et.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Buzlar parçalandı; köprü kurtarıldı ve ordu hızla karşıya geçti."},{"label":"Köprü sağlamdır; buz kendi erir deyip bekleyin.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Buz Kütlelerinin Yıkacağı Duba Köprü meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Buz Kütlelerinin Yıkacağı Duba Köprü meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Buz Kütlelerinin Yıkacağı Duba Köprü gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 754) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_755', 'ottoman', 'Fırtınada Kayalıklara Sürüklenen Osmanlı Kalyonu', 'Girit Suları', 'Fırtınada dümeni kırılan 70 toplu bir kalyonumuz Hanya açıklarındaki kayalıklara çarpmak üzere.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Hanya leventlerini fırtına sandallarıyla yardıma çıkar; halatlarla kalyonu yedekleyip limana çek.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Kalyon ve 500 cengaver levent kurtarıldı; kahramanlık ödüllendirildi."},{"label":"Deniz çok azgındır; sandalları riske atmayın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Fırtınada Kayalıklara Sürüklenen Osmanlı Kalyonu nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Fırtınada Kayalıklara Sürüklenen Osmanlı Kalyonu fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Fırtınada Kayalıklara Sürüklenen Osmanlı Kalyonu meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 755) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_756', 'ottoman', 'Lağımcıların Yerin Altında Düşmanla Karşılaşması', 'Uyvar Kuşatması', 'Kazılan tünelde düşman lağımcılarıyla burun buruna gelindi; yer altında kazma kürekle kanlı boğuşma başladı.', '[{"id":"char_humbaracibasi","name":"Humbaracıbaşı"}]', '[{"label":"Tünele el humbaracılarını sok; düşman galerisini patlatıp tüneli kontrol altına al.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Düşman lağımı yerin altında havaya uçuruldu; kale burcu çöktü."},{"label":"Tüneli geriden toprakla doldurup kaçın.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Lağımcıların Yerin Altında Düşmanla Karşılaşması nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Lağımcıların Yerin Altında Düşmanla Karşılaşması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Lağımcıların Yerin Altında Düşmanla Karşılaşması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 756) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_757', 'ottoman', 'Karantinayı Delmek İsteyen Fransız Tüccar Kalyonu', 'İskenderiye Limanı', 'Marsilya\'da kolera varken gelen Fransız kalyonu, 40 günlük tecridi beklemeyip zorla limana yanaşmak istiyor.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Liman toplarına ateş emri ver: Karantinayı bozan gemi yakılacaktır! Hukuku ve sağlığı çiğnetme.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Fransız kalyonu geri çekildi; kolera Mısır\'a girmeden önlendi."},{"label":"Fransa ile dostuz; gümrük vergisini alıp limana yanaştırın.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Karantinayı Delmek İsteyen Fransız Tüccar Kalyonu hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Karantinayı Delmek İsteyen Fransız Tüccar Kalyonu hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Karantinayı Delmek İsteyen Fransız Tüccar Kalyonu gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 757) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_758', 'ottoman', 'Serhad Paşasının Düşman Elçisini Zindana Atması', 'Belgrad Sefareti', 'Barış mektubu getiren Avusturya elçisinin kibirli tavırlarına öfkelenen sınır paşası, elçiyi kaleye hapsetti.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Elçiyi derhal serbest bıraktır; paşayı azarla: \'Elçiye zeval olmaz, devletin ahdi çiğnenemez!\'.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Devletin diplomasi haysiyeti korundu; haksız bir harp engellendi."},{"label":"Paşa doğru yapmıştır; düşman elçisi haddini bilsin.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Serhad Paşasının Düşman Elçisini Zindana Atması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Serhad Paşasının Düşman Elçisini Zindana Atması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Serhad Paşasının Düşman Elçisini Zindana Atması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 758) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_759', 'ottoman', 'Bahreyn İnci Avcılarına Korsan Saldırısı', 'Basra Körfezi', 'Dalgıçların çıkardığı incileri taşıyan teknelerin maskatlı korsanlarca basıldığı, dalgıçların zincire vurulduğu bildirildi.', '[{"id":"char_denizci_balikci","name":"Denizci / Balıkçı Esnafı"},{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Basra kalyonlarını sevk et; korsanları yakalatıp incileri sahiplerine iade et ve koruma fırkateyni ata.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Körfez emniyete kavuştu; inci ticareti devlete muazzam vergi getirdi."},{"label":"Dalgıçlar kendi tüfeklerini alsın; donanma Basra\'dan çıkmasın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Bahreyn İnci Avcılarına Korsan Saldırısı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Bahreyn İnci Avcılarına Korsan Saldırısı fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Bahreyn İnci Avcılarına Korsan Saldırısı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 759) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_760', 'ottoman', 'Yirmi Yıllık Kuşatmanın Askerde Bıkkınlık Yaratması', 'Kandiye Önleri', 'Girit Kandiye siperlerindeki yeniçeriler \'Ömrümüz çamurda bitti\' diyerek silah çatıp çorba kazanlarını devirdi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Fazıl Ahmed Paşa bizzat siperlere insin; birikmiş ulufeleri tam ayar altınla öde ve son fethin müjdesini ver.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Asker coştu; Kandiye kalesi teslim alındı, Akdeniz fethi mühürlendi."},{"label":"Asileri idam ettirin; zorla hücuma kaldırın.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yirmi Yıllık Kuşatmanın Askerde Bıkkınlık Yaratması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Yirmi Yıllık Kuşatmanın Askerde Bıkkınlık Yaratması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Yirmi Yıllık Kuşatmanın Askerde Bıkkınlık Yaratması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 760) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_761', 'ottoman', 'Medrese Talebelerinin İlim Yerine Çarşıda Zorbalık Yapması', 'Süleymaniye Medresesi', 'Bazı suhtelerin dersleri bırakıp çeteler kurarak esnaftan \'cer harcı\' adı altında para kestiği tespit edildi.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Eşkıyalık yapan suhteleri medreseden at, zindana koy ve medreselere sıkı ilim yoklaması getir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"İlim yuvaları zorbalardan temizlendi; talebeler kitaplarının başına döndü."},{"label":"Talebe-i ulumdur, incitmeyin; esnaf biraz harçlık versin.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Medrese Talebelerinin İlim Yerine Çarşıda Zorbalık Yapması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Medrese Talebelerinin İlim Yerine Çarşıda Zorbalık Yapması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Medrese Talebelerinin İlim Yerine Çarşıda Zorbalık Yapması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 761) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_762', 'ottoman', 'Müderrislik İmtihanında Kazaskerin Damadına Ayrıcalık', 'Kazaskerlik Meclisi', 'Büyük medresenin boşalan müderrislik kürsüsü için yapılan münazarada allame bir âlim yerine kazaskerin cahil damadı seçilmek isteniyor.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Müdahale et! Kürsüyü hakiki allameye ver; torpil yapan kazaskeri vazifeden uzaklaştır.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"İlimde liyakat galip geldi; talebeler hakiki hocanın dersine koştu."},{"label":"Kazasker devlette rükündür; damadını küstürmeyin.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Müderrislik İmtihanında Kazaskerin Damadına Ayrıcalık nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Müderrislik İmtihanında Kazaskerin Damadına Ayrıcalık fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Müderrislik İmtihanında Kazaskerin Damadına Ayrıcalık meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 762) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_763', 'ottoman', 'Takiyüddin\'in Rasathanesine \'Melekleri Dikizliyor\' İftirası', 'Tophane Tepesi', 'Yobaz bir vaizin kışkırtmasıyla halk toplanıp astronomi rasathanesinin deprem getirdiğini öne sürerek yıkılmasını istedi.', '[{"id":"char_cami_imami","name":"Cami İmamı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Rasathaneyi ordu muhafazasına al! \'Gökyüzünü seyretmek Allah\'ın ayetlerini anlamaktır\' de ve ilmi koru.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Bilimsel ilerleme korundu; deniz haritaları ve takvimler mükemmelleşti."},{"label":"Halkın infialini dindirmek için rasathaneyi top ateşiyle yıktırın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Takiyüddin\'in Rasathanesine \'Melekleri Dikizliyor\' İftirası meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Takiyüddin\'in Rasathanesine \'Melekleri Dikizliyor\' İftirası hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Takiyüddin\'in Rasathanesine \'Melekleri Dikizliyor\' İftirası gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 763) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_764', 'ottoman', 'Tarihi El Yazmalarının Güve ve Rutubetten Çürümesi', 'Fatih Kütüphanesi', 'İbn Sina ve Fârâbî\'nin tek nüsha el yazması eserlerinin mahzenlerde nemden kurtlandığı görüldü.', '[{"id":"char_farabi","name":"Fârâbî"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Hususi sedir ağacından dolaplar yaptır, mücellitler ve hattatlar tutarak kitapları restore ettir.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"İslam medeniyetinin hafızası kurtarıldı; kütüphane ilim yuvası oldu."},{"label":"Eski kitaplara bütçe ayrılmaz; sadece güneşlendirip havalandırın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Tarihi El Yazmalarının Güve ve Rutubetten Çürümesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Tarihi El Yazmalarının Güve ve Rutubetten Çürümesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tarihi El Yazmalarının Güve ve Rutubetten Çürümesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 764) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_765', 'ottoman', 'Avrupa\'dan Gelen Hendese Kitaplarının Yasaklanması Talebi', 'Hendese Mektebi', 'Muhafazakâr bir grup, topçuluk ve istihkâm hesapları içeren Fransızca hendese kitaplarının \'gâvur icadı\' diye yakılmasını istedi.', '[{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"Kitapları koru; \'İlim müminin yitiğidir, nerede bulsa alır!\' hadisini hatırlatarak tercümesini emret.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Topçularımız modern matematik öğrendi; kale kuşatmaları hızlandı."},{"label":"Ulemanın hatırına kitapları meydanda yaktırın.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Avrupa\'dan Gelen Hendese Kitaplarının Yasaklanması Talebi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Avrupa\'dan Gelen Hendese Kitaplarının Yasaklanması Talebi fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Avrupa\'dan Gelen Hendese Kitaplarının Yasaklanması Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 765) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_766', 'ottoman', 'Kadı Naiplerinin Mühürsüz İlamlarla Rüşvet Alması', 'Kaza Mahkemeleri', 'Mahkemelerde kadı yerine bakan tecrübesiz naiplerin vatandaştan para sızdırmak için mühürsüz sahte kararlar verdiği anlaşıldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Naiplik suiistimalini bitir: Bütün kararların doğrudan kadının bizzat mührüyle çıkmasını mecbur kıl.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Yargıda sahtecilik durduruldu; mahkeme kararları mutlak güven kazandı."},{"label":"Kadılar yetişemiyor; naiplerin harç almasına tarafları divanda dinleyip makul bir tazminat ve rıza ile sulh bağlayın.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadı Naiplerinin Mühürsüz İlamlarla Rüşvet Alması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadı Naiplerinin Mühürsüz İlamlarla Rüşvet Alması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadı Naiplerinin Mühürsüz İlamlarla Rüşvet Alması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 766) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_767', 'ottoman', 'Tıp Talebelerinin Anatomi Modelleri Üzerinde Eğitimi', 'Tıbbiye Mektebi', 'Hekim adaylarının insan vücudunu tanımadan cerrahlık yapmasını önlemek için balmumundan organ modelleri yaptırılması teklif edildi.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Floransa\'dan balmumu anatomi heykelleri getirt; hekimleri insan bedenini tam bilerek mezun et.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Cerrahlar hata yapmadan ameliyat yaptı; binlerce can kurtarıldı."},{"label":"İnsan heykeli günahtır deyip modellere izin vermeyin.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şifalı bitki ve ecza temini için hekim heyetine yıllık bütçe bağla; karantina zararını gümrük harçlarından mahsup et ve Tıp Talebelerinin Anatomi Modelleri Üzerinde Eğitimi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Veba tecridini bozan tüccarları derhal tevkif et; ferman-ı hümâyûna karşı gelenleri ibret için kale zindanına kapat ve Tıp Talebelerinin Anatomi Modelleri Üzerinde Eğitimi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Karantina-i Bahriye ve Sıhhat Kanunu\' yürürlüğe koy; yetki aşımını durdurup liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Tıp Talebelerinin Anatomi Modelleri Üzerinde Eğitimi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 767) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_768', 'ottoman', 'Hattatların Matbaayı Protesto İçin Divana Yürümesi', 'Matbaa Teftişi', 'Yazma eser kopyalayan binlerce hattat, İbrahim Müteferrika\'nın matbaası yüzünden işsiz kaldıklarını söyleyerek divan kapısına dayandı.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Dengeyi kur: Dini kitapları hattatlara bırak, lügat, tarih ve coğrafya kitaplarını matbaada bastır.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Hem hattatların ekmeği korundu hem de ilmi kitaplar matbaayla ucuzladı."},{"label":"Matbaayı tamamen kapatıp makineleri Haliç\'e atın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Hattatların Matbaayı Protesto İçin Divana Yürümesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Hattatların Matbaayı Protesto İçin Divana Yürümesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Hattatların Matbaayı Protesto İçin Divana Yürümesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 768) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_769', 'ottoman', 'Katip Çelebi\'nin Cihannümâ Eserinin Çoğaltılması', 'Süleymaniye Kütüphanesi', 'Dünya denizlerini, boğazlarını ve iklimlerini anlatan muazzam eserin donanma kaptanlarına ve valilere dağıtılması teklif edildi.', '[{"id":"char_katip_celebi","name":"Kâtip Çelebi"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Eseri matbaada bastır; her kalyona ve her sancak beyine birer cilt zimmetle.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Kaptanlarımız denizleri karış karış öğrendi; valiler coğrafya şuuruna erdi."},{"label":"Coğrafya öğrenmek lüzumsuzdur; kaptanlar kılavuz baksın.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Katip Çelebi\'nin Cihannümâ Eserinin Çoğaltılması meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Katip Çelebi\'nin Cihannümâ Eserinin Çoğaltılması hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Katip Çelebi\'nin Cihannümâ Eserinin Çoğaltılması gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 769) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_770', 'ottoman', 'Medreselerden Mantık ve Riyaziye Derslerinin Kaldırılması Girişimi', 'Medrese Müfredatı', 'Mutaassıp bir müderris heyeti, medreselerden mantık, cebir ve hendese derslerinin kaldırılıp sadece ezber fıkıh konmasını istedi.', '[{"id":"char_muderris","name":"Medrese Müderrisi"}]', '[{"label":"Reddet! \'Akıl olmadan şeriat anlaşılamaz!\' Mantık ve riyaziyeyi zorunlu ders olarak muhafaza et.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"İlmi muhakeme kabiliyeti korundu; medreselerden aydın hukukçular yetişti."},{"label":"Heyetin talebini onayla; mantık derslerini kaldırın.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Medreselerden Mantık ve Riyaziye Derslerinin Kaldırılması Girişimi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Medreselerden Mantık ve Riyaziye Derslerinin Kaldırılması Girişimi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Medreselerden Mantık ve Riyaziye Derslerinin Kaldırılması Girişimi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 770) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_771', 'ottoman', 'Sadrazamın Siyasi İdam İçin Şeyhülislama Baskısı', 'Şeyhülislamlık', 'Sadrazam, kendisine rakip olan dürüst bir veziri idam ettirmek için \'Mülke fesat soktu\' diyerek zorla fetva istiyor.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"Şeyhülislamın arkasında dur: \'Haksız yere cana kıyılamaz!\' Sadrazamı derhal azlet.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Fetva makamı siyasi kılıç olmaktan kurtarıldı; masum devlet adamı ipten alındı."},{"label":"Sadrazamın dediğini yap; Şeyhülislama fetvayı zorla imzalattır.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Sadrazamın Siyasi İdam İçin Şeyhülislama Baskısı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Sadrazamın Siyasi İdam İçin Şeyhülislama Baskısı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Sadrazamın Siyasi İdam İçin Şeyhülislama Baskısı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 771) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_772', 'ottoman', 'Darüşşifada Su ve Musiki Tedavisinin Masraf Sayılması', 'Edirne Şifahanesi', 'Maliye kâtipleri, akıl hastalarına çalınan neyzenlerin ve su şadırvanının bütçesini \'fuzuli eğlence\' diyerek kesmek istedi.', '[{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Tahsisatı bizzat Padişah vakfından bağla: \'Gönül yarasına musiki ve su şifadır, dokunulamaz!\'.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Hastalar nağmelerle şifa buldu; medeniyetin zarafeti korundu."},{"label":"Kâtipler haklıdır; müzisyenleri kovun, fıskiyeleri kapatın.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Darüşşifada Su ve Musiki Tedavisinin Masraf Sayılması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Darüşşifada Su ve Musiki Tedavisinin Masraf Sayılması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Darüşşifada Su ve Musiki Tedavisinin Masraf Sayılması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 772) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_773', 'ottoman', 'Enderun Atölyelerinde Zanaat Derslerinin İhmali', 'Enderun Mektebi', 'Devlet idare edecek gençlerin sadece yazı yazıp ata bindiği, saatçilik, marangozluk ve döküm zanaatlarını hor gördüğü görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Her talebeye bir el zanaatı mecburi kıl: \'Alın teri bilmeyen vezir, milletin halini anlayamaz!\'.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Enderun gençleri tevazu ve hüner kazandı; üreteni anlayan vezirler yetişti."},{"label":"Vezir olacak adam çekiç sallamaz; zanaat derslerini kaldırın.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Enderun Atölyelerinde Zanaat Derslerinin İhmali nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Enderun Atölyelerinde Zanaat Derslerinin İhmali fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Enderun Atölyelerinde Zanaat Derslerinin İhmali meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 773) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_774', 'ottoman', 'Fransız Deniz Haritacılık Metotlarının Okutulması', 'Mühendishane-i Bahrî', 'Fransız mühendislerin küre ve enlem-boylam hesaplı modern haritacılık dersleri vermesine ulemanın karşı çıktığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Dersi mecburi kıl: \'Kafir haritası değil, Allah\'ın yarattığı arzın ilmidir!\' Kaptanları haritayla donat.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Kalyonlarımız okyanuslarda milimetrik rotalar çizdi; deniz hakimiyeti pekişti."},{"label":"Eski pergel usulü yeterlidir; yabancı hocaları memleketine yollayın.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Fransız Deniz Haritacılık Metotlarının Okutulması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Fransız Deniz Haritacılık Metotlarının Okutulması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Fransız Deniz Haritacılık Metotlarının Okutulması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 774) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_775', 'ottoman', 'Aç Kalan Suhtelerin Şehre Yürüyüşü', 'Taşra Medreseleri', 'Vakıf gelirleri kesilen Konya medresesi talebeleri aç kaldıklarını söyleyerek valilik konağını kuşattı.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Vakıf gelirlerini haksız gasbeden mültezimden tahsil et; talebelerin tayınını eksiksiz öde.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Suhte isyanı adaletle yatıştırıldı; talebeler tencerelerine kavuştu."},{"label":"Talebelere asker sevk edin; dağılmazlarsa kurşuna dizin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Aç Kalan Suhtelerin Şehre Yürüyüşü hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Aç Kalan Suhtelerin Şehre Yürüyüşü hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Aç Kalan Suhtelerin Şehre Yürüyüşü gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 775) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_776', 'ottoman', 'Modern Harp Talimnamelerinin Tercümesi', 'Bab-ı Âli Tercüme Odası', 'Prusya ordusunun hızlı tüfek doldurma ve kare piyade siperi nizamnamesinin Türkçeye çevrilmesi teklif edildi.', '[{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Tercümeyi yaptır, ordu matbaasında bastır ve tüm piyade alaylarına tatbiki talim yaptır.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Piyadelerimiz çelik bir disiplin kazandı; düşman süvari hücumları kırıldı."},{"label":"Bizim ecdat nizamımız kafidir; Alman taktiğine ihtiyacımız yok.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Modern Harp Talimnamelerinin Tercümesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Modern Harp Talimnamelerinin Tercümesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Modern Harp Talimnamelerinin Tercümesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 776) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_777', 'ottoman', 'Yerli Kâğıt Değirmeninin Su Çarkı Tahribatı', 'Yalova Kâğıt Fabrikası', 'İbrahim Müteferrika\'nın Yalova\'daki kâğıt değirmeninin bentleri selde yarıldı; kâğıt üretimi durdu.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Hazine bütçesinden bendleri taştan yeniden yaptır; yerli kâğıt üretimini canlandır.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Kâğıt değirmeni dönmeye başladı; matbaaya bol ve ucuz kâğıt aktı."},{"label":"Fabrikayı kapatın; Avrupa\'dan kâğıt ithal etmek daha kolaydır.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Yerli Kâğıt Değirmeninin Su Çarkı Tahribatı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Yerli Kâğıt Değirmeninin Su Çarkı Tahribatı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Yerli Kâğıt Değirmeninin Su Çarkı Tahribatı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 777) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_778', 'ottoman', 'Mekanik Sarkaçlı Saatlerin Cami ve Gemilerde Kullanımı', 'Muvakkithane-i Âmire', 'Namaz vakitlerinin ve deniz boylamlarının tespiti için yerli mekanik sarkaçlı saatlerin üretimi önerildi.', '[{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Saatçi loncasına sermaye ver; muvakkithanelere ve kalyonlara hassas saatler koydur.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Zaman tam dakikasıyla ölçüldü; gemiler denizde boylamını hatasız buldu."},{"label":"Güneş saati asırlardır yetiyor; mekanik saate lüzum yok.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vakıf akarını gasp eden tarafa ağır para cezası kes; Mekanik Sarkaçlı Saatlerin Cami ve Gemilerde Kullanımı hadisesinde toplanan cerimeyi darüşşifa ve imaretin tamir fonuna aktar.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını silahlı neferlerle gönder; Mekanik Sarkaçlı Saatlerin Cami ve Gemilerde Kullanımı hadisesinde vakıf toprağındaki kaçak binaları kazma kürekle yıktırıp gaspa yeltenenleri derdest et.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' neşret; Mekanik Sarkaçlı Saatlerin Cami ve Gemilerde Kullanımı gibi hadiselerin tekerrürünü önleyecek şekilde tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 778) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_779', 'ottoman', 'İlmiye Mensuplarının Ticaret Tekellerine Ortak Olması', 'Kazaskerlik Meclisi', 'Bazı müderris ve kadıların un ve et kapanlarındaki şirketlere gizli ortak olup fahiş fiyatı fetvayla savunduğu belgelendi.', '[{"id":"char_kazasker","name":"Kazasker"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"İlmiye mensuplarının ticarete ortaklığını kesinlikle men et; ortaklığı olan kadıyı azlet.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Yargı sermaye bağından arındırıldı; ekmek ve et fiyatları hakiki narha indi."},{"label":"Âlimlerin para kazanması helaldir deyip ortaklığa divan gözetiminde tarafları meşverete davet edip orta yolu bul.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve İlmiye Mensuplarının Ticaret Tekellerine Ortak Olması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve İlmiye Mensuplarının Ticaret Tekellerine Ortak Olması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve İlmiye Mensuplarının Ticaret Tekellerine Ortak Olması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 779) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_780', 'ottoman', 'Cevdet Paşa\'nın \'Tarih ve Kanun\' Islahat Raporu', 'Dîvân-ı Hümâyûn', 'Devletin çöküşünü önlemek için kanunların açık maddelerle yazılmasını, kadıların ehliyet sınavıyla atanmasını teklif eden büyük layiha sunuldu.', '[{"id":"char_ahmet_cevdet_pasa","name":"Ahmet Cevdet Paşa"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Layihayı derhal kanunlaştır: \'Adalet bilmeyen hâkim, mülkün altındaki dinamittir!\'.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Hukuk devleti kemale erdi; Osmanlı adliyesi cihan çapında örnek oldu."},{"label":"Eski usul tecrübedir; kanunları maddelere bağlayıp kadıları kısıtlamayın.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Cevdet Paşa\'nın \'Tarih ve Kanun\' Islahat Raporu nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Cevdet Paşa\'nın \'Tarih ve Kanun\' Islahat Raporu fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Cevdet Paşa\'nın \'Tarih ve Kanun\' Islahat Raporu meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 780) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_781', 'ottoman', 'Sadrazamın Divan Kararlarını Padişahtan Gizlemesi', 'Bab-ı Âli Sadareti', 'Sadrazamın önemli eyalet tayinlerini ve vergi muafiyetlerini padişahın onayına sunmadan kendi mührüyle fermanlaştırdığı anlaşıldı.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Mühr-i Hümayun\'u sadrazamdan geri al; her fermanın bizzat padişah hatt-ı hümayunuyla çıkmasını emret.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Saray vesayeti kırıldı; padişah devletin dizginlerini bizzat eline aldı."},{"label":"Sadrazam vekil-i mutlaktır; işine karışıp otoritesini sarsma.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sadrazamın Divan Kararlarını Padişahtan Gizlemesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Sadrazamın Divan Kararlarını Padişahtan Gizlemesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Sadrazamın Divan Kararlarını Padişahtan Gizlemesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 781) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_782', 'ottoman', 'Müsadere Edilen Sadrazam Servetinin Vakıflara Aktarılması', 'Topkapı Hazine Odası', 'İdam edilen rüşvetçi sadrazamın sarayından çıkan 50 sandık altının doğrudan hastane ve mektep vakıflarına bağışlanması teklif edildi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Halktan çalınan altına halka iade et: Parayı yetimhanelere, darüşşifalara ve su bentlerine vakfet.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Haram servet mazlumun yarasına merhem oldu; halk hükümdara dua etti."},{"label":"Hepsini padişahın gizli şahsi kasasına aktarın.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Müsadere Edilen Sadrazam Servetinin Vakıflara Aktarılması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Müsadere Edilen Sadrazam Servetinin Vakıflara Aktarılması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Müsadere Edilen Sadrazam Servetinin Vakıflara Aktarılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 782) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_783', 'ottoman', 'Rüşvet Defteri Tutan Divan Kâtibinin İfşası', 'Bâb-ı Âli Divanı', 'Hangi vezirin hangi mültezimden kaç bin altın rüşvet aldığını tek tek kaydeden gizli bir kara kaplı defter ele geçirildi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_divan_katibi","name":"Divan Kâtibi"}]', '[{"label":"Defteri divanda açıkça okut; adı geçen tüm rüşvetçi paşaları azledip yargılat.","preview":"Adalet +8, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":8,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Bürokrasideki rüşvet ağı kökünden temizlendi; devlet kadroları aklandı."},{"label":"Defteri ateşe atın; bu kadar paşayı azledersek devlet başsız kalır.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Rüşvet Defteri Tutan Divan Kâtibinin İfşası nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Rüşvet Defteri Tutan Divan Kâtibinin İfşası fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Rüşvet Defteri Tutan Divan Kâtibinin İfşası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 783) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_784', 'ottoman', 'Halkın Padişahın Atının Önüne Çıkıp Dilekçe Sunması', 'Cuma Selamlığı', 'Cuma namazı yolunda fukara bir kadının elinde yanan meşaleyle padişahın atının önüne atlayıp valiyi şikâyet ettiği görüldü.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Atı durdur, kadının dilekçesini bizzat elinden al; zalim valiyi derhal huzura çağırıp hesaba çek.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Mazlumun ahı yerde kalmadı; tüm taşra valileri titreyip zulmü kesti."},{"label":"Bostancılara emret; kadını atın önünden sürükleyip zindana atsınlar.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Halkın Padişahın Atının Önüne Çıkıp Dilekçe Sunması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Halkın Padişahın Atının Önüne Çıkıp Dilekçe Sunması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Halkın Padişahın Atının Önüne Çıkıp Dilekçe Sunması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 784) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_785', 'ottoman', 'Taşra Ayânlarının Merkeze Karşı Gizli İttifakı', 'Rumeli ve Anadolu', 'Tepedelenli, Karaosmanoğlu ve Çapanoğlu ayânlarının vergi vermemek ve ordu göndermemek için gizlice anlaştığı bildirildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Ayânların arasını diplomasiyle aç, liyakatli olanları sisteme dahil et, direnenlerin ordularını dağıt.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Feodal tehlike bertaraf edildi; devletin tek bir vatan olduğu gösterildi."},{"label":"Ayânların gücünü kabul edip taşrayı tamamen onlara terk edin.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Taşra Ayânlarının Merkeze Karşı Gizli İttifakı nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Taşra Ayânlarının Merkeze Karşı Gizli İttifakı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Taşra Ayânlarının Merkeze Karşı Gizli İttifakı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 785) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_786', 'ottoman', 'Cülus Bahşişi İçin Hazine Sandığının Zorlanması', 'Bab-ı Âli', 'Yeniçeriler tahta çıkan hükümdardan devasa cülus bahşişi istiyor; hazinede para kalmadığı için tağşiş teklif edildi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Tağşişi kesinlikle reddet! Sarayın gümüş tabaklarını darphanede erittir ama paranın ayarıyla oynama.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Piyasa enflasyondan kurtuldu; asker hakkını alırken halk ezilmedi."},{"label":"Bakır karıştırıp hafif akçeyle askeri kandırın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Cülus Bahşişi İçin Hazine Sandığının Zorlanması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Cülus Bahşişi İçin Hazine Sandığının Zorlanması fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Cülus Bahşişi İçin Hazine Sandığının Zorlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 786) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_787', 'ottoman', 'Elçilik Heyetine Devlet Sırrı Sızdıran Saray Görevlisi', 'Topkapı Enderun Kalemi', 'Sefer hazırlığı haritalarını ve cephane miktarlarını Rus elçisine satan bir saray kâtibi altınlarla yakalandı.', '[{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Haini divan kapısında as, elçiliğe sert nota ver ve saraydaki tüm güvenlik nizamını yenile.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Devlet sırları korundu; hain ibret-i âlem olarak cezalandırıldı."},{"label":"Olayı büyütmeyin; kâtibi sessizce taşraya sürgüne yollayın.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Elçilik Heyetine Devlet Sırrı Sızdıran Saray Görevlisi hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Elçilik Heyetine Devlet Sırrı Sızdıran Saray Görevlisi hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Elçilik Heyetine Devlet Sırrı Sızdıran Saray Görevlisi gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 787) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_788', 'ottoman', 'Maliye Bütçesinde İsraf Kalemlerinin Kısılması', 'Maliye Kalemi', 'Saray mutfağı, kürk alımları ve vezir konaklarının devlete fatura edilen debdebe harcamalarının yarıya indirilmesi teklif edildi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Tasarruf fermanını imzala: \'Millet dar boğazdayken sarayda zevk ü sefa sürmek haramdır!\'.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Bütçe fazlası verildi; devletin parası borç yerine üretime ayrıldı."},{"label":"Sarayın ihtişamı devletin itibarıdır; tek akçe dahi kısmayın.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Maliye Bütçesinde İsraf Kalemlerinin Kısılması nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Maliye Bütçesinde İsraf Kalemlerinin Kısılması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Maliye Bütçesinde İsraf Kalemlerinin Kısılması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 788) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_789', 'ottoman', 'Vezirlerin Şahsi Husumet Yüzünden Divanı Kilitlemesi', 'Divan Meclisi', 'Sadrazam ile Şeyhülislamın birbirlerine inat olsun diye kanun layihalarını imzalamayıp devlet işlerini durdurduğu görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_seyhulislam","name":"Şeyhülislam"}]', '[{"label":"İkisini de huzura çekip uyar: \'Devlet şahsi kaprislerin kurbanı olamaz!\' Uzlaşmazlarsa ikisini de azlet.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Bürokratik tıkanıklık dağıtıldı; divan saat gibi tıkır tıkır işlemeye başladı."},{"label":"Aralarına girmeyin; zamanla uzlaşırlar deyip bekleyin.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Vezirlerin Şahsi Husumet Yüzünden Divanı Kilitlemesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Vezirlerin Şahsi Husumet Yüzünden Divanı Kilitlemesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Vezirlerin Şahsi Husumet Yüzünden Divanı Kilitlemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 789) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_790', 'ottoman', 'Zalim Sancak Beyinin Divanda Yargılanması', 'Şikâyet Defteri', 'Köylüleri zincire vurup zorla altınlarını alan sancak beyi, köylülerin feryadı üzerine divana celbedildi.', '[{"id":"char_sancak_beyi","name":"Sancak Beyi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Halkın huzurunda adaletle muhakeme et; suçunu sabit kıl, beyin rütbesini sök ve zindana at.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Taşra zorbalığına ölümcül darbe vuruldu; millet adaletin gücünü gördü."},{"label":"Bey asilzadedir; köylülerin önünde küçük düşürmeyip affedin.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zalim Sancak Beyinin Divanda Yargılanması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Zalim Sancak Beyinin Divanda Yargılanması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Zalim Sancak Beyinin Divanda Yargılanması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 790) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_791', 'ottoman', 'Kanunnâme-i Âl-i Osman\'ın Taşrada İlanı', 'Defterhâne-i Âmire', 'Fatih\'in ve Kanuni\'nin adalet fermanlarının mermer levhalara kazınıp her kaza meydanına dikilmesi teklif edildi.', '[{"id":"char_divan_katibi","name":"Divan Kâtibi"},{"id":"char_sadrazam","name":"Sadrazam"}]', '[{"label":"Mermer levhaları diktir: \'Her vatandaş kanun önünde eşittir, hiçbir bey kanunun üstünde değildir!\'.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Hukuk devleti taşraya mühürlendi; keyfi idarecilerin nefesi kesildi."},{"label":"Kanun taşlara yazılmaz; masrafa gerek yok.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Kanunnâme-i Âl-i Osman\'ın Taşrada İlanı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Kanunnâme-i Âl-i Osman\'ın Taşrada İlanı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kanunnâme-i Âl-i Osman\'ın Taşrada İlanı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 791) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_792', 'ottoman', 'Padişahın Derviş Kılığında Fırınları Teftiş Etmesi', 'Tebdil-i Kıyafet Teftişi', 'Padişah derviş kılığında bir fırından aldığı ekmeğin çiğ ve eksik gramajlı olduğunu bizzat kendi gözüyle gördü.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Hileyi yapan fırıncıyı derhal tecziye et, un kapanı nazırını azlet ve denetimleri gece gündüz sürdür.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Hükümdarın teftişi şehri titretti; ekmekler tam gramajlı ve tertemiz çıktı."},{"label":"Padişahın fırın denetlemesi saltanat şanına uymaz; bir daha tebdile çıkma.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Padişahın Derviş Kılığında Fırınları Teftiş Etmesi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Padişahın Derviş Kılığında Fırınları Teftiş Etmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Padişahın Derviş Kılığında Fırınları Teftiş Etmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 792) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_793', 'ottoman', 'Genç Subaylar ile Yaşlı Paşaların Fikir Çatışması', 'Meşveret Meclisi', 'Modern harp taktiklerini savunan genç subaylar ile eski kılıç nizamını savunan paşalar mecliste birbirine girdi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Dengeyi kur: Yaşlıların tecrübesiyle gençlerin modern fenni ilmini birleştiren ortak komuta heyeti kur.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Ordu hem tecrübeyi hem fenni kazandı; muharebe meydanında zaferler aktı."},{"label":"Gençleri susturun; yaşlı paşaların dediğinden şaşmayın.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Genç Subaylar ile Yaşlı Paşaların Fikir Çatışması sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Genç Subaylar ile Yaşlı Paşaların Fikir Çatışması meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Genç Subaylar ile Yaşlı Paşaların Fikir Çatışması gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 793) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_794', 'ottoman', 'Saray Kadınlarının Siyasete Müdahalesinin Yasaklanması', 'Harem Teşrifatı', 'Harem kethüdalarının sadrazam ve vezir tayinlerine müdahale etmesini kesinlikle yasaklayan kanunname teklif edildi.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Kanunu tasdikle: \'Devlet idaresi sadece divanın ve ehil ricalin işidir, harem siyasete karışamaz!\'.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Saray entrikaları kapı dışarı edildi; meşru bürokrasi huzur buldu."},{"label":"Haremdeki validelerin ricalarını kırmayın; idareye ortak olsunlar.","preview":"Reaya +9, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Saray Kadınlarının Siyasete Müdahalesinin Yasaklanması nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Saray Kadınlarının Siyasete Müdahalesinin Yasaklanması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Saray Kadınlarının Siyasete Müdahalesinin Yasaklanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 794) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_795', 'ottoman', 'Gayrimüslim Tebaanın İbadet Hürriyetinin Teyidi', 'Şeyhülislamlık', 'Fanatik bir grubun kiliseleri kapatma talebine karşı Şeyhülislam, Fatih Sultan Mehmed\'in Bosna Ahidnâmesini divana getirdi.', '[{"id":"char_seyhulislam","name":"Şeyhülislam"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Ahidnâmeyi öpüp başına koy: \'Zimmîlerin canı, malı ve mabetleri bize emanettir!\' Taassuba geçit verme.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Toplumsal barış korundu; gayrimüslim tebaa devlete canla başla bağlandı."},{"label":"Fanatiklerin talebini dinleyin; kiliseleri kapatın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Gayrimüslim Tebaanın İbadet Hürriyetinin Teyidi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Gayrimüslim Tebaanın İbadet Hürriyetinin Teyidi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gayrimüslim Tebaanın İbadet Hürriyetinin Teyidi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 795) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_796', 'ottoman', 'Umran Kanunu: Düşük Vergi, Yüksek Hasılat', 'İbn Haldun\'un Hikmeti', 'Mukaddime\'de yazılı iktisat kanunu hatırlatıldı: \'Devletin başında vergi oranları düşük, hasılat yüksektir; çöküşte ise oranlar yüksek, hasılat sıfırdır!\'', '[{"id":"char_ibn_haldun","name":"İbn Haldun"}]', '[{"label":"Vergi oranlarını düşür, üretimi teşvik et; tebaanın kazanıp zenginleşmesine izin ver.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"İktisadi mucize gerçekleşti; üretim patladı, hazine düşük vergiyle dolup taştı."},{"label":"Vergi oranlarını artırın; hazinenin bugünkü paraya ihtiyacı var.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Umran Kanunu: Düşük Vergi, Yüksek Hasılat hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Umran Kanunu: Düşük Vergi, Yüksek Hasılat hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Umran Kanunu: Düşük Vergi, Yüksek Hasılat gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 796) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_797', 'ottoman', 'Mazlumun Ahı ile Hükümdarın Tacı', 'Nizamülmülk\'ün Siyasetnâmesi', 'Siyasetnâme\'nin kurucu öğüdü divanda yankılandı: \'Küfür ile mülk devam eder, lakin zulüm ile devam etmez!\'', '[{"id":"char_nizamulmulk","name":"Nizamülmülk"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Hükmünü adalet üzere ver: Mazlumun karşısında padişah dahi olsa boynunu büküp hakkı teslim et.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Hukukun üstünlüğü mutlak kılındı; adalet mülkün sarsılmaz temeli oldu."},{"label":"Devletin bekası için bazen zulüm şarttır de.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Mazlumun Ahı ile Hükümdarın Tacı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Mazlumun Ahı ile Hükümdarın Tacı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Mazlumun Ahı ile Hükümdarın Tacı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 797) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_798', 'ottoman', 'Liyakat ve Emanet Prensibi', 'Mâverdî\'nin Ahkâmü\'s-Sultâniyyesi', 'Klasik kamu hukukunun babası Mâverdî sorar: \'Emaneti ehline vermeyen, iş başına ehil olmayan akrabasını getiren hükümdar meşru kalabilir mi?\'', '[{"id":"char_maverdi","name":"Mâverdî"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"\'Emanetleri mutlaka ehline veriniz!\' emrine uy; bütün akraba ve torpilli tayinleri iptal edip liyakati tek kıstas yap.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Bürokrasi dâhiler ve erdemli insanlarla doldu; devlet çarkı kusursuz işledi."},{"label":"Sadakat liyakatten mühimdir; bana sadık akrabalarımı makamlara koyarım de.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Liyakat ve Emanet Prensibi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Liyakat ve Emanet Prensibi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Liyakat ve Emanet Prensibi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 798) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_799', 'ottoman', 'Büyük Nizamın Sekiz Direği', 'Kınalızâde Ali Çelebi\'nin Dâire-i Adliyyesi', 'Ahlâk-ı Alâî müellifi divana çıkar: \'Ey Hükümdar! Adalet bağını devlet korur, devleti şeriat kurar, şeriatı mülk tutar, mülkü ordu zapteder, orduyu mal besler, malı reaya üretir, reayayı ise ancak ADALET devlete bağlar!\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"ÇEMBERİ EBEDİYEN BİRLEŞTİR: \'BU HALKALARIN BİRİ BİLE KOPARSA CİHAN NİZAMI YIKILIR!\'.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Adalet çemberi kemale erdi; mülk dünya durdukça yaşayacak kusursuz bir nizama kavuştu."},{"label":"Bu felsefi laflarla devlet yönetilmez; gücün yettiğini ez, gerisini boş ver.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Büyük Nizamın Sekiz Direği meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Büyük Nizamın Sekiz Direği hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Büyük Nizamın Sekiz Direği gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 799) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_800', 'ottoman', 'Ebed-Müddet Mühür: İnsanı Yaşat ki Devlet Yaşasın!', 'Nizâm-ı Âlem Tacı', 'Sekiz yüz vakalık büyük adalet imtihanının nihai zirvesi: Kınalızâde, İbn Haldun, Nizamülmülk ve Şeyh Edebali tek bir sesle seslenir: Mülk kılıçla kurulur, lakin ancak ve ancak ADALETLE yaşar!', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"}]', '[{"label":"SON FERMANI MÜHÜRLE: \'ADALET MÜLKÜN TEMELİDİR, ZULÜM İSE MÜLKÜN ZEVALİDİR!\'.","preview":"Adalet +6, Reaya +7 | Hazine -4, Otorite -2","effects":{"justice":6,"people":7,"treasury":-4,"military":0,"authority":-2},"log":"Adalet çemberi kainat nizamıyla kenetlendi; cihanşümul sulh, adalet ve saadet tecelli etti."},{"label":"Kuvvet benimdir, dilediğimi ezerim.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Ebed-Müddet Mühür: İnsanı Yaşat ki Devlet Yaşasın! nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Ebed-Müddet Mühür: İnsanı Yaşat ki Devlet Yaşasın! fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Ebed-Müddet Mühür: İnsanı Yaşat ki Devlet Yaşasın! meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 800) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_801', 'ottoman', 'Şahi Topların Dökümünde Kalay Oranının Düşürülmesi', 'Tophane-i Âmire', 'Tophane kethüdasının İngiliz kalayı yerine ucuz kurşun karıştırarak döktürdüğü bronz topların, ilk prova atışında namlu ağzından yarıldığı görüldü.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kethüdayı azlet, hileli namluları derhal erittir ve saf İngiliz kalayı ile yeniden döktür.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Toplar sağlam döküldü; topçu neferlerinin canı ve kalelerin istihkâmı kurtarıldı."},{"label":"Kusurlu topları hafif barutla talimde kullanın; dökmek masraflıdır.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Şahi Topların Dökümünde Kalay Oranının Düşürülmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Şahi Topların Dökümünde Kalay Oranının Düşürülmesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Şahi Topların Dökümünde Kalay Oranının Düşürülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 801) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_802', 'ottoman', 'Simli Kurşun Ocaklarında Taban Suyunun Yükselmesi', 'Keban Maden-i Hümâyûnu', 'Keban maden ocaklarının en zengin gümüşlü kurşun damarını yeraltı suları bastı; su tulumbaları için bütçe tahsis edilmezse maden kapanacak.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Maden bütçesinden su tulumbası ve atlı çarklar kurdur; madencilerin emniyetini sağla.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -4","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-4},"log":"Galeri kurutuldu; darphaneye gümüş, cephaneliğe kurşun sevkiyatı kesilmedi."},{"label":"Ocağı kapatın; su çekmekle uğraşılmaz.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Simli Kurşun Ocaklarında Taban Suyunun Yükselmesi meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Simli Kurşun Ocaklarında Taban Suyunun Yükselmesi hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Simli Kurşun Ocaklarında Taban Suyunun Yükselmesi gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 802) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_803', 'ottoman', 'Güherçile Tasfiyesinde Kireç Hilesi', 'Bakırköy Baruthanesi', 'Müteahhidin baruthaneye teslim ettiği güherçilenin içine beyaz kireç tozu kattığı, barutun tutuşma süratinin yarı yarıya düştüğü belgelendi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Müteahhidi küreğe koy, tüm partiyi imha et ve Kayseri\'den saf kaya güherçilesi getirt.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Tüfekler ıslak havada dahi şimşek gibi ateş aldı; ordunun ateş gücü korundu."},{"label":"Barut baruttur; idareten harmanlayıp kalede saklayın.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Güherçile Tasfiyesinde Kireç Hilesi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Güherçile Tasfiyesinde Kireç Hilesi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Güherçile Tasfiyesinde Kireç Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 803) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_804', 'ottoman', 'Su Çarklı Ağır Tokmakların Dingil Kırılması', 'Samakov Demirhanesi', 'Zırh ve kalkan levhalarını döven büyük su çarkının kara gürgen dingili kırıldı; kılıç üretimi durdu.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Rodoslu döküm ustalarını görevlendir; kırılmayan çelik dingil döktür ve üretimi hızlandır.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Demirhane çelikten çarklarla dönmeye başladı; orduya her gün yüz zırh dövüldü."},{"label":"İşçiler el balyozlarıyla dövsün; çarka masraf yapmayın.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Su Çarklı Ağır Tokmakların Dingil Kırılması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Su Çarklı Ağır Tokmakların Dingil Kırılması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Su Çarklı Ağır Tokmakların Dingil Kırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 804) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_805', 'ottoman', 'Maden Köylülerinin Aşırı Ağır Odun Angaryası', 'Küre Bakır Madeni', 'Bakır fırınlarını yakmak için çevre köylülerin sırtında fersahlarca uzaktan odun taşıtıldığı, tarlaların boş kaldığı şikâyet edildi.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Odun nakliyesini ücrete bağla, köylünün vergi borcundan düş ve katır arabaları tahsis et.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Köylü angaryadan kurtuldu; madene düzenli yakacak akışı sağlandı."},{"label":"Devletin madenidir; köylü sırtında odun taşımaya mecburdur.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Maden Köylülerinin Aşırı Ağır Odun Angaryası hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Maden Köylülerinin Aşırı Ağır Odun Angaryası hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Maden Köylülerinin Aşırı Ağır Odun Angaryası gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 805) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_806', 'ottoman', 'Kenevir Liflerinin Yağlanmasında Çürük Balık Yağı', 'Tersane Halathanesi', 'Kalyon halatları bükülürken yumuşatıcı olarak kullanılan beziryağı yerine bayat balık yağı sürülmesi yüzünden halatların ambarlarda çürüdüğü anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Hileli halatçıbaşını cezalandır, çürük halatları söktür ve saf beziryağıyla yenilerini bük.","preview":"Adalet +8, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":8,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Kalyon palamarları çelik gibi sağlam oldu; fırtınada tek bir demir halatı kopmadı."},{"label":"Halat halattır; bu seferlik donanmaya takın.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":6,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Kenevir Liflerinin Yağlanmasında Çürük Balık Yağı nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Kenevir Liflerinin Yağlanmasında Çürük Balık Yağı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Kenevir Liflerinin Yağlanmasında Çürük Balık Yağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":8,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 806) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_807', 'ottoman', 'Tüfek Namlularına Dökme Demir Kaynatılması', 'Cebeci Kışlaları', 'Cebecilerin namluları dövme çelik yerine dökme demirden yaptığı ve namluların üçüncü atışta ortadan yarıldığı tespit edildi.', '[{"id":"char_cebecibasi","name":"Cebecibaşı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Hileli dökümleri toplat, Cebecibaşıyı azlet ve dövme çelik namlu nizamnamesini uygulat.","preview":"Adalet +7, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":7,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Askerin elindeki tüfekler emniyete kavuştu; talimlerde kaza yaşanmadı."},{"label":"Dökme demir ucuzdur; neferler az barut koysun.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Tüfek Namlularına Dökme Demir Kaynatılması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Tüfek Namlularına Dökme Demir Kaynatılması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Tüfek Namlularına Dökme Demir Kaynatılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 807) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_808', 'ottoman', 'Cevher Ergitme Ocaklarında Gümüşün Havaya Uçması', 'Gümüşhane Darphanesi', 'Baca filtreleri tıkandığı için eriyen kurşunlu gümüşün dumanla havaya karıştığı, hem hazinenin zarar gördüğü hem de köyün zehirlendiği bildirildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"}]', '[{"label":"Taş dinlendirme bacaları ve su filtreleri kurdur; gümüş tozunu bacada tut, köyü zehirden kurtar.","preview":"Adalet +6, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":6,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Bacadan gümüş geri kazanıldı; köylü zehirli dumandan kurtulup devlete dua etti."},{"label":"Madenin dumanı böyle olur; bacaya para harcamayın.","preview":"Reaya +6, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Cevher Ergitme Ocaklarında Gümüşün Havaya Uçması meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Cevher Ergitme Ocaklarında Gümüşün Havaya Uçması hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Cevher Ergitme Ocaklarında Gümüşün Havaya Uçması gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 808) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_809', 'ottoman', 'Kalyon Bordalarına Zırh Levhaları Takılması Teklifi', 'Tersane-i Âmire', 'Mühendishane hocaları, su kesimi hizasına dövme demir plakalar çakılırsa düşman kalyonlarının güllelerinin sekeceğini hesapladı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Bütçe ayır; ilk iki kalyonun bordasını zırhla tahkim ettirip açık denizde tecrübe et.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Donanmamız zırhlı kalyon çağına adım attı; düşman gülleleri bordadan sekti."},{"label":"Gemi ağırlaşır ve alabora olur; ahşap bordadan şaşmayın.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Kalyon Bordalarına Zırh Levhaları Takılması Teklifi nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Kalyon Bordalarına Zırh Levhaları Takılması Teklifi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kalyon Bordalarına Zırh Levhaları Takılması Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 809) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_810', 'ottoman', 'Maden Galerilerinde Çökme ve Mahsur Kalan İşçiler', 'Divriği Demir Madeni', 'Destek direklerinin çürük konması yüzünden göçük altında kalan 30 madenci işçinin kurtarılması için acil tünel açılması gerekiyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Asker istihkâmcılarını ve maden ustalarını derhal seferber et; masrafı düşünmeden canları kurtar.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Bütün madenciler sağ salim çıkarıldı; devletin şefkati tebaayı gözyaşına boğdu."},{"label":"Ocağı kapatın; kurtarma ameliyesi yeni göçüklere yol açar.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Maden Galerilerinde Çökme ve Mahsur Kalan İşçiler nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Maden Galerilerinde Çökme ve Mahsur Kalan İşçiler fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Maden Galerilerinde Çökme ve Mahsur Kalan İşçiler meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 810) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_811', 'ottoman', 'Mermer Taş Güllelerin Yerine Demir Döküm Gülle Talebi', 'Tophane Dökümhanesi', 'Kale surlarına atılan mermer güllelerin taşa çarpınca parçalandığı, dökme demir güllelerin ise surları un gibi dağıttığı bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Samakov ve Bilecik demir ocaklarına sipariş ver; orduyu tamamen demir gülleyle donat.","preview":"Adalet +6, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":6,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Kuşatma tabyalarımızın tahrip gücü üç katına çıktı; kaleler süratle teslim alındı."},{"label":"Marmara mermeri boldur; mermer yontmaya devam edin.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Mermer Taş Güllelerin Yerine Demir Döküm Gülle Talebi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Mermer Taş Güllelerin Yerine Demir Döküm Gülle Talebi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Mermer Taş Güllelerin Yerine Demir Döküm Gülle Talebi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 811) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_812', 'ottoman', 'Kömür Ocağında Çıkan Yeraltı Yangını', 'Bilecik Demir Ocakları', 'Demir eritmek için kazılan maden galerisinde kükürtlü kömür damarı alev aldı; duman ovadaki köyleri boğuyor.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Derhal nehir yatağını kısmen çevirip ocağı suyla boğdur, ardından suyu tahliye et.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Yeraltı yangını söndürüldü; ovadaki tarım ve köy havası kurtarıldı."},{"label":"Kendi haline bırakın; yeraltındaki ateş elbet bir gün söner.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kömür Ocağında Çıkan Yeraltı Yangını nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kömür Ocağında Çıkan Yeraltı Yangını fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kömür Ocağında Çıkan Yeraltı Yangını meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 812) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_813', 'ottoman', 'Güherçile Toplayıcılarının Köy Mezarlıklarını Eşelemesi', 'Kütahya Güherçilehanesi', 'Güherçile simsarlarının azot bakımından zengin diye kadim köy kabirlerindeki toprağı gizlice kazıp çuvalladığı ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Bu alçaklığı yapanları derhal yakalatıp zindana at; mezarlık toprağından barut yapılmasını men et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Kabristan tecavüzü cezalandırıldı; halkın manevi mukaddesatı korundu."},{"label":"Baruta hammadde lazımdır; nereden bulurlarsa bulsunlar.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Güherçile Toplayıcılarının Köy Mezarlıklarını Eşelemesi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Güherçile Toplayıcılarının Köy Mezarlıklarını Eşelemesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Güherçile Toplayıcılarının Köy Mezarlıklarını Eşelemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 813) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_814', 'ottoman', 'Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması', 'Tersane-i Âmire', 'Depodaki dev meşe direklerinin böceklenmemesi için sıcak çam katranı havuzlarına yatırılması gerektiği bildirildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Katran havuzlarını hazırla; direkleri usulünce kaynatıp ömrünü yirmi yıla çıkar.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Direkler taş gibi sertleşti; fırtınalarda tek bir kalyon direksiz kalmadı."},{"label":"Direkler kurudur, katrana lüzum yok deyip ambara yığın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tüccar gemilerinden toplanan emniyet harçlarını doğrudan tersaneye tahsis et; Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması hadisesine karşı sahil kaleleri ve donanma kalyonlarını bu bütçeyle donat.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kapudan-ı Derya\'ya kesin emir ver; Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması hadisesinde ferman tanımaz korsan ve kaçakçı gemilerini batırıp reislerini küreğe mahkûm et.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tersane-i Âmire ve Bahriye Kanunnâmesi\' neşret; Kalyon Direklerinin Kurtlanmaya Karşı Katranlanması gibi hadiselerin tekerrürünü önleyecek şekilde deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 814) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_815', 'ottoman', 'Kış Soğuğunda Tüfek Yağlarının Donması', 'Erzurum Cephaneliği', 'Kars hududundaki neferlerin tüfek mekanizmalarının donduğu, tetiğin düşmediği; ayı yağı veya saf bezir gerektiği bildirildi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Trabzon üzerinden özel donmayan yağ fıçıları yetiştir; tüfek mekanizmalarını elden geçirt.","preview":"Adalet +6, Reaya +9 | Hazine -2, Otorite -3","effects":{"justice":6,"people":9,"treasury":-2,"military":0,"authority":-3},"log":"Tüfekler eksi otuz derecede tıkır tıkır ateş aldı; hudut nöbeti aksamadı."},{"label":"Asker namluları nefesiyle ısıtsın; hususi yağa para ayrılmaz.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kış Soğuğunda Tüfek Yağlarının Donması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kış Soğuğunda Tüfek Yağlarının Donması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kış Soğuğunda Tüfek Yağlarının Donması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 815) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_816', 'ottoman', 'Kalyon Küreklerinde Çam Yerine Ağır Kayın Kullanımı', 'Sinop Tersanesi', 'Müteahhidin ucuz diye ağır kayın ağacından kürek yontturduğu, forsa ve leventlerin iki saatte kollarının koptuğu anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Kayın kürekleri söktür, Karadeniz çamından hafif ve esnek kürekler yonttur.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Kadırgaların manevra hızı iki katına çıktı; kürekçiler yorulmadan asıldı."},{"label":"Ağır kürek kuvvet verir; neferler alışsın.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Kalyon Küreklerinde Çam Yerine Ağır Kayın Kullanımı nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Kalyon Küreklerinde Çam Yerine Ağır Kayın Kullanımı fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Kalyon Küreklerinde Çam Yerine Ağır Kayın Kullanımı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 816) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_817', 'ottoman', 'Barut Değirmenlerinde Demir Tokmak Yasağı', 'Baruthane-i Âmire', 'Barut karıştırılan dibeklerde demir tokmak kullanıldığı, kıvılcım çıkıp değirmeni havaya uçurma tehlikesi olduğu bildirildi.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"},{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Derhal bronz ve meşe tokmaklar yaptır; demir aletle baruthaneye girmeyi yasakla.","preview":"Adalet +8, Reaya +6 | Hazine -3, Otorite -4","effects":{"justice":8,"people":6,"treasury":-3,"military":0,"authority":-4},"log":"Büyük bir patlama faciası önlendi; barut üretimi emniyete kavuştu."},{"label":"İşçiler dikkatli vursun; tokmak değiştirmeye masraf yapmayın.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Barut Değirmenlerinde Demir Tokmak Yasağı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Barut Değirmenlerinde Demir Tokmak Yasağı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Barut Değirmenlerinde Demir Tokmak Yasağı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 817) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_818', 'ottoman', 'Maden Eriyik Bacalarının Zehirli Gazı', 'Keban Madeni', 'Kurşun izabe fırınlarından çıkan gazların Fırat kenarındaki köylerde hayvanları telef ettiği, çocukları hasta ettiği bildirildi.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Fırınları yüksek rüzgâr tepelerine taşıt ve taş dinlendirme kanalları kurdur.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Köylülerin sağlığı korundu; maden çevreye zarar vermeden üretime devam etti."},{"label":"Madenin yanına yerleşmeselerdi; köylüler taşınsın.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Maden Eriyik Bacalarının Zehirli Gazı nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Maden Eriyik Bacalarının Zehirli Gazı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Maden Eriyik Bacalarının Zehirli Gazı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 818) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_819', 'ottoman', 'Yivli ve Setli Namlu İcadı Teklifi', 'Tophane Dökümhanesi', 'Mühendishane kalfası, namlunun içine helezonik yiv açılırsa güllelerin iki kat menzile ve nokta isabetle gideceğini ispatladı.', '[{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Kalfayı altınla taltif et; Tophane\'de yiv açma tezgâhları kurdurup orduyu donat.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Topçulukta çağ atlandı; düşman bataryaları menzilimize giremeden vuruldu."},{"label":"Düz namlu asırlardır kâfidir; yeni usuller kafaları karıştırır.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Yivli ve Setli Namlu İcadı Teklifi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Yivli ve Setli Namlu İcadı Teklifi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Yivli ve Setli Namlu İcadı Teklifi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 819) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_820', 'ottoman', 'Madenler ve Harp Levazımı Kanunnâmesi', 'Dîvân-ı Hümâyûn', 'İmparatorluktaki tüm kömür, demir, bakır, kurşun ve güherçile ocaklarını tek bir nizam altında toplayan kanunname hazırlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Kanunu mühürle: \'Madenler mülkün kalkanıdır; tek bir cevher dahi ziyan edilemez!\'.","preview":"Adalet +8, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":8,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Harp sanayiimiz sarsılmaz bir nizam kazandı; dışa bağımlılık tamamen kırıldı."},{"label":"Madenleri mültezimlere bırakın; devlet memurlarla uğraşmasın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Madenler ve Harp Levazımı Kanunnâmesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Madenler ve Harp Levazımı Kanunnâmesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Madenler ve Harp Levazımı Kanunnâmesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 820) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_821', 'ottoman', 'Gedik Hakkının İhalesi ve Rüşvet', 'Ahi Ocakları', 'Boşalan kuyumcu gediği için Ahi şeyhinin rüşvet aldığı, en mahir kalfa yerine zengin bir sarraf çırağına berat verdiği ortaya çıktı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Gedik beratını iptal et, Şeyhi divanda hesaba çek ve dükkânı açık imtihanla kazanan kalfaya ver.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Ahi ocağına adalet geri geldi; zanaat erbabının devlete olan itimadı tazelendi."},{"label":"Ahi şeyhinin tasarrufudur; loncanın iç işine divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Gedik Hakkının İhalesi ve Rüşvet nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Gedik Hakkının İhalesi ve Rüşvet fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Gedik Hakkının İhalesi ve Rüşvet meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 821) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_822', 'ottoman', 'Koyun İşkembelerinin Mahalle Çeşmelerinde Temizlenmesi', 'İstanbul Kasapbaşı', 'Kasap çıraklarının sokak çeşmelerinde işkembe yıkayarak mahallenin içme suyunu kirlettiği ve koku yaydığı şikâyet edildi.', '[{"id":"char_kasap_esnafi","name":"Kasap Esnafı"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Çeşmelerde sakatat yıkamayı yasakla; mezbaha içinde hususi yıkama havuzları kurdur, uymayanı cezalandır.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Mahalle suları temizlendi; pis koku ve tifo tehlikesi ortadan kalktı."},{"label":"Kasaplar nerede yıkasın; sokak çeşmesine divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Koyun İşkembelerinin Mahalle Çeşmelerinde Temizlenmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Koyun İşkembelerinin Mahalle Çeşmelerinde Temizlenmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Koyun İşkembelerinin Mahalle Çeşmelerinde Temizlenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 822) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_823', 'ottoman', 'Kapan Kânûnuna Aykırı Toptan Buğday Kapatma', 'Un Kapanı Kâhyalığı', 'Büyük bir tüccarın limana yanaşan Kırım buğday gemilerini kapana sokmadan açıkta toptan satın alıp depoladığı tespit edildi.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"Bütün buğdaya el koy, kapana çektirip narh üzerinden halka dağıt; vurguncuyu sürgün et.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Karaborsa vurgunu durduruldu; payitahtta ekmek fiyatları anında düştü."},{"label":"Tüccar parasını vermiştir; serbest ticarettir deyip izin verin.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Kapan Kânûnuna Aykırı Toptan Buğday Kapatma sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Kapan Kânûnuna Aykırı Toptan Buğday Kapatma hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Kapan Kânûnuna Aykırı Toptan Buğday Kapatma gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 823) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_824', 'ottoman', 'Testi ve Kaplarda Kurşunlu Sır Zehirlenmesi', 'Eyüp Çömlekçileri', 'Çömlek ustalarının parlasın diye kapların içine sürdüğü kalitesiz kurşun sırrının yoğurt ve sirkeyi zehirlediği hekimlerce bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"Kurşun sırrı yasakla; çömlekleri kalay ve kuvars sırrıyla denetlet, uymayan fırınları yıktır.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Halk zehirlenmekten kurtuldu; çömlekçi esnafı sıhhi üretime geçti."},{"label":"Çömlek ucuz olsun; halk sirke koymasın de.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Testi ve Kaplarda Kurşunlu Sır Zehirlenmesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Testi ve Kaplarda Kurşunlu Sır Zehirlenmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Testi ve Kaplarda Kurşunlu Sır Zehirlenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 824) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_825', 'ottoman', 'Tabakhane Havuzlarının Şehir İçine Taşması', 'Debbağlar Loncası', 'Yedikule debbağhanelerindeki gübreli ve kireçli dinlendirme havuzlarının taşarak çevre mahalleleri yaşanmaz kıldığı bildirildi.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Havuzları surların uzağına, deniz kıyısına taşıt; kapalı arıtma kanalları açtır.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Mahalleler pis kokudan kurtuldu; deri sanayii intizamla çalıştı."},{"label":"Debbağlar asırlardır oradadır; taşınma masrafı çıkarmayın.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Liman gümrük tarifelerini revize et; emniyetli ticaret yapan bezirgânlara navlun kolaylığı sağlayıp donanma payını tahsil et ve Tabakhane Havuzlarının Şehir İçine Taşması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tersane disiplinini bozan kalyon reislerini görevden al; deniz haydutlarına yardım eden liman muhafızlarını prangaya vur ve Tabakhane Havuzlarının Şehir İçine Taşması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Tabakhane Havuzlarının Şehir İçine Taşması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 825) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_826', 'ottoman', 'Bal Peteğine İri Balmumu Levha Eklenmesi', 'Balkapanı Nazırlığı', 'Arıcıların arıya bal yaptırmak yerine peteğin ortasına kalın yapay mum tabakası koyup bal miktarını azalttığı görüldü.', '[{"id":"char_debbag","name":"Debbağ (Deri Ustası)"}]', '[{"label":"Hileli petekleri imha et; saf süzme bal ve tabii petek nizamını sıkı muhtesip kontrolüne al.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Halk bal yerine mum yemekten kurtuldu; dürüst arıcılar korundu."},{"label":"Petektir, mum da baldan sayılır deyip ceza kesme.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını ihlal eden esnafa ağır para cezası kes; Bal Peteğine İri Balmumu Levha Eklenmesi hadisesinde toplanan akçeleri Ahi esnaf sandığına ve kamu imaretine irad kaydet.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip ve yeniçeri çavuşlarıyla çarşıya baskın yap; Bal Peteğine İri Balmumu Levha Eklenmesi hadisesinde tartıda hile yapanları esnaf önünde teşhir edip dükkânlarını mühürlet.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Lonca ve Gedik Teşkilatı Nizamı\' neşret; Bal Peteğine İri Balmumu Levha Eklenmesi gibi hadiselerin tekerrürünü önleyecek şekilde esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":6,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 826) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_827', 'ottoman', 'Yük Beygirlerine Küçük Nal Çakılması', 'Nalbandlar Loncası', 'Nalbandların büyük tırnaklı atlara küçük nal çakarak tırnakları kestiği, beygirlerin yürüyemez hale geldiği belgelendi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"}]', '[{"label":"Nalband kethüdasına denetim emri ver; tırnağa göre nal çakmayan ustayı meslekten men et.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Taşımacı hayvanların eziyeti dindi; şehir lojistiği aksamadan yürüdü."},{"label":"Ustanın bileceği iştir; hayvanın nallanmasına divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Yük Beygirlerine Küçük Nal Çakılması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Yük Beygirlerine Küçük Nal Çakılması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Yük Beygirlerine Küçük Nal Çakılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 827) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_828', 'ottoman', 'Çeyiz Sandıklarında Çürük Ihlamur Tahtası', 'Kapalıçarşı Sandıkçıları', 'Sandıkçıların dışını sedefle süsleyip içini kurtlu kavak tahtasından yaptığı, içine konan ipek elbiselerin kurtlandığı şikâyet edildi.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Sandıkların içine kurt kovucu saf sedir ve ceviz şartı koy; hileli sandıkları imha ettir.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -4","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-4},"log":"Genç kızların çeyizleri kurtlanmaktan kurtuldu; marangozlar dürüstleşti."},{"label":"Dışı süslüdür, içine kimse bakmaz deyip esnafı kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Çeyiz Sandıklarında Çürük Ihlamur Tahtası nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Çeyiz Sandıklarında Çürük Ihlamur Tahtası fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Çeyiz Sandıklarında Çürük Ihlamur Tahtası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 828) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_829', 'ottoman', 'Kaldırımlara Taşarak Yolu Kapatan Manav Tezgâhları', 'İstanbul Şehremaneti', 'Manavların meyve kasalarını sokak ortasına kadar yığdığı, yangın tulumbacılarının dar sokaklardan geçemediği bildirildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Sokak hizasını tavizsiz uygula; kasalarını yola taşıran manavın malını müsadere et.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Sokaklar açıldı; yangın tulumbaları ve ambulans sedyeleri hızla geçti."},{"label":"Esnaf ekmek parası kazanıyor; yola kasasını koysun.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Kaldırımlara Taşarak Yolu Kapatan Manav Tezgâhları hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Kaldırımlara Taşarak Yolu Kapatan Manav Tezgâhları hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Kaldırımlara Taşarak Yolu Kapatan Manav Tezgâhları gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 829) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_830', 'ottoman', 'Altın Zincirlerde Bakır Lehim Hilesi', 'Kuyumcular Loncası', 'Kuyumcuların altın zincir halkalarını saf altın yerine kalın bakır lehimle kaynatıp altın gramajından çaldığı anlaşıldı.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Ateşte lehim eritme testi uygulat; hileli zincir satan sarrafın ruhsatını iptal et.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Altın ziynetlerde sahtecilik bitti; halkın birikimi teminata alındı."},{"label":"Lehimsiz zincir olmaz deyip teftişi savsaklayın.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İltizam müzayedelerinde peşin teminat şartı getir; mültezimlerin devlete olan birikmiş borçlarını rehin mallarından tahsil et ve Altın Zincirlerde Bakır Lehim Hilesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hazinesine olan borcunu ödemeyen zorba mültezimlerin köşklerini kuşat; servetlerini müsadere edip kendilerini zincire vur ve Altın Zincirlerde Bakır Lehim Hilesi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Darphane ve Meskûkât Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Altın Zincirlerde Bakır Lehim Hilesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 830) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_831', 'ottoman', 'Kandil Yağına Bezir Karıştırılarak Zeytinyağı Diye Satılması', 'Yağ Kapanı Kâhyalığı', 'Zeytinyağı tenekelerine acı beziryağı karıştırıldığı, salatalarda ve yemeklerde kullananların midesinin yandığı tespit edildi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Tenekeleri tahlil ettir; acı yağ karıştıran simsarların mallarını imha edip hapis cezası ver.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Mutfak güvenliği korundu; zeytinyağında hile kökünden kesildi."},{"label":"Yağ kıttır; millet yesin bir şey olmaz de.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Kandil Yağına Bezir Karıştırılarak Zeytinyağı Diye Satılması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Kandil Yağına Bezir Karıştırılarak Zeytinyağı Diye Satılması fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kandil Yağına Bezir Karıştırılarak Zeytinyağı Diye Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 831) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_832', 'ottoman', 'İpek İpliğinin Nemlendirilerek Tartılması', 'Bursa İpekçileri', 'Tüccarların ham ipek çilelerini nemli bodrumlarda bekleterek tartıda %20 ağır gelmesini sağladığı belgelendi.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kurutma fırını kontrolü koy; kuru ağırlık üzerinden tartmayan tüccarı kaza dışına sür.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"İpek tartısında hile bitti; dokuma esnafı gerçek ağırlıkla iplik aldı."},{"label":"İpek narin maldır, rutubeti sever deyip yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağlaun.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; İpek İpliğinin Nemlendirilerek Tartılması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; İpek İpliğinin Nemlendirilerek Tartılması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; İpek İpliğinin Nemlendirilerek Tartılması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 832) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_833', 'ottoman', 'Badem Ezmesine Ezilmiş Kayısı Çekirdeği Katılması', 'Helvacılar Loncası', 'Lüks badem ezmesinin içine zehirli acıbadem ve kayısı çekirdeği tozu karıştırıldığı, çocukların zehirlendiği bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"İmalathaneleri mühürlet, zehirli tatlıları gömdür ve helvacıbaşını azlet.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Saray ve halk tatlıları zehirden kurtuldu; gıda ahlakı korundu."},{"label":"Tadı güzeldir; biraz acılık tat verir deyip affedin.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":7,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Badem Ezmesine Ezilmiş Kayısı Çekirdeği Katılması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Badem Ezmesine Ezilmiş Kayısı Çekirdeği Katılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Badem Ezmesine Ezilmiş Kayısı Çekirdeği Katılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 833) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_834', 'ottoman', 'Fırıncıların Geceleyin Hamuru Suyla Kabartması', 'İstanbul Fırınları', 'Un tasarrufu için hamura bol su ve soda katılarak şişirilen ekmeklerin fırından çıkınca balon gibi söndüğü görüldü.', '[{"id":"char_firinci_esnafi","name":"Fırıncı / Ekmekçi Esnafı"}]', '[{"label":"Ekmeklerin yoğunluk ve un nispetini denetlet; içi boş hava ekmeği yapan fırını kapat.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Halk doyurucu hakiki buğday ekmeği yedi; fırıncı hilesi durduruldu."},{"label":"Ekmek büyük görünüyor ya; halk memnun kalır.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Fırıncıların Geceleyin Hamuru Suyla Kabartması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Fırıncıların Geceleyin Hamuru Suyla Kabartması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Fırıncıların Geceleyin Hamuru Suyla Kabartması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":7,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 834) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_835', 'ottoman', 'Bakkalların Toz Şekere İnce Kum Karıştırması', 'Kaza İhtisabı', 'Çuvallardaki toz şekerin içine elenmiş beyaz dere kumu karıştırıldığı, çay ve şerbetlerin dibine kum çöktüğü şikâyet edildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Bakkalları denetle; suda erimeyen kumlu şekeri satan bakkala ağır para cezası kes ve teşhir et.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Şeker kumlardan temizlendi; esnaf terazide dürüstlüğe mecbur edildi."},{"label":"Şeker nemlenince taşlaşır; kum değildir deyip geçiştir.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Bakkalların Toz Şekere İnce Kum Karıştırması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Bakkalların Toz Şekere İnce Kum Karıştırması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Bakkalların Toz Şekere İnce Kum Karıştırması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 835) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_836', 'ottoman', 'Gemi Palamarlarının İçi Çürük Dışı Sağlam Halatla Satılması', 'Tersane İskelesi', 'Kalyonları bağlayan palamarların ortasına eski çürük kendir lifleri doldurulup dışına parlak ip sarıldığı anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Halatçıbaşını zindana at; gemi palamarlarını kesip içini denetlemeden tersaneye sokma.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Donanmanın demir emniyeti sağlandı; kalyonların başıboş sürüklenmesi önlendi."},{"label":"Dışı sağlamdır; kalyonları tutar deyip idare edin.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Gemi Palamarlarının İçi Çürük Dışı Sağlam Halatla Satılması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Gemi Palamarlarının İçi Çürük Dışı Sağlam Halatla Satılması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Gemi Palamarlarının İçi Çürük Dışı Sağlam Halatla Satılması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -7","effects":{"justice":9,"people":1,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 836) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_837', 'ottoman', 'Sedefli Sehpalarda Boyalı Kemik Kullanımı', 'Kapalıçarşı Sandıkçıları', 'Hakiki inci sedefi fiyatına sığır kemiğini parlatıp sedef diye satan marangozların çarşıyı dolandırdığı kanıtlandı.', '[{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Ateş testi uygulat; kemik yakan sahtekârların sedefkâr beratını iptal et.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Sedefkârlık sanatı kurtarıldı; Kapalıçarşı eserlerine güven tazelendi."},{"label":"Kemik de beyazdır; sedef gibi parlıyor deyip meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağla.","preview":"Reaya +9, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Sedefli Sehpalarda Boyalı Kemik Kullanımı nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Sedefli Sehpalarda Boyalı Kemik Kullanımı fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Sedefli Sehpalarda Boyalı Kemik Kullanımı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 837) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_838', 'ottoman', 'At Yularlarında İnce Pamuk İpiyle Dikiş Hilesi', 'Saraçlar Çarşısı', 'Saraçların deri kayışları balmumlu kalın ibrişim yerine çürük pamuk ipliğiyle diktiği, atların yolda boşanıp kaçtığı görüldü.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Bütün yularları çektirme testine tabi tut; çürük dikişli koşumları imha ettir.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Atlar kontrolden çıkmaktan kurtuldu; sokaklarda araba kazaları önlendi."},{"label":"Pamuk ipliği esnektir; saraçların dikişine divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"At Yularlarında İnce Pamuk İpiyle Dikiş Hilesi sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; At Yularlarında İnce Pamuk İpiyle Dikiş Hilesi meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; At Yularlarında İnce Pamuk İpiyle Dikiş Hilesi gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 838) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_839', 'ottoman', 'Kesilen Hayvanların Kanının Suya Karıştırılıp Sucuk Yapılması', 'İstanbul Kasapbaşı', 'Mezbaha artıklarının ve pıhtılaşmış kanların baharatla yoğrularak sucuk diye halka satıldığı muhtesipçe basıldı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_kasap_esnafi","name":"Kasap Esnafı"}]', '[{"label":"Kanlı sucuk imalathanelerini derhal yaktır, failleri küreğe mahkûm et ve helal et nizamını işlet.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Şeriatın helal gıda emri uygulandı; halkın midesi pislikten korundu."},{"label":"Baharat kokuyu bastırır; fukara ucuza sucuk yesin.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Kesilen Hayvanların Kanının Suya Karıştırılıp Sucuk Yapılması nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Kesilen Hayvanların Kanının Suya Karıştırılıp Sucuk Yapılması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Kesilen Hayvanların Kanının Suya Karıştırılıp Sucuk Yapılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 839) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_840', 'ottoman', 'Ahilik ve Fütüvvet-nâme Kanunnâmesi', 'Dîvân-ı Hümâyûn', 'Esnaf ahlakını \'Eline, beline, diline sahip ol; harama el uzatma, tartıda eksik tartma!\' prensibiyle kanunlaştıran büyük ferman hazırlandı.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Fermanı mühürle: \'Ahlaksız tüccar mülkün içindeki kurttur; esnafı fütüvvet ahlakıyla yaşat!\'.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Çarşılara asrısaadet bereketi geldi; aldatan da aldatılan da kalmadı."},{"label":"Ticarette ahlak aranmaz; serbest kâr esastır deyip fermanı yırt.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Ahilik ve Fütüvvet-nâme Kanunnâmesi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Ahilik ve Fütüvvet-nâme Kanunnâmesi fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Ahilik ve Fütüvvet-nâme Kanunnâmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 840) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_841', 'ottoman', 'Kadı Naibinin Mirasçıdan Gizlice \'Çıkma\' İstemesi', 'Kaza Sicili', 'Miras taksiminde hakkı olan kadına ilam çıkarmak için naibin \'Bana bir yüzük vermezsen hücceti imzalamam\' dediği arz edildi.', '[{"id":"char_kadi_naibi","name":"Kadı Naibi"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Naibin cübbesini al, kadı kapısından kov ve mirası kadına tek akçe harç almadan teslim et.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Rüşvetçi naip ibret oldu; mahkeme kapısı mazluma kalkan oldu."},{"label":"Küçük bir hediyedir; kadı naipleriyle arayı bozmayın.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadı Naibinin Mirasçıdan Gizlice \'Çıkma\' İstemesi davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadı Naibinin Mirasçıdan Gizlice \'Çıkma\' İstemesi davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadı Naibinin Mirasçıdan Gizlice \'Çıkma\' İstemesi gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 841) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_842', 'ottoman', 'Aşiret Ağasının Mahkeme Şahitlerini Tehdidi', 'Diyar-ı Bekr Kadılığı', 'Cinayet davasında şahitlik yapacak köylülerin kapısına silahlı adamlar diken aşiret beyi \'Şahitlik edenin köyünü yakarım\' dedi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Yeniçeri müfrezesiyle köyü muhafazaya al; aşiret beyini zincire vurup mahkeme salonuna çek.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Zorbalık sindirildi; şahitler korkusuzca hakikati söyledi, katil cezasını buldu."},{"label":"Aşiret çok kalabalıktır; köylüler şahitlikten vazgeçsin de.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Aşiret Ağasının Mahkeme Şahitlerini Tehdidi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Aşiret Ağasının Mahkeme Şahitlerini Tehdidi fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Aşiret Ağasının Mahkeme Şahitlerini Tehdidi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 842) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_843', 'ottoman', 'Zimmî Esnafın Müslüman Ortağından Alacağı', 'İstanbul Kadılığı', 'Müslüman ortak, Ermeni ortağına olan borcunu inkâr edip \'Gayrimüslimin Müslümana şahitliği geçmez\' bahanesine sığındı.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Ticari defterleri ve mühürlü senetleri esas al: \'Hukukta ahde vefa esastır!\' Borcu zorla tahsil ettir.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Dinin sahtekârlığa alet edilmesi engellendi; gayrimüslim tüccar devlete bağlandı."},{"label":"Müslümanı gayrimüslimin önünde mahcup etmeyin deyip davayı düşür.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hileli mal satan ve gramajdan çalan dükkânlara ağır cerime uygula; toplanan parayla dürüst üreticiye faizsiz hammadde desteği ver ve Zimmî Esnafın Müslüman Ortağından Alacağı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çarşı nizamını bozan ve sahte mal üreten tezgâhları derhal müsadere et; sorumluları şehrin meydanında ibret için teşhir et ve Zimmî Esnafın Müslüman Ortağından Alacağı fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Lonca ve Gedik Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Zimmî Esnafın Müslüman Ortağından Alacağı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 843) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_844', 'ottoman', 'Kadıların Davaları Aylarca Sürüncemede Bırakması', 'Kaza Teftişi', 'Taşra kadısının rüşvet alamadığı davaların dosyasını rafa kaldırıp tarafları aylarca kaza merkezinde perişan ettiği görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_divan_mufettisi","name":"Divan Müfettişi"}]', '[{"label":"Kadıya teftiş aç; her davanın azami üç celsede bitirilmesini emret, geciktiren kadıyı azlet.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Geciken adaletin zulüm olduğu hatırlatıldı; mahkemeler yıldırım gibi işledi."},{"label":"Kadıların işi çoktur; davalar ne zaman biterse bitsin.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kadıların Davaları Aylarca Sürüncemede Bırakması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Kadıların Davaları Aylarca Sürüncemede Bırakması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +7, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Kadıların Davaları Aylarca Sürüncemede Bırakması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 844) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_845', 'ottoman', 'Vakıf Arazisini Şahsi Mülk Diye Satan Mütevelli', 'Edirne Mahkemesi', 'Sultan Bayezid Vakfı\'nın bağını sahte tapuyla tüccara satan mütevellinin altınlarla kaçmaya hazırlandığı tespit edildi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Mütevelliyi sınırda yakalat, altınları vakfa iade et ve kendisini kalebend cezasına çarptır.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Vakıf hırsızı yakalandı; ata yadigârı vakıf arazisi kurtarıldı."},{"label":"Alan tüccar iyi niyetlidir; arazi tüccarda kalsın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Vakıf Arazisini Şahsi Mülk Diye Satan Mütevelli nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Vakıf Arazisini Şahsi Mülk Diye Satan Mütevelli fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Vakıf Arazisini Şahsi Mülk Diye Satan Mütevelli meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 845) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_846', 'ottoman', 'Zorla Kaçırılan Kızın Nikâhının Feshi', 'Kaza Sicili', 'Zorba bir levent reisinin köylünün kızını dağa kaçırıp sahte bir imama zorla nikâh kıydırdığı feryatla duyuruldu.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Rızasız nikâh bâtıldır! Nikâhı derhal feshet, kızı ailesine teslim et ve zorba levendi as.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Zulüm kılıçla kesildi; iffet ve namus güvencesi tebaa için kalkan oldu."},{"label":"Nikâh kıyılmıştır bir kere; aralarını bulun deyip affedin.","preview":"Reaya +7, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Zorla Kaçırılan Kızın Nikâhının Feshi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Zorla Kaçırılan Kızın Nikâhının Feshi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Zorla Kaçırılan Kızın Nikâhının Feshi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 846) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_847', 'ottoman', 'Hacı Kafilesini Soyan Bedevilere Kadı Koruması', 'Şam Mahkemesi', 'Kadının bedevi aşiretiyle akraba olduğu, hacıların çalınan altınlarını getiren şahitleri zindana attığı ortaya çıktı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Kadıyı derhal azlet ve zincire vur; hacıların altınlarını aşiretten süvari zoruyla tahsil ettir.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -4","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-4},"log":"Hac yolundaki yargı hıyaneti temizlendi; Surre Alayı emniyete kavuştu."},{"label":"Kadı ulemadandır; hacılar Allah için affetsin de.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hacı Kafilesini Soyan Bedevilere Kadı Koruması davasında haksız alınan akçeleri ve mahkeme harçlarını kusurlulardan tahsil edip kaza sandığına aktar; mağdurların harçlarını iade et.","preview":"Hazine +7, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Çavuşbaşıyı derhal kaza merkezine yolla; Hacı Kafilesini Soyan Bedevilere Kadı Koruması davasında usulsüzlük yapan kadı ve kâtipleri tevkif ettirip mahkeme defterlerini mühürlet.","preview":"Ordu +8, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kaza ve Tereke Nizamnâmesi\' neşret; Hacı Kafilesini Soyan Bedevilere Kadı Koruması gibi hadiselerin tekerrürünü önleyecek şekilde mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 847) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_848', 'ottoman', 'İpek Fabrikasında İşçinin Kolunun Dişliye Kaptırılması', 'Bursa Kadılığı', 'Dikkatsiz fabrika sahibinin koruma tahtası koymadığı için kolunu kaybeden dokuma işçisine tazminat verilmediği bildirildi.', '[{"id":"char_bursa_kadisi","name":"Bursa Kadısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Kazaen diyet hükmü ver: Fabrika sahibine işçiye ömür boyu maaş ve diyet ödettir, tezgâhlara siperlik taktır.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"İşçi hakkı korundu; fabrikalara can emniyeti kuralları girdi."},{"label":"Kendi hatasıdır; fabrika sahibine masraf çıkarmayın.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve İpek Fabrikasında İşçinin Kolunun Dişliye Kaptırılması nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve İpek Fabrikasında İşçinin Kolunun Dişliye Kaptırılması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve İpek Fabrikasında İşçinin Kolunun Dişliye Kaptırılması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 848) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_849', 'ottoman', 'Sahte Delille Boşanıp Mehrini Alamayan Kadın', 'Kaza Sicili', 'Zengin bir kocanın yalancı şahitlerle hanımını itaatsiz gösterip tek kuruş mehir ödemeden sokağa attığı anlaşıldı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Yalancı şahitleri küreğe koy, kadının mehrini ve nafakasını kocanın servetinden zorla alıp teslim et.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Mazlum kadının hakkı alındı; iftiracı koca sokakta rezil edildi."},{"label":"Kocanın şahitleri tamamdır; kadının davasını reddedin.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Sahte Delille Boşanıp Mehrini Alamayan Kadın nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Sahte Delille Boşanıp Mehrini Alamayan Kadın fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Sahte Delille Boşanıp Mehrini Alamayan Kadın meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 849) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_850', 'ottoman', 'Hristiyan Mezarlığının Yanına Çöp Dökülmesi', 'Kudüs Kadılığı', 'Müslüman mahalle kethüdasının inat olsun diye çöpleri Latin cemaatinin mezarlık kapısına döktürdüğü bildirildi.', '[{"id":"char_kudus_kadisi","name":"Kudüs Kadısı"},{"id":"char_sehir_kethudasi","name":"Şehir Kethüdası"}]', '[{"label":"Kethüdayı azlet; çöpleri temizlet ve kabristan kapısına saygı nöbetçisi diktir.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Ölüye ve mabede hürmet korundu; Kudüs\'te mezhep barışı tazelendi."},{"label":"Gâvur mezarlığıdır; çöp nereye dökülürse dökülsün.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hristiyan Mezarlığının Yanına Çöp Dökülmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Hristiyan Mezarlığının Yanına Çöp Dökülmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Hristiyan Mezarlığının Yanına Çöp Dökülmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 850) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_851', 'ottoman', 'Kadıların Mahkeme Harçlarını Kanundan Fazla Alması', 'Kaza Teftişi', 'Padişah kanunnâmesinde yazılı harç tarifesini saklayan kadının vatandaştan üç kat \'resm-i kısmet\' aldığı ortaya çıktı.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Harç tarifesini mahkeme kapısına taşa kazıt; fazla akçe alan kadıyı sürgün et.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Tarife şeffaflaştı; mahkemeler haraç kapısı olmaktan çıkarıldı."},{"label":"Kadıların masrafı çoktur; tarife gizli kalsın.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Kadıların Mahkeme Harçlarını Kanundan Fazla Alması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Kadıların Mahkeme Harçlarını Kanundan Fazla Alması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Kadıların Mahkeme Harçlarını Kanundan Fazla Alması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 851) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_852', 'ottoman', 'Kölelerin Efendileri Tarafından Sakatlanması', 'İstanbul Kadılığı', 'Zalim bir tüccarın kaçmaya kalktı diye kölesinin ayak parmaklarını kestiği hekim raporuyla kadı önüne geldi.', '[{"id":"char_istanbul_kadisi","name":"İstanbul Kadısı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Köleyi derhal hürriyetine kavuştur, efendiye ağır diyet cezası kes ve kendisini hapse at.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Şer\'i merhamet hukuku korundu; köle dahi olsa canın dokunulmaz olduğu gösterildi."},{"label":"Mülküdür; efendi kölesine istediğini yapar deyip davayı düşür.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Kölelerin Efendileri Tarafından Sakatlanması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Kölelerin Efendileri Tarafından Sakatlanması fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Kölelerin Efendileri Tarafından Sakatlanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 852) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_853', 'ottoman', 'Yetim Malıyla Ticaret Yapan Vasinin İflası', 'Kaza Sicili', 'Yetimlerin parasını kendi riskli kervanına yatırıp batıran vasinin \'Kaderdir\' deyip kenara çekildiği görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kervancibasi","name":"Kervancıbaşı"}]', '[{"label":"Vasinin şahsi konağını ve arazisini sattır; yetimlerin anaparasını kuruşuna kadar kurtar.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Yetim hakkı korundu; emanete hıyanet eden zengin ibret oldu."},{"label":"Ticaret zararla biter; vasinin konağına meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yetim Malıyla Ticaret Yapan Vasinin İflası sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; Yetim Malıyla Ticaret Yapan Vasinin İflası meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; Yetim Malıyla Ticaret Yapan Vasinin İflası gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 853) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_854', 'ottoman', 'Rum Balıkçıların Ağlarını Kesen Müslüman Leventler', 'Trabzon Mahkemesi', 'Leventlerin \'Deniz gazilerindir\' diyerek zimmî balıkçıların ağlarını parçalayıp balıklarına el koyduğu bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Leventleri hapsettir, ağların parasını leventlerin ulufe maaşından kesip balıkçılara ver.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Zimmî tebaa adaleti gördü; leventlerin zorbalığı durduruldu."},{"label":"Gazi askerlerdir; balıkçılar şikâyet etmesin.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Rum Balıkçıların Ağlarını Kesen Müslüman Leventler nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Rum Balıkçıların Ağlarını Kesen Müslüman Leventler fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Rum Balıkçıların Ağlarını Kesen Müslüman Leventler meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 854) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_855', 'ottoman', 'Borçlu Köylünün Çocuğunun Rehin İstenmesi', 'Kaza Meclisi', 'Faizci sarrafın borcunu ödeyemeyen köylünün on yaşındaki oğlunu rehin alıp uşak yapmaya kalktığı ihbar edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_sarraf","name":"Sarraf / Kuyumcu"}]', '[{"label":"Sarrafı derhal tutukla! \'İnsan hür doğar, rehin edilemez!\' Sarrafın faiz senetlerini yırt.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Çocuk ailesine kavuştu; insan onurunu ayaklar altına alan tefecilik ezildi."},{"label":"Borç ödenene kadar çocuk sarrafın yanında çalışsın de.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Borçlu Köylünün Çocuğunun Rehin İstenmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Borçlu Köylünün Çocuğunun Rehin İstenmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Borçlu Köylünün Çocuğunun Rehin İstenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 855) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_856', 'ottoman', 'Yalancı Şahidin Dili Kesilmesi Cezası', 'Edirne Kadılığı', 'Bir masumun idamına sebep olacak sahte şahitliği para karşılığı yaptığı ispatlanan şahsın davası geldi.', '[{"id":"char_edirne_kadisi","name":"Edirne Kadısı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Şer\'i kısas ve teşhir hükmünü ver; yalancı şahidi çarşıda teşhir edip ebediyen şahitlikten men et.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Yalan şahitlik felaketi önlendi; mahkemelere ilahi vakar geldi."},{"label":"Hafif bir para cezasıyla kefalete bağlayıp divan murakabesinde ıslahına fırsat tanıın.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yalancı Şahidin Dili Kesilmesi Cezası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Yalancı Şahidin Dili Kesilmesi Cezası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Yalancı Şahidin Dili Kesilmesi Cezası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":9,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 856) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_857', 'ottoman', 'Vefat Eden Gayrimüslimin Terekesine Kadının Çökmesi', 'Kaza Sicili', 'Mirasçısı olan zengin bir Yahudi tacirin terekesini kadının \'Vârisi yoktur\' diye kendi zimmetine geçirdiği kanıtlandı.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kadıyı azlet, serveti hakiki varislere teslim et ve kadının şahsi malına el koy.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Yargıç zorbalığı ezildi; zimmî cemaat devlete şükran sundu."},{"label":"Kadı hazineye de pay vermiştir; olayı büyütmeyin.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Vefat Eden Gayrimüslimin Terekesine Kadının Çökmesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Vefat Eden Gayrimüslimin Terekesine Kadının Çökmesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Vefat Eden Gayrimüslimin Terekesine Kadının Çökmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 857) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_858', 'ottoman', 'Ortak Miras Binasının Çürümeye Terk Edilmesi', 'Kayseri Mahkemesi', 'On kardeşin inatlaşması yüzünden şehir meydanındaki tarihi büyük hanın tamir ettirilmeyip yıkılma tehlikesi taşıdığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Mecelle kaidesini işlet: Mirası açık artırmayla sattır, bedelini kardeşlere paylaştırıp hanı kurtar.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Tarihi han yıkılmaktan kurtarıldı; çarşı meydanı emniyete kavuştu."},{"label":"Kardeşler anlaşana kadar han yıkılırsa yıkılsın; divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Ortak Miras Binasının Çürümeye Terk Edilmesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Ortak Miras Binasının Çürümeye Terk Edilmesi fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Ortak Miras Binasının Çürümeye Terk Edilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 858) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_859', 'ottoman', 'Sancak Beyinin Köylüyü Kendi Bahçesinde Çalıştırması', 'Dîvân-ı Mezalim', 'Beyin köylüleri haftada iki gün zorla kendi bostanında bila-ücret çalıştırdığı şikâyet mektuplarıyla belgelendi.', '[{"id":"char_sancak_beyi","name":"Sancak Beyi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Angaryayı kesinlikle men et! Beyin tarlasındaki tüm köylülerin geçmiş yevmiyelerini zorla ödet.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Köylü angaryadan kurtuldu; beyin haksız zorbalığı kırıldı."},{"label":"Bey asker besliyor; köylü biraz yardım etsin.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sancak Beyinin Köylüyü Kendi Bahçesinde Çalıştırması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Sancak Beyinin Köylüyü Kendi Bahçesinde Çalıştırması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Sancak Beyinin Köylüyü Kendi Bahçesinde Çalıştırması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 859) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_860', 'ottoman', 'Yargı Bağımsızlığı ve Kadı Teminatı Fermanı', 'Dîvân-ı Hümâyûn', 'Hiçbir paşanın, vezirin veya askerin mahkeme hükmüne müdahale edemeyeceğini emreden Adalet Fermanı hazırlandı.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Fermanı mühürle: \'Kadı yalnız şeriat ve kanuna bakar; kadıya baskı kuranın boynu vurulur!\'.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Mahkemeler mutlak bağımsızlığa kavuştu; adalet mülkün sarsılmaz kalesi oldu."},{"label":"Devlet ricali gerektiğinde kadıya talimat vermelidir de.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miras ve tereke harçlarını sabit ve mühürlü bir vergi tarifesine bağla; usulsüzlük yapan kadı naibinin haksız kazancını müsadere et ve Yargı Bağımsızlığı ve Kadı Teminatı Fermanı nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Yetim ve miras hakkına el uzatan görevlileri derhal görevden azlet; suç ortaklarını ibret için taşra kalesine sürgüne gönder ve Yargı Bağımsızlığı ve Kadı Teminatı Fermanı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kaza ve Tereke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Yargı Bağımsızlığı ve Kadı Teminatı Fermanı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 860) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_861', 'ottoman', 'Tuna Donunca Kazakların Buz Üstünden Akını', 'Vidin Palankası', 'Nehir kalın buz tutunca Kazak süvarileri botlara gerek kalmadan buzun üstünden sınır köylerini vurmaya başladı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Buz kırıcı istihkâm neferleri çıkar, nehir ortasına barutla yarıklar aç ve kızaklı nöbetçiler dik.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Buz yarıldı; Kazak süvarisi nehir dibine gömüldü, köyler kurtuldu."},{"label":"Köylüler içeri kaçsın; buz eriyene kadar nehri beklemeyin.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Tuna Donunca Kazakların Buz Üstünden Akını nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Tuna Donunca Kazakların Buz Üstünden Akını fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tuna Donunca Kazakların Buz Üstünden Akını meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 861) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_862', 'ottoman', 'Don Nehri Ağzında Rus Kalyonlarının İnşası', 'Azak Garnizonu', 'Çarlık tersanesinin Karadeniz\'e inmek için nehirde gizlice kalyonlar çattığı sınır akıncılarınca haber verildi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"}]', '[{"label":"Kırım süvarisi ve nehir şaykalarıyla ani gece baskını ver; düşman tersanesini ateşe ver.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Rus kalyonları denize inemeden küle döndü; Karadeniz emniyette kaldı."},{"label":"Diplomatik protesto mektubu yazıp Petersburg\'dan cevap bekleyin.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Don Nehri Ağzında Rus Kalyonlarının İnşası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Don Nehri Ağzında Rus Kalyonlarının İnşası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Don Nehri Ağzında Rus Kalyonlarının İnşası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 862) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_863', 'ottoman', 'Kandiye Siperlerinde Askerin Karavana Kavgası', 'Girit Serdarlığı', 'Yeniçeriler ile Arnavut leventler arasında bulgur ve et istihkakı yüzünden siperde kılıç çekildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_serdar_i_ekrem","name":"Sefer Serdarı"}]', '[{"label":"Serdar bizzat siperlere girsin; kazanları eşit tartıyla paylaştır, fitne çıkaran iki elebaşını as.","preview":"Adalet +7, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":7,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Siperde fitne söndürüldü; asker birleşip düşman burcuna hücum etti."},{"label":"Yeniçerinin payını fazla verin; ocaklı küsmesin.","preview":"Reaya +8, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kandiye Siperlerinde Askerin Karavana Kavgası nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kandiye Siperlerinde Askerin Karavana Kavgası fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kandiye Siperlerinde Askerin Karavana Kavgası meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 863) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_864', 'ottoman', 'Kuşatma Surlarının Altına Gizli Su Kuyusu Kazılması', 'Kamaniçe Kalesi', 'Düşman barutçularının kale hendeklerine zehir akıtması üzerine içeride acil derin artezyen kuyusu kazılması gerekti.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Maden lağımcılarını derhal kayalık dibine kazdır; tatlı su damarını bulup depola.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Kalede tatlı su fışkırdı; garnizon zehirlenmekten ve teslim olmaktan kurtuldu."},{"label":"Yağmur suyuyla idare edin; kuyu kazmak masraflıdır.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kuşatma Surlarının Altına Gizli Su Kuyusu Kazılması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kuşatma Surlarının Altına Gizli Su Kuyusu Kazılması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kuşatma Surlarının Altına Gizli Su Kuyusu Kazılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 864) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_865', 'ottoman', 'Kalyon Halatlarının Katran Yerine Yağla Islatılması', 'Sinop Tersanesi', 'Müteahhidin katrandan tasarruf etmek için palamutları zeytinyağı tortusuyla yağlattığı, iplerin çürüdüğü anlaşıldı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Bütün palamutları söktür, müteahhidin tüm malını müsadere et ve saf çam katranıyla donat.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Donanmanın halatları taşa döndü; açık denizde gemilerimiz güvende kaldı."},{"label":"Halatlar yenidir; bu seferlik donanmaya takın.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Kalyon Halatlarının Katran Yerine Yağla Islatılması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Kalyon Halatlarının Katran Yerine Yağla Islatılması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Kalyon Halatlarının Katran Yerine Yağla Islatılması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 865) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_866', 'ottoman', 'Hürmüz Boğazı\'nda Portekiz Korsan Pusu', 'Basra Körfezi', 'Hindistan\'dan gelen baharat yüklü ticaret gemilerimizin boğaz ağzında Portekiz korsanlarınca çevrildiği bildirildi.', '[{"id":"char_deniz_korsani","name":"Deniz Korsanı"}]', '[{"label":"Basra kalyonlarını tam yelken sevk et; korsanları çapraz top ateşiyle boğazda batır.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Baharat kervanı kurtarıldı; Portekiz korsanları Körfez\'den kovuldu."},{"label":"Uzak denizdir; gemiler kendi başının çaresine baksın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Hürmüz Boğazı\'nda Portekiz Korsan Pusu nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Hürmüz Boğazı\'nda Portekiz Korsan Pusu fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Hürmüz Boğazı\'nda Portekiz Korsan Pusu meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 866) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_867', 'ottoman', 'Kuşatma Siperlerinde Askerin Dizanteriye Yakalanması', 'Hotin Kuşatması', 'Çamurlu yağmur sularını içmek zorunda kalan piyadelerin dizanteriden kırıldığı, siperlerin boşaldığı bildirildi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sıhhiye çadırları kurdur, kaynatılmış sirkeli su ve kuru nane dağıt; askerin sağlığını kurtar.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Salgın söndürüldü; neferler ayağa kalkıp hücum mevzilerine koştu."},{"label":"Savaş hali budur; hasta asker kendi kendine iyileşsin.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Kuşatma Siperlerinde Askerin Dizanteriye Yakalanması nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Kuşatma Siperlerinde Askerin Dizanteriye Yakalanması fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Kuşatma Siperlerinde Askerin Dizanteriye Yakalanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 867) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_868', 'ottoman', 'Sınır Boyundaki Köylerin Safevi Süvarilerince Basılması', 'Kars Hududu', 'Sınır karakollarının ihmali yüzünden sınırı geçen 500 Safevi atlının köyleri ateşe verip sürüleri kaçırdığı bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Sipahi alaylarını derhal takibe çıkar; eşkıyayı sınırda kıstırıp sürüleri köylüye iade et.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Sürüler kurtarıldı; köylünün devlete olan güveni tazelendi."},{"label":"Sınır ihlali küçüktür; barışı bozmamak için takip etmeyin.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sınır Boyundaki Köylerin Safevi Süvarilerince Basılması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Sınır Boyundaki Köylerin Safevi Süvarilerince Basılması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Sınır Boyundaki Köylerin Safevi Süvarilerince Basılması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 868) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_869', 'ottoman', 'Avusturya Topçusunun Kaledeki Cephaneliği Hedef Alması', 'Belgrad Surları', 'Düşman havanlarının kale cephaneliğinin kubbesini dövdüğü; acilen üzerine toprak ve ıslak keçe yığılması gerektiği bildirildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"İstihkâm neferlerini seferber et; kubbeyi metrelerce kum torbasıyla tahkim ettir.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -2","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-2},"log":"Cephanelik korundu; düşman havan mermileri kum torbalarında söndü."},{"label":"Kubbe taştır, bir şey olmaz deyip askeri yormayın.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Avusturya Topçusunun Kaledeki Cephaneliği Hedef Alması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Avusturya Topçusunun Kaledeki Cephaneliği Hedef Alması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Avusturya Topçusunun Kaledeki Cephaneliği Hedef Alması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 869) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_870', 'ottoman', 'Teslim Olan Düşman Garnizonunun Katledilmek İstenmesi', 'Uyvar Kalesi', 'Kalenin fethinden sonra yeniçerilerin \'Ganimet az çıktı\' diyerek teslim olan düşman askerlerini kılıçtan geçirmek istediği görüldü.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kılıçları kınına soktur! \'Aman dileyene kılıç çekilmez, ahde vefa farzdır!\' Asilere haddini bildir.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"İslam\'ın harp hukuku korundu; teslim olan düşman Osmanlı adaletine hayran kaldı."},{"label":"Askerin hakkıdır; yağmaya ve kılıca yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağlaun.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Teslim Olan Düşman Garnizonunun Katledilmek İstenmesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Teslim Olan Düşman Garnizonunun Katledilmek İstenmesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Teslim Olan Düşman Garnizonunun Katledilmek İstenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 870) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_871', 'ottoman', 'Şayka Kaptanlarının Köylünün Balık Ağlarına Zarar Vermesi', 'Tuna Donanması', 'Şaykaların hız yapmak için Tuna köylülerinin nehirdeki kadim mersin balığı dalyanlarını parçaladığı bildirildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kaptanlara nehir güzergâhı kuralı koy; köylünün zararını kaptanların maaşından kesip tazmin et.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -2","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-2},"log":"Köylü ile asker barıştı; dalyanlar korunarak balık üretimi sürdü."},{"label":"Devlet gemisidir; köylü ağını nehre atmasın.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Şayka Kaptanlarının Köylünün Balık Ağlarına Zarar Vermesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Şayka Kaptanlarının Köylünün Balık Ağlarına Zarar Vermesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Şayka Kaptanlarının Köylünün Balık Ağlarına Zarar Vermesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 871) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_872', 'ottoman', 'Seddülbahir Kalesinde Çatlayan Şahi Top', 'Çanakkale Boğazı', 'Boğazı koruyan devasa bronz topun atış anında gövdesinden çatladığı, demir çemberlerle sarılmazsa patlayacağı bildirildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Samakov demircilerini getir; topun gövdesine kızgın çelik çemberler çektirip sağlamlaştır.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Top kurtarıldı; Boğaz\'a girmeye çalışan düşman kalyonları menzile giremedi."},{"label":"Topu emekliye ayırın; yerine küçük top koyun.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Seddülbahir Kalesinde Çatlayan Şahi Top nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Seddülbahir Kalesinde Çatlayan Şahi Top fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Seddülbahir Kalesinde Çatlayan Şahi Top meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 872) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_873', 'ottoman', 'Karlı Dağlarda Mühimmat Taşıyan Katırların Telef Olması', 'Kafkasya Cephesi', 'Yem yetersizliği yüzünden yüzlerce katır uçurumlara yuvarlandı; top cephanesi karlar altında kaldı.', '[{"id":"char_gayrimuslim_tebaa","name":"Gayrimüslim Zimmî Tebaa"}]', '[{"label":"Kafkas aşiretlerinden yüksek bedelle kızaklı atlar kirala; cephaneyi derhal mevziye yetiştir.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Cephane kurtarıldı; Kafkas cephesindeki tabyalarımız düşmana direndi."},{"label":"Cephaneyi karda bırakıp askeri geri çekin.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Karlı Dağlarda Mühimmat Taşıyan Katırların Telef Olması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Karlı Dağlarda Mühimmat Taşıyan Katırların Telef Olması fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Karlı Dağlarda Mühimmat Taşıyan Katırların Telef Olması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 873) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_874', 'ottoman', 'Venedik Kalyonundan Kurtarılan Müslüman Esirler', 'Akdeniz Sefareti', 'Zapt edilen Venedik kalyonunun sintinesinde zincire vurulmuş 200 Müslüman tacir ve hacı kurtarıldı.', '[{"id":"char_tuccar","name":"Tüccar"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Gazilere ikramda bulun, yaralarını sardır ve hazineden harçlık vererek memleketlerine uğurla.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -1","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-1},"log":"Kurtarılan gaziler gözyaşlarıyla devlete dua etti; İslam alemi sevince boğuldu."},{"label":"Kendi imkânlarıyla evlerine dönsünler; hazineden para çıkmaz.","preview":"Reaya +8, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Venedik Kalyonundan Kurtarılan Müslüman Esirler hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Venedik Kalyonundan Kurtarılan Müslüman Esirler hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Venedik Kalyonundan Kurtarılan Müslüman Esirler gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 874) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_875', 'ottoman', 'Kalyonların Kalafatında Katranın Yanması', 'Tersane-i Âmire', 'Tersane havuzunda katran kaynatan kazanın devrilmesiyle büyük bir kalyonun iskele tahtaları tutuştu.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Tulumbacıları derhal sevk et; alevleri diğer gemilere sıçramadan söndür ve zararı tazmin et.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Büyük tersane yangını önlendi; kalyon tamir edilip sefere yetiştirildi."},{"label":"Yanan gemiyi Haliç\'e bırakın; diğerleri kurtulsun.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Kalyonların Kalafatında Katranın Yanması nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Kalyonların Kalafatında Katranın Yanması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Kalyonların Kalafatında Katranın Yanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 875) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_876', 'ottoman', 'Sınır Boyundaki Çobanların Esir Alınması', 'Kars Hududu', 'Safevi akıncılarının sınırda koyun otlatan masum 20 çobanı kaçırıp Tebriz pazarlarında köle diye sattığı bildirildi.', '[{"id":"char_serhat_akincisi","name":"Serhat Akıncısı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Sınır beylerine emret: Misilleme akını yap, çobanlarımızı kurtarana kadar düşman karakollarını kuşat.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Çobanlar kurtarılıp köylerine getirildi; devlet tebaasını sahipsiz bırakmadı."},{"label":"Çobanlar sınıra yaklaşmasaydı; diplomasiyle mektup yazın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve Sınır Boyundaki Çobanların Esir Alınması nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve Sınır Boyundaki Çobanların Esir Alınması fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Sınır Boyundaki Çobanların Esir Alınması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 876) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_877', 'ottoman', 'Siper Kazarken Bulunan Kadim Hazine', 'Uyvar Kuşatması', 'Hendek kazan neferlerin toprağın altında küpler dolusu altın bulduğu; neferlerin kazmayı bırakıp altına üşüştüğü görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Hazineyi kayda geçir: Askerlere cömertçe gazilik payı dağıt, kalanını ordunun erzak sandığına koy.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -1","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-1},"log":"Asker coşkuyla kazmaya sarıldı; hendekler düşman kalesine dayandı."},{"label":"Hepsini zorla saray hazinesine aktarın; askere tek akçe vermeyin.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Siper Kazarken Bulunan Kadim Hazine meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Siper Kazarken Bulunan Kadim Hazine hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Siper Kazarken Bulunan Kadim Hazine gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 877) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_878', 'ottoman', 'Şayka Kaptanlarının Ticaret Gemilerinden Haraç Alması', 'Tuna Donanması', 'Nehir güvenliğini sağlayan şayka zabitlerinin geçen tuz ve un gemilerini durdurup \'geçiş haracı\' kestiği kanıtlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Hain zabitleri rütbelerini söküp zindana at; Tuna\'da haraç kesilmesini kesinlikle yasakla.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -4","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-4},"log":"Tuna nehir ticareti emniyete kavuştu; un ve tuz fiyatları ucuzladı."},{"label":"Zabitlerin deniz harçlığıdır; arayı bozmayın.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Şayka Kaptanlarının Ticaret Gemilerinden Haraç Alması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Şayka Kaptanlarının Ticaret Gemilerinden Haraç Alması fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Şayka Kaptanlarının Ticaret Gemilerinden Haraç Alması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 878) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_879', 'ottoman', 'Kuşatma Sona Erince Siperlerde Kalan Barutlu Tuzaklar', 'Kamaniçe Garnizonu', 'Düşman çekilirken hendeklere basınca patlayan gizli barutlu çivili tahtalar bıraktı; köylüler ve hayvanlar telef oluyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"İstihkâm neferlerini görevlendir; hendekleri karış karış temizlet ve tuzakları imha et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Tuzaklar temizlendi; köylüler güvenle tarlalarına döndü."},{"label":"Köylüler hendeklere yaklaşmasın; temizlik masraflıdır.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Kuşatma Sona Erince Siperlerde Kalan Barutlu Tuzaklar nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Kuşatma Sona Erince Siperlerde Kalan Barutlu Tuzaklar fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kuşatma Sona Erince Siperlerde Kalan Barutlu Tuzaklar meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 879) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_880', 'ottoman', 'Serhad Gazileri ve Donanma Nizamnamesi', 'Dîvân-ı Hümâyûn', 'Sınır boylarında ve denizlerde kan döken gazilerin haklarını koruyan, dirlikleri liyakatsize peşkeş çekilmekten kurtaran kanunname mühürlendi.', '[{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kanunu mühürle: \'Serhad kılıçla tutulur, adaletle korunur; gazinin hakkını yiyenin ocağı sönsün!\'.","preview":"Adalet +6, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":6,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Ordumuz ve donanmamız çelik bir nizam kazandı; hudutlarımız geçilmez oldu."},{"label":"Masa başı bürokratların dediği olsun; askeri kanunlarla bağlamayın.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Serhad Gazileri ve Donanma Nizamnamesi meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Serhad Gazileri ve Donanma Nizamnamesi hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Serhad Gazileri ve Donanma Nizamnamesi gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 880) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_881', 'ottoman', 'Koçi Bey\'in Tımar Nizamının Bozulması İhtarı', 'Koçi Bey Risalesi', 'IV. Murad\'a sunulan risalede: \'Kılıç ehli sipahinin dirlikleri saray hadımlarına ve dalkavuklara peşkeş çekildi, ordu sefere askersiz çıkıyor!\' denildi.', '[{"id":"char_koci_bey","name":"Koçi Bey"},{"id":"char_timarli_sipahi","name":"Tımarlı Sipahi"}]', '[{"label":"Risaleyi emir bil: Bütün sahte beratları iptal et, dirlikleri hakiki sınır gazilerine iade et.","preview":"Adalet +7, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":7,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Tımar ordusu küllerinden doğdu; saray asalakları ordudan temizlendi."},{"label":"Saray ağalarını küstürmeyin; dirlikler kimdeyse kalsın.","preview":"Reaya +9, Otorite +6 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Koçi Bey\'in Tımar Nizamının Bozulması İhtarı nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Koçi Bey\'in Tımar Nizamının Bozulması İhtarı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Koçi Bey\'in Tımar Nizamının Bozulması İhtarı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 881) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_882', 'ottoman', 'Bütçe Açıkları ve Şişen Bürokrasi Teşhisi', 'Katip Çelebi\'nin Düstûrü\'l-Amel\'i', 'Devleti canlı bir insana benzeten Katip Çelebi: \'Vergi veren reaya zayıfladı, asker ve bürokrasi obez gibi şişti; bu beden bu yükü taşıyamaz!\' dedi.', '[{"id":"char_katip_celebi","name":"Kâtip Çelebi"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Reçeteyi uygula: Gereksiz bürokrat kadrolarını tasfiye et, saray masrafını kıs ve halkın vergisini hafiflet.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Devlet bedeni sıhhate kavuştu; reaya üretti, bütçe fazlası sağlandı."},{"label":"Memur sayısını azaltmak devleti zayıflatır; masraflara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Bütçe Açıkları ve Şişen Bürokrasi Teşhisi nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Bütçe Açıkları ve Şişen Bürokrasi Teşhisi fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Bütçe Açıkları ve Şişen Bürokrasi Teşhisi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 882) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_883', 'ottoman', 'Nushatü\'s-Selâtîn\'de Liyakatsizlik Tenkidi', 'Gelibolulu Mustafa Âlî', 'Bürokrasideki yozlaşmayı yazan allame: \'Rüşvetsiz iş görülmez oldu, layık olanlar köşede kaldı, dalkavuklar vezir oldu!\' diyerek padişahı uyardı.', '[{"id":"char_gelibolulu_ali","name":"Gelibolulu Mustafa Âlî"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Liyakat komisyonu kurdur: Her makama sınav ve ehliyetle atama yap, rüşvetle gelen paşaları azlet.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Bürokrasi dâhilerle doldu; devlet idaresi saat gibi tıkır tıkır işledi."},{"label":"Mustafa Âlî sivri dillidir; nasihatini dinlemeyip sürgüne yollayın.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Nushatü\'s-Selâtîn\'de Liyakatsizlik Tenkidi hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Nushatü\'s-Selâtîn\'de Liyakatsizlik Tenkidi hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Nushatü\'s-Selâtîn\'de Liyakatsizlik Tenkidi gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 883) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_884', 'ottoman', 'Usûlü\'l-Hikem\'deki Dört Temel Direk', 'Hasan Kâfî el-Akhisârî', 'Serhad âlimi: \'Mülkün bekası dört direkle kaimdir: Adalet, istişare, askeri disiplin ve liyakatli vezirler!\' dedi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Dört direği anayasa bil: İstişaresiz karar alma, adaleti çiğnetme, askere gevşeklik verme.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -3","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-3},"log":"Devletin dört direği çelikle tahkim edildi; nizam sarsılmaz oldu."},{"label":"Kitabi sözlerdir; hükümdar dilediği gibi tek başına hükmeder.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Usûlü\'l-Hikem\'deki Dört Temel Direk nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Usûlü\'l-Hikem\'deki Dört Temel Direk fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Usûlü\'l-Hikem\'deki Dört Temel Direk meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 884) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_885', 'ottoman', 'Mülk Zabt Eyleyemez İllâ Ricâl Hikmeti', 'Kınalızâde Ali Çelebi', 'Ahlâk-ı Alâî müellifi hatırlatır: \'Mülkü tutan ordudur, lakin ordu sadece silahla değil, adil kumandanların ahlakıyla muzaffer olur!\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"}]', '[{"label":"Ordu kumandanlarını ahlak ve takva sahibi erdemli neferlerden seç; askere halkın malına el sürmeme yemini ettir.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Ordu peygamber ocağına döndü; fethedilen yerlerin halkı Osmanlı\'ya sığındı."},{"label":"Asker savaşmayı bilsin yeter; ahlakına ve adaletine divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +7, Otorite +6 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Mülk Zabt Eyleyemez İllâ Ricâl Hikmeti nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Mülk Zabt Eyleyemez İllâ Ricâl Hikmeti fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Mülk Zabt Eyleyemez İllâ Ricâl Hikmeti meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 885) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_886', 'ottoman', 'Hilafet ve Kamu Emanetinin Sınırları', 'Mâverdî\'nin Ahkâmı', 'el-Ahkâmü\'s-Sultâniyye müellifi: \'Hükümdar çoban gibidir; sürüyü kurtlardan korumakla mükelleftir, sürüyü kendisi yerse hükümdarlık biter!\' dedi.', '[{"id":"char_maverdi","name":"Mâverdî"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Tevazu hırkasını giy: Mazlumun karşısında kul gibi dur, halkın malına göz diken valileri cezalandır.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Çoban görevini yaptı; sürü kurtlardan kurtuldu, memleket refaha erdi."},{"label":"Mülk hükümdarın şahsi çiftliğidir; dilediğini alır.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hilafet ve Kamu Emanetinin Sınırları meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Hilafet ve Kamu Emanetinin Sınırları meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Hilafet ve Kamu Emanetinin Sınırları gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 886) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_887', 'ottoman', 'Ârâü Ehli\'l-Medîneti\'l-Fâzıla Nizamı', 'Fârâbî\'nin Erdemli Şehri', 'Büyük filozof: \'Cahil ve erdemsiz şehirlerde herkes gücünün yettiğini ezer; adil şehirde ise bilge yönetici ortak saadeti kurar!\' dedi.', '[{"id":"char_farabi","name":"Fârâbî"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Erdemli nizamı kur: İlim adamlarını, sanatkârları ve dürüst tüccarları el üstünde tut; cehaleti kov.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Şehirler ilim ve sanatla parladı; toplum ortak saadet etrafında birleşti."},{"label":"Şehirler zenginleşsin de ahlakına bakmayın; para her kapıyı açar.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Ârâü Ehli\'l-Medîneti\'l-Fâzıla Nizamı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Ârâü Ehli\'l-Medîneti\'l-Fâzıla Nizamı fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ârâü Ehli\'l-Medîneti\'l-Fâzıla Nizamı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 887) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_888', 'ottoman', 'es-Siyâsetü\'ş-Şer\'iyye\'de Emanet ve Liyakat', 'İbn Teymiyye\'nin Siyaseti', 'Büyük fakih: \'Bir memuriyeti hak edene değil de hatır için dostuna veren, Allah\'a, Resulüne ve bütün Müslümanlara hıyanet etmiştir!\' dedi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Akraba torpilini lanetle: Devlet makamlarına sadece ehil ve takva sahibi olanları ata.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Hıyanet zinciri kırıldı; ehil ellerde devlet daireleri nur gibi parladı."},{"label":"Bana sadık adam olsun da liyakati olmasa da olur de.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve es-Siyâsetü\'ş-Şer\'iyye\'de Emanet ve Liyakat nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve es-Siyâsetü\'ş-Şer\'iyye\'de Emanet ve Liyakat fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve es-Siyâsetü\'ş-Şer\'iyye\'de Emanet ve Liyakat meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 888) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_889', 'ottoman', 'Mazlumun Şikâyet Kapısının Kapanmaması', 'Nizamülmülk\'ün Siyasetnâmesi', 'Büyük Selçuklu veziri: \'Zalimler padişahın kapısına perde çeker; hükümdar saraydan çıkıp halkın içine karışmadıkça adalet kurulamaz!\' dedi.', '[{"id":"char_nizamulmulk","name":"Nizamülmülk"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Saray kapılarını ardına kadar aç, her cuma divanında halkın dilekçelerini bizzat kabul et.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Saray ile millet arasındaki perde kalktı; zalim idareciler titredi."},{"label":"Padişah halkın ayağına gitmez; dilekçeleri kâtipler incelesin.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Mazlumun Şikâyet Kapısının Kapanmaması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Mazlumun Şikâyet Kapısının Kapanmaması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Mazlumun Şikâyet Kapısının Kapanmaması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 889) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_890', 'ottoman', 'Yusuf Has Hacib\'in \'Kün-Toğdı\' Adalet Güneşi', 'Kutadgu Bilig', 'Türk-İslam siyasetinin kurucu eseri: \'Hükümdar adalet güneşidir; ışığı zengine de fakire de, beye de çobana da eşit vurmalıdır!\' dedi.', '[{"id":"char_yusuf_has_hacib","name":"Yusuf Has Hacib"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Adalet güneşini parlat: Kanun önünde vezir ile köylüyü eşit tut, hiçbir ayrıcalığa izin verme.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -2","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-2},"log":"Türk-İslam nizamı kemale erdi; mülk asırlarca parlayacak bir adalete kavuştu."},{"label":"Beyler üstündür, köylüyle bir tutulamaz de.","preview":"Reaya +6, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Yusuf Has Hacib\'in \'Kün-Toğdı\' Adalet Güneşi nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Yusuf Has Hacib\'in \'Kün-Toğdı\' Adalet Güneşi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Yusuf Has Hacib\'in \'Kün-Toğdı\' Adalet Güneşi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 890) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_891', 'ottoman', 'Asabiyenin Çözülüşü ve Lüksün Yıkımı', 'İbn Haldun\'un Mukaddimesi', 'Tarih sosyolojisinin kurucusu: \'Devletler yerleşik hayata geçip saraylar diktiğinde konfor ve lüks savaşçı asabiyeyi öldürür; ordu paralı asker olunca çöküş başlar!\' dedi.', '[{"id":"char_ibn_haldun","name":"İbn Haldun"},{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Sarayda sadeliğe dön: Askeri talimi sertleştir, saray lüksünü kıs ve milli dayanışma ruhunu dirilt.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Lüksün zehri atıldı; devlet genç ve dinamik fetih ruhuna geri döndü."},{"label":"İmparatorluk debdebeyle yaşar; altın saraylar yapmaya devam edin.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Asabiyenin Çözülüşü ve Lüksün Yıkımı nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Asabiyenin Çözülüşü ve Lüksün Yıkımı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Asabiyenin Çözülüşü ve Lüksün Yıkımı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 891) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_892', 'ottoman', 'Düşük Vergi ile Yüksek Hasılat Mucizesi', 'İbn Haldun\'un İktisat Yasası', 'Mukaddime\'nin maliye kanunu: \'Vergi oranları hafif tutulursa herkes şevkle üretir, ticaret patlar ve hazine dolar; ağır vergi ise üretimi öldürür!\'', '[{"id":"char_ibn_haldun","name":"İbn Haldun"}]', '[{"label":"Vergileri hafiflet, gümrükleri indir ve üreticiyi teşvik et; tebaanın kazanmasına izin ver.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"İktisadi bereket patladı; düşük vergiyle hazine ağzına kadar altınla doldu."},{"label":"Hazinenin acil paraya ihtiyacı var; vergi oranlarını iki katına çıkarın.","preview":"Reaya +9, Otorite +6 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Düşük Vergi ile Yüksek Hasılat Mucizesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Düşük Vergi ile Yüksek Hasılat Mucizesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +8 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Düşük Vergi ile Yüksek Hasılat Mucizesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 892) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_893', 'ottoman', 'Gıyâsü\'l-Ümem\'deki Olağanüstü Hal Siyaseti', 'İmâmü\'l-Haremeyn el-Cüveynî', 'Kriz fakihi: \'Devlet fetret veya kriz dönemindeyse hükümdar kılıçla değil, kamu menfaatini koruyan hikmetli hukukla nizamı sürdürür!\' dedi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Krizi hukukla yönet: İstişare meclislerini topla, kamu menfaatini öncele ve fitneyi adaletle teskin et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Büyük buhran kan dökülmeden aşıldı; devlet aklı galip geldi."},{"label":"Kriz anında kanun dinlenmez; darağaçları kurup herkesi sindirin.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":9,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Gıyâsü\'l-Ümem\'deki Olağanüstü Hal Siyaseti nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Gıyâsü\'l-Ümem\'deki Olağanüstü Hal Siyaseti fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gıyâsü\'l-Ümem\'deki Olağanüstü Hal Siyaseti meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 893) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_894', 'ottoman', 'Harun Reşid\'e Verilen Vergi ve Mülkiyet Dersi', 'Ebû Yûsuf\'un Kitâbü\'l-Harâc\'ı', 'İslam iktisadının kurucusu: \'Tebaaya güçlerinin yetmeyeceği vergi yükleme! Hazineyi doldurmak için köylünün tohumunu elinden alan devlet helak olur!\' dedi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kitâbü\'l-Harâc hükümlerini uygula: Köylünün gelirine göre adil vergi al, kuraklıkta vergisini sil.","preview":"Adalet +7, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":7,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Topraklar şenlendi; çiftçinin duası hazinenin en büyük bereketi oldu."},{"label":"Köylü ne kadar vergi verirse o kadar iyidir; haracı eksiltmeyin.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Harun Reşid\'e Verilen Vergi ve Mülkiyet Dersi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Harun Reşid\'e Verilen Vergi ve Mülkiyet Dersi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Harun Reşid\'e Verilen Vergi ve Mülkiyet Dersi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +6 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 894) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_895', 'ottoman', 'Devlet Adamlığı ve Elçilik Edebi', 'Keykâvus\'un Kâbûsnâme\'si', 'Ziyârî prensi: \'Akıllı hükümdar düşmanla hemen savaşa tutuşmaz; önce tatlı dilli, haysiyetli ve bilgili elçilerle diplomasiyi işletir!\' dedi.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Diplomasiyi işlet: Lisan bilen ve vakar sahibi sefirleri gönder; savaşı masada kazan.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Kan dökülmeden büyük kaleler fethedildi; devletin diplomatik heybeti parladı."},{"label":"Konuşmak zayıflıktır; hemen hücum emri verin.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Devlet Adamlığı ve Elçilik Edebi meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +6, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Devlet Adamlığı ve Elçilik Edebi hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +9, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Devlet Adamlığı ve Elçilik Edebi gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 895) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_896', 'ottoman', 'Cevdet Paşa\'nın \'Zarar İzale Olunur\' İlkesi', 'Mecelle-i Ahkâm-ı Adliyye', 'Klasik İslam kamu hukukunun ana kaidesi mecliste yankılandı: \'Zarar ve mukabele-i bizzarar yoktur; kamu menfaati için de olsa ferde zulmedilemez!\'', '[{"id":"char_ahmet_cevdet_pasa","name":"Ahmet Cevdet Paşa"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Kaideyi kanun yap: Devlet kamulaştırma yaparken dahi vatandaşın hakkını peşin ve piyasa rayiciyle ödesin.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Mülkiyet hakkı teminat altına alındı; vatandaş devletine aşkla bağlandı."},{"label":"Devlet her şeyin sahibidir; istediği arazisini bedelsiz alır de.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Cevdet Paşa\'nın \'Zarar İzale Olunur\' İlkesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Cevdet Paşa\'nın \'Zarar İzale Olunur\' İlkesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Cevdet Paşa\'nın \'Zarar İzale Olunur\' İlkesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":9,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 896) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_897', 'ottoman', 'İstişaresiz Karar Alan Hükümdarın Hatası', 'Meşveret Meclisi', 'Padişahın vezirlerine danışmadan kendi başına verdiği ani bir savaş kararı ordunun bataklıkta kuşatılmasına sebep oldu.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Hatanı kabul et: Divanı topla, komutanların ortak harp planına tabi ol ve orduyu kurtar.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Kolektif akıl orduyu hezimetten kurtardı; zafer meşveretle kazanıldı."},{"label":"Hükümdar hata yapmaz; kumandanları idama gönderin.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve İstişaresiz Karar Alan Hükümdarın Hatası nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve İstişaresiz Karar Alan Hükümdarın Hatası fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve İstişaresiz Karar Alan Hükümdarın Hatası meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 897) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_898', 'ottoman', 'İnsanı Yaşat ki Devlet Yaşasın!', 'Şeyh Edebali\'nin Vasiyeti', 'Osman Gazi\'ye verilen kurucu öğüt divanın duvarlarında yankılandı: \'Ey oğul! Ananı, atanı say; bereket büyüklerle beraberdir. İnsanı yaşat ki devlet yaşasın!\'', '[{"id":"char_seyh_edebali","name":"Şeyh Edebali"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Vasiyeti mülkün ruhu bil: Bütün siyasetini halkın huzuruna, can emniyetine ve refahına ada.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"İnsan yaşadı, devlet yaşadı; mülk asırları aşan bir cihan nizamı oldu."},{"label":"Devlet insan için değil, insan devlet için ölmek içindir de.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İnsanı Yaşat ki Devlet Yaşasın sebebiyle aksayan menzilhane masraflarını karşılamak üzere bütçeden düzenli posta ödeneği bağla; ulak atlarının kiralanmasını ağır para cezasıyla önle.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Menzil eminini derhal azlet; İnsanı Yaşat ki Devlet Yaşasın meselesinde devlet atlarını şahsi ticaretine alet eden görevlileri prangaya vurup divan çavuşlarına teslim et.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Menzilhane ve Berid Teşkilatı Nizamı\' neşret; İnsanı Yaşat ki Devlet Yaşasın gibi hadiselerin tekerrürünü önleyecek şekilde ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 898) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_899', 'ottoman', 'Sekiz Direğin Ebedi Birleşimi', 'Dâire-i Adliyye\'nin Kalbi', 'Kınalızâde Ali Çelebi son defa divana çıkar: \'Ey Hükümdar! Adalet cihanın selametidir, cihan bir bağdır duvarı devlet, devletin kurucusu şeriat, şeriatın koruyucusu mülk, mülkü tutan ordu, orduyu besleyen mal, malı üreten reaya, reayayı devlete kul eden ise ancak ADALETTİR!\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"ÇEMBERİ MÜHÜRLE: \'BU SEKİZ HALKA BİRBİRİNE EMANETTİR, BİRİ BİLE KOPARILAMAZ!\'.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Dâire-i Adliyye hakikatiyle nizam-ı mülk tamamlandı; devlet ebed-müddet mertebesine erdi."},{"label":"Kılıç tek başına yeterlidir; gerisi felsefedir deyip çemberi boz.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Sekiz Direğin Ebedi Birleşimi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Sekiz Direğin Ebedi Birleşimi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Sekiz Direğin Ebedi Birleşimi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 899) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_900', 'ottoman', 'Ebed-Müddet Mühür: Adalet Mülkün Temelidir!', 'Nizâm-ı Âlem Tacı', 'Dokuz yüz vakalık büyük imtihan kemale erdi. Şeyh Edebali, Nizamülmülk, Fârâbî, Mâverdî, İbn Haldun ve Kınalızâde tek bir ağızdan mühür vurur: Mülk kılıçla fethedilir, ancak ADALETLE yaşar!', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"}]', '[{"label":"MÜHRÜ BAS: \'ADALET MÜLKÜN TEMELİDİR, ZULÜM İSE MÜLKÜN ZEVALİDİR!\'.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -4","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-4},"log":"Adalet çemberi kainat nizamıyla kenetlendi; cihanşümul sulh, adalet ve saadet tecelli etti."},{"label":"Kuvvet benimdir, dilediğimi ezerim.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Ebed-Müddet Mühür: Adalet Mülkün Temelidir! nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Ebed-Müddet Mühür: Adalet Mülkün Temelidir! fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ebed-Müddet Mühür: Adalet Mülkün Temelidir! meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 900) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_901', 'ottoman', 'Kırkçeşme Su Künklerine Kaçak Bağlantı', 'Su Yolcuları Kâhyalığı', 'Sarayburnu ve Fatih mahallelerine içme suyu taşıyan Mimar Sinan künklerinin zengin bir paşa tarafından delinip özel konağının mermer havuzuna akıtıldığı tespit edildi.', '[{"id":"char_mimar_sinan","name":"Mimar Sinan"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kaçak künkü derhal balyozla kırdır, paşaya ağır para cezası kes ve suyu umumi çeşmelere ver.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Halkın suyu kurtarıldı; paşanın keyfi zorbalığı mahalleli önünde cezalandırıldı."},{"label":"Paşa devletin rüknüdür; konağına cüzi bir su payı bağlayıp olayı büyütme.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kırkçeşme Su Künklerine Kaçak Bağlantı meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Kırkçeşme Su Künklerine Kaçak Bağlantı hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Kırkçeşme Su Künklerine Kaçak Bağlantı gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 901) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_902', 'ottoman', 'Haliç Kıyısındaki Ahşap Binalara Kâgir Şartı', 'Hassa Mimarları', 'Tersane ve kapanlar çevresindeki ahşap barakaların yangında donanmayı tehdit etmesi sebebiyle binaların taştan yapılmasını zorunlu kılan nizamname sunuldu.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Kâgir şartını kanunlaştır; fukara esnafa taş bina yapabilmesi için hazineden uzun vadeli kredi aç.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Haliç kıyısı yangın felaketinden korundu; tersane emniyete alındı."},{"label":"Esnaf neyle yaparsa yapsın; taş bina masrafına devlet divan gözetiminde tarafları meşverete davet edip orta yolu bulz.","preview":"Reaya +7, Otorite +8 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Haliç Kıyısındaki Ahşap Binalara Kâgir Şartı nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Haliç Kıyısındaki Ahşap Binalara Kâgir Şartı fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Haliç Kıyısındaki Ahşap Binalara Kâgir Şartı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 902) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_903', 'ottoman', 'Tarihi Türbe Çevresine Yapılan Kaçak Kahvehaneler', 'Eyüp Kadılığı', 'Ebû Eyyûb el-Ensârî türbesinin avlu duvarına bitişik nargile ve kumar kahvehaneleri açıldığı, cemaatin huzurunun kaçtığı ihbar edildi.', '[{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Kaçak dükkânları derhal yıktır, türbe çevresini gül ve çınar bahçesi yaparak sükuneti sağla.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Mukaddes mekânın vakarı korundu; halk hayır dualarıyla hükümdara bağlandı."},{"label":"Kahvehaneciler kira ödüyor; meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayıp kiranın bir kısmını vakfa aktarın.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Tarihi Türbe Çevresine Yapılan Kaçak Kahvehaneler nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Tarihi Türbe Çevresine Yapılan Kaçak Kahvehaneler fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tarihi Türbe Çevresine Yapılan Kaçak Kahvehaneler meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 903) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_904', 'ottoman', 'Payitahtta Kolera Salgını ve Kireç Kuyuları', 'Hekimbaşı Tezkiresi', 'Kasımpaşa ve Galata\'da baş gösteren kolera yüzünden her gün yüzlerce insanın öldüğü, kireçli toplu mezarlar ve temiz su bentleri gerektiği bildirildi.', '[{"id":"char_hekimbasi","name":"Hekimbaşı"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Hazineyi aç; mahallelere kaynamış su dağıt, sıhhiye karantinası kur ve cesetleri hızla kireçlet.","preview":"Adalet +9, Reaya +6 | Hazine -3, Otorite -1","effects":{"justice":9,"people":6,"treasury":-3,"military":0,"authority":-1},"log":"Salgın kontrol altına alındı; binlerce masum tebaanın hayatı kurtarıldı."},{"label":"Hastalık takdirdir; karantina ticareti aksatır deyip şehri kefalete bağlayıp divan murakabesinde ıslahına fırsat tanı.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Payitahtta Kolera Salgını ve Kireç Kuyuları meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Payitahtta Kolera Salgını ve Kireç Kuyuları hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Payitahtta Kolera Salgını ve Kireç Kuyuları gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":9,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 904) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_905', 'ottoman', 'Tarihi Sur Taşlarının Ev İnşaatında Yağmalanması', 'İstanbul Şehremaneti', 'Yedikule ve Topkapı surlarının asırlık kesme taşlarının gece vakti arabalarla sökülüp paşa yalılarına temel yapıldığı görüldü.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Taş hırsızlarını zindana at, sökülen taşları geri koydur ve sur boyuna muhafız devriyesi çıkar.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -2","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-2},"log":"Tarihi surlar yağmadan korundu; şehrin tahkimat kapıları emniyete alındı."},{"label":"Surlar eski Bizans taşıdır; Müslüman evine temel olsun deyip aldırma.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Tarihi Sur Taşlarının Ev İnşaatında Yağmalanması nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Tarihi Sur Taşlarının Ev İnşaatında Yağmalanması fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Tarihi Sur Taşlarının Ev İnşaatında Yağmalanması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +9 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 905) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_906', 'ottoman', 'Medrese Çatılarındaki Kurşun Levhaların Çalınması', 'Vakıflar İdaresi', 'Fatih Külliyesi medreselerinin kubbe kurşunlarını gece eritip kurşun külçesi olarak hurdacılara satan bir çete yakalandı.', '[{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"},{"id":"char_celali_eskiya","name":"Celali / Eşkıya Başı"}]', '[{"label":"Çeteyi ve hırsız hurdacıları küreğe mahkûm et; kubbeleri derhal yeni kurşun levhalarla kaplat.","preview":"Adalet +9, Reaya +9 | Hazine -2, Otorite -2","effects":{"justice":9,"people":9,"treasury":-2,"military":0,"authority":-2},"log":"Kütüphaneler su almaktan kurtuldu; ata mirası mabetler emniyete kavuştu."},{"label":"Kurşun pahalıdır; kubbeleri çamur sıva ve kireçle sıvayıp kapatın.","preview":"Reaya +6, Otorite +8 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Medrese Çatılarındaki Kurşun Levhaların Çalınması nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Medrese Çatılarındaki Kurşun Levhaların Çalınması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Medrese Çatılarındaki Kurşun Levhaların Çalınması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 906) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_907', 'ottoman', 'Boğaz Kıyısında Kaçak İskele Kuran Tüccarlar', 'Boğaziçi Muhafızlığı', 'Yabancı gemilerin gece gizlice mal indirip gümrük kaçırması için Kandilli kıyısına ruhsatsız ahşap iskeleler çakıldığı tespit edildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Kaçak iskeleleri kalyon toplarıyla yıktır, sahile muhafız nöbetçileri dik ve mallara el koy.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Gece kaçakçılığı durduruldu; gümrük gelirleri hazineye eksiksiz aktı."},{"label":"İskele sahiplerinden maktu vergi alıp iskeleyi yerinde bırakın.","preview":"Reaya +6, Otorite +9 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":6,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Boğaz Kıyısında Kaçak İskele Kuran Tüccarlar hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Boğaz Kıyısında Kaçak İskele Kuran Tüccarlar hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Boğaz Kıyısında Kaçak İskele Kuran Tüccarlar gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 907) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_908', 'ottoman', 'Hortacı Camii Çevresindeki Meyhane Taşkınlığı', 'Selanik Kadılığı', 'Eski caminin avlu kapısının tam karşısına açılan meyhanelerden çıkan sarhoşların cemaate hakaret ettiği arz edildi.', '[{"id":"char_selanik_kadisi","name":"Selanik Kadısı"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Meyhaneleri cami ve mektep sınırından 200 arşın uzağa taşıt; uymayanın fıçılarını kırdır.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Mabet çevresine vakar ve sükûnet geldi; mahalleli huzura kavuştu."},{"label":"Zimmîlerin ticaretidir; sarhoşluğa çok divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +6, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Hortacı Camii Çevresindeki Meyhane Taşkınlığı nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Hortacı Camii Çevresindeki Meyhane Taşkınlığı fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Hortacı Camii Çevresindeki Meyhane Taşkınlığı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":7,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 908) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_909', 'ottoman', 'Gökdere Taşkını ve Köprülerin Yıkılması', 'Bursa Şehremaneti', 'Uludağ\'dan inen taşkın suları Bursa\'nın kadim köprülerini yıktı; su değirmenleri su altında kaldı, un öğütülemiyor.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"İstihkâm neferlerini gönder; köprüleri taştan yeniden kurdur ve su bentlerini temizlet.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Bursa köprüleri kurtarıldı; un değirmenleri dönmeye başlayıp kıtlığı önledi."},{"label":"Köylüler salla karşıya geçsin; köprü yapacak para yoktur.","preview":"Reaya +9, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Gökdere Taşkını ve Köprülerin Yıkılması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Gökdere Taşkını ve Köprülerin Yıkılması fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Gökdere Taşkını ve Köprülerin Yıkılması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":8,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 909) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_910', 'ottoman', 'Süleymaniye Kubbesinde Kurşun Sızıntısı', 'Hassa Mimarları', 'Sinan\'ın başyapıtı Süleymaniye Camii\'nin ana kubbe derzlerinin açıldığı ve yağmur suyunun tarihi hat yazılarına aktığı görüldü.', '[{"id":"char_hassa_mimarbasisi","name":"Hassa Mimarbaşısı"},{"id":"char_cami_imami","name":"Cami İmamı"}]', '[{"label":"Derhal mimar kalfalarını kubbe iskelesine çıkar; saf kurşun kaynatarak şaheseri koru.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Karahisârî\'nin eşsiz hat yazıları kurtarıldı; cihan mabedi pırıl pırıl parladı."},{"label":"Kovalar koyup suyu tutsunlar; kubbe tamiri çok pahalıdır.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Süleymaniye Kubbesinde Kurşun Sızıntısı sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Süleymaniye Kubbesinde Kurşun Sızıntısı hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Süleymaniye Kubbesinde Kurşun Sızıntısı gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 910) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_911', 'ottoman', 'Kayıkçı Loncasında Hamallar ile Kavga', 'Üsküdar İskelesi', 'Erzak sandıklarını taşıyan hamallar ile iskele kayıkçılarının rıhtım paylaşımı yüzünden taşlı sopalı savaşa tutuştuğu bildirildi.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"}]', '[{"label":"İskele zabıtasını koy; yük boşaltma saatlerini iki lonca arasında adaletle nöbete bağla.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"İskelede nizam tesis edildi; sandıklar kırılmadan payitahta taşındı."},{"label":"Loncaların kendi meselesidir; birbirlerini yorsunlar.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gedik ve dükkân devir harçlarını şeffaf bir nispete bağla; lonca tezgâhlarını tefecilerin elinden kurtaracak kamu kredisi tahsis et ve Kayıkçı Loncasında Hamallar ile Kavga nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hileli mal satan lonca ustalarını esnaf önünde falakaya yatır; haksız kazanç sağlayan lonca kethüdasını vazifeden azlet ve Kayıkçı Loncasında Hamallar ile Kavga fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Lonca ve Gedik Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup esnaf gediklerini kayıt altına alıp tartı ve hammadde standartlarını fütüvvetname kanununa bağla ve Kayıkçı Loncasında Hamallar ile Kavga meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 911) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_912', 'ottoman', 'Karanlık Sokaklara Fener Asma Mecburiyeti', 'Payitaht İhtisabı', 'Geceleri hırsızlık ve cinayetleri önlemek için her hane ve dükkânın kapısına camlı kandil asması teklif edildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"}]', '[{"label":"Kandil fermanını neşret: Her kapıya fener asılsın, asmayana ceza kesilsin; sokaklar nura kavuşsun.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Sokak cinayetleri ve hırsızlık bıçak gibi kesildi; halk gece de güvenle yürüdü."},{"label":"Halk kendi evinin önünü aydınlatmak zorunda değildir; ferman çıkarmayın.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Karanlık Sokaklara Fener Asma Mecburiyeti nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Karanlık Sokaklara Fener Asma Mecburiyeti fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Karanlık Sokaklara Fener Asma Mecburiyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":8,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 912) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_913', 'ottoman', 'Köy Kabristanının Sürülüp Buğday Ekilmesi', 'Kaza Sicili', 'Bir ağanın sahipsiz kalmış kadim mezarlığın taşlarını kırıp tarlaya kattığı ve buğday ektiği şikâyet edildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Tarlayı müsadere et, ağayı teşhirle cezalandır ve mezarlığı taş duvarla çevirtip iade et.","preview":"Adalet +9, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":9,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Ölüye hürmet ve mülk hakkı korundu; ağanın mezar talanı cezalandırıldı."},{"label":"Buğday ekilmiş bir kere; hasada kadar meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +7, Otorite +8 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Köy Kabristanının Sürülüp Buğday Ekilmesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Köy Kabristanının Sürülüp Buğday Ekilmesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Köy Kabristanının Sürülüp Buğday Ekilmesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 913) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_914', 'ottoman', 'Meriç Kenarındaki Debbağların Suyu Zehirlemesi', 'Edirne Şehremaneti', 'Deri atölyelerinin zehirli kireç sularını doğrudan Meriç\'e dökmesi yüzünden nehirde binlerce balık kıyıya vurdu.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"},{"id":"char_debbag","name":"Debbağ (Deri Ustası)"}]', '[{"label":"Debbağlara kapalı dinlendirme havuzu kurdur; nehri zehirleyenin atölyesini mühürle.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Meriç suları temizlendi; nehir balıkçılığı ve içme suyu kurtarıldı."},{"label":"Deri ihracatı mühimdir; balık için sanayiyi durdurmayın.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve Meriç Kenarındaki Debbağların Suyu Zehirlemesi nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve Meriç Kenarındaki Debbağların Suyu Zehirlemesi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve Meriç Kenarındaki Debbağların Suyu Zehirlemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -6","effects":{"justice":6,"people":2,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 914) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_915', 'ottoman', 'Fırın Bacalarına Kıvılcım Teli Mecburiyeti', 'İstanbul Fırınları', 'Ahşap evlerin çatısına sıçrayan fırın kıvılcımlarının yangın çıkarmasını önlemek için bacalara tel kafes şartı getirildi.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Nizamı uygula: Kıvılcım teli takmayan fırının ocağını söndür; payitahtı yangından koru.","preview":"Adalet +9, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":9,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Fırın yangınları önlendi; mahalleler ahşap külü olmaktan kurtuldu."},{"label":"Fırıncı masraf yapamaz; tel kafes işini erteleyin.","preview":"Reaya +6, Otorite +6 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":6,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Fırın Bacalarına Kıvılcım Teli Mecburiyeti nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Fırın Bacalarına Kıvılcım Teli Mecburiyeti fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Fırın Bacalarına Kıvılcım Teli Mecburiyeti meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -7","effects":{"justice":9,"people":4,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 915) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_916', 'ottoman', 'Saray Meyve Bahçelerindeki Ağaçların Kuruması', 'Hassa Bahçıvanbaşılığı', 'Topkapı sarayının Hasbahçe\'sindeki asırlık nar ve incir ağaçlarının dip kurdu yüzünden kurumaya başladığı görüldü.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ziraat ehli dervişleri çağır; ağaç diplerine kireç ve şifalı katran sürdürerek kurtları temizlet.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Hasbahçe kurtarıldı; ağaçlar yeniden meyve ve çiçeğe durdu."},{"label":"Kuruyanları kesin, odun yapın; yerine çim ekin.","preview":"Reaya +6, Otorite +7 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray Meyve Bahçelerindeki Ağaçların Kuruması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Saray Meyve Bahçelerindeki Ağaçların Kuruması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Saray Meyve Bahçelerindeki Ağaçların Kuruması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":8,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 916) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_917', 'ottoman', 'At ve Eşeklerin Çarşı Ortasına Pislemesi', 'Üsküdar Çarşısı', 'Kervan hayvanlarının çarşı içine gelişigüzel pislemesi yüzünden dükkânları sinek bastığı, süpürücülerin yetişemediği bildirildi.', '[{"id":"char_kervancibasi","name":"Kervancıbaşı"},{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"}]', '[{"label":"Kervan develerine ve atlarına torba takma mecburiyeti koy; çarşı girişine hayvan parkı kurdur.","preview":"Adalet +7, Reaya +9 | Hazine -1, Otorite -3","effects":{"justice":7,"people":9,"treasury":-1,"military":0,"authority":-3},"log":"Çarşı pırıl pırıl oldu; gıdaların üzerine sinek konması önlendi."},{"label":"Hayvandır, nereye isterse yapar; kervancıyı bunaltmayın.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":6,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kervan geçiş harçlarından cüzi bir payı menzil eminlerine yemlik olarak tahsis et; atların bakım masrafını hazine garantisine al ve At ve Eşeklerin Çarşı Ortasına Pislemesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bolu ve Anadolu menzillerine müfettiş müfrezesi sevk et; ulak seferini geciktiren eminleri görevden alıp sürgüne yolla ve At ve Eşeklerin Çarşı Ortasına Pislemesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Menzilhane ve Berid Teşkilatı Nizamı\' yürürlüğe koy; yetki aşımını durdurup ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve At ve Eşeklerin Çarşı Ortasına Pislemesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 917) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_918', 'ottoman', 'Vakıf Kütüphanesindeki Nadir Yazmaların Rutubeti', 'Kaza Meclisi', 'Kayseri Raşid Efendi Kütüphanesi\'ndeki tek nüsha felsefe ve tıp risalelerinin mahzende küflendiği arz edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Kütüphaneye havalandırmalı taş bina tahsis et, nem tutucu sedir sandıklar yaptır.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Eşsiz el yazmaları kurtarıldı; ilim talipleri eserlere güvenle ulaştı."},{"label":"Kitapları sandıklarda kilitli tutun; masrafa gerek yok.","preview":"Reaya +6, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gasp edilen zeytinlik ve dükkân gelirlerini geçmişe dönük faiziyle tahsil et; vakıf bütçesini mütevelli denetimine al ve Vakıf Kütüphanesindeki Nadir Yazmaların Rutubeti nizamına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Hayrat ve vakıf malına el uzatan yerel ayânları saray çavuşlarıyla yakalat; gasbettikleri mülkleri zorla geri alıp kendilerini hapse at ve Vakıf Kütüphanesindeki Nadir Yazmaların Rutubeti fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Vakıf Kütüphanesindeki Nadir Yazmaların Rutubeti meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 918) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_919', 'ottoman', 'Çöpçülerin Topladığı Çöpleri Denize Dökmesi', 'İstanbul Şehremaneti', 'Şehir süpürücülerinin arabalarla topladığı ev çöplerini Haliç kıyısına döküp koyu doldurduğu tespit edildi.', '[{"id":"char_sehremini","name":"İstanbul Şehremini"}]', '[{"label":"Denize çöp dökmeyi yasakla; sur dışındaki kireçli çöp çukurlarına taşıt, uymayan süpürücübaşını azlet.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Haliç balçıkla dolmaktan kurtarıldı; deniz suyu temiz kaldı."},{"label":"Deniz akıntılıdır, çöpü sürükler; sur dışına taşımak masraflıdır.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":6,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Çöpçülerin Topladığı Çöpleri Denize Dökmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Çöpçülerin Topladığı Çöpleri Denize Dökmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Çöpçülerin Topladığı Çöpleri Denize Dökmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 919) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_920', 'ottoman', 'Büyük Şehir İmar ve Hıfzıssıhha Kanunnâmesi', 'Dîvân-ı Hümâyûn', 'Şehirlerin suyunu, havasını, sokak genişliğini ve yapı nizamını kanun altına alan büyük İmar Fermanı hazırlandı.', '[{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Fermanı mühürle: \'Şehirlerini mamur kılmayan, milletini sağlıklı yaşatmayan hükümdar meşru kalamaz!\'.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -3","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-3},"log":"İmparatorluk şehirleri cihanın en temiz ve mamur merkezleri oldu."},{"label":"Şehirler kendi kendine büyüsün; kanunlarla inşaatı sınırlamayın.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Büyük Şehir İmar ve Hıfzıssıhha Kanunnâmesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Büyük Şehir İmar ve Hıfzıssıhha Kanunnâmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Büyük Şehir İmar ve Hıfzıssıhha Kanunnâmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 920) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_921', 'ottoman', 'Büyük Çekirge Sürülerinin Ekini Yok Etmesi', 'İç Anadolu Tahriratı', 'Suriye çöllerinden gelen dev çekirge bulutları Konya ve Niğde tarlalarına indi; yeşil tek bir başak dahi bırakmıyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Askeri birlikleri ve köylüyü süpürgelerle çekirge yumurtalarını imhaya çıkar; ambarlardan bedava tohum dağıt.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Çekirge yumurtaları topraktan söküldü; gelecek yılın hasadı kurtarıldı."},{"label":"Çekirge Allah\'ın afetidir; çekilmesini duayla bekleyin.","preview":"Reaya +7, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Büyük Çekirge Sürülerinin Ekini Yok Etmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Büyük Çekirge Sürülerinin Ekini Yok Etmesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Büyük Çekirge Sürülerinin Ekini Yok Etmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -7","effects":{"justice":6,"people":1,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 921) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_922', 'ottoman', 'Zeytinliklerde Şiddetli Don Felaketi', 'Ege Vilayeti', 'Balkan ayazı Ege zeytinliklerini vurdu; asırlık ağaçlar yarıldı, köylü öşür vergisini ödeyemeyecek durumda.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Fırtına felaketi sebebiyle bu seneki zeytin öşrünü tamamen affet, köylüye budama desteği ver.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Çiftçiler iflastan kurtuldu; zeytin fidanları yeniden yeşerdi."},{"label":"Hazine tarafların meşru taleplerini dinleyip orta yolda uzlaşz; borçlarını hayvanlarını satıp ödesinler.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Zeytinliklerde Şiddetli Don Felaketi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +7, Otorite +2 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Zeytinliklerde Şiddetli Don Felaketi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Zeytinliklerde Şiddetli Don Felaketi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 922) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_923', 'ottoman', 'Pamuk Tarlalarında Kırmızı Kurt Salgını', 'Çukurova Tahriri', 'Çukurova\'da pamuk kozalarını delen kurtlar lifleri çürüttü; dokuma fabrikaları hammadde bekliyor.', '[{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ziraat muallimlerini yolla; tarlalara kükürtleme yaptır ve çiftçiye faizsiz avans dağıt.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Pamuk hasadı kurtarıldı; tezgâhlar iplik bulup harıl harıl çalıştı."},{"label":"Zarar çiftçinin kaderidir; devlet ilaç parası veremez.","preview":"Reaya +8, Otorite +9 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Pamuk Tarlalarında Kırmızı Kurt Salgını nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Pamuk Tarlalarında Kırmızı Kurt Salgını fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Pamuk Tarlalarında Kırmızı Kurt Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 923) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_924', 'ottoman', 'Birecik Su Dolaplarının Taşkında Parçalanması', 'Fırat Kenarı', 'Fırat\'tan tarlalara su basan devasa ahşap su dolapları taşkında yıkıldı; binlerce dönüm bostan susuzluktan kuruyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Ordu marangozlarını ve tersane kerestelerini sevk et; dolapları acilen yeniden çattır.","preview":"Adalet +9, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":9,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Dolaplar dönmeye başladı; sular bostanlara fışkırıp kuraklığı yendi."},{"label":"Köylü kendi dolabını kendi yapsın; ordu neferini yormayın.","preview":"Reaya +9, Otorite +8 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Birecik Su Dolaplarının Taşkında Parçalanması nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Birecik Su Dolaplarının Taşkında Parçalanması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Birecik Su Dolaplarının Taşkında Parçalanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":9,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 924) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_925', 'ottoman', 'Nil Nilometresinde Su Seviyesinin Düşüklüğü', 'Mısır Valiliği', 'Nil suları bu sene kâfi yükselmedi; çeltik ve buğday ekimi yarıya düştü, Mısır ambarları boş kalma tehlikesinde.', '[{"id":"char_misir_valisi","name":"Mısır Valisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Nilometre kuralını işlet: Kuraklık oranında vergiyi bağışla, Sudan\'dan mısır nakliyatını başlat.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Mısır fukarası açlıktan kurtuldu; adalet taşkın suları gibi gönülleri suladı."},{"label":"Mısır hazinesi payitahta tam gelecektir; vergi affı yapmayın.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":9,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Nil Nilometresinde Su Seviyesinin Düşüklüğü meselesinde kaçak su hattı çekenlerden ağır cerime ve \'mâ-i leziz harcı\' tahsil et; meblağı su kemerlerinin onarımına bağla.","preview":"Hazine +6, Otorite +4 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Su nazırına bostancı müfrezesi ver; Nil Nilometresinde Su Seviyesinin Düşüklüğü hadisesinde kaçak su künklerini balyozla kırdırıp hattı çeken ustaları ve emri verenleri divana celbet.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Suyolları ve Mirî Şebeke Nizamnâmesi\' neşret; Nil Nilometresinde Su Seviyesinin Düşüklüğü gibi hadiselerin tekerrürünü önleyecek şekilde şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -9","effects":{"justice":6,"people":4,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 925) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_926', 'ottoman', 'Meriç Suyunun Paylaşımında Kanlı Kavga', 'Trakya Çeltikçileri', 'Kurak mevsimde nehir suyu azalınca yukarı köydeki pirinç ağaları bendi kapatıp aşağı köylere su bırakmadı.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Zaptiyeyle bendi açtır; nehir suyunu saat esasına göre tüm köylere eşit paylaştır.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Su kavgası bitti; pirinç tarlalarının tamamı eşit suya kavuştu."},{"label":"Yukarı köyün arazisidir, su öncelikle onlarındır de.","preview":"Reaya +6, Otorite +6 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Meriç Suyunun Paylaşımında Kanlı Kavga nizamına bağla.","preview":"Hazine +7, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Meriç Suyunun Paylaşımında Kanlı Kavga fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Meriç Suyunun Paylaşımında Kanlı Kavga meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +6 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 926) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_927', 'ottoman', 'Erken Bastıran Kar ve Sürülerin Dağda Kalması', 'Erzurum Yaylaları', 'Eylül sonunda karlı fırtına koptu; yayladan inemeyen yüz bin koyun ve çobanlar donma tehlikesiyle karşı karşıya.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Sınır alaylarını ve kızakları derhal dağa çıkar; sürüleri ve çobanları vadiye indir.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Sürüler ve çobanlar kurtarıldı; et ve yapağı ambarları ziyan olmadı."},{"label":"Dağ yolları kapalıdır; askerin canını tehlikeye atmayın.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":6,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Erken Bastıran Kar ve Sürülerin Dağda Kalması nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Erken Bastıran Kar ve Sürülerin Dağda Kalması fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Erken Bastıran Kar ve Sürülerin Dağda Kalması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 927) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_928', 'ottoman', 'Zahire Karaborsacılarının Mağaralarda Buğday Saklaması', 'Kaza İhtisabı', 'Kıtlık var diyerek buğdayı dağ mağaralarına saklayıp şehirde ekmek fiyatını dört katına çıkaran simsarlar yakalandı.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_toprak_agasi","name":"Toprak Ağası"}]', '[{"label":"Mağaralardaki buğdayı müsadere et, fırınlara narhtan dağıt ve karaborsacıları meydanda as.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -2","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-2},"log":"Ekmek fiyatları yarıya indi; halk açlıktan kurtulup dualar etti."},{"label":"Tüccarın şahsi malıdır; zorla el koymak mülkiyete uymaz de.","preview":"Reaya +6, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":6,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Zahire Karaborsacılarının Mağaralarda Buğday Saklaması sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +4 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Zahire Karaborsacılarının Mağaralarda Buğday Saklaması hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +9, Otorite +6 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Zahire Karaborsacılarının Mağaralarda Buğday Saklaması gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -7","effects":{"justice":7,"people":3,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 928) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_929', 'ottoman', 'Kuraklık Yüzünden Tohumluk Buğdayın Yenmesi', 'Konya Ovası', 'Aç kalan köylülerin gelecek yıl ekecekleri tohumluk buğdayı öğütüp ekmek yaptığı feryatla duyuruldu.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"Devlet ambarlarından ücretsiz tohum hibe et; \'Tohumunu yiyen millet geleceğini yer!\'.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -3","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-3},"log":"Tarlalar tohumsuz kalmadı; ertesi yıl bereketli hasatla hazine doldu."},{"label":"Tohumu yerlerse seneye aç kalırlar; kendi başlarının çaresine baksınlar.","preview":"Reaya +9, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Fırıncı ve esnafa hazineden un sübvansiyonu sağla; ekmek fiyatını halkı ezmeyecek seviyede tutarken spekülasyon yapanları mali denetime al ve Kuraklık Yüzünden Tohumluk Buğdayın Yenmesi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Muhtesip çavuşlarıyla çarşıya ani baskın düzenle; narh fermanına uymayan bezirgânların dükkânlarını mühürleyip mallarını müsadere et ve Kuraklık Yüzünden Tohumluk Buğdayın Yenmesi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'İhtisap ve Narh Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kuraklık Yüzünden Tohumluk Buğdayın Yenmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +6 | Hazine -8","effects":{"justice":6,"people":1,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 929) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_930', 'ottoman', 'Dut Yapraklarına Tırtıl Salgını', 'Bursa İpekçileri', 'İpekböceklerini besleyen yüz binlerce dut ağacını orman tırtılları istila etti; yaprak kalmadığı için böcekler ölüyor.', '[{"id":"char_toprak_agasi","name":"Toprak Ağası"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Bursa köylerine kireç ve kükürt dumanlama desteği ver; dutlukları kurtar.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Dut ağaçları kurtarıldı; ipekböcekleri kozalarını örüp üretimi kurtardı."},{"label":"Tırtıl tabiatın işidir; ilaçlama masrafına girmeyin.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Dut Yapraklarına Tırtıl Salgını nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Dut Yapraklarına Tırtıl Salgını fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Dut Yapraklarına Tırtıl Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 930) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_931', 'ottoman', 'Kestane Dal Kanserinin Yayılması', 'Karadeniz Sahili', 'Kafkasya\'dan gelen mantar hastalığının Karadeniz kıyısındaki yabani ve aşılı kestane ormanlarını kuruttuğu görüldü.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_darussifa_hastasi","name":"Darüşşifa Hastası"}]', '[{"label":"Hastalıklı ağaçları derhal kestirip yaktır; köylüye dayanıklı fidan tahsisi yap.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Hastalık diğer vadilere sıçramadan durduruldu; kestane hasadı korundu."},{"label":"Kestaneler kendi kendine kurur; ormana masraf yapmayın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kestane Dal Kanserinin Yayılması hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +2 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Kestane Dal Kanserinin Yayılması hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Kestane Dal Kanserinin Yayılması gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 931) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_932', 'ottoman', 'Kuru İncirde Kurtlanma ve Güve Salgını', 'Aydın Bağları', 'Ambarlarda bekleyen incirleri güve bastı; kurutma sergilerine kükürt buharı verilmezse tüm mahsul çürüyecek.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"İncir kooperatif ambarlarına kükürtleme fırınları kurdur; ihracat malını kurtar.","preview":"Adalet +6, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":6,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"İncirler güveden temizlendi; Avrupa limanlarına tam kalitede satıldı."},{"label":"Kurtlu incirleri ucuza iç pazara satın.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Kuru İncirde Kurtlanma ve Güve Salgını nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Kuru İncirde Kurtlanma ve Güve Salgını fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Kuru İncirde Kurtlanma ve Güve Salgını meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 932) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_933', 'ottoman', 'Kıtlık Sebebiyle Köylerden Başkente Kaçış', 'Sivas Vilayeti', 'Kuraklık yüzünden aç kalan binlerce köylü aileleriyle payitaht surlarının önüne yığıldı; şehirde sefalet başladı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Köylüleri boş devlet çiftliklerine yerleştir, tohum ve çadır verip tarıma bağla.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Muhacir köylüler üretici oldu; payitaht çevresinde tarım patlaması yaşandı."},{"label":"Zaptiye zoruyla köyleri neredeyse oraya geri sürün.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Kıtlık Sebebiyle Köylerden Başkente Kaçış nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Kıtlık Sebebiyle Köylerden Başkente Kaçış fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Kıtlık Sebebiyle Köylerden Başkente Kaçış meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +8 | Hazine -8","effects":{"justice":9,"people":1,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 933) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_934', 'ottoman', 'Ambarlara Dadanan Sıçan ve Fare Sürüleri', 'Payitaht Zahire Ambarları', 'Devlet buğday ambarlarına giren farelerin çuvalları delip tonlarca buğdayı telef ettiği görüldü.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Taş ambarları havalandırmalı sac levhalarla kaplat ve sokak kedilerini ambarlara tahsis et.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -4","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-4},"log":"Tahıllar kurtarıldı; tabii yöntemle fareler ambarlardan temizlendi."},{"label":"Fare zehri serpin; buğdayla karışsa da bir şey olmaz.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Ambarlara Dadanan Sıçan ve Fare Sürüleri sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +8, Otorite +4 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Ambarlara Dadanan Sıçan ve Fare Sürüleri hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Ambarlara Dadanan Sıçan ve Fare Sürüleri gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":8,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 934) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_935', 'ottoman', 'Sıtma Yayan Bataklıkların Şehir Merkezine Dayanması', 'Edirne Çeltikçileri', 'Pirinç mültezimlerinin kontrolsüz su basması yüzünden Edirne surlarına kadar bataklık yayıldı; sıtma halkı kırıyor.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_tasra_ayani","name":"Taşra Âyanı"}]', '[{"label":"Surlara yakın çeltik ekimini yasakla; bataklıkları okaliptüs fidanlarıyla kurut.","preview":"Adalet +9, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":9,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Sıtma mikrobu kurutuldu; Edirne halkı derin bir nefes aldı."},{"label":"Pirinç gelirinden vazgeçilmez; mültezim istediği yere su bassın.","preview":"Reaya +9, Otorite +8 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Sıtma Yayan Bataklıkların Şehir Merkezine Dayanması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Sıtma Yayan Bataklıkların Şehir Merkezine Dayanması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Sıtma Yayan Bataklıkların Şehir Merkezine Dayanması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 935) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_936', 'ottoman', 'Mısır Tarlalarında Yaban Domuzu İstilası', 'Trabzon Kırsalı', 'Ormanlardan inen domuz sürülerinin dik yamaçlardaki mısır tarlalarını bir gecede yerle bir ettiği bildirildi.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Köylü avcılara barut ve kurşun tahsisi yap; sürek avı düzenleyip hasadı koru.","preview":"Adalet +6, Reaya +6 | Hazine -3, Otorite -3","effects":{"justice":6,"people":6,"treasury":-3,"military":0,"authority":-3},"log":"Mısır tarlaları kurtarıldı; köylünün kışlık ekmeği teminata alındı."},{"label":"Köylü tarlasının başında nöbet tutsun; hazineden barut verilmez.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Mısır Tarlalarında Yaban Domuzu İstilası nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Mısır Tarlalarında Yaban Domuzu İstilası fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Mısır Tarlalarında Yaban Domuzu İstilası meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 936) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_937', 'ottoman', 'Şiddetli Don Sebebiyle Tahıl Filizlerinin Çürümesi', 'Kayseri Ovası', 'Bahar başında aniden sıfırın altına düşen sıcaklıklar filizlenen buğdayı yaktı; ekinler sararıp öldü.', '[{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Acil baharlık mısır ve darı tohumu dağıt; tarlaların boş kalmasını engelle.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Tarlalar kurtarıldı; mısır hasadı buğdayın yokluğunu unutturdu."},{"label":"Tarlayı nadasa bırakın; seneye yeniden ekersiniz.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Şiddetli Don Sebebiyle Tahıl Filizlerinin Çürümesi sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +9, Otorite +1 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Şiddetli Don Sebebiyle Tahıl Filizlerinin Çürümesi hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +7, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Şiddetli Don Sebebiyle Tahıl Filizlerinin Çürümesi gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +4, Otorite +9 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 937) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_938', 'ottoman', 'Pamuk Tarlalarında Tuzlanma Tehlikesi', 'Gediz Havzası', 'Yanlış sulama yüzünden Gediz ovasındaki en verimli pamuk tarlaları beyaz tuza kesti; ekin boy vermiyor.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Drenaj kanalları açtırıp toprağı tatlı nehir suyuyla yıka; nöbetleşe ekim mecburi kıl.","preview":"Adalet +8, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":8,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Toprak tuzdan temizlendi; pamuk lifleri yeniden fışkırdı."},{"label":"Tuzlu toprağa arpa ekin; drenaj masraflıdır.","preview":"Reaya +9, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Pamuk Tarlalarında Tuzlanma Tehlikesi nizamına bağla.","preview":"Hazine +8, Otorite +1 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Pamuk Tarlalarında Tuzlanma Tehlikesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Pamuk Tarlalarında Tuzlanma Tehlikesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +9 | Hazine -9","effects":{"justice":8,"people":2,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 938) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_939', 'ottoman', 'Kıtlık Sebebiyle Aşiretlerin Buğday Kervanlarını Yağmalaması', 'Halep Kırsalı', 'Çölde aç kalan bedevilerin payitahta buğday taşıyan develeri basıp çuvalları paylaştığı bildirildi.', '[{"id":"char_kervancibasi","name":"Kervancıbaşı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Aşiretlere ambarlardan acil yardım buğdayı tahsis et ama kervan yağmacılarını adaletle cezalandır.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Hem açlık dindirildi hem de yolların emniyeti sağlandı."},{"label":"Bütün aşiret çadırlarını süvarilerle ateşe verin.","preview":"Reaya +6, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":6,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Kıtlık Sebebiyle Aşiretlerin Buğday Kervanlarını Yağmalaması nizamına bağla.","preview":"Hazine +9, Otorite +1 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":9,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Kıtlık Sebebiyle Aşiretlerin Buğday Kervanlarını Yağmalaması fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Kıtlık Sebebiyle Aşiretlerin Buğday Kervanlarını Yağmalaması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +6 | Hazine -9","effects":{"justice":7,"people":4,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 939) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_940', 'ottoman', 'Büyük İaşe ve Kıtlık Nizamnamesi', 'Dîvân-ı Hümâyûn', 'Kuraklık ve afet anında devletin tüm ambarlarını halka açmasını, aşırı kârı yasaklamasını emreden ferman hazırlandı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Fermanı mühürle: \'Tebaa açken sarayda tok yatan hükümdar zâlimdir; ambarlar halkındır!\'.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Kıtlık felaketi devlet eliyle yenildi; millet hükümdara canıyla bağlandı."},{"label":"Kıtlık serbest piyasadır; kim çok verirse buğdayı o alsın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Büyük İaşe ve Kıtlık Nizamnamesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Büyük İaşe ve Kıtlık Nizamnamesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Büyük İaşe ve Kıtlık Nizamnamesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 940) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_941', 'ottoman', 'İlk Kâğıt Paranın (Kâime) İntizamı', 'Maliye Nezareti', 'Maden darlığı sebebiyle basılan el yazması mühürlü kâimelerin piyasada sahtelerinin türediği ve değer kaybettiği görüldü.', '[{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Kâimeleri altın karşılığıyla garantiye al; sahtecileri as ve matbaada filigranlı kâğıda bas.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -4","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-4},"log":"Kâğıt paraya güven tesis edildi; ticaret modern banknotla hızlandı."},{"label":"Karşılıksız kâime basmaya devam edin; harcamalar çoktur.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve İlk Kâğıt Paranın (Kâime) İntizamı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve İlk Kâğıt Paranın (Kâime) İntizamı fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve İlk Kâğıt Paranın (Kâime) İntizamı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 941) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_942', 'ottoman', 'Galata Sarraflarının Kâime Kırma Vurgunu', 'Galata Rıhtımı', 'Tüccar ve sarrafların devletin 100 kuruşluk kâimesini vatandaştan 60 kuruşa kırarak fukarayı soyduğu tespit edildi.', '[{"id":"char_sarraf","name":"Sarraf / Kuyumcu"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Sarrafların kâime kırmasını kanunen yasakla; kurşunlu resmi kambiyo büroları açtır.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Sarraf vurgunu durduruldu; memur ve esnaf maaşının tam karşılığını aldı."},{"label":"Piyasa rayicidir; sarrafların iskonto hakkına divan gözetiminde tarafları meşverete davet edip orta yolu bulyın.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Galata Sarraflarının Kâime Kırma Vurgunu nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Galata Sarraflarının Kâime Kırma Vurgunu fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Galata Sarraflarının Kâime Kırma Vurgunu meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 942) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_943', 'ottoman', 'Yabancı Reji Şirketinin Köylüyü Silahla Tacizi', 'Tütün Rejisi İdaresi', 'Dış borçlar için kurulan yabancı Reji idaresinin silahlı kolcuları, kendi tütününü içen köylüleri kurşunlamaya başladı.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kolcuların silah taşımasını yasakla! Reji şirketini feshet ve tütün tekelini devlete geri al.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Milli egemenlik korundu; köylü yabancı şirket zorbalığından kurtuldu."},{"label":"Avrupa devletleri borç için baskı yapıyor; kolculara meşveret meclisinde tarafların haklarını dengeleyen bir uzlaşı sağlayın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Yabancı Reji Şirketinin Köylüyü Silahla Tacizi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +6, Otorite +3 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Yabancı Reji Şirketinin Köylüyü Silahla Tacizi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Yabancı Reji Şirketinin Köylüyü Silahla Tacizi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +6, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 943) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_944', 'ottoman', 'Altın Mecidiye Sikkesinin Ayarı', 'Darbhane-i Âmire', 'Sultan Abdülmecid devrinde basılacak yeni altın Mecidiyelerin ayarının dünya standartlarında tutulması teklif edildi.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"Saf ayardan şaşma: Mecidiye\'yi Avrupa borsalarında geçerli tam altın kıl.","preview":"Adalet +9, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":9,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Mecidiye altını dünyada itibar kazandı; Osmanlı parası küresel değer oldu."},{"label":"Bakırını biraz artırın; hazineye altın kalsın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Altın Mecidiye Sikkesinin Ayarı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Altın Mecidiye Sikkesinin Ayarı fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Altın Mecidiye Sikkesinin Ayarı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":9,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 944) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_945', 'ottoman', 'Dış Borçlanmada İngiliz Faiz Tuzağı', 'Maliye Kalemi', 'İngiliz bankerlerin yıllık %12 faizle 5 milyon altın teklif ettiği, karşılığında İzmir gümrüklerini ipotek istediği bildirildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_yabanci_banker","name":"Yabancı Banker (Düyun-ı Umumiye)"}]', '[{"label":"İpoteği ve tefeci faizini reddet! \'Borç alan emir alır!\' İç tasarrufla bütçeyi denkleştir.","preview":"Adalet +8, Reaya +9 | Hazine -1, Otorite -1","effects":{"justice":8,"people":9,"treasury":-1,"military":0,"authority":-1},"log":"Devletin boynuna sömürge prangası takılması engellendi; istiklal korundu."},{"label":"Parayı alın; saraylar ve donanma için altın lazımdır.","preview":"Reaya +7, Otorite +7 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tağşiş edilen paraları piyasadan toplatıp hazine kasasında saf külçeye dönüştür; sikke istikrarını devlet garantisine al ve Dış Borçlanmada İngiliz Faiz Tuzağı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Piyasanın gümüşünü eriten sarrafları Divan-ı Hümâyûn huzurunda isticvap et; tağşiş çetelerini derhal küreğe mahkûm eyle ve Dış Borçlanmada İngiliz Faiz Tuzağı fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Darphane ve Meskûkât Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp akçenin gümüş nispetini kanunla sabitleyip tağşiş ve kırpık akçe ticaretini men et ve Dış Borçlanmada İngiliz Faiz Tuzağı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":8,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 945) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_946', 'ottoman', 'Esham Gelirlerinin Zengin Paşalarca Kapatılması', 'Esham İdaresi', 'Halkın küçük birikimleriyle devlete borç vermesi için çıkarılan esham senetlerini zengin paşaların toptan kapattığı görüldü.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Kişi başına alım sınırı koy; senetleri küçük paylarla doğrudan esnafa ve fukaraya sat.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Halk devletine ortak oldu; zengin faizcilerin tekeli kırıldı."},{"label":"Parayı kim verirse senet ona verilsin; toptan satmak kolaydır.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Esham Gelirlerinin Zengin Paşalarca Kapatılması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Esham Gelirlerinin Zengin Paşalarca Kapatılması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Esham Gelirlerinin Zengin Paşalarca Kapatılması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -8","effects":{"justice":7,"people":3,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 946) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_947', 'ottoman', 'Zırhlı Kalyon Alımı İçin Dış Borç Talebi', 'Tersane Kasası', 'İngiltere\'den iki modern zırhlı buhar gemisi almak için yabancı bankadan fahiş faizli borç çekilmesi istendi.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Borçla gemi alınmaz! Kendi tersanemizde buharlı fırkateyn inşaatına yerli bütçe ayır.","preview":"Adalet +6, Reaya +6 | Hazine -4, Otorite -2","effects":{"justice":6,"people":6,"treasury":-4,"military":0,"authority":-2},"log":"Tersane-i Âmire yerli buharlı gemiyi yaptı; dışa bağımlılık önlendi."},{"label":"Borcu çekip İngiliz gemilerini hemen satın alın.","preview":"Reaya +9, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":9,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Zırhlı Kalyon Alımı İçin Dış Borç Talebi nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Zırhlı Kalyon Alımı İçin Dış Borç Talebi fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Zırhlı Kalyon Alımı İçin Dış Borç Talebi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 947) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_948', 'ottoman', 'Memur Maaşlarının Üç Ay Gecikmesi', 'Taşra Mal Sandığı', 'Kaza kâtiplerinin ve zaptiyelerin maaş alamadıkları için esnaftan zorla borç ve rüşvet almaya başladığı bildirildi.', '[{"id":"char_carsi_esnafi","name":"Çarşı Esnafı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Saray ödeneğini derhal kesip taşraya maaş konvoyu çıkar; \'Memuruna bakmayan devlet yaşayamaz!\'.","preview":"Adalet +7, Reaya +6 | Hazine -2, Otorite -3","effects":{"justice":7,"people":6,"treasury":-2,"military":0,"authority":-3},"log":"Rüşvet kapısı kapandı; memurlar namusla vazifesine sarıldı."},{"label":"Memurlar idare etsin; saray bütçesi kısılamaz.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Memur Maaşlarının Üç Ay Gecikmesi nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Memur Maaşlarının Üç Ay Gecikmesi fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Memur Maaşlarının Üç Ay Gecikmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":7,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 948) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_949', 'ottoman', 'İthal Sanayi Mallarına Koruyucu Gümrük Vergisi', 'Gümrük Nezareti', 'Avrupa\'dan gelen ucuz fabrikasyon malların yerli kunduracı, demirci ve dokumacıları iflas ettirdiği bildirildi.', '[{"id":"char_gumruk_emini","name":"Gümrük Emini"},{"id":"char_dokumaci_esnafi","name":"Dokumacı / İpekçi Esnafı"}]', '[{"label":"Gümrük duvarını yükselt! İthal mallara %30 ek gümrük koyup yerli sanayiyi koru.","preview":"Adalet +8, Reaya +6 | Hazine -1, Otorite -1","effects":{"justice":8,"people":6,"treasury":-1,"military":0,"authority":-1},"log":"Yerli atölyeler kepenk kapatmaktan kurtuldu; üretim yeniden şahlandı."},{"label":"Avrupa ile serbest ticaret anlaşmamız var; gümrük koyamayız.","preview":"Reaya +9, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":9,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İthal Sanayi Mallarına Koruyucu Gümrük Vergisi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":8,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; İthal Sanayi Mallarına Koruyucu Gümrük Vergisi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +7 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; İthal Sanayi Mallarına Koruyucu Gümrük Vergisi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +6 | Hazine -6","effects":{"justice":8,"people":4,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 949) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_950', 'ottoman', 'Tuz Tekelinin Fransız Şirketine İltizamla Verilmesi', 'Maliye Kalemi', 'Acil nakit için imparatorluktaki tüm kaya ve deniz tuzlalarının 30 yıllığına Fransız kumpanyasına devri teklif edildi.', '[{"id":"char_multezim","name":"İltizam Mültezimi"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Reddet! Tuz halkın ekmeğidir, ecnebi kumpanyanın tekeline terk edilemez.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Halkın tuzu korundu; yabancı şirketlerin sofraya el uzatması önlendi."},{"label":"Peşin parayı alın; Fransız kumpanyasına tuzlaları teslim edin.","preview":"Reaya +8, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":8,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Korsanların gaspedilen ganimetlerini Beytülmâl\'e aktar; serhad kaleleri ve deniz leventleri için acil mühimmat sandığı oluştur ve Tuz Tekelinin Fransız Şirketine İltizamla Verilmesi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Liman asayişini bozan levend elebaşılarını derhal yakalat; tersane zindanına kapatıp deniz nizamını kılıçla tesis et ve Tuz Tekelinin Fransız Şirketine İltizamla Verilmesi fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tersane-i Âmire ve Bahriye Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup deniz seferi ve kıyı muhafazasını disipline bağlayıp tüccar gemilerinin güvenliğini kanun hükmü kıl ve Tuz Tekelinin Fransız Şirketine İltizamla Verilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +9 | Hazine -8","effects":{"justice":6,"people":3,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 950) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_951', 'ottoman', 'Bakır Meteliklerin Hileli Basımı', 'Darbhane-i Âmire', 'Darphane kâtibinin bakır madenine kurşun katarak bastığı meteliklerin ilk sürtünmede ufalandığı görüldü.', '[{"id":"char_darphane_emini","name":"Darphane Emini"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Kâtibi azlet, bozuk paraları toplatıp erittir ve saf kızıl bakırdan yeni metelikler bas.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -3","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-3},"log":"Çarşıda bozuk para güveni sağlandı; fukara alışverişini huzurla yaptı."},{"label":"Küçük paradır; halk idare etsin deyip masraf etmeyin.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Piyasa narhını bozan bezirgânlara ağır cerime kes; toplanan akçelerle halka ucuz ekmek ve iaşe desteği sağla ve Bakır Meteliklerin Hileli Basımı nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Halkın ekmeğiyle oynayan ihtikârcı tüccarları derhal zincire vurdur; un saklayan ambarları kırıp sorumluları esnaf önünde teşhir et ve Bakır Meteliklerin Hileli Basımı fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'İhtisap ve Narh Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et ve Bakır Meteliklerin Hileli Basımı meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +1, Otorite +7 | Hazine -9","effects":{"justice":9,"people":1,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 951) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_952', 'ottoman', 'Dolmabahçe Sarayı İnşaatının Bütçeyi Aşması', 'Saray Başkâtipliği', 'Balyan kalfanın Dolmabahçe için hazırladığı altın varak ve billur avize faturasının yıllık bütçenin beşte birine ulaştığı arz edildi.', '[{"id":"char_mimar_balyan","name":"Mimar Garabet Balyan"},{"id":"char_lonca_zanaatkari","name":"Lonca Zanaatkarı"}]', '[{"label":"İsrafı derhal durdur! Yaldız ve kristal siparişlerini iptal et, sade ve vakur bir bina ile bitir.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Milyonlarca altın kurtarıldı; devlet hazinesi debdebe batağından çekildi."},{"label":"Saray cihanın en süslüsü olmalıdır; borç alıp tamamlayın.","preview":"Reaya +7, Otorite +9 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Dolmabahçe Sarayı İnşaatının Bütçeyi Aşması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Dolmabahçe Sarayı İnşaatının Bütçeyi Aşması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +9 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Dolmabahçe Sarayı İnşaatının Bütçeyi Aşması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 952) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_953', 'ottoman', 'Mithat Paşa\'nın Memleket Sandıklarının Genişletilmesi', 'Ziraat Sandıkları', 'Tuna vilayetinde köylüyü tefeciden kurtaran sandıkların tüm Anadolu ve Rumeli\'ye yayılması için ferman istendi.', '[{"id":"char_mithat_pasa","name":"Mithat Paşa"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Fermanı çıkar: Her sancakta Ziraat Sandığı açılsın; köylüye faizsiz tohum kredisi bağlansın.","preview":"Adalet +9, Reaya +7 | Hazine -1, Otorite -4","effects":{"justice":9,"people":7,"treasury":-1,"military":0,"authority":-4},"log":"Tefecilik çöktü; Türk köylüsü kendi milli bankasının sahibi oldu."},{"label":"Sandık işi devleti zarara sokar; köylü tefeciyle anlaşsın.","preview":"Reaya +8, Otorite +8 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Mithat Paşa\'nın Memleket Sandıklarının Genişletilmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Mithat Paşa\'nın Memleket Sandıklarının Genişletilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Mithat Paşa\'nın Memleket Sandıklarının Genişletilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 953) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_954', 'ottoman', 'Taşra Muhassıllarının Fazla Vergi Toplayıp Cebe İndirmesi', 'Maliye Teftişi', 'Aydın muhassılının ferman edilen verginin üstüne \'kırtasiye ve nal bahası\' adı altında haksız akçe topladığı belgelendi.', '[{"id":"char_divan_mufettisi","name":"Divan Müfettişi"},{"id":"char_vergi_muhassili","name":"Vergi Muhassılı"}]', '[{"label":"Muhassılı azlet, mal varlığına el koy ve haksız toplanan parayı köylüye tek tek iade ettir.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -3","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-3},"log":"Tahsildar zulmü kırıldı; köylü adil padişaha dualar yükseltti."},{"label":"Muhassıl hazineye payını veriyor; küçük fazlalıklara yerel dengeleri gözeterek arabulucu heyeti tayin et ve sulh sağlaun.","preview":"Reaya +8, Otorite +9 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ziraat yapan köylüye faizsiz çift avansı tahsis et; kuraklık ve kriz yaşayan köylerin tekâlif-i şâkka vergisini bu senelik affet ve Taşra Muhassıllarının Fazla Vergi Toplayıp Cebe İndirmesi nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Reayaya zulmeden mültezimleri derhal derdest ettir; çiftçinin hayvanını zorla alanları ibret-i âlem için kalebend et ve Taşra Muhassıllarının Fazla Vergi Toplayıp Cebe İndirmesi fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Ziraat ve Cibayet Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Taşra Muhassıllarının Fazla Vergi Toplayıp Cebe İndirmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":6,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 954) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_955', 'ottoman', 'Düyun-ı Umumiye Heyetinin Saraya Gelmesi', 'Hariciye Nezareti', 'İflas eden devletin borçlarını tahsil etmek için gelen yabancı bankerler, altı ana vergi gelirinin doğrudan kendilerine bağlanmasını dayatıyor.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_banker","name":"Yabancı Banker (Düyun-ı Umumiye)"}]', '[{"label":"Milli egemenliği teslim etme! Borçları vadelere yay, tasarruf yap ama yabancı heyeti kapıdan sokma.","preview":"Adalet +9, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":9,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Mali istiklal kurtarıldı; devlet kendi toprağında sömürge olmaktan döndü."},{"label":"Çaresiziz; altı verginin anahtarını yabancı komisyona teslim edin.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Düyun-ı Umumiye Heyetinin Saraya Gelmesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Düyun-ı Umumiye Heyetinin Saraya Gelmesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +8, Otorite +8 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Düyun-ı Umumiye Heyetinin Saraya Gelmesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 955) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_956', 'ottoman', 'Gümüş Kuruşların Ağırlığının Düşürülmesi Fikri', 'Darbhane-i Âmire', 'Kasadaki darlık yüzünden defterdar, piyasadaki kuruşların içine %30 bakır karıştırıp maaşları öyle ödemeyi teklif etti.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_darphane_emini","name":"Darphane Emini"}]', '[{"label":"Tağşişi kesinlikle men et: \'Paranın ayarını bozan, devletin temel taşını oynatmış olur!\'.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"Enflasyon canavarı engellendi; askerin ve esnafın rızkı korundu."},{"label":"Tağşişe onay verin; maaşları bu ay hafif akçeyle kapatalım.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Gümüş Kuruşların Ağırlığının Düşürülmesi Fikri nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Gümüş Kuruşların Ağırlığının Düşürülmesi Fikri fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gümüş Kuruşların Ağırlığının Düşürülmesi Fikri meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 956) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_957', 'ottoman', 'Tüccarların Yabancı Banknotla Alışveriş Dayatması', 'Kaza İhtisabı', 'Galata tüccarlarının Osmanlı kâimesini kabul etmeyip halktan zorla İngiliz sterlini ve Fransız frangı istediği bildirildi.', '[{"id":"char_muhtesip","name":"Muhtesip (Çarşı Zabiti)"},{"id":"char_tuccar","name":"Tüccar"}]', '[{"label":"Ferman çıkar: Mülkümüzde tek geçerli para milli paradır! Yabancı parayla fiyat koyan tüccarı cezalandır.","preview":"Adalet +7, Reaya +9 | Hazine -4, Otorite -1","effects":{"justice":7,"people":9,"treasury":-4,"military":0,"authority":-1},"log":"Milli sikke nizamı korundu; halk yabancı paranın spekülasyonundan kurtuldu."},{"label":"Serbest piyasadır; isteyen istediği parayla satsın.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Tüccarların Yabancı Banknotla Alışveriş Dayatması nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Tüccarların Yabancı Banknotla Alışveriş Dayatması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Tüccarların Yabancı Banknotla Alışveriş Dayatması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 957) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_958', 'ottoman', 'Orman ve Maden İhalelerinde Açık Artırma Şeffaflığı', 'Taşra Defterdarlığı', 'Büyük orman ve maden mukataalarının kapalı kapılar ardında akrabalara peşkeş çekilmesini önleyecek açık ihale kanunu sunuldu.', '[{"id":"char_defterdar","name":"Defterdar"},{"id":"char_maden_iscisi","name":"Maden / Ocak İşçisi"}]', '[{"label":"Kanunu onayla: İhaleler divan önünde davulla ilan edilip en yüksek verene açıkça verilsin.","preview":"Adalet +6, Reaya +9 | Hazine -3, Otorite -4","effects":{"justice":6,"people":9,"treasury":-3,"military":0,"authority":-4},"log":"İhale yolsuzlukları bitti; hazineye hak ettiği dev gelirler aktı."},{"label":"Gizli ihale daha usuldendir; akrabaları kayırmaya devam edin.","preview":"Reaya +6, Otorite +9 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Orman ve Maden İhalelerinde Açık Artırma Şeffaflığı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +4 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":6,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Orman ve Maden İhalelerinde Açık Artırma Şeffaflığı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Orman ve Maden İhalelerinde Açık Artırma Şeffaflığı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 958) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_959', 'ottoman', 'Yıllık Devlet Bütçesinin Mecliste İlanı (Bütçe Kanunu)', 'Maliye Nezareti', 'Gelir ve giderlerin kalem kalem Meclis\'te okunup onaylanması, bütçe dışı saray harcamalarının suç sayılması teklif edildi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Bütçe Kanunu\'nu yürürlüğe koy: \'Devletin tek bir akçesi dahi hesapsız ve kanunsuz harcanamaz!\'.","preview":"Adalet +7, Reaya +6 | Hazine -1, Otorite -3","effects":{"justice":7,"people":6,"treasury":-1,"military":0,"authority":-3},"log":"Mali şeffaflık sağlandı; devlet modern bir hesap verebilirlik kazandı."},{"label":"Devlet bütçesi padişahın sırrıdır; mecliste hesap verilmez.","preview":"Reaya +6, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":6,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kaçak su kullananların mülklerine özel su vergisi koy; toplanan akçeleri suyolcu loncasına tamir bütçesi olarak devret ve Yıllık Devlet Bütçesinin Mecliste İlanı (Bütçe Kanunu) nizamına bağla.","preview":"Hazine +7, Otorite +4 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Şehrin su şebekesine kaçak hat bağlayanların konaklarını mühürle; sorumluları payitahttan derhal taşra kalesine sür ve Yıllık Devlet Bütçesinin Mecliste İlanı (Bütçe Kanunu) fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Suyolları ve Mirî Şebeke Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Yıllık Devlet Bütçesinin Mecliste İlanı (Bütçe Kanunu) meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 959) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_960', 'ottoman', 'Mali İstiklal ve Dâire-i Adliyye Dengesi', 'Dîvân-ı Hümâyûn', 'Maliye reformunun zirvesinde Kınalızâde\'nin ilkesi hatırlatıldı: \'Mal olmadan ordu olmaz, lakin malı toplayacağım diye reayayı ezen mülkünü yıkar!\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"DENGE FERMANINI İMZALA: \'Reayayı gözet ki hazine dolsun, hazineyi adaletle harca ki ordu korusun!\'.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Maliye nizamı adalet çemberiyle kenetlendi; devlet iflastan kurtulup refaha erdi."},{"label":"Zenginleşmek için her yol mübahtır; halkı soyun.","preview":"Reaya +9, Otorite +8 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Ordu masraflarını karşılamak üzere mukataa gelirlerini doğrudan ocak hazinesine bağla; askerin akçesiz kalmasını önle ve Mali İstiklal ve Dâire-i Adliyye Dengesi nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Askeri itaatsizliğe yeltenen ocak ağalarını divan huzuruna celbet; ordu nizamını bozanların rütbelerini söküp sürgüne yolla ve Mali İstiklal ve Dâire-i Adliyye Dengesi fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Asakir ve Mevacib Kanunnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Mali İstiklal ve Dâire-i Adliyye Dengesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -7","effects":{"justice":9,"people":2,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 960) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_961', 'ottoman', 'Levent Çiftliği Kışlasında Modern Talim', 'Nizâm-ı Cedîd Kışlası', 'III. Selim\'in kurduğu Nizâm-ı Cedîd ordusunun Fransız usulü seri tüfek doldurma ve süngü hücumu talimi yeniçerileri öfkelendirdi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Geri adım atma! Nizâm-ı Cedîd alaylarını çoğalt, Anadolu\'dan disiplinli yiğitleri orduya kat.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Akka önlerinde Napolyon\'u dize getiren muazzam modern ordu doğdu."},{"label":"Yeniçeriler kazan kaldırır; modern talimi durdurup kışlayı kapatın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Levent Çiftliği Kışlasında Modern Talim hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Levent Çiftliği Kışlasında Modern Talim hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +6, Otorite +7 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Levent Çiftliği Kışlasında Modern Talim gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 961) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_962', 'ottoman', 'Kabakçı Mustafa İsyanı ve Reform Tehdidi', 'Bab-ı Âli', 'Boğaz yamakları ayaklandı; \'Nizâm-ı Cedîd kâfirliktir, yeniçeri ocağı esastır\' diyerek sadrazamın kellesini istiyorlar.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"}]', '[{"label":"Saray muhafızlarını ve topçuları meydana çıkar; asileri tavizsiz dağıt ve reformları koru.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"İsyan bastırıldı; gerici zorbalık ezilerek devletin önü açıldı."},{"label":"Kan dökülmesin; Nizâm-ı Cedîd\'i lağvettik fermanı çıkarın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Harp sanayiinde kaliteyi korumak için prim usulü iktisadi teşvik ver; hileli alaşım kullanan müteahhitlerin teminat akçelerini hazineye irad kaydet ve Kabakçı Mustafa İsyanı ve Reform Tehdidi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Baruthane ve tophane imalatında hile yapan ustabaşıları derdest et; mühimmatı sabote edenleri ibret-i âlem için cezalandır ve Kabakçı Mustafa İsyanı ve Reform Tehdidi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Tophane ve Harbiye İmalat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Kabakçı Mustafa İsyanı ve Reform Tehdidi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +3, Otorite +7 | Hazine -7","effects":{"justice":9,"people":3,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 962) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_963', 'ottoman', 'Yeniçeri Ocağının Kanlı Tasfiyesi', 'Vaka-i Hayriye', 'II. Mahmud devrinde yine isyan eden yeniçerilere karşı Sancak-ı Şerif açıldı; halk ve topçular sarayın etrafında birleşti.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_topcubasi","name":"Topçubaşı"}]', '[{"label":"Toplara ateş emri ver! Üç asırlık kangren olan bu zorba ocağı tarihten ebediyen sil.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Yeniçeri zorbalığı bitti; mülk prangalarından kurtulup hürriyete kavuştu."},{"label":"Yine taviz verin; kazan kaldıran ağalarla anlaşın.","preview":"Reaya +8, Otorite +7 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Yeniçeri Ocağının Kanlı Tasfiyesi nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Yeniçeri Ocağının Kanlı Tasfiyesi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Yeniçeri Ocağının Kanlı Tasfiyesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":8,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 963) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_964', 'ottoman', 'Asakir-i Mansure-i Muhammediye\'nin İhdası', 'Asakir-i Mansure Kışlaları', 'Yeniçeriliğin yerine kurulan modern ordunun disiplinli, namazında ve vatan aşkıyla yetiştirilmesi emredildi.', '[{"id":"char_yeniceri","name":"Yeniçeri Ocağı Askeri"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Yeni orduyu kur: Üniformasını, modern tüfeğini ve mektepli zabitlerini nizamla teşkil et.","preview":"Adalet +9, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":9,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Milli ve modern Türk ordusu doğdu; serhad kaleleri güvene kavuştu."},{"label":"Bütçe yetersizdir; köylerden düzensiz milislerle idare edin.","preview":"Reaya +8, Otorite +8 | Adalet -7, Hazine -3","effects":{"justice":-7,"people":8,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Asakir-i Mansure-i Muhammediye\'nin İhdası meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Asakir-i Mansure-i Muhammediye\'nin İhdası meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Asakir-i Mansure-i Muhammediye\'nin İhdası gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +8 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 964) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_965', 'ottoman', 'Harbiye Mektebinde Kurmay Subay Yetiştirilmesi', 'Mekteb-i Harbiye', 'Pangaltı\'da açılan Harbiye\'de hendese, haritacılık ve yabancı dil bilen kurmay subaylar yetiştirilmesi teklif edildi.', '[{"id":"char_harbiye_subayi","name":"Harbiye Mektebi Subayı"}]', '[{"label":"Mektebi aç, Prusyalı kurmay hocalar getirt ve ordunun başına mektepli zabitleri geçir.","preview":"Adalet +6, Reaya +7 | Hazine -1, Otorite -1","effects":{"justice":6,"people":7,"treasury":-1,"military":0,"authority":-1},"log":"Harbiye bir dâhiler ocağı oldu; Çanakkale\'yi savunan o muazzam nesil yetişti."},{"label":"Alaylı çavuşlar kafidir; mektepten kumandan çıkmaz.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Harbiye Mektebinde Kurmay Subay Yetiştirilmesi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Harbiye Mektebinde Kurmay Subay Yetiştirilmesi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Harbiye Mektebinde Kurmay Subay Yetiştirilmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -6","effects":{"justice":6,"people":1,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 965) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_966', 'ottoman', 'Gülhane Tıbbiyesi ve Kadavra Anatomi Dersi', 'Mekteb-i Tıbbiye-i Şahane', 'Askeri cerrahların yetişmesi için kadavra üzerinde anatomi çalışmasına karşı çıkan mutaassıplar mektebi basmak istedi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_tabip","name":"Tabip / Cerrah"}]', '[{"label":"Mektebi muhafaza et: \'Tabip insan bedenini bilmeden ameliyat edemez!\' İlim hürriyetini koru.","preview":"Adalet +7, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":7,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Modern cerrahi kuruldu; cephelerde binlerce Mehmetçiğin canı kurtarıldı."},{"label":"Mutaassıpların dediğini yapın; kadavra dersini yasaklayın.","preview":"Reaya +8, Otorite +6 | Adalet -8, Hazine -3","effects":{"justice":-8,"people":8,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Karantina masraflarını karşılamak üzere liman fonu oluştur; tecrit altındaki gemilere ücretsiz tababet ve iaşe temin et ve Gülhane Tıbbiyesi ve Kadavra Anatomi Dersi nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı müfrezesini limana sevk et; karantina rüşveti teklif eden gemi kaptanlarını ve işbirlikçilerini derhal prangaya vur ve Gülhane Tıbbiyesi ve Kadavra Anatomi Dersi fermanını uygulat.","preview":"Ordu +7, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Karantina-i Bahriye ve Sıhhat Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp liman ve sınırlarda tabip denetimini zorunlu kılıp karantina ihlallerini ağır suç say ve Gülhane Tıbbiyesi ve Kadavra Anatomi Dersi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +8 | Hazine -9","effects":{"justice":7,"people":2,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 966) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_967', 'ottoman', 'Mahmudiye Kalyonunun Denize İndirilmesi', 'Tersane-i Âmire', '128 topu ve üç ambarıyla dünyanın en büyük ahşap savaş gemisi Mahmudiye Haliç\'te inşa edildi; denize indirilmesi gurur yarattı.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"}]', '[{"label":"Mahmudiye\'yi donanmanın sancak gemisi yap; Boğaz\'da tebaaya geçit yaptırıp milli gururu şahlandır.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -3","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-3},"log":"Dünyanın en heybetli kalyonu denizlere indi; yabancı filolar selam durdu."},{"label":"Gemiyi yabancı bir devlete satın; hazineye altın gelsin.","preview":"Reaya +8, Otorite +7 | Adalet -8, Hazine -1","effects":{"justice":-8,"people":8,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mahmudiye Kalyonunun Denize İndirilmesi meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Mahmudiye Kalyonunun Denize İndirilmesi meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Mahmudiye Kalyonunun Denize İndirilmesi gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +8, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":8,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 967) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_968', 'ottoman', 'Redif (İhtiyat Askeri) Teşkilatının Kurulması', 'Taşra Askeri İdaresi', 'Barış zamanında tarlasını eken köylü gençlerin haftada bir gün talim yaparak savaşta orduya katılacağı Redif sistemi teklif edildi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Redif sistemini kanunlaştır: Hem ziraat devam etsin hem de bir günde yüz bin asker silaha sarılsın.","preview":"Adalet +7, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":7,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Devasa bir yedek ordu kuruldu; tarım ve üretim aksamadan ordu güçlendi."},{"label":"Köylü askerlik yapamaz; sürekli maaşlı asker tutun.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -1","effects":{"justice":-7,"people":7,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Köylünün öküz ve tohum borçlarını hazine kefaletiyle ertele; zorba tahsildarların topladığı harçları kuruşu kuruşuna reayaya iade ettir ve Redif (İhtiyat Askeri) Teşkilatının Kurulması nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Taşra muhassılını derhal azlet; kanunsuz harç toplayan tahsildarların mallarına el koyup divan huzurunda teftişe çek ve Redif (İhtiyat Askeri) Teşkilatının Kurulması fermanını uygulat.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Ziraat ve Cibayet Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et ve Redif (İhtiyat Askeri) Teşkilatının Kurulması meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -7","effects":{"justice":7,"people":2,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 968) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_969', 'ottoman', 'Krupp Çelik Sahra Toplarının Satın Alınması', 'Tophane-i Âmire', 'Prusya\'dan gelen namludan değil arkadan doldurulan modern çelik Krupp toplarının orduya kazandırılması teklif edildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Eski bronz topları devreden çıkar; orduyu modern çelik sahra toplarıyla donat.","preview":"Adalet +6, Reaya +9 | Hazine -4, Otorite -4","effects":{"justice":6,"people":9,"treasury":-4,"military":0,"authority":-4},"log":"Topçu birliklerimiz düşmanı fersah fersah uzaktan seri ateşle ezdi."},{"label":"Bronz toplarımız bize yeter; çelik topa servet dökmeyin.","preview":"Reaya +6, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":6,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Barut ve gülle imalatçılarına faizsiz devlet ikrazı sağla; ordu mühimmatını doğrudan darphane denetimli saf madenle üret ve Krupp Çelik Sahra Toplarının Satın Alınması nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kusurlu top ve bozuk barut üreten ocak görevlilerini derhal prangaya vurdur; devlete ihanet derecesinde kusur işleyenleri zindana at ve Krupp Çelik Sahra Toplarının Satın Alınması fermanını uygulat.","preview":"Ordu +8, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":8,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Tophane ve Harbiye İmalat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et ve Krupp Çelik Sahra Toplarının Satın Alınması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":6,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 969) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_970', 'ottoman', 'Yerli Tüfek ve Süngü Fabrikasının Açılışı', 'Zeytinburnu Fabrika-i Hümâyûnu', 'İngiliz ve Fransız tüfeğine muhtaç kalmamak için Zeytinburnu\'nda buhar gücüyle çalışan yerli tüfek fabrikası kurulması istendi.', '[{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Fabrikayı kurdur, madenleri bağla ve her yıl 50 bin yerli tüfek ürettir.","preview":"Adalet +8, Reaya +9 | Hazine -3, Otorite -3","effects":{"justice":8,"people":9,"treasury":-3,"military":0,"authority":-3},"log":"Silah sanayiinde milli istiklal kazanıldı; ordumuz yerli tüfekle donandı."},{"label":"Dışarıdan hazır almak daha kolaydır; fabrika masrafına girmeyin.","preview":"Reaya +6, Otorite +9 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":6,"treasury":-3,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Yerli Tüfek ve Süngü Fabrikasının Açılışı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +8, Otorite +4 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Yerli Tüfek ve Süngü Fabrikasının Açılışı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Yerli Tüfek ve Süngü Fabrikasının Açılışı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +8, Reaya +3, Otorite +6 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 970) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_971', 'ottoman', 'Sinop Baskını ve Donanmanın Yanması', 'Kırım Harbi', 'Rus filosunun Sinop limanında yatan ahşap kalyonlarımızı yangın bombalarıyla yakıp binlerce leventimizi şehit ettiği haberi geldi.', '[{"id":"char_iskele_hamali","name":"İskele Hamalı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Milli seferberlik ilan et: İngiltere ve Fransa ile ittifak yapıp Kırım\'a ordu çıkar, ahşap devrini bitir.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Sivastopol fethedildi; Rus donanması Karadeniz\'de tamamen batırıldı."},{"label":"Rusya çok güçlüdür; Kırım ve Karadeniz\'den çekilip teslim olun.","preview":"Reaya +7, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Sinop Baskını ve Donanmanın Yanması nizamına bağla.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Sinop Baskını ve Donanmanın Yanması fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Sinop Baskını ve Donanmanın Yanması meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +4, Otorite +6 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 971) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_972', 'ottoman', 'Harbiye Talebelerine Felsefe ve Mantık Eğitimi', 'Mekteb-i Harbiye', 'Kumandan adaylarının sadece silah atmayı değil, strateji, felsefe ve harp ahlakı bilmesi için ders konması teklif edildi.', '[{"id":"char_medrese_talebesi","name":"Medrese Talebesi (Suhte)"},{"id":"char_harbiye_subayi","name":"Harbiye Mektebi Subayı"}]', '[{"label":"Müfredatı genişlet: Subayları derin bir tefekkür, vatan sevgisi ve adalet ahlakıyla donat.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -4","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-4},"log":"Çanakkale ve İstiklal Harbini zaferle taçlandıracak dahi kurmaylar yetişti."},{"label":"Asker felsefe bilmez; sadece emir dinlesin kafidir.","preview":"Reaya +7, Otorite +9 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Harbiye Talebelerine Felsefe ve Mantık Eğitimi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Harbiye Talebelerine Felsefe ve Mantık Eğitimi fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Harbiye Talebelerine Felsefe ve Mantık Eğitimi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +9 | Hazine -8","effects":{"justice":6,"people":2,"treasury":-8,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 972) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_973', 'ottoman', 'Savaşta Kolunu Kaybeden Neferin Emekliliği', 'Askeri Tekâüd Sandığı', 'Kırım\'da gülleyle kolu kopan bir neferin \'Maaş defterinde kaydın yok\' diye kapıdan çevrildiği feryatla duyuruldu.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Zimmetçi memuru derhal azlet; gaziyi huzura al, altın madalya tak ve ömür boyu şerefli gazi maaşı bağla.","preview":"Adalet +9, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":9,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Gazinin onuru kurtarıldı; askerin devlete can feda bağlılığı perçinlendi."},{"label":"Nizam böyledir; kaydı olmayan gazilik maaşı alamaz.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -4","effects":{"justice":-6,"people":8,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Savaşta Kolunu Kaybeden Neferin Emekliliği meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Savaşta Kolunu Kaybeden Neferin Emekliliği meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Savaşta Kolunu Kaybeden Neferin Emekliliği gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +9, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":9,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 973) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_974', 'ottoman', 'Askeri Kıyafetlerde Fes ve Pantolon Nizamı', 'Hassa Kışlaları', 'Sarığın ve şalvarın siperde hareketi engellemesi yüzünden getirilen fes ve pantolona \'Gâvur kıyafetidir\' diye itiraz edildi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Taviz verme: \'Kılık kıyafetle iman ölçülmez; muharebede çeviklik esastır!\' Nizamı tavizsiz uygula.","preview":"Adalet +8, Reaya +8 | Hazine -3, Otorite -2","effects":{"justice":8,"people":8,"treasury":-3,"military":0,"authority":-2},"log":"Asker modern ve çevik bir nizama kavuştu; taassup hezimete uğradı."},{"label":"Gelenektir; askeri eski şalvar ve sarıkla bırakın.","preview":"Reaya +8, Otorite +9 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":8,"treasury":-1,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Askeri Kıyafetlerde Fes ve Pantolon Nizamı nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Askeri Kıyafetlerde Fes ve Pantolon Nizamı fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Askeri Kıyafetlerde Fes ve Pantolon Nizamı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -8","effects":{"justice":8,"people":2,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 974) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_975', 'ottoman', 'Buharlı Çekiçle Zırh Levhası Bükülmesi', 'Zeytinburnu Demirhanesi', 'Kalyonların bordasını kaplamak için İngiltere\'den getirilen buharlı ağır çekicin başarıyla çalıştığı bildirildi.', '[{"id":"char_demirci_ustasi","name":"Demirci / Nalband Ustası"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Yerli zırh üretimini başlat; kalyonlarımızı kendi dövdüğümüz çelik zırhlarla kaplat.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -4","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-4},"log":"Deniz sanayiinde çağ atlandı; zırhlı donanmamız Akdeniz\'e hakim oldu."},{"label":"Çok kömür yakıyor; çekici durdurup ithal zırh alın.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Buharlı Çekiçle Zırh Levhası Bükülmesi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Buharlı Çekiçle Zırh Levhası Bükülmesi fermanını uygulat.","preview":"Ordu +7, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Buharlı Çekiçle Zırh Levhası Bükülmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 975) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_976', 'ottoman', 'Şeyh Şamil\'e Silah ve Topçu Yardımı', 'Kafkas Kolordusu', 'Dağıstan dağlarında Rus işgaline karşı destan yazan Şamil\'in Osmanlı halifesinden acil dağ topu ve barut istediği bildirildi.', '[{"id":"char_topcubasi","name":"Topçubaşı"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Trabzon üzerinden gizli konvoylarla yüz dağ topu ve tonlarca barut yetiştir; Kafkas gazalarını destekle.","preview":"Adalet +6, Reaya +7 | Hazine -2, Otorite -1","effects":{"justice":6,"people":7,"treasury":-2,"military":0,"authority":-1},"log":"Kafkasya seddi tutuldu; Rus orduları yıllarca Anadolu sınırına yaklaşamadı."},{"label":"Rusya ile aramızı bozmayın; Şamil\'e yardım yollamayın.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hazine tahsisatıyla tophane ve baruthane ocaklarına saf maden avansı aktar; Şeyh Şamil\'e Silah ve Topçu Yardımı hadisesinde kusurlu döküm yapanlara ağır cerime cezası kes.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Tophane kethüdasını derhal vazifeden al; Şeyh Şamil\'e Silah ve Topçu Yardımı hadisesinde kusurlu mühimmat döken ve hile yapan ustaları Divan-ı Hümâyûn huzurunda sorguya çek.","preview":"Ordu +8, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Tophane ve Harbiye İmalat Nizamnâmesi\' neşret; Şeyh Şamil\'e Silah ve Topçu Yardımı gibi hadiselerin tekerrürünü önleyecek şekilde dökümde kullanılacak maden alaşımlarını sıkı mühür şartına bağlayıp kusurlu imalatı men et.","preview":"Adalet +6, Reaya +3, Otorite +8 | Hazine -6","effects":{"justice":6,"people":3,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 976) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_977', 'ottoman', 'Harbiye Mektebinde İlk Telgraf ve Muhabere Bölüğü', 'Harbiye Nezareti', 'Savaş meydanında karargâh ile ön hatlar arasına sahra telgraf telleri çekilerek emirlerin saniyede iletilmesi önerildi.', '[{"id":"char_kadi","name":"Kadı"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"Sahra muhabere bölüğünü kurdur; her alaya seyyar telgraf arabaları tahsis et.","preview":"Adalet +7, Reaya +7 | Hazine -4, Otorite -3","effects":{"justice":7,"people":7,"treasury":-4,"military":0,"authority":-3},"log":"Harpte sevk ve idare şimşek gibi hızlandı; pusular anında haber alındı."},{"label":"Atlı emir subayları kafidir; tellere masraf etmeyin.","preview":"Reaya +8, Otorite +6 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":8,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Harbiye Mektebinde İlk Telgraf ve Muhabere Bölüğü nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Harbiye Mektebinde İlk Telgraf ve Muhabere Bölüğü fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Harbiye Mektebinde İlk Telgraf ve Muhabere Bölüğü meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -6","effects":{"justice":7,"people":1,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 977) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_978', 'ottoman', 'Denizaltı (Tahtelbahir) Tecrübesi', 'Tersane-i Âmire', 'Mimar İbrahim Efendi\'nin su altında kürekle giden timsah şeklinde hava sarnıçlı bir denizaltı yaptığı ve tecrübe istediği görüldü.', '[{"id":"char_tersane_emini","name":"Tersane-i Âmire Emini"},{"id":"char_lonca_seyhi","name":"Lonca Şeyhi"}]', '[{"label":"Tarihin ilk denizaltı denemesine bütçe ver; Sarayburnu önünde tecrübe ettirip donanmaya kazandır.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -2","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-2},"log":"Su altından çıkan timsah gemi gülle atıp daldı; dünya hayretle izledi."},{"label":"İnsan suyun altında yaşayamaz; şeytan icadı deyip gemiyi parçalatın.","preview":"Reaya +8, Otorite +7 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":8,"treasury":-3,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Suyollarına verilen zararı kusurlulardan kuruşu kuruşuna tazmin ettir; şehir çeşmelerinin bakımını hazine güvencesine al ve Denizaltı (Tahtelbahir) Tecrübesi nizamına bağla.","preview":"Hazine +8, Otorite +4 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":8,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Bostancıbaşını görevlendir; kamu suyunu özel havuzuna akıtan nüfuzlu paşaları azarla ve kaçak su şebekesini yerle bir et ve Denizaltı (Tahtelbahir) Tecrübesi fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Suyolları ve Mirî Şebeke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp şehir su kemerlerini haftalık mühürlü teftişe bağlayıp kaçak künk bağlamayı kanunen yasakla ve Denizaltı (Tahtelbahir) Tecrübesi meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +7 | Hazine -6","effects":{"justice":8,"people":3,"treasury":-6,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 978) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_979', 'ottoman', 'Asker Karavanasında Kurtlu Bakla ve Kokmuş Et', 'Kışla İaşe Nazırlığı', 'Müteahhidin rüşvetle kışlaya kurtlu bakla ve bayat et soktuğu, yüzlerce neferin zehirlenip yataklara düştüğü belgelendi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"},{"id":"char_yabanci_elci","name":"Yabancı Elçi (Sefir)"}]', '[{"label":"Müteahhidi ve rüşvetçi levazım binbaşısını askerin önünde divanda as; temiz erzak ambarlarını açtır.","preview":"Adalet +7, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":7,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Mehmetçiğin aşına el uzatanın hesabı kesildi; kışlaya tam sıhhat geldi."},{"label":"Binbaşı hatırlı ailedendir; olayı kaza süsüyle örtbas edin.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Mevacib defterini sıkı mali denetime al; Asker Karavanasında Kurtlu Bakla ve Kokmuş Et meselesinde sahte esameleri ayıklayıp askerin ulufesini hazine ihtiyat akçesinden tam ayar gümüşle öde.","preview":"Hazine +7, Otorite +1 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Ocak disiplinini bozan ve fitne çıkaran elebaşıları fermanla derhal yakalat; Asker Karavanasında Kurtlu Bakla ve Kokmuş Et hadisesine karışanları kapıkulu defterinden silip serhad zindanına sür.","preview":"Ordu +8, Otorite +6 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Asakir ve Mevacib Kanunnâmesi\' neşret; Asker Karavanasında Kurtlu Bakla ve Kokmuş Et gibi hadiselerin tekerrürünü önleyecek şekilde ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir.","preview":"Adalet +7, Reaya +4, Otorite +7 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 979) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_980', 'ottoman', 'Nizâm-ı Askeri ve Vatan Müdafaası Kanunnâmesi', 'Dîvân-ı Hümâyûn', 'Ordunun siyasetten tamamen arındırılmasını, askerin tek gayesinin vatan müdafaası ve milletin emniyeti olduğunu emreden kanunname mühürlendi.', '[{"id":"char_ordu_neferi","name":"Ordu Neferi"}]', '[{"label":"Kanunu mühürle: \'Asker siyasete girerse vatan batar; ordu milletin sarsılmaz zırhıdır!\'.","preview":"Adalet +9, Reaya +9 | Hazine -3, Otorite -1","effects":{"justice":9,"people":9,"treasury":-3,"military":0,"authority":-1},"log":"Ordu çelik bir disiplin kazandı; vatan savunması ebediyen teminat altına alındı."},{"label":"Subaylar siyasete karışsın; sarayda söz sahibi olsunlar.","preview":"Reaya +9, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":9,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Sefer levazımatı için saray tasarruf akçelerini devreye sok; askere zamanında ulufe verip piyasa borçlarını peşin akçeyle kapat ve Nizâm-ı Askeri ve Vatan Müdafaası Kanunnâmesi nizamına bağla.","preview":"Hazine +9, Otorite +4 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":4},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Kazan kaldıran zorbalara asla taviz verme; bostancıbaşını görevlendirip isyan tellallarını derhal derdest ettir ve Nizâm-ı Askeri ve Vatan Müdafaası Kanunnâmesi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Asakir ve Mevacib Kanunnâmesi\' yürürlüğe koy; yetki aşımını durdurup ocak yoklamalarını bizzat vezir huzurunda yaptırıp sahte esame ve disiplinsizliği kanunen bitir ve Nizâm-ı Askeri ve Vatan Müdafaası Kanunnâmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +9, Reaya +2, Otorite +6 | Hazine -6","effects":{"justice":9,"people":2,"treasury":-6,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 980) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_981', 'ottoman', 'Vatandaşın Devlete Karşı Dava Açma Hakkı', 'Şura-yı Devlet (Danıştay)', 'Mithat Paşa\'nın kurduğu Danıştay nizamnamesinde, mülkü haksız kamulaştırılan vatandaşın doğrudan hükümete dava açabilmesi teklif edildi.', '[{"id":"char_mithat_pasa","name":"Mithat Paşa"},{"id":"char_surayidevlet_heyeti","name":"Şura-yı Devlet Heyeti"}]', '[{"label":"Nizamnameyi onayla: \'Devlet dahi olsa haksızlık yapan mahkemede boyun büker!\'.","preview":"Adalet +8, Reaya +9 | Hazine -4, Otorite -2","effects":{"justice":8,"people":9,"treasury":-4,"military":0,"authority":-2},"log":"Hukuk devleti zirveye çıktı; devlet vatandaşına hesap veren adil kutup oldu."},{"label":"Devlete karşı dava açılamaz; devletin her yaptığı doğrudur.","preview":"Reaya +6, Otorite +7 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":6,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Dava konusu terekeden devlete borçlu kısmı tahsil et; kalan helal mal varlığını yetim ve mirasçıların geçimi için vakıf emlakine dönüştür ve Vatandaşın Devlete Karşı Dava Açma Hakkı nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -3, Reaya -6","effects":{"justice":-3,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Mezalim fermanıyla kadının konağını bastır; rüşvet ve haksız iltimasa bulaşan tüm naip ve memurları zindana kapat ve Vatandaşın Devlete Karşı Dava Açma Hakkı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kaza ve Tereke Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp mahkeme harçlarını ve miras taksimini şeffaf defter usulüne bağlayıp rüşvet alan kadıları derhal azlet ve Vatandaşın Devlete Karşı Dava Açma Hakkı meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +6 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 981) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_982', 'ottoman', 'Sadrazamın Bakanlar Kurulu Kararlarını Tek Başına Bozması', 'Meclis-i Vükelâ', 'Sadrazamın, tüm vekillerin ittifakla aldığı reform kararını \'Ben vekil-i mutlakım\' diyerek tek başına çöpe attığı görüldü.', '[{"id":"char_sadrazam","name":"Sadrazam"},{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Sadrazamı uyar: \'Meşveret esastır, tek adam kararıyla mülk yönetilemez!\' Heyetin ortak kararına uy.","preview":"Adalet +9, Reaya +8 | Hazine -2, Otorite -2","effects":{"justice":9,"people":8,"treasury":-2,"military":0,"authority":-2},"log":"Kolektif akıl üstün geldi; bakanlar kurulu ortak sorumlulukla devleti yüceltti."},{"label":"Sadrazam haklıdır; heyet sadece danışma kuruludur.","preview":"Reaya +7, Otorite +8 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":7,"treasury":-2,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Sadrazamın Bakanlar Kurulu Kararlarını Tek Başına Bozması hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -7","effects":{"justice":-3,"people":-7,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Sadrazamın Bakanlar Kurulu Kararlarını Tek Başına Bozması hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Sadrazamın Bakanlar Kurulu Kararlarını Tek Başına Bozması gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +9, Reaya +3, Otorite +9 | Hazine -6","effects":{"justice":9,"people":3,"treasury":-6,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 982) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_983', 'ottoman', 'I. Meşrutiyet\'in İlanı ve Anayasa Teminatı', 'Kanûn-ı Esasî', '1876\'da ilan edilen Anayasa ile tebaanın kanun önünde eşitliği, işkencenin yasaklanması ve meclisin açılması mühürlendi.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"}]', '[{"label":"Anayasayı baş tacı yap: \'Kanunun üstünde hiçbir şahıs ve irade yoktur!\' Hürriyeti ilan et.","preview":"Adalet +6, Reaya +8 | Hazine -1, Otorite -1","effects":{"justice":6,"people":8,"treasury":-1,"military":0,"authority":-1},"log":"Tarihin ilk anayasası yürürlüğe girdi; imparatorluk meşruti nizamla yenilendi."},{"label":"Anayasa padişahın elini kolunu bağlar; fermanı imzalamayın.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve I. Meşrutiyet\'in İlanı ve Anayasa Teminatı nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -9","effects":{"justice":-2,"people":-9,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve I. Meşrutiyet\'in İlanı ve Anayasa Teminatı fermanını uygulat.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve I. Meşrutiyet\'in İlanı ve Anayasa Teminatı meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +4, Otorite +9 | Hazine -7","effects":{"justice":6,"people":4,"treasury":-7,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 983) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_984', 'ottoman', 'Müslüman ve Gayrimüslim Mebusların Ortak Bütçe Denetimi', 'Meclis-i Mebusan', 'Açılan Meclis\'te Arap, Rum, Türk ve Ermeni mebusların hükümetin bütçe harcamalarını kuruşu kuruşuna sorguladığı görüldü.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_ermeni_cemaat_temsilcisi","name":"Ermeni Cemaat Temsilcisi"}]', '[{"label":"Meclisin denetim hakkına saygı duy: \'Milletin vergisi milletin meclisinde hesap verir!\'.","preview":"Adalet +9, Reaya +7 | Hazine -3, Otorite -1","effects":{"justice":9,"people":7,"treasury":-3,"military":0,"authority":-1},"log":"Maliye açık saçık hesap verdi; yolsuzluklar meclis kürsüsünde boğuldu."},{"label":"Mebuslar haddini aşıyor; meclisi derhal tatil edin.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":7,"treasury":-4,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Müslüman ve Gayrimüslim Mebusların Ortak Bütçe Denetimi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -7","effects":{"justice":-2,"people":-7,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Müslüman ve Gayrimüslim Mebusların Ortak Bütçe Denetimi fermanını uygulat.","preview":"Ordu +6, Otorite +8 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Müslüman ve Gayrimüslim Mebusların Ortak Bütçe Denetimi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 984) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_985', 'ottoman', 'Taşra Valilerinin Meclis Kararıyla Denetlenmesi', 'Vilayet Nizamnamesi', 'Valilerin keyfi kararlarını sınırlayan, halkın seçtiği vilayet meclislerinin onayı olmadan vergi ve imar yapılamayacağı nizamname sunuldu.', '[{"id":"char_meclis_mebusan_temsilcisi","name":"Meclis-i Mebusan Temsilcisi"},{"id":"char_tasra_valisi","name":"Taşra Valisi"}]', '[{"label":"Nizamnameyi onayla; taşraya meşveret ve yerel denetim ahlakını yerleştir.","preview":"Adalet +8, Reaya +8 | Hazine -4, Otorite -2","effects":{"justice":8,"people":8,"treasury":-4,"military":0,"authority":-2},"log":"Taşra derebeylikten kurtuldu; halk kendi şehrinin imarına sahip çıktı."},{"label":"Vali padişahın gölgesidir; meclise hesap vermez.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -4","effects":{"justice":-7,"people":8,"treasury":-4,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Taşra Valilerinin Meclis Kararıyla Denetlenmesi hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +8, Otorite +3 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Taşra Valilerinin Meclis Kararıyla Denetlenmesi hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Taşra Valilerinin Meclis Kararıyla Denetlenmesi gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +8, Reaya +4, Otorite +7 | Hazine -7","effects":{"justice":8,"people":4,"treasury":-7,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 985) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_986', 'ottoman', 'Gazetecilerin Yolsuzluk Yapan Bakanı İfşa Etmesi', 'Matbuat Dairesi', 'Tercüman-ı Ahval gazetesinin bir vezirin rüşvet aldığını belgelerle basması üzerine sansür kurulu gazeteyi kapatmak istedi.', '[{"id":"char_vezir","name":"Kubbealtı Veziri"},{"id":"char_kale_dizdari","name":"Kale Dizdarı"}]', '[{"label":"Gazeteyi kapatma! \'Doğruyu yazan kalem kılıçtan keskindir!\' Veziri teftişe çek.","preview":"Adalet +7, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":7,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"Hür ve dürüst matbuat adaletin bekçisi oldu; rüşvetçi vezir azledildi."},{"label":"Gazeteyi derhal kapatın; devlet adamının ayıbı yazılmaz.","preview":"Reaya +8, Otorite +8 | Adalet -8, Hazine -4","effects":{"justice":-8,"people":8,"treasury":-4,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Gazetecilerin Yolsuzluk Yapan Bakanı İfşa Etmesi nizamına bağla.","preview":"Hazine +9, Otorite +3 | Adalet -2, Reaya -8","effects":{"justice":-2,"people":-8,"treasury":9,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Gazetecilerin Yolsuzluk Yapan Bakanı İfşa Etmesi fermanını uygulat.","preview":"Ordu +9, Otorite +6 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":0,"military":9,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Gazetecilerin Yolsuzluk Yapan Bakanı İfşa Etmesi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +2, Otorite +7 | Hazine -8","effects":{"justice":7,"people":2,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 986) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_987', 'ottoman', 'Cevdet Paşa\'nın Mecelle\'yi Tamamlaması', 'Mecelle Heyeti', '1851 maddelik muazzam İslam Borçlar ve Ticaret Kanunu Mecelle tamamlandı; şeriat ile modern hukukun zirve sentezi yapıldı.', '[{"id":"char_ahmet_cevdet_pasa","name":"Ahmet Cevdet Paşa"},{"id":"char_mecelle_heyeti","name":"Mecelle Heyeti"}]', '[{"label":"Mecelle\'yi tüm mahkemelere anayasa kıl: \'Ezmanın tagayyürü ile ahkâmın tagayyürü inkâr olunamaz!\'.","preview":"Adalet +6, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":6,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Dünya hukuk tarihine altın bir abide dikildi; mahkemeler asrın idrakine erdi."},{"label":"Eski fetva defterleri kafidir; kanunlaştırmak bid\'attir deyip reddet.","preview":"Reaya +7, Otorite +9 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Cevdet Paşa\'nın Mecelle\'yi Tamamlaması nizamına bağla.","preview":"Hazine +6, Otorite +3 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Cevdet Paşa\'nın Mecelle\'yi Tamamlaması fermanını uygulat.","preview":"Ordu +8, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":8,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Cevdet Paşa\'nın Mecelle\'yi Tamamlaması meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":6,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 987) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_988', 'ottoman', 'Gayrimüslim Vatan Evladının Londra Sefiri Olması', 'Hariciye Nezareti', 'Diplomaside deha olan Kostaki Musurus Paşa\'nın Londra\'ya büyükelçi olarak atanması teklifi divanda tartışıldı.', '[{"id":"char_kale_dizdari","name":"Kale Dizdarı"},{"id":"char_yayla_cobani","name":"Yayla Çobanı"}]', '[{"label":"Liyakat ehliyetledir: Atamayı tasdikle; Osmanlı\'nın bir cihan devleti olduğunu tüm dünyaya haykır.","preview":"Adalet +7, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":7,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Osmanlı diplomasisi Londra\'da zaferler kazandı; ayrımcılık çöpe atıldı."},{"label":"Hristiyan adamdan elçi olmaz deyip ehliyetsiz bir saray ağasını yollayın.","preview":"Reaya +7, Otorite +6 | Adalet -8, Hazine -2","effects":{"justice":-8,"people":7,"treasury":-2,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Gayrimüslim Vatan Evladının Londra Sefiri Olması meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +9, Otorite +2 | Adalet -3, Reaya -8","effects":{"justice":-3,"people":-8,"treasury":9,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Gayrimüslim Vatan Evladının Londra Sefiri Olması meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +7, Otorite +8 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":7,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Gayrimüslim Vatan Evladının Londra Sefiri Olması gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +7, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":7,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 988) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_989', 'ottoman', 'Ahmet Cevdet Paşa\'nın Devletin Beka Tahlili', 'Tarih-i Cevdet Hikmeti', 'Büyük allame: \'Bir devletin ömrü sınırlarının genişliğiyle değil, mahkemelerinde verilen hükmün adilliğiyle ölçülür!\' dedi.', '[{"id":"char_ahmet_cevdet_pasa","name":"Ahmet Cevdet Paşa"},{"id":"char_kadi","name":"Kadı"}]', '[{"label":"Hikmeti mülkün kalbine kazı: \'Adaletli bir köy, adaletsiz bir imparatorluktan daha üstündür!\'.","preview":"Adalet +8, Reaya +7 | Hazine -1, Otorite -2","effects":{"justice":8,"people":7,"treasury":-1,"military":0,"authority":-2},"log":"Adalet mülkün ruhu oldu; devlet dünya durdukça yaşayacak manevi bir zırha büründü."},{"label":"Kılıç toprak fethetsin de adalete sonra bakarız de.","preview":"Reaya +8, Otorite +9 | Adalet -7, Hazine -2","effects":{"justice":-7,"people":8,"treasury":-2,"military":0,"authority":9},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Ahmet Cevdet Paşa\'nın Devletin Beka Tahlili nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Ahmet Cevdet Paşa\'nın Devletin Beka Tahlili fermanını uygulat.","preview":"Ordu +7, Otorite +7 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":0,"military":7,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Ahmet Cevdet Paşa\'nın Devletin Beka Tahlili meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +1, Otorite +8 | Hazine -9","effects":{"justice":8,"people":1,"treasury":-9,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 989) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_990', 'ottoman', 'Mülkiye Mezunlarının Taşra Kaymakamlıklarına Tayini', 'Mülkiye Mektebi', 'Hukuk, iktisat ve maliye tahsil etmiş Mülkiyeli genç kaymakamların taşraya gönderilerek ayân vesayetini kırması planlandı.', '[{"id":"char_tasra_ayani","name":"Taşra Âyanı"},{"id":"char_mulkiyeli_idareci","name":"Mülkiyeli Genç İdareci"}]', '[{"label":"Mülkiyelileri taşraya sevk et; rüşvetçi yerel ağaların saltanatına kanun kılıcıyla son ver.","preview":"Adalet +6, Reaya +6 | Hazine -2, Otorite -4","effects":{"justice":6,"people":6,"treasury":-2,"military":0,"authority":-4},"log":"Taşra aydınlandı; devlet kaymakamı halkın sığınağı ve koruyucusu oldu."},{"label":"Taşrayı eski ağaların çocuklarına bırakın; mektepli çocuk köylüyü yönetemez.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":9,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Mülkiye Mezunlarının Taşra Kaymakamlıklarına Tayini nizamına bağla.","preview":"Hazine +6, Otorite +1 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":6,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Mülkiye Mezunlarının Taşra Kaymakamlıklarına Tayini fermanını uygulat.","preview":"Ordu +6, Otorite +7 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Mülkiye Mezunlarının Taşra Kaymakamlıklarına Tayini meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +3, Otorite +6 | Hazine -7","effects":{"justice":6,"people":3,"treasury":-7,"military":0,"authority":6},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 990) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_991', 'ottoman', 'Hükümdarın Kendisine Hakaret Eden Vatandaşı Affı', 'Siyasetname Ahlakı', 'Çarşıda öfkeyle padişaha beddua eden yoksul bir köylüyü cellada götüren muhafızları gören hükümdar durdu.', '[{"id":"char_padisah","name":"Padişah"},{"id":"char_reaya_ciftcisi","name":"Reaya Çiftçisi"}]', '[{"label":"\'Bırakın adamı! Onu bu hale getiren bizim açlığımız ve ihmalimizdir!\' de; köylüye aş ve iş bağla.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -4","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-4},"log":"Tevazu ve af saltanatı yüceltti; köylü ağlayarak padişahın eteğine kapandı, isyan bitti."},{"label":"Padişaha hakaretin cezası ölümdür; kellesini meydanda vurdurun.","preview":"Reaya +9, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":9,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hükümdarın Kendisine Hakaret Eden Vatandaşı Affı hadisesinde toplanan haksız salgunları gelecek yılın vergisinden mahsup et; darda kalan çiftçilere hazineden tohumluk buğday ve avans sağla.","preview":"Hazine +7, Otorite +1 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve sipahi müfrezesi sevk et; Hükümdarın Kendisine Hakaret Eden Vatandaşı Affı hadisesinde köylünün öküzüne ve tohumuna el uzatan zorba tahsildarları prangaya vurup hapse at.","preview":"Ordu +6, Otorite +8 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":6,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Ziraat ve Cibayet Kanunnâmesi\' neşret; Hükümdarın Kendisine Hakaret Eden Vatandaşı Affı gibi hadiselerin tekerrürünü önleyecek şekilde çift hayvanı ve tohum haczini kesinlikle yasaklayıp keyfi salgun toplayan mültezimleri men et.","preview":"Adalet +9, Reaya +4, Otorite +9 | Hazine -9","effects":{"justice":9,"people":4,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 991) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_992', 'ottoman', 'Bedevilikten Hadariliğe: Şehir Ahlakının Korunması', 'İbn Haldun\'un Şehir Sosyolojisi', 'Mukaddime\'nin ihtarı: \'Şehir büyüdükçe ahlak çözülür; dayanışma biter, bencillik başlar. Şehri vakıf ve adaletle tahkim et!\'', '[{"id":"char_ibn_haldun","name":"İbn Haldun"},{"id":"char_vakif_mutevellisi","name":"Vakıf Mütevellisi"}]', '[{"label":"Şehirleri vakıflarla, mekteplerle ve yardımlaşma sandıklarıyla donat; ahlaki dayanışmayı kanunlaştır.","preview":"Adalet +8, Reaya +7 | Hazine -3, Otorite -3","effects":{"justice":8,"people":7,"treasury":-3,"military":0,"authority":-3},"log":"Şehirler birer fazilet yurdu oldu; komşuluk ve kardeşlik harcı korundu."},{"label":"Şehir sadece ticaret yeridir; herkes kendi çıkarına baksın de.","preview":"Reaya +9, Otorite +7 | Adalet -9, Hazine -2","effects":{"justice":-9,"people":9,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Tahrip edilen vakıf yapılarının tamir masrafını kusurlulardan kuruşu kuruşuna tazmin ettir; vakıf akarını doğrudan hazine garantisine bağla ve Bedevilikten Hadariliğe: Şehir Ahlakının Korunması nizamına bağla.","preview":"Hazine +8, Otorite +2 | Adalet -4, Reaya -8","effects":{"justice":-4,"people":-8,"treasury":8,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Vakıf arazisini mülküne katan sancakbeyine sert ferman gönder: 24 saatte topraktan çekilmezse beyliğini alıp nefer olarak sür ve Bedevilikten Hadariliğe: Şehir Ahlakının Korunması fermanını uygulat.","preview":"Ordu +9, Otorite +7 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":0,"military":9,"authority":7},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Evkaf-ı Hümâyûn ve Kadastro Kanunu\' yürürlüğe koy; yetki aşımını durdurup tüm vakıf emlakini tahrir defterine mühürletip askeri zümrenin vakıf toprağına tecavüzünü yasakla ve Bedevilikten Hadariliğe: Şehir Ahlakının Korunması meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +3, Otorite +9 | Hazine -9","effects":{"justice":8,"people":3,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 992) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_993', 'ottoman', 'Vezirlik Makamında Sadakat Değil Ehliyet Şartı', 'Mâverdî\'nin Kamu Hukuku', 'el-Ahkâmü\'s-Sultâniyye\'nin ebedi dersi: \'Sana dalkavukluk eden sadıkları değil, yüzüne karşı hatanı söyleyen allameleri vezir et!\'', '[{"id":"char_maverdi","name":"Mâverdî"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Dalkavukları saraydan sür; divana cesur, dik duruşlu ve hakikati haykıran allameleri oturt.","preview":"Adalet +9, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":9,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Devlet idaresi dâhilerin eline geçti; hükümdar kör olmaktan kurtuldu."},{"label":"Beni öven adam huzur verir; eleştirenleri zindana atın.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -3","effects":{"justice":-9,"people":9,"treasury":-3,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Saray masraflarını kısıtlayıp bürokrasi harcamalarını murakabeye bağla; tasarruf edilen meblağı kamu hizmetlerine aktar ve Vezirlik Makamında Sadakat Değil Ehliyet Şartı nizamına bağla.","preview":"Hazine +7, Otorite +3 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet hiyerarşisini bozan saray kethüdalarını ve nüfuz tüccarlarını azlet; fitneye cüret edenleri taşra kalelerine sür ve Vezirlik Makamında Sadakat Değil Ehliyet Şartı fermanını uygulat.","preview":"Ordu +6, Otorite +6 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":6,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Kalemiyye ve Liyakat Nizamnâmesi\' ferman eyle; kurumsal denetimi sıkılaştırıp bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Vezirlik Makamında Sadakat Değil Ehliyet Şartı meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +9 | Hazine -9","effects":{"justice":7,"people":1,"treasury":-9,"military":0,"authority":9},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 993) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_994', 'ottoman', 'Hükümdarın Gözyaşı ve Mazlumun Ahı', 'Nizamülmülk\'ün Siyasetnâmesi', 'Büyük Selçuklu veziri son sahifede haykırır: \'Mazlumun gözünden damlayan tek bir damla yaş, hükümdarın altın tacını eritir!\'', '[{"id":"char_nizamulmulk","name":"Nizamülmülk"},{"id":"char_vezir","name":"Kubbealtı Veziri"}]', '[{"label":"Mülkünü mazluma siper et: \'Hiçbir ferdin gözünden tek damla haksız yaş akmayacak!\' Fermanı mühürle.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -4","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-4},"log":"Mülk ilahi rahmetle kuşatıldı; mazlumun duası devlete aşılmaz bir zırh oldu."},{"label":"Büyük devlet yönetirken arada masumlar da ezilir de.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -2","effects":{"justice":-6,"people":7,"treasury":-2,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Hükümdarın Gözyaşı ve Mazlumun Ahı meselesinde haksız kazanç sağlayan taraflara ağır cerime cezası kes; mağdur olanların zararını hazine kefaletiyle tazmin et.","preview":"Hazine +6, Otorite +3 | Adalet -1, Reaya -7","effects":{"justice":-1,"people":-7,"treasury":6,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Divan-ı Hümâyûn fermanıyla derhal tahkikat müfrezesi sevk et; Hükümdarın Gözyaşı ve Mazlumun Ahı meselesinde nizama kasteden sorumluları makamından alıp ibretle cezalandır.","preview":"Ordu +6, Otorite +9 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":0,"military":6,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Nizâm-ı Devlet ve Adâletnâme Kanunu\' neşret; Hükümdarın Gözyaşı ve Mazlumun Ahı gibi hadiselerin tekerrürünü önleyecek şekilde kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et.","preview":"Adalet +6, Reaya +3, Otorite +7 | Hazine -9","effects":{"justice":6,"people":3,"treasury":-9,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 994) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_995', 'ottoman', 'Odgurmış ve Ögdülmiş: Akıl ile Akıbetin Birleşimi', 'Kutadgu Bilig\'in Zirvesi', 'Yusuf Has Hacib son nasihatini verir: \'Adaletle hükmet (Kün-Toğdı), iktidarını koru (Ay-Toldı), aklını rehber et (Ögdülmiş) ve akıbetini unutma (Odgurmış)!\'', '[{"id":"char_odgurmis","name":"Odgurmış"}]', '[{"label":"DÖRT KUTBU BİRLEŞTİR: Adalet, kudret, akıl ve ahiret şuuruyla cihan nizamını yönet.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Kutadgu Bilig nuru devleti sardı; mülk kâmil bir fazilet kutbuna erdi."},{"label":"Sadece kudrete sarıl; akıl ve akıbeti boş ver.","preview":"Reaya +7, Otorite +6 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":7,"treasury":-1,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Devlet bütçesinden acil ödenek tahsis ederek hadiseyi iktisadi yoldan çöz; haksız çıkar sağlayanların servetini hazineye aktar ve Odgurmış ve Ögdülmiş: Akıl ile Akıbetin Birleşimi nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -9","effects":{"justice":-4,"people":-9,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devletin mutlak otoritesini göster; fermanı çiğneyen failleri derhal divan huzurunda sorguya çekip ibret-i âlem için cezalandır ve Odgurmış ve Ögdülmiş: Akıl ile Akıbetin Birleşimi fermanını uygulat.","preview":"Ordu +9, Otorite +8 | Adalet -1, Reaya -6","effects":{"justice":-1,"people":-6,"treasury":0,"military":9,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' yürürlüğe koy; yetki aşımını durdurup kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Odgurmış ve Ögdülmiş: Akıl ile Akıbetin Birleşimi meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +1, Otorite +7 | Hazine -8","effects":{"justice":7,"people":1,"treasury":-8,"military":0,"authority":7},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 995) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_996', 'ottoman', 'İnsanı Yaşat ki Devlet Yaşasın!', 'Şeyh Edebali\'nin Vasiyetnâmesi', 'Söğüt\'ten yükselen ebedi kurucu çerağ: \'Ey oğul! Sabretmesini bil, vaktinden önce çiçek açmaz. İnsanı yaşat ki devlet yaşasın!\'', '[{"id":"char_seyh_edebali","name":"Şeyh Edebali"},{"id":"char_yetim_vasisi","name":"Yetim Vasisi"}]', '[{"label":"VASİYETİ BAŞ TACI ET: Bütün kudretini, hazineni ve kılıcını insanı yaşatmaya vakfet.","preview":"Adalet +8, Reaya +8 | Hazine -2, Otorite -3","effects":{"justice":8,"people":8,"treasury":-2,"military":0,"authority":-3},"log":"İnsan yaşadı, devlet yaşadı; mülk asırları aşan bir cihanşümul nizam oldu."},{"label":"Devlet insan için değil, insan devlet için kurbandır de.","preview":"Reaya +7, Otorite +7 | Adalet -9, Hazine -4","effects":{"justice":-9,"people":7,"treasury":-4,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Menzil atlarını şahsi kervanlara kiralayanlardan tazminat tahsil et; posta teşkilatına yeni cins atlar satın al ve İnsanı Yaşat ki Devlet Yaşasın! nizamına bağla.","preview":"Hazine +8, Otorite +3 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":8,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Devlet fermanlarını geciktiren menzil görevlilerini ibret-i âlem için divan huzurunda sorguya çekip zindana at ve İnsanı Yaşat ki Devlet Yaşasın! fermanını uygulat.","preview":"Ordu +9, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":9,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Menzilhane ve Berid Teşkilatı Nizamı\' ferman eyle; kurumsal denetimi sıkılaştırıp ulak atlarının kaydını mühürlü deftere bağlayıp menzil eminlerine haftalık teftiş şartı getir ve İnsanı Yaşat ki Devlet Yaşasın! meselesini kalıcı kanuna bağla.","preview":"Adalet +8, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":8,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 996) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_997', 'ottoman', 'Umranın Kemali: Asabiyeden Hukuka ve Adalete', 'İbn Haldun\'un Nihai Hükmü', 'Tarihin filozofu son mührü vurur: \'Asabiye devleti kurar; fakat o devleti asırlarca yaşatacak tek şey HUKUK ve ADALETTİR!\'', '[{"id":"char_ibn_haldun","name":"İbn Haldun"}]', '[{"label":"HUKUKUN ÜSTÜNLÜĞÜNÜ TASDİKLE: Padişah dahi olsa kanunun emrine boyun eğ.","preview":"Adalet +7, Reaya +8 | Hazine -1, Otorite -2","effects":{"justice":7,"people":8,"treasury":-1,"military":0,"authority":-2},"log":"Hukuk hükümdarın üstünde taç oldu; devlet ebed-müddet mertebesine erdi."},{"label":"Hükümdar kanunun üstündedir de.","preview":"Reaya +8, Otorite +8 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":8,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Kalem bütçesini ve saray harcamalarını sıkı tasarrufa al; Umranın Kemali: Asabiyeden Hukuka ve Adalete hadisesinde iltimasla gelen memurların ulufesini kesip hazine giderlerini dengele.","preview":"Hazine +7, Otorite +3 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":7,"military":0,"authority":3},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Padişah fermanıyla makamını kötüye kullanan ricali derhal azlet; Umranın Kemali: Asabiyeden Hukuka ve Adalete hadisesinde saray içinde nüfuz ticareti yapanları payitahttan uzaklaştır.","preview":"Ordu +7, Otorite +6 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":0,"military":7,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'Kalemiyye ve Liyakat Nizamnâmesi\' neşret; Umranın Kemali: Asabiyeden Hukuka ve Adalete gibi hadiselerin tekerrürünü önleyecek şekilde bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -8","effects":{"justice":7,"people":4,"treasury":-8,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 997) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_998', 'ottoman', 'Sekiz Halkalı Cihan Çevrimi', 'Kınalızâde Ali Çelebi\'nin Dâire-i Adliyyesi', 'Ahlâk-ı Alâî divana çıkar: \'Adldir mûcib-i salâh-ı cihân, Cihân bir bâğdır dîvârı devlet, Devletin bâisi şerîattır, Şerîate olamaz hîç harîs illâ mülk, Mülk zabt eyleyemez illâ ricâl, Ricâli cem‘ eyleyemez illâ mâl, Mâmûr eyleyen mâli re‘âyâdır, Re‘âyâyı kul eyler padişah-ı âleme adl!\'', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"},{"id":"char_padisah","name":"Padişah"}]', '[{"label":"SEKİZ HALKAYI MÜHÜRLE: \'BU ÇEMBERİN TEK BİR HALKASI BİLE KOPARILAMAZ!\'.","preview":"Adalet +6, Reaya +8 | Hazine -3, Otorite -1","effects":{"justice":6,"people":8,"treasury":-3,"military":0,"authority":-1},"log":"Dâire-i Adliyye hakikatiyle nizam-ı mülk tamamlandı; cihan sulhü ilan edildi."},{"label":"Çemberi kır; kılıcın ve zulmün keyfiyetine tabi ol.","preview":"Reaya +7, Otorite +7 | Adalet -6, Hazine -1","effects":{"justice":-6,"people":7,"treasury":-1,"military":0,"authority":7},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Vezir ve ricalin resmi terekelerini Beytülmâl emanetine al; resmi borçlar tahsil edildikten sonra kalan helal mirası aileye bırak ve Sekiz Halkalı Cihan Çevrimi nizamına bağla.","preview":"Hazine +6, Otorite +2 | Adalet -4, Reaya -7","effects":{"justice":-4,"people":-7,"treasury":6,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Sadrazamın yetki aşımını divan fermanıyla durdur; iltimasla tayin edilen liyakatsiz akrabaları defterhane kapısından kov ve Sekiz Halkalı Cihan Çevrimi fermanını uygulat.","preview":"Ordu +7, Otorite +9 | Adalet -1, Reaya -8","effects":{"justice":-1,"people":-8,"treasury":0,"military":7,"authority":9},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Tüm vilayetleri bağlayan \'Kalemiyye ve Liyakat Nizamnâmesi\' yürürlüğe koy; yetki aşımını durdurup bürokrasiye girişte imtihan şartı getirip akraba iltimasıyla tayin yapılmasını padişah fermanıyla yasakla ve Sekiz Halkalı Cihan Çevrimi meselesini kalıcı kanuna bağla.","preview":"Adalet +6, Reaya +2, Otorite +8 | Hazine -7","effects":{"justice":6,"people":2,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 998) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_999', 'ottoman', 'Dokuz Yüz Doksan Dokuzuncu Nasihat: Adalet Mülkün Temelidir!', 'Nizâm-ı Âlem Tacı', 'Bin yıllık İslam siyaset tecrübesi son nefesini verir: Hükümdar tahtında misafir, millet toprağında emanettir; baki kalan sadece ADALETTİR!', '[{"id":"char_padisah","name":"Padişah"}]', '[{"label":"EMANETİ KUŞAN: \'ADALET MÜLKÜN TEMELİDİR, ZULÜM İSE MÜLKÜN ZEVALİDİR!\'.","preview":"Adalet +7, Reaya +8 | Hazine -4, Otorite -1","effects":{"justice":7,"people":8,"treasury":-4,"military":0,"authority":-1},"log":"Adalet çemberi kainat nizamıyla kenetlendi; cihan devleti tarihe altın mühürle kazındı."},{"label":"Divan erkânı ve yerel temsilcilerle meşveret meclisi kur; kamu maslahatını koruyan bir uzlaşma kararı bağla.","preview":"Reaya +7, Otorite +6 | Adalet -6, Hazine -3","effects":{"justice":-6,"people":7,"treasury":-3,"military":0,"authority":6},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"İhtilafın taraflarını mali murakabeye al; devlete ve halka verilen zararı faillerin emlakinden tahsil et ve Dokuz Yüz Doksan Dokuzuncu Nasihat: Adalet Mülkün Temelidir! nizamına bağla.","preview":"Hazine +7, Otorite +2 | Adalet -4, Reaya -6","effects":{"justice":-4,"people":-6,"treasury":7,"military":0,"authority":2},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"Subaşı ve çavuşlara kesin emir ver; kanun tanımaz zorbaları derhal derdest edip kale zindanında hapse at ve Dokuz Yüz Doksan Dokuzuncu Nasihat: Adalet Mülkün Temelidir! fermanını uygulat.","preview":"Ordu +8, Otorite +8 | Adalet -1, Reaya -9","effects":{"justice":-1,"people":-9,"treasury":0,"military":8,"authority":8},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"Padişah tuğrasıyla \'Nizâm-ı Devlet ve Adâletnâme Kanunu\' ferman eyle; kurumsal denetimi sıkılaştırıp kurumsal yetki sınırlarını yeniden çizip keyfi müdahaleleri padişah fermanıyla kesinlikle men et ve Dokuz Yüz Doksan Dokuzuncu Nasihat: Adalet Mülkün Temelidir! meselesini kalıcı kanuna bağla.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -6","effects":{"justice":7,"people":4,"treasury":-6,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 999) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
INSERT INTO `events` (`id`, `era`, `title`, `source`, `desc`, `characters_json`, `options_json`, `sort_order`) VALUES ('vaka_1000', 'ottoman', 'Cihanşümul Adalet Güneşi: Ebed-Müddet Saltanat', 'BİNİNCİ MÜHÜR: HÂTEM-İ NİZÂM-I ÂLEM', 'Tam bin vakalık imtihan kemale erdi. Şeyh Edebali\'nin feyzi, Fârâbî\'nin erdemi, Nizamülmülk\'ün terazisi, Mâverdî\'nin emaneti, İbn Haldun\'un umranı ve Kınalızâde\'nin çemberi tek bir kelamda birleşti: Adalet ile kâim olan mülk ebedîdir!', '[{"id":"char_kinalizade_ali_celebi","name":"Kınalızâde Ali Çelebi"}]', '[{"label":"BİNİNCİ MÜHRÜ BAS: \'ADL İLE KÂİM OLAN CİHAN NİZAMI EBEDİYEN YAŞASIN!\'.","preview":"Adalet +9, Reaya +6 | Hazine -4, Otorite -1","effects":{"justice":9,"people":6,"treasury":-4,"military":0,"authority":-1},"log":"Bin vakanın ardından Dâire-i Adliyye sonsuz bir cihanşümul nizam olarak kainata mühürlendi."},{"label":"Divan erkânı ve yerel temsilcilerle meşveret meclisi kur; kamu maslahatını koruyan bir uzlaşma kararı bağla.","preview":"Reaya +9, Otorite +8 | Adalet -9, Hazine -1","effects":{"justice":-9,"people":9,"treasury":-1,"military":0,"authority":8},"log":"Maslahat-ı âmme gözetilerek sulh sağlandı; taraflar tatmin edildi ve toplumsal nizam muhafaza edildi."},{"label":"Miri zahire ambarlarını açıp piyasaya ucuz buğday tahsis et; Cihanşümul Adalet Güneşi: Ebed-Müddet Saltanat sebebiyle artan maliyeti düşürürken narh ihlalcilerine ağır para cezası kes.","preview":"Hazine +7, Otorite +1 | Adalet -3, Reaya -9","effects":{"justice":-3,"people":-9,"treasury":7,"military":0,"authority":1},"log":"İktisadi çarklar dengeye alındı; hazine zararı tazmin edilerek mali disiplin sağlandı."},{"label":"İstanbul Kadısı ve yeniçeri subaşısını çarşıya yolla; Cihanşümul Adalet Güneşi: Ebed-Müddet Saltanat hadisesinde kepenk kapatan depoları zorla açtırıp fırıncı kethüdasını ibret için kalebend et.","preview":"Ordu +8, Otorite +6 | Adalet -2, Reaya -6","effects":{"justice":-2,"people":-6,"treasury":0,"military":8,"authority":6},"log":"Hükümdarın mutlak kudreti ve heybeti hissettirildi; kamu nizamına kastedenler sindirildi."},{"label":"\'İhtisap ve Narh Kanunnâmesi\' neşret; Cihanşümul Adalet Güneşi: Ebed-Müddet Saltanat gibi hadiselerin tekerrürünü önleyecek şekilde fırınların zahire tahsisatını mühürlü kayda bağlayıp gramaj ve fiyat hilesini men et.","preview":"Adalet +7, Reaya +4, Otorite +8 | Hazine -7","effects":{"justice":7,"people":4,"treasury":-7,"military":0,"authority":8},"log":"Yürürlüğe konan yeni nizamname ile kurumsal intizam sağlandı; benzer usulsüzlüklerin önü kanunen kesildi."}]', 1000) ON DUPLICATE KEY UPDATE `title` = VALUES(`title`), `source` = VALUES(`source`), `desc` = VALUES(`desc`), `characters_json` = VALUES(`characters_json`), `options_json` = VALUES(`options_json`), `sort_order` = VALUES(`sort_order`);
